fn desktop_runtime_trace_enabled() -> bool {
    std::env::var_os("MINDUSTRY_DESKTOP_TRACE").is_some()
}

fn desktop_runtime_trace(message: impl AsRef<str>) {
    if desktop_runtime_trace_enabled() {
        eprintln!("[desktop-runtime] {}", message.as_ref());
    }
}

fn desktop_fast_menu_enabled() -> bool {
    std::env::var_os("MINDUSTRY_DESKTOP_FAST_MENU")
        .map(|value| value != "0")
        .unwrap_or(true)
}

fn render_command_is_screen_visible(command: &RenderCommand) -> bool {
    matches!(
        command,
        RenderCommand::FillRect { .. }
            | RenderCommand::StrokeRect { .. }
            | RenderCommand::DrawSprite { .. }
            | RenderCommand::DrawTextureRegion { .. }
            | RenderCommand::DrawLine { .. }
            | RenderCommand::DrawCircle { .. }
            | RenderCommand::DrawPolygon { .. }
            | RenderCommand::DrawTriangle { .. }
            | RenderCommand::DrawPixel { .. }
            | RenderCommand::DrawText { .. }
    )
}

fn render_pass_has_screen_visible_commands(pass: &RenderPass) -> bool {
    pass.commands.iter().any(render_command_is_screen_visible)
}

fn desktop_join_search_plain_text(text: &str) -> String {
    let plain = opengl_backend_markup_plain_text(text).to_lowercase();
    let mut collapsed = String::with_capacity(plain.len());
    let mut previous_space = false;
    for ch in plain.chars() {
        if ch == ' ' {
            if !previous_space {
                collapsed.push(ch);
            }
            previous_space = true;
        } else {
            collapsed.push(ch);
            previous_space = false;
        }
    }
    collapsed.trim().to_string()
}

fn desktop_join_search_terms(fields: &[&str]) -> String {
    fields
        .iter()
        .map(|field| desktop_join_search_plain_text(field))
        .collect::<Vec<_>>()
        .join(" ")
}

fn desktop_join_description_limit_newlines_like_java(description: &str) -> String {
    let mut newline_count = 0;
    let mut result = String::with_capacity(description.len());
    for ch in description.chars() {
        if ch == '\n' {
            newline_count += 1;
            if newline_count < 3 {
                result.push(ch);
            }
        } else {
            result.push(ch);
        }
    }
    result
}

fn desktop_join_visible_char_estimated_width_like_java(ch: char, font_size: f32) -> f32 {
    if ch.is_ascii() {
        font_size * 0.56
    } else {
        font_size
    }
}

const DESKTOP_JOIN_SINGLE_LINE_ELLIPSIS_CACHE_LIMIT: usize = 1024;

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct DesktopJoinSingleLineEllipsisCacheKey {
    text: String,
    max_width_bits: u32,
    font_size_bits: u32,
}

#[derive(Debug, Default)]
struct DesktopJoinSingleLineEllipsisCache {
    entries: BTreeMap<DesktopJoinSingleLineEllipsisCacheKey, String>,
    rebuilds: u64,
}

fn desktop_join_single_line_ellipsis_cache() -> &'static Mutex<DesktopJoinSingleLineEllipsisCache> {
    static CACHE: OnceLock<Mutex<DesktopJoinSingleLineEllipsisCache>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(DesktopJoinSingleLineEllipsisCache::default()))
}

fn desktop_join_single_line_ellipsis_cache_key(
    text: &str,
    max_width: f32,
    font_size: f32,
) -> DesktopJoinSingleLineEllipsisCacheKey {
    DesktopJoinSingleLineEllipsisCacheKey {
        text: text.to_string(),
        max_width_bits: max_width.max(1.0).to_bits(),
        font_size_bits: font_size.to_bits(),
    }
}

fn desktop_join_single_line_ellipsis_like_java_uncached(
    text: &str,
    max_width: f32,
    font_size: f32,
) -> String {
    let text = text.replace('\n', " ");
    let max_width = max_width.max(1.0);
    let ellipsis = "...";
    let ellipsis_width = ellipsis
        .chars()
        .map(|ch| desktop_join_visible_char_estimated_width_like_java(ch, font_size))
        .sum::<f32>();
    let mut width = 0.0;
    let mut output = String::with_capacity(text.len().min(96));
    let mut chars = text.chars().peekable();
    let mut truncated = false;

    while let Some(ch) = chars.next() {
        if ch == '[' {
            let mut tag = String::from("[");
            let mut closed = false;
            while let Some(tag_ch) = chars.next() {
                tag.push(tag_ch);
                if tag_ch == ']' {
                    closed = true;
                    break;
                }
            }
            if closed {
                output.push_str(&tag);
                continue;
            }
            for visible in tag.chars() {
                let char_width =
                    desktop_join_visible_char_estimated_width_like_java(visible, font_size);
                if width + char_width + ellipsis_width > max_width {
                    truncated = true;
                    break;
                }
                output.push(visible);
                width += char_width;
            }
            if truncated {
                break;
            }
            continue;
        }

        let char_width = desktop_join_visible_char_estimated_width_like_java(ch, font_size);
        if width + char_width + ellipsis_width > max_width {
            truncated = true;
            break;
        }
        output.push(ch);
        width += char_width;
    }

    if truncated {
        output.push_str(ellipsis);
    }

    output
}

fn desktop_join_single_line_ellipsis_like_java(
    text: &str,
    max_width: f32,
    font_size: f32,
) -> String {
    let key = desktop_join_single_line_ellipsis_cache_key(text, max_width, font_size);
    if let Ok(cache) = desktop_join_single_line_ellipsis_cache().lock() {
        if let Some(cached) = cache.entries.get(&key) {
            return cached.clone();
        }
    }

    let output = desktop_join_single_line_ellipsis_like_java_uncached(text, max_width, font_size);
    if let Ok(mut cache) = desktop_join_single_line_ellipsis_cache().lock() {
        if cache.entries.len() >= DESKTOP_JOIN_SINGLE_LINE_ELLIPSIS_CACHE_LIMIT {
            if let Some(first_key) = cache.entries.keys().next().cloned() {
                cache.entries.remove(&first_key);
            }
        }
        if !cache.entries.contains_key(&key) {
            cache.rebuilds = cache.rebuilds.saturating_add(1);
            cache.entries.insert(key, output.clone());
        }
    }
    output
}

fn desktop_join_players_value_markup_like_java(players: i32, player_limit: i32) -> String {
    let player_color = if players == 0 {
        "[lightgray]"
    } else {
        "[accent]"
    };
    if player_limit > 0 {
        format!(
            "{}{}[lightgray]/[accent]{}[lightgray]",
            player_color,
            players.max(0),
            player_limit.max(0)
        )
    } else {
        format!("{}{}[lightgray]", player_color, players.max(0))
    }
}

fn desktop_join_snapshot_players_value_markup_like_java(players: &str) -> String {
    let players = players.trim();
    let (count, limit) = players
        .split_once('/')
        .map(|(count, limit)| (count.trim(), Some(limit.trim())))
        .unwrap_or((players, None));
    let player_color = if count.parse::<i32>().ok() == Some(0) {
        "[lightgray]"
    } else {
        "[accent]"
    };
    match limit {
        Some(limit) => format!("{player_color}{count}[lightgray]/[accent]{limit}[lightgray]"),
        None => format!("{player_color}{count}[lightgray]"),
    }
}

fn desktop_join_ping_ms_like_java(ping: &str) -> Option<String> {
    let trimmed = ping.trim();
    let digits = trimmed.strip_suffix("ms").unwrap_or(trimmed).trim();
    let value = digits.parse::<i32>().ok()?;
    (value > 0).then(|| format!("{value}ms"))
}

