const DESKTOP_JOIN_SAVED_SERVER_SNAPSHOT_KEY_FNV_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
const DESKTOP_JOIN_SAVED_SERVER_SNAPSHOT_KEY_FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

fn desktop_join_saved_server_snapshot_key_digest_write_byte(digest: &mut u64, byte: u8) {
    *digest =
        (*digest ^ u64::from(byte)).wrapping_mul(DESKTOP_JOIN_SAVED_SERVER_SNAPSHOT_KEY_FNV_PRIME);
}

fn desktop_join_saved_server_snapshot_key_digest_write_u64(digest: &mut u64, value: u64) {
    for byte in value.to_le_bytes() {
        desktop_join_saved_server_snapshot_key_digest_write_byte(digest, byte);
    }
}

fn desktop_join_saved_server_snapshot_key_digest_write_i32(digest: &mut u64, value: i32) {
    desktop_join_saved_server_snapshot_key_digest_write_u64(digest, value as u32 as u64);
}

fn desktop_join_saved_server_snapshot_key_digest_write_str(digest: &mut u64, value: &str) {
    desktop_join_saved_server_snapshot_key_digest_write_u64(digest, value.len() as u64);
    for byte in value.as_bytes() {
        desktop_join_saved_server_snapshot_key_digest_write_byte(digest, *byte);
    }
}

fn desktop_join_saved_server_snapshot_key_digest_write_opt_str(
    digest: &mut u64,
    value: Option<&str>,
) {
    match value {
        Some(value) => {
            desktop_join_saved_server_snapshot_key_digest_write_byte(digest, 1);
            desktop_join_saved_server_snapshot_key_digest_write_str(digest, value);
        }
        None => desktop_join_saved_server_snapshot_key_digest_write_byte(digest, 0),
    }
}

fn desktop_join_saved_server_snapshot_target_cache_key(
    target: &DesktopConnectTarget,
) -> (usize, u64) {
    let mut digest = DESKTOP_JOIN_SAVED_SERVER_SNAPSHOT_KEY_FNV_OFFSET;
    desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &target.host);
    desktop_join_saved_server_snapshot_key_digest_write_u64(&mut digest, u64::from(target.port));
    (target.host.len(), digest)
}

fn desktop_join_saved_server_snapshot_state_cache_key(
    state: &DesktopJoinSavedServerRefreshState,
) -> Option<DesktopJoinSavedServerSnapshotStateCacheKey> {
    let mut digest = DESKTOP_JOIN_SAVED_SERVER_SNAPSHOT_KEY_FNV_OFFSET;
    let (kind, len) = match state {
        DesktopJoinSavedServerRefreshState::Idle => return None,
        DesktopJoinSavedServerRefreshState::Refreshing => (1, 0),
        DesktopJoinSavedServerRefreshState::Failed(error) => {
            desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, error);
            (2, error.len())
        }
        DesktopJoinSavedServerRefreshState::Resolved(host) => {
            desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.ping);
            desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &host.name);
            desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &host.address);
            desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.port);
            desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &host.mapname);
            desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.players);
            desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.player_limit);
            desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.version);
            desktop_join_saved_server_snapshot_key_digest_write_str(
                &mut digest,
                &host.version_type,
            );
            desktop_join_saved_server_snapshot_key_digest_write_str(
                &mut digest,
                &host.mode.name_bundle_key(),
            );
            desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &host.description);
            desktop_join_saved_server_snapshot_key_digest_write_opt_str(
                &mut digest,
                host.mode_name.as_deref(),
            );
            (
                3,
                host.name.len()
                    + host.address.len()
                    + host.mapname.len()
                    + host.version_type.len()
                    + host.description.len()
                    + host.mode_name.as_deref().map(str::len).unwrap_or(0),
            )
        }
    };
    Some(DesktopJoinSavedServerSnapshotStateCacheKey { kind, len, digest })
}

