#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DesktopSchematicCardEntry {
    pub name: String,
    pub description: String,
    pub width: i32,
    pub height: i32,
    pub tile_count: usize,
    pub requirements: Vec<ItemStack>,
    pub power_consumption_centi: i32,
    pub power_production_centi: i32,
    pub preview_tiles: Vec<DesktopSchematicPreviewTile>,
    pub labels: Vec<String>,
    pub has_steam_id: bool,
    pub mod_name: Option<String>,
}

impl DesktopSchematicCardEntry {
    pub fn new(name: impl Into<String>, width: i32, height: i32, tile_count: usize) -> Self {
        Self {
            name: name.into(),
            description: String::new(),
            width,
            height,
            tile_count,
            requirements: Vec::new(),
            power_consumption_centi: 0,
            power_production_centi: 0,
            preview_tiles: Vec::new(),
            labels: Vec::new(),
            has_steam_id: false,
            mod_name: None,
        }
    }

    pub fn from_schematic(schematic: &Schematic, content_loader: &ContentLoader) -> Self {
        let mut entry = Self::new(
            schematic.name(),
            schematic.width,
            schematic.height,
            schematic.tiles.len(),
        );
        entry.description = schematic.description();
        entry.requirements = schematic.requirements(content_loader);
        entry.power_consumption_centi =
            schematic_power_centi_per_second(schematic.power_consumption(content_loader));
        entry.power_production_centi =
            schematic_power_centi_per_second(schematic.power_production(content_loader));
        entry.preview_tiles = schematic
            .tiles
            .iter()
            .map(DesktopSchematicPreviewTile::from_tile)
            .collect();
        entry.labels = schematic.labels.clone();
        entry.has_steam_id = schematic.tags.contains_key("steamid");
        entry.mod_name = schematic.r#mod.clone();
        entry
    }
}

