fn settings_language_display_name_for_code(code: &str) -> String {
    LanguageDialog::display_name_for_code(code)
}

fn map_locales_display_name_from_table(
    table: &[DesktopLanguageOption],
    code: &str,
) -> Option<String> {
    table
        .iter()
        .find(|option| option.code == code)
        .map(|option| option.display_name.to_string())
}

fn map_locales_display_names_for_ui_locale(
    normalized_ui_locale: &str,
    ui_language: &str,
) -> Option<&'static [DesktopLanguageOption]> {
    if ui_language.eq_ignore_ascii_case("en") || ui_language.eq_ignore_ascii_case("router") {
        return Some(MAP_LOCALES_ENGLISH_DISPLAY_NAMES);
    }
    if ui_language.eq_ignore_ascii_case("zh") {
        return if normalized_ui_locale.eq_ignore_ascii_case("zh_TW")
            || normalized_ui_locale.eq_ignore_ascii_case("zh_HK")
            || normalized_ui_locale.eq_ignore_ascii_case("zh_MO")
        {
            Some(MAP_LOCALES_TRADITIONAL_CHINESE_DISPLAY_NAMES)
        } else {
            Some(MAP_LOCALES_SIMPLIFIED_CHINESE_DISPLAY_NAMES)
        };
    }
    match ui_language {
        "ja" => Some(MAP_LOCALES_JAPANESE_DISPLAY_NAMES),
        "ko" => Some(MAP_LOCALES_KOREAN_DISPLAY_NAMES),
        "ru" => Some(MAP_LOCALES_RUSSIAN_DISPLAY_NAMES),
        "de" => Some(MAP_LOCALES_GERMAN_DISPLAY_NAMES),
        "fr" => Some(MAP_LOCALES_FRENCH_DISPLAY_NAMES),
        "cs" => Some(MAP_LOCALES_CZECH_DISPLAY_NAMES),
        "da" => Some(MAP_LOCALES_DANISH_DISPLAY_NAMES),
        "fi" => Some(MAP_LOCALES_FINNISH_DISPLAY_NAMES),
        "hu" => Some(MAP_LOCALES_HUNGARIAN_DISPLAY_NAMES),
        "ro" => Some(MAP_LOCALES_ROMANIAN_DISPLAY_NAMES),
        "sv" => Some(MAP_LOCALES_SWEDISH_DISPLAY_NAMES),
        "be" => Some(MAP_LOCALES_BELARUSIAN_DISPLAY_NAMES),
        "bg" => Some(MAP_LOCALES_BULGARIAN_DISPLAY_NAMES),
        "ca" => Some(MAP_LOCALES_CATALAN_DISPLAY_NAMES),
        "et" => Some(MAP_LOCALES_ESTONIAN_DISPLAY_NAMES),
        "eu" => Some(MAP_LOCALES_BASQUE_DISPLAY_NAMES),
        "fil" => Some(MAP_LOCALES_FILIPINO_DISPLAY_NAMES),
        "lt" => Some(MAP_LOCALES_LITHUANIAN_DISPLAY_NAMES),
        "sr" => Some(MAP_LOCALES_SERBIAN_DISPLAY_NAMES),
        "th" => Some(MAP_LOCALES_THAI_DISPLAY_NAMES),
        "tk" => Some(MAP_LOCALES_TURKMEN_DISPLAY_NAMES),
        "uk" => Some(MAP_LOCALES_UKRAINIAN_DISPLAY_NAMES),
        "id" => Some(MAP_LOCALES_INDONESIAN_DISPLAY_NAMES),
        "es" => Some(MAP_LOCALES_SPANISH_DISPLAY_NAMES),
        "it" => Some(MAP_LOCALES_ITALIAN_DISPLAY_NAMES),
        "pt" => {
            if normalized_ui_locale.eq_ignore_ascii_case("pt_PT") {
                Some(MAP_LOCALES_PORTUGUESE_PORTUGAL_DISPLAY_NAMES)
            } else {
                Some(MAP_LOCALES_PORTUGUESE_BRAZIL_DISPLAY_NAMES)
            }
        }
        "pl" => Some(MAP_LOCALES_POLISH_DISPLAY_NAMES),
        "tr" => Some(MAP_LOCALES_TURKISH_DISPLAY_NAMES),
        "vi" => Some(MAP_LOCALES_VIETNAMESE_DISPLAY_NAMES),
        "nl" => {
            if normalized_ui_locale.eq_ignore_ascii_case("nl_BE") {
                Some(MAP_LOCALES_DUTCH_BELGIUM_DISPLAY_NAMES)
            } else {
                Some(MAP_LOCALES_DUTCH_DISPLAY_NAMES)
            }
        }
        _ => None,
    }
}

fn map_locales_display_name_for_code(code: &str, ui_locale: &str) -> String {
    let code = code.trim();
    let code = if code == "in_ID" { "id_ID" } else { code };
    let normalized_ui_locale = desktop_normalize_bundle_locale_code(ui_locale);
    let ui_language = normalized_ui_locale
        .split('_')
        .next()
        .unwrap_or("en")
        .trim();
    if let Some(table) = map_locales_display_names_for_ui_locale(&normalized_ui_locale, ui_language)
    {
        if let Some(display_name) = map_locales_display_name_from_table(table, code) {
            return display_name;
        }
    }
    settings_language_display_name_for_code(code)
}

fn settings_language_display_name_static_for_code(code: &'static str) -> &'static str {
    LanguageDialog::display_name_static_for_code(code)
}

fn java_case_insensitive_order_char(ch: char, upper: bool) -> char {
    if upper {
        ch.to_uppercase().next().unwrap_or(ch)
    } else {
        ch.to_lowercase().next().unwrap_or(ch)
    }
}

fn java_case_insensitive_order_cmp(left: &str, right: &str) -> Ordering {
    let mut left_chars = left.chars();
    let mut right_chars = right.chars();
    loop {
        match (left_chars.next(), right_chars.next()) {
            (Some(left_char), Some(right_char)) => {
                if left_char == right_char {
                    continue;
                }
                let left_upper = java_case_insensitive_order_char(left_char, true);
                let right_upper = java_case_insensitive_order_char(right_char, true);
                if left_upper == right_upper {
                    continue;
                }
                let left_lower = java_case_insensitive_order_char(left_upper, false);
                let right_lower = java_case_insensitive_order_char(right_upper, false);
                if left_lower != right_lower {
                    return left_lower.cmp(&right_lower);
                }
            }
            (Some(_), None) => return Ordering::Greater,
            (None, Some(_)) => return Ordering::Less,
            (None, None) => return Ordering::Equal,
        }
    }
}

fn settings_language_options_from_locales_asset_like_java(
    locales: &'static str,
) -> Vec<DesktopLanguageOption> {
    let mut codes = locales
        .lines()
        .map(str::trim)
        .filter(|code| !code.is_empty())
        .collect::<Vec<_>>();
    codes.sort_by(|left, right| {
        let left_name = settings_language_display_name_for_code(left);
        let right_name = settings_language_display_name_for_code(right);
        java_case_insensitive_order_cmp(&left_name, &right_name)
    });
    codes.push("router");
    codes
        .into_iter()
        .map(|code| DesktopLanguageOption {
            code,
            display_name: settings_language_display_name_static_for_code(code),
        })
        .collect()
}

fn settings_language_options_like_java() -> &'static [DesktopLanguageOption] {
    static CACHE: OnceLock<Vec<DesktopLanguageOption>> = OnceLock::new();
    CACHE.get_or_init(|| {
        settings_language_options_from_locales_asset_like_java(include_str!(
            "../../core/assets/locales"
        ))
    })
}

#[cfg(test)]
fn settings_language_codes_from_locales_asset_like_java(locales: &'static str) -> Vec<String> {
    settings_language_options_from_locales_asset_like_java(locales)
        .into_iter()
        .map(|option| option.code.to_string())
        .collect()
}

