static ABOUT_CONTRIBUTORS_CACHE: OnceLock<Vec<String>> = OnceLock::new();

fn about_contributors_candidate_paths() -> Vec<PathBuf> {
    let desktop_manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    vec![
        desktop_manifest_dir.join("../core/assets/contributors"),
        cwd.join("core/assets/contributors"),
        cwd.join("../mindustry-upstream-v157.4/core/assets/contributors"),
        PathBuf::from("D:/MDT/mindustry-upstream-v157.4/core/assets/contributors"),
    ]
}

fn about_contributors_from_utf8_like_java(value: &str) -> Vec<String> {
    let mut contributors = value
        .split('\n')
        .map(|line| line.trim_end_matches('\r').to_string())
        .collect::<Vec<_>>();
    while contributors.last().is_some_and(|line| line.is_empty()) {
        contributors.pop();
    }
    contributors
}

fn load_about_contributors_from_resource_like_java() -> Option<Vec<String>> {
    about_contributors_candidate_paths()
        .into_iter()
        .find_map(|path| fs::read_to_string(path).ok())
        .map(|value| about_contributors_from_utf8_like_java(&value))
}

fn about_contributors() -> &'static [String] {
    ABOUT_CONTRIBUTORS_CACHE.get_or_init(|| {
        load_about_contributors_from_resource_like_java().unwrap_or_else(|| {
            ABOUT_CONTRIBUTORS
                .iter()
                .map(|contributor| (*contributor).to_string())
                .collect()
        })
    })
}

