#[derive(Debug, Clone, Copy, PartialEq)]
struct DesktopMenuBackgroundStaticCacheKey {
    x: f32,
    y: f32,
    width: f32,
    height: f32,
}

impl DesktopMenuBackgroundStaticCacheKey {
    fn from_viewport(viewport: RenderViewport) -> Self {
        Self {
            x: viewport.x,
            y: viewport.y,
            width: viewport.width.max(1.0),
            height: viewport.height.max(1.0),
        }
    }
}

#[derive(Debug, Clone)]
struct DesktopMenuBackgroundStaticCache {
    key: DesktopMenuBackgroundStaticCacheKey,
    commands: Vec<RenderCommand>,
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct DesktopMenuBackgroundDynamicCacheKey {
    viewport: DesktopMenuBackgroundStaticCacheKey,
    phase_index: i64,
}

impl DesktopMenuBackgroundDynamicCacheKey {
    fn from_viewport_and_time(viewport: RenderViewport, time: f32) -> Self {
        Self {
            viewport: DesktopMenuBackgroundStaticCacheKey::from_viewport(viewport),
            phase_index: desktop_menu_background_animation_phase_index(time),
        }
    }

    fn phase_time(self) -> f32 {
        self.phase_index as f32 / DESKTOP_MENU_BACKGROUND_ANIMATION_STEPS_PER_SECOND
    }
}

#[derive(Debug, Clone)]
struct DesktopMenuBackgroundDynamicCache {
    key: DesktopMenuBackgroundDynamicCacheKey,
    commands: Vec<RenderCommand>,
}

fn desktop_menu_background_animation_phase_index(time: f32) -> i64 {
    (time.max(0.0) * DESKTOP_MENU_BACKGROUND_ANIMATION_STEPS_PER_SECOND).floor() as i64
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct DesktopDatabaseContentStatLine {
    label: String,
    value: String,
}

impl DesktopDatabaseContentStatLine {
    fn new(label: impl Into<String>, value: impl ToString) -> Self {
        Self {
            label: label.into(),
            value: value.to_string(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct DesktopDatabaseContentStatGroup {
    category: &'static str,
    lines: Vec<DesktopDatabaseContentStatLine>,
}

impl DesktopDatabaseContentStatGroup {
    fn new(category: &'static str) -> Self {
        Self {
            category,
            lines: Vec::new(),
        }
    }

    fn push(&mut self, label: impl Into<String>, value: impl ToString) {
        self.lines
            .push(DesktopDatabaseContentStatLine::new(label, value));
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct DesktopDatabaseContentStats {
    use_categories: bool,
    groups: Vec<DesktopDatabaseContentStatGroup>,
}

impl DesktopDatabaseContentStats {
    fn new(use_categories: bool) -> Self {
        Self {
            use_categories,
            groups: Vec::new(),
        }
    }

    fn is_empty(&self) -> bool {
        self.groups.iter().all(|group| group.lines.is_empty())
    }

    fn line_count(&self) -> usize {
        self.groups.iter().map(|group| group.lines.len()).sum()
    }

    fn visible_category_count(&self) -> usize {
        if self.is_empty() {
            0
        } else if self.use_categories {
            self.groups
                .iter()
                .filter(|group| !group.lines.is_empty())
                .count()
        } else {
            1
        }
    }

    fn rendered_height(&self) -> f32 {
        if self.is_empty() {
            0.0
        } else {
            self.visible_category_count() as f32 * 24.0 + self.line_count() as f32 * 20.0 + 12.0
        }
    }
}

