const DESKTOP_ICON_LARGE_MISSING_REGION_LIKE_JAVA: &str = "error";

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DesktopLargeIconSourceLikeJava {
    IconLargeGlyph {
        name: String,
        glyph: String,
        unicode: u32,
    },
    AtlasRegion {
        name: String,
        symbol: String,
    },
}

impl DesktopLargeIconSourceLikeJava {
    pub fn name(&self) -> &str {
        match self {
            Self::IconLargeGlyph { name, .. } | Self::AtlasRegion { name, .. } => name,
        }
    }

    pub fn atlas_symbol(&self) -> Option<&str> {
        match self {
            Self::AtlasRegion { symbol, .. } => Some(symbol),
            Self::IconLargeGlyph { .. } => None,
        }
    }

    pub fn is_missing_region_fallback_like_java(&self) -> bool {
        matches!(
            self,
            Self::AtlasRegion { name, symbol }
                if symbol == DESKTOP_ICON_LARGE_MISSING_REGION_LIKE_JAVA && name != symbol
        )
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DesktopContentIconGlyphRegistry {
    pub source_path: String,
    pub file_path: Option<String>,
    pub load_error: Option<String>,
    icons: Vec<UpstreamContentIcon>,
    by_name: BTreeMap<String, usize>,
    by_unicode: BTreeMap<u32, usize>,
    by_atlas_symbol: BTreeMap<String, usize>,
}

impl DesktopContentIconGlyphRegistry {
    pub fn new(
        source_path: impl Into<String>,
        file_path: Option<String>,
        icons: Vec<UpstreamContentIcon>,
        load_error: Option<String>,
    ) -> Self {
        let mut by_name = BTreeMap::new();
        let mut by_unicode = BTreeMap::new();
        let mut by_atlas_symbol = BTreeMap::new();

        for (index, icon) in icons.iter().enumerate() {
            by_name.insert(icon.name.clone(), index);
            by_unicode.insert(icon.unicode, index);
            by_atlas_symbol.insert(icon.atlas_symbol.clone(), index);
        }
        if let Some(index) = by_name.get("alphaaaa").copied() {
            by_name.insert("alphachan".into(), index);
        }

        Self {
            source_path: source_path.into(),
            file_path,
            load_error,
            icons,
            by_name,
            by_unicode,
            by_atlas_symbol,
        }
    }

    pub fn len(&self) -> usize {
        self.icons.len()
    }

    pub fn is_empty(&self) -> bool {
        self.icons.is_empty()
    }

    pub fn resolved(&self) -> bool {
        self.file_path.is_some()
    }

    pub fn loaded(&self) -> bool {
        self.resolved() && self.load_error.is_none() && !self.icons.is_empty()
    }

    pub fn icons(&self) -> &[UpstreamContentIcon] {
        &self.icons
    }

    pub fn get_by_name(&self, name: &str) -> Option<&UpstreamContentIcon> {
        self.by_name
            .get(name)
            .and_then(|index| self.icons.get(*index))
    }

    pub fn get_by_unicode(&self, unicode: u32) -> Option<&UpstreamContentIcon> {
        self.by_unicode
            .get(&unicode)
            .and_then(|index| self.icons.get(*index))
    }

    pub fn get_by_atlas_symbol(&self, atlas_symbol: &str) -> Option<&UpstreamContentIcon> {
        self.by_atlas_symbol
            .get(atlas_symbol)
            .and_then(|index| self.icons.get(*index))
    }

    pub fn validation_report(&self) -> DesktopContentIconGlyphRegistryReport {
        DesktopContentIconGlyphRegistryReport {
            source_path: self.source_path.clone(),
            file_path: self.file_path.clone(),
            icon_count: self.icons.len(),
            load_error: self.load_error.clone(),
        }
    }
}

fn desktop_iconc_glyph_by_name_like_java(name: &str) -> Option<&'static UpstreamUiIconGlyph> {
    UPSTREAM_UI_ICON_GLYPHS
        .iter()
        .find(|glyph| glyph.java_name == name)
}

fn desktop_content_icon_runtime_registry_like_java(
    registry: &DesktopContentIconGlyphRegistry,
    texture_atlas: &TextureAtlasPlan<bool>,
) -> UpstreamContentIconRuntimeRegistry {
    upstream_content_icon_runtime_registry_like_java(registry.icons(), |icon| {
        desktop_content_icon_glyph_registerable_like_java(texture_atlas, icon)
    })
}

fn desktop_unicode_to_name_like_java(
    registry: &DesktopContentIconGlyphRegistry,
    texture_atlas: &TextureAtlasPlan<bool>,
    unicode: u32,
) -> Option<String> {
    let runtime_registry = desktop_content_icon_runtime_registry_like_java(registry, texture_atlas);
    upstream_unicode_to_name_like_java(&runtime_registry, unicode)
}

fn desktop_icon_large_glyph_source_like_java(
    name: &str,
    atlas: Option<&DesktopRealFontAtlas>,
) -> Option<DesktopLargeIconSourceLikeJava> {
    let codepoint = desktop_iconc_glyph_by_name_like_java(name)
        .map(|glyph| glyph.codepoint)
        .unwrap_or(DESKTOP_ICON_LARGE_FALLBACK_CODE_LIKE_JAVA);
    let character = char::from_u32(codepoint)?;
    let key = DesktopRealFontGlyphKey::new(RenderFontId::IconLarge, character)?;
    atlas.and_then(|atlas| {
        atlas
            .glyphs
            .contains_key(&key)
            .then(|| DesktopLargeIconSourceLikeJava::IconLargeGlyph {
                name: name.to_string(),
                glyph: character.to_string(),
                unicode: codepoint,
            })
    })
}

fn desktop_large_icon_source_like_java(
    name: &str,
    texture_atlas: &TextureAtlasPlan<bool>,
    font_atlas: Option<&DesktopRealFontAtlas>,
) -> Option<DesktopLargeIconSourceLikeJava> {
    desktop_icon_large_glyph_source_like_java(name, font_atlas).or_else(|| {
        let symbol = if texture_atlas.lookup(name).is_ok() {
            name
        } else {
            DESKTOP_ICON_LARGE_MISSING_REGION_LIKE_JAVA
        };
        Some(DesktopLargeIconSourceLikeJava::AtlasRegion {
            name: name.to_string(),
            symbol: symbol.to_string(),
        })
    })
}

fn desktop_content_icon_glyph_registerable_like_java(
    texture_atlas: &TextureAtlasPlan<bool>,
    icon: &UpstreamContentIcon,
) -> bool {
    desktop_content_icon_glyph_resolved_like_java(texture_atlas, icon)
}

fn desktop_content_icon_glyph_resolved_like_java(
    texture_atlas: &TextureAtlasPlan<bool>,
    icon: &UpstreamContentIcon,
) -> bool {
    texture_atlas.has_in_page(PageType::Ui, &icon.atlas_symbol)
}

