#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct DesktopRealFontGlyphKey {
    font_key: u8,
    character: char,
}

impl DesktopRealFontGlyphKey {
    const DEFAULT: u8 = 0;
    const OUTLINE: u8 = 1;
    const ICON: u8 = 2;
    const ICON_LARGE: u8 = 3;
    const LOGIC: u8 = 4;
    const TECH: u8 = 5;
    const MONOSPACE: u8 = 6;

    fn font_key_for_render_font(font: RenderFontId) -> Option<u8> {
        match font {
            RenderFontId::Default => Some(Self::DEFAULT),
            RenderFontId::Outline => Some(Self::OUTLINE),
            RenderFontId::Icon => Some(Self::ICON),
            RenderFontId::IconLarge => Some(Self::ICON_LARGE),
            RenderFontId::Logic => Some(Self::LOGIC),
            RenderFontId::Tech => Some(Self::TECH),
            RenderFontId::Monospace => Some(Self::MONOSPACE),
        }
    }

    fn new(font: RenderFontId, character: char) -> Option<Self> {
        Some(Self {
            font_key: Self::font_key_for_render_font(font)?,
            character,
        })
    }

    fn label(self) -> &'static str {
        match self.font_key {
            Self::OUTLINE => "Outline",
            Self::ICON => "Icon",
            Self::ICON_LARGE => "IconLarge",
            Self::LOGIC => "Logic",
            Self::TECH => "Tech",
            Self::MONOSPACE => "Monospace",
            _ => "Default",
        }
    }
}

