impl DesktopGraphicsOpenGlBackendFramebufferAttachmentPlan {
    pub fn from_buffer_name_with_size(
        name: impl Into<String>,
        width: u32,
        height: u32,
        generation: u64,
    ) -> Self {
        let name = name.into();
        let width = width.max(2);
        let height = height.max(2);
        Self {
            framebuffer_key: format!("framebuffer:{name}"),
            framebuffer_target: DESKTOP_GRAPHICS_OPENGL_FRAMEBUFFER,
            color_attachment: DESKTOP_GRAPHICS_OPENGL_COLOR_ATTACHMENT0,
            color_texture_identity:
                DesktopGraphicsOpenGlBackendTextureResourceIdentity::from_framebuffer_color_attachment(
                    name,
                ),
            width,
            height,
            generation,
        }
    }

    pub fn from_buffer_name(name: impl Into<String>) -> Self {
        Self::from_buffer_name_with_size(name, 0, 0, 0)
    }

    pub fn effect_buffer_with_size(width: u32, height: u32, generation: u64) -> Self {
        Self::from_buffer_name_with_size("renderer.effectBuffer", width, height, generation)
    }

    pub fn effect_buffer() -> Self {
        Self::from_buffer_name("renderer.effectBuffer")
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DesktopGraphicsOpenGlBackendTextureUploadPixelSource {
    AtlasPage {
        page_type: PageType,
        page_source_path: String,
        width: u32,
        height: u32,
    },
    ArchivePngBytes {
        source_tag: String,
        width: u32,
        height: u32,
        bytes: Vec<u8>,
    },
    GeneratedRgba8888 {
        source_tag: String,
        width: u32,
        height: u32,
        pixels: Vec<u8>,
    },
    RuntimeTexture {
        texture_key: String,
        page_source_path: String,
        width: u32,
        height: u32,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DesktopGraphicsOpenGlBackendTextureUploadPixelBytes {
    pub width: u32,
    pub height: u32,
    pub pixels: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DesktopGraphicsOpenGlBackendTextureUploadPixelLoadError {
    PngDecode {
        source_path: String,
        error: PngRgba8888DecodeError,
    },
    SizeMismatch {
        source_path: String,
        expected_width: u32,
        expected_height: u32,
        actual_width: u32,
        actual_height: u32,
    },
    RuntimeTexturePixelsUnavailable {
        texture_key: String,
    },
}

impl DesktopGraphicsOpenGlBackendTextureUploadPixelSource {
    pub fn load_rgba8888_pixels(
        &self,
    ) -> Result<
        DesktopGraphicsOpenGlBackendTextureUploadPixelBytes,
        DesktopGraphicsOpenGlBackendTextureUploadPixelLoadError,
    > {
        match self {
            Self::GeneratedRgba8888 {
                source_tag,
                width,
                height,
                pixels,
            } => {
                let expected_len = width.saturating_mul(*height).saturating_mul(4) as usize;
                if pixels.len() != expected_len {
                    let actual_pixels = (pixels.len() / 4).min(u32::MAX as usize) as u32;
                    return Err(
                        DesktopGraphicsOpenGlBackendTextureUploadPixelLoadError::SizeMismatch {
                            source_path: source_tag.clone(),
                            expected_width: *width,
                            expected_height: *height,
                            actual_width: (*width).max(1),
                            actual_height: actual_pixels / (*width).max(1),
                        },
                    );
                }
                Ok(DesktopGraphicsOpenGlBackendTextureUploadPixelBytes {
                    width: *width,
                    height: *height,
                    pixels: pixels.clone(),
                })
            }
            Self::AtlasPage {
                page_type,
                page_source_path,
                width,
                height,
            } => {
                let image = match png_rgba8888_from_path(page_source_path) {
                    Ok(image) => image,
                    Err(PngRgba8888DecodeError::Io)
                        if page_source_path == page_type.atlas_source_path() =>
                    {
                        return Ok(DesktopGraphicsOpenGlBackendTextureUploadPixelBytes {
                            width: *width,
                            height: *height,
                            pixels: opengl_backend_atlas_page_placeholder_pixels(*width, *height),
                        });
                    }
                    Err(error) => {
                        return Err(
                            DesktopGraphicsOpenGlBackendTextureUploadPixelLoadError::PngDecode {
                                source_path: page_source_path.clone(),
                                error,
                            },
                        );
                    }
                };
                if image.width != *width || image.height != *height {
                    return Err(
                        DesktopGraphicsOpenGlBackendTextureUploadPixelLoadError::SizeMismatch {
                            source_path: page_source_path.clone(),
                            expected_width: *width,
                            expected_height: *height,
                            actual_width: image.width,
                            actual_height: image.height,
                        },
                    );
                }
                Ok(DesktopGraphicsOpenGlBackendTextureUploadPixelBytes {
                    width: image.width,
                    height: image.height,
                    pixels: image.pixels,
                })
            }
            Self::ArchivePngBytes {
                source_tag,
                width,
                height,
                bytes,
            } => {
                let image = png_rgba8888_from_bytes(bytes).map_err(|error| {
                    DesktopGraphicsOpenGlBackendTextureUploadPixelLoadError::PngDecode {
                        source_path: source_tag.clone(),
                        error,
                    }
                })?;
                if image.width != *width || image.height != *height {
                    return Err(
                        DesktopGraphicsOpenGlBackendTextureUploadPixelLoadError::SizeMismatch {
                            source_path: source_tag.clone(),
                            expected_width: *width,
                            expected_height: *height,
                            actual_width: image.width,
                            actual_height: image.height,
                        },
                    );
                }
                Ok(DesktopGraphicsOpenGlBackendTextureUploadPixelBytes {
                    width: image.width,
                    height: image.height,
                    pixels: image.pixels,
                })
            }
            Self::RuntimeTexture {
                texture_key,
                width,
                height,
                ..
            } if texture_key == DESKTOP_GRAPHICS_OPENGL_PRIMITIVE_TEXTURE_KEY
                && *width == 1
                && *height == 1 =>
            {
                Ok(DesktopGraphicsOpenGlBackendTextureUploadPixelBytes {
                    width: *width,
                    height: *height,
                    pixels: vec![255, 255, 255, 255],
                })
            }
            Self::RuntimeTexture {
                texture_key,
                width,
                height,
                ..
            } if texture_key == DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY
                && *width > 0
                && *height > 0 =>
            {
                Ok(DesktopGraphicsOpenGlBackendTextureUploadPixelBytes {
                    width: *width,
                    height: *height,
                    pixels: opengl_backend_font_glyph_atlas_placeholder_pixels(*width, *height),
                })
            }
            Self::RuntimeTexture { texture_key, .. } => Err(
                DesktopGraphicsOpenGlBackendTextureUploadPixelLoadError::RuntimeTexturePixelsUnavailable {
                    texture_key: texture_key.clone(),
                },
            ),
        }
    }
}

