fn opengl_backend_default_sprite_shader_program(
) -> DesktopGraphicsOpenGlBackendShaderProgramIdentity {
    DesktopGraphicsOpenGlBackendShaderProgramIdentity::from_shader(ShaderId::Mesh)
}

const DESKTOP_GRAPHICS_OPENGL_PRIMITIVE_TEXTURE_NAME: &str = "primitive-white";
const DESKTOP_GRAPHICS_OPENGL_PRIMITIVE_TEXTURE_KEY: &str = "runtime-texture:primitive-white";
const DESKTOP_GRAPHICS_OPENGL_PRIMITIVE_TEXTURE_SOURCE: &str = "runtime:primitive-white";
const DESKTOP_GRAPHICS_OPENGL_CIRCLE_MIN_SEGMENTS: usize = 12;
const DESKTOP_GRAPHICS_OPENGL_CIRCLE_MAX_SEGMENTS: usize = 96;
const DESKTOP_GRAPHICS_OPENGL_PLACEHOLDER_TEXT_COLUMNS: usize = 5;
const DESKTOP_GRAPHICS_OPENGL_PLACEHOLDER_TEXT_ROWS: usize = 7;

fn opengl_backend_primitive_texture_binding(
    symbol: impl Into<String>,
) -> DesktopGraphicsOpenGlBackendTextureBinding {
    DesktopGraphicsOpenGlBackendTextureBinding {
        command_index: None,
        symbol: symbol.into(),
        texture_identity: DesktopGraphicsOpenGlBackendTextureResourceIdentity::from_runtime_texture(
            DESKTOP_GRAPHICS_OPENGL_PRIMITIVE_TEXTURE_NAME,
        ),
        page_type: PageType::Ui,
        page_source_path: DESKTOP_GRAPHICS_OPENGL_PRIMITIVE_TEXTURE_SOURCE.to_string(),
        source_png_bytes: None,
        page_width: 1,
        page_height: 1,
        sampler: DesktopGraphicsTextureSamplerTrace::Nearest,
        uv: [0.0, 0.0, 1.0, 1.0],
        region_width: 1,
        region_height: 1,
        nine_patch: None,
    }
}

impl DesktopGraphicsOpenGlBackendMeshBufferPlan {
    pub const SPRITE_VERTEX_FLOATS: usize = 6;
    pub const SPRITE_VERTEX_STRIDE_BYTES: usize =
        Self::SPRITE_VERTEX_FLOATS * std::mem::size_of::<f32>();
    pub const SPRITE_POSITION_OFFSET_BYTES: usize = 0;
    pub const SPRITE_COLOR_OFFSET_BYTES: usize = 2 * std::mem::size_of::<f32>();
    pub const SPRITE_TEXCOORD_OFFSET_BYTES: usize = 3 * std::mem::size_of::<f32>();
    pub const SPRITE_MIX_COLOR_OFFSET_BYTES: usize = 5 * std::mem::size_of::<f32>();

    pub fn sprite_vertex_attributes() -> Vec<DesktopGraphicsOpenGlBackendVertexAttributePlan> {
        vec![
            DesktopGraphicsOpenGlBackendVertexAttributePlan {
                name: "a_position",
                components: 2,
                offset_bytes: Self::SPRITE_POSITION_OFFSET_BYTES,
                packed_color: false,
                attribute_location: None,
            },
            DesktopGraphicsOpenGlBackendVertexAttributePlan {
                name: "a_color",
                components: 4,
                offset_bytes: Self::SPRITE_COLOR_OFFSET_BYTES,
                packed_color: true,
                attribute_location: None,
            },
            DesktopGraphicsOpenGlBackendVertexAttributePlan {
                name: "a_texCoord0",
                components: 2,
                offset_bytes: Self::SPRITE_TEXCOORD_OFFSET_BYTES,
                packed_color: false,
                attribute_location: None,
            },
            DesktopGraphicsOpenGlBackendVertexAttributePlan {
                name: "a_mix_color",
                components: 4,
                offset_bytes: Self::SPRITE_MIX_COLOR_OFFSET_BYTES,
                packed_color: true,
                attribute_location: None,
            },
        ]
    }

    pub fn from_sprite_batch(
        batch_index: usize,
        batch: &DesktopGraphicsOpenGlBackendSpriteMeshBatch,
    ) -> Self {
        Self {
            batch_index,
            vertex_count: batch.packed_vertices.len(),
            index_count: batch.indices.len(),
            vertex_attributes: Self::sprite_vertex_attributes(),
            vertex_stride_bytes: Self::SPRITE_VERTEX_STRIDE_BYTES,
            vertex_buffer_bytes: batch.packed_vertices.len() * Self::SPRITE_VERTEX_STRIDE_BYTES,
            index_buffer_bytes: batch.indices.len() * std::mem::size_of::<u32>(),
        }
    }

    pub fn resolve_attribute_locations(
        &mut self,
        program_key: &str,
        cache: &mut DesktopGraphicsOpenGlBackendLocationCache,
    ) {
        for attribute in &mut self.vertex_attributes {
            attribute.attribute_location =
                Some(cache.attribute_location(program_key, attribute.name));
        }
    }
}

impl DesktopGraphicsOpenGlBackendSpriteMeshResourcePlan {
    pub fn from_buffer_plan_and_batch(
        plan: &DesktopGraphicsOpenGlBackendMeshBufferPlan,
        batch: &DesktopGraphicsOpenGlBackendSpriteMeshBatch,
    ) -> Self {
        let batch_index = plan.batch_index;
        let key_stem = opengl_backend_sprite_mesh_batch_resource_key_stem(batch);
        Self {
            batch_index,
            vertex_array_key: format!("{key_stem}:vao"),
            vertex_buffer_key: format!("{key_stem}:vbo"),
            index_buffer_key: format!("{key_stem}:ibo"),
            vertex_buffer_bytes: plan.vertex_buffer_bytes,
            index_buffer_bytes: plan.index_buffer_bytes,
            vertex_stride_bytes: plan.vertex_stride_bytes,
        }
    }
}

impl DesktopGraphicsOpenGlBackendSpriteMeshResource {
    pub fn from_plan(plan: &DesktopGraphicsOpenGlBackendSpriteMeshResourcePlan) -> Self {
        Self {
            batch_index: plan.batch_index,
            vertex_array_key: plan.vertex_array_key.clone(),
            vertex_buffer_key: plan.vertex_buffer_key.clone(),
            index_buffer_key: plan.index_buffer_key.clone(),
            vertex_array_handle: None,
            vertex_buffer_handle: None,
            index_buffer_handle: None,
            vertex_buffer_bytes: plan.vertex_buffer_bytes,
            index_buffer_bytes: plan.index_buffer_bytes,
            vertex_stride_bytes: plan.vertex_stride_bytes,
        }
    }
}

impl DesktopGraphicsOpenGlBackendSpriteMeshResourceTable {
    pub fn from_plans(plans: &[DesktopGraphicsOpenGlBackendSpriteMeshResourcePlan]) -> Self {
        Self {
            resources: plans
                .iter()
                .map(|plan| {
                    (
                        plan.vertex_array_key.clone(),
                        DesktopGraphicsOpenGlBackendSpriteMeshResource::from_plan(plan),
                    )
                })
                .collect(),
        }
    }

    pub fn get_by_batch_index(
        &self,
        batch_index: usize,
    ) -> Option<&DesktopGraphicsOpenGlBackendSpriteMeshResource> {
        self.resources
            .values()
            .find(|resource| resource.batch_index == batch_index)
    }
}

impl DesktopGraphicsOpenGlBackendPackedSpriteVertex {
    fn append_to_vertex_bytes(self, bytes: &mut Vec<u8>) {
        bytes.extend_from_slice(&self.position.x.to_le_bytes());
        bytes.extend_from_slice(&self.position.y.to_le_bytes());
        bytes.extend_from_slice(&self.color_packed.to_le_bytes());
        bytes.extend_from_slice(&self.uv[0].to_le_bytes());
        bytes.extend_from_slice(&self.uv[1].to_le_bytes());
        bytes.extend_from_slice(&self.mix_color_packed.to_le_bytes());
    }
}

impl DesktopGraphicsOpenGlBackendSpriteMeshUploadPlan {
    pub fn from_batch_buffer_and_resource_plan(
        batch: &DesktopGraphicsOpenGlBackendSpriteMeshBatch,
        buffer_plan: &DesktopGraphicsOpenGlBackendMeshBufferPlan,
        resource_plan: &DesktopGraphicsOpenGlBackendSpriteMeshResourcePlan,
    ) -> Self {
        let mut vertex_bytes =
            Vec::with_capacity(buffer_plan.vertex_count * buffer_plan.vertex_stride_bytes);
        for vertex in &batch.packed_vertices {
            vertex.append_to_vertex_bytes(&mut vertex_bytes);
        }
        let mut index_bytes =
            Vec::with_capacity(buffer_plan.index_count * std::mem::size_of::<u32>());
        for index in &batch.indices {
            index_bytes.extend_from_slice(&index.to_le_bytes());
        }

        Self {
            batch_index: buffer_plan.batch_index,
            vertex_array_key: resource_plan.vertex_array_key.clone(),
            vertex_buffer_key: resource_plan.vertex_buffer_key.clone(),
            index_buffer_key: resource_plan.index_buffer_key.clone(),
            upload_scope: DesktopGraphicsOpenGlBackendSpriteMeshUploadScope::FullMesh,
            vertex_count: buffer_plan.vertex_count,
            index_count: buffer_plan.index_count,
            vertex_stride_bytes: buffer_plan.vertex_stride_bytes,
            vertex_attributes: buffer_plan.vertex_attributes.clone(),
            vertex_bytes,
            index_bytes,
        }
    }
}

impl DesktopGraphicsOpenGlBackendResolvedSpriteMeshUpload {
    pub fn to_opengl_sprite_mesh_upload_commands(
        &self,
    ) -> Vec<DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand> {
        if self.upload_scope == DesktopGraphicsOpenGlBackendSpriteMeshUploadScope::VertexBufferOnly
        {
            return vec![
                DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand::BindBuffer {
                    target: DESKTOP_GRAPHICS_OPENGL_ARRAY_BUFFER,
                    buffer_handle: self.vertex_buffer_handle,
                },
                DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand::BufferData {
                    target: DESKTOP_GRAPHICS_OPENGL_ARRAY_BUFFER,
                    usage: DESKTOP_GRAPHICS_OPENGL_DYNAMIC_DRAW,
                    bytes: self.vertex_bytes.clone(),
                },
            ];
        }

        let mut commands = vec![
            DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand::BindVertexArray {
                vertex_array_handle: self.vertex_array_handle,
            },
            DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand::BindBuffer {
                target: DESKTOP_GRAPHICS_OPENGL_ARRAY_BUFFER,
                buffer_handle: self.vertex_buffer_handle,
            },
            DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand::BufferData {
                target: DESKTOP_GRAPHICS_OPENGL_ARRAY_BUFFER,
                usage: DESKTOP_GRAPHICS_OPENGL_DYNAMIC_DRAW,
                bytes: self.vertex_bytes.clone(),
            },
            DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand::BindBuffer {
                target: DESKTOP_GRAPHICS_OPENGL_ELEMENT_ARRAY_BUFFER,
                buffer_handle: self.index_buffer_handle,
            },
            DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand::BufferData {
                target: DESKTOP_GRAPHICS_OPENGL_ELEMENT_ARRAY_BUFFER,
                usage: DESKTOP_GRAPHICS_OPENGL_DYNAMIC_DRAW,
                bytes: self.index_bytes.clone(),
            },
        ];

        for attribute in &self.vertex_attributes {
            let Some(attribute_location) = attribute.attribute_location else {
                continue;
            };
            commands.push(
                DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand::EnableVertexAttributeArray {
                    attribute_location,
                },
            );
            commands.push(
                DesktopGraphicsOpenGlBackendSpriteMeshUploadCommand::VertexAttributePointer {
                    attribute_location,
                    components: attribute.components,
                    gl_type: if attribute.packed_color {
                        DESKTOP_GRAPHICS_OPENGL_UNSIGNED_BYTE
                    } else {
                        DESKTOP_GRAPHICS_OPENGL_FLOAT
                    },
                    normalized: attribute.packed_color,
                    stride_bytes: self.vertex_stride_bytes,
                    offset_bytes: attribute.offset_bytes,
                },
            );
        }

        commands
    }
}

impl DesktopGraphicsOpenGlBackendShaderProgramIdentity {
    pub fn from_shader(shader: ShaderId) -> Self {
        Self {
            shader,
            program_key: format!("shader:{shader:?}"),
            generation: 0,
            gl_program: None,
        }
    }

    pub fn with_gl_program(mut self, gl_program: u32, generation: u64) -> Self {
        self.generation = generation;
        self.gl_program = Some(gl_program);
        self.program_key = format!("gl-program:{gl_program}:generation:{generation}");
        self
    }

    pub fn with_resolved_gl_program(mut self, gl_program: u32) -> Self {
        self.gl_program = Some(gl_program);
        self
    }
}

impl DesktopGraphicsOpenGlBackendShaderProgramBinding {
    pub fn from_apply(apply: &ShaderApplyPlan) -> Self {
        let uniform_bindings = apply
            .operations
            .iter()
            .filter_map(|operation| match operation {
                ShaderApplyOperation::SetUniform(binding)
                | ShaderApplyOperation::SetUniformIfPresent(binding) => {
                    Some(DesktopGraphicsOpenGlBackendShaderUniformBindingPlan {
                        name: binding.name,
                        value: binding.value.clone(),
                        uniform_location: None,
                    })
                }
                _ => None,
            })
            .collect();
        let texture_unit_bindings = apply
            .operations
            .iter()
            .filter_map(|operation| match operation {
                ShaderApplyOperation::BindTexture {
                    uniform,
                    slot,
                    texture,
                } => Some(DesktopGraphicsOpenGlBackendShaderTextureUnitBindingPlan {
                    uniform,
                    slot: *slot,
                    texture: texture.clone(),
                    uniform_location: None,
                    resolved_texture_identity: None,
                    resolved_texture_handle: None,
                }),
                _ => None,
            })
            .collect();
        Self {
            identity: DesktopGraphicsOpenGlBackendShaderProgramIdentity::from_shader(apply.shader),
            operation_count: apply.operations.len(),
            error_count: apply.errors.len(),
            uniform_bindings,
            texture_unit_bindings,
        }
    }

    pub fn resolve_locations(&mut self, cache: &mut DesktopGraphicsOpenGlBackendLocationCache) {
        for binding in &mut self.uniform_bindings {
            binding.uniform_location =
                Some(cache.uniform_location(&self.identity.program_key, binding.name));
        }
        for binding in &mut self.texture_unit_bindings {
            binding.uniform_location =
                Some(cache.uniform_location(&self.identity.program_key, binding.uniform));
        }
    }

    pub fn resolve_program_handle(
        &mut self,
        cache: &mut DesktopGraphicsOpenGlBackendHandleCache,
        allocator: &mut DesktopGraphicsOpenGlBackendHandleAllocator,
    ) {
        let program_handle = cache.program_handle(self.identity.program_key.clone(), allocator);
        self.identity = self
            .identity
            .clone()
            .with_resolved_gl_program(program_handle);
    }

    pub fn resolve_texture_bindings(
        &mut self,
        cache: &mut DesktopGraphicsOpenGlBackendHandleCache,
        allocator: &mut DesktopGraphicsOpenGlBackendHandleAllocator,
    ) {
        for binding in &mut self.texture_unit_bindings {
            let texture_identity =
                DesktopGraphicsOpenGlBackendTextureResourceIdentity::from_shader_texture_binding(
                    &binding.texture,
                );
            let texture_handle = cache.texture_handle_for_identity(&texture_identity, allocator);
            binding.resolved_texture_identity = Some(
                texture_identity
                    .clone()
                    .with_uploaded_gl_handle(texture_handle, texture_identity.generation),
            );
            binding.resolved_texture_handle = Some(texture_handle);
        }
    }

    pub fn to_opengl_shader_commands(&self) -> Vec<DesktopGraphicsOpenGlBackendShaderCommand> {
        let program_key = self.identity.program_key.clone();
        let mut commands = vec![DesktopGraphicsOpenGlBackendShaderCommand::UseProgram {
            program_key: program_key.clone(),
        }];

        for binding in &self.uniform_bindings {
            let Some(location) = binding.uniform_location else {
                continue;
            };
            commands.push(DesktopGraphicsOpenGlBackendShaderCommand::UploadUniform {
                program_key: program_key.clone(),
                uniform: binding.name,
                location,
                value: binding.value.clone(),
            });
        }

        for binding in &self.texture_unit_bindings {
            commands.push(DesktopGraphicsOpenGlBackendShaderCommand::ActiveTexture {
                program_key: program_key.clone(),
                slot: binding.slot,
                texture_unit: DESKTOP_GRAPHICS_OPENGL_TEXTURE0 + u32::from(binding.slot),
            });
            commands.push(DesktopGraphicsOpenGlBackendShaderCommand::BindTexture {
                program_key: program_key.clone(),
                slot: binding.slot,
                target: DESKTOP_GRAPHICS_OPENGL_TEXTURE_2D,
                texture: binding.texture.clone(),
            });
        }

        commands
    }
}

fn opengl_backend_shader_program_key(shader: ShaderId) -> String {
    DesktopGraphicsOpenGlBackendShaderProgramIdentity::from_shader(shader).program_key
}

fn opengl_backend_shader_stage_key(
    shader: ShaderId,
    stage: DesktopGraphicsOpenGlBackendShaderStage,
) -> String {
    format!(
        "{}:{}",
        opengl_backend_shader_program_key(shader),
        stage.key_suffix()
    )
}

impl DesktopGraphicsOpenGlBackendShaderLifecycleCommand {
    pub fn shader(&self) -> ShaderId {
        match self {
            Self::DeleteProgram { shader, .. }
            | Self::CreateShader { shader, .. }
            | Self::ShaderSource { shader, .. }
            | Self::CompileShader { shader, .. }
            | Self::CreateProgram { shader, .. }
            | Self::AttachShader { shader, .. }
            | Self::LinkProgram { shader, .. }
            | Self::DeleteShader { shader, .. } => *shader,
        }
    }

    pub fn from_load_task(
        task: &ShaderLoadTask,
    ) -> Vec<DesktopGraphicsOpenGlBackendShaderLifecycleCommand> {
        let program_key = opengl_backend_shader_program_key(task.shader);
        let vertex_path = task.source.vertex_path();
        let fragment_path = task.source.fragment_path();
        vec![
            Self::CreateShader {
                shader: task.shader,
                stage: DesktopGraphicsOpenGlBackendShaderStage::Vertex,
                source_path: vertex_path.clone(),
            },
            Self::ShaderSource {
                shader: task.shader,
                stage: DesktopGraphicsOpenGlBackendShaderStage::Vertex,
                source_path: vertex_path,
            },
            Self::CompileShader {
                shader: task.shader,
                stage: DesktopGraphicsOpenGlBackendShaderStage::Vertex,
            },
            Self::CreateShader {
                shader: task.shader,
                stage: DesktopGraphicsOpenGlBackendShaderStage::Fragment,
                source_path: fragment_path.clone(),
            },
            Self::ShaderSource {
                shader: task.shader,
                stage: DesktopGraphicsOpenGlBackendShaderStage::Fragment,
                source_path: fragment_path,
            },
            Self::CompileShader {
                shader: task.shader,
                stage: DesktopGraphicsOpenGlBackendShaderStage::Fragment,
            },
            Self::CreateProgram {
                shader: task.shader,
                program_key: program_key.clone(),
            },
            Self::AttachShader {
                shader: task.shader,
                program_key: program_key.clone(),
                stage: DesktopGraphicsOpenGlBackendShaderStage::Vertex,
            },
            Self::AttachShader {
                shader: task.shader,
                program_key: program_key.clone(),
                stage: DesktopGraphicsOpenGlBackendShaderStage::Fragment,
            },
            Self::LinkProgram {
                shader: task.shader,
                program_key,
            },
            Self::DeleteShader {
                shader: task.shader,
                stage: DesktopGraphicsOpenGlBackendShaderStage::Vertex,
            },
            Self::DeleteShader {
                shader: task.shader,
                stage: DesktopGraphicsOpenGlBackendShaderStage::Fragment,
            },
        ]
    }
}

impl DesktopGraphicsOpenGlBackendShaderLifecycleCommandPlan {
    pub fn from_load_plan(plan: &ShaderLoadPlan) -> Self {
        Self {
            commands: plan
                .enabled_tasks()
                .flat_map(DesktopGraphicsOpenGlBackendShaderLifecycleCommand::from_load_task)
                .collect(),
        }
    }

    pub fn from_reload_plan(plan: &ShaderReloadPlan) -> Self {
        let mut commands = Vec::new();
        for action in &plan.actions {
            match action {
                ShaderReloadAction::DropCachedProgram(shader) => {
                    commands.push(
                        DesktopGraphicsOpenGlBackendShaderLifecycleCommand::DeleteProgram {
                            shader: *shader,
                            program_key: opengl_backend_shader_program_key(*shader),
                        },
                    );
                }
                ShaderReloadAction::Recreate(task) => {
                    commands.extend(
                        DesktopGraphicsOpenGlBackendShaderLifecycleCommand::from_load_task(task),
                    );
                }
            }
        }
        Self { commands }
    }

    pub fn drive_shader_lifecycle_command_sink<
        S: DesktopGraphicsOpenGlBackendShaderLifecycleCommandSink,
    >(
        &self,
        sink: &mut S,
    ) -> usize {
        for command in &self.commands {
            sink.consume_opengl_shader_lifecycle_command(command.clone());
        }
        self.commands.len()
    }
}

fn opengl_backend_normalize_shader_source(source: &str) -> String {
    source.replace("\r\n", "\n").replace('\r', "\n")
}

fn opengl_backend_shader_precision(source: &str) -> &'static str {
    if source.contains("#define HIGHP") && !source.contains("//#define HIGHP") {
        "highp"
    } else {
        "mediump"
    }
}

fn opengl_backend_preprocess_non_gl30_header(
    stage: DesktopGraphicsOpenGlBackendShaderStage,
    source: &str,
) -> String {
    match stage {
        DesktopGraphicsOpenGlBackendShaderStage::Vertex => {
            format!(
                "#ifndef GL_ES\n#define lowp \n#define mediump \n#define highp \n#endif\n{source}"
            )
        }
        DesktopGraphicsOpenGlBackendShaderStage::Fragment => {
            let precision = opengl_backend_shader_precision(source);
            format!(
                "#ifdef GL_ES\nprecision {precision} float;\nprecision mediump int;\n#else\n#define lowp \n#define mediump \n#define highp \n#endif\n{source}"
            )
        }
    }
}

fn opengl_backend_preprocess_gl30_source(
    stage: DesktopGraphicsOpenGlBackendShaderStage,
    source: String,
    options: &DesktopGraphicsOpenGlBackendShaderPreprocessOptions,
) -> String {
    let version = if options.desktop {
        if options.gl_version_at_least_3_2 {
            "150"
        } else {
            "130"
        }
    } else {
        "300 es"
    };
    let mut result = format!("#version {version}\n");
    if stage == DesktopGraphicsOpenGlBackendShaderStage::Fragment {
        result.push_str("out vec4 fragColor;\n");
    }
    let varying_replacement = if stage == DesktopGraphicsOpenGlBackendShaderStage::Fragment {
        "in"
    } else {
        "out"
    };
    result.push_str(
        &source
            .replace("varying", varying_replacement)
            .replace("attribute", "in")
            .replace("texture2D(", "texture(")
            .replace("textureCube(", "texture(")
            .replace("gl_FragColor", "fragColor"),
    );
    result
}

impl Default for DesktopGraphicsOpenGlBackendShaderPreprocessOptions {
    fn default() -> Self {
        Self {
            prepend_vertex_code: String::new(),
            prepend_fragment_code: String::new(),
            gl30: false,
            desktop: true,
            mobile: false,
            gl_version_at_least_3_2: true,
        }
    }
}

impl DesktopGraphicsOpenGlBackendShaderSourceFile {
    pub fn preprocess(
        &self,
        options: &DesktopGraphicsOpenGlBackendShaderPreprocessOptions,
    ) -> Result<
        DesktopGraphicsOpenGlBackendShaderPreprocessedSource,
        DesktopGraphicsOpenGlBackendShaderPreprocessError,
    > {
        let prepend = match self.stage {
            DesktopGraphicsOpenGlBackendShaderStage::Vertex => &options.prepend_vertex_code,
            DesktopGraphicsOpenGlBackendShaderStage::Fragment => &options.prepend_fragment_code,
        };
        let source = format!("{prepend}{}", self.source_text);

        if source.contains("#ifdef GL_ES") {
            return Err(
                DesktopGraphicsOpenGlBackendShaderPreprocessError::ExplicitGlesBlock {
                    shader: self.shader,
                    stage: self.stage,
                    source_path: self.source_path.clone(),
                },
            );
        }
        if source.contains("#version") {
            return Err(
                DesktopGraphicsOpenGlBackendShaderPreprocessError::ExplicitVersion {
                    shader: self.shader,
                    stage: self.stage,
                    source_path: self.source_path.clone(),
                },
            );
        }

        let source_text = opengl_backend_preprocess_non_gl30_header(self.stage, &source);
        let source_text = if options.gl30 {
            opengl_backend_preprocess_gl30_source(self.stage, source_text, options)
        } else {
            source_text
        };

        Ok(DesktopGraphicsOpenGlBackendShaderPreprocessedSource {
            shader: self.shader,
            stage: self.stage,
            source_path: self.source_path.clone(),
            source_text,
        })
    }
}

impl DesktopGraphicsOpenGlBackendShaderProgramSourceFiles {
    pub fn preprocess(
        &self,
        options: &DesktopGraphicsOpenGlBackendShaderPreprocessOptions,
    ) -> Result<
        DesktopGraphicsOpenGlBackendShaderProgramPreprocessedSources,
        DesktopGraphicsOpenGlBackendShaderPreprocessError,
    > {
        Ok(
            DesktopGraphicsOpenGlBackendShaderProgramPreprocessedSources {
                shader: self.shader,
                program_key: self.program_key.clone(),
                vertex: self.vertex.preprocess(options)?,
                fragment: self.fragment.preprocess(options)?,
            },
        )
    }
}

impl DesktopGraphicsOpenGlBackendShaderSourceLoader {
    pub fn new(asset_root: impl Into<PathBuf>) -> Self {
        Self {
            asset_root: asset_root.into(),
        }
    }

    pub fn source_file_path(&self, source_path: &str) -> PathBuf {
        self.asset_root.join(Path::new(source_path))
    }

    pub fn load_stage_source(
        &self,
        shader: ShaderId,
        stage: DesktopGraphicsOpenGlBackendShaderStage,
        source_path: impl Into<String>,
    ) -> Result<
        DesktopGraphicsOpenGlBackendShaderSourceFile,
        DesktopGraphicsOpenGlBackendShaderSourceLoadError,
    > {
        let source_path = source_path.into();
        if source_path.trim().is_empty() {
            return Err(
                DesktopGraphicsOpenGlBackendShaderSourceLoadError::EmptySourcePath {
                    shader,
                    stage,
                },
            );
        }

        let file_path = self.source_file_path(&source_path);
        let source_text = std::fs::read_to_string(&file_path).map_err(|error| {
            DesktopGraphicsOpenGlBackendShaderSourceLoadError::ReadSource {
                shader,
                stage,
                source_path: source_path.clone(),
                file_path: file_path.clone(),
                message: error.to_string(),
            }
        })?;
        let source_text = opengl_backend_normalize_shader_source(&source_text);
        if source_text.trim().is_empty() {
            return Err(
                DesktopGraphicsOpenGlBackendShaderSourceLoadError::EmptySource {
                    shader,
                    stage,
                    source_path,
                    file_path,
                },
            );
        }

        Ok(DesktopGraphicsOpenGlBackendShaderSourceFile {
            shader,
            stage,
            source_path,
            file_path,
            source_text,
        })
    }

    pub fn load_program_sources(
        &self,
        task: &ShaderLoadTask,
    ) -> Result<
        DesktopGraphicsOpenGlBackendShaderProgramSourceFiles,
        DesktopGraphicsOpenGlBackendShaderSourceLoadError,
    > {
        Ok(DesktopGraphicsOpenGlBackendShaderProgramSourceFiles {
            shader: task.shader,
            program_key: opengl_backend_shader_program_key(task.shader),
            vertex: self.load_stage_source(
                task.shader,
                DesktopGraphicsOpenGlBackendShaderStage::Vertex,
                task.source.vertex_path(),
            )?,
            fragment: self.load_stage_source(
                task.shader,
                DesktopGraphicsOpenGlBackendShaderStage::Fragment,
                task.source.fragment_path(),
            )?,
        })
    }
}

impl From<DesktopGraphicsOpenGlBackendShaderSourceLoadError>
    for DesktopGraphicsOpenGlBackendShaderBuildError
{
    fn from(error: DesktopGraphicsOpenGlBackendShaderSourceLoadError) -> Self {
        Self::SourceLoad(error)
    }
}

impl From<DesktopGraphicsOpenGlBackendShaderPreprocessError>
    for DesktopGraphicsOpenGlBackendShaderBuildError
{
    fn from(error: DesktopGraphicsOpenGlBackendShaderPreprocessError) -> Self {
        Self::Preprocess(error)
    }
}

impl DesktopGraphicsOpenGlBackendShaderBuildReport {
    pub fn has_errors(&self) -> bool {
        self.compile_reports
            .iter()
            .any(|report| report.success == Some(false))
            || self
                .link_reports
                .iter()
                .any(|report| report.success == Some(false))
    }
}

impl DesktopGraphicsOpenGlBackendShaderBuildExecutor {
    pub fn new(source_loader: DesktopGraphicsOpenGlBackendShaderSourceLoader) -> Self {
        Self {
            source_loader,
            preprocess_options: DesktopGraphicsOpenGlBackendShaderPreprocessOptions::default(),
            lifecycle_executor:
                DesktopGraphicsResolvingOpenGlBackendShaderLifecycleExecutor::default(),
            compile_log_overrides: Vec::new(),
            link_log_overrides: Vec::new(),
        }
    }

    pub fn with_preprocess_options(
        mut self,
        preprocess_options: DesktopGraphicsOpenGlBackendShaderPreprocessOptions,
    ) -> Self {
        self.preprocess_options = preprocess_options;
        self
    }

    pub fn push_compile_log_override(
        &mut self,
        override_log: DesktopGraphicsOpenGlBackendShaderCompileLogOverride,
    ) {
        self.compile_log_overrides.push(override_log);
    }

    pub fn push_link_log_override(
        &mut self,
        override_log: DesktopGraphicsOpenGlBackendShaderLinkLogOverride,
    ) {
        self.link_log_overrides.push(override_log);
    }

    fn compile_log_for(
        &self,
        shader: ShaderId,
        stage: DesktopGraphicsOpenGlBackendShaderStage,
    ) -> (Option<bool>, Option<String>) {
        self.compile_log_overrides
            .iter()
            .rev()
            .find(|override_log| override_log.shader == shader && override_log.stage == stage)
            .map(|override_log| (Some(override_log.success), Some(override_log.log.clone())))
            .unwrap_or((None, None))
    }

    fn link_log_for(&self, shader: ShaderId) -> (Option<bool>, Option<String>) {
        self.link_log_overrides
            .iter()
            .rev()
            .find(|override_log| override_log.shader == shader)
            .map(|override_log| (Some(override_log.success), Some(override_log.log.clone())))
            .unwrap_or((None, None))
    }

    pub fn build_task(
        &mut self,
        task: &ShaderLoadTask,
    ) -> Result<
        DesktopGraphicsOpenGlBackendShaderBuildReport,
        DesktopGraphicsOpenGlBackendShaderBuildError,
    > {
        let sources = self.source_loader.load_program_sources(task)?;
        let preprocessed_sources = sources.preprocess(&self.preprocess_options)?;
        let command_plan = DesktopGraphicsOpenGlBackendShaderLifecycleCommandPlan {
            commands: DesktopGraphicsOpenGlBackendShaderLifecycleCommand::from_load_task(task),
        };
        let command_start = self.lifecycle_executor.commands.len();
        command_plan.drive_shader_lifecycle_command_sink(&mut self.lifecycle_executor);
        let resolved_commands = self.lifecycle_executor.commands[command_start..].to_vec();

        let mut compile_reports = Vec::new();
        let mut link_reports = Vec::new();
        for command in &resolved_commands {
            match command {
                DesktopGraphicsOpenGlBackendResolvedShaderLifecycleCommand::CompileShader {
                    shader,
                    stage,
                    shader_key,
                    shader_handle,
                } => {
                    let source_path = match stage {
                        DesktopGraphicsOpenGlBackendShaderStage::Vertex => {
                            preprocessed_sources.vertex.source_path.clone()
                        }
                        DesktopGraphicsOpenGlBackendShaderStage::Fragment => {
                            preprocessed_sources.fragment.source_path.clone()
                        }
                    };
                    let (success, log) = self.compile_log_for(*shader, *stage);
                    compile_reports.push(DesktopGraphicsOpenGlBackendShaderCompileReport {
                        shader: *shader,
                        stage: *stage,
                        shader_key: shader_key.clone(),
                        shader_handle: *shader_handle,
                        source_path,
                        success,
                        log,
                    });
                }
                DesktopGraphicsOpenGlBackendResolvedShaderLifecycleCommand::LinkProgram {
                    shader,
                    program_key,
                    program_handle,
                } => {
                    let (success, log) = self.link_log_for(*shader);
                    link_reports.push(DesktopGraphicsOpenGlBackendShaderLinkReport {
                        shader: *shader,
                        program_key: program_key.clone(),
                        program_handle: *program_handle,
                        success,
                        log,
                    });
                }
                _ => {}
            }
        }

        Ok(DesktopGraphicsOpenGlBackendShaderBuildReport {
            shader: task.shader,
            program_key: opengl_backend_shader_program_key(task.shader),
            sources,
            preprocessed_sources,
            resolved_commands,
            compile_reports,
            link_reports,
        })
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct DesktopGraphicsOpenGlBackendLocationCache {
    pub uniform_locations: BTreeMap<String, BTreeMap<&'static str, i32>>,
    pub attribute_locations: BTreeMap<String, BTreeMap<&'static str, i32>>,
}

impl DesktopGraphicsOpenGlBackendLocationCache {
    pub fn uniform_location(&mut self, program_key: &str, name: &'static str) -> i32 {
        let locations = self
            .uniform_locations
            .entry(program_key.to_string())
            .or_default();
        if let Some(location) = locations.get(name) {
            *location
        } else {
            let location = locations.len() as i32;
            locations.insert(name, location);
            location
        }
    }

    pub fn attribute_location(&mut self, program_key: &str, name: &'static str) -> i32 {
        let locations = self
            .attribute_locations
            .entry(program_key.to_string())
            .or_default();
        if let Some(location) = locations.get(name) {
            *location
        } else {
            let location = locations.len() as i32;
            locations.insert(name, location);
            location
        }
    }
}

impl DesktopGraphicsOpenGlBackendSpriteDrawCallPlan {
    pub const TRIANGLES_PRIMITIVE: u32 = 4;

    fn from_batch_and_resource_plan(
        batch: &DesktopGraphicsOpenGlBackendSpriteMeshBatch,
        resource_plan: &DesktopGraphicsOpenGlBackendSpriteMeshResourcePlan,
    ) -> Self {
        Self {
            batch_index: resource_plan.batch_index,
            target: batch.target.clone(),
            shader_program: batch.shader_program.clone(),
            blend_state: batch.blend_state,
            clip: batch.clip,
            texture_identity: batch.texture_identity.clone(),
            vertex_array_key: resource_plan.vertex_array_key.clone(),
            index_count: batch.indices.len(),
            index_offset: 0,
            primitive_type: Self::TRIANGLES_PRIMITIVE,
        }
    }
}

impl DesktopGraphicsOpenGlBackendSpriteMeshBatch {
    fn new(quad: &DesktopGraphicsOpenGlBackendSpriteQuad) -> Self {
        Self {
            target: quad.target.clone(),
            shader_program: quad.shader_program.clone(),
            blend_state: quad.blend_state,
            clip: quad.clip,
            texture_identity: quad.texture_identity.clone(),
            page_source_path: quad.page_source_path.clone(),
            sampler: quad.sampler,
            quad_count: 0,
            min_layer: quad.layer,
            max_layer: quad.layer,
            vertices: Vec::with_capacity(4),
            packed_vertices: Vec::with_capacity(4),
            indices: Vec::with_capacity(6),
        }
    }

    fn push_quad(&mut self, quad: &DesktopGraphicsOpenGlBackendSpriteQuad) {
        let base = self.vertices.len() as u32;
        self.vertices.extend_from_slice(&quad.vertices);
        self.packed_vertices.extend(
            quad.vertices
                .iter()
                .copied()
                .map(DesktopGraphicsOpenGlBackendPackedSpriteVertex::from_sprite_vertex),
        );
        self.indices
            .extend_from_slice(&[base, base + 1, base + 2, base + 2, base + 3, base]);
        self.quad_count += 1;
        self.min_layer = self.min_layer.min(quad.layer);
        self.max_layer = self.max_layer.max(quad.layer);
    }
}

fn opengl_backend_mesh_buffer_plans_from_batches(
    batches: &[DesktopGraphicsOpenGlBackendSpriteMeshBatch],
    location_cache: &mut DesktopGraphicsOpenGlBackendLocationCache,
) -> Vec<DesktopGraphicsOpenGlBackendMeshBufferPlan> {
    batches
        .iter()
        .enumerate()
        .map(|(batch_index, batch)| {
            let mut plan =
                DesktopGraphicsOpenGlBackendMeshBufferPlan::from_sprite_batch(batch_index, batch);
            plan.resolve_attribute_locations(&batch.shader_program.program_key, location_cache);
            plan
        })
        .collect()
}

fn opengl_backend_sprite_mesh_resource_plans_from_batches(
    batches: &[DesktopGraphicsOpenGlBackendSpriteMeshBatch],
    plans: &[DesktopGraphicsOpenGlBackendMeshBufferPlan],
) -> Vec<DesktopGraphicsOpenGlBackendSpriteMeshResourcePlan> {
    plans
        .iter()
        .zip(batches.iter())
        .map(|(plan, batch)| {
            DesktopGraphicsOpenGlBackendSpriteMeshResourcePlan::from_buffer_plan_and_batch(
                plan, batch,
            )
        })
        .collect()
}

fn opengl_backend_optional_rect_key(rect: Option<RenderRect>) -> String {
    match rect {
        Some(rect) => format!(
            "{:08x}:{:08x}:{:08x}:{:08x}",
            rect.x.to_bits(),
            rect.y.to_bits(),
            rect.width.to_bits(),
            rect.height.to_bits()
        ),
        None => "none".to_string(),
    }
}

fn opengl_backend_sprite_mesh_batch_resource_key_stem(
    batch: &DesktopGraphicsOpenGlBackendSpriteMeshBatch,
) -> String {
    format!(
        "sprite-batch:target={:?}:shader={}:shader-generation={}:blend={:?}:clip={}:texture={}:texture-generation={}:page={}:sampler={:?}:layer={:08x}",
        batch.target,
        batch.shader_program.program_key,
        batch.shader_program.generation,
        batch.blend_state,
        opengl_backend_optional_rect_key(batch.clip),
        batch.texture_identity.key,
        batch.texture_identity.generation,
        batch.page_source_path,
        batch.sampler,
        batch.min_layer.to_bits()
    )
}

fn opengl_backend_sprite_mesh_upload_plans_from_batches(
    batches: &[DesktopGraphicsOpenGlBackendSpriteMeshBatch],
    buffer_plans: &[DesktopGraphicsOpenGlBackendMeshBufferPlan],
    resource_plans: &[DesktopGraphicsOpenGlBackendSpriteMeshResourcePlan],
) -> Vec<DesktopGraphicsOpenGlBackendSpriteMeshUploadPlan> {
    batches
        .iter()
        .zip(buffer_plans.iter())
        .zip(resource_plans.iter())
        .map(|((batch, buffer_plan), resource_plan)| {
            DesktopGraphicsOpenGlBackendSpriteMeshUploadPlan::from_batch_buffer_and_resource_plan(
                batch,
                buffer_plan,
                resource_plan,
            )
        })
        .collect()
}

fn opengl_backend_sprite_draw_call_plans_from_batches(
    batches: &[DesktopGraphicsOpenGlBackendSpriteMeshBatch],
    resource_plans: &[DesktopGraphicsOpenGlBackendSpriteMeshResourcePlan],
) -> Vec<DesktopGraphicsOpenGlBackendSpriteDrawCallPlan> {
    if batches.is_empty() {
        return Vec::new();
    }
    let mut batch_order = Vec::with_capacity(batches.len());
    batch_order.extend(0..batches.len());
    batch_order.sort_unstable_by(|left, right| {
        batches[*left]
            .min_layer
            .total_cmp(&batches[*right].min_layer)
            .then_with(|| left.cmp(right))
    });
    batch_order
        .into_iter()
        .filter_map(|batch_index| {
            let batch = batches.get(batch_index)?;
            let resource_plan = resource_plans.get(batch_index)?;
            Some(
                DesktopGraphicsOpenGlBackendSpriteDrawCallPlan::from_batch_and_resource_plan(
                    batch,
                    resource_plan,
                ),
            )
        })
        .collect()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct DesktopGraphicsOpenGlBackendSpriteMeshBatchKey<'a> {
    target_kind: u8,
    target_name: &'a str,
    shader: ShaderId,
    shader_program_key: &'a str,
    shader_generation: u64,
    shader_gl_program: Option<u32>,
    blend_mode: (u8, Option<u8>, Option<u8>),
    blend_enabled: bool,
    blend_source_factor: Option<u8>,
    blend_destination_factor: Option<u8>,
    clip: Option<(u32, u32, u32, u32)>,
    texture_key: &'a str,
    texture_resource_kind: u8,
    texture_page_type: PageType,
    texture_page_source_path: &'a str,
    texture_generation: u64,
    texture_gl_handle: Option<u32>,
    page_source_path: &'a str,
    sampler: u8,
    layer_bits: u32,
}

fn opengl_backend_render_target_batch_key(target: &Option<RenderTarget>) -> (u8, &str) {
    match target {
        None => (0, ""),
        Some(RenderTarget::Screen) => (1, ""),
        Some(RenderTarget::Texture(name)) => (2, name),
        Some(RenderTarget::Buffer(name)) => (3, name),
    }
}

fn opengl_backend_blend_factor_batch_key(factor: RenderBlendFactor) -> u8 {
    match factor {
        RenderBlendFactor::Zero => 0,
        RenderBlendFactor::One => 1,
        RenderBlendFactor::SrcColor => 2,
        RenderBlendFactor::OneMinusSrcColor => 3,
        RenderBlendFactor::DstColor => 4,
        RenderBlendFactor::OneMinusDstColor => 5,
        RenderBlendFactor::SrcAlpha => 6,
        RenderBlendFactor::OneMinusSrcAlpha => 7,
        RenderBlendFactor::DstAlpha => 8,
        RenderBlendFactor::OneMinusDstAlpha => 9,
    }
}

fn opengl_backend_blend_factor_option_batch_key(factor: Option<RenderBlendFactor>) -> Option<u8> {
    factor.map(opengl_backend_blend_factor_batch_key)
}

fn opengl_backend_blend_mode_batch_key(mode: RenderBlendMode) -> (u8, Option<u8>, Option<u8>) {
    match mode {
        RenderBlendMode::Normal => (0, None, None),
        RenderBlendMode::Additive => (1, None, None),
        RenderBlendMode::Multiply => (2, None, None),
        RenderBlendMode::Screen => (3, None, None),
        RenderBlendMode::PremultipliedAlpha => (4, None, None),
        RenderBlendMode::Disabled => (5, None, None),
        RenderBlendMode::Custom {
            source,
            destination,
        } => (
            6,
            Some(opengl_backend_blend_factor_batch_key(source)),
            Some(opengl_backend_blend_factor_batch_key(destination)),
        ),
    }
}

fn opengl_backend_optional_rect_batch_key(
    rect: Option<RenderRect>,
) -> Option<(u32, u32, u32, u32)> {
    rect.map(|rect| {
        (
            rect.x.to_bits(),
            rect.y.to_bits(),
            rect.width.to_bits(),
            rect.height.to_bits(),
        )
    })
}

fn opengl_backend_texture_resource_kind_batch_key(
    kind: &DesktopGraphicsOpenGlBackendTextureResourceKind,
) -> u8 {
    match kind {
        DesktopGraphicsOpenGlBackendTextureResourceKind::AtlasPage => 0,
        DesktopGraphicsOpenGlBackendTextureResourceKind::RuntimeTexture => 1,
        DesktopGraphicsOpenGlBackendTextureResourceKind::FramebufferAttachment => 2,
    }
}

fn opengl_backend_texture_sampler_batch_key(sampler: DesktopGraphicsTextureSamplerTrace) -> u8 {
    match sampler {
        DesktopGraphicsTextureSamplerTrace::Nearest => 0,
        DesktopGraphicsTextureSamplerTrace::Linear => 1,
    }
}

const DESKTOP_OPENGL_UI_LAYER_BATCH_GRANULARITY: f32 = 0.004;

fn opengl_backend_sprite_mesh_layer_batch_bits(layer: f32) -> u32 {
    if layer.is_finite() && (Layer::END_PIXELED..=Layer::MAX).contains(&layer) {
        let bucket =
            ((layer - Layer::END_PIXELED) / DESKTOP_OPENGL_UI_LAYER_BATCH_GRANULARITY).floor();
        return (Layer::END_PIXELED + bucket * DESKTOP_OPENGL_UI_LAYER_BATCH_GRANULARITY).to_bits();
    }
    layer.to_bits()
}

fn opengl_backend_sprite_mesh_batch_key(
    quad: &DesktopGraphicsOpenGlBackendSpriteQuad,
) -> DesktopGraphicsOpenGlBackendSpriteMeshBatchKey<'_> {
    let (target_kind, target_name) = opengl_backend_render_target_batch_key(&quad.target);
    DesktopGraphicsOpenGlBackendSpriteMeshBatchKey {
        target_kind,
        target_name,
        shader: quad.shader_program.shader,
        shader_program_key: &quad.shader_program.program_key,
        shader_generation: quad.shader_program.generation,
        shader_gl_program: quad.shader_program.gl_program,
        blend_mode: opengl_backend_blend_mode_batch_key(quad.blend_state.mode),
        blend_enabled: quad.blend_state.enabled,
        blend_source_factor: opengl_backend_blend_factor_option_batch_key(
            quad.blend_state.source_factor,
        ),
        blend_destination_factor: opengl_backend_blend_factor_option_batch_key(
            quad.blend_state.destination_factor,
        ),
        clip: opengl_backend_optional_rect_batch_key(quad.clip),
        texture_key: &quad.texture_identity.key,
        texture_resource_kind: opengl_backend_texture_resource_kind_batch_key(
            &quad.texture_identity.resource_kind,
        ),
        texture_page_type: quad.texture_identity.page_type,
        texture_page_source_path: &quad.texture_identity.page_source_path,
        texture_generation: quad.texture_identity.generation,
        texture_gl_handle: quad.texture_identity.gl_handle,
        page_source_path: &quad.page_source_path,
        sampler: opengl_backend_texture_sampler_batch_key(quad.sampler),
        layer_bits: opengl_backend_sprite_mesh_layer_batch_bits(quad.layer),
    }
}

fn opengl_backend_sprite_mesh_batches_from_quads(
    quads: &[DesktopGraphicsOpenGlBackendSpriteQuad],
) -> Vec<DesktopGraphicsOpenGlBackendSpriteMeshBatch> {
    let mut batches: Vec<DesktopGraphicsOpenGlBackendSpriteMeshBatch> =
        Vec::with_capacity(quads.len().min(256));
    let mut batch_indices: HashMap<DesktopGraphicsOpenGlBackendSpriteMeshBatchKey<'_>, usize> =
        HashMap::with_capacity(quads.len().min(256));
    for quad in quads {
        let key = opengl_backend_sprite_mesh_batch_key(quad);
        if let Some(batch) = batch_indices
            .get(&key)
            .and_then(|index| batches.get_mut(*index))
        {
            batch.push_quad(quad);
            continue;
        }

        let mut batch = DesktopGraphicsOpenGlBackendSpriteMeshBatch::new(quad);
        batch.push_quad(quad);
        let index = batches.len();
        batches.push(batch);
        batch_indices.insert(key, index);
    }
    batches
}

fn opengl_backend_pack_color_rgba(color: [f32; 4]) -> f32 {
    let [r, g, b, a] = color.map(|channel| (channel.clamp(0.0, 1.0) * 255.0) as u32);
    f32::from_bits(((a << 24) | (b << 16) | (g << 8) | r) & 0xfeff_ffff)
}

fn opengl_backend_sprite_quad_positions(
    rect: RenderRect,
    origin: RenderPoint,
    rotation: f32,
) -> [RenderPoint; 4] {
    let positions = [
        RenderPoint::new(rect.x, rect.y),
        RenderPoint::new(rect.x, rect.bottom()),
        RenderPoint::new(rect.right(), rect.bottom()),
        RenderPoint::new(rect.right(), rect.y),
    ];
    if rotation.abs() <= f32::EPSILON {
        return positions;
    }
    let pivot = RenderPoint::new(rect.x + origin.x, rect.y + origin.y);
    let radians = rotation.to_radians();
    let (sin, cos) = radians.sin_cos();
    positions.map(|point| {
        let dx = point.x - pivot.x;
        let dy = point.y - pivot.y;
        RenderPoint::new(pivot.x + dx * cos - dy * sin, pivot.y + dx * sin + dy * cos)
    })
}

fn opengl_backend_rect_primitive_positions(rect: RenderRect) -> [RenderPoint; 4] {
    [
        RenderPoint::new(rect.x, rect.y),
        RenderPoint::new(rect.x, rect.y + rect.height),
        RenderPoint::new(rect.x + rect.width, rect.y + rect.height),
        RenderPoint::new(rect.x + rect.width, rect.y),
    ]
}

fn opengl_backend_line_primitive_positions(
    from: RenderPoint,
    to: RenderPoint,
    stroke: f32,
) -> Option<[RenderPoint; 4]> {
    let stroke = stroke.max(0.0);
    if stroke <= f32::EPSILON {
        return None;
    }
    let dx = to.x - from.x;
    let dy = to.y - from.y;
    let length = (dx * dx + dy * dy).sqrt();
    let half = stroke * 0.5;
    if length <= f32::EPSILON {
        return Some(opengl_backend_rect_primitive_positions(RenderRect::new(
            from.x - half,
            from.y - half,
            stroke,
            stroke,
        )));
    }
    let nx = -dy / length * half;
    let ny = dx / length * half;
    Some([
        RenderPoint::new(from.x + nx, from.y + ny),
        RenderPoint::new(from.x - nx, from.y - ny),
        RenderPoint::new(to.x - nx, to.y - ny),
        RenderPoint::new(to.x + nx, to.y + ny),
    ])
}

fn opengl_backend_polygon_primitive_points(
    center: RenderPoint,
    radius: f32,
    sides: usize,
    rotation: f32,
) -> Vec<RenderPoint> {
    if sides < 3 || radius <= f32::EPSILON {
        return Vec::new();
    }
    let rotation = rotation.to_radians();
    (0..sides)
        .map(|side| {
            let angle = rotation + (side as f32 / sides as f32) * std::f32::consts::TAU;
            RenderPoint::new(
                center.x + angle.cos() * radius,
                center.y + angle.sin() * radius,
            )
        })
        .collect()
}

fn opengl_backend_triangle_primitive_positions(
    center: RenderPoint,
    width: f32,
    length: f32,
    rotation: f32,
) -> Option<[RenderPoint; 4]> {
    if width <= f32::EPSILON || length <= f32::EPSILON {
        return None;
    }
    let rotation = rotation.to_radians();
    let tip = RenderPoint::new(
        center.x + rotation.cos() * length,
        center.y + rotation.sin() * length,
    );
    let half_width = width * 0.5;
    let base_offset = RenderPoint::new(rotation.sin() * half_width, -rotation.cos() * half_width);
    let base_a = RenderPoint::new(center.x + base_offset.x, center.y + base_offset.y);
    let base_b = RenderPoint::new(center.x - base_offset.x, center.y - base_offset.y);
    Some([base_a, tip, base_b, base_a])
}

fn opengl_backend_circle_primitive_segment_count(radius: f32) -> usize {
    if radius <= f32::EPSILON {
        return 0;
    }
    ((radius * 2.0).ceil() as usize).clamp(
        DESKTOP_GRAPHICS_OPENGL_CIRCLE_MIN_SEGMENTS,
        DESKTOP_GRAPHICS_OPENGL_CIRCLE_MAX_SEGMENTS,
    )
}

