#[derive(Debug, Clone, Default, PartialEq)]
pub struct DesktopGraphicsOpenGlBackendFramePlan {
    pub steps: Vec<DesktopGraphicsOpenGlBackendStep>,
    pub texture_upload_plans: Vec<DesktopGraphicsOpenGlBackendTextureUploadPlan>,
    pub framebuffer_attachment_plans: Vec<DesktopGraphicsOpenGlBackendFramebufferAttachmentPlan>,
}

impl DesktopGraphicsOpenGlBackendFramePlan {
    pub fn from_frame(frame: &DesktopGraphicsFrame) -> Self {
        Self::from_frame_with_effect_buffer_surface(frame, None)
    }

    pub fn from_frame_with_effect_buffer_surface(
        frame: &DesktopGraphicsFrame,
        effect_buffer_surface: Option<DesktopGraphicsEffectBufferSurface>,
    ) -> Self {
        let trace = DesktopGraphicsExecutionTrace::from_frame(frame);
        Self::from_trace_with_frame_and_effect_buffer_surface(&trace, frame, effect_buffer_surface)
    }

    pub fn from_frame_direct_with_effect_buffer_surface(
        frame: &DesktopGraphicsFrame,
        effect_buffer_surface: Option<DesktopGraphicsEffectBufferSurface>,
    ) -> Self {
        Self::from_frame_direct_with_effect_buffer_surface_and_submitted_generations(
            frame,
            effect_buffer_surface,
            None,
        )
    }

    pub fn from_frame_direct_with_effect_buffer_surface_and_submitted_generations(
        frame: &DesktopGraphicsFrame,
        effect_buffer_surface: Option<DesktopGraphicsEffectBufferSurface>,
        submitted_frame_texture_generations: Option<&BTreeMap<String, u64>>,
    ) -> Self {
        let font_locale = frame
            .font_glyph_upload_plan
            .as_ref()
            .map(|plan| plan.locale.as_str())
            .unwrap_or("en");
        let mut plan = Self::default();

        let block_particle_render_commands = frame
            .bundle
            .block_renderer
            .as_ref()
            .map_or_else(Vec::new, |block_renderer| {
                block_renderer.to_block_particle_render_commands(8.0)
            });
        let block_particle_commands_in_render_pass = !block_particle_render_commands.is_empty()
            && frame
                .bundle
                .render_frame
                .as_ref()
                .is_some_and(|render_frame| {
                    render_frame
                        .passes
                        .iter()
                        .any(|pass| pass.commands == block_particle_render_commands)
                });
        if !block_particle_commands_in_render_pass && !block_particle_render_commands.is_empty() {
            plan.push_synthetic_block_particle_pass(&block_particle_render_commands, font_locale);
        }

        if let Some(render_frame) = &frame.bundle.render_frame {
            for (pass_index, pass) in render_frame.passes.iter().enumerate() {
                plan.push_render_pass_direct(
                    pass_index,
                    pass,
                    &frame.texture_atlas,
                    &frame.mod_texture_source_bytes,
                    font_locale,
                );
            }
        }

        plan.push_frame_surface_and_texture_uploads_with_submitted_generations(
            frame,
            effect_buffer_surface,
            submitted_frame_texture_generations,
        );
        plan
    }

    pub fn from_trace_with_frame_and_effect_buffer_surface(
        trace: &DesktopGraphicsExecutionTrace,
        frame: &DesktopGraphicsFrame,
        effect_buffer_surface: Option<DesktopGraphicsEffectBufferSurface>,
    ) -> Self {
        let font_locale = frame
            .font_glyph_upload_plan
            .as_ref()
            .map(|plan| plan.locale.as_str())
            .unwrap_or("en");
        let mut plan = trace.to_opengl_backend_plan_for_font_locale(font_locale);
        plan.push_frame_surface_and_texture_uploads(frame, effect_buffer_surface);
        plan
    }

    fn push_frame_surface_and_texture_uploads(
        &mut self,
        frame: &DesktopGraphicsFrame,
        effect_buffer_surface: Option<DesktopGraphicsEffectBufferSurface>,
    ) {
        if let Some(effect_buffer_surface) = effect_buffer_surface {
            self.framebuffer_attachment_plans
                .push(effect_buffer_surface.to_attachment_plan());
        }
        if let Some(minimap_texture_frame) = &frame.minimap_texture_frame {
            self.texture_upload_plans.extend(
                opengl_backend_texture_upload_plans_from_minimap_texture_frame(
                    minimap_texture_frame,
                ),
            );
        }
        if let Some(font_upload_plan) = &frame.font_glyph_upload_plan {
            if let Some(upload) = font_upload_plan.to_opengl_texture_upload_plan() {
                self.texture_upload_plans.push(upload);
            }
        }
    }

    fn push_frame_surface_and_texture_uploads_with_submitted_generations(
        &mut self,
        frame: &DesktopGraphicsFrame,
        effect_buffer_surface: Option<DesktopGraphicsEffectBufferSurface>,
        submitted_frame_texture_generations: Option<&BTreeMap<String, u64>>,
    ) {
        if let Some(effect_buffer_surface) = effect_buffer_surface {
            self.framebuffer_attachment_plans
                .push(effect_buffer_surface.to_attachment_plan());
        }
        if let Some(minimap_texture_frame) = &frame.minimap_texture_frame {
            self.texture_upload_plans.extend(
                opengl_backend_texture_upload_plans_from_minimap_texture_frame(
                    minimap_texture_frame,
                ),
            );
        }
        if let Some(font_upload_plan) = &frame.font_glyph_upload_plan {
            let upload_pending = submitted_frame_texture_generations
                .and_then(|generations| generations.get(&font_upload_plan.texture_key))
                .map(|submitted_generation| *submitted_generation < font_upload_plan.generation)
                .unwrap_or(true);
            if upload_pending {
                if let Some(upload) = font_upload_plan.to_opengl_texture_upload_plan() {
                    self.texture_upload_plans.push(upload);
                }
            }
        }
    }

    pub fn from_trace(trace: &DesktopGraphicsExecutionTrace) -> Self {
        Self::from_trace_for_font_locale(trace, "en")
    }

    pub fn from_trace_for_font_locale(
        trace: &DesktopGraphicsExecutionTrace,
        font_locale: &str,
    ) -> Self {
        let mut plan = Self::default();

        let block_particle_commands_in_render_pass =
            !trace.block_particle_render_commands.is_empty()
                && trace
                    .render_passes
                    .iter()
                    .any(|pass| pass.commands == trace.block_particle_render_commands);

        if !block_particle_commands_in_render_pass
            && !trace.block_particle_render_commands.is_empty()
        {
            plan.push_synthetic_block_particle_pass(
                &trace.block_particle_render_commands,
                font_locale,
            );
        }

        for (pass_index, pass) in trace.render_passes.iter().enumerate() {
            plan.push_render_pass(pass_index, pass, font_locale);
        }

        plan
    }

    pub fn drive_texture_upload_sink<S: DesktopGraphicsOpenGlBackendTextureUploadSink>(
        &self,
        sink: &mut S,
    ) -> DesktopGraphicsOpenGlBackendTextureUploadSinkExecutionState {
        let mut state = DesktopGraphicsOpenGlBackendTextureUploadSinkExecutionState::default();
        for upload in &self.texture_upload_plans {
            sink.consume_opengl_texture_upload(upload.clone());
            state.texture_uploads_emitted += 1;
            state.last_texture_upload = Some(upload.clone());
        }
        state
    }

    pub fn drive_framebuffer_attachment_sink<
        S: DesktopGraphicsOpenGlBackendFramebufferAttachmentSink,
    >(
        &self,
        sink: &mut S,
    ) -> DesktopGraphicsOpenGlBackendFramebufferAttachmentSinkExecutionState {
        let mut state =
            DesktopGraphicsOpenGlBackendFramebufferAttachmentSinkExecutionState::default();
        for plan in &self.framebuffer_attachment_plans {
            sink.consume_opengl_framebuffer_attachment(plan.clone());
            state.framebuffer_attachments_emitted += 1;
            state.last_framebuffer_attachment = Some(plan.clone());
        }
        state
    }

    fn push_synthetic_block_particle_pass(
        &mut self,
        commands: &[RenderCommand],
        font_locale: &str,
    ) {
        let target = RenderTarget::Screen;
        self.steps.push(DesktopGraphicsOpenGlBackendStep {
            source: DesktopGraphicsOpenGlBackendStepSource::BlockParticles {
                command_index: None,
            },
            target: target.clone(),
            kind: DesktopGraphicsOpenGlBackendStepKind::BeginPass,
            font_locale: font_locale.to_string(),
        });
        self.push_commands(
            target.clone(),
            DesktopGraphicsOpenGlBackendStepSource::BlockParticles {
                command_index: None,
            },
            commands,
            &[],
            &[],
            font_locale,
        );
        self.steps.push(DesktopGraphicsOpenGlBackendStep {
            source: DesktopGraphicsOpenGlBackendStepSource::BlockParticles {
                command_index: None,
            },
            target,
            kind: DesktopGraphicsOpenGlBackendStepKind::EndPass,
            font_locale: font_locale.to_string(),
        });
    }

    fn push_render_pass(
        &mut self,
        pass_index: usize,
        pass: &DesktopGraphicsPassExecutionTrace,
        font_locale: &str,
    ) {
        self.steps.push(DesktopGraphicsOpenGlBackendStep {
            source: DesktopGraphicsOpenGlBackendStepSource::RenderPass {
                pass_index,
                command_index: None,
                pass_kind: pass.kind.clone(),
                pass_order: pass.order,
            },
            target: pass.target.clone(),
            kind: DesktopGraphicsOpenGlBackendStepKind::BeginPass,
            font_locale: font_locale.to_string(),
        });

        self.push_commands(
            pass.target.clone(),
            DesktopGraphicsOpenGlBackendStepSource::RenderPass {
                pass_index,
                command_index: None,
                pass_kind: pass.kind.clone(),
                pass_order: pass.order,
            },
            &pass.commands,
            &pass.resolved_sprites,
            &pass.shader_applies,
            font_locale,
        );

        self.steps.push(DesktopGraphicsOpenGlBackendStep {
            source: DesktopGraphicsOpenGlBackendStepSource::RenderPass {
                pass_index,
                command_index: None,
                pass_kind: pass.kind.clone(),
                pass_order: pass.order,
            },
            target: pass.target.clone(),
            kind: DesktopGraphicsOpenGlBackendStepKind::EndPass,
            font_locale: font_locale.to_string(),
        });

        if let Some(resolve_target) = pass.resolve_target.clone() {
            self.steps.push(DesktopGraphicsOpenGlBackendStep {
                source: DesktopGraphicsOpenGlBackendStepSource::RenderPass {
                    pass_index,
                    command_index: None,
                    pass_kind: pass.kind.clone(),
                    pass_order: pass.order,
                },
                target: pass.target.clone(),
                kind: DesktopGraphicsOpenGlBackendStepKind::Resolve {
                    resolve_target,
                    resolve_kind: pass.resolve_kind.unwrap_or(RenderResolveKind::Blit),
                    resolve_sample: pass.resolve_sample,
                },
                font_locale: font_locale.to_string(),
            });
        }
    }

    fn push_render_pass_direct(
        &mut self,
        pass_index: usize,
        pass: &RenderPass,
        atlas: &TextureAtlasPlan<bool>,
        mod_texture_source_bytes: &BTreeMap<String, Vec<u8>>,
        font_locale: &str,
    ) {
        let source = DesktopGraphicsOpenGlBackendStepSource::RenderPass {
            pass_index,
            command_index: None,
            pass_kind: pass.kind.clone(),
            pass_order: pass.order,
        };
        self.steps.push(DesktopGraphicsOpenGlBackendStep {
            source: source.clone(),
            target: pass.target.clone(),
            kind: DesktopGraphicsOpenGlBackendStepKind::BeginPass,
            font_locale: font_locale.to_string(),
        });

        let mut resolved_sprites = Vec::new();
        for (command_index, command) in pass.commands.iter().enumerate() {
            if let RenderCommand::DrawSprite { symbol, .. }
            | RenderCommand::DrawTextureRegion { symbol, .. } = command
            {
                let mut resolved = resolve_sprite_symbol_with_mod_texture_bytes(
                    atlas,
                    symbol,
                    mod_texture_source_bytes,
                );
                resolved.command_index = Some(command_index);
                resolved_sprites.push(resolved);
            }
        }

        self.push_commands(
            pass.target.clone(),
            source.clone(),
            &pass.commands,
            &resolved_sprites,
            &[],
            font_locale,
        );

        self.steps.push(DesktopGraphicsOpenGlBackendStep {
            source: source.clone(),
            target: pass.target.clone(),
            kind: DesktopGraphicsOpenGlBackendStepKind::EndPass,
            font_locale: font_locale.to_string(),
        });

        if let Some(resolve_target) = pass.resolve_target.clone() {
            self.steps.push(DesktopGraphicsOpenGlBackendStep {
                source,
                target: pass.target.clone(),
                kind: DesktopGraphicsOpenGlBackendStepKind::Resolve {
                    resolve_target,
                    resolve_kind: pass.resolve_kind.unwrap_or(RenderResolveKind::Blit),
                    resolve_sample: pass.resolve_sample,
                },
                font_locale: font_locale.to_string(),
            });
        }
    }

    fn push_commands(
        &mut self,
        target: RenderTarget,
        source: DesktopGraphicsOpenGlBackendStepSource,
        commands: &[RenderCommand],
        resolved_sprites: &[DesktopGraphicsResolvedSpriteTrace],
        shader_applies: &[DesktopGraphicsShaderApplyCommandTrace],
        font_locale: &str,
    ) {
        for (command_index, command) in commands.iter().enumerate() {
            let command_source = match &source {
                DesktopGraphicsOpenGlBackendStepSource::RenderPass {
                    pass_index,
                    pass_kind,
                    pass_order,
                    ..
                } => DesktopGraphicsOpenGlBackendStepSource::RenderPass {
                    pass_index: *pass_index,
                    command_index: Some(command_index),
                    pass_kind: pass_kind.clone(),
                    pass_order: *pass_order,
                },
                DesktopGraphicsOpenGlBackendStepSource::BlockParticles { .. } => {
                    DesktopGraphicsOpenGlBackendStepSource::BlockParticles {
                        command_index: Some(command_index),
                    }
                }
            };

            if let Some(boundary) = command.backend_flush_boundary() {
                self.steps.push(DesktopGraphicsOpenGlBackendStep {
                    source: command_source.clone(),
                    target: target.clone(),
                    kind: DesktopGraphicsOpenGlBackendStepKind::FlushBoundary {
                        boundary,
                        label: boundary.label(),
                    },
                    font_locale: font_locale.to_string(),
                });
            }

            if let Some(apply) = shader_applies
                .iter()
                .find(|trace| trace.command_index == command_index)
                .map(|trace| trace.apply.clone())
                .or_else(|| {
                    blockbuild_shader_apply_plan_from_render_command(command, resolved_sprites)
                })
            {
                self.steps.push(DesktopGraphicsOpenGlBackendStep {
                    source: command_source.clone(),
                    target: target.clone(),
                    kind: DesktopGraphicsOpenGlBackendStepKind::ShaderApply { apply },
                    font_locale: font_locale.to_string(),
                });
            }

            self.steps.push(DesktopGraphicsOpenGlBackendStep {
                source: command_source,
                target: target.clone(),
                kind: DesktopGraphicsOpenGlBackendStepKind::Command {
                    kind: render_command_trace_kind(command),
                    command: command.clone(),
                    resolved_sprite: opengl_backend_resolved_sprite_for_command(
                        command_index,
                        command,
                        resolved_sprites,
                    ),
                },
                font_locale: font_locale.to_string(),
            });
        }
    }
}

fn opengl_backend_texture_upload_plans_from_minimap_texture_frame(
    minimap_texture_frame: &MinimapTextureFramePlan,
) -> Vec<DesktopGraphicsOpenGlBackendTextureUploadPlan> {
    let mut plans = Vec::new();
    let identity =
        DesktopGraphicsOpenGlBackendTextureResourceIdentity::from_runtime_texture("minimap");
    let page_width = minimap_texture_frame.texture_size.width.max(0) as u32;
    let page_height = minimap_texture_frame.texture_size.height.max(0) as u32;
    let base_plan = |kind, generation, recreate_texture, dirty_pixels| {
        DesktopGraphicsOpenGlBackendTextureUploadPlan {
            texture_key: identity.key.clone(),
            texture_identity: identity.clone(),
            resource_kind: DesktopGraphicsOpenGlBackendTextureResourceKind::RuntimeTexture,
            page_type: identity.page_type,
            page_source_path: identity.page_source_path.clone(),
            source_png_bytes: None,
            page_width,
            page_height,
            sampler: DesktopGraphicsTextureSamplerTrace::Nearest,
            generation,
            bind_count: 0,
            recreate_texture,
            dirty_pixels,
            kind,
        }
    };

    if let Some(full_upload) = minimap_texture_frame.full_upload {
        plans.push(base_plan(
            DesktopGraphicsOpenGlBackendTextureUploadKind::FullPage,
            1,
            minimap_texture_frame.recreate_texture,
            Vec::new(),
        ));
        debug_assert_eq!(page_width, full_upload.width.max(0) as u32);
        debug_assert_eq!(page_height, full_upload.height.max(0) as u32);
    }

    if !minimap_texture_frame.dirty_pixels.is_empty() {
        let dirty_pixels = minimap_texture_frame
            .dirty_pixels
            .iter()
            .map(|pixel| DesktopGraphicsOpenGlBackendTexturePixelUpdate {
                x: pixel.texture_x,
                y: pixel.texture_y,
                rgba: pixel.rgba,
            })
            .collect();
        plans.push(base_plan(
            DesktopGraphicsOpenGlBackendTextureUploadKind::DirtyPixels,
            1,
            false,
            dirty_pixels,
        ));
    }

    plans
}

fn opengl_backend_resolved_sprite_for_command(
    command_index: usize,
    command: &RenderCommand,
    resolved_sprites: &[DesktopGraphicsResolvedSpriteTrace],
) -> Option<DesktopGraphicsResolvedSpriteTrace> {
    let symbol = match command {
        RenderCommand::DrawSprite { symbol, .. }
        | RenderCommand::DrawTextureRegion { symbol, .. } => symbol,
        _ => return None,
    };
    resolved_sprites
        .iter()
        .find(|sprite| sprite.command_index == Some(command_index) && sprite.symbol == *symbol)
        .or_else(|| {
            resolved_sprites
                .iter()
                .find(|sprite| sprite.symbol == *symbol)
        })
        .cloned()
}

