#[derive(Debug, Clone, PartialEq)]
pub struct DesktopFrameLoopState {
    pub surface: DesktopSurfaceConfig,
    pub effect_buffer_generation: u64,
    pub pacing: DesktopFramePacing,
    pub next_frame_index: u64,
    pub closed: bool,
    pub input_events_seen: u64,
    pub last_frame_instant: Option<Instant>,
}

impl DesktopFrameLoopState {
    pub fn new(surface: DesktopSurfaceConfig, pacing: DesktopFramePacing) -> Self {
        Self {
            surface,
            effect_buffer_generation: 0,
            pacing,
            next_frame_index: 0,
            closed: false,
            input_events_seen: 0,
            last_frame_instant: None,
        }
    }

    pub fn request_close(&mut self) {
        self.closed = true;
    }

    pub fn menu_frame_delta_like_java(&mut self) -> Duration {
        let now = Instant::now();
        let fallback = if self.pacing.is_paced() {
            self.pacing.target_frame_time
        } else {
            Duration::from_secs_f32(1.0 / 60.0)
        };
        let delta = self
            .last_frame_instant
            .map(|last| now.saturating_duration_since(last))
            .filter(|delta| !delta.is_zero())
            .unwrap_or(fallback);
        self.last_frame_instant = Some(now);
        delta
    }
}

impl Default for DesktopFrameLoopState {
    fn default() -> Self {
        Self::new(
            DesktopSurfaceConfig::default(),
            DesktopFramePacing::default(),
        )
    }
}

