    pub fn fonts_get_large_icon_source_like_java(
        &self,
        name: &str,
    ) -> Option<DesktopLargeIconSourceLikeJava> {
        let font_atlas = desktop_default_real_font_atlas_for_locale(&self.font_locale);
        desktop_large_icon_source_like_java(name, &self.texture_atlas, font_atlas.as_deref())
    }

    fn push_large_icon_source_like_java(
        &self,
        pass: &mut RenderPass,
        source: &DesktopLargeIconSourceLikeJava,
        rect: RenderRect,
        tint: [f32; 4],
        layer: f32,
    ) {
        match source {
            DesktopLargeIconSourceLikeJava::IconLargeGlyph { glyph, .. } => {
                pass.push(RenderCommand::draw_text_styled(
                    glyph.clone(),
                    rect.center(),
                    tint,
                    rect.height,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_font(RenderFontId::IconLarge)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true),
                    layer,
                ));
            }
            DesktopLargeIconSourceLikeJava::AtlasRegion { symbol, .. } => {
                pass.push(RenderCommand::draw_sprite(
                    symbol.clone(),
                    rect,
                    tint,
                    0.0,
                    layer,
                ));
            }
        }
    }

    fn push_large_icon_like_java(
        &self,
        pass: &mut RenderPass,
        name: &str,
        rect: RenderRect,
        tint: [f32; 4],
        layer: f32,
    ) -> bool {
        let Some(source) = self.fonts_get_large_icon_source_like_java(name) else {
            return false;
        };
        self.push_large_icon_source_like_java(pass, &source, rect, tint, layer);
        true
    }

