    fn cached_content_icon_atlas_visibility_key_for_font_glyph_upload(
        &self,
        registry_key: (usize, u64),
    ) -> (usize, u64) {
        if let Some(atlas_visibility_key) = self
            .font_glyph_content_icon_atlas_visibility_key_cache
            .borrow()
            .as_ref()
            .filter(|cache| cache.registry_key == registry_key)
            .map(|cache| cache.atlas_visibility_key)
        {
            return atlas_visibility_key;
        }

        let atlas_visibility_key = desktop_content_icon_atlas_visibility_cache_key(
            &self.content_icon_glyph_registry,
            &self.texture_atlas,
        );
        *self
            .font_glyph_content_icon_atlas_visibility_key_cache
            .borrow_mut() = Some(DesktopFontGlyphContentIconAtlasVisibilityKeyCache {
            registry_key,
            atlas_visibility_key,
        });
        self.font_glyph_content_icon_atlas_visibility_key_cache_rebuilds
            .set(
                self.font_glyph_content_icon_atlas_visibility_key_cache_rebuilds
                    .get()
                    .saturating_add(1),
            );
        atlas_visibility_key
    }

    fn invalidate_content_icon_atlas_visibility_dependent_caches(&self) {
        *self
            .font_glyph_content_icon_atlas_visibility_key_cache
            .borrow_mut() = None;
        self.content_icon_runtime_registry_last_frame_validation
            .set(None);
    }

    fn note_texture_atlas_region_changed_for_content_icon_visibility(&self, region_name: &str) {
        if self
            .content_icon_glyph_registry
            .get_by_atlas_symbol(region_name)
            .is_some()
        {
            self.invalidate_content_icon_atlas_visibility_dependent_caches();
        }
    }

    fn font_glyph_upload_plan_cache_key(&self) -> DesktopFontGlyphUploadPlanCacheKey {
        let content_icon_registry_key =
            desktop_content_icon_registry_cache_key(&self.content_icon_glyph_registry);
        DesktopFontGlyphUploadPlanCacheKey {
            locale: desktop_normalize_bundle_locale_code(&self.font_locale),
            font_asset_sources_key: desktop_font_asset_sources_cache_key(&self.font_asset_sources),
            content_icon_registry_key,
            content_icon_atlas_visibility_key: self
                .cached_content_icon_atlas_visibility_key_for_font_glyph_upload(
                    content_icon_registry_key,
                ),
            external_font_seed_key: desktop_external_font_seed_key(),
        }
    }

    fn cached_font_glyph_upload_plan_for_frame(&mut self) -> DesktopFontGlyphUploadPlan {
        let key = self.font_glyph_upload_plan_cache_key();
        let should_rebuild = self
            .font_glyph_upload_plan_cache
            .as_ref()
            .map_or(true, |cache| cache.key != key);
        if should_rebuild {
            let plan = self.font_glyph_upload_plan();
            self.font_glyph_upload_plan_cache = Some(DesktopFontGlyphUploadPlanCache { key, plan });
            self.font_glyph_upload_plan_cache_rebuilds += 1;
        }
        self.font_glyph_upload_plan_cache
            .as_ref()
            .expect("font glyph upload plan cache should be populated before frame use")
            .plan
            .clone()
    }

    #[cfg(test)]
    fn font_glyph_upload_plan_cache_rebuilds(&self) -> u64 {
        self.font_glyph_upload_plan_cache_rebuilds
    }

    #[cfg(test)]
    fn font_glyph_content_icon_atlas_visibility_key_cache_rebuilds(&self) -> u64 {
        self.font_glyph_content_icon_atlas_visibility_key_cache_rebuilds
            .get()
    }

    pub fn merge_mod_directory_into_texture_atlas(
        &mut self,
        mod_name: impl Into<String>,
        headless: bool,
        root: impl AsRef<Path>,
    ) -> io::Result<usize> {
        let mod_name = mod_name.into();
        let root = root.as_ref();
        let plan = ModResourceDirectoryPlan::from_directory(mod_name.clone(), headless, root)?;
        self.last_mods_directory_mod_names = vec![mod_name];
        self.last_mods_directory_mod_roots = vec![plan.root.to_string_lossy().into_owned()];
        self.last_mods_directory_mod_metas = vec![plan.meta.clone()];
        self.last_mods_directory_mod_states = vec![DesktopModsRouteModStateSnapshot::default()];
        let icon_symbol =
            self.merge_mod_resource_icon_into_texture_atlas(&plan.mod_name, &plan.resource_plan);
        self.last_mods_directory_mod_icon_symbols = vec![icon_symbol];
        self.mods_selected_mod_index = None;
        self.mods_delete_dialog_index = None;
        self.refresh_mods_directory_bundle_values_like_java();
        Ok(self.merge_mod_resource_plan_into_texture_atlas(&plan.resource_plan))
    }

    pub fn merge_mods_directory_into_texture_atlas(
        &mut self,
        mods_dir: impl AsRef<Path>,
        headless: bool,
    ) -> io::Result<usize> {
        let container = ModResourceContainerPlan::discover_from_mods_directory(mods_dir, headless)?;
        Ok(self.merge_mod_resource_container_plan_into_texture_atlas(&container))
    }

    pub fn merge_mod_resource_container_plan_into_texture_atlas(
        &mut self,
        container: &ModResourceContainerPlan,
    ) -> usize {
        self.last_mods_directory_mod_names = container
            .mods
            .iter()
            .map(|mod_dir| mod_dir.mod_name.clone())
            .collect();
        self.last_mods_directory_mod_roots = container
            .mods
            .iter()
            .map(|mod_dir| mod_dir.root.to_string_lossy().into_owned())
            .collect();
        self.last_mods_directory_mod_metas = container
            .mods
            .iter()
            .map(|mod_dir| mod_dir.meta.clone())
            .collect();
        self.last_mods_directory_mod_states =
            vec![DesktopModsRouteModStateSnapshot::default(); container.mods.len()];
        self.last_mods_directory_mod_icon_symbols = container
            .mods
            .iter()
            .map(|mod_dir| {
                self.merge_mod_resource_icon_into_texture_atlas(
                    &mod_dir.mod_name,
                    &mod_dir.resource_plan,
                )
            })
            .collect();
        self.mods_selected_mod_index = None;
        self.mods_delete_dialog_index = None;
        self.refresh_mods_directory_bundle_values_like_java();
        container
            .mods
            .iter()
            .map(|mod_dir| self.merge_mod_resource_plan_into_texture_atlas(&mod_dir.resource_plan))
            .sum()
    }

    pub fn merge_mods_directory_arg_into_texture_atlas(&mut self) -> io::Result<usize> {
        let Some(mods_dir) = self.mods_directory_arg.clone() else {
            self.last_mods_directory_merge_count = Some(0);
            self.mods_directory_error = None;
            self.last_mods_directory_mod_names.clear();
            self.last_mods_directory_mod_roots.clear();
            self.last_mods_directory_mod_metas.clear();
            self.last_mods_directory_mod_states.clear();
            self.last_mods_directory_mod_icon_symbols.clear();
            self.last_mods_directory_bundle_values.clear();
            self.mods_selected_mod_index = None;
            self.mods_delete_dialog_index = None;
            return Ok(0);
        };

        match self.merge_mods_directory_into_texture_atlas(&mods_dir, false) {
            Ok(count) => {
                self.last_mods_directory_merge_count = Some(count);
                self.mods_directory_error = None;
                self.mods_selected_mod_index = None;
                Ok(count)
            }
            Err(error) => {
                self.last_mods_directory_merge_count = None;
                self.mods_directory_error = Some(error.to_string());
                self.last_mods_directory_mod_names.clear();
                self.last_mods_directory_mod_roots.clear();
                self.last_mods_directory_mod_metas.clear();
                self.last_mods_directory_mod_states.clear();
                self.last_mods_directory_mod_icon_symbols.clear();
                self.last_mods_directory_bundle_values.clear();
                self.mods_selected_mod_index = None;
                self.mods_delete_dialog_index = None;
                Err(error)
            }
        }
    }

    pub fn merge_mod_resource_plan_into_texture_atlas(&mut self, plan: &ModResourcePlan) -> usize {
        let mod_atlas = TextureAtlasPlan::from_sprite_sources(
            plan.sprite_sources.iter().filter_map(|source| {
                let request = source.to_request()?;
                if let Some(bytes) = source.source_bytes.as_ref() {
                    Arc::make_mut(&mut self.mod_texture_source_bytes)
                        .insert(request.atlas_name.clone(), bytes.clone());
                } else {
                    Arc::make_mut(&mut self.mod_texture_source_bytes).remove(&request.atlas_name);
                }
                let texture_scale = request.texture_scale();
                Some(
                    TextureAtlasSpriteSourceDescriptor::new(
                        request.source_path,
                        request.atlas_name,
                    )
                    .with_page_hint(request.page_hint)
                    .with_override(request.r#override)
                    .with_texture_scale(texture_scale)
                    .with_dimensions(request.dimensions),
                )
            }),
        );
        let mut merged = 0;

        for page in mod_atlas.pages {
            let page_type = page.page_type;
            for region in page.regions {
                let region_name = region.name.clone();
                let _ = Arc::make_mut(&mut self.texture_atlas)
                    .insert_or_replace_region(page_type, region);
                self.note_texture_atlas_region_changed_for_content_icon_visibility(&region_name);
                merged += 1;
            }
        }

        merged
    }

    fn mod_icon_atlas_symbol(mod_name: &str) -> String {
        let normalized = mod_name
            .trim()
            .replace([':', ' ', '/', '\\'], "_")
            .trim_matches('_')
            .to_string();
        format!(
            "mod-icon-{}",
            if normalized.is_empty() {
                "unnamed"
            } else {
                normalized.as_str()
            }
        )
    }

    fn merge_mod_resource_icon_into_texture_atlas(
        &mut self,
        mod_name: &str,
        plan: &ModResourcePlan,
    ) -> Option<String> {
        let source = plan.icon.source.as_ref()?;
        let symbol = Self::mod_icon_atlas_symbol(mod_name);
        if let Some(bytes) = source.source_bytes.as_ref() {
            Arc::make_mut(&mut self.mod_texture_source_bytes).insert(symbol.clone(), bytes.clone());
        } else {
            Arc::make_mut(&mut self.mod_texture_source_bytes).remove(&symbol);
        }
        let icon_atlas =
            TextureAtlasPlan::from_sprite_sources([TextureAtlasSpriteSourceDescriptor::new(
                source.source_path.clone(),
                symbol.clone(),
            )
            .with_page_hint("ui")
            .with_dimensions(source.dimensions)]);
        for page in icon_atlas.pages {
            let page_type = page.page_type;
            for region in page.regions {
                let region_name = region.name.clone();
                let _ = Arc::make_mut(&mut self.texture_atlas)
                    .insert_or_replace_region(page_type, region);
                self.note_texture_atlas_region_changed_for_content_icon_visibility(&region_name);
            }
        }
        Some(symbol)
    }

    fn active_accelerator_launch_animation_config(
        &self,
    ) -> Option<DesktopAcceleratorLaunchAnimationConfig> {
        for (tile_pos, state) in &self.runtime.campaign_runtime_states {
            let GameRuntimeCampaignBlockState::Accelerator(state) = state else {
                continue;
            };
            if !state.launching {
                continue;
            }

            let Some(block_id) = self
                .runtime
                .buildings
                .iter()
                .find(|building| building.tile_pos == *tile_pos)
                .map(|building| building.block.id)
                .or_else(|| {
                    self.game_state
                        .world
                        .tile(point2_x(*tile_pos) as i32, point2_y(*tile_pos) as i32)
                        .map(|tile| tile.block)
                })
            else {
                continue;
            };
            let Some(BlockDef::Campaign(campaign_block)) = self.content_loader.block(block_id)
            else {
                continue;
            };
            if let Some(config) = accelerator_launch_animation_config(*tile_pos, campaign_block) {
                return Some(config);
            }
        }

        None
    }

    fn skip_core_animation_like_java(&self) -> bool {
        self.settings_overrides
            .get("skipcoreanimation")
            .and_then(|value| Self::settings_parse_bool(value))
            .unwrap_or(false)
    }

    fn begin_campaign_core_launch_cutscene_like_java(&mut self) {
        if self.skip_core_animation_like_java() {
            self.launch_animation_source = DesktopLaunchAnimationSource::None;
            self.launch_animation_state.clear();
            self.cutscene = false;
            self.land_scale = 1.0;
            self.campaign_core_land_particle_timer = 0.0;
            return;
        }

        self.launch_animation_source = DesktopLaunchAnimationSource::CampaignCore;
        self.launch_animation_state
            .show_launch(DESKTOP_CAMPAIGN_CORE_LAUNCH_DURATION);
        let mut cloud_rand = DesktopArcRand::with_seed(
            (self.game_state.tick.to_bits() as i64) ^ ((self.render_time.to_bits() as i64) << 1),
        );
        self.campaign_core_cloud_seed = cloud_rand.random(1.0);
        self.campaign_core_land_particle_timer = 0.0;
        self.cutscene = self.launch_animation_state.is_cutscene();
        self.land_scale =
            campaign_core_launch_zoom_scale(self.launch_animation_state.get_land_time_in());
    }

    fn tick_campaign_core_launch_dust_like_java(&mut self, delta: f32, land_time_in: f32) -> usize {
        let tsize = desktop_campaign_core_land_dust_timer_step(land_time_in);
        self.campaign_core_land_particle_timer += tsize * delta.max(0.0);
        if self.campaign_core_land_particle_timer < 1.0 {
            return 0;
        }
        self.campaign_core_land_particle_timer = 0.0;

        let default_team = TeamId(self.game_state.rules.default_team as u8);
        let Some((core_tile_pos, core_size)) = self
            .runtime
            .buildings
            .iter()
            .find(|building| {
                building.team == default_team && building.block.flags.contains(&BlockFlag::Core)
            })
            .map(|building| (building.tile_pos, building.block.size.max(1)))
        else {
            return 0;
        };

        let center = desktop_building_center(
            TileCoord::new(
                point2_x(core_tile_pos) as i32,
                point2_y(core_tile_pos) as i32,
            ),
            core_size.min(u8::MAX as i32) as u8,
            mindustry_core::mindustry::vars::TILE_SIZE as f32,
        );
        let mut rand = DesktopArcRand::with_seed(
            (core_tile_pos as i64)
                ^ ((land_time_in.to_bits() as i64) << 1)
                ^ ((self.render_time.to_bits() as i64) << 17)
                ^ self.game_state.tick.to_bits() as i64,
        );
        let effect_id = FX_CORE_LAND_DUST_ID as u16;
        let mut events = Vec::new();

        for (x, y) in footprint_tiles(
            point2_x(core_tile_pos) as i32,
            point2_y(core_tile_pos) as i32,
            core_size,
        ) {
            let Some(tile) = self.game_state.world.tile(x, y) else {
                continue;
            };
            if rand.next_float() >= 0.4 {
                continue;
            }

            let position = RenderPoint::new(tile.world_x(), tile.world_y());
            let rotation =
                desktop_angle_between(center, position) + rand.random_between(-30.0, 30.0);
            let color_mul = 1.5 + rand.random_between(-0.15, 0.15);
            let floor_color = self
                .content_loader
                .block(tile.floor_id())
                .map(|block| block.base().map_color_rgba)
                .unwrap_or(0);
            let color = desktop_mul_rgba8888_rgb_like_arc(floor_color, color_mul);

            events.push(EffectCallPacket2 {
                effect: EffectCallPacket {
                    effect_id,
                    x: position.x,
                    y: position.y,
                    rotation,
                    color: type_io::RgbaColor::new(color as i32),
                },
                data: TypeValue::Null,
            });
        }

        let queued = events.len();
        self.runtime.client_local_effect_events.extend(events);
        queued
    }

    pub fn tick_accelerator_launch_animations_for_render(
        &mut self,
        delta: f32,
    ) -> Option<LaunchAnimationStep> {
        let Some(config) = self.active_accelerator_launch_animation_config() else {
            if self.launch_animation_source == DesktopLaunchAnimationSource::CampaignCore {
                let step = self
                    .launch_animation_state
                    .tick(delta, self.game_state.is_paused());
                if step.should_update_launch {
                    self.tick_campaign_core_launch_dust_like_java(delta, step.land_time_in);
                }
                if step.ended {
                    self.launch_animation_source = DesktopLaunchAnimationSource::None;
                    self.cutscene = false;
                    self.land_scale = 1.0;
                    self.campaign_core_land_particle_timer = 0.0;
                    if let Some(destination) =
                        self.campaign_launch_pending_destination_sector.take()
                    {
                        self.launch_campaign_smoke_world_for_sector(Some(destination));
                    }
                } else {
                    self.cutscene = self.launch_animation_state.is_cutscene();
                    self.land_scale = if self.cutscene {
                        campaign_core_launch_zoom_scale(step.land_time_in)
                    } else {
                        1.0
                    };
                }
                return Some(step);
            }

            self.launch_animation_source = DesktopLaunchAnimationSource::None;
            self.launch_animation_state.clear();
            self.cutscene = false;
            self.land_scale = 1.0;
            self.campaign_core_land_particle_timer = 0.0;
            return None;
        };

        if self.launch_animation_source != DesktopLaunchAnimationSource::Accelerator
            || !self.launch_animation_state.active
            || !self.launch_animation_state.launching
            || (self.launch_animation_state.launch_duration - config.total_duration).abs()
                > f32::EPSILON
        {
            self.launch_animation_source = DesktopLaunchAnimationSource::Accelerator;
            self.launch_animation_state
                .show_launch(config.total_duration);
            self.campaign_core_land_particle_timer = 0.0;
        }

        let step = self
            .launch_animation_state
            .tick(delta, self.game_state.is_paused());

        if step.should_update_launch {
            if let Some(GameRuntimeCampaignBlockState::Accelerator(state)) = self
                .runtime
                .campaign_runtime_states
                .get_mut(&config.tile_pos)
            {
                let launch_time = config.total_duration - step.land_time_in * config.total_duration;
                state.launch_time = launch_time.clamp(0.0, config.total_duration);
            }
        }

        if step.ended {
            if let Some(GameRuntimeCampaignBlockState::Accelerator(state)) = self
                .runtime
                .campaign_runtime_states
                .get_mut(&config.tile_pos)
            {
                state.launching = false;
                state.launch_time = 0.0;
            }
            self.cutscene = false;
            self.land_scale = 1.0;
            self.launch_animation_source = DesktopLaunchAnimationSource::None;
            return Some(step);
        }

        self.cutscene = self.launch_animation_state.is_cutscene();
        self.land_scale = if self.cutscene {
            accelerator_launch_zoom_scale(config, step.land_time, step.land_time_in)
        } else {
            1.0
        };

        Some(step)
    }

    pub fn update(&mut self) {
        if !self.game_state.is_paused() {
            self.render_time = (self.render_time + 1.0).max(0.0);
        }
        self.tick_campaign_planet_new_presets_like_java(1.0);
        self.tick_campaign_complete_pending_like_java(1.0);
        if self.active_menu_route == Some(DesktopMenuRoute::SaveGame) && self.game_state.is_menu() {
            self.close_play_entry_ui_state_like_java();
        }
        if self.has_renderable_world_for_default_frame() {
            self.tick_save_game_pending_save();
        }
        self.tick_host_pending_run();
        self.client.update();
        self.net_client.update();
        self.sync_join_reconnect_from_net_state();
        self.poll_join_reconnect();
        self.sync_join_connection_error_dialog_from_net_state();
        self.poll_join_local_discovery();
        self.poll_join_saved_server_refreshes();
        self.sync_loaded_world_data();
        self.sync_client_loaded_state();
        self.sync_state_snapshot();
        self.sync_game_over_winner_from_net_client();
        self.sync_snapshot_mirrors();
        self.runtime
            .update_client_effect_snapshot_parent_transforms();
        self.sync_building_storage_mirrors_to_runtime();
        self.sync_unit_item_mirrors_to_runtime();
        self.sync_unit_payload_mirrors_to_runtime();
        self.sync_unit_entered_payload_to_runtime();
        self.sync_unit_tether_block_spawned_to_runtime();
        self.sync_unit_lifecycle_to_runtime();
        self.sync_unit_spawn_packets_to_runtime();
        self.sync_world_update_events_to_runtime();
        self.sync_runtime_trigger_events_to_service();
        self.sync_tile_config_to_runtime();
        self.sync_command_building_to_runtime();
        self.sync_player_trace_dialog_from_net_client();
        self.sync_effect_packets_to_runtime();
        let now_millis = current_millis();
        self.sync_remote_player_snapshots_from_runtime();
        self.update_player_list_spectating_like_java();
        self.update_player_list_visibility_like_java();
        self.update_chat_visibility_like_java(self.hud_fragment.shown);
        self.tick_chat_fade_like_java(1.0);
        self.sync_remote_preview_plan_packets(now_millis);
        self.rebuild_other_player_preview_overlays_at(now_millis, 1.0, None);
        self.runtime.tick_client_move_effect_abilities(1.0, false);
        self.tick_client_unit_snapshot_hard_shadow_alpha_for_render(1.0);
        self.runtime.tick_client_unit_snapshot_trails(1.0);
        self.runtime
            .tick_client_fire_snapshot_entities(1.0, false, 0.0);
        self.tick_accelerator_launch_animations_for_render(1.0);
        let mut puddle_particle_rand_state = self.puddle_particle_rand_state;
        self.runtime
            .tick_client_puddle_snapshot_particle_effects(1.0, |particle| {
                (
                    next_puddle_particle_range(&mut puddle_particle_rand_state, particle.range),
                    next_puddle_particle_range(&mut puddle_particle_rand_state, particle.range),
                )
            });
        self.puddle_particle_rand_state = puddle_particle_rand_state;
        self.materialize_local_effect_events_for_render();
        self.sync_local_sound_at_events_for_audio();
        let camera_shake_center = self
            .player_list_spectating
            .map(|spectating| RenderPoint::new(spectating.camera_x, spectating.camera_y))
            .unwrap_or_else(|| RenderPoint::new(self.player.x, self.player.y));
        self.sync_local_camera_shake_events_for_render(
            camera_shake_center.x,
            camera_shake_center.y,
        );
        self.tick_camera_shake_for_render(1.0, 4);
        self.tick_local_effect_states_for_render(1.0);
        let standard_local_effect_draw_plans =
            self.collect_standard_local_effect_draw_plans_for_render();
        self.standard_local_effect_circle_primitives = standard_local_effect_draw_plans
            .iter()
            .flat_map(StandardEffectDrawPlan::circle_render_primitives_from_seed)
            .collect();
        self.standard_local_effect_square_primitives = standard_local_effect_draw_plans
            .iter()
            .flat_map(StandardEffectDrawPlan::square_render_primitives_from_seed)
            .collect();
        self.standard_local_effect_rect_primitives = standard_local_effect_draw_plans
            .iter()
            .flat_map(StandardEffectDrawPlan::rect_render_primitives_from_seed)
            .collect();
        self.standard_local_effect_line_primitives = standard_local_effect_draw_plans
            .iter()
            .flat_map(StandardEffectDrawPlan::line_render_primitives_from_seed)
            .collect();
        self.standard_local_effect_triangle_primitives = standard_local_effect_draw_plans
            .iter()
            .flat_map(StandardEffectDrawPlan::triangle_render_primitives_from_seed)
            .collect();
        self.standard_local_effect_light_primitives = standard_local_effect_draw_plans
            .iter()
            .flat_map(StandardEffectDrawPlan::light_render_primitives)
            .collect();
        self.standard_local_effect_draw_plans = standard_local_effect_draw_plans;
    }

    fn player_list_context_like_java(&self) -> PlayerListContext {
        let (net_active, net_server, net_client) = {
            let net = self.net_client.net_mut();
            (net.active(), net.server(), net.client())
        };

        PlayerListContext {
            net_active,
            net_server,
            net_client,
            state_is_game: self.game_state.is_game(),
            campaign: self.game_state.is_campaign(),
            pvp: self.game_state.rules.pvp,
            infinite_resources: self.game_state.rules.infinite_resources,
            fog: self.game_state.rules.fog,
            local_player_id: self.player.id,
            local_player_team: self.player.team.0 as i32,
            local_player_admin: self.player.admin,
        }
    }

    fn player_list_player_from_comp_like_java(
        player: &PlayerComp,
        local: bool,
    ) -> PlayerListPlayer {
        PlayerListPlayer {
            id: player.id,
            uuid: player.uuid().to_string(),
            name: player.name.clone(),
            stripped_name: player.plain_name(),
            color: format!("{:08X}", player.color),
            team: player.team.0 as i32,
            local,
            admin: player.admin,
            dead: player.dead(),
            has_connection: local || player.con.is_some(),
        }
    }

    fn player_list_players_like_java(&self) -> Vec<PlayerListPlayer> {
        let mut players = Vec::with_capacity(self.remote_players.len() + 1);
        players.push(Self::player_list_player_from_comp_like_java(
            &self.player,
            true,
        ));
        players.extend(
            self.remote_players
                .values()
                .map(|player| Self::player_list_player_from_comp_like_java(player, false)),
        );
        players
    }

    pub fn player_list_visible_like_java(&self) -> bool {
        self.player_list_fragment.visible()
    }

    pub fn player_list_model_like_java(&self) -> Option<PlayerListModel> {
        if !self.player_list_fragment.visible() {
            return None;
        }

        let players = self.player_list_players_like_java();
        let context = self.player_list_context_like_java();
        Some(self.player_list_fragment.rebuild(&players, &context))
    }

    pub fn update_player_list_visibility_like_java(&mut self) {
        let context = self.player_list_context_like_java();
        self.player_list_fragment.update_visibility(&context);
        if !(context.net_active && context.state_is_game) {
            self.player_trace_dialog = None;
        }
        self.last_player_list_model = if self.player_list_fragment.visible() {
            let players = self.player_list_players_like_java();
            Some(self.player_list_fragment.rebuild(&players, &context))
        } else {
            None
        };
    }

    pub fn toggle_player_list_like_java(&mut self) -> Option<PlayerListModel> {
        let players = self.player_list_players_like_java();
        let context = self.player_list_context_like_java();
        let model = self.player_list_fragment.toggle(&players, &context);
        self.last_player_list_model = model.clone();
        model
    }

    fn player_by_id_like_java(&self, player_id: i32) -> Option<&PlayerComp> {
        if self.player.id == player_id {
            Some(&self.player)
        } else {
            self.remote_players.get(&player_id)
        }
    }

    fn player_list_spectate_camera_position_like_java(
        &self,
        unit: UnitRef,
        player_x: f32,
        player_y: f32,
    ) -> RenderPoint {
        match unit {
            UnitRef::Unit { id } => self
                .runtime
                .client_unit_snapshot_entities
                .get(&id)
                .map(|unit| RenderPoint::new(unit.x(), unit.y()))
                .unwrap_or_else(|| RenderPoint::new(player_x, player_y)),
            UnitRef::Block { tile_pos } => self
                .runtime
                .buildings
                .iter()
                .find(|building| building.tile_pos == tile_pos)
                .map(|building| RenderPoint::new(building.x, building.y))
                .unwrap_or_else(|| {
                    RenderPoint::new(
                        point2_x(tile_pos) as f32 * TILE_SIZE as f32,
                        point2_y(tile_pos) as f32 * TILE_SIZE as f32,
                    )
                }),
            UnitRef::Null => RenderPoint::new(player_x, player_y),
        }
    }

    fn player_list_spectate_target_team_like_java(
        &self,
        unit: UnitRef,
        player_team: TeamId,
    ) -> Option<TeamId> {
        match unit {
            UnitRef::Unit { id } => self
                .runtime
                .client_unit_snapshot_entities
                .get(&id)
                .map(|unit| unit.is_valid().then_some(unit.team_id()))
                .unwrap_or(Some(player_team)),
            UnitRef::Block { tile_pos } => self
                .runtime
                .buildings
                .iter()
                .find(|building| building.tile_pos == tile_pos)
                .map(|building| (!building.dead).then_some(building.team))
                .unwrap_or(Some(player_team)),
            UnitRef::Null => None,
        }
    }

    fn player_list_spectate_target_like_java(
        &self,
        player_id: i32,
        require_clickable: bool,
    ) -> Option<(String, UnitRef, RenderPoint, TeamId)> {
        let context = self.player_list_context_like_java();
        let player = self.player_by_id_like_java(player_id)?;
        if require_clickable
            && context.fog
            && context.pvp
            && player.team.0 as i32 != context.local_player_team
        {
            return None;
        }
        if player.dead() {
            return None;
        }
        let unit = player.unit_ref()?;
        let position =
            self.player_list_spectate_camera_position_like_java(unit, player.x, player.y);
        let team = self.player_list_spectate_target_team_like_java(unit, player.team)?;
        Some((player.name.clone(), unit, position, team))
    }

    fn player_list_viewplayer_message_like_java(&self, player_name: &str) -> String {
        self.bundle_format_for_current_locale("viewplayer", &[player_name])
            .or_else(|| upstream_menu_bundle_format_for_locale("en", "viewplayer", &[player_name]))
            .unwrap_or_else(|| format!("viewplayer: {player_name}"))
    }

    pub fn spectate_player_list_player_like_java(&mut self, player_id: i32) -> bool {
        let Some((player_name, unit, camera, _team)) =
            self.player_list_spectate_target_like_java(player_id, true)
        else {
            return false;
        };
        let info_message = self.player_list_viewplayer_message_like_java(&player_name);
        self.player_list_spectating = Some(DesktopPlayerListSpectating {
            player_id,
            unit,
            camera_x: camera.x,
            camera_y: camera.y,
        });
        self.last_menu_info_message = Some(info_message);
        true
    }

    pub fn update_player_list_spectating_like_java(&mut self) -> bool {
        let Some(spectating) = self.player_list_spectating else {
            return false;
        };
        let Some((_player_name, unit, camera, team)) =
            self.player_list_spectate_target_like_java(spectating.player_id, false)
        else {
            self.player_list_spectating = None;
            return false;
        };
        if team != self.player.team {
            self.player_list_spectating = None;
            return false;
        }
        self.player_list_spectating = Some(DesktopPlayerListSpectating {
            player_id: spectating.player_id,
            unit,
            camera_x: camera.x,
            camera_y: camera.y,
        });
        true
    }

    pub fn clear_player_list_spectating_like_java(&mut self) -> bool {
        self.player_list_spectating.take().is_some()
    }

    fn player_trace_info_from_comp_like_java(player: &PlayerComp) -> TraceDialogInfo {
        let ip = player.ip().to_string();
        let uuid = player.uuid().to_string();
        let locale = player
            .con
            .as_ref()
            .map(|connection| connection.locale.clone())
            .unwrap_or_else(|| player.locale.clone());
        let modded = player
            .con
            .as_ref()
            .is_some_and(|connection| connection.modclient);
        let mobile = player
            .con
            .as_ref()
            .is_some_and(|connection| connection.mobile);

        TraceDialogInfo {
            ip: ip.clone(),
            locale,
            uuid,
            modded,
            mobile,
            times_joined: 0,
            times_kicked: 0,
            ips: vec![ip],
            names: vec![player.plain_name()],
        }
    }

    fn player_trace_info_from_packet_like_java(
        info: &mindustry_core::mindustry::net::TraceInfo,
    ) -> TraceDialogInfo {
        TraceDialogInfo {
            ip: info.ip.clone().unwrap_or_default(),
            locale: info.locale.clone().unwrap_or_default(),
            uuid: info.uuid.clone().unwrap_or_default(),
            modded: info.modded,
            mobile: info.mobile,
            times_joined: info.times_joined,
            times_kicked: info.times_kicked,
            ips: info.ips.iter().filter_map(Clone::clone).collect(),
            names: info.names.iter().filter_map(Clone::clone).collect(),
        }
    }

    fn show_player_trace_dialog_with_info_like_java(
        &mut self,
        player_id: i32,
        info: TraceDialogInfo,
    ) -> bool {
        let model = {
            let Some(player) = self.player_by_id_like_java(player_id) else {
                return false;
            };
            TraceDialog::new().show(&player.name, &info)
        };
        self.player_trace_dialog = Some(model);
        true
    }

    pub fn show_player_trace_dialog_like_java(&mut self, player_id: i32) -> bool {
        let model = {
            let Some(player) = self.player_by_id_like_java(player_id) else {
                return false;
            };
            let info = Self::player_trace_info_from_comp_like_java(player);
            TraceDialog::new().show(&player.name, &info)
        };
        self.player_trace_dialog = Some(model);
        true
    }

    fn show_player_trace_dialog_from_packet_like_java(
        &mut self,
        packet: &TraceInfoCallPacket,
    ) -> bool {
        let Some(player_id) = packet.player.id else {
            return false;
        };
        let info = Self::player_trace_info_from_packet_like_java(&packet.info);
        self.show_player_trace_dialog_with_info_like_java(player_id, info)
    }

    pub fn show_bans_dialog_like_java(&mut self) -> bool {
        if self.player_list_context_like_java().net_client {
            return false;
        }
        let banned = self
            .net_server_admins
            .get_banned()
            .into_iter()
            .map(|info| BannedPlayerInfo::new(info.id, info.last_ip, info.last_name))
            .collect::<Vec<_>>();
        self.bans_dialog = Some(BansDialog::new().setup(&banned));
        true
    }

    pub fn show_admins_dialog_like_java(&mut self) -> bool {
        if self.player_list_context_like_java().net_client {
            return false;
        }
        let admins = self
            .net_server_admins
            .get_admins()
            .into_iter()
            .map(|info| AdminPlayerInfo::new(info.id, info.last_name))
            .collect::<Vec<_>>();
        self.admins_dialog = Some(AdminsDialog::new().setup(&admins));
        true
    }

    pub fn open_player_list_team_select_like_java(&mut self, player_id: i32) -> bool {
        let context = self.player_list_context_like_java();
        if context.campaign || !(context.pvp || context.infinite_resources) {
            return false;
        }
        let (player_name, current_team) = {
            let Some(player) = self.player_by_id_like_java(player_id) else {
                return false;
            };
            (player.name.clone(), player.team.0)
        };
        let title_key = self
            .bundle_value_for_current_locale("player.team")
            .or_else(|| upstream_menu_bundle_value_for_locale_owned("en", "player.team"))
            .unwrap_or_else(|| "player.team".to_string());
        let teams = vanilla_teams();
        let buttons = teams
            .base_teams()
            .iter()
            .enumerate()
            .map(|(index, team)| DesktopPlayerListTeamSelectButton {
                team_id: team.id,
                team_name: team.name.clone(),
                color_rgba: team.color_rgba,
                row: index / 3,
                column: index % 3,
                checked: team.id == current_team,
                button_size: PLAYER_LIST_TEAM_BUTTON_SIZE,
            })
            .collect::<Vec<_>>();

        self.player_list_team_select = Some(DesktopPlayerListTeamSelect {
            player_id,
            title: format!("{title_key}: {player_name}"),
            buttons,
        });
        true
    }

    pub fn dispatch_player_list_team_select_like_java(&mut self, team_id: u8) -> bool {
        let Some(select) = self.player_list_team_select.take() else {
            return false;
        };
        self.send_player_admin_request_like_java(
            select.player_id,
            AdminAction::SwitchTeam,
            TypeValue::Team(team_id),
        )
    }

    pub fn cancel_player_list_team_select_like_java(&mut self) -> bool {
        self.player_list_team_select.take().is_some()
    }

    pub fn open_player_list_votekick_input_like_java(&mut self, player_id: i32) -> bool {
        let context = self.player_list_context_like_java();
        if !context.net_client {
            return false;
        }
        let player_name = {
            let Some(player) = self.player_by_id_like_java(player_id) else {
                return false;
            };
            player.name.clone()
        };
        let message = self
            .bundle_format_for_current_locale("votekick.reason.message", &[&player_name])
            .or_else(|| {
                upstream_menu_bundle_format_for_locale(
                    "en",
                    "votekick.reason.message",
                    &[&player_name],
                )
            })
            .unwrap_or_else(|| format!("votekick.reason.message: {player_name}"));

        self.player_list_votekick_input = Some(DesktopPlayerListVoteKickInput {
            player_id,
            title: "@votekick.reason",
            message,
            default_text: String::new(),
            max_length: 32,
            numeric: false,
            allow_empty: false,
        });
        true
    }

    pub fn accept_player_list_votekick_reason_like_java(
        &mut self,
        reason: impl Into<String>,
    ) -> Vec<ChatAction> {
        let Some(input) = self.player_list_votekick_input.take() else {
            return Vec::new();
        };
        let reason = reason.into();
        if reason.is_empty() {
            return Vec::new();
        }
        let command = format!("/votekick #{} {}", input.player_id, reason);
        self.dispatch_chat_actions_like_java(vec![
            ChatAction::FireClientChatEvent(command.clone()),
            ChatAction::SendChatMessage(command),
        ])
    }

    pub fn cancel_player_list_votekick_input_like_java(&mut self) -> bool {
        self.player_list_votekick_input.take().is_some()
    }

    fn send_player_admin_request_like_java(
        &mut self,
        player_id: i32,
        action: AdminAction,
        params: TypeValue,
    ) -> bool {
        let packet = AdminRequestCallPacket {
            other: mindustry_core::mindustry::io::EntityRef::new(player_id),
            action,
            params: params.clone(),
        };
        self.last_player_admin_request = Some(DesktopPlayerAdminRequest { player_id, action });
        self.last_player_admin_request_params = Some(params);
        let _ = self
            .net_client
            .net_mut()
            .send(&PacketKind::AdminRequestCallPacket(packet), true);
        true
    }

    fn player_admin_confirm_message_like_java(
        &self,
        action: &DesktopPlayerListAdminConfirmAction,
        player_name: &str,
    ) -> String {
        let key = match action {
            DesktopPlayerListAdminConfirmAction::AdminRequest {
                action: AdminAction::Ban,
            } => "confirmban",
            DesktopPlayerListAdminConfirmAction::AdminRequest {
                action: AdminAction::Kick,
            } => "confirmkick",
            DesktopPlayerListAdminConfirmAction::ToggleAdmin {
                currently_admin: true,
                ..
            } => "confirmunadmin",
            DesktopPlayerListAdminConfirmAction::ToggleAdmin {
                currently_admin: false,
                ..
            } => "confirmadmin",
            _ => return String::new(),
        };
        self.bundle_format_for_current_locale(key, &[player_name])
            .or_else(|| upstream_menu_bundle_format_for_locale("en", key, &[player_name]))
            .unwrap_or_else(|| format!("{key}: {player_name}"))
    }

    fn open_player_list_admin_confirm_like_java(
        &mut self,
        player_id: i32,
        action: DesktopPlayerListAdminConfirmAction,
    ) -> bool {
        let player_name = {
            let Some(player) = self.player_by_id_like_java(player_id) else {
                return false;
            };
            player.name.clone()
        };
        let message = self.player_admin_confirm_message_like_java(&action, &player_name);
        self.player_list_admin_confirm = Some(DesktopPlayerListAdminConfirm {
            player_id,
            action,
            title: "@confirm",
            message,
        });
        true
    }

    pub fn confirm_player_list_admin_action_like_java(&mut self) -> bool {
        let Some(confirm) = self.player_list_admin_confirm.take() else {
            return false;
        };
        match confirm.action {
            DesktopPlayerListAdminConfirmAction::AdminRequest { action } => {
                self.send_player_admin_request_like_java(confirm.player_id, action, TypeValue::Null)
            }
            DesktopPlayerListAdminConfirmAction::ToggleAdmin {
                uuid,
                usid,
                currently_admin,
            } => {
                let admin = !currently_admin;
                let (last_ip, last_name) = {
                    let Some(player) = self.remote_players.get_mut(&confirm.player_id) else {
                        return false;
                    };
                    player.admin = admin;
                    (player.ip().to_string(), player.name.clone())
                };
                self.net_server_admins
                    .update_player_joined(uuid.clone(), last_ip, last_name);
                if admin {
                    self.net_server_admins
                        .admin_player(uuid.clone(), usid.clone());
                } else {
                    self.net_server_admins.unadmin_player(&uuid);
                }
                self.last_player_admin_toggle = Some(DesktopPlayerAdminToggle {
                    player_id: confirm.player_id,
                    uuid,
                    usid,
                    admin,
                });
                true
            }
        }
    }

    pub fn cancel_player_list_admin_confirm_like_java(&mut self) -> bool {
        self.player_list_admin_confirm.take().is_some()
    }

    pub fn dispatch_player_list_menu_action_like_java(
        &mut self,
        action: PlayerListPlayerMenuAction,
    ) -> bool {
        match action {
            PlayerListPlayerMenuAction::Ban { player_id } => self
                .open_player_list_admin_confirm_like_java(
                    player_id,
                    DesktopPlayerListAdminConfirmAction::AdminRequest {
                        action: AdminAction::Ban,
                    },
                ),
            PlayerListPlayerMenuAction::Kick { player_id } => self
                .open_player_list_admin_confirm_like_java(
                    player_id,
                    DesktopPlayerListAdminConfirmAction::AdminRequest {
                        action: AdminAction::Kick,
                    },
                ),
            PlayerListPlayerMenuAction::Trace { player_id } => {
                let context = self.player_list_context_like_java();
                if context.net_client {
                    self.send_player_admin_request_like_java(
                        player_id,
                        AdminAction::Trace,
                        TypeValue::Null,
                    )
                } else {
                    self.show_player_trace_dialog_like_java(player_id)
                }
            }
            PlayerListPlayerMenuAction::OpenTeamSelect { player_id } => {
                self.open_player_list_team_select_like_java(player_id)
            }
            PlayerListPlayerMenuAction::Back => false,
            PlayerListPlayerMenuAction::ToggleAdmin {
                player_id,
                uuid,
                currently_admin,
            } => {
                let usid = {
                    let Some(player) = self.player_by_id_like_java(player_id) else {
                        return false;
                    };
                    player.usid().to_string()
                };
                self.open_player_list_admin_confirm_like_java(
                    player_id,
                    DesktopPlayerListAdminConfirmAction::ToggleAdmin {
                        uuid,
                        usid,
                        currently_admin,
                    },
                )
            }
        }
    }

    pub fn dispatch_player_list_row_action_like_java(
        &mut self,
        action: PlayerListRowAction,
    ) -> bool {
        match action {
            PlayerListRowAction::StartVoteKick { player_id } => {
                self.open_player_list_votekick_input_like_java(player_id)
            }
            PlayerListRowAction::Spectate { player_id } => {
                self.spectate_player_list_player_like_java(player_id)
            }
            PlayerListRowAction::OpenMenu { .. } => false,
        }
    }

    pub fn dispatch_player_list_footer_action_like_java(
        &mut self,
        action: PlayerListFooterButtonAction,
    ) -> Option<PlayerListModel> {
        match action {
            PlayerListFooterButtonAction::Close => self.toggle_player_list_like_java(),
            PlayerListFooterButtonAction::ShowBans => {
                self.show_bans_dialog_like_java();
                None
            }
            PlayerListFooterButtonAction::ShowAdmins => {
                self.show_admins_dialog_like_java();
                None
            }
        }
    }

    pub fn copy_player_trace_row_like_java<P: Platform>(
        &mut self,
        row_index: usize,
        platform: &mut P,
    ) -> bool {
        let Some(model) = self.player_trace_dialog.as_ref() else {
            return false;
        };
        let Some(row) = model.copy_rows.get(row_index) else {
            return false;
        };
        let copy_value = row.copy_value.clone();
        platform.set_clipboard_text(&copy_value);
        self.last_player_trace_clipboard_text = Some(copy_value);
        self.last_menu_info_message = Some(TraceDialog::copy_feedback_key().to_string());
        true
    }

    pub fn close_player_trace_dialog_like_java(&mut self) -> bool {
        self.player_trace_dialog.take().is_some()
    }

    pub fn dispatch_desktop_input_action_like_java(
        &mut self,
        action: DesktopInputAction,
    ) -> Option<PlayerListModel> {
        match action {
            DesktopInputAction::TogglePlayerList => self.toggle_player_list_like_java(),
            DesktopInputAction::ToggleDebugHitboxes
            | DesktopInputAction::ToggleDetachedCamera { .. }
            | DesktopInputAction::ResetMenuState => None,
            DesktopInputAction::ClearSpectating => {
                self.clear_player_list_spectating_like_java();
                None
            }
        }
    }

    pub fn dispatch_hud_mobile_button_action_like_java(
        &mut self,
        action: HudMobileButtonAction,
    ) -> Option<PlayerListModel> {
        match action {
            HudMobileButtonAction::TogglePlayerList => self.toggle_player_list_like_java(),
            HudMobileButtonAction::ToggleConsoleMobile => {
                self.toggle_menu_mobile_terminal_like_java();
                None
            }
            HudMobileButtonAction::ToggleChat => {
                self.toggle_chat_like_java(true);
                None
            }
            HudMobileButtonAction::OpenPauseDialog => {
                self.game_state.set(GameStateState::Paused);
                self.paused_dialog_shown_like_java();
                self.active_menu_route = None;
                self.pause_overlay_modal = None;
                self.last_menu_guard_message = None;
                self.last_menu_route_shell_action = None;
                None
            }
            HudMobileButtonAction::ToggleMenus => {
                self.hud_fragment.toggle_menus();
                None
            }
            HudMobileButtonAction::OpenSchematics => {
                self.open_pause_overlay_route(DesktopMenuRoute::Schematics);
                None
            }
            HudMobileButtonAction::TogglePause => {
                self.game_state.set(if self.game_state.is_paused() {
                    GameStateState::Playing
                } else {
                    GameStateState::Paused
                });
                None
            }
            HudMobileButtonAction::OpenResearch => {
                self.open_pause_overlay_route(DesktopMenuRoute::TechTree);
                None
            }
            HudMobileButtonAction::OpenDatabase => {
                self.open_pause_overlay_route(DesktopMenuRoute::Database);
                None
            }
        }
    }

    fn paused_dialog_shown_like_java(&mut self) {
        let context = PauseContext {
            state_is_campaign: self.game_state.is_campaign(),
            ..PauseContext::default()
        };
        for action in PausedDialog::shown_effects(&context) {
            self.dispatch_paused_dialog_shown_action_like_java(action);
        }
    }

    fn dispatch_paused_dialog_shown_action_like_java(&mut self, action: PausedDialogAction) {
        match action {
            PausedDialogAction::SaveCampaignStats => self.save_campaign_stats_like_java(),
            PausedDialogAction::Hide
            | PausedDialogAction::ConfirmQuit { .. }
            | PausedDialogAction::DisconnectQuietly
            | PausedDialogAction::ResumeEditing
            | PausedDialogAction::ResumeAfterPlaytest { .. }
            | PausedDialogAction::ResetLogic
            | PausedDialogAction::SaveCurrentThenReset { .. } => {}
        }
    }

    fn save_campaign_stats_like_java(&mut self) {
        let planet_name = self
            .game_state
            .get_planet_name()
            .expect("campaign state should resolve the current planet")
            .to_string();
        self.settings_overrides.insert(
            format!("{planet_name}-campaign-stats"),
            self.runtime.campaign_stats.to_settings_json_like_java(),
        );
    }

    fn world_tile_in_bounds_for_chat_ping_like_java(x: i32, y: i32) -> bool {
        x >= 0 && y >= 0
    }

    pub fn dispatch_chat_actions_like_java(&mut self, actions: Vec<ChatAction>) -> Vec<ChatAction> {
        self.last_chat_sent_message = None;
        self.last_chat_client_event = None;
        self.last_chat_ping = None;
        self.last_chat_mobile_text_input_max_length = None;

        for action in &actions {
            match action {
                ChatAction::RequestMobileTextInput { max_length } => {
                    self.last_chat_mobile_text_input_max_length = Some(*max_length);
                }
                ChatAction::FireClientChatEvent(message) => {
                    self.last_chat_client_event = Some(message.clone());
                }
                ChatAction::SendChatMessage(message) => {
                    self.last_chat_sent_message = Some(message.clone());
                }
                ChatAction::PingLocation { x, y, text } => {
                    self.last_chat_ping = Some((*x, *y, text.clone()));
                }
                ChatAction::RequestKeyboard
                | ChatAction::ClearKeyboardFocus
                | ChatAction::Hide
                | ChatAction::ScheduleSend { .. } => {}
            }
        }

        self.last_chat_actions = actions.clone();
        actions
    }

    pub fn toggle_chat_like_java(&mut self, mobile: bool) -> Vec<ChatAction> {
        let actions = self.chat_fragment.toggle(mobile, MAX_TEXT_LENGTH);
        self.dispatch_chat_actions_like_java(actions)
    }

    pub fn update_chat_like_java(&mut self, mut frame: ChatUpdateFrame) -> Vec<ChatAction> {
        frame.console_shown |= self.console_fragment.shown();
        frame.player_admin = self.player.admin;
        let actions = self.chat_fragment.update_like_java(&frame);
        self.dispatch_chat_actions_like_java(actions)
    }

    pub fn update_chat_visibility_like_java(&mut self, hud_shown: bool) -> ChatVisibilityUpdate {
        let net_active = {
            let net = self.net_client.net_mut();
            net.active()
        };
        let update = self
            .chat_fragment
            .update_visibility_like_java(net_active, hud_shown);
        self.dispatch_chat_actions_like_java(update.actions.clone());
        self.last_chat_visibility = Some(update.clone());
        update
    }

    pub fn tick_chat_fade_like_java(&mut self, delta: f32) {
        self.chat_fragment.tick_fade_like_java(delta);
    }

    pub fn finish_scheduled_chat_send_like_java(&mut self) -> Vec<ChatAction> {
        let actions = self
            .chat_fragment
            .finish_scheduled_send(Self::world_tile_in_bounds_for_chat_ping_like_java);
        self.dispatch_chat_actions_like_java(actions)
    }

    pub fn accept_mobile_chat_text_like_java(
        &mut self,
        text: impl Into<String>,
    ) -> Vec<ChatAction> {
        self.chat_fragment.set_input(text);
        let actions = self
            .chat_fragment
            .send_message(Self::world_tile_in_bounds_for_chat_ping_like_java);
        let mut dispatched = self.dispatch_chat_actions_like_java(actions);
        dispatched.extend(self.chat_fragment.hide());
        self.last_chat_actions = dispatched.clone();
        dispatched
    }

