    pub fn background_render_pass(&self, camera: RenderCamera) -> Option<RenderPass> {
        if self.game_state.rules.background_texture.is_none()
            && self.game_state.rules.custom_background_callback.is_none()
        {
            return None;
        }

        let mut pass = RenderPass::new(RenderPassKind::Background)
            .with_target(RenderTarget::Buffer("background-buffer".into()))
            .with_resolve(RenderTarget::Screen, RenderResolveKind::DrawRectSample)
            .with_resolve_sample(RenderTextureSamplePlan::background_buffer_geometry_flip(
                camera,
            ));
        pass.push(RenderCommand::custom(
            "background-buffer-render",
            vec![
                RenderProperty::new(
                    "texture",
                    self.game_state
                        .rules
                        .background_texture
                        .as_deref()
                        .unwrap_or(""),
                ),
                RenderProperty::new(
                    "callback",
                    self.game_state
                        .rules
                        .custom_background_callback
                        .as_deref()
                        .unwrap_or(""),
                ),
                RenderProperty::new("speed", self.game_state.rules.background_speed.to_string()),
                RenderProperty::new("scale", self.game_state.rules.background_scl.to_string()),
                RenderProperty::new(
                    "offset_x",
                    self.game_state.rules.background_offset_x.to_string(),
                ),
                RenderProperty::new(
                    "offset_y",
                    self.game_state.rules.background_offset_y.to_string(),
                ),
            ],
        ));
        Some(pass)
    }

    fn desktop_ui_status_bar_model(&self) -> Option<(String, f32, u32)> {
        let connect_error = self.connect_error.as_deref();
        let (connected, connecting) = {
            let state = self.net_client.state();
            let state = state.lock().unwrap();
            (state.connected, state.connecting)
        };
        if !connected && connect_error.is_none() && !connecting {
            return None;
        }

        if let Some(error) = connect_error {
            let label = if error.trim_start().starts_with('@') {
                self.localize_bundle_markup_text(error)
            } else {
                self.localize_bundle_markup_text("@disconnect.error")
            };
            return Some((label, 0.0, 0xff55_55ff));
        }

        if connecting {
            return Some((
                self.localize_bundle_markup_text("@connecting"),
                0.1,
                0xffd3_7fff,
            ));
        }

        let status = self.playable_smoke_status();
        let checks = [
            status.client_ready,
            status.connected,
            status.world_loaded,
            status.confirmed,
            status.game_playing,
            status.runtime_client,
            status.world_width > 0 && status.world_height > 0,
            status.buildings > 0,
            status.player_on_default_team,
        ];
        let ready = checks.iter().filter(|ready| **ready).count();
        let total = checks.len();
        if status.ready() {
            return None;
        }
        Some((
            self.localize_bundle_markup_text("@connecting.data"),
            ready as f32 / total as f32,
            0xffd3_7fff,
        ))
    }

    pub fn show_desktop_hint_like_java(&mut self, name: impl Into<String>) -> bool {
        let name = name.into();
        if self.active_desktop_hint_name.is_some() || self.completed_desktop_hints.contains(&name) {
            return false;
        }
        self.active_desktop_hint_name = Some(name);
        true
    }

    pub fn hide_desktop_hint_like_java(&mut self) -> bool {
        self.active_desktop_hint_name.take().is_some()
    }

    pub fn complete_desktop_hint_like_java(&mut self) -> bool {
        let Some(name) = self.active_desktop_hint_name.take() else {
            return false;
        };
        self.completed_desktop_hints.insert(name);
        true
    }

    pub fn desktop_hint_shown_like_java(&self) -> bool {
        self.active_desktop_hint_name.is_some()
    }

    fn desktop_hint_missing_bundle_fallback_text(name: &str) -> String {
        let mut label = String::new();
        let mut previous_was_word = false;
        for ch in name.chars() {
            if matches!(ch, '-' | '_' | '.') {
                if !label.ends_with(' ') && !label.is_empty() {
                    label.push(' ');
                }
                previous_was_word = false;
                continue;
            }
            if ch.is_uppercase() && previous_was_word && !label.ends_with(' ') {
                label.push(' ');
            }
            if label.is_empty() {
                for upper in ch.to_uppercase() {
                    label.push(upper);
                }
            } else {
                label.push(ch);
            }
            previous_was_word = ch.is_alphanumeric();
        }
        let label = label.trim();
        if label.is_empty() {
            "Hint".into()
        } else {
            label.to_string()
        }
    }

    fn desktop_hint_text_like_java(&self, name: &str, mobile: bool) -> String {
        let key = format!("hint.{name}");
        let raw = if mobile {
            let mobile_key = format!("{key}.mobile");
            self.bundle_value_for_current_locale(&mobile_key)
                .or_else(|| self.bundle_value_for_current_locale(&key))
        } else {
            self.bundle_value_for_current_locale(&key)
        }
        .unwrap_or_else(|| Self::desktop_hint_missing_bundle_fallback_text(name));
        let text = if mobile {
            raw
        } else {
            raw.replace("tap", "click").replace("Tap", "Click")
        };
        self.format_icons_like_java(text)
    }

    fn desktop_hint_text_width_like_java(&self) -> f32 {
        if self.menu_renderer_state.config.mobile {
            DESKTOP_HINT_TEXT_WIDTH_MOBILE_LIKE_JAVA
        } else {
            DESKTOP_HINT_TEXT_WIDTH_DESKTOP_LIKE_JAVA
        }
    }

    fn desktop_hint_estimated_text_height_like_java(text: &str, text_width: f32) -> f32 {
        let chars_per_line = (text_width / 8.0).max(24.0);
        let mut lines = 0.0f32;
        for line in text.split('\n') {
            lines += ((line.chars().count() as f32).max(1.0) / chars_per_line)
                .ceil()
                .max(1.0);
        }
        (lines * DESKTOP_HINT_TEXT_LINE_HEIGHT).max(DESKTOP_HINT_TEXT_MIN_HEIGHT)
    }

    fn desktop_hint_overlay_rects_like_java(
        viewport: RenderViewport,
        text_width: f32,
        text_height: f32,
    ) -> (RenderRect, RenderRect) {
        let panel_width = text_width + DESKTOP_HINT_MARGIN_LIKE_JAVA * 2.0;
        let panel_height = text_height + DESKTOP_HINT_MARGIN_LIKE_JAVA * 2.0;
        let total_height = panel_height + DESKTOP_HINT_SKIP_BUTTON_HEIGHT_LIKE_JAVA;
        let bottom = viewport.y + (viewport.height - total_height).max(0.0) * 0.5;
        let skip_rect = RenderRect::new(
            viewport.x,
            bottom,
            DESKTOP_HINT_SKIP_BUTTON_WIDTH_LIKE_JAVA,
            DESKTOP_HINT_SKIP_BUTTON_HEIGHT_LIKE_JAVA,
        );
        let panel_rect = RenderRect::new(
            viewport.x,
            bottom + DESKTOP_HINT_SKIP_BUTTON_HEIGHT_LIKE_JAVA,
            panel_width,
            panel_height,
        );
        (panel_rect, skip_rect)
    }

    fn push_desktop_hint_overlay_like_java(
        &self,
        pass: &mut RenderPass,
        viewport: RenderViewport,
        name: &str,
    ) {
        let text_width = self.desktop_hint_text_width_like_java();
        let hint_text =
            self.desktop_hint_text_like_java(name, self.menu_renderer_state.config.mobile);
        let text_height =
            Self::desktop_hint_estimated_text_height_like_java(&hint_text, text_width);
        let (panel_rect, skip_rect) =
            Self::desktop_hint_overlay_rects_like_java(viewport, text_width, text_height);
        pass.push(RenderCommand::fill_rect(
            panel_rect,
            [0.0, 0.0, 0.0, 0.5],
            Layer::END + 0.018,
        ));
        pass.push(RenderCommand::draw_text_styled(
            hint_text,
            RenderPoint::new(
                panel_rect.x + DESKTOP_HINT_MARGIN_LIKE_JAVA,
                panel_rect.center().y,
            ),
            [1.0, 1.0, 1.0, 1.0],
            14.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_wrap_width(text_width)
                .with_integer_position(true),
            Layer::END + 0.019,
        ));

        let hovered = self
            .last_menu_cursor
            .map(|point| skip_rect.contains_point(point))
            .unwrap_or(false);
        let skip_color =
            Self::settings_text_button_font_color("nonet", hovered, false, false, true);
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@hint.skip"),
            skip_rect.center(),
            skip_color,
            15.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            Layer::END + 0.020,
        ));
    }

    pub fn desktop_ui_render_pass(&mut self, viewport: RenderViewport) -> Option<RenderPass> {
        let status_bar_model = self.desktop_ui_status_bar_model();
        let active_hint_name = self.active_desktop_hint_name.clone();
        let (announcement, info_message, toast_message, hud_text) = {
            let state = self.net_client.state();
            let state = state.lock().unwrap();
            (
                state.last_announcement.clone(),
                state.last_info_message.clone(),
                state.last_toast_message.clone(),
                state.last_hud_text.clone(),
            )
        };
        if status_bar_model.is_none()
            && announcement.is_none()
            && info_message.is_none()
            && toast_message.is_none()
            && hud_text.is_none()
            && active_hint_name.is_none()
        {
            return None;
        }

        let mut pass = RenderPass::new(RenderPassKind::Ui);
        if let Some((label, fraction, color)) = status_bar_model {
            self.ui_status_bar.set_name(label);
            self.ui_status_bar.set_fraction(fraction);
            self.ui_status_bar.set_color(color);
            self.ui_status_bar.set_blink_color(0xffff_ffff);
            self.ui_status_bar.outline(0x0000_00ff, 1.0);

            let width = viewport.width.min(260.0).max(96.0);
            let layout = BarLayout {
                x: viewport.x + 12.0,
                y: viewport.y + viewport.height - 28.0,
                width,
                height: 16.0,
                parent_alpha: 1.0,
                label_width: width,
                label_height: 12.0,
                top_min_width: 1.0,
            };
            if let Some(plan) = self.ui_status_bar.draw_plan(layout) {
                push_bar_draw_plan_as_ui_commands(&mut pass, &plan, Layer::END);
            }
        }

        if let Some(text) = hud_text {
            pass.push(RenderCommand::draw_text_styled(
                self.format_icons_like_java(text),
                RenderPoint::new(
                    viewport.x + viewport.width * 0.5,
                    viewport.y + viewport.height - 64.0,
                ),
                [1.0, 1.0, 1.0, 1.0],
                16.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_wrap_width((viewport.width - 80.0).max(120.0))
                    .with_integer_position(true)
                    .with_outline(true),
                Layer::END + 0.020,
            ));
        }
        if let Some(text) = announcement {
            pass.push(RenderCommand::draw_text_styled(
                self.format_icons_like_java(text),
                RenderPoint::new(
                    viewport.x + viewport.width * 0.5,
                    viewport.y + viewport.height * 0.68,
                ),
                [1.0, 0.84, 0.50, 1.0],
                18.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_wrap_width((viewport.width - 80.0).max(120.0))
                    .with_integer_position(true)
                    .with_outline(true),
                Layer::END + 0.021,
            ));
        }
        if let Some(text) = info_message {
            pass.push(RenderCommand::draw_text_styled(
                self.format_icons_like_java(text),
                RenderPoint::new(viewport.x + viewport.width * 0.5, viewport.y + 104.0),
                [0.86, 0.94, 1.0, 1.0],
                14.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_wrap_width((viewport.width - 80.0).max(120.0))
                    .with_integer_position(true)
                    .with_outline(true),
                Layer::END + 0.022,
            ));
        }
        if let Some(text) = toast_message {
            pass.push(RenderCommand::draw_text_styled(
                self.format_icons_like_java(text),
                RenderPoint::new(viewport.x + viewport.width * 0.5, viewport.y + 74.0),
                [1.0, 1.0, 1.0, 1.0],
                14.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_wrap_width((viewport.width - 80.0).max(120.0))
                    .with_integer_position(true)
                    .with_outline(true),
                Layer::END + 0.023,
            ));
        }
        if let Some(name) = active_hint_name {
            self.push_desktop_hint_overlay_like_java(&mut pass, viewport, &name);
        }
        Some(pass)
    }

    pub fn minimap_overlay_plan(
        &mut self,
        camera: MinimapCamera,
        mut input: MinimapOverlayInput,
    ) -> MinimapOverlayPlan {
        let world = self.current_minimap_world_size();
        if world.width <= 0 || world.height <= 0 {
            return MinimapOverlayPlan {
                world_rect: MinimapRect::new(0.0, 0.0, 0.0, 0.0),
                scale_factor: 0.0,
                commands: Vec::new(),
            };
        }

        if self.minimap_renderer_state.world != world {
            self.minimap_renderer_state.reset(world);
        }

        for player in &mut input.players {
            if let Some(text) = player.ping_text.take() {
                player.ping_text = Some(self.format_icons_like_java(&text));
            }
        }

        self.minimap_renderer_state.overlay_plan(camera, input)
    }

    pub fn minimap_texture_frame_plan(&mut self) -> Option<MinimapTextureFramePlan> {
        let world = self.current_minimap_world_size();
        if world.width <= 0 || world.height <= 0 {
            return None;
        }
        if self.minimap_renderer_state.world != world {
            return Some(
                self.minimap_renderer_state
                    .reset(world)
                    .texture_frame_plan(),
            );
        }

        self.minimap_renderer_state.texture_frame_plan()
    }

    pub fn drain_overlay_renderer_plan(&mut self) -> OverlayRendererPlan {
        self.overlay_renderer_state.drain_plan()
    }

    pub fn drain_light_renderer_plan(&mut self) -> LightRendererPlan {
        self.light_renderer_state.drain_plan()
    }

    pub fn light_renderer_plan_to_render_pass(
        &self,
        plan: LightRendererPlan,
    ) -> Option<RenderPass> {
        let mut pass = RenderPass::new(RenderPassKind::Lighting);

        for light in plan.circle_lights {
            pass.push(RenderCommand::draw_circle(
                RenderPoint::new(light.center.0, light.center.1),
                light.radius,
                desktop_light_render_color(light),
                true,
                LIGHT_RENDER_LAYER,
            ));
        }

        for command in plan.commands {
            match command {
                LightCommand::Runnable { label } => {
                    pass.push(RenderCommand::custom(
                        "light-runnable",
                        vec![RenderProperty::new("label", label)],
                    ));
                }
                LightCommand::Region(region) => {
                    let symbol = region.region;
                    let fallback_size = (region.color.radius * 2.0).max(1.0);
                    let (width, height) = self
                        .texture_atlas
                        .lookup(&symbol)
                        .map(|sprite| {
                            (
                                sprite.region.width.max(1) as f32,
                                sprite.region.height.max(1) as f32,
                            )
                        })
                        .unwrap_or((fallback_size, fallback_size));
                    pass.push(RenderCommand::draw_sprite(
                        symbol,
                        RenderRect::from_center(
                            RenderPoint::new(region.x, region.y),
                            width,
                            height,
                        ),
                        desktop_light_render_color(region.color),
                        region.rotation,
                        LIGHT_RENDER_LAYER,
                    ));
                }
                LightCommand::Line {
                    x,
                    y,
                    x2,
                    y2,
                    stroke,
                    tint,
                } => {
                    pass.push(RenderCommand::draw_line(
                        RenderPoint::new(x, y),
                        RenderPoint::new(x2, y2),
                        stroke,
                        desktop_light_render_color(tint),
                        LIGHT_RENDER_LAYER,
                    ));
                }
            }
        }

        (!pass.commands.is_empty()).then_some(pass)
    }

    pub fn env_render_plan(&self) -> Option<EnvRendererPlan> {
        let context = EnvRendererContext::new(
            self.game_state.rules.env,
            None,
            GraphicsEnv::TERRESTRIAL,
            true,
            self.game_state.rules.fog,
        );
        let plan = self.env_renderer_registry.plan(&context);
        if plan.render_command_count() > 0 {
            Some(plan)
        } else {
            None
        }
    }

    pub fn block_render_plan(
        &mut self,
        mut camera: RenderCamera,
        viewport: RenderViewport,
    ) -> Option<BlockRendererPlan> {
        let world = self.current_minimap_world_size();
        if world.width <= 0 || world.height <= 0 {
            return None;
        }

        let bounds = TileBounds::new(0, 0, world.width, world.height);
        if self.block_renderer_state.cache.block_tree.bounds != bounds {
            self.block_renderer_state =
                BlockRendererState::reload(bounds, self.game_state.rules.limit_map_area);
        }

        camera.viewport = viewport;
        let visible_tiles = visible_block_tiles(camera, viewport, world, 8.0);
        let snapshot = self.block_renderer_world_snapshot(&visible_tiles);
        self.block_renderer_state.cache.tile_view = visible_tiles;

        let plan = self
            .block_renderer_state
            .build_plan_from_snapshot(&snapshot);
        if plan.is_empty() {
            None
        } else {
            Some(plan)
        }
    }

    pub fn floor_render_plan(
        &mut self,
        mut camera: RenderCamera,
        viewport: RenderViewport,
    ) -> Option<FloorRenderPlan> {
        let world = self.current_minimap_world_size();
        if world.width <= 0 || world.height <= 0 {
            return None;
        }

        self.floor_renderer_state
            .set_world_tiles(world.width, world.height);
        camera.viewport = viewport;
        let world_rect = camera.world_rect();
        Some(self.floor_renderer_state.build_plan(FloorViewport::new(
            world_rect.center().x,
            world_rect.center().y,
            world_rect.width,
            world_rect.height,
        )))
    }

    pub fn floor_chunk_draw_batches(
        &mut self,
        mut camera: RenderCamera,
        viewport: RenderViewport,
    ) -> Vec<FloorChunkDrawBatch> {
        let world = self.current_minimap_world_size();
        if world.width <= 0 || world.height <= 0 {
            return Vec::new();
        }

        self.floor_renderer_state
            .set_world_tiles(world.width, world.height);
        camera.viewport = viewport;
        let world_rect = camera.world_rect();
        self.floor_renderer_state
            .build_chunk_draw_batches(FloorViewport::new(
                world_rect.center().x,
                world_rect.center().y,
                world_rect.width,
                world_rect.height,
            ))
    }

    pub fn fog_frame_plan(
        &mut self,
        mut camera: RenderCamera,
        viewport: RenderViewport,
    ) -> Option<FogFramePlan> {
        let world = self.current_minimap_world_size();
        if world.width <= 0 || world.height <= 0 || !self.game_state.rules.fog {
            return None;
        }

        let team = self.player.team.0;
        let discovered = self.game_state.fog_control.get_discovered(team)?;
        let discovered_tiles = (0..discovered.len())
            .map(|index| discovered.get(index))
            .collect::<Vec<_>>();

        camera.viewport = viewport;
        let world_rect = camera.world_rect();
        let mut input = FogFrameInput::new(
            FogViewport::new(
                world.width,
                world.height,
                8,
                world_rect.x,
                world_rect.y,
                world_rect.width,
                world_rect.height,
            ),
            team as u32,
            true,
            self.game_state.rules.static_fog,
            FogColor::WHITE,
            FogColor::BLACK,
        );
        input.discovered_tiles = Some(discovered_tiles);

        self.fog_renderer_state.draw_fog_plan(input)
    }

    pub fn pixelator_frame_plan(
        &mut self,
        mut camera: RenderCamera,
        viewport: RenderViewport,
    ) -> Option<PixelatorFramePlan> {
        camera.viewport = viewport;
        let world_rect = camera.world_rect();
        self.pixelator_state.draw_pixelate_plan(PixelatorInput::new(
            self.pixelate,
            self.renderer_scale,
            self.land_scale,
            self.cutscene,
            viewport.width.max(0.0).round() as i32,
            viewport.height.max(0.0).round() as i32,
            PixelatorCamera::new(
                camera.center.x,
                camera.center.y,
                world_rect.width,
                world_rect.height,
            ),
        ))
    }

    pub fn bloom_render_pass(
        &self,
        camera: RenderCamera,
        viewport: RenderViewport,
        source_frame: &RenderFramePlan,
    ) -> Option<RenderPass> {
        if !self.renderer_bloom_enabled {
            return None;
        }

        let captured_commands = Self::bloom_capture_commands_from_frame(source_frame);
        if captured_commands.is_empty() {
            return None;
        }

        let sample = RenderTextureSamplePlan::new(
            RenderRect::new(viewport.x, viewport.y, viewport.width, viewport.height),
            RenderUvRect::full(),
            RenderTextureSampleFlip::UvY,
        );
        let mut pass = RenderPass::new(RenderPassKind::Bloom)
            .with_target(RenderTarget::Buffer("bloom-buffer".into()))
            .with_resolve(RenderTarget::Screen, RenderResolveKind::ShaderBlit)
            .with_resolve_sample(sample)
            .with_viewport(viewport)
            .with_camera(camera);
        pass.push(RenderCommand::custom(
            "bloom-capture",
            vec![
                RenderProperty::new("captureLayer", (Layer::BULLET - 0.02).to_string()),
                RenderProperty::new("renderLayer", (Layer::EFFECT + 0.02).to_string()),
            ],
        ));
        pass.push(RenderCommand::clear([0.0, 0.0, 0.0, 0.0]));
        pass.push(RenderCommand::set_blend(RenderBlendMode::Additive));
        for command in captured_commands {
            pass.push(command);
        }
        pass.push(RenderCommand::set_blend(RenderBlendMode::Normal));
        pass.push(RenderCommand::custom(
            "bloom-render",
            vec![
                RenderProperty::new("intensity", self.renderer_bloom_intensity.to_string()),
                RenderProperty::new("blurPasses", self.renderer_bloom_blur_passes.to_string()),
            ],
        ));
        Some(pass)
    }

    fn bloom_capture_commands_from_frame(source_frame: &RenderFramePlan) -> Vec<RenderCommand> {
        let min_layer = Layer::BULLET - 0.02;
        let max_layer = Layer::EFFECT + 0.02;
        source_frame
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter(|command| {
                Self::render_command_layer(command)
                    .is_some_and(|layer| (min_layer..=max_layer).contains(&layer))
            })
            .cloned()
            .collect()
    }

    pub fn shader_dispatch_frame_plan(
        &self,
        camera: RenderCamera,
        viewport: RenderViewport,
    ) -> ShaderDispatchFrame {
        let mut context = ShaderApplyContext::default();
        context.camera = Some(ShaderCamera::new(
            camera.center.x,
            camera.center.y,
            viewport.width,
            viewport.height,
        ));
        context.graphics = Some(ShaderViewport::new(viewport.width, viewport.height));
        context.time = self.game_state.tick as f32;
        context.global_time = self.game_state.update_id as f32;

        ShaderDispatchFrame::from_applies([
            ShaderCatalog::apply_plan(ShaderId::Light, &context),
            ShaderCatalog::apply_plan(ShaderId::Shockwave, &context),
        ])
    }

    fn active_menu_pressed_button_for_visuals(&self) -> Option<MenuButtonRole> {
        self.last_menu_pressed_button.or_else(|| {
            (self.last_menu_visual_pressed_frames > 0)
                .then_some(self.last_menu_visual_pressed_button)
                .flatten()
        })
    }

    fn active_menu_pressed_chrome_action_for_visuals(&self) -> Option<DesktopMenuChromeAction> {
        self.last_menu_pressed_chrome_action.or_else(|| {
            (self.last_menu_visual_pressed_chrome_frames > 0)
                .then_some(self.last_menu_visual_pressed_chrome_action)
                .flatten()
        })
    }

    fn apply_menu_visual_pressed_frame_decay(&mut self) {
        if self.last_menu_pressed_button.is_none() && self.last_menu_visual_pressed_frames > 0 {
            self.last_menu_visual_pressed_frames -= 1;
            if self.last_menu_visual_pressed_frames == 0 {
                self.last_menu_visual_pressed_button = None;
            }
        }
        if self.last_menu_pressed_chrome_action.is_none()
            && self.last_menu_visual_pressed_chrome_frames > 0
        {
            self.last_menu_visual_pressed_chrome_frames -= 1;
            if self.last_menu_visual_pressed_chrome_frames == 0 {
                self.last_menu_visual_pressed_chrome_action = None;
            }
        }
    }

    pub fn menu_frame_for_render(&mut self, input: MenuFrameInput) -> DesktopFrame {
        self.menu_renderer_state
            .set_locale(self.settings_locale.clone());
        let mut plan = self
            .menu_renderer_state
            .render_plan_without_ui_render_commands(input);
        self.finalize_menu_frame_plan_for_desktop_visuals(&mut plan);
        DesktopFrame {
            kind: DesktopFrameKind::Menu,
            payload: DesktopFramePayload::Menu(plan),
        }
    }

    fn finalize_menu_frame_plan_for_desktop_visuals(&mut self, plan: &mut MenuFramePlan) {
        self.localize_menu_frame_plan(plan);
        plan.ui = plan
            .ui
            .clone()
            .with_hovered_role(self.last_menu_hovered_button)
            .with_pressed_role(self.active_menu_pressed_button_for_visuals());
        plan.ui_render_commands = MenuUiRenderCommandCache::render_commands_for_plan(
            &mut self.finalized_menu_ui_render_command_cache,
            &plan.ui,
            &mut self.finalized_menu_ui_render_command_cache_rebuilds,
        );
        self.apply_menu_visual_pressed_frame_decay();
    }

    #[cfg(test)]
    fn finalized_menu_ui_render_command_cache_rebuilds(&self) -> usize {
        self.finalized_menu_ui_render_command_cache_rebuilds
    }

    fn refresh_mod_bundle_names_cache_for_locale(&self, locale: &str) {
        if self
            .mod_bundle_names_cache
            .borrow()
            .as_ref()
            .is_some_and(|cache| cache.locale == locale)
        {
            return;
        }
        *self.mod_bundle_names_cache.borrow_mut() = Some(DesktopModBundleNamesCache {
            locale: locale.to_string(),
            names: desktop_mod_bundle_names_for_locale(locale),
        });
        self.mod_bundle_names_cache_rebuilds
            .set(self.mod_bundle_names_cache_rebuilds.get().saturating_add(1));
    }

    fn mod_bundle_value_for_current_locale(&self, key: &str) -> Option<String> {
        let locale = self.settings_current_locale_code_like_java();
        self.refresh_mod_bundle_names_cache_for_locale(&locale);
        let cache = self.mod_bundle_names_cache.borrow();
        let names = cache
            .as_ref()
            .map(|cache| cache.names.as_slice())
            .unwrap_or(&[]);
        for bundle_name in names.iter().rev() {
            if let Some(value) = self
                .last_mods_directory_bundle_values
                .get(bundle_name)
                .and_then(|values| values.get(key))
            {
                return Some(value.clone());
            }
        }
        None
    }

    #[cfg(test)]
    fn mod_bundle_names_cache_rebuilds(&self) -> u64 {
        self.mod_bundle_names_cache_rebuilds.get()
    }

    fn external_bundle_cache_validated_for_active_frame(
        &self,
        data_dir: &str,
        locale: &str,
    ) -> bool {
        let Some(frame_index) = self.external_bundle_active_frame_index.get() else {
            return false;
        };
        if self.external_bundle_cache.borrow().is_none() {
            return false;
        }
        self.external_bundle_last_frame_validation
            .borrow()
            .as_ref()
            .is_some_and(|validation| {
                validation.frame_index == frame_index
                    && validation.data_dir == data_dir
                    && validation.locale == locale
            })
    }

    fn remember_external_bundle_cache_validation_for_active_frame(
        &self,
        data_dir: &str,
        locale: &str,
    ) {
        let Some(frame_index) = self.external_bundle_active_frame_index.get() else {
            return;
        };
        *self.external_bundle_last_frame_validation.borrow_mut() =
            Some(DesktopExternalBundleFrameValidation {
                frame_index,
                data_dir: data_dir.to_string(),
                locale: locale.to_string(),
            });
    }

    fn refresh_external_bundle_cache_for_locale(&self, locale: &str) {
        let data_dir = self.client.context.paths.data_dir.as_str();
        if self.external_bundle_cache_validated_for_active_frame(data_dir, locale) {
            return;
        }

        self.external_bundle_cache_validations.set(
            self.external_bundle_cache_validations
                .get()
                .saturating_add(1),
        );
        if self
            .external_bundle_cache
            .borrow()
            .as_ref()
            .is_some_and(|cache| cache.is_current_for(data_dir, locale))
        {
            self.remember_external_bundle_cache_validation_for_active_frame(data_dir, locale);
            return;
        }

        let cache = DesktopExternalBundleCache::load(data_dir, locale);
        *self.external_bundle_cache.borrow_mut() = Some(cache);
        self.external_bundle_cache_rebuilds
            .set(self.external_bundle_cache_rebuilds.get().saturating_add(1));
        self.remember_external_bundle_cache_validation_for_active_frame(data_dir, locale);
    }

    fn external_bundle_value_for_locale(&self, locale: &str, key: &str) -> Option<Option<String>> {
        self.refresh_external_bundle_cache_for_locale(locale);
        let cache = self.external_bundle_cache.borrow();
        cache
            .as_ref()
            .and_then(|cache| cache.values.as_ref())
            .map(|values| values.get(key).cloned())
    }

    fn external_bundle_readable_path_for_locale(&self, locale: &str) -> Option<PathBuf> {
        self.refresh_external_bundle_cache_for_locale(locale);
        self.external_bundle_cache
            .borrow()
            .as_ref()
            .and_then(|cache| cache.readable_path.clone())
    }

    fn external_bundle_source_paths_for_locale(&self, locale: &str) -> Vec<PathBuf> {
        self.refresh_external_bundle_cache_for_locale(locale);
        self.external_bundle_cache
            .borrow()
            .as_ref()
            .map(|cache| cache.source_paths.clone())
            .unwrap_or_default()
    }

