    fn bundle_value_for_current_locale(&self, key: &str) -> Option<String> {
        let locale = self.settings_current_locale_code_like_java();
        self.mod_bundle_value_for_current_locale(key)
            .or_else(|| desktop_bundle_global_value(key))
            .or_else(|| match self.external_bundle_value_for_locale("en", key) {
                Some(value) => value,
                None => desktop_bundle_value_for_locale(&locale, key),
            })
    }

    fn bundle_format_for_current_locale(&self, key: &str, args: &[&str]) -> Option<String> {
        let mut value = self.bundle_value_for_current_locale(key)?;
        for (index, arg) in args.iter().enumerate() {
            value = value.replace(&format!("{{{index}}}"), arg);
        }
        Some(value)
    }

    fn sync_external_bundle_loaded_notice_like_java(&mut self) {
        let Some(path) = self.external_bundle_readable_path_for_locale("en") else {
            self.external_bundle_notice_path = None;
            return;
        };
        let display_path = path.display().to_string();
        if self.external_bundle_notice_path.as_deref() == Some(display_path.as_str()) {
            return;
        }
        for source_path in self.external_bundle_source_paths_for_locale("en") {
            if let Ok(contents) = desktop_read_utf8_text_file(&source_path) {
                desktop_register_external_font_seed_characters_from_bundle_source(&contents);
            }
        }
        let message = self.format_bundle_text("bundle.external", &[display_path.as_str()]);
        self.external_bundle_notice_path = Some(display_path);
        self.last_menu_info_message = Some(message);
    }

    fn localize_menu_frame_plan(&self, plan: &mut MenuFramePlan) {
        for button in &mut plan.ui.buttons {
            if let Some(key) = button.role.bundle_key() {
                if let Some(label) = self.bundle_value_for_current_locale(key) {
                    button.label = label;
                }
            }
        }
    }

    fn localize_load_text(&self, text: &mut String) {
        *text = self.localize_bundle_markup_text(text.as_str());
    }

    fn localize_load_frame_plan(&self, plan: &mut LoadFramePlan) {
        self.localize_load_text(&mut plan.stage_text);
        self.localize_load_text(&mut plan.prompt_text);
        for command in &mut plan.commands {
            match command {
                LoadRenderCommand::Logo { text, .. }
                | LoadRenderCommand::ProgressBar { label: text, .. }
                | LoadRenderCommand::StageLabel { text, .. }
                | LoadRenderCommand::PromptText { text, .. }
                | LoadRenderCommand::CompletionBanner { message: text, .. } => {
                    self.localize_load_text(text);
                }
                LoadRenderCommand::LoadingFragment {
                    label,
                    cancel_label,
                    ..
                } => {
                    self.localize_load_text(label);
                    self.localize_load_text(cancel_label);
                }
                LoadRenderCommand::ErrorBanner {
                    message, details, ..
                } => {
                    self.localize_load_text(message);
                    if let Some(details) = details {
                        self.localize_load_text(details);
                    }
                }
                LoadRenderCommand::Clear { .. }
                | LoadRenderCommand::BackgroundGlow { .. }
                | LoadRenderCommand::BackgroundGrid { .. }
                | LoadRenderCommand::Planet { .. } => {}
            }
        }
    }

