    fn database_content_display_name(&self, content_type: ContentType, name: &str) -> String {
        match content_type {
            ContentType::Block => self
                .content_loader
                .block_by_name(name)
                .map(|block| block.base().display_name().to_string()),
            ContentType::Item => self
                .content_loader
                .item_by_name(name)
                .map(|item| item.localized_name().to_string()),
            ContentType::Liquid => self
                .content_loader
                .liquid_by_name(name)
                .map(|liquid| liquid.localized_name().to_string()),
            ContentType::Status => self
                .content_loader
                .status_effect_by_name(name)
                .map(|status| status.localized_name().to_string()),
            ContentType::Unit => self
                .content_loader
                .unit_by_name(name)
                .map(|unit| unit.localized_name().to_string()),
            ContentType::Weather => self
                .content_loader
                .weather_by_name(name)
                .map(|weather| weather.weather().localized_name().to_string()),
            ContentType::Sector => self
                .content_loader
                .sector_by_name(name)
                .map(|sector| sector.localized_name.clone()),
            ContentType::Planet => self
                .content_loader
                .catalog()
                .planet_by_name(name)
                .map(|planet| planet.localized_name().to_string()),
            _ => None,
        }
        .unwrap_or_else(|| name.to_string())
    }

    fn database_content_description(
        &self,
        content_type: ContentType,
        name: &str,
    ) -> Option<String> {
        let description = match content_type {
            ContentType::Item => self
                .content_loader
                .item_by_name(name)
                .and_then(|item| item.base.description.clone()),
            ContentType::Liquid => self
                .content_loader
                .liquid_by_name(name)
                .and_then(|liquid| liquid.base.description.clone()),
            ContentType::Status => self
                .content_loader
                .status_effect_by_name(name)
                .and_then(|status| status.base.description.clone()),
            ContentType::Unit => self
                .content_loader
                .unit_by_name(name)
                .and_then(|unit| unit.base.description.clone()),
            ContentType::Weather => self
                .content_loader
                .weather_by_name(name)
                .and_then(|weather| weather.weather().base.description.clone()),
            ContentType::Sector => self
                .content_loader
                .sector_by_name(name)
                .and_then(|sector| sector.description.clone()),
            _ => None,
        };
        let mut description = description?;
        if let Some(mod_source) = self.database_content_mod_source_like_java(content_type, name) {
            let mod_display = self.database_content_mod_display_text_like_java(&mod_source);
            description.push('\n');
            description.push_str(&self.format_bundle_text("mod.display", &[mod_display.as_str()]));
        }
        (!description.trim().is_empty()).then_some(description)
    }

    fn database_content_mod_source_like_java(
        &self,
        content_type: ContentType,
        name: &str,
    ) -> Option<String> {
        match content_type {
            ContentType::Item => self
                .content_loader
                .item_by_name(name)
                .and_then(|item| item.base.mappable.base.source.clone()),
            ContentType::Liquid => self
                .content_loader
                .liquid_by_name(name)
                .and_then(|liquid| liquid.base.mappable.base.source.clone()),
            ContentType::Status => self
                .content_loader
                .status_effect_by_name(name)
                .and_then(|status| status.base.mappable.base.source.clone()),
            ContentType::Unit => self
                .content_loader
                .unit_by_name(name)
                .and_then(|unit| unit.base.mappable.base.source.clone()),
            ContentType::Weather => self
                .content_loader
                .weather_by_name(name)
                .and_then(|weather| weather.weather().base.mappable.base.source.clone()),
            _ => None,
        }
        .map(|source| source.trim().to_string())
        .filter(|source| !source.is_empty())
    }

    fn database_content_mod_display_text_like_java(&self, source: &str) -> String {
        self.last_mods_directory_mod_names
            .iter()
            .enumerate()
            .find_map(|(index, name)| {
                let meta = self.last_mods_directory_mod_metas.get(index);
                let root = self
                    .last_mods_directory_mod_roots
                    .get(index)
                    .map(String::as_str);
                let matches_source = name == source
                    || root == Some(source)
                    || meta
                        .and_then(|meta| meta.name.as_deref())
                        .is_some_and(|name| name == source)
                    || meta
                        .and_then(|meta| meta.display_name.as_deref())
                        .is_some_and(|display| display == source);
                matches_source.then(|| {
                    meta.and_then(ModMetadata::display_name_or_name)
                        .unwrap_or(name)
                        .to_string()
                })
            })
            .unwrap_or_else(|| source.to_string())
    }

