    fn database_content_unlocked(&self, content_type: ContentType, name: &str) -> bool {
        if !self.game_state.is_campaign() && !self.game_state.is_menu() {
            return true;
        }
        match content_type {
            ContentType::Item => self
                .content_loader
                .item_by_name(name)
                .is_some_and(|item| item.base.unlocked()),
            ContentType::Liquid => self
                .content_loader
                .liquid_by_name(name)
                .is_some_and(|liquid| liquid.base.unlocked()),
            ContentType::Status => self
                .content_loader
                .status_effect_by_name(name)
                .is_some_and(|status| status.base.unlocked()),
            ContentType::Unit => self
                .content_loader
                .unit_by_name(name)
                .is_some_and(|unit| unit.base.unlocked()),
            ContentType::Weather => self
                .content_loader
                .weather_by_name(name)
                .is_some_and(|weather| weather.weather().base.unlocked()),
            ContentType::Sector => self
                .content_loader
                .sector_by_name(name)
                .is_some_and(|sector| sector.always_unlocked),
            ContentType::Planet => self
                .content_loader
                .catalog()
                .planet_by_name(name)
                .is_some_and(|planet| planet.always_unlocked),
            _ => true,
        }
    }

    fn database_content_is_banned(&self, content_type: ContentType, name: &str) -> bool {
        self.game_state.is_game()
            && match content_type {
                ContentType::Block => self.game_state.rules.is_block_banned(name),
                ContentType::Unit => self.game_state.rules.is_unit_banned(name),
                _ => false,
            }
    }

    fn database_content_is_patched(&self, content_type: ContentType, name: &str) -> bool {
        self.game_state.is_game()
            && self
                .game_state
                .patcher
                .is_patched_content(content_type.wire_name(), name)
    }

    fn database_block_tag_key(block: &BlockDef) -> &'static str {
        match block {
            BlockDef::Production(_) => "production",
            BlockDef::Storage(_) | BlockDef::Effect(_) | BlockDef::Campaign(_) => "effect",
            BlockDef::Turret(_) => "turret",
            BlockDef::Crafting(_) => "crafting",
            BlockDef::DefenseWall(_) => "defense",
            BlockDef::Distribution(_) => "distribution",
            BlockDef::Liquid(_) => "liquid",
            BlockDef::Power(_) => "power",
            BlockDef::UnitFactory(_)
            | BlockDef::UnitReconstructor(_)
            | BlockDef::UnitAssembler(_)
            | BlockDef::UnitAssemblerModule(_)
            | BlockDef::UnitRepairTower(_) => "units",
            BlockDef::Payload(_)
            | BlockDef::PayloadMassDriver(_)
            | BlockDef::PayloadDeconstructor(_)
            | BlockDef::PayloadConstructor(_)
            | BlockDef::PayloadLoader(_) => "units",
            BlockDef::Sandbox(sandbox) => match sandbox.kind {
                SandboxBlockKind::PowerSource | SandboxBlockKind::PowerVoid => "power",
                SandboxBlockKind::ItemSource | SandboxBlockKind::ItemVoid => "distribution",
                SandboxBlockKind::LiquidSource | SandboxBlockKind::LiquidVoid => "liquid",
                SandboxBlockKind::PayloadSource | SandboxBlockKind::PayloadVoid => "units",
            },
            BlockDef::Light(_) => "effect",
            BlockDef::Logic(_) => "logic",
            _ => "distribution",
        }
    }

    fn database_content_tag_key(&self, content_type: ContentType, name: &str) -> Option<String> {
        let tag = match content_type {
            ContentType::Block => self
                .content_loader
                .block_by_name(name)
                .map(Self::database_block_tag_key),
            ContentType::Item => self
                .content_loader
                .item_by_name(name)
                .map(|item| item.base.database_tag_key()),
            ContentType::Liquid => self
                .content_loader
                .liquid_by_name(name)
                .map(|liquid| liquid.base.database_tag_key()),
            ContentType::Status => self
                .content_loader
                .status_effect_by_name(name)
                .map(|status| status.base.database_tag_key()),
            ContentType::Unit => self.content_loader.unit_by_name(name).map(|unit| {
                unit.base
                    .database_tag
                    .as_deref()
                    .unwrap_or(unit.default_database_tag())
            }),
            ContentType::Weather => self
                .content_loader
                .weather_by_name(name)
                .map(|weather| weather.weather().base.database_tag_key()),
            _ => None,
        }?;
        (tag != "default").then(|| tag.to_string())
    }

