    fn settings_language_dialog_model_like_java(&mut self) -> LanguageDialog {
        self.materialize_settings_default_locale_like_java();
        Self::settings_language_dialog_model_from_selected_locale_like_java(
            self.selected_settings_language_locale_code_like_java(),
        )
    }

    fn settings_language_dialog_render_model_like_java(&self) -> LanguageDialog {
        Self::settings_language_dialog_model_from_selected_locale_like_java(
            self.selected_settings_language_locale_code_like_java(),
        )
    }

    fn settings_data_archive_source_paths(&self) -> Vec<PathBuf> {
        let paths = &self.client.context.paths;
        vec![
            PathBuf::from(&paths.data_dir).join("settings.bin"),
            PathBuf::from(&paths.map_dir),
            PathBuf::from(&paths.save_dir),
            PathBuf::from(&paths.mod_dir),
            PathBuf::from(&paths.schematic_dir),
        ]
    }

    fn settings_data_archive_entry_name(
        base: &Path,
        path: &Path,
        directory: bool,
    ) -> io::Result<String> {
        let relative = path.strip_prefix(base).map_err(|_| {
            io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "settings data path {} is outside data dir {}",
                    path.display(),
                    base.display()
                ),
            )
        })?;
        let mut parts = Vec::new();
        for component in relative.components() {
            match component {
                std::path::Component::Normal(value) => {
                    let value = value.to_string_lossy();
                    if value.is_empty() || value == "." || value == ".." || value.contains(':') {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            format!("invalid settings data archive path {}", path.display()),
                        ));
                    }
                    parts.push(value.into_owned());
                }
                _ => {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        format!("invalid settings data archive path {}", path.display()),
                    ));
                }
            }
        }
        let mut name = parts.join("/");
        if directory && !name.ends_with('/') {
            name.push('/');
        }
        Ok(name)
    }

    fn insert_settings_data_archive_parent_dirs(
        entries: &mut BTreeMap<String, Option<Vec<u8>>>,
        name: &str,
    ) {
        let segments = name
            .trim_end_matches('/')
            .split('/')
            .filter(|segment| !segment.is_empty())
            .collect::<Vec<_>>();
        if segments.len() < 2 {
            return;
        }
        let mut parent = String::new();
        for segment in segments.iter().take(segments.len() - 1) {
            if !parent.is_empty() {
                parent.push('/');
            }
            parent.push_str(segment);
            entries.entry(format!("{parent}/")).or_insert(None);
        }
    }

    fn collect_settings_data_archive_path(
        base: &Path,
        path: &Path,
        entries: &mut BTreeMap<String, Option<Vec<u8>>>,
    ) -> io::Result<()> {
        let metadata = fs::metadata(path)?;
        let directory = metadata.is_dir();
        let name = Self::settings_data_archive_entry_name(base, path, directory)?;
        if !name.is_empty() {
            Self::insert_settings_data_archive_parent_dirs(entries, &name);
            if directory {
                entries.entry(name).or_insert(None);
            } else if metadata.is_file() {
                entries.insert(name, Some(fs::read(path)?));
            }
        }

        if directory {
            let mut children = fs::read_dir(path)?
                .map(|entry| entry.map(|entry| entry.path()))
                .collect::<io::Result<Vec<_>>>()?;
            children.sort_by(|left, right| {
                left.to_string_lossy()
                    .to_ascii_lowercase()
                    .cmp(&right.to_string_lossy().to_ascii_lowercase())
            });
            for child in children {
                Self::collect_settings_data_archive_path(base, &child, entries)?;
            }
        }
        Ok(())
    }

    fn collect_settings_data_archive_entries(
        &self,
    ) -> io::Result<Vec<DesktopSettingsDataArchiveEntry>> {
        let base = PathBuf::from(&self.client.context.paths.data_dir);
        let mut entries = BTreeMap::new();
        for source in self.settings_data_archive_source_paths() {
            if !source.exists() {
                if source.file_name().and_then(|name| name.to_str()) == Some("settings.bin") {
                    return Err(io::Error::new(
                        io::ErrorKind::NotFound,
                        format!("missing settings file {}", source.display()),
                    ));
                }
                continue;
            }
            Self::collect_settings_data_archive_path(&base, &source, &mut entries)?;
        }
        Ok(entries
            .into_iter()
            .map(|(name, data)| DesktopSettingsDataArchiveEntry { name, data })
            .collect())
    }

    fn normalize_settings_data_archive_destination(destination: impl AsRef<Path>) -> PathBuf {
        let destination = destination.as_ref();
        if destination
            .extension()
            .and_then(|extension| extension.to_str())
            .is_some_and(|extension| extension.eq_ignore_ascii_case("zip"))
        {
            destination.to_path_buf()
        } else {
            let mut normalized = destination.to_path_buf();
            normalized.set_extension("zip");
            normalized
        }
    }

    pub fn export_settings_data_to(
        &mut self,
        destination: impl AsRef<Path>,
    ) -> io::Result<DesktopSettingsDataArchiveResult> {
        let destination = Self::normalize_settings_data_archive_destination(destination);
        let entries = self.collect_settings_data_archive_entries()?;
        let bytes = desktop_settings_data_zip_bytes(&entries)?;
        if let Some(parent) = destination.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(&destination, bytes)?;
        let result = desktop_settings_data_zip_result(destination.display().to_string(), &entries);
        self.last_settings_data_export_result = Some(result.clone());
        Ok(result)
    }

    pub fn import_settings_data_from(
        &mut self,
        source: impl AsRef<Path>,
    ) -> io::Result<DesktopSettingsDataArchiveResult> {
        let source = source.as_ref();
        let bytes = fs::read(source)?;
        let entries = desktop_settings_data_zip_entries(&bytes)?;
        if !entries
            .iter()
            .any(|entry| entry.name == "settings.bin" && entry.data.is_some())
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "Not valid save data.",
            ));
        }

        let base = PathBuf::from(&self.client.context.paths.data_dir);
        let save_dir = PathBuf::from(&self.client.context.paths.save_dir);
        let tmp_dir = base.join("tmp");
        for path in [&save_dir, &tmp_dir] {
            match fs::remove_dir_all(path) {
                Ok(()) => {}
                Err(error) if error.kind() == io::ErrorKind::NotFound => {}
                Err(error) => return Err(error),
            }
        }
        fs::create_dir_all(&base)?;

        for entry in &entries {
            let destination = desktop_settings_data_archive_destination(&base, &entry.name)?;
            if let Some(data) = &entry.data {
                if let Some(parent) = destination.parent() {
                    fs::create_dir_all(parent)?;
                }
                fs::write(destination, data)?;
            } else {
                fs::create_dir_all(destination)?;
            }
        }

        self.settings_overrides.clear();
        self.load_settings_locale_from_settings();
        let result = desktop_settings_data_zip_result(source.display().to_string(), &entries);
        self.last_settings_data_import_result = Some(result.clone());
        Ok(result)
    }

    fn normalize_settings_crash_export_destination(destination: impl AsRef<Path>) -> PathBuf {
        let destination = destination.as_ref();
        if destination
            .extension()
            .and_then(|extension| extension.to_str())
            .is_some_and(|extension| extension.eq_ignore_ascii_case("txt"))
        {
            destination.to_path_buf()
        } else {
            let mut normalized = destination.to_path_buf();
            normalized.set_extension("txt");
            normalized
        }
    }

    fn settings_crash_logs_text(&self) -> io::Result<(String, usize, bool)> {
        let data_dir = PathBuf::from(&self.client.context.paths.data_dir);
        let crashes_dir = data_dir.join("crashes");
        let mut text = String::new();
        let mut crash_files = 0usize;

        if crashes_dir.is_dir() {
            let mut entries = fs::read_dir(&crashes_dir)?
                .map(|entry| entry.map(|entry| entry.path()))
                .collect::<io::Result<Vec<_>>>()?;
            entries.sort_by(|left, right| {
                left.file_name()
                    .map(|name| name.to_string_lossy().to_ascii_lowercase())
                    .cmp(
                        &right
                            .file_name()
                            .map(|name| name.to_string_lossy().to_ascii_lowercase()),
                    )
            });
            for path in entries {
                if !path.is_file() {
                    continue;
                }
                let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                    continue;
                };
                let contents = fs::read(&path)?;
                text.push_str(name);
                text.push_str("\n\n");
                text.push_str(&String::from_utf8_lossy(&contents));
                text.push('\n');
                crash_files += 1;
            }
        }

        let last_log = data_dir.join("last_log.txt");
        let included_last_log = last_log.is_file();
        if included_last_log {
            let contents = fs::read(&last_log)?;
            text.push_str("\nlast log:\n");
            text.push_str(&String::from_utf8_lossy(&contents));
        }

        Ok((text, crash_files, included_last_log))
    }

    pub fn export_settings_crash_logs_to(
        &mut self,
        destination: impl AsRef<Path>,
    ) -> io::Result<DesktopSettingsCrashExportResult> {
        let destination = Self::normalize_settings_crash_export_destination(destination);
        let (text, crash_files, included_last_log) = self.settings_crash_logs_text()?;
        if let Some(parent) = destination.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(&destination, text.as_bytes())?;
        let result = DesktopSettingsCrashExportResult {
            file: destination.display().to_string(),
            crash_files,
            included_last_log,
            bytes: text.len(),
        };
        self.last_settings_crash_export_result = Some(result.clone());
        Ok(result)
    }

    pub fn complete_settings_data_export_selection(
        &mut self,
        selected: impl AsRef<str>,
    ) -> io::Result<DesktopSettingsDataArchiveResult> {
        let request = self
            .last_settings_data_export_request
            .clone()
            .unwrap_or_else(|| FileChooserRequest::new(false, "@data.export", "zip"));
        self.export_settings_data_to(request.selected_result(selected.as_ref()))
    }

    pub fn complete_settings_data_import_selection(
        &mut self,
        selected: impl AsRef<str>,
    ) -> io::Result<DesktopSettingsDataArchiveResult> {
        let request = self
            .last_settings_data_import_request
            .clone()
            .unwrap_or_else(|| FileChooserRequest::new(true, "@data.import", "zip"));
        self.import_settings_data_from(request.selected_result(selected.as_ref()))
    }

    pub fn complete_settings_crash_export_selection(
        &mut self,
        selected: impl AsRef<str>,
    ) -> io::Result<DesktopSettingsCrashExportResult> {
        let request = self
            .last_settings_crash_export_request
            .clone()
            .unwrap_or_else(|| FileChooserRequest::new(false, "@crash.export", "txt"));
        self.export_settings_crash_logs_to(request.selected_result(selected.as_ref()))
    }

    fn set_settings_locale(&mut self, code: &'static str) -> bool {
        let locale = Self::settings_closest_locale_code(code);
        if self.selected_settings_language_locale_code_like_java() == locale {
            return false;
        }
        self.player_locale = locale.clone();
        self.settings_overrides.insert("locale".into(), locale);
        self.last_settings_language_restart_message =
            Some(LANGUAGE_DIALOG_RESTART_MESSAGE_KEY.into());
        self.last_menu_info_message = Some(LANGUAGE_DIALOG_RESTART_MESSAGE_KEY.into());
        true
    }

    pub fn take_settings_language_restart_message(&mut self) -> Option<String> {
        self.last_settings_language_restart_message.take()
    }

    pub fn schematic_tags_persisted_json(&self) -> Option<&str> {
        self.settings_overrides
            .get(SCHEMATIC_TAGS_SETTINGS_KEY)
            .map(String::as_str)
    }

    pub fn persist_schematic_tags(&mut self) {
        self.sync_schematic_tag_order();
        self.settings_overrides.insert(
            SCHEMATIC_TAGS_SETTINGS_KEY.to_string(),
            schematic_tags_to_json(&self.schematic_tag_order),
        );
    }

    pub fn load_schematic_tags_from_settings(&mut self) -> usize {
        let Some(value) = self
            .settings_overrides
            .get(SCHEMATIC_TAGS_SETTINGS_KEY)
            .cloned()
        else {
            self.sync_schematic_tag_order();
            return self.schematic_tag_order.len();
        };
        let loaded = schematic_tags_from_json(&value);
        self.schematic_tag_order = loaded;
        self.sync_schematic_tag_order();
        self.schematic_tag_order.len()
    }

    pub fn reset_settings_table_overrides(&mut self, table: &str) -> usize {
        let Some(group) = Self::settings_pref_group(table) else {
            return 0;
        };
        let removed = group
            .entries
            .iter()
            .filter_map(|key| {
                self.settings_overrides
                    .remove(&Self::settings_storage_key(table, key))
                    .map(|_| *key)
            })
            .collect::<Vec<_>>();
        for key in &removed {
            if let Some(default) =
                settings_pref_spec(table, key).map(|spec| spec.default_value.text())
            {
                self.apply_setting_override_side_effect(table, key, &default);
            }
        }
        removed.len()
    }

    fn reset_settings_pref_specs_overrides(&mut self, specs: &[DesktopSettingsPrefSpec]) -> usize {
        let removed = specs
            .iter()
            .filter_map(|spec| {
                self.settings_overrides
                    .remove(&Self::settings_storage_key(spec.table, spec.key))
                    .map(|_| *spec)
            })
            .collect::<Vec<_>>();
        for spec in &removed {
            self.apply_setting_override_side_effect(
                spec.table,
                spec.key,
                &spec.default_value.text(),
            );
        }
        removed.len()
    }

    pub fn reset_current_settings_page_overrides(&mut self) -> usize {
        let removed = match self.settings_dialog_state.page {
            DesktopSettingsPage::Game
            | DesktopSettingsPage::Graphics
            | DesktopSettingsPage::Sound => {
                self.reset_settings_table_overrides(self.settings_dialog_state.page.key())
            }
            DesktopSettingsPage::DynamicCategory => self
                .settings_dynamic_category_page_index
                .and_then(|index| self.settings_dynamic_categories.get(index))
                .map(|category| category.entries.clone())
                .map(|entries| self.reset_settings_pref_specs_overrides(&entries))
                .unwrap_or(0),
            DesktopSettingsPage::Main | DesktopSettingsPage::Data => 0,
        };
        self.settings_text_focused_control = None;
        removed
    }

