    fn settings_tint_with_alpha(mut tint: [f32; 4], alpha_scale: f32) -> [f32; 4] {
        tint[3] *= alpha_scale;
        tint
    }

    fn settings_drawable_symbol_and_tint(
        java_drawable: &str,
        alpha_scale: f32,
    ) -> (String, [f32; 4]) {
        upstream_ui_drawable_alias(java_drawable)
            .map(|alias| {
                (
                    alias.atlas_symbol.to_string(),
                    Self::settings_tint_with_alpha(alias.tint.rgba(), alpha_scale),
                )
            })
            .unwrap_or_else(|| (java_drawable.to_string(), [1.0, 1.0, 1.0, alpha_scale]))
    }

    fn settings_text_button_drawable(
        style_name: &str,
        hovered: bool,
        pressed: bool,
        enabled: bool,
    ) -> &'static str {
        Self::settings_text_button_drawable_with_checked(
            style_name, hovered, pressed, false, enabled,
        )
    }

    fn settings_text_button_drawable_with_checked(
        style_name: &str,
        hovered: bool,
        pressed: bool,
        checked: bool,
        enabled: bool,
    ) -> &'static str {
        let style = upstream_text_button_style_skin(style_name)
            .unwrap_or_else(|| panic!("{style_name} should be present in upstream style registry"));
        if !enabled {
            return style.disabled.or(style.up).unwrap_or("button");
        }
        if pressed {
            style.down.or(style.over).or(style.up)
        } else if checked {
            style.checked.or(style.down).or(style.over).or(style.up)
        } else if hovered {
            style.over.or(style.up)
        } else {
            style.up
        }
        .unwrap_or("button")
    }

    fn settings_text_button_symbol(style_name: &str, hovered: bool, pressed: bool) -> String {
        let drawable = Self::settings_text_button_drawable(style_name, hovered, pressed, true);
        Self::settings_drawable_symbol(drawable)
    }

    fn settings_text_button_symbol_checked(
        style_name: &str,
        hovered: bool,
        pressed: bool,
        checked: bool,
    ) -> String {
        let drawable = Self::settings_text_button_drawable_with_checked(
            style_name, hovered, pressed, checked, true,
        );
        Self::settings_drawable_symbol(drawable)
    }

    fn settings_text_button_symbol_and_tint_checked(
        style_name: &str,
        hovered: bool,
        pressed: bool,
        checked: bool,
        enabled: bool,
        alpha_scale: f32,
    ) -> (String, [f32; 4]) {
        let drawable = Self::settings_text_button_drawable_with_checked(
            style_name, hovered, pressed, checked, enabled,
        );
        Self::settings_drawable_symbol_and_tint(drawable, alpha_scale)
    }

    fn settings_text_button_symbol_and_tint(
        style_name: &str,
        hovered: bool,
        pressed: bool,
        enabled: bool,
        alpha_scale: f32,
    ) -> (String, [f32; 4]) {
        let drawable = Self::settings_text_button_drawable(style_name, hovered, pressed, enabled);
        Self::settings_drawable_symbol_and_tint(drawable, alpha_scale)
    }

    fn settings_text_button_style_uses_java_drawable_border(style_name: &str) -> bool {
        matches!(
            style_name,
            "defaultt"
                | "flatt"
                | "togglet"
                | "flatTogglet"
                | "flatToggleMenut"
                | "grayt"
                | "flatBordert"
        )
    }

    fn settings_text_button_font_color(
        style_name: &str,
        hovered: bool,
        pressed: bool,
        checked: bool,
        enabled: bool,
    ) -> [f32; 4] {
        let style = upstream_text_button_style_skin(style_name)
            .unwrap_or_else(|| panic!("{style_name} should be present in upstream style registry"));
        if !enabled {
            return style.disabled_font_color.rgba();
        }
        if pressed {
            if let Some(color) = style.down_font_color {
                return color.rgba();
            }
        }
        if checked {
            if let Some(color) = style.checked_font_color {
                return color.rgba();
            }
        }
        if hovered {
            if let Some(color) = style.over_font_color {
                return color.rgba();
            }
        }
        style.font_color.rgba()
    }

    fn settings_java_font_role_for_static_name(font: &str) -> Option<UpstreamFontRole> {
        match font {
            "Fonts.def" => Some(UpstreamFontRole::Default),
            "Fonts.outline" => Some(UpstreamFontRole::Outline),
            "Fonts.icon" => Some(UpstreamFontRole::Icon),
            "Fonts.iconLarge" => Some(UpstreamFontRole::IconLarge),
            "Fonts.tech" => Some(UpstreamFontRole::Tech),
            "Fonts.logic" => Some(UpstreamFontRole::Logic),
            "Fonts.monospace" => Some(UpstreamFontRole::Monospace),
            _ => None,
        }
    }

