    fn settings_image_button_symbol(style_name: &str, hovered: bool, pressed: bool) -> String {
        let style = upstream_image_button_style_skin(style_name)
            .unwrap_or_else(|| panic!("{style_name} should be present in upstream style registry"));
        let drawable = if pressed {
            style.down.or(style.over).or(style.up)
        } else if hovered {
            style.over.or(style.up)
        } else {
            style.up
        }
        .unwrap_or("clear");
        Self::settings_drawable_symbol(drawable)
    }

    fn settings_image_button_symbol_checked(
        style_name: &str,
        hovered: bool,
        pressed: bool,
        checked: bool,
    ) -> String {
        let style = upstream_image_button_style_skin(style_name)
            .unwrap_or_else(|| panic!("{style_name} should be present in upstream style registry"));
        let drawable = if pressed {
            style.down.or(style.over).or(style.up)
        } else if checked {
            style.checked.or(style.down).or(style.over).or(style.up)
        } else if hovered {
            style.over.or(style.up)
        } else {
            style.up
        }
        .unwrap_or("clear");
        Self::settings_drawable_symbol(drawable)
    }

    fn settings_image_button_image_color(
        style_name: &str,
        hovered: bool,
        pressed: bool,
        checked: bool,
        enabled: bool,
    ) -> [f32; 4] {
        let style = upstream_image_button_style_skin(style_name)
            .unwrap_or_else(|| panic!("{style_name} should be present in upstream style registry"));
        let color = if !enabled {
            style
                .image_disabled_color
                .or(style.image_up_color)
                .or(Some(mindustry_core::mindustry::ui::UiStyleColor::White))
        } else if pressed {
            style
                .image_down_color
                .or(style.image_over_color)
                .or(style.image_up_color)
        } else if checked {
            style
                .image_checked_color
                .or(style.image_down_color)
                .or(style.image_over_color)
                .or(style.image_up_color)
        } else if hovered {
            style.image_over_color.or(style.image_up_color)
        } else {
            style.image_up_color
        };
        color
            .unwrap_or(mindustry_core::mindustry::ui::UiStyleColor::White)
            .rgba()
    }

