    fn player_color_button_tint(&self) -> [f32; 4] {
        [
            ((self.player.color >> 24) & 0xff) as f32 / 255.0,
            ((self.player.color >> 16) & 0xff) as f32 / 255.0,
            ((self.player.color >> 8) & 0xff) as f32 / 255.0,
            1.0,
        ]
    }

    fn push_player_color_image_button(
        &self,
        pass: &mut RenderPass,
        button: RenderRect,
        layer: f32,
    ) {
        let hovered = self
            .last_menu_cursor
            .map(|point| button.contains_point(point))
            .unwrap_or(false);
        let background = Self::settings_image_button_symbol("squarei", hovered, false);
        if background != "clear" {
            pass.push(RenderCommand::draw_sprite(
                background,
                button,
                [1.0, 1.0, 1.0, 0.92],
                0.0,
                layer,
            ));
        }
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("whiteui"),
            Self::player_color_button_swatch_rect(button),
            self.player_color_button_tint(),
            0.0,
            layer + 0.001,
        ));
    }

