    fn settings_pref_label(&self, key: &str) -> String {
        if cfg!(windows) {
            let windows_key = format!("setting.{key}.name.windows");
            if let Some(label) = self.bundle_value_for_current_locale(&windows_key) {
                return label;
            }
        }
        self.localize_bundle_markup_text_or(Self::settings_pref_label_key(key), key)
    }

