    fn settings_dynamic_category_pref_spec(
        &self,
        table: &str,
        key: &str,
    ) -> Option<DesktopSettingsPrefSpec> {
        self.settings_dynamic_categories
            .iter()
            .flat_map(|category| category.entries.iter())
            .find(|spec| spec.table == table && spec.key == key)
            .copied()
    }

    fn settings_pref_spec_for_runtime(
        &self,
        table: &str,
        key: &str,
    ) -> Option<DesktopSettingsPrefSpec> {
        settings_pref_spec(table, key)
            .copied()
            .or_else(|| self.settings_dynamic_category_pref_spec(table, key))
    }

    fn settings_dynamic_category_main_menu_signature(&self) -> (usize, u64) {
        let mut digest = DESKTOP_JOIN_SAVED_SERVER_SNAPSHOT_KEY_FNV_OFFSET;
        for (index, category) in self.settings_dynamic_categories.iter().enumerate() {
            desktop_join_saved_server_snapshot_key_digest_write_u64(&mut digest, index as u64);
            desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &category.id);
            desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, category.table);
            desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &category.label);
            desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &category.icon);
        }
        (self.settings_dynamic_categories.len(), digest)
    }

    fn settings_visible_main_menu_entries_cache_key(
        &self,
    ) -> DesktopSettingsVisibleMainMenuEntriesCacheKey {
        let (dynamic_count, dynamic_digest) = self.settings_dynamic_category_main_menu_signature();
        DesktopSettingsVisibleMainMenuEntriesCacheKey {
            mobile: self.menu_renderer_state.config.mobile,
            controls_visible: self.settings_controls_menu_entry_visible(),
            dynamic_count,
            dynamic_digest,
        }
    }

    fn rebuild_settings_visible_main_menu_entries_cache(
        &self,
        key: DesktopSettingsVisibleMainMenuEntriesCacheKey,
    ) -> DesktopSettingsVisibleMainMenuEntriesCache {
        let mut entries = SETTINGS_MENU_ENTRIES
            .iter()
            .filter(|entry| self.settings_main_menu_entry_visible(entry))
            .map(|entry| DesktopSettingsVisibleMenuEntry {
                label: entry.label.to_string(),
                icon: entry.icon.to_string(),
                target: entry.target.to_string(),
                dynamic_index: None,
            })
            .collect::<Vec<_>>();
        entries.extend(self.settings_dynamic_categories.iter().enumerate().map(
            |(index, category)| DesktopSettingsVisibleMenuEntry {
                label: category.label.clone(),
                icon: category.icon.clone(),
                target: format!("dynamic:{}", category.id),
                dynamic_index: Some(index),
            },
        ));
        DesktopSettingsVisibleMainMenuEntriesCache { key, entries }
    }

    fn settings_visible_main_menu_entries(&self) -> Vec<DesktopSettingsVisibleMenuEntry> {
        let key = self.settings_visible_main_menu_entries_cache_key();
        if let Some(cache) = self
            .settings_visible_main_menu_entries_cache
            .borrow()
            .as_ref()
        {
            if cache.key == key {
                return cache.entries.clone();
            }
        }

        let cache = self.rebuild_settings_visible_main_menu_entries_cache(key);
        let entries = cache.entries.clone();
        *self.settings_visible_main_menu_entries_cache.borrow_mut() = Some(cache);
        self.settings_visible_main_menu_entries_cache_rebuilds.set(
            self.settings_visible_main_menu_entries_cache_rebuilds
                .get()
                .saturating_add(1),
        );
        entries
    }

    #[cfg(test)]
    fn settings_visible_main_menu_entries_cache_rebuilds(&self) -> u64 {
        self.settings_visible_main_menu_entries_cache_rebuilds.get()
    }

    fn settings_data_action_visible(&self, action: &DesktopSettingsDataAction) -> bool {
        action.action != DesktopSettingsAction::OpenDataFolder
            || !self.menu_renderer_state.config.mobile
    }

    fn settings_visible_data_actions(&self) -> Vec<&'static DesktopSettingsDataAction> {
        SETTINGS_DATA_ACTIONS
            .iter()
            .filter(|action| self.settings_data_action_visible(action))
            .collect()
    }

    fn setting_slider_effective_value(&self, spec: &DesktopSettingsPrefSpec) -> Option<i32> {
        Some(self.setting_pref_effective_value(spec)).and_then(|value| value.parse::<i32>().ok())
    }

    fn setting_pref_effective_value(&self, spec: &DesktopSettingsPrefSpec) -> String {
        self.setting_override_value(spec.table, spec.key)
            .map(ToOwned::to_owned)
            .unwrap_or_else(|| spec.default_value.text())
    }

    fn settings_java_float_label(value: f32) -> String {
        let mut text = format!("{value:.2}");
        while text.ends_with('0') && !text.ends_with(".0") {
            text.pop();
        }
        text
    }

    fn settings_slider_display_value(&self, spec: &DesktopSettingsPrefSpec, value: i32) -> String {
        match (spec.table, spec.key) {
            ("game", "saveinterval") => {
                let value_text = value.to_string();
                self.format_bundle_text("setting.seconds", &[value_text.as_str()])
            }
            ("game", "playerlimit") => value.to_string(),
            ("graphics", "uiEdgePadding") => format!("{value}px"),
            ("graphics", "screenshake") => {
                format!("{}x", Self::settings_java_float_label(value as f32 / 4.0))
            }
            ("graphics", "bloomintensity") => {
                format!("{}%", (value as f32 / 4.0 * 100.0) as i32)
            }
            ("graphics", "bloomblur") => format!("{value}x"),
            ("graphics", "fpscap") => {
                if value > 240 {
                    self.localize_bundle_markup_text("@setting.fpscap.none")
                } else {
                    let value_text = value.to_string();
                    self.format_bundle_text("setting.fpscap.text", &[value_text.as_str()])
                }
            }
            ("graphics", "uiscale")
            | ("graphics", "chatopacity")
            | ("graphics", "lasersopacity")
            | ("graphics", "unitlaseropacity")
            | ("graphics", "bridgeopacity")
            | ("graphics", "maxmagnificationmultiplierpercent")
            | ("graphics", "minmagnificationmultiplierpercent")
            | ("sound", "musicvol")
            | ("sound", "sfxvol")
            | ("sound", "ambientvol") => format!("{value}%"),
            _ => value.to_string(),
        }
    }

    fn settings_pref_widget_clip_rect_for_panel(panel: RenderRect) -> RenderRect {
        let bottom_reserved = SETTINGS_BACK_BUTTON_HEIGHT + 30.0 + 16.0;
        let height = (panel.height - bottom_reserved - 150.0).max(140.0);
        RenderRect::new(
            panel.x + 36.0,
            panel.y + bottom_reserved,
            (panel.width - 84.0).max(160.0),
            height,
        )
    }

    fn settings_pref_table_container_rect_for_panel(panel: RenderRect) -> RenderRect {
        let clip = Self::settings_pref_widget_clip_rect_for_panel(panel);
        let margin = 14.0;
        RenderRect::new(
            clip.x - margin,
            clip.y - margin,
            clip.width + margin * 2.0,
            clip.height + margin * 2.0,
        )
    }

    fn settings_pref_widget_row_rect_for_clip_with_scroll(
        clip: RenderRect,
        index: usize,
        scroll_offset: f32,
    ) -> RenderRect {
        let row_width = Self::settings_pref_widget_row_width_for_clip(clip);
        let row_height = SETTINGS_PREF_ROW_HEIGHT;
        let top = clip.y + clip.height
            - row_height
            - index as f32 * (SETTINGS_PREF_ROW_HEIGHT + SETTINGS_PREF_ROW_GAP)
            + scroll_offset;
        RenderRect::new(clip.x, top, row_width, row_height)
    }

    fn settings_pref_widget_row_width_for_clip(clip: RenderRect) -> f32 {
        (clip.width - 18.0).max(140.0)
    }

    fn settings_table_total_height(row_count: usize) -> f32 {
        row_count as f32 * (SETTINGS_PREF_ROW_HEIGHT + SETTINGS_PREF_ROW_GAP)
    }

    fn settings_pref_widget_row_height(spec: DesktopSettingsPrefSpec) -> f32 {
        match spec.kind {
            DesktopSettingsPrefKind::AreaText => {
                SETTINGS_TEXT_FIELD_HEIGHT * spec.text_rows.max(2) as f32 + 34.0
            }
            _ => SETTINGS_PREF_ROW_HEIGHT,
        }
    }

    fn settings_pref_widget_total_height_for_specs(specs: &[DesktopSettingsPrefSpec]) -> f32 {
        specs
            .iter()
            .map(|spec| Self::settings_pref_widget_row_height(*spec) + SETTINGS_PREF_ROW_GAP)
            .sum()
    }

    fn settings_pref_widget_total_height_for_specs_with_reset(
        specs: &[DesktopSettingsPrefSpec],
    ) -> f32 {
        Self::settings_pref_widget_total_height_for_specs(specs)
            + SETTINGS_RESET_BUTTON_HEIGHT
            + SETTINGS_PREF_ROW_GAP
    }

    fn settings_pref_widget_row_rect_for_specs_with_scroll(
        clip: RenderRect,
        specs: &[DesktopSettingsPrefSpec],
        index: usize,
        scroll_offset: f32,
    ) -> RenderRect {
        let row_width = Self::settings_pref_widget_row_width_for_clip(clip);
        let mut top = clip.y + clip.height + scroll_offset;
        for spec in specs.iter().take(index) {
            top -= Self::settings_pref_widget_row_height(*spec) + SETTINGS_PREF_ROW_GAP;
        }
        let row_height = specs
            .get(index)
            .map(|spec| Self::settings_pref_widget_row_height(*spec))
            .unwrap_or(SETTINGS_PREF_ROW_HEIGHT);
        RenderRect::new(clip.x, top - row_height, row_width, row_height)
    }

    fn settings_pref_widget_reset_row_rect_for_specs_with_scroll(
        clip: RenderRect,
        specs: &[DesktopSettingsPrefSpec],
        scroll_offset: f32,
    ) -> RenderRect {
        let row_width = Self::settings_pref_widget_row_width_for_clip(clip);
        let mut top = clip.y + clip.height + scroll_offset;
        for spec in specs {
            top -= Self::settings_pref_widget_row_height(*spec) + SETTINGS_PREF_ROW_GAP;
        }
        RenderRect::new(
            clip.x,
            top - SETTINGS_RESET_BUTTON_HEIGHT,
            row_width,
            SETTINGS_RESET_BUTTON_HEIGHT,
        )
    }

    fn settings_pref_widget_reset_button_rect(row: RenderRect) -> RenderRect {
        let width = SETTINGS_RESET_BUTTON_WIDTH.min(row.width);
        let height = SETTINGS_RESET_BUTTON_HEIGHT.min(row.height);
        let x = if row.width > width {
            row.x + 6.0
        } else {
            row.x
        };
        RenderRect::new(x, row.center().y - height * 0.5, width, height)
    }

    fn settings_max_scroll_offset_for_total_height(clip: RenderRect, total_height: f32) -> i32 {
        (total_height - clip.height).max(0.0).round() as i32
    }

    fn settings_max_scroll_offset_for_clip(clip: RenderRect, row_count: usize) -> i32 {
        Self::settings_max_scroll_offset_for_total_height(
            clip,
            Self::settings_table_total_height(row_count),
        )
    }

    fn settings_scroll_offset_pixels_for_specs(
        &self,
        table: &'static str,
        clip: RenderRect,
        specs: &[DesktopSettingsPrefSpec],
    ) -> f32 {
        let max = Self::settings_max_scroll_offset_for_total_height(
            clip,
            Self::settings_pref_widget_total_height_for_specs_with_reset(specs),
        );
        self.settings_scroll_offsets
            .get(table)
            .copied()
            .unwrap_or(0)
            .clamp(0, max) as f32
    }

