    fn settings_language_list_clip_rect(dialog: RenderRect) -> RenderRect {
        let scrollpane = Self::settings_language_scrollpane_rect(dialog);
        RenderRect::new(
            scrollpane.x,
            scrollpane.y,
            (scrollpane.width - SETTINGS_LANGUAGE_SCROLLBAR_WIDTH).max(0.0),
            scrollpane.height,
        )
    }

    fn settings_language_total_content_height() -> f32 {
        let rows = settings_language_options_like_java().len().max(1);
        rows as f32 * SETTINGS_LANGUAGE_ROW_HEIGHT
            + rows.saturating_sub(1) as f32 * SETTINGS_LANGUAGE_ROW_GAP
    }

    fn settings_language_visible_rows_for_dialog(dialog: RenderRect) -> usize {
        let scrollpane = Self::settings_language_scrollpane_rect(dialog);
        let row_span = Self::settings_language_row_span();
        ((scrollpane.height + SETTINGS_LANGUAGE_ROW_GAP) / row_span)
            .floor()
            .max(1.0) as usize
    }

    fn settings_language_max_scroll_rows_for_dialog(dialog: RenderRect, row_count: usize) -> usize {
        let visible_rows = Self::settings_language_visible_rows_for_dialog(dialog);
        row_count.saturating_sub(visible_rows)
    }

    fn settings_language_scroll_parts_for_dialog(
        &self,
        dialog: RenderRect,
        row_count: usize,
    ) -> (usize, f32) {
        let max_rows = Self::settings_language_max_scroll_rows_for_dialog(dialog, row_count);
        let rows = self.settings_language_scroll_offset.min(max_rows);
        let subrow = if rows >= max_rows {
            0.0
        } else {
            self.settings_language_scroll_subrow_offset
                .clamp(0.0, Self::settings_language_row_span())
        };
        (rows, subrow)
    }

    fn apply_settings_language_scroll_delta(&mut self, dialog: RenderRect, delta_y: f32) -> bool {
        let max_rows = Self::settings_language_max_scroll_rows_for_dialog(
            dialog,
            settings_language_options_like_java().len(),
        );
        if max_rows == 0 {
            return false;
        }
        let row_span = Self::settings_language_row_span();
        let current_rows = self.settings_language_scroll_offset.min(max_rows);
        let current_subrow = if current_rows >= max_rows {
            0.0
        } else {
            self.settings_language_scroll_subrow_offset
                .clamp(0.0, row_span)
        };
        let current = current_rows as f32 * row_span + current_subrow;
        let next = (current - delta_y * row_span).clamp(0.0, max_rows as f32 * row_span);
        let next_rows = (next / row_span).floor().min(max_rows as f32) as usize;
        let next_subrow = if next_rows >= max_rows {
            0.0
        } else {
            next - next_rows as f32 * row_span
        };
        self.settings_language_scroll_offset = next_rows;
        self.settings_language_scroll_subrow_offset = next_subrow;
        (next - current).abs() > f32::EPSILON
    }

