    fn game_over_stat_label_text(&self, key: &'static str) -> String {
        let localized = self.localize_bundle_markup_text(key);
        if localized != key {
            return localized;
        }
        match key {
            "stats.wave" => "Wave",
            "stats.unitsCreated" => "Units Created",
            "stats.enemiesDestroyed" => "Enemies Destroyed",
            "stats.built" => "Built",
            "stats.destroyed" => "Destroyed",
            "stats.deconstructed" => "Deconstructed",
            _ => key,
        }
        .to_string()
    }

    fn game_over_stat_rows(&self) -> Vec<(String, i32)> {
        let stats = &self.game_state.stats;
        let mut rows = Vec::new();
        if self.game_state.rules.waves {
            rows.push((
                self.game_over_stat_label_text("stats.wave"),
                stats.waves_lasted,
            ));
        }
        rows.extend([
            (
                self.game_over_stat_label_text("stats.unitsCreated"),
                stats.units_created,
            ),
            (
                self.game_over_stat_label_text("stats.enemiesDestroyed"),
                stats.enemy_units_destroyed,
            ),
            (
                self.game_over_stat_label_text("stats.built"),
                stats.buildings_built,
            ),
            (
                self.game_over_stat_label_text("stats.destroyed"),
                stats.buildings_destroyed,
            ),
            (
                self.game_over_stat_label_text("stats.deconstructed"),
                stats.buildings_deconstructed,
            ),
        ]);
        rows
    }

    fn game_over_sector_name(&self) -> Option<String> {
        self.game_state.get_sector().map(|sector| {
            sector
                .preset
                .as_ref()
                .map(|preset| preset.localized_name.clone())
                .or_else(|| sector.info.name.clone())
                .unwrap_or_else(|| sector.id.to_string())
        })
    }

    fn game_over_title_text(&self) -> String {
        if self.game_state.rules.pvp {
            if let Some(winner_name) = self.game_over_winner_colored_name() {
                return self.format_bundle_text("gameover.pvp", &[winner_name.as_str()]);
            }
        }
        if self.game_state.is_campaign() {
            if let Some(sector_name) = self.game_over_sector_name() {
                return self.format_bundle_text("sector.lost", &[sector_name.as_str()]);
            }
        }
        self.localize_bundle_markup_text("@gameover")
    }

    fn populate_base_team_emojis_from_content_icons(
        teams: &mut TeamRegistry,
        registry: &DesktopContentIconGlyphRegistry,
        texture_atlas: &TextureAtlasPlan<bool>,
    ) {
        let runtime_registry =
            desktop_content_icon_runtime_registry_like_java(registry, texture_atlas);
        for team in teams.base_teams_mut() {
            team.emoji = runtime_registry
                .string_icon(&team.name)
                .unwrap_or("")
                .to_string();
        }
    }

    fn vanilla_teams_with_content_icon_emojis(&self) -> TeamRegistry {
        let mut teams = vanilla_teams();
        Self::populate_base_team_emojis_from_content_icons(
            &mut teams,
            &self.content_icon_glyph_registry,
            &self.texture_atlas,
        );
        teams
    }

    fn team_colored_name(&self, team_id: TeamId) -> String {
        let teams = self.vanilla_teams_with_content_icon_emojis();
        let team = teams.get(team_id.0 as i32);
        let key = format!("@team.{}.name", team.name);
        let localized = self.localize_bundle_markup_text_or(&key, team.name.as_str());
        team.colored_name_with(&localized)
    }

    fn game_over_winner_colored_name(&self) -> Option<String> {
        self.game_state
            .game_over_winner
            .map(|winner| self.team_colored_name(winner))
    }

    fn game_over_is_high_score(&self) -> bool {
        if !self.game_state.rules.waves {
            return false;
        }
        let current_wave = self
            .game_state
            .stats
            .waves_lasted
            .max(self.game_state.wave)
            .max(0);
        current_wave > 0 && self.map_play_high_score(&self.game_state.map) < current_wave
    }

    fn current_loaded_save_slot(&self) -> Option<&SaveSlotRecord> {
        let action = self.last_load_game_result.as_ref()?;
        if action.kind != DesktopLoadGameActionKind::Load || action.status != "loaded" {
            return None;
        }
        self.load_game_slots
            .iter()
            .find(|slot| slot.file.display().to_string() == action.file)
    }

    fn game_over_playtime_text(&self) -> Option<String> {
        self.current_loaded_save_slot()
            .map(|slot| Self::format_save_playtime(slot.time_played()))
    }

    fn game_over_primary_action(&self) -> DesktopPausedOverlayAction {
        if self.game_state.is_campaign() {
            if self.pause_overlay_net_active() {
                DesktopPausedOverlayAction::GameOverDisconnect
            } else {
                DesktopPausedOverlayAction::GameOverContinue
            }
        } else {
            DesktopPausedOverlayAction::GameOverMenu
        }
    }

    fn game_over_primary_button_label(&self) -> String {
        let key = match self.game_over_primary_action() {
            DesktopPausedOverlayAction::GameOverDisconnect => "@gameover.disconnect",
            DesktopPausedOverlayAction::GameOverContinue => "@continue",
            _ => "@menu",
        };
        self.localize_bundle_markup_text(key)
    }

    fn pause_overlay_net_active(&self) -> bool {
        if self.runtime.network_context.active {
            return true;
        }
        self.net_client
            .state()
            .lock()
            .map(|state| state.connected || state.connecting)
            .unwrap_or(false)
    }

    fn pause_overlay_net_client(&self) -> bool {
        if self.runtime.network_context.active && !self.runtime.network_context.server {
            return true;
        }
        self.net_client
            .state()
            .lock()
            .map(|state| state.connected || state.connecting)
            .unwrap_or(false)
    }

    fn pause_overlay_net_server(&self) -> bool {
        self.runtime.network_context.server
    }

    fn pause_overlay_custom_rules_visible(&self) -> bool {
        self.game_state.rules.allow_edit_rules
            && (self.pause_overlay_net_server() || !self.pause_overlay_net_active())
    }

    fn pause_overlay_custom_rules_button_rect_for_viewport(viewport: RenderViewport) -> RenderRect {
        RenderRect::new(viewport.x + 18.0, viewport.y + 18.0, 70.0, 70.0)
    }

    fn pause_overlay_host_invites_friends(&self) -> bool {
        self.host_steam_enabled() && self.pause_overlay_net_server()
    }

    fn pause_overlay_has_objective(&self) -> bool {
        self.game_state
            .get_sector()
            .and_then(|sector| sector.preset.as_ref())
            .and_then(|preset| preset.description.as_ref())
            .is_some()
    }

    fn pause_overlay_quit_label(&self) -> &'static str {
        if self
            .current_loaded_save_slot()
            .is_some_and(|slot| self.load_game_slot_is_autosave(slot))
        {
            "@save.quit"
        } else {
            "@quit"
        }
    }

    fn pause_overlay_button_specs(&self) -> Vec<DesktopPausedOverlayButtonSpec> {
        let net_active = self.pause_overlay_net_active();
        let is_campaign = self.game_state.is_campaign();
        let is_editor = self.game_state.is_editor();
        let is_mobile = self.menu_renderer_state.config.mobile;
        let mut specs = Vec::new();

        if is_campaign {
            if self.pause_overlay_has_objective() {
                specs.push(DesktopPausedOverlayButtonSpec {
                    action: DesktopPausedOverlayAction::Objective,
                    label: "@objective",
                    icon: Some("info"),
                    enabled: true,
                });
            }
            specs.push(DesktopPausedOverlayButtonSpec {
                action: DesktopPausedOverlayAction::Abandon,
                label: "@abandon",
                icon: Some("cancel"),
                enabled: !self.pause_overlay_net_client() && !self.game_state.game_over,
            });
        }

        specs.push(DesktopPausedOverlayButtonSpec {
            action: DesktopPausedOverlayAction::Back,
            label: "@back",
            icon: Some(if is_mobile { "play" } else { "left" }),
            enabled: true,
        });
        specs.push(DesktopPausedOverlayButtonSpec {
            action: DesktopPausedOverlayAction::Settings,
            label: "@settings",
            icon: Some("settings"),
            enabled: true,
        });

        if is_mobile {
            if !is_campaign && !is_editor {
                specs.push(DesktopPausedOverlayButtonSpec {
                    action: DesktopPausedOverlayAction::SaveGame,
                    label: "@save",
                    icon: Some("save"),
                    enabled: true,
                });
                specs.push(DesktopPausedOverlayButtonSpec {
                    action: if net_active {
                        DesktopPausedOverlayAction::Database
                    } else {
                        DesktopPausedOverlayAction::LoadGame
                    },
                    label: if net_active { "@database" } else { "@load" },
                    icon: Some(if net_active { "book" } else { "download" }),
                    enabled: true,
                });
            } else if is_campaign {
                specs.push(DesktopPausedOverlayButtonSpec {
                    action: DesktopPausedOverlayAction::Research,
                    label: "@research",
                    icon: Some("tree"),
                    enabled: true,
                });
                specs.push(DesktopPausedOverlayButtonSpec {
                    action: DesktopPausedOverlayAction::PlanetMap,
                    label: "@planetmap",
                    icon: Some("map"),
                    enabled: true,
                });
            }

            specs.push(DesktopPausedOverlayButtonSpec {
                action: DesktopPausedOverlayAction::HostServer,
                label: "@hostserver.mobile",
                icon: Some("host"),
                enabled: !net_active,
            });
            specs.push(DesktopPausedOverlayButtonSpec {
                action: DesktopPausedOverlayAction::Quit,
                label: self.pause_overlay_quit_label(),
                icon: Some("exit"),
                enabled: true,
            });

            return specs;
        }

        if !is_campaign && !is_editor {
            specs.push(DesktopPausedOverlayButtonSpec {
                action: DesktopPausedOverlayAction::SaveGame,
                label: "@savegame",
                icon: Some("save"),
                enabled: true,
            });
            specs.push(DesktopPausedOverlayButtonSpec {
                action: DesktopPausedOverlayAction::LoadGame,
                label: "@loadgame",
                icon: Some("upload"),
                enabled: !net_active,
            });
        }

        specs.push(DesktopPausedOverlayButtonSpec {
            action: DesktopPausedOverlayAction::HostServer,
            label: if self.pause_overlay_host_invites_friends() {
                "@invitefriends"
            } else if is_editor {
                "@hostserver.mobile"
            } else {
                "@hostserver"
            },
            icon: Some("host"),
            enabled: self.pause_overlay_host_invites_friends() || !net_active,
        });

        if is_editor {
            specs.push(DesktopPausedOverlayButtonSpec {
                action: DesktopPausedOverlayAction::WorldProcessors,
                label: "@editor.worldprocessors",
                icon: Some("logic"),
                enabled: true,
            });
        }

        specs.push(DesktopPausedOverlayButtonSpec {
            action: DesktopPausedOverlayAction::Quit,
            label: self.pause_overlay_quit_label(),
            icon: Some("exit"),
            enabled: true,
        });

        specs
    }

