    fn pause_custom_rules_inline_resource_button_rects(
        &self,
        content: RenderRect,
    ) -> Vec<(DesktopPausedOverlayAction, RenderRect)> {
        let buttons = self.pause_custom_rules_inline_resource_buttons();
        if buttons.is_empty() {
            return Vec::new();
        }

        let mut y = content.y + content.height - 20.0;
        for (title_key, toggles) in PAUSE_CUSTOM_RULE_TOGGLE_GROUPS {
            let is_resources = *title_key == "@rules.title.resourcesbuilding";
            let is_environment = *title_key == "@rules.title.environment";
            let visible_toggles = toggles
                .iter()
                .copied()
                .filter(|toggle| self.pause_custom_rule_label_matches(toggle.label_key()))
                .collect::<Vec<_>>();
            if visible_toggles.is_empty()
                && !(is_resources && !buttons.is_empty())
                && !(is_environment
                    && (!self
                        .pause_custom_rules_inline_environment_numbers()
                        .is_empty()
                        || !self
                            .pause_custom_rules_inline_environment_buttons()
                            .is_empty()))
            {
                continue;
            }
            y -= 36.0;
            for toggle in visible_toggles {
                y -= 24.0;
                if toggle == DesktopCustomRulesToggle::LimitMapArea {
                    y -= CUSTOM_RULE_LIMIT_AREA_NUMBER_ROW_HEIGHT;
                }
            }
            if is_resources {
                let mut rects = Vec::new();
                let button_count = buttons.len();
                for (button_index, (action, _)) in buttons.into_iter().enumerate() {
                    rects.push((
                        action,
                        Self::map_play_customize_inline_resource_button_rect(
                            content,
                            y,
                            button_index,
                            button_count,
                        ),
                    ));
                }
                return rects;
            }
            if is_environment {
                y -= self.pause_custom_rules_inline_environment_numbers().len() as f32
                    * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT;
                let button_count = self.pause_custom_rules_inline_environment_buttons().len();
                if button_count > 0 {
                    let columns = Self::map_play_customize_inline_resource_button_columns(
                        content,
                        button_count,
                    );
                    y -= button_count.div_ceil(columns) as f32 * 38.0;
                }
            }
            y -= 10.0;
        }
        Vec::new()
    }

