    fn pause_custom_rules_toggle_content_height(&self, content: RenderRect) -> f32 {
        let mut height = 40.0;
        let resource_buttons = self.pause_custom_rules_inline_resource_buttons();
        let unit_buttons = self.pause_custom_rules_inline_unit_buttons();
        let inline_environment_count = self.pause_custom_rules_inline_environment_numbers().len();
        let environment_buttons = self.pause_custom_rules_inline_environment_buttons();
        for (title_key, toggles) in PAUSE_CUSTOM_RULE_TOGGLE_GROUPS {
            let is_resources = *title_key == "@rules.title.resourcesbuilding";
            let is_unit = *title_key == "@rules.title.unit";
            let is_environment = *title_key == "@rules.title.environment";
            let visible_count = toggles
                .iter()
                .copied()
                .filter(|toggle| self.pause_custom_rule_label_matches(toggle.label_key()))
                .count();
            if visible_count == 0
                && !(is_resources && !resource_buttons.is_empty())
                && !(is_unit && !unit_buttons.is_empty())
                && !(is_environment
                    && (inline_environment_count > 0 || !environment_buttons.is_empty()))
            {
                continue;
            }
            height += PAUSE_CUSTOM_RULE_TOGGLE_GROUP_HEADER_HEIGHT
                + visible_count as f32 * PAUSE_CUSTOM_RULE_TOGGLE_ROW_HEIGHT;
            if toggles
                .iter()
                .copied()
                .any(|toggle| toggle == DesktopCustomRulesToggle::LimitMapArea)
                && self.pause_custom_rule_label_matches(
                    DesktopCustomRulesToggle::LimitMapArea.label_key(),
                )
            {
                height += CUSTOM_RULE_LIMIT_AREA_NUMBER_ROW_HEIGHT;
            }
            if is_resources && !resource_buttons.is_empty() {
                let columns = Self::map_play_customize_inline_resource_button_columns(
                    content,
                    resource_buttons.len(),
                );
                height += resource_buttons.len().div_ceil(columns) as f32 * 38.0;
            }
            if is_unit && !unit_buttons.is_empty() {
                let columns = Self::map_play_customize_inline_resource_button_columns(
                    content,
                    unit_buttons.len(),
                );
                height += unit_buttons.len().div_ceil(columns) as f32 * 38.0;
            }
            if is_environment {
                height += inline_environment_count as f32 * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT;
                if !environment_buttons.is_empty() {
                    let columns = Self::map_play_customize_inline_resource_button_columns(
                        content,
                        environment_buttons.len(),
                    );
                    height += environment_buttons.len().div_ceil(columns) as f32 * 38.0;
                }
            }
        }
        let visible_additional_count = self
            .custom_rules_additional_setup_entries
            .iter()
            .filter(|entry| self.pause_custom_rules_additional_setup_entry_matches(entry))
            .count();
        if visible_additional_count > 0 {
            height += PAUSE_CUSTOM_RULE_TOGGLE_GROUP_HEADER_HEIGHT
                + visible_additional_count as f32 * PAUSE_CUSTOM_RULE_TOGGLE_ROW_HEIGHT;
        }
        if self.pause_custom_rules_inline_planet_visible() {
            let button_count = self.pause_planet_candidates().len() + 1;
            let columns = Self::map_play_customize_inline_planet_columns(content);
            height += 46.0 + button_count.div_ceil(columns) as f32 * 42.0;
        }
        if self.pause_custom_rules_inline_teams_visible() {
            height += 46.0 + 2.0 * 42.0 + Self::map_play_team_options().len() as f32 * 34.0;
            height += self.pause_inline_team_rules_expanded_teams.len() as f32
                * Self::map_play_customize_inline_team_expanded_field_height();
        }
        height
    }

    fn pause_custom_rules_number_policy_content_height(&self) -> f32 {
        let row_count = self
            .pause_custom_rules_visible_number_count()
            .max(self.pause_custom_rules_visible_policy_count());
        40.0 + row_count as f32 * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT
    }

    fn pause_custom_rules_content_height(&self, content: RenderRect) -> f32 {
        self.pause_custom_rules_toggle_content_height(content)
            .max(self.pause_custom_rules_number_policy_content_height())
            .max(content.height)
    }

    fn pause_custom_rules_max_scroll_offset(&self, content: RenderRect) -> f32 {
        ((self.pause_custom_rules_content_height(content) - content.height).max(0.0)
            / PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT)
            .ceil()
    }

    fn pause_custom_rules_scrolled_content_rect(&self, content: RenderRect) -> RenderRect {
        let offset = self
            .pause_custom_rules_scroll_offset
            .clamp(0.0, self.pause_custom_rules_max_scroll_offset(content));
        RenderRect::new(
            content.x,
            content.y + offset * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT,
            content.width,
            content.height,
        )
    }

