    fn campaign_launch_loadout_picker_columns(picker: RenderRect, count: usize) -> usize {
        if count == 0 {
            return 1;
        }
        (((picker.width + 68.0) / CAMPAIGN_LAUNCH_LOADOUT_PICKER_TARGET_WIDTH).floor() as usize)
            .max(1)
            .min(count)
    }

    fn campaign_launch_loadout_picker_candidate_rect(
        picker: RenderRect,
        index: usize,
        count: usize,
    ) -> RenderRect {
        let columns = Self::campaign_launch_loadout_picker_columns(picker, count);
        let gap = 8.0;
        let rows = count.saturating_add(columns - 1).max(1) / columns;
        let width =
            ((picker.width - gap * (columns.saturating_sub(1) as f32)) / columns as f32).max(1.0);
        let height = ((picker.height
            - CAMPAIGN_LAUNCH_LOADOUT_PICKER_ROW_GAP * rows.saturating_sub(1) as f32)
            / rows as f32)
            .max(1.0);
        let column = index % columns;
        let row = index / columns;
        RenderRect::new(
            picker.x + column as f32 * (width + gap),
            picker.y + picker.height
                - height
                - row as f32 * (height + CAMPAIGN_LAUNCH_LOADOUT_PICKER_ROW_GAP),
            width,
            height,
        )
    }

