    fn join_route_community_group_header_label_width_fallback(group_name: &str) -> f32 {
        if group_name.trim().is_empty() {
            return 0.0;
        }
        group_name
            .chars()
            .map(|character| if character.is_ascii() { 7.0 } else { 12.0 })
            .sum::<f32>()
            + 4.0
    }

    fn join_route_community_group_header_label_width_like_java(&self, group_name: &str) -> f32 {
        if group_name.trim().is_empty() {
            return 0.0;
        }
        static CACHE: OnceLock<Mutex<BTreeMap<(String, String), f32>>> = OnceLock::new();
        let key = (self.settings_locale.clone(), group_name.to_string());
        if let Some(width) = CACHE
            .get_or_init(|| Mutex::new(BTreeMap::new()))
            .lock()
            .ok()
            .and_then(|cache| cache.get(&key).copied())
        {
            return width;
        }
        let width = desktop_default_real_font_atlas_for_locale(&self.settings_locale)
            .as_deref()
            .and_then(|atlas| {
                opengl_backend_real_font_text_line_width(group_name, atlas, RenderFontId::Outline)
            })
            .map(|width| width * (12.0 / 18.0) + 4.0)
            .unwrap_or_else(|| {
                Self::join_route_community_group_header_label_width_fallback(group_name)
            });
        if let Ok(mut cache) = CACHE.get_or_init(|| Mutex::new(BTreeMap::new())).lock() {
            cache.insert(key, width);
        }
        width
    }

