    fn join_route_scrollbar_knob_rect_for_panel(&self, panel: RenderRect) -> Option<RenderRect> {
        let max = self.max_join_route_scroll_offset_for_panel(panel);
        if max == 0 {
            return None;
        }
        let clip = Self::join_route_scroll_clip_rect_for_panel(panel);
        let track = Self::join_route_scrollbar_track_rect_for_panel(panel);
        let visible_fraction = 1.0 / (max as f32 + 1.0);
        let knob_height = (clip.height * visible_fraction).clamp(36.0, clip.height);
        let travel = (clip.height - knob_height).max(0.0);
        let offset = self.join_route_scroll_offset.clamp(0.0, max as f32);
        let knob_y = clip.y + clip.height - knob_height - travel * (offset / max as f32);
        Some(RenderRect::new(track.x - 2.0, knob_y, 10.0, knob_height))
    }

    fn join_route_scroll_slot_offset_for_panel(&self, panel: RenderRect) -> usize {
        let max = self.max_join_route_scroll_offset_for_panel(panel);
        self.join_route_scroll_offset.round().clamp(0.0, max as f32) as usize
    }

