    fn join_route_server_snapshot_for_target(
        &self,
        index: usize,
        target: &DesktopConnectTarget,
    ) -> DesktopJoinRouteServerSnapshot {
        let Some(refresh_state) = self.join_saved_server_refresh_states.get(index) else {
            return self.join_route_server_snapshot_for_target_uncached(index, target);
        };
        let Some(state_key) = desktop_join_saved_server_snapshot_state_cache_key(refresh_state)
        else {
            return self.join_route_server_snapshot_for_target_uncached(index, target);
        };
        let (target_len, target_digest) =
            desktop_join_saved_server_snapshot_target_cache_key(target);
        let key = DesktopJoinSavedServerSnapshotCacheKey {
            index,
            target_port: target.port,
            target_len,
            target_digest,
            state: state_key,
        };
        if let Some(snapshot) = {
            let cache = self.join_saved_server_snapshot_cache.borrow();
            cache
                .entries
                .get(index)
                .and_then(|entry| entry.as_ref())
                .filter(|entry| entry.key == key)
                .map(|entry| entry.snapshot.clone())
        } {
            return snapshot;
        }

        let snapshot = self.join_route_server_snapshot_for_target_uncached(index, target);
        {
            let mut cache = self.join_saved_server_snapshot_cache.borrow_mut();
            if cache.entries.len() < self.join_saved_servers.len() {
                cache
                    .entries
                    .resize_with(self.join_saved_servers.len(), || None);
            } else if cache.entries.len() > self.join_saved_servers.len() {
                cache.entries.truncate(self.join_saved_servers.len());
            }
            if let Some(slot) = cache.entries.get_mut(index) {
                *slot = Some(DesktopJoinSavedServerSnapshotCacheEntry {
                    key,
                    snapshot: snapshot.clone(),
                });
            }
        }
        self.join_saved_server_snapshot_cache_rebuilds
            .set(self.join_saved_server_snapshot_cache_rebuilds.get() + 1);
        snapshot
    }

    fn join_route_server_snapshot_for_target_uncached(
        &self,
        index: usize,
        target: &DesktopConnectTarget,
    ) -> DesktopJoinRouteServerSnapshot {
        if let Some(refresh_state) = self.join_saved_server_refresh_states.get(index) {
            match refresh_state {
                DesktopJoinSavedServerRefreshState::Idle => {}
                DesktopJoinSavedServerRefreshState::Refreshing => {
                    return Self::join_route_server_snapshot_from_parts(
                        desktop_connect_target_display_ip(target),
                        "saved",
                        "@server.refreshing",
                        "--",
                        "@server.refreshing",
                        "--",
                        "--",
                        "--",
                        "--ms",
                    );
                }
                DesktopJoinSavedServerRefreshState::Resolved(host) => {
                    let address = desktop_connect_target_display_ip(target);
                    let description_raw = true;
                    let description = host.description.as_str();
                    let (map, map_raw) = if host.mapname.trim().is_empty() {
                        ("", true)
                    } else {
                        (host.mapname.as_str(), true)
                    };
                    let raw_mode = host
                        .mode_name
                        .as_deref()
                        .filter(|name| !name.is_empty())
                        .map(|name| name.replace('\n', " "));
                    let mode_raw = raw_mode.is_some();
                    let mode =
                        raw_mode.unwrap_or_else(|| format!("@{}", host.mode.name_bundle_key()));
                    let mut snapshot = Self::join_route_server_snapshot_from_parts(
                        address,
                        "saved",
                        "online",
                        host.version.to_string(),
                        description,
                        format!("{}/{}", host.players.max(0), host.player_limit.max(0)),
                        map,
                        mode,
                        format!("{}ms", host.ping.max(0)),
                    );
                    snapshot.description_raw = description_raw;
                    snapshot.map_raw = map_raw;
                    snapshot.mode_raw = mode_raw;
                    snapshot.version_type = host.version_type.replace('\n', " ");
                    if !host.name.trim().is_empty() {
                        snapshot.name = host.name.replace('\n', " ");
                    }
                    snapshot.refresh_search_terms();
                    return snapshot;
                }
                DesktopJoinSavedServerRefreshState::Failed(_) => {
                    return Self::join_route_server_snapshot_from_parts(
                        desktop_connect_target_display_ip(target),
                        "saved",
                        "@host.invalid",
                        "--",
                        "@host.invalid",
                        "--",
                        "--",
                        "--",
                        "--ms",
                    );
                }
            }
        }

        let state = self.net_client.state();
        let state = state.lock().unwrap();
        let world = state.last_loaded_world_data.as_ref();
        let address = desktop_connect_target_display_ip(target);
        let source = "saved".to_string();
        let status = if let Some(error) = self.connect_error.as_ref() {
            format!("error: {error}")
        } else if state.connected {
            "connected".to_string()
        } else if state.connecting {
            "connecting".to_string()
        } else {
            "saved".to_string()
        };
        let version = UPSTREAM_BASELINE.to_string();
        let world_description = world.and_then(|world| {
            world
                .map_tags
                .get("description")
                .filter(|description| !description.trim().is_empty())
        });
        let description_raw = world_description.is_some();
        let description = world_description
            .cloned()
            .unwrap_or_else(|| "@server.refreshing".into());
        let world_map = world.and_then(|world| {
            world
                .map_tags
                .get("name")
                .filter(|name| !name.trim().is_empty())
        });
        let map_raw = world_map.is_some();
        let map = world_map.cloned().unwrap_or_else(|| "@unknown".into());
        let players = if world.and_then(|world| world.player.as_ref()).is_some()
            || state.connected
            || state.connect_confirm_sent
        {
            "1".to_string()
        } else {
            "0".to_string()
        };
        let mode = format!("@{}", self.game_state.rules.mode().name_bundle_key());
        let ping = if state.ping_ms > 0 {
            format!("{}ms", state.ping_ms)
        } else {
            "--ms".into()
        };
        let name = address.clone();
        let search_terms = desktop_join_search_terms(&[
            name.as_str(),
            address.as_str(),
            source.as_str(),
            status.as_str(),
            version.as_str(),
            DEFAULT_CLIENT_VERSION_TYPE,
            description.as_str(),
            players.as_str(),
            map.as_str(),
            mode.as_str(),
            ping.as_str(),
        ]);
        DesktopJoinRouteServerSnapshot {
            name,
            address,
            source,
            status,
            version,
            version_type: DEFAULT_CLIENT_VERSION_TYPE.into(),
            description,
            description_raw,
            players,
            map,
            map_raw,
            mode,
            mode_raw: false,
            ping,
            search_terms,
        }
    }

    fn join_route_server_snapshot_from_parts(
        address: impl Into<String>,
        source: impl Into<String>,
        status: impl Into<String>,
        version: impl Into<String>,
        description: impl Into<String>,
        players: impl Into<String>,
        map: impl Into<String>,
        mode: impl Into<String>,
        ping: impl Into<String>,
    ) -> DesktopJoinRouteServerSnapshot {
        let address = address.into();
        let source = source.into();
        let status = status.into();
        let version = version.into();
        let description = description.into();
        let players = players.into();
        let map = map.into();
        let mode = mode.into();
        let ping = ping.into();
        let name = address.clone();
        let search_terms = desktop_join_search_terms(&[
            name.as_str(),
            address.as_str(),
            source.as_str(),
            status.as_str(),
            version.as_str(),
            DEFAULT_CLIENT_VERSION_TYPE,
            description.as_str(),
            players.as_str(),
            map.as_str(),
            mode.as_str(),
            ping.as_str(),
        ]);
        DesktopJoinRouteServerSnapshot {
            name,
            address,
            source,
            status,
            version,
            version_type: DEFAULT_CLIENT_VERSION_TYPE.into(),
            description,
            description_raw: false,
            players,
            map,
            map_raw: false,
            mode,
            mode_raw: false,
            ping,
            search_terms,
        }
    }

    fn join_host_card_projection_digest(host: &Host, is_banned: bool) -> u64 {
        let mut digest = DESKTOP_JOIN_SAVED_SERVER_SNAPSHOT_KEY_FNV_OFFSET;
        desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.ping);
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &host.name);
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &host.address);
        desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.port);
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &host.mapname);
        desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.players);
        desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.player_limit);
        desktop_join_saved_server_snapshot_key_digest_write_i32(&mut digest, host.version);
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &host.version_type);
        desktop_join_saved_server_snapshot_key_digest_write_str(
            &mut digest,
            &host.mode.name_bundle_key(),
        );
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &host.description);
        desktop_join_saved_server_snapshot_key_digest_write_opt_str(
            &mut digest,
            host.mode_name.as_deref(),
        );
        desktop_join_saved_server_snapshot_key_digest_write_byte(&mut digest, is_banned as u8);
        digest
    }

    fn join_snapshot_card_projection_digest(snapshot: &DesktopJoinRouteServerSnapshot) -> u64 {
        let mut digest = DESKTOP_JOIN_SAVED_SERVER_SNAPSHOT_KEY_FNV_OFFSET;
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.name);
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.address);
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.source);
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.status);
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.version);
        desktop_join_saved_server_snapshot_key_digest_write_str(
            &mut digest,
            &snapshot.version_type,
        );
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.description);
        desktop_join_saved_server_snapshot_key_digest_write_byte(
            &mut digest,
            snapshot.description_raw as u8,
        );
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.players);
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.map);
        desktop_join_saved_server_snapshot_key_digest_write_byte(
            &mut digest,
            snapshot.map_raw as u8,
        );
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.mode);
        desktop_join_saved_server_snapshot_key_digest_write_byte(
            &mut digest,
            snapshot.mode_raw as u8,
        );
        desktop_join_saved_server_snapshot_key_digest_write_str(&mut digest, &snapshot.ping);
        digest
    }

    fn join_card_projection_cache_key(
        &self,
        index: usize,
        digest: u64,
        text_width: f32,
    ) -> DesktopJoinCardTextProjectionCacheKey {
        DesktopJoinCardTextProjectionCacheKey {
            index,
            digest,
            text_width_bits: text_width.max(1.0).to_bits(),
            locale: self.settings_current_locale_code_like_java(),
        }
    }

    fn join_local_host_card_projection(
        &self,
        index: usize,
        host: &Host,
        is_banned: bool,
        text_width: f32,
    ) -> DesktopJoinCardTextProjection {
        let digest = Self::join_host_card_projection_digest(host, is_banned);
        let key = self.join_card_projection_cache_key(index, digest, text_width);
        if let Some(entry) = self
            .join_local_host_card_projection_cache
            .borrow()
            .get(&index)
        {
            if entry.key == key {
                return entry.projection.clone();
            }
        }

        let title = desktop_join_single_line_ellipsis_like_java(
            &self.join_server_card_title_with_banned_suffix_like_java(
                &host.name,
                host.version,
                host.version_type.as_str(),
                is_banned,
            ),
            text_width,
            12.0,
        );
        let description = desktop_join_description_limit_newlines_like_java(&host.description);
        let players_value =
            desktop_join_players_value_markup_like_java(host.players, host.player_limit);
        let players_key = if host.players == 1 && host.player_limit <= 0 {
            "players.single"
        } else {
            "players"
        };
        let mode_name = self.join_host_mode_name_like_java(host.mode_name.as_deref(), host.mode);
        let mut lines = Vec::new();
        if !description.trim().is_empty() && !is_banned {
            lines.push(DesktopJoinCardRenderLine {
                text: self.format_icons_like_java(format!("[gray]{}", description)),
                size: 10.0,
                wrap_width: Some(text_width),
            });
        }
        lines.push(DesktopJoinCardRenderLine {
            text: self.format_icons_like_java(format!(
                "[lightgray]{}",
                self.format_bundle_text(players_key, &[players_value.as_str()])
            )),
            size: 10.0,
            wrap_width: None,
        });
        lines.push(DesktopJoinCardRenderLine {
            text: self.format_icons_like_java(desktop_join_single_line_ellipsis_like_java(
                &format!(
                    "[lightgray]{}[lightgray] / {}",
                    self.format_bundle_text("save.map", &[host.mapname.as_str()]),
                    mode_name
                ),
                text_width,
                10.0,
            )),
            size: 10.0,
            wrap_width: None,
        });
        if host.ping > 0 {
            lines.push(DesktopJoinCardRenderLine {
                text: format!(
                    "{} {}ms",
                    desktop_ui_icon_glyph_or_label("chartBar", "ping"),
                    host.ping
                ),
                size: 10.0,
                wrap_width: None,
            });
        }
        let projection = DesktopJoinCardTextProjection { title, lines };
        self.join_local_host_card_projection_cache
            .borrow_mut()
            .insert(
                index,
                DesktopJoinCardTextProjectionCacheEntry {
                    key,
                    projection: projection.clone(),
                },
            );
        self.join_local_host_card_projection_cache_rebuilds.set(
            self.join_local_host_card_projection_cache_rebuilds
                .get()
                .saturating_add(1),
        );
        projection
    }

    fn join_saved_server_card_projection(
        &self,
        index: usize,
        snapshot: &DesktopJoinRouteServerSnapshot,
        text_width: f32,
    ) -> DesktopJoinCardTextProjection {
        let digest = Self::join_snapshot_card_projection_digest(snapshot);
        let key = self.join_card_projection_cache_key(index, digest, text_width);
        if let Some(entry) = self
            .join_saved_server_card_projection_cache
            .borrow()
            .get(&index)
        {
            if entry.key == key {
                return entry.projection.clone();
            }
        }

        let title = format!("[accent]{}", snapshot.address);
        let players_value = desktop_join_snapshot_players_value_markup_like_java(&snapshot.players);
        let mode = if snapshot.mode_raw {
            self.format_icons_like_java(snapshot.mode.replace('\n', " "))
        } else {
            self.localize_bundle_markup_text(snapshot.mode.replace('\n', " "))
        };
        let map = if snapshot.map_raw {
            self.format_icons_like_java(snapshot.map.replace('\n', " "))
        } else {
            self.localize_bundle_markup_text(snapshot.map.replace('\n', " "))
        };
        let version_line = snapshot
            .version
            .parse::<i32>()
            .map(|version| {
                self.join_server_card_title_like_java(
                    &snapshot.name,
                    version,
                    snapshot.version_type.as_str(),
                )
            })
            .unwrap_or_else(|_| {
                format!(
                    "{}   {}",
                    snapshot.name,
                    self.format_bundle_text(
                        "server.version",
                        &[snapshot.version.as_str(), snapshot.version_type.as_str()]
                    )
                )
            });
        let mut lines = Vec::new();
        if snapshot.name.trim() != snapshot.address.trim()
            || (snapshot.version != "--" && !version_line.trim().is_empty())
        {
            lines.push(DesktopJoinCardRenderLine {
                text: desktop_join_single_line_ellipsis_like_java(&version_line, text_width, 10.0),
                size: 10.0,
                wrap_width: None,
            });
        }
        if !snapshot.description.trim().is_empty() {
            let description =
                desktop_join_description_limit_newlines_like_java(&snapshot.description);
            let description = if snapshot.description_raw {
                format!("[gray]{description}")
            } else {
                self.localize_bundle_markup_text(format!("[gray]{description}"))
            };
            lines.push(DesktopJoinCardRenderLine {
                text: self.format_icons_like_java(description),
                size: 9.0,
                wrap_width: Some(text_width),
            });
        }
        lines.push(DesktopJoinCardRenderLine {
            text: self.format_icons_like_java(format!(
                "[lightgray]{}",
                self.format_bundle_text("players", &[players_value.as_str()])
            )),
            size: 9.0,
            wrap_width: None,
        });
        lines.push(DesktopJoinCardRenderLine {
            text: self.format_icons_like_java(desktop_join_single_line_ellipsis_like_java(
                &format!(
                    "[lightgray]{}[lightgray] / {}",
                    self.format_bundle_text("save.map", &[map.as_str()]),
                    mode
                ),
                text_width,
                9.0,
            )),
            size: 9.0,
            wrap_width: None,
        });
        if let Some(ping) = desktop_join_ping_ms_like_java(&snapshot.ping) {
            lines.push(DesktopJoinCardRenderLine {
                text: format!(
                    "{} {}",
                    desktop_ui_icon_glyph_or_label("chartBar", "ping"),
                    ping
                ),
                size: 9.0,
                wrap_width: None,
            });
        }
        let projection = DesktopJoinCardTextProjection {
            title,
            lines: lines.into_iter().take(5).collect(),
        };
        self.join_saved_server_card_projection_cache
            .borrow_mut()
            .insert(
                index,
                DesktopJoinCardTextProjectionCacheEntry {
                    key,
                    projection: projection.clone(),
                },
            );
        self.join_saved_server_card_projection_cache_rebuilds.set(
            self.join_saved_server_card_projection_cache_rebuilds
                .get()
                .saturating_add(1),
        );
        projection
    }

