    fn join_community_cache_file_path(&self) -> PathBuf {
        PathBuf::from(self.client.context.paths.server_cache_file())
    }

    fn join_font_ignore_dirty_active_like_java(&self) -> bool {
        self.join_font_ignore_dirty_frames_remaining > 0
    }

    fn arm_join_font_ignore_dirty_task_like_java(&mut self) {
        if self.join_font_ignore_dirty_frames_remaining == 0 {
            self.join_font_ignore_dirty_frames_remaining = JOIN_FONT_IGNORE_DIRTY_FRAMES_LIKE_JAVA;
        }
    }

    fn tick_join_font_ignore_dirty_task_like_java(&mut self) {
        self.join_font_ignore_dirty_frames_remaining = self
            .join_font_ignore_dirty_frames_remaining
            .saturating_sub(1);
    }

    fn ensure_join_community_server_cache_loaded(&mut self) {
        if self.join_community_cache_loaded || !self.join_community_servers_enabled() {
            return;
        }
        if let Err(error) = self.load_join_community_server_cache() {
            self.join_community_cache_error = Some(error.to_string());
        }
    }

    pub fn load_join_community_server_cache(&mut self) -> io::Result<usize> {
        if !self.join_community_servers_enabled() {
            return Ok(0);
        }
        let path = self.join_community_cache_file_path();
        if !path.exists() {
            self.join_community_cache_error = None;
            return Ok(0);
        }
        self.join_community_cache_loaded = true;
        let value = fs::read_to_string(path)?;
        let count = self.load_join_community_groups_from_server_json(&value);
        if count > 0 {
            self.join_community_cache_error = None;
        }
        Ok(count)
    }

    pub fn apply_join_community_feed_json(&mut self, value: &str) -> io::Result<usize> {
        if !self.join_community_servers_enabled() {
            return Ok(0);
        }
        let groups = join_community_groups_from_server_json(value);
        if groups.is_empty() {
            return Ok(0);
        }
        let count = groups.len();
        self.join_community_groups = groups;
        self.invalidate_join_community_visible_cache();
        self.join_community_cache_loaded = true;
        self.join_community_feed_fetched = true;
        self.join_community_cache_error = None;
        self.arm_join_font_ignore_dirty_task_like_java();

        let path = self.join_community_cache_file_path();
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(path, value)?;
        Ok(count)
    }

    pub fn set_join_community_group_hidden(&mut self, index: usize, hidden: bool) -> bool {
        let Some(group) = self.join_community_groups.get(index) else {
            return false;
        };
        self.settings_overrides
            .insert(group.hidden_setting_key(), hidden.to_string());
        self.invalidate_join_community_visible_cache();
        true
    }

    pub fn set_join_community_group_favorite(&mut self, index: usize, favorite: bool) -> bool {
        let Some(group) = self.join_community_groups.get(index) else {
            return false;
        };
        self.settings_overrides
            .insert(group.favorite_setting_key(), favorite.to_string());
        true
    }

    pub fn load_join_community_groups_from_server_json(&mut self, value: &str) -> usize {
        let groups = join_community_groups_from_server_json(value);
        if groups.is_empty() {
            return 0;
        }
        self.join_community_groups = groups;
        self.invalidate_join_community_visible_cache();
        self.arm_join_font_ignore_dirty_task_like_java();
        self.join_community_groups.len()
    }

    fn invalidate_join_community_visible_cache(&self) {
        self.join_community_visible_groups_version.set(
            self.join_community_visible_groups_version
                .get()
                .wrapping_add(1),
        );
        *self.join_community_visible_cache.borrow_mut() = None;
    }

    fn join_community_visible_cache_key(&self) -> DesktopJoinCommunityVisibleCacheKey {
        DesktopJoinCommunityVisibleCacheKey {
            query: desktop_join_search_plain_text(&self.join_community_search_committed),
            show_hidden: self.join_show_hidden,
            groups_len: self.join_community_groups.len(),
            groups_version: self.join_community_visible_groups_version.get(),
        }
    }

    fn join_community_group_matches_plain_query(
        &self,
        group: &DesktopJoinCommunityGroup,
        query: &str,
    ) -> bool {
        if query.is_empty() {
            return true;
        }
        desktop_join_search_plain_text(&group.name).contains(query)
            || (group.hosts.is_empty()
                && group
                    .addresses
                    .iter()
                    .any(|address| desktop_join_search_plain_text(address).contains(query)))
            || group.hosts.iter().any(|host| {
                [
                    host.name.as_str(),
                    host.description.as_str(),
                    host.mapname.as_str(),
                    host.mode_name.as_deref().unwrap_or_default(),
                ]
                .into_iter()
                .any(|field| desktop_join_search_plain_text(field).contains(query))
            })
    }

    fn rebuild_join_community_visible_cache(
        &self,
        key: DesktopJoinCommunityVisibleCacheKey,
    ) -> DesktopJoinCommunityVisibleCache {
        let mut group_indices = (0..self.join_community_groups.len()).collect::<Vec<_>>();
        if group_indices.len() > 1 {
            let java_half_column_offset = group_indices.len() / 2;
            group_indices.rotate_left(java_half_column_offset);
        }
        group_indices.retain(|group_index| {
            let Some(group) = self.join_community_groups.get(*group_index) else {
                return false;
            };
            (key.show_hidden || !self.join_community_group_hidden(group))
                && self.join_community_group_matches_plain_query(group, &key.query)
        });
        let mut entries = Vec::new();
        for group_index in &group_indices {
            let Some(group) = self.join_community_groups.get(*group_index) else {
                continue;
            };
            if group.hosts.is_empty() {
                entries.push((*group_index, None));
            } else {
                for host_index in 0..group.hosts.len() {
                    entries.push((*group_index, Some(host_index)));
                }
            }
        }
        DesktopJoinCommunityVisibleCache {
            key,
            group_indices,
            entries,
        }
    }

    fn refresh_join_community_visible_cache(&self) {
        let key = self.join_community_visible_cache_key();
        let is_current = {
            self.join_community_visible_cache
                .borrow()
                .as_ref()
                .is_some_and(|cache| cache.key == key)
        };
        if is_current {
            return;
        }
        let cache = self.rebuild_join_community_visible_cache(key);
        *self.join_community_visible_cache.borrow_mut() = Some(cache);
        self.join_community_visible_cache_rebuilds
            .set(self.join_community_visible_cache_rebuilds.get() + 1);
    }

    fn visible_join_community_groups(&self) -> Vec<(usize, &DesktopJoinCommunityGroup)> {
        self.refresh_join_community_visible_cache();
        let group_indices = self
            .join_community_visible_cache
            .borrow()
            .as_ref()
            .map(|cache| cache.group_indices.clone())
            .unwrap_or_default();
        group_indices
            .into_iter()
            .filter_map(|group_index| {
                self.join_community_groups
                    .get(group_index)
                    .map(|group| (group_index, group))
            })
            .collect()
    }

    fn visible_join_community_entries(
        &self,
    ) -> Vec<(usize, Option<usize>, &DesktopJoinCommunityGroup)> {
        self.refresh_join_community_visible_cache();
        let entries = self
            .join_community_visible_cache
            .borrow()
            .as_ref()
            .map(|cache| cache.entries.clone())
            .unwrap_or_default();
        entries
            .into_iter()
            .filter_map(|(group_index, host_index)| {
                self.join_community_groups
                    .get(group_index)
                    .map(|group| (group_index, host_index, group))
            })
            .collect()
    }

    fn visible_join_community_entries_len(&self) -> usize {
        self.refresh_join_community_visible_cache();
        self.join_community_visible_cache
            .borrow()
            .as_ref()
            .map(|cache| cache.entries.len())
            .unwrap_or(0)
    }

    fn visible_join_community_entry_window_for_panel(
        &self,
        panel: RenderRect,
    ) -> Vec<(usize, Option<usize>, &DesktopJoinCommunityGroup)> {
        self.refresh_join_community_visible_cache();
        let start = self.join_route_community_group_scroll_entry_offset_for_panel(panel);
        let capacity = Self::join_route_community_group_visible_slots_for_panel(panel);
        let entries = self
            .join_community_visible_cache
            .borrow()
            .as_ref()
            .map(|cache| {
                cache
                    .entries
                    .iter()
                    .skip(start)
                    .take(capacity)
                    .copied()
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        entries
            .into_iter()
            .filter_map(|(group_index, host_index)| {
                self.join_community_groups
                    .get(group_index)
                    .map(|group| (group_index, host_index, group))
            })
            .collect()
    }

