    fn join_server_version_text_like_java(&self, version: i32, version_type: &str) -> String {
        if version == -1 {
            let custom_build = self
                .bundle_value_for_current_locale("server.custombuild")
                .unwrap_or_else(|| "Custom Build".into());
            return self.format_bundle_text("server.version", &[custom_build.as_str(), ""]);
        }
        if version == 0 {
            return self.localize_bundle_markup_text("@server.outdated");
        }

        let version_number = version.to_string();
        let version_line =
            self.format_bundle_text("server.version", &[version_number.as_str(), version_type]);
        if version < DEFAULT_CLIENT_VERSION && DEFAULT_CLIENT_VERSION != -1 {
            return format!(
                "{}\n{}",
                self.localize_bundle_markup_text("@server.outdated"),
                version_line
            );
        }
        if version > DEFAULT_CLIENT_VERSION && DEFAULT_CLIENT_VERSION != -1 {
            return format!(
                "{}\n{}",
                self.localize_bundle_markup_text("@server.outdated.client"),
                version_line
            );
        }
        if version == DEFAULT_CLIENT_VERSION && version_type == DEFAULT_CLIENT_VERSION_TYPE {
            return String::new();
        }
        version_line
    }

    fn join_server_card_title_like_java(
        &self,
        name: &str,
        version: i32,
        version_type: &str,
    ) -> String {
        self.join_server_card_title_with_banned_suffix_like_java(name, version, version_type, false)
    }

    fn join_server_card_title_with_banned_suffix_like_java(
        &self,
        name: &str,
        version: i32,
        version_type: &str,
        is_banned: bool,
    ) -> String {
        let version_text = self.join_server_version_text_like_java(version, version_type);
        let version_text = if is_banned {
            format!(
                "{version_text}[red]{} [banned]",
                desktop_ui_icon_glyph_or_label("hammer", "\u{e817}")
            )
        } else {
            version_text
        };
        if version_text.trim().is_empty() {
            name.to_string()
        } else {
            format!("{name}   {version_text}")
        }
    }

    fn join_local_host_is_banned_like_java(&self, host: &Host) -> bool {
        self.host_steam_enabled() && host.description == "[banned]"
    }

    fn join_host_mode_name_like_java(&self, mode_name: Option<&str>, mode: Gamemode) -> String {
        mode_name
            .filter(|name| !name.is_empty())
            .map(|name| name.replace('\n', " "))
            .unwrap_or_else(|| self.localized_gamemode_name_like_java(mode))
    }

    fn join_server_version_mismatch_message(&self, server_version: i32) -> Option<String> {
        if server_version == DEFAULT_CLIENT_VERSION
            || DEFAULT_CLIENT_VERSION == -1
            || server_version == -1
        {
            return None;
        }

        let reason_key = if server_version > DEFAULT_CLIENT_VERSION {
            "server.kicked.clientOutdated"
        } else {
            "server.kicked.serverOutdated"
        };
        let reason = self
            .bundle_value_for_current_locale(reason_key)
            .unwrap_or_else(|| {
                if server_version > DEFAULT_CLIENT_VERSION {
                    "Outdated client! Update your game!".into()
                } else {
                    "Outdated server! Ask the host to update!".into()
                }
            });
        let client_version = DEFAULT_CLIENT_VERSION.to_string();
        let server_version = server_version.to_string();
        Some(format!(
            "[scarlet]{reason}\n[]{}",
            self.format_bundle_text(
                "server.versions",
                &[client_version.as_str(), server_version.as_str()]
            )
        ))
    }

    fn safe_connect_to_target(
        &mut self,
        target: DesktopConnectTarget,
        server_version: Option<i32>,
    ) -> io::Result<()> {
        if let Some(message) =
            server_version.and_then(|version| self.join_server_version_mismatch_message(version))
        {
            self.join_version_mismatch_dialog_message = Some(message);
            self.join_connection_error_dialog_message = None;
            self.join_reconnect_target = None;
            self.join_reconnect_receiver = None;
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "server version mismatch",
            ));
        }
        self.connect_to_target(target)
    }

    fn start_host_pending_run_like_java(&mut self, name: String, port: u16) {
        self.host_pending_run = Some(DesktopHostPendingRun::new(name, port));
        self.host_error = None;
        self.host_name_focused = false;
        self.host_port_focused = false;
        self.host_color_picker_open = false;
        self.host_info_dialog_open = false;
        self.show_loading_fragment_like_java("@hosting");
    }

    fn tick_host_pending_run(&mut self) -> bool {
        let should_complete = match self.host_pending_run.as_mut() {
            Some(pending) => {
                if pending.frames_remaining > 0 {
                    pending.frames_remaining -= 1;
                }
                pending.frames_remaining == 0
            }
            None => false,
        };
        if should_complete {
            self.complete_host_pending_run_like_java();
        }
        should_complete
    }

    fn complete_host_pending_run_like_java(&mut self) -> bool {
        let Some(pending) = self.host_pending_run.take() else {
            return false;
        };
        let DesktopHostPendingRun { name, port, .. } = pending;
        let host_result = {
            let mut net = self.net_client.net_mut();
            net.host(port)
        };
        match host_result {
            Ok(()) => {
                self.player.name = name;
                self.player.admin = true;
                self.settings_overrides
                    .insert("name".into(), self.player.name.clone());
                self.settings_overrides
                    .insert("port".into(), port.to_string());
                self.set_setting_override(
                    "game",
                    "steampublichost",
                    (!self.host_friends_only).to_string(),
                );
                if self.host_steam_enabled()
                    && !self.host_friends_only
                    && self.host_public_lobby_blocked_by_prerelease()
                {
                    self.set_setting_override("game", "steampublichost", "false");
                    self.host_friends_only = true;
                    self.last_menu_platform_action =
                        Some(DesktopMenuPlatformAction::UpdateSteamLobby);
                    if !self.host_beta_public_info_seen_once() {
                        self.last_menu_info_message = Some("@public.beta".into());
                        self.mark_host_beta_public_info_seen_once();
                    }
                }
                self.sync_runtime_state_from_game_state();
                self.runtime
                    .set_network_context(GameRuntimeNetworkContext::server());
                self.host_error = None;
                self.host_name_focused = false;
                self.host_port_focused = false;
                self.host_color_picker_open = false;
                self.active_menu_route = None;
                self.last_menu_guard_message = Some(format!(
                    "HostDialog.runHost {}:{} friendsOnly={}",
                    self.player.name, port, self.host_friends_only
                ));
            }
            Err(error) => {
                let error_text = error.to_string();
                self.host_error = Some(Self::host_error_message_for_exception(&error_text));
                self.host_name_focused = false;
                self.host_port_focused = false;
                self.host_color_picker_open = false;
                self.host_info_dialog_open = false;
                self.last_menu_guard_message = Some(format!(
                    "HostDialog.runHost failed {}:{} {}",
                    name, port, error
                ));
            }
        }
        self.hide_loading_fragment_like_java();
        true
    }

    fn host_error_message_for_exception(error_text: &str) -> String {
        if error_text.to_lowercase().contains("address already in use") {
            "@server.error.addressinuse".into()
        } else {
            "@server.error".into()
        }
    }

    fn delete_join_saved_server_at(&mut self, index: usize) -> bool {
        if index >= self.join_saved_servers.len() {
            return false;
        }
        let removed = self.join_saved_servers.remove(index);
        if index < self.join_saved_server_refresh_states.len() {
            self.join_saved_server_refresh_states.remove(index);
        }
        if self.connect_target.as_ref() == Some(&removed) {
            self.connect_target = self.join_saved_servers.first().cloned();
        }
        self.connect_error = None;
        self.join_add_dialog_open = false;
        self.join_add_server_focused = false;
        self.join_add_server_edit_index = None;
        self.join_delete_dialog_index = None;
        self.persist_join_saved_servers_to_settings();
        true
    }

    fn refresh_join_local_hosts(&mut self) {
        let (tx, rx) = mpsc::channel::<Option<Host>>();
        let host_tx = tx.clone();
        self.join_local_hosts.clear();
        self.join_local_discovering = true;
        self.join_local_discovery_finished = false;
        self.join_local_discovery_receiver = Some(Arc::new(Mutex::new(rx)));
        self.net_client.net_mut().discover_servers(
            Box::new(move |host| {
                let _ = host_tx.send(Some(host));
            }),
            Box::new(move || {
                let _ = tx.send(None);
            }),
        );
    }

    fn poll_join_local_discovery(&mut self) {
        let Some(receiver) = self.join_local_discovery_receiver.as_ref().cloned() else {
            return;
        };
        let mut finished = false;
        let mut hosts = Vec::new();
        let receiver = receiver.lock().unwrap();
        while let Ok(message) = receiver.try_recv() {
            match message {
                Some(host) => hosts.push(host),
                None => finished = true,
            }
        }
        for host in hosts {
            let duplicate = self
                .join_local_hosts
                .iter()
                .any(|known| known.address == host.address && known.port == host.port);
            if !duplicate {
                self.join_local_hosts.push(host);
            }
        }
        if finished {
            self.join_local_discovering = false;
            self.join_local_discovery_finished = true;
            self.join_local_discovery_receiver = None;
        }
    }

