    fn host_steam_enabled(&self) -> bool {
        self.setting_override_value("platform", "steam")
            .is_some_and(Self::settings_platform_steam_from_storage_value)
    }

    fn platform_ios_enabled(&self) -> bool {
        self.setting_override_value("platform", "ios")
            .is_some_and(|value| matches!(value, "true" | "1" | "ios"))
    }

    fn host_steam_public_host(&self) -> bool {
        self.setting_effective_value("game", "steampublichost")
            .is_some_and(|value| matches!(value.as_str(), "true" | "1"))
    }

    fn host_version_modifier(&self) -> String {
        self.setting_override_value("platform", "versionmodifier")
            .or_else(|| self.setting_override_value("version", "modifier"))
            .map(str::to_string)
            .unwrap_or_else(|| mindustry_core::mindustry::upstream_version_info().modifier)
    }

    fn host_public_lobby_blocked_by_prerelease(&self) -> bool {
        let modifier = self.host_version_modifier().to_ascii_lowercase();
        modifier.contains("beta") || modifier.contains("alpha")
    }

    fn host_beta_public_info_seen_once(&self) -> bool {
        self.settings_overrides
            .get(HOST_BETA_PUBLIC_INFO_SETTINGS_KEY)
            .is_some_and(|value| Self::settings_bool_from_storage_value(value))
    }

    fn mark_host_beta_public_info_seen_once(&mut self) {
        self.settings_overrides
            .insert(HOST_BETA_PUBLIC_INFO_SETTINGS_KEY.into(), "true".into());
    }

    fn host_info_seen_once(&self) -> bool {
        self.settings_overrides
            .get(HOST_INFO_SETTINGS_KEY)
            .is_some_and(|value| Self::settings_bool_from_storage_value(value))
    }

    fn mark_host_info_seen_once(&mut self) {
        self.settings_overrides
            .insert(HOST_INFO_SETTINGS_KEY.into(), "true".into());
    }

    fn host_port_text_is_valid(text: &str) -> bool {
        text.trim()
            .parse::<u16>()
            .is_ok_and(|port| (1..=u16::MAX).contains(&port))
    }

    fn host_port_is_valid(&self) -> bool {
        Self::host_port_text_is_valid(&self.host_port_text)
    }

    fn host_name_setting_or_player_name(&self) -> String {
        self.settings_overrides
            .get("name")
            .filter(|name| !name.trim().is_empty())
            .cloned()
            .or_else(|| (!self.player.name.trim().is_empty()).then(|| self.player.name.clone()))
            .unwrap_or_else(|| "Player".into())
    }

    fn host_port_setting_or_default(&self) -> String {
        self.settings_overrides
            .get("port")
            .filter(|port| Self::host_port_text_is_valid(port))
            .cloned()
            .unwrap_or_else(|| DEFAULT_MINDUSTRY_PORT.to_string())
    }

    fn host_route_content_height(steam: bool) -> f32 {
        HOST_DIALOG_ROW_HEIGHT * 3.0
            + HOST_DIALOG_VERTICAL_GAP * 2.0
            + if steam {
                HOST_DIALOG_FRIENDS_ONLY_HEIGHT + HOST_DIALOG_VERTICAL_GAP
            } else {
                0.0
            }
    }

    fn host_route_content_bottom_for_panel(panel: RenderRect, steam: bool) -> f32 {
        let lower = Self::route_back_button_rect_for_panel(panel).bottom() + 18.0;
        let upper = panel.y + panel.height - 86.0;
        let content_height = Self::host_route_content_height(steam);
        let available = (upper - lower).max(content_height);
        lower + (available - content_height) * 0.5
    }

