    fn map_play_preview_rect_with_max_size(dialog: RenderRect, max_size: f32) -> RenderRect {
        let customize = Self::map_play_customize_button_rect(dialog);
        let top = customize.y - 12.0;
        let bottom_limit = dialog.y + SETTINGS_BACK_BUTTON_HEIGHT + 32.0;
        let available = (top - bottom_limit).max(120.0);
        let size = max_size.min(available).max(120.0);
        RenderRect::new(dialog.center().x - size * 0.5, top - size, size, size)
    }

    fn map_play_preview_fit_rect(
        preview: RenderRect,
        content_width: f32,
        content_height: f32,
    ) -> RenderRect {
        if content_width <= 0.0 || content_height <= 0.0 {
            return preview;
        }
        let scale = (preview.width / content_width).min(preview.height / content_height);
        RenderRect::from_center(
            preview.center(),
            content_width * scale,
            content_height * scale,
        )
    }

