    fn map_play_customize_toggle_rects(
        &self,
        content: RenderRect,
    ) -> Vec<(DesktopCustomRulesToggle, RenderRect)> {
        let mut y = content.y + content.height - 20.0;
        let resource_buttons = self.map_play_customize_inline_resource_buttons();
        let resource_numbers = self.map_play_customize_inline_resource_numbers();
        let resource_suffix_toggles = self.map_play_customize_visible_resource_suffix_toggles();
        let unit_buttons = self.map_play_customize_inline_unit_buttons();
        let unit_numbers = self.map_play_customize_inline_unit_numbers();
        let unit_suffix_toggles = self.map_play_customize_visible_unit_suffix_toggles();
        let environment_numbers = self.map_play_customize_inline_environment_numbers();
        let environment_buttons = self.map_play_customize_inline_environment_buttons();
        let mut rects = Vec::new();
        for (title_key, toggles) in MAP_PLAY_CUSTOM_RULE_TOGGLE_GROUPS {
            let is_resources = *title_key == "@rules.title.resourcesbuilding";
            let is_unit = *title_key == "@rules.title.unit";
            let is_environment = *title_key == "@rules.title.environment";
            let visible_toggles = toggles
                .iter()
                .copied()
                .filter(|toggle| self.map_play_custom_rule_label_matches(toggle.label_key()))
                .collect::<Vec<_>>();
            if visible_toggles.is_empty()
                && !(is_resources
                    && (!resource_numbers.is_empty()
                        || !resource_buttons.is_empty()
                        || !resource_suffix_toggles.is_empty()))
                && !(is_unit
                    && (!unit_numbers.is_empty()
                        || !unit_buttons.is_empty()
                        || !unit_suffix_toggles.is_empty()))
                && !(is_environment
                    && (!environment_numbers.is_empty() || !environment_buttons.is_empty()))
            {
                continue;
            }
            y -= 36.0;
            if is_unit {
                for toggle in self.map_play_customize_visible_unit_prefix_toggles() {
                    rects.push((
                        toggle,
                        RenderRect::new(content.x + 16.0, y - 12.0, content.width - 32.0, 22.0),
                    ));
                    y -= PAUSE_CUSTOM_RULE_TOGGLE_ROW_HEIGHT;
                }
                y -= unit_numbers.len() as f32 * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT;
                for toggle in self.map_play_customize_visible_unit_logic_toggles() {
                    rects.push((
                        toggle,
                        RenderRect::new(content.x + 16.0, y - 12.0, content.width - 32.0, 22.0),
                    ));
                    y -= PAUSE_CUSTOM_RULE_TOGGLE_ROW_HEIGHT;
                }
                y -= Self::map_play_customize_inline_unit_button_rows(content, unit_buttons.len())
                    as f32
                    * 38.0;
                for toggle in unit_suffix_toggles.iter().copied() {
                    rects.push((
                        toggle,
                        RenderRect::new(content.x + 16.0, y - 12.0, content.width - 32.0, 22.0),
                    ));
                    y -= PAUSE_CUSTOM_RULE_TOGGLE_ROW_HEIGHT;
                }
                y -= 10.0;
                continue;
            }
            for toggle in visible_toggles {
                rects.push((
                    toggle,
                    RenderRect::new(content.x + 16.0, y - 12.0, content.width - 32.0, 22.0),
                ));
                y -= 24.0;
                if toggle == DesktopCustomRulesToggle::LimitMapArea {
                    y -= CUSTOM_RULE_LIMIT_AREA_NUMBER_ROW_HEIGHT;
                }
            }
            if is_resources {
                y -= resource_numbers.len() as f32 * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT;
                let columns = Self::map_play_customize_inline_resource_button_columns(
                    content,
                    resource_buttons.len(),
                );
                y -= resource_buttons.len().div_ceil(columns) as f32 * 38.0;
                for toggle in resource_suffix_toggles.iter().copied() {
                    rects.push((
                        toggle,
                        RenderRect::new(content.x + 16.0, y - 12.0, content.width - 32.0, 22.0),
                    ));
                    y -= PAUSE_CUSTOM_RULE_TOGGLE_ROW_HEIGHT;
                }
            }
            if is_unit && !unit_buttons.is_empty() {
                let columns = Self::map_play_customize_inline_resource_button_columns(
                    content,
                    unit_buttons.len(),
                );
                y -= unit_buttons.len().div_ceil(columns) as f32 * 38.0;
            }
            if is_environment {
                y -= environment_numbers.len() as f32 * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT;
                if !environment_buttons.is_empty() {
                    let columns = Self::map_play_customize_inline_resource_button_columns(
                        content,
                        environment_buttons.len(),
                    );
                    y -= environment_buttons.len().div_ceil(columns) as f32 * 38.0;
                }
            }
            y -= 10.0;
        }
        rects
    }

