    fn map_play_custom_rules_visible_number_count(&self) -> usize {
        DesktopCustomRulesNumber::ALL
            .into_iter()
            .filter(|number| self.map_play_custom_rule_label_matches(number.label_key()))
            .count()
    }

    fn map_play_custom_rules_visible_banned_policy_toggles(&self) -> Vec<DesktopCustomRulesToggle> {
        MAP_PLAY_CUSTOM_RULE_BANNED_POLICY_TOGGLES
            .iter()
            .copied()
            .filter(|toggle| {
                !matches!(
                    *toggle,
                    DesktopCustomRulesToggle::HideBannedBlocks
                        | DesktopCustomRulesToggle::BlockWhitelist
                        | DesktopCustomRulesToggle::UnitWhitelist
                ) && self.map_play_custom_rule_label_matches(toggle.label_key())
            })
            .collect()
    }

    fn map_play_custom_rules_visible_policy_count(&self) -> usize {
        self.map_play_custom_rules_visible_banned_policy_toggles()
            .len()
    }

    fn map_play_custom_rules_additional_setup_content_height(&self) -> f32 {
        let mut height = 0.0;
        let mut current_category: Option<&str> = None;
        for entry in &self.custom_rules_additional_setup_entries {
            if !self.map_play_custom_rules_additional_setup_entry_matches(entry) {
                continue;
            }
            let category = entry.category_key.as_str();
            if current_category != Some(category) {
                if current_category.is_some() {
                    height += 10.0;
                }
                height += 36.0;
                current_category = Some(category);
            }
            height += PAUSE_CUSTOM_RULE_TOGGLE_ROW_HEIGHT;
        }
        height
    }

    fn map_play_custom_rules_toggle_content_height(&self, content: RenderRect) -> f32 {
        let resource_buttons = self.map_play_customize_inline_resource_buttons();
        let resource_numbers = self.map_play_customize_inline_resource_numbers();
        let resource_suffix_toggles = self.map_play_customize_visible_resource_suffix_toggles();
        let unit_buttons = self.map_play_customize_inline_unit_buttons();
        let unit_numbers = self.map_play_customize_inline_unit_numbers();
        let unit_suffix_toggles = self.map_play_customize_visible_unit_suffix_toggles();
        let environment_numbers = self.map_play_customize_inline_environment_numbers();
        let environment_buttons = self.map_play_customize_inline_environment_buttons();
        let mut height = 20.0;
        for (title_key, toggles) in MAP_PLAY_CUSTOM_RULE_TOGGLE_GROUPS {
            let is_resources = *title_key == "@rules.title.resourcesbuilding";
            let is_unit = *title_key == "@rules.title.unit";
            let is_environment = *title_key == "@rules.title.environment";
            let visible_count = toggles
                .iter()
                .copied()
                .filter(|toggle| self.map_play_custom_rule_label_matches(toggle.label_key()))
                .count();
            if visible_count == 0
                && !(is_resources
                    && (!resource_numbers.is_empty()
                        || !resource_buttons.is_empty()
                        || !resource_suffix_toggles.is_empty()))
                && !(is_unit
                    && (!unit_numbers.is_empty()
                        || !unit_buttons.is_empty()
                        || !unit_suffix_toggles.is_empty()))
                && !(is_environment
                    && (!environment_numbers.is_empty() || !environment_buttons.is_empty()))
            {
                continue;
            }
            if is_unit {
                height += PAUSE_CUSTOM_RULE_TOGGLE_GROUP_HEADER_HEIGHT
                    + self.map_play_customize_inline_unit_body_height(content);
                continue;
            }
            height += PAUSE_CUSTOM_RULE_TOGGLE_GROUP_HEADER_HEIGHT
                + visible_count as f32 * PAUSE_CUSTOM_RULE_TOGGLE_ROW_HEIGHT;
            if toggles
                .iter()
                .copied()
                .any(|toggle| toggle == DesktopCustomRulesToggle::LimitMapArea)
                && self.map_play_custom_rule_label_matches(
                    DesktopCustomRulesToggle::LimitMapArea.label_key(),
                )
            {
                height += CUSTOM_RULE_LIMIT_AREA_NUMBER_ROW_HEIGHT;
            }
            if is_resources {
                height += resource_numbers.len() as f32 * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT;
                let columns = Self::map_play_customize_inline_resource_button_columns(
                    content,
                    resource_buttons.len(),
                );
                height += resource_buttons.len().div_ceil(columns) as f32 * 38.0;
                height +=
                    resource_suffix_toggles.len() as f32 * PAUSE_CUSTOM_RULE_TOGGLE_ROW_HEIGHT;
            }
            if is_environment {
                height += environment_numbers.len() as f32 * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT;
                if !environment_buttons.is_empty() {
                    let columns = Self::map_play_customize_inline_resource_button_columns(
                        content,
                        environment_buttons.len(),
                    );
                    height += environment_buttons.len().div_ceil(columns) as f32 * 38.0;
                }
            }
        }
        height += self.map_play_custom_rules_additional_setup_content_height();
        if self.map_play_custom_rule_label_matches("@rules.title.planet") {
            let button_count = self.pause_planet_candidates().len() + 1;
            let columns = Self::map_play_customize_inline_planet_columns(content);
            height += 46.0 + button_count.div_ceil(columns) as f32 * 42.0;
        }
        if self.map_play_customize_inline_teams_visible() {
            height += 46.0 + 36.0 + 2.0 * 42.0 + Self::map_play_team_options().len() as f32 * 34.0;
            height += self.map_play_inline_team_rules_expanded_teams.len() as f32
                * Self::map_play_customize_inline_team_expanded_field_height();
        }
        height + 18.0
    }

    fn map_play_custom_rules_number_policy_content_height(&self) -> f32 {
        let row_count = self
            .map_play_custom_rules_visible_number_count()
            .max(self.map_play_custom_rules_visible_policy_count())
            .max(DesktopCustomRulesNumber::ALL.len());
        40.0 + row_count as f32 * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT
    }

    fn map_play_custom_rules_content_height(&self, content: RenderRect) -> f32 {
        self.map_play_custom_rules_toggle_content_height(content)
            .max(self.map_play_custom_rules_number_policy_content_height())
            .max(content.height)
    }

    fn map_play_custom_rules_max_scroll_offset(&self, content: RenderRect) -> f32 {
        ((self.map_play_custom_rules_content_height(content) - content.height).max(0.0)
            / PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT)
            .ceil()
    }

    fn map_play_custom_rules_scrolled_content_rect(&self, content: RenderRect) -> RenderRect {
        let offset = self
            .map_play_custom_rules_scroll_offset
            .clamp(0.0, self.map_play_custom_rules_max_scroll_offset(content));
        RenderRect::new(
            content.x,
            content.y + offset * PAUSE_CUSTOM_RULE_SCROLL_ROW_HEIGHT,
            content.width,
            content.height,
        )
    }

