    fn custom_rules_additional_setup_rects_from_y(
        &self,
        content: RenderRect,
        mut y: f32,
        pause: bool,
        clipped: bool,
    ) -> Vec<(usize, RenderRect)> {
        let mut rects = Vec::new();
        let mut current_category: Option<&str> = None;
        for (entry_index, entry) in self
            .custom_rules_additional_setup_entries
            .iter()
            .enumerate()
        {
            let visible = if pause {
                self.pause_custom_rules_additional_setup_entry_matches(entry)
            } else {
                self.map_play_custom_rules_additional_setup_entry_matches(entry)
            };
            if !visible {
                continue;
            }
            let category = entry.category_key.as_str();
            if current_category != Some(category) {
                if current_category.is_some() {
                    y -= 10.0;
                }
                if clipped && y < content.y + 34.0 {
                    break;
                }
                y -= 36.0;
                current_category = Some(category);
            }
            if clipped && y < content.y + 18.0 {
                break;
            }
            rects.push((
                entry_index,
                RenderRect::new(content.x + 16.0, y - 12.0, content.width - 32.0, 22.0),
            ));
            y -= 24.0;
        }
        rects
    }

    fn map_play_limit_area_number_rects(
        &self,
        content: RenderRect,
    ) -> Vec<(DesktopLimitAreaNumber, RenderRect)> {
        if !self.limit_area_number_rows_visible_for_query(false) {
            return Vec::new();
        }
        let Some((_, toggle_row)) = self
            .map_play_customize_toggle_rects(content)
            .into_iter()
            .find(|(toggle, _)| *toggle == DesktopCustomRulesToggle::LimitMapArea)
        else {
            return Vec::new();
        };
        let row = Self::custom_rules_limit_area_number_row_rect(toggle_row);
        DesktopLimitAreaNumber::ALL
            .into_iter()
            .enumerate()
            .map(|(field_index, number)| {
                (
                    number,
                    Self::custom_rules_limit_area_number_field_rect(row, field_index),
                )
            })
            .collect()
    }

