    fn custom_rules_number_row_rect_with_count(
        content: RenderRect,
        index: usize,
        count: usize,
    ) -> RenderRect {
        let width = (content.width - 40.0).clamp(260.0, 390.0);
        RenderRect::new(
            content.right() - width - 16.0,
            content.y + 20.0 + (count - 1 - index) as f32 * 27.0,
            width,
            23.0,
        )
    }

    fn map_play_customize_number_button_rect(row: RenderRect, increase: bool) -> RenderRect {
        let width = 24.0;
        let gap = 4.0;
        let x = if increase {
            row.right() - width
        } else {
            row.right() - width * 2.0 - gap
        };
        RenderRect::new(x, row.y + 1.0, width, row.height - 2.0)
    }

    fn map_play_customize_banned_policy_row_rect(content: RenderRect, index: usize) -> RenderRect {
        let number_row = Self::map_play_customize_number_row_rect(content, index);
        RenderRect::new(
            content.x + 16.0,
            number_row.y,
            (number_row.x - content.x - 28.0).max(150.0),
            number_row.height,
        )
    }

    fn map_play_custom_rule_label_matches(&self, label_key: &'static str) -> bool {
        self.custom_rule_label_matches_query(label_key, self.map_play_custom_rules_search.trim())
    }

    fn pause_custom_rule_label_matches(&self, label_key: &'static str) -> bool {
        self.custom_rule_label_matches_query(label_key, self.pause_custom_rules_search.trim())
    }

    fn custom_rules_additional_setup_text(&self, text: &str) -> String {
        if text.starts_with('@') {
            self.localize_bundle_markup_text(text)
        } else {
            text.to_string()
        }
    }

    fn custom_rules_additional_setup_entry_matches_query(
        &self,
        entry: &DesktopCustomRulesAdditionalSetupEntry,
        query: &str,
    ) -> bool {
        let query = schematic_search_normalize(query);
        if query.is_empty() {
            return true;
        }
        schematic_search_normalize(&self.custom_rules_additional_setup_text(&entry.label_key))
            .contains(query.as_str())
            || schematic_search_normalize(
                &self.custom_rules_additional_setup_text(&entry.category_key),
            )
            .contains(query.as_str())
    }

    fn map_play_custom_rules_additional_setup_entry_matches(
        &self,
        entry: &DesktopCustomRulesAdditionalSetupEntry,
    ) -> bool {
        self.custom_rules_additional_setup_entry_matches_query(
            entry,
            self.map_play_custom_rules_search.trim(),
        )
    }

    fn pause_custom_rules_additional_setup_entry_matches(
        &self,
        entry: &DesktopCustomRulesAdditionalSetupEntry,
    ) -> bool {
        self.custom_rules_additional_setup_entry_matches_query(
            entry,
            self.pause_custom_rules_search.trim(),
        )
    }

    fn custom_rule_label_matches_query(&self, label_key: &'static str, query: &str) -> bool {
        let query = schematic_search_normalize(query);
        if query.is_empty() {
            return true;
        }
        let localized = self.localize_bundle_markup_text(label_key);
        schematic_search_normalize(&localized).contains(query.as_str())
    }

    fn map_play_banned_content_dialog_rect(child: RenderRect) -> RenderRect {
        let width = (child.width - 64.0).clamp(520.0, 700.0);
        let height = (child.height - 86.0).clamp(300.0, 420.0);
        RenderRect::new(
            child.center().x - width * 0.5,
            child.center().y - height * 0.5,
            width,
            height,
        )
    }

    fn map_play_banned_content_close_rect(dialog: RenderRect) -> RenderRect {
        RenderRect::new(dialog.center().x - 70.0, dialog.y + 18.0, 140.0, 38.0)
    }

    fn map_play_banned_content_search_rect(dialog: RenderRect) -> RenderRect {
        RenderRect::new(
            dialog.x + 42.0,
            dialog.y + dialog.height - 78.0,
            dialog.width - 96.0,
            34.0,
        )
    }

    fn map_play_banned_content_search_clear_rect(dialog: RenderRect) -> RenderRect {
        let search = Self::map_play_banned_content_search_rect(dialog);
        RenderRect::new(search.right() - 34.0, search.y + 3.0, 28.0, 28.0)
    }

    fn map_play_banned_content_category_rect(dialog: RenderRect, index: usize) -> RenderRect {
        let width = 32.0;
        let gap = 2.0;
        let total = Category::ALL.len() as f32 * width + (Category::ALL.len() - 1) as f32 * gap;
        RenderRect::new(
            dialog.center().x - total * 0.5 + index as f32 * (width + gap),
            dialog.y + dialog.height - 120.0,
            width,
            28.0,
        )
    }

    fn map_play_banned_content_add_all_rect(dialog: RenderRect, selected_side: bool) -> RenderRect {
        let grid = Self::map_play_banned_content_grid_rect(dialog, selected_side);
        RenderRect::new(grid.x, dialog.y + 62.0, grid.width, 28.0)
    }

    fn map_play_banned_content_grid_rect(dialog: RenderRect, selected_side: bool) -> RenderRect {
        let column_width = (dialog.width - 56.0) * 0.5;
        let x = if selected_side {
            dialog.x + 20.0
        } else {
            dialog.x + 36.0 + column_width
        };
        let bottom = dialog.y + 96.0;
        let top = dialog.y + dialog.height - 156.0;
        RenderRect::new(x, bottom, column_width, (top - bottom).max(50.0))
    }

    fn map_play_banned_content_grid_columns(grid: RenderRect) -> usize {
        ((grid.width + 4.0) / 54.0).floor().max(4.0) as usize
    }

    fn map_play_banned_content_visible_rows(dialog: RenderRect) -> usize {
        let grid = Self::map_play_banned_content_grid_rect(dialog, true);
        ((grid.height + 4.0) / 54.0).floor().max(1.0) as usize
    }

    fn map_play_banned_content_visible_capacity(dialog: RenderRect) -> usize {
        let grid = Self::map_play_banned_content_grid_rect(dialog, true);
        Self::map_play_banned_content_grid_columns(grid)
            * Self::map_play_banned_content_visible_rows(dialog)
    }

    fn map_play_banned_content_item_rect(
        dialog: RenderRect,
        selected_side: bool,
        visible_index: usize,
    ) -> RenderRect {
        let grid = Self::map_play_banned_content_grid_rect(dialog, selected_side);
        let columns = Self::map_play_banned_content_grid_columns(grid);
        let column = visible_index % columns;
        let row = visible_index / columns;
        RenderRect::new(
            grid.x + column as f32 * 54.0,
            grid.y + grid.height - 50.0 - row as f32 * 54.0,
            50.0,
            50.0,
        )
    }

    fn map_play_banned_content_block_category(block: &BlockDef) -> Category {
        match block {
            BlockDef::Turret(_) => Category::Turret,
            BlockDef::Production(_) | BlockDef::Ore(_) => Category::Production,
            BlockDef::Distribution(_) | BlockDef::PayloadMassDriver(_) => Category::Distribution,
            BlockDef::Liquid(_) => Category::Liquid,
            BlockDef::Power(_) => Category::Power,
            BlockDef::DefenseWall(_) => Category::Defense,
            BlockDef::Crafting(_) => Category::Crafting,
            BlockDef::UnitFactory(_)
            | BlockDef::UnitReconstructor(_)
            | BlockDef::UnitAssembler(_)
            | BlockDef::UnitAssemblerModule(_)
            | BlockDef::UnitRepairTower(_) => Category::Units,
            BlockDef::Logic(_) => Category::Logic,
            BlockDef::Storage(_)
            | BlockDef::Effect(_)
            | BlockDef::Payload(_)
            | BlockDef::PayloadDeconstructor(_)
            | BlockDef::PayloadConstructor(_)
            | BlockDef::PayloadLoader(_)
            | BlockDef::Sandbox(_)
            | BlockDef::Light(_)
            | BlockDef::Campaign(_) => Category::Effect,
            BlockDef::Plain(_)
            | BlockDef::Floor(_)
            | BlockDef::StaticWall(_)
            | BlockDef::StaticTree(_)
            | BlockDef::TreeBlock(_)
            | BlockDef::TallBlock(_)
            | BlockDef::Prop(_)
            | BlockDef::Legacy(_) => Category::Effect,
        }
    }

    fn map_play_banned_content_candidate_entries(
        &self,
        kind: DesktopBannedContentKind,
    ) -> Vec<DesktopBannedContentEntry> {
        self.banned_content_candidate_entries_with_filter(
            kind,
            &self.map_play_banned_content_search,
            self.map_play_banned_content_selected_category,
        )
    }

    fn pause_banned_content_candidate_entries(
        &self,
        kind: DesktopBannedContentKind,
    ) -> Vec<DesktopBannedContentEntry> {
        self.banned_content_candidate_entries_with_filter(
            kind,
            &self.pause_custom_rules_banned_content_search,
            self.pause_custom_rules_banned_content_selected_category,
        )
    }

    fn banned_content_candidate_entries_with_filter(
        &self,
        kind: DesktopBannedContentKind,
        search: &str,
        selected_category: Option<Category>,
    ) -> Vec<DesktopBannedContentEntry> {
        let mut entries = match kind {
            DesktopBannedContentKind::Blocks => self
                .content_loader
                .blocks()
                .filter(|block| {
                    let base = block.base();
                    base.name != "air" && base.build_visibility.statically_visible()
                })
                .map(|block| {
                    let base = block.base();
                    DesktopBannedContentEntry {
                        name: base.name.clone(),
                        label: base.display_name().to_string(),
                        category: Some(Self::map_play_banned_content_block_category(block)),
                    }
                })
                .collect::<Vec<_>>(),
            DesktopBannedContentKind::Units => self
                .content_loader
                .units()
                .iter()
                .filter(|unit| !unit.is_hidden())
                .map(|unit| DesktopBannedContentEntry {
                    name: unit.name().to_string(),
                    label: unit.localized_name().to_string(),
                    category: None,
                })
                .collect::<Vec<_>>(),
        };
        entries.sort_by(|a, b| {
            schematic_search_normalize(&a.label)
                .cmp(&schematic_search_normalize(&b.label))
                .then_with(|| a.name.cmp(&b.name))
        });
        let query = schematic_search_normalize(search);
        if !query.is_empty() {
            entries.retain(|entry| {
                schematic_search_normalize(&entry.label).contains(&query)
                    || schematic_search_normalize(&entry.name).contains(&query)
            });
        }
        if kind == DesktopBannedContentKind::Blocks {
            if let Some(category) = selected_category {
                entries.retain(|entry| entry.category == Some(category));
            }
        }
        entries
    }

    fn map_play_banned_content_candidate_names(
        &self,
        kind: DesktopBannedContentKind,
    ) -> Vec<String> {
        self.map_play_banned_content_candidate_entries(kind)
            .into_iter()
            .map(|entry| entry.name)
            .collect()
    }

