    fn map_play_banned_content_max_scroll_offset(
        &self,
        dialog: RenderRect,
        kind: DesktopBannedContentKind,
        rules: &Rules,
    ) -> usize {
        let columns = Self::map_play_banned_content_grid_columns(
            Self::map_play_banned_content_grid_rect(dialog, true),
        )
        .max(1);
        let visible_rows = Self::map_play_banned_content_visible_rows(dialog).max(1);
        let selected = self
            .map_play_banned_content_column_entries(kind, rules, true)
            .len();
        let deselected = self
            .map_play_banned_content_column_entries(kind, rules, false)
            .len();
        selected
            .max(deselected)
            .div_ceil(columns)
            .saturating_sub(visible_rows)
    }

    fn pause_banned_content_max_scroll_offset(
        &self,
        dialog: RenderRect,
        kind: DesktopBannedContentKind,
        rules: &Rules,
    ) -> usize {
        let columns = Self::map_play_banned_content_grid_columns(
            Self::map_play_banned_content_grid_rect(dialog, true),
        )
        .max(1);
        let visible_rows = Self::map_play_banned_content_visible_rows(dialog).max(1);
        let selected = self
            .pause_banned_content_column_entries(kind, rules, true)
            .len();
        let deselected = self
            .pause_banned_content_column_entries(kind, rules, false)
            .len();
        selected
            .max(deselected)
            .div_ceil(columns)
            .saturating_sub(visible_rows)
    }

