    fn map_play_team_rules_hover_tooltip_text(&self, dialog: RenderRect) -> Option<String> {
        let cursor = self.last_menu_cursor?;
        if Self::map_play_team_rules_allow_edit_rect(dialog).contains_point(cursor) {
            return Some(self.localize_bundle_markup_text("@rules.allowedit.info"));
        }
        for (field_index, field) in DesktopInlineTeamRuleField::JAVA_ORDER
            .into_iter()
            .enumerate()
        {
            if let DesktopInlineTeamRuleField::Toggle(toggle) = field {
                if let Some(info_key) = toggle.info_key() {
                    if Self::map_play_team_rules_field_rect(dialog, field_index)
                        .contains_point(cursor)
                    {
                        return Some(self.localize_bundle_markup_text(info_key));
                    }
                }
            }
        }
        None
    }

    fn map_play_team_rules_hover_tooltip_target_rect(
        &self,
        dialog: RenderRect,
    ) -> Option<RenderRect> {
        let cursor = self.last_menu_cursor?;
        let allow_edit = Self::map_play_team_rules_allow_edit_rect(dialog);
        if allow_edit.contains_point(cursor) {
            return Some(allow_edit);
        }
        for (field_index, field) in DesktopInlineTeamRuleField::JAVA_ORDER
            .into_iter()
            .enumerate()
        {
            if let DesktopInlineTeamRuleField::Toggle(toggle) = field {
                if toggle.info_key().is_some() {
                    let row = Self::map_play_team_rules_field_rect(dialog, field_index);
                    if row.contains_point(cursor) {
                        return Some(row);
                    }
                }
            }
        }
        None
    }

    fn map_play_team_rules_section_rect(dialog: RenderRect, team_index: usize) -> RenderRect {
        RenderRect::new(
            dialog.x + 22.0,
            dialog.y + dialog.height - 174.0 - team_index as f32 * 34.0,
            180.0,
            28.0,
        )
    }

    fn map_play_team_rules_field_rect(dialog: RenderRect, field_index: usize) -> RenderRect {
        let gap = 12.0;
        let width = ((dialog.width - 244.0 - gap) * 0.5).max(150.0);
        let col = field_index % 2;
        let row = field_index / 2;
        RenderRect::new(
            dialog.x + 220.0 + col as f32 * (width + gap),
            dialog.y + dialog.height - 158.0 - row as f32 * 30.0,
            width,
            26.0,
        )
    }

    fn map_play_team_rules_field_toggle_rect(row: RenderRect) -> RenderRect {
        RenderRect::new(row.right() - 48.0, row.y + 2.0, 42.0, 22.0)
    }

    fn map_play_team_rules_number_button_rect(row: RenderRect, increase: bool) -> RenderRect {
        if increase {
            RenderRect::new(row.right() - 24.0, row.y + 2.0, 22.0, 22.0)
        } else {
            RenderRect::new(row.right() - 88.0, row.y + 2.0, 22.0, 22.0)
        }
    }

