    fn map_editor_locales_add_locale_dialog_rect(
        parent: RenderRect,
        option_count: usize,
    ) -> RenderRect {
        let width = (SETTINGS_LANGUAGE_LIST_WIDTH
            + SETTINGS_LANGUAGE_TABLE_MARGIN_HORIZONTAL * 2.0)
            .max(448.0)
            .min((parent.width - 96.0).max(320.0));
        let content_height = option_count.max(1) as f32 * SETTINGS_LANGUAGE_ROW_HEIGHT
            + option_count.saturating_sub(1) as f32 * SETTINGS_LANGUAGE_ROW_GAP;
        let height = (content_height + SETTINGS_BACK_BUTTON_HEIGHT + 128.0)
            .max(224.0)
            .min((parent.height - 96.0).max(224.0));
        RenderRect::new(
            parent.x + (parent.width - width) * 0.5,
            parent.y + (parent.height - height) * 0.5,
            width,
            height,
        )
    }

