    fn map_editor_locales_locale_rank_like_java(code: &str) -> usize {
        let normalized = if code == "in_ID" { "id_ID" } else { code };
        settings_language_options_like_java()
            .iter()
            .position(|option| option.code == normalized)
            .unwrap_or(usize::MAX)
    }

    fn map_editor_locales_locale_rows_like_java(
        model: &mut MapLocalesDialog,
        ui_locale: &str,
    ) -> Vec<MapLocalesDialogLocaleEntry> {
        let mut locale_rows = Vec::new();
        let mut add_rows = Vec::new();
        for entry in model.locale_rows(|code| map_locales_display_name_for_code(code, ui_locale)) {
            match entry {
                MapLocalesDialogLocaleEntry::Locale(row) => locale_rows.push(row),
                MapLocalesDialogLocaleEntry::Add(row) => add_rows.push(row),
            }
        }
        locale_rows.sort_by(|left, right| {
            Self::map_editor_locales_locale_rank_like_java(&left.locale)
                .cmp(&Self::map_editor_locales_locale_rank_like_java(
                    &right.locale,
                ))
                .then_with(|| {
                    java_case_insensitive_order_cmp(&left.display_name, &right.display_name)
                })
                .then_with(|| left.locale.cmp(&right.locale))
        });
        locale_rows
            .into_iter()
            .map(MapLocalesDialogLocaleEntry::Locale)
            .chain(add_rows.into_iter().map(MapLocalesDialogLocaleEntry::Add))
            .collect()
    }

