        self.editor_map_locales_add_icon_search.clear();
        self.editor_map_locales_add_icon_search_focused = false;
        self.editor_map_locales_add_icon_scroll_offset = 0;
        self.editor_map_locales_property_name.clear();
        self.editor_map_locales_property_value.clear();
        self.editor_map_locales_property_focused = None;
        self.editor_map_locales_property_edit_key = None;
