    fn schematic_info_description_height(
        entry: &DesktopSchematicCardEntry,
        dialog: RenderRect,
    ) -> f32 {
        if entry.description.is_empty() {
            return 0.0;
        }
        let wrap_width = (dialog.width - 80.0).min(500.0).max(120.0);
        let approximate_chars_per_line = (wrap_width / 6.6).floor().max(12.0) as usize;
        let wrapped_lines = entry
            .description
            .split('\n')
            .map(|line| {
                line.chars()
                    .count()
                    .max(1)
                    .div_ceil(approximate_chars_per_line)
            })
            .sum::<usize>()
            .max(1);
        22.0 + wrapped_lines as f32 * 15.0
    }

    fn schematic_info_content_total_height(
        dialog: RenderRect,
        entry: &DesktopSchematicCardEntry,
    ) -> f32 {
        let top = dialog.y + dialog.height - 50.0;
        let mut bottom = dialog.y + 84.0;
        if !entry.requirements.is_empty() {
            let requirement_rows = entry.requirements.len().min(8).div_ceil(4).max(1);
            bottom = bottom.min(dialog.y + 104.0 - (requirement_rows - 1) as f32 * 24.0 - 14.0);
        }
        if entry.power_consumption_centi != 0 || entry.power_production_centi != 0 {
            bottom = bottom.min(dialog.y + 78.0);
        }
        if !entry.description.is_empty() {
            let has_power = entry.power_consumption_centi != 0 || entry.power_production_centi != 0;
            let description_anchor = dialog.y + if has_power { 72.0 } else { 82.0 };
            bottom = bottom
                .min(description_anchor - Self::schematic_info_description_height(entry, dialog));
        }
        (top - bottom + 16.0).max(0.0)
    }

    fn schematic_info_max_scroll_offset(
        dialog: RenderRect,
        entry: &DesktopSchematicCardEntry,
    ) -> f32 {
        let clip = Self::schematic_info_content_clip_rect(dialog);
        (Self::schematic_info_content_total_height(dialog, entry) - clip.height).max(0.0)
    }

