    fn schematic_info_action_at_point(
        &self,
        panel: RenderRect,
        point: RenderPoint,
    ) -> Option<DesktopMenuRouteShellAction> {
        let index = self.schematic_info_dialog?;
        let dialog = Self::schematic_info_dialog_rect_for_panel(panel);
        if let Some(entry) = self.schematic_cards.get(index) {
            let content_clip = Self::schematic_info_content_clip_rect(dialog);
            if point.y >= content_clip.y && point.y <= content_clip.bottom() {
                let scrolled_dialog = Self::schematic_info_scrolled_dialog(
                    dialog,
                    entry,
                    self.schematic_info_scroll_offset,
                );
                for (tag_index, _) in entry.labels.iter().enumerate() {
                    let chip = Self::schematic_edit_owned_tag_chip_rect(scrolled_dialog, tag_index);
                    if Self::schematic_edit_tag_remove_rect(chip).contains_point(point) {
                        return Some(DesktopMenuRouteShellAction::SchematicModalButton(
                            DesktopSchematicModalButton::CardTagRemove {
                                card_index: index,
                                tag_index,
                            },
                        ));
                    }
                }
                let available = self
                    .schematics_tag_names()
                    .into_iter()
                    .filter(|tag| !entry.labels.iter().any(|label| label == tag))
                    .collect::<Vec<_>>();
                for (tag_index, _) in available.iter().enumerate() {
                    if Self::schematic_edit_available_tag_chip_rect(scrolled_dialog, tag_index)
                        .contains_point(point)
                    {
                        return Some(DesktopMenuRouteShellAction::SchematicModalButton(
                            DesktopSchematicModalButton::CardTagAdd {
                                card_index: index,
                                tag_index,
                            },
                        ));
                    }
                }
                if Self::schematic_label_add_button_rect(scrolled_dialog).contains_point(point) {
                    return Some(DesktopMenuRouteShellAction::SchematicModalButton(
                        DesktopSchematicModalButton::CardTagNewText { card_index: index },
                    ));
                }
                if Self::schematic_label_add_icon_button_rect(scrolled_dialog).contains_point(point)
                {
                    return Some(DesktopMenuRouteShellAction::SchematicModalButton(
                        DesktopSchematicModalButton::CardTagNewIcon { card_index: index },
                    ));
                }
            }
        }
        if Self::schematic_info_button_rect(dialog, 0).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::CloseSchematicInfo);
        }
        if Self::schematic_info_button_rect(dialog, 1).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::SchematicInfoExport);
        }
        if Self::schematic_info_button_rect(dialog, 2).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::SchematicInfoEdit);
        }
        None
    }

