    fn database_content_info_body_height(
        &self,
        clip: RenderRect,
        content_type: ContentType,
        name: &str,
    ) -> f32 {
        // Java ContentInfoDialog builds one Table containing the icon/name header,
        // patched banner, body rows, buttons, and displayExtra, then wraps that
        // whole table in a ScrollPane. Keep this as the full table height, not
        // just the post-header body height.
        let stats = self.database_content_stats_like_java(content_type, name);
        let mut height = DATABASE_CONTENT_INFO_HEADER_HEIGHT;
        if self
            .database_content_description(content_type, name)
            .is_some()
        {
            height += if stats.is_empty() { 44.0 } else { 70.0 };
        }
        height += stats.rendered_height();
        if self
            .database_content_resolved_details_like_java(content_type, name)
            .is_some()
        {
            height += 58.0;
        }
        if self.database_content_credit(content_type, name).is_some() {
            height += 34.0;
        }
        if self.menu_console_setting_enabled {
            height += 58.0;
        }
        if self
            .database_content_extra_like_java(content_type, name)
            .is_some()
        {
            height += 64.0;
        }
        height.max(clip.height)
    }

    fn max_database_content_info_scroll_offset(
        &self,
        clip: RenderRect,
        content_type: ContentType,
        name: &str,
    ) -> f32 {
        ((self.database_content_info_body_height(clip, content_type, name) - clip.height).max(0.0)
            / DATABASE_CONTENT_INFO_SCROLL_ROW_HEIGHT)
            .ceil()
    }

    fn database_content_info_scrolled_content_rect(
        &self,
        clip: RenderRect,
        content_type: ContentType,
        name: &str,
    ) -> RenderRect {
        let table_height = self.database_content_info_body_height(clip, content_type, name);
        let offset = self.database_content_info_scroll_offset.clamp(
            0.0,
            self.max_database_content_info_scroll_offset(clip, content_type, name),
        );
        let scroll_pixels = offset * DATABASE_CONTENT_INFO_SCROLL_ROW_HEIGHT;
        RenderRect::new(
            clip.x,
            clip.y + clip.height - table_height + scroll_pixels,
            clip.width,
            table_height,
        )
    }

