    fn campaign_sector_submission_generate_enemy_base_like_java(
        preset: Option<&SectorPreset>,
        runtime: Option<&Sector>,
    ) -> bool {
        runtime.is_some_and(|sector| sector.generate_enemy_base)
            || preset.is_some_and(|preset| {
                preset.planet_name.as_deref() == Some("serpulo")
                    && preset.name.starts_with("sector-serpulo-")
                    && !preset.require_unlock
                    && preset.capture_wave == 0
            })
    }

    fn campaign_sector_submission_open_condition_like_java(
        dialog: &CampaignPlanetDialogState,
        preset: Option<&SectorPreset>,
        runtime: Option<&Sector>,
    ) -> bool {
        let has_base_in_look_mode = runtime.is_some_and(|sector| {
            sector.has_base(Default::default()) && dialog.mode == CampaignPlanetDialogMode::Look
        });
        has_base_in_look_mode || preset.is_some_and(|preset| preset.always_unlocked)
    }

    fn campaign_sector_submission_link_for_selection(
        &self,
        dialog: &CampaignPlanetDialogState,
        preset: Option<&SectorPreset>,
        runtime: Option<&Sector>,
    ) -> Option<&'static str> {
        if !self.campaign_show_sector_submissions {
            return None;
        }
        if !Self::campaign_sector_submission_open_condition_like_java(dialog, preset, runtime) {
            return None;
        }
        if !Self::campaign_sector_submission_generate_enemy_base_like_java(preset, runtime) {
            return None;
        }
        let sector_id = preset
            .and_then(|preset| preset.sector_id)
            .or_else(|| runtime.map(|sector| sector.id))?;
        Self::campaign_sector_submission_link_by_id(sector_id)
    }

    pub fn dispatch_campaign_sector_submission_action_with_platform<P: Platform>(
        &mut self,
        sector_id: i32,
        platform: &mut P,
    ) -> Option<DesktopCampaignSectorSubmissionAction> {
        if !self.campaign_show_sector_submissions {
            return None;
        }
        let uri = Self::campaign_sector_submission_link_by_id(sector_id)?;
        let opened = platform.open_uri(uri);
        let action = DesktopCampaignSectorSubmissionAction {
            sector_id,
            uri: uri.to_string(),
            opened,
        };
        self.last_campaign_sector_submission_action = Some(action.clone());
        Some(action)
    }

    pub fn dispatch_campaign_sector_submission_action(
        &mut self,
        sector_id: i32,
    ) -> Option<DesktopCampaignSectorSubmissionAction> {
        let mut platform = DefaultPlatform;
        self.dispatch_campaign_sector_submission_action_with_platform(sector_id, &mut platform)
    }

    fn campaign_sector_resource_display_name(&self, item_name: &str) -> String {
        let bundle_key = format!("@item.{item_name}.name");
        let localized = self.localize_bundle_markup_text(&bundle_key);
        if localized != bundle_key {
            return localized;
        }
        self.content_loader
            .item_by_name(item_name)
            .map(|item| item.localized_name().to_string())
            .unwrap_or_else(|| item_name.to_string())
    }

    fn campaign_sector_selected_id_like_java(
        preset: Option<&SectorPreset>,
        runtime: Option<&Sector>,
    ) -> Option<i32> {
        runtime
            .map(|sector| sector.id)
            .or_else(|| preset.and_then(|preset| preset.sector_id))
            .or_else(|| preset.map(|preset| preset.original_position))
    }

    fn campaign_sector_selected_has_base_like_java(runtime: Option<&Sector>) -> bool {
        runtime.is_some_and(|sector| sector.has_base(Default::default()))
    }

    fn campaign_sector_selected_locked_like_java(
        preset: Option<&SectorPreset>,
        runtime: Option<&Sector>,
    ) -> bool {
        !Self::campaign_sector_selected_has_base_like_java(runtime)
            && preset.is_some_and(|preset| preset.require_unlock && !preset.always_unlocked)
    }

    fn campaign_sector_selected_has_enemy_base_like_java(
        preset: Option<&SectorPreset>,
        runtime: Option<&Sector>,
    ) -> bool {
        runtime
            .map(|sector| sector.has_enemy_base(Default::default()))
            .unwrap_or_else(|| preset.is_some_and(|preset| preset.capture_wave == 0))
    }

    fn campaign_sector_selected_is_vulnerable_like_java(
        &self,
        dialog: &CampaignPlanetDialogState,
        preset: Option<&SectorPreset>,
        runtime: Option<&Sector>,
    ) -> bool {
        if !Self::campaign_sector_selected_has_base_like_java(runtime)
            || !self
                .campaign_planet_campaign_rules_like_java(&dialog.planet_name)
                .sector_invasion
        {
            return false;
        }
        let Some(sector_id) = Self::campaign_sector_selected_id_like_java(preset, runtime) else {
            return false;
        };
        self.campaign_planet_neighbor_sector_ids_like_java(&dialog.planet_name, sector_id)
            .into_iter()
            .any(|neighbor_id| {
                let enemy =
                    self.campaign_sector_snapshot_by_id_like_java(&dialog.planet_name, neighbor_id);
                enemy.has_enemy_base(Default::default())
                    && enemy
                        .preset
                        .as_ref()
                        .is_none_or(|preset| !preset.require_unlock)
            })
    }

    fn campaign_sector_selected_panel_lines_like_java(
        &self,
        dialog: &CampaignPlanetDialogState,
        preset: Option<&SectorPreset>,
        runtime: Option<&Sector>,
    ) -> Vec<String> {
        if preset.is_none() && runtime.is_none() {
            return Vec::new();
        }

        let mut lines = Vec::new();
        let has_base = Self::campaign_sector_selected_has_base_like_java(runtime);
        let locked = Self::campaign_sector_selected_locked_like_java(preset, runtime);
        let attacked = runtime.is_some_and(|sector| sector.is_attacked(Default::default()));

        if locked {
            lines.push(self.localize_bundle_markup_text("@complete"));
        } else if !has_base {
            let threat = preset
                .map(|preset| Self::campaign_sector_threat_value(preset, runtime))
                .unwrap_or_else(|| runtime.map_or(0.0, |sector| sector.threat));
            let threat_key = Self::campaign_threat_key(threat);
            lines.push(format!(
                "{} [accent]{}",
                self.localize_bundle_markup_text("@sectors.threat"),
                self.localized_threat_label_like_java(threat_key)
            ));
        }

        if attacked {
            lines.push(self.localize_bundle_markup_text("@sectors.underattack"));
        } else if self.campaign_sector_selected_is_vulnerable_like_java(dialog, preset, runtime) {
            lines.push(self.localize_bundle_markup_text("@sectors.vulnerable"));
        } else if !has_base
            && Self::campaign_sector_selected_has_enemy_base_like_java(preset, runtime)
        {
            lines.push(self.localize_bundle_markup_text("@sectors.enemybase"));
        }

        if let Some(resources) = runtime
            .filter(|sector| sector.save_exists && !sector.info.resources.is_empty())
            .map(|sector| sector.info.resources.as_slice())
        {
            let resources = resources
                .iter()
                .take(6)
                .map(|name| self.campaign_sector_resource_display_name(name))
                .collect::<Vec<_>>()
                .join(", ");
            lines.push(format!(
                "{} [accent]{resources}",
                self.localize_bundle_markup_text("@sectors.resources")
            ));
        }

        lines
    }

    fn campaign_planet_defaults_for_name(&self, planet_name: &str) -> SectorPlanetDefaults {
        self.content_loader
            .catalog()
            .planet_by_name(planet_name)
            .map(|planet| planet.meta.to_sector_defaults(planet.sector_count))
            .unwrap_or_else(|| SectorPlanetDefaults::new(planet_name.to_string()))
    }

    fn campaign_launch_loadout_selected_preset(&self) -> Option<&SectorPreset> {
        let dialog = self.campaign_planet_dialog.as_ref()?;
        let selected = dialog.selected_sector_id?;
        self.campaign_sector_preset_by_id(&dialog.planet_name, selected)
    }

    fn campaign_sector_preset_display_name(preset: &SectorPreset) -> String {
        if preset.localized_name.is_empty() {
            preset.name.clone()
        } else {
            preset.localized_name.clone()
        }
    }

    fn campaign_sector_display_name_for_id(&self, planet_name: &str, sector_id: i32) -> String {
        self.campaign_sector_preset_by_id(planet_name, sector_id)
            .map(Self::campaign_sector_preset_display_name)
            .unwrap_or_else(|| format!("#{sector_id}"))
    }

    fn campaign_launch_loadout_sector_name(&self) -> String {
        let Some(dialog) = self.campaign_planet_dialog.as_ref() else {
            return "unknown".into();
        };
        if let Some(source_id) = dialog.launch_sector_id {
            return self.campaign_sector_display_name_for_id(&dialog.planet_name, source_id);
        }
        self.campaign_launch_loadout_selected_preset()
            .map(Self::campaign_sector_preset_display_name)
            .unwrap_or_else(|| "unknown".into())
    }

    fn campaign_launch_loadout_destination_sector(&self) -> Option<Sector> {
        self.campaign_selected_sector_from_dialog()
    }

    fn campaign_launch_loadout_launch_sector_id(&self) -> Option<i32> {
        self.campaign_planet_dialog
            .as_ref()
            .and_then(|dialog| dialog.launch_sector_id)
    }

    fn campaign_launch_sector_matches_launch_id_like_java(
        sector: &Sector,
        launch_sector_id: Option<i32>,
    ) -> bool {
        let Some(launch_sector_id) = launch_sector_id else {
            return true;
        };
        sector.id == launch_sector_id
            || sector.preset.as_ref().and_then(|preset| preset.sector_id) == Some(launch_sector_id)
            || sector
                .preset
                .as_ref()
                .is_some_and(|preset| preset.original_position == launch_sector_id)
    }

    fn campaign_launch_loadout_source_sector(&self) -> Option<&Sector> {
        let launch_sector_id = self.campaign_launch_loadout_launch_sector_id();

        self.game_state
            .get_sector()
            .filter(|sector| {
                Self::campaign_launch_sector_matches_launch_id_like_java(sector, launch_sector_id)
            })
            .or_else(|| {
                self.runtime.state.get_sector().filter(|sector| {
                    Self::campaign_launch_sector_matches_launch_id_like_java(
                        sector,
                        launch_sector_id,
                    )
                })
            })
            .or_else(|| self.game_state.get_sector())
            .or_else(|| self.runtime.state.get_sector())
    }

    fn campaign_launch_loadout_allows_resources(&self) -> bool {
        let Some(sector) = self.campaign_launch_loadout_destination_sector() else {
            return false;
        };
        let planet_name = sector
            .preset
            .as_ref()
            .and_then(|preset| preset.planet_name.as_deref())
            .or_else(|| {
                self.campaign_planet_dialog
                    .as_ref()
                    .map(|dialog| dialog.planet_name.as_str())
            })
            .unwrap_or("serpulo");
        let defaults = self.campaign_planet_defaults_for_name(planet_name);
        sector.allow_launch_loadout(&defaults)
    }

    fn campaign_launch_loadout_allows_schematics(&self) -> bool {
        let Some(sector) = self.campaign_launch_loadout_destination_sector() else {
            return false;
        };
        let planet_name = sector
            .preset
            .as_ref()
            .and_then(|preset| preset.planet_name.as_deref())
            .or_else(|| {
                self.campaign_planet_dialog
                    .as_ref()
                    .map(|dialog| dialog.planet_name.as_str())
            })
            .unwrap_or("serpulo");
        let defaults = self.campaign_planet_defaults_for_name(planet_name);
        sector.allow_launch_schematics(&defaults)
    }

    fn campaign_launch_loadout_destination_description(&self) -> Option<String> {
        self.campaign_launch_loadout_destination_sector()
            .and_then(|sector| sector.preset)
            .and_then(|preset| preset.description)
            .filter(|description| !description.trim().is_empty())
    }

    fn campaign_launch_loadout_planet_name(&self) -> String {
        self.campaign_planet_dialog
            .as_ref()
            .map(|dialog| dialog.planet_name.clone())
            .or_else(|| {
                self.campaign_launch_loadout_destination_sector()
                    .and_then(|sector| {
                        sector
                            .preset
                            .and_then(|preset| preset.planet_name)
                            .filter(|name| !name.is_empty())
                    })
            })
            .unwrap_or_else(|| "serpulo".into())
    }

    fn campaign_launch_loadout_source_planet_name(&self) -> String {
        self.campaign_launch_loadout_source_sector()
            .and_then(|sector| sector.preset.as_ref())
            .and_then(|preset| preset.planet_name.as_deref())
            .filter(|name| !name.is_empty())
            .map(str::to_string)
            .or_else(|| {
                self.campaign_planet_dialog
                    .as_ref()
                    .map(|dialog| dialog.planet_name.clone())
            })
            .unwrap_or_else(|| "serpulo".into())
    }

    fn campaign_launch_item_allowed_on_source_planet_like_java(
        item: &Item,
        source_planet_name: &str,
    ) -> bool {
        item.base.unlocked()
            && item.is_on_planet(item.base.visible_on_database_tab(source_planet_name))
    }

    fn campaign_launch_item_name_allowed_on_source_planet_like_java(
        &self,
        item_name: &str,
        source_planet_name: &str,
    ) -> bool {
        self.content_loader
            .item_by_name(item_name)
            .is_some_and(|item| {
                Self::campaign_launch_item_allowed_on_source_planet_like_java(
                    item,
                    source_planet_name,
                )
            })
    }

    fn campaign_launch_loadout_source_core_name(&self) -> String {
        if let Some(core) = self
            .campaign_launch_loadout_source_sector()
            .map(|sector| sector.info.best_core_type.trim())
            .filter(|core| !core.is_empty())
        {
            return core.to_string();
        }
        let planet_name = self.campaign_launch_loadout_planet_name();
        self.content_loader
            .catalog()
            .planet_by_name(&planet_name)
            .map(|planet| planet.meta.default_core.clone())
            .unwrap_or_else(|| "core-shard".into())
    }

    fn campaign_launch_loadout_core_size(&self, core_name: &str) -> i32 {
        self.content_loader
            .block_by_name(core_name)
            .map(|block| block.base().size)
            .unwrap_or(3)
    }

    fn campaign_launch_loadout_core_capacity(&self, core_name: &str) -> i32 {
        self.content_loader
            .block_by_name(core_name)
            .map(|block| block.base().item_capacity)
            .unwrap_or(4000)
    }

    fn campaign_launch_loadout_candidate_from_loadout(
        &self,
        loadout: &Loadout,
    ) -> Option<DesktopCampaignLaunchLoadoutCandidate> {
        let core_name = loadout.core_block_name()?.to_string();
        let core_size = self.campaign_launch_loadout_core_size(&core_name);
        let name = loadout
            .schematic
            .file
            .as_deref()
            .map(file_stem_like_java)
            .filter(|name| !name.is_empty())
            .unwrap_or_else(|| loadout.name.clone());
        let schematic_name = loadout.schematic.name();
        let display_name = if schematic_name == "unknown" || schematic_name.trim().is_empty() {
            loadout.name.clone()
        } else {
            schematic_name
        };
        Some(DesktopCampaignLaunchLoadoutCandidate {
            name,
            display_name,
            core_name,
            core_size,
            width: loadout.schematic.width,
            height: loadout.schematic.height,
            tile_count: loadout.schematic.tiles.len(),
            requirements: loadout.schematic.requirements(&self.content_loader),
            preview_tiles: loadout
                .schematic
                .tiles
                .iter()
                .map(DesktopSchematicPreviewTile::from_tile)
                .collect(),
        })
    }

    fn campaign_launch_loadout_candidates(&self) -> Vec<DesktopCampaignLaunchLoadoutCandidate> {
        let source_core = self.campaign_launch_loadout_source_core_name();
        let source_core_size = self.campaign_launch_loadout_core_size(&source_core);
        self.content_loader
            .catalog()
            .loadouts
            .iter()
            .filter_map(|loadout| self.campaign_launch_loadout_candidate_from_loadout(loadout))
            .filter(|candidate| candidate.core_size <= source_core_size)
            .collect()
    }

    fn campaign_launch_loadout_selected_candidate(
        &self,
    ) -> Option<DesktopCampaignLaunchLoadoutCandidate> {
        let candidates = self.campaign_launch_loadout_candidates();
        let source_core = self.campaign_launch_loadout_source_core_name();
        let persisted = self
            .campaign_launch_loadout_selected
            .as_deref()
            .or_else(|| {
                self.settings_overrides
                    .get(&last_loadout_key(&source_core))
                    .map(String::as_str)
            });
        persisted
            .and_then(|name| candidates.iter().find(|candidate| candidate.name == name))
            .cloned()
            .or_else(|| candidates.first().cloned())
    }

    fn ensure_campaign_launch_loadout_selected_like_java(&mut self) {
        self.campaign_launch_loadout_selected = self
            .campaign_launch_loadout_selected_candidate()
            .map(|candidate| candidate.name);
    }

    fn select_campaign_launch_loadout_candidate_like_java(&mut self, index: usize) {
        if let Some(candidate) = self.campaign_launch_loadout_candidates().get(index) {
            self.campaign_launch_loadout_selected = Some(candidate.name.clone());
        }
    }

    fn commit_campaign_launch_loadout_selection_like_java(&mut self) {
        if let Some(candidate) = self.campaign_launch_loadout_selected_candidate() {
            let source_core = self.campaign_launch_loadout_source_core_name();
            self.settings_overrides
                .insert(last_loadout_key(&source_core), candidate.name.clone());
            self.campaign_launch_loadout_selected = Some(candidate.name);
        }
    }

    fn campaign_launch_loadout_selected_loadout_like_java(&self) -> Option<Loadout> {
        let selected = self.campaign_launch_loadout_selected_candidate()?;
        self.content_loader
            .catalog()
            .loadouts
            .iter()
            .find_map(|loadout| {
                self.campaign_launch_loadout_candidate_from_loadout(loadout)
                    .filter(|candidate| candidate.name == selected.name)
                    .map(|_| loadout.clone())
            })
    }

    fn sync_campaign_launch_source_sector_like_java(&mut self, source: &Sector) {
        let launch_sector_id = self.campaign_launch_loadout_launch_sector_id();
        let update_game_state = self.game_state.get_sector().is_some_and(|sector| {
            Self::campaign_launch_sector_matches_launch_id_like_java(sector, launch_sector_id)
        });
        let update_runtime_state = self.runtime.state.get_sector().is_some_and(|sector| {
            Self::campaign_launch_sector_matches_launch_id_like_java(sector, launch_sector_id)
        });

        if update_game_state {
            self.game_state.set_sector(Some(source.clone()));
        }
        if update_runtime_state {
            self.runtime.state.set_sector(Some(source.clone()));
        }
    }

    fn consume_campaign_launch_loadout_resources_like_java(&mut self) -> Option<Sector> {
        self.last_campaign_launch_loadout_event = None;
        let source = self.campaign_launch_loadout_source_sector()?.clone();
        let destination = self.campaign_launch_loadout_destination_sector()?;
        let loadout = self.campaign_launch_loadout_selected_loadout_like_java()?;
        let stacks = self.campaign_launch_loadout_stacks();
        let mut from = source;

        for stack in stacks {
            from.remove_stored_item(stack.item, stack.amount);
        }

        self.sync_campaign_launch_source_sector_like_java(&from);
        self.last_campaign_launch_loadout_event = Some(SectorLaunchLoadoutEvent::new(
            destination,
            from.clone(),
            loadout.schematic,
        ));
        Some(from)
    }

    fn campaign_launch_loadout_capacity(&self) -> i32 {
        let planet_name = self.campaign_launch_loadout_planet_name();
        let Some(planet) = self.content_loader.catalog().planet_by_name(&planet_name) else {
            return 1000;
        };
        let core_name = self
            .campaign_launch_loadout_selected_candidate()
            .map(|candidate| candidate.core_name)
            .unwrap_or_else(|| self.campaign_launch_loadout_source_core_name());
        let core_capacity = self.campaign_launch_loadout_core_capacity(&core_name);
        ((core_capacity as f32) * planet.meta.launch_capacity_multiplier)
            .round()
            .max(0.0) as i32
    }

    fn campaign_launch_loadout_valid(&self) -> bool {
        if self.campaign_launch_loadout_destination_sector().is_none() {
            return false;
        }
        let Some(source) = self.campaign_launch_loadout_source_sector() else {
            return true;
        };
        self.campaign_launch_loadout_stacks()
            .iter()
            .all(|stack| source.stored_item_amount(&stack.item) >= stack.amount)
    }

    fn campaign_launch_resource_step(amount: i32) -> i32 {
        if amount < 1000 {
            100
        } else if amount < 2000 {
            200
        } else if amount < 5000 {
            500
        } else {
            1000
        }
    }

    fn campaign_launch_resource_names(&self) -> Vec<String> {
        let source_planet_name = self.campaign_launch_loadout_source_planet_name();
        let mut names = self
            .campaign_launch_loadout_source_sector()
            .map(|sector| sector.info.resources.clone())
            .unwrap_or_default();
        names.retain(|name| {
            self.campaign_launch_item_name_allowed_on_source_planet_like_java(
                name,
                &source_planet_name,
            )
        });
        if let Some(source) = self.campaign_launch_loadout_source_sector() {
            for (item, amount) in &source.info.items {
                if *amount > 0
                    && self.campaign_launch_item_name_allowed_on_source_planet_like_java(
                        item,
                        &source_planet_name,
                    )
                    && !names.iter().any(|existing| existing == item)
                {
                    names.push(item.clone());
                }
            }
        }
        for item in self.content_loader.items().iter().filter(|item| {
            Self::campaign_launch_item_allowed_on_source_planet_like_java(item, &source_planet_name)
        }) {
            let name = item.name().to_string();
            if !names.iter().any(|existing| existing == &name) {
                names.push(name);
            }
        }
        if self.campaign_launch_item_name_allowed_on_source_planet_like_java(
            "copper",
            &source_planet_name,
        ) && !names.iter().any(|name| name == "copper")
        {
            names.insert(0, "copper".into());
        }
        if let Some(candidate) = self.campaign_launch_loadout_selected_candidate() {
            for stack in candidate.requirements {
                if self.campaign_launch_item_name_allowed_on_source_planet_like_java(
                    &stack.item,
                    &source_planet_name,
                ) && !names.iter().any(|name| name == &stack.item)
                {
                    names.push(stack.item);
                }
            }
        }
        names
    }

    fn campaign_launch_resources_default_draft(&self) -> Vec<ItemStack> {
        self.campaign_launch_resource_names()
            .into_iter()
            .map(|name| ItemStack::new(name, 0))
            .collect()
    }

    fn campaign_launch_resources_visible_draft(&self) -> Vec<ItemStack> {
        if self.campaign_launch_resources_draft.is_empty() {
            self.campaign_launch_resources_default_draft()
        } else {
            self.campaign_launch_resources_draft.clone()
        }
    }

    fn campaign_launch_resource_amount(&self, name: &str) -> i32 {
        self.campaign_launch_resources_draft
            .iter()
            .find(|stack| stack.item == name)
            .map(|stack| stack.amount)
            .unwrap_or(0)
    }

    fn seed_campaign_launch_resources_draft_like_java(&mut self) {
        let capacity = self.campaign_launch_loadout_capacity().max(0);
        let previous = self
            .campaign_launch_resources_draft
            .iter()
            .map(|stack| (stack.item.clone(), stack.amount))
            .collect::<BTreeMap<_, _>>();
        self.campaign_launch_resources_draft = self
            .campaign_launch_resource_names()
            .into_iter()
            .map(|name| {
                let amount = previous.get(&name).copied().unwrap_or(0).clamp(0, capacity);
                ItemStack::new(name, amount)
            })
            .collect();
    }

    fn update_campaign_launch_resource_amount<F>(&mut self, index: usize, update: F)
    where
        F: FnOnce(i32, i32) -> i32,
    {
        if self.campaign_launch_resources_draft.is_empty() {
            self.seed_campaign_launch_resources_draft_like_java();
        }
        let capacity = self.campaign_launch_loadout_capacity().max(0);
        if let Some(stack) = self.campaign_launch_resources_draft.get_mut(index) {
            stack.amount = update(stack.amount, capacity).clamp(0, capacity);
        }
    }

    fn campaign_launch_loadout_stacks(&self) -> Vec<ItemStack> {
        let allows_resources = self.campaign_launch_loadout_allows_resources();
        let max_resources = self.campaign_launch_loadout_use_max_resources && allows_resources;
        let capacity = self.campaign_launch_loadout_capacity().max(0);
        let source = self.campaign_launch_loadout_source_sector();
        let mut schematic_requirements = BTreeMap::<String, i32>::new();
        if let Some(candidate) = self.campaign_launch_loadout_selected_candidate() {
            for stack in candidate.requirements {
                *schematic_requirements.entry(stack.item).or_insert(0) += stack.amount;
            }
        }
        let mut names = source
            .map(|sector| sector.info.resources.clone())
            .unwrap_or_default();
        if let Some(source) = source {
            for (item, amount) in &source.info.items {
                if *amount > 0 && !names.iter().any(|existing| existing == item) {
                    names.push(item.clone());
                }
            }
        }
        if names.is_empty() {
            self.content_loader
                .items()
                .iter()
                .filter(|item| !item.is_hidden())
                .map(|item| item.name().to_string())
                .for_each(|name| {
                    if !names.iter().any(|existing| existing == &name) {
                        names.push(name);
                    }
                });
        }
        if !names.iter().any(|name| name == "copper") {
            names.insert(0, "copper".into());
        }
        for name in schematic_requirements.keys() {
            if !names.iter().any(|existing| existing == name) {
                names.push(name.clone());
            }
        }
        for stack in &self.campaign_launch_resources_draft {
            if stack.amount > 0 && !names.iter().any(|name| name == &stack.item) {
                names.push(stack.item.clone());
            }
        }
        names
            .into_iter()
            .enumerate()
            .filter_map(|(index, name)| {
                let schematic_amount = schematic_requirements.get(&name).copied().unwrap_or(0);
                let launch_amount = if max_resources {
                    source
                        .map(|source| {
                            (source.stored_item_amount(&name) - schematic_amount).clamp(0, capacity)
                        })
                        .unwrap_or_else(|| (capacity / (4 + index as i32)).max(0))
                } else if allows_resources {
                    self.campaign_launch_resource_amount(&name)
                } else {
                    0
                };
                let amount = schematic_amount + launch_amount;
                (amount > 0).then(|| ItemStack::new(name, amount))
            })
            .collect()
    }

    fn campaign_sector_stats_snapshot(&self) -> Option<Sector> {
        let dialog = self.campaign_planet_dialog.as_ref()?;
        let selected = dialog
            .selected_sector_id
            .and_then(|id| self.campaign_sector_preset_by_id(&dialog.planet_name, id))
            .or_else(|| self.content_loader.sector_by_name("groundZero"));
        self.campaign_selected_runtime_sector(dialog, selected)
            .cloned()
            .or_else(|| self.campaign_selected_sector_from_dialog())
    }

    fn campaign_sector_has_base_for_stats(sector: &Sector) -> bool {
        sector.save_exists && sector.info.has_core
    }

    fn campaign_sector_play_time_label(sector: &Sector) -> String {
        let minutes = sector.info.minutes_captured.max(0.0).round() as i32;
        if minutes >= 60 {
            format!("{}h {}m", minutes / 60, minutes % 60)
        } else {
            format!("{minutes}m")
        }
    }

    fn campaign_sector_stat_item_lines(
        &self,
        stats: &HashMap<String, ExportStat>,
    ) -> Vec<(String, String)> {
        let mut lines = stats
            .iter()
            .filter_map(|(item, stat)| {
                let total = (stat.mean * 60.0) as i32;
                (total > 1).then(|| {
                    (
                        item.clone(),
                        format!(
                            "{} {}",
                            ui_format_amount(total as i64),
                            self.localize_bundle_markup_text("@unit.perminute")
                        ),
                    )
                })
            })
            .collect::<Vec<_>>();
        lines.sort_by(|left, right| left.0.cmp(&right.0));
        lines
    }

    fn campaign_selected_sector_from_dialog(&self) -> Option<Sector> {
        let dialog = self.campaign_planet_dialog.as_ref()?;
        let selected = dialog.selected_sector_id?;
        let preset = self.campaign_sector_preset_by_id(&dialog.planet_name, selected)?;
        let mut sector = Sector::new(selected);
        sector.preset = Some(preset.clone());
        sector.save_exists = true;
        sector.info.has_core = true;
        Some(sector)
    }

    fn visible_about_links(&self) -> Vec<&'static AboutLinkEntry> {
        let filter_banned = self.about_filter_banned_links
            || self.host_steam_enabled()
            || self.platform_ios_enabled();
        ABOUT_LINKS
            .iter()
            .filter(|link| !filter_banned || !ABOUT_BANNED_LINK_NAMES.contains(&link.name))
            .collect()
    }

    fn about_link_by_name(&self, name: &str) -> Option<&'static AboutLinkEntry> {
        self.visible_about_links()
            .into_iter()
            .find(|link| link.name == name)
    }

    pub fn dispatch_about_link_action_with_platform<P: Platform>(
        &mut self,
        name: &str,
        platform: &mut P,
    ) -> Option<DesktopAboutLinkAction> {
        let link = self.about_link_by_name(name)?;
        let wiki_event_fired = link.name == "wiki";
        let opened = platform.open_uri(link.url);
        let (clipboard_text, error_message) = if opened {
            (None, None)
        } else {
            platform.set_clipboard_text(link.url);
            (Some(link.url.to_string()), Some("@linkfail".to_string()))
        };
        let action = DesktopAboutLinkAction {
            name: link.name.to_string(),
            url: link.url.to_string(),
            opened,
            wiki_event_fired,
            clipboard_text,
            error_message,
        };
        self.last_about_linkfail_message = action.error_message.clone();
        self.last_about_link_action = Some(action.clone());
        Some(action)
    }

    pub fn dispatch_about_link_action(&mut self, name: &str) -> Option<DesktopAboutLinkAction> {
        let mut platform = DefaultPlatform;
        self.dispatch_about_link_action_with_platform(name, &mut platform)
    }

    pub fn dispatch_database_content_fields_with_platform<P: Platform>(
        &mut self,
        platform: &mut P,
    ) -> Option<DesktopDatabaseFieldsAction> {
        let (content_type, name) = self.last_database_content_opened.clone()?;
        let class_name = self
            .database_content_fields_class_name(content_type, &name)
            .to_string();
        let url = self.database_content_fields_url(content_type, &name);
        let opened = platform.open_uri(&url);
        let (clipboard_text, error_message) = if opened {
            (None, None)
        } else {
            platform.set_clipboard_text(&url);
            (Some(url.clone()), Some("@linkfail".to_string()))
        };
        let action = DesktopDatabaseFieldsAction {
            content_type,
            name,
            class_name,
            url,
            opened,
            clipboard_text,
            error_message,
        };
        self.last_about_linkfail_message = action.error_message.clone();
        self.last_database_fields_action = Some(action.clone());
        Some(action)
    }

    pub fn dispatch_database_content_fields(&mut self) -> Option<DesktopDatabaseFieldsAction> {
        let mut platform = DefaultPlatform;
        self.dispatch_database_content_fields_with_platform(&mut platform)
    }

    pub fn dispatch_database_content_icon_copy_with_platform<P: Platform>(
        &mut self,
        content_type: ContentType,
        record_index: usize,
        platform: &mut P,
    ) -> Option<DesktopDatabaseIconCopyAction> {
        let name = self
            .content_loader
            .get_by(content_type)
            .get(record_index)
            .and_then(|record| record.name())?
            .to_string();
        let (atlas_symbol, emoji) = self.database_content_icon_emoji(content_type, &name)?;
        platform.set_clipboard_text(&emoji);
        self.last_menu_info_message = Some("@copied".to_string());
        let action = DesktopDatabaseIconCopyAction {
            content_type,
            name,
            atlas_symbol,
            emoji,
        };
        self.last_database_icon_copy_action = Some(action.clone());
        Some(action)
    }

    pub fn dispatch_database_content_icon_copy(
        &mut self,
        content_type: ContentType,
        record_index: usize,
    ) -> Option<DesktopDatabaseIconCopyAction> {
        let mut platform = DefaultPlatform;
        self.dispatch_database_content_icon_copy_with_platform(
            content_type,
            record_index,
            &mut platform,
        )
    }

    pub fn copy_discord_link_with_platform<P: Platform>(&mut self, platform: &mut P) -> String {
        platform.set_clipboard_text(DISCORD_URL);
        self.last_discord_clipboard_text = Some(DISCORD_URL.to_string());
        DISCORD_URL.to_string()
    }

    pub fn copy_discord_link(&mut self) -> String {
        let mut platform = DefaultPlatform;
        self.copy_discord_link_with_platform(&mut platform)
    }

    fn push_database_route_page(&self, pass: &mut RenderPass, panel: RenderRect) {
        let search = Self::database_search_rect_for_panel(panel);
        let search_field = Self::database_search_field_rect_for_panel(panel);
        pass.push(RenderCommand::draw_sprite(
            Self::settings_text_field_background_symbol(),
            search_field,
            [
                1.0,
                1.0,
                1.0,
                if self.database_search_focused {
                    0.98
                } else {
                    0.90
                },
            ],
            0.0,
            Layer::END_PIXELED + 0.025,
        ));
        if self.database_search_focused {
            pass.push(RenderCommand::stroke_rect(
                search_field,
                [0.66, 0.82, 0.94, 0.72],
                1.0,
                Layer::END_PIXELED + 0.0255,
            ));
        }
        pass.push(RenderCommand::draw_text_styled(
            desktop_ui_icon_glyph_or_label("zoom", "zoom"),
            RenderPoint::new(search.x + 14.0, search.center().y),
            [0.72, 0.82, 0.9, 1.0],
            14.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_font(RenderFontId::Icon)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            Layer::END_PIXELED + 0.03,
        ));
        pass.push(RenderCommand::draw_text_styled(
            if self.database_search.is_empty() {
                self.localize_bundle_markup_text("@players.search")
            } else {
                self.database_search.clone()
            },
            RenderPoint::new(search_field.x + 10.0, search_field.center().y),
            if self.database_search.is_empty() {
                [0.60, 0.70, 0.78, 1.0]
            } else {
                [0.90, 0.96, 1.0, 1.0]
            },
            12.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            Layer::END_PIXELED + 0.03,
        ));
        if self.database_search_focused {
            pass.push(RenderCommand::draw_sprite(
                Self::settings_text_field_cursor_symbol(),
                Self::single_line_text_field_cursor_rect(search_field, &self.database_search),
                [0.92, 0.98, 1.0, 1.0],
                0.0,
                Layer::END_PIXELED + 0.0305,
            ));
        }

        let all_tab = Self::database_tab_rect_for_panel(panel, 0);
        let all_tab_hovered = self
            .last_menu_cursor
            .is_some_and(|cursor| all_tab.contains_point(cursor));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_image_button_symbol_checked(
                "clearNoneTogglei",
                all_tab_hovered,
                false,
                self.database_selected_tab == 0,
            ),
            all_tab,
            [1.0, 1.0, 1.0, 0.92],
            0.0,
            Layer::END_PIXELED + 0.0328,
        ));
        pass.push(RenderCommand::draw_text_styled(
            desktop_ui_icon_glyph_or_label("eyeSmall", "eyeSmall"),
            all_tab.center(),
            [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
            20.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_font(RenderFontId::Icon)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            Layer::END_PIXELED + 0.033,
        ));

        let tab_keys = self.database_tab_keys();
        for (index, tab_key) in tab_keys.iter().enumerate().skip(1) {
            let tab = Self::database_tab_rect_for_panel(panel, index);
            let planet = self.content_loader.catalog().planet_by_name(tab_key);
            let icon = planet
                .and_then(|planet| {
                    (!planet.meta.icon.trim().is_empty()).then_some(planet.meta.icon.as_str())
                })
                .unwrap_or("commandRally");
            let selected = self.database_selected_tab == index;
            let hovered = self
                .last_menu_cursor
                .is_some_and(|cursor| tab.contains_point(cursor));
            pass.push(RenderCommand::draw_sprite(
                Self::settings_image_button_symbol_checked(
                    "clearNoneTogglei",
                    hovered,
                    false,
                    selected,
                ),
                tab,
                [1.0, 1.0, 1.0, 0.92],
                0.0,
                Layer::END_PIXELED + 0.0328 + index as f32 * 0.0001,
            ));
            pass.push(RenderCommand::draw_text_styled(
                desktop_ui_icon_glyph_or_label(icon, "commandRally"),
                tab.center(),
                if selected {
                    [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0]
                } else if let Some(planet) = planet {
                    rgba8888_to_render_color(planet.icon_color_rgba, 1.0)
                } else {
                    [0.86, 0.92, 1.0, 1.0]
                },
                if selected { 22.0 } else { 20.0 },
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_font(RenderFontId::Icon)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                Layer::END_PIXELED + 0.033 + index as f32 * 0.0001,
            ));
        }

        let rows = self.database_visible_grid_rows_for_panel(panel);
        if rows.is_empty() {
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@none.found"),
                RenderPoint::new(panel.x + panel.width * 0.5, all_tab.y - 50.0),
                [0.70, 0.78, 0.84, 1.0],
                13.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.034,
            ));
            self.push_database_content_info_dialog(pass, panel);
            return;
        }

        let row_capacity = Self::database_visible_row_capacity_for_panel(panel);
        let max_scroll = Self::max_database_scroll_offset_for_rows(rows.len(), panel);
        let scroll_offset = self.database_scroll_offset.min(max_scroll);
        for (row_index, row) in rows
            .iter()
            .skip(scroll_offset)
            .take(row_capacity)
            .enumerate()
        {
            let header = Self::database_category_header_rect_for_panel(panel, row_index);
            if header.y < panel.y + 42.0 {
                break;
            }
            if row.category_start {
                let label = self
                    .localize_bundle_markup_text(Self::database_category_label(row.content_type));
                pass.push(RenderCommand::draw_text_styled(
                    label,
                    RenderPoint::new(header.x, header.center().y),
                    [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
                    12.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.034 + row_index as f32 * 0.001,
                ));
                pass.push(RenderCommand::fill_rect(
                    RenderRect::new(header.x, header.y - 4.0, header.width, 3.0),
                    [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 0.92],
                    Layer::END_PIXELED + 0.0345 + row_index as f32 * 0.001,
                ));
            }
            if row.tag_start {
                if let Some(tag) = row.tag.as_ref() {
                    pass.push(RenderCommand::draw_text_styled(
                        self.localized_database_tag_label(tag),
                        RenderPoint::new(header.x + 8.0, header.y - 21.0),
                        [0.56, 0.62, 0.66, 1.0],
                        9.5,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Start)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true),
                        Layer::END_PIXELED + 0.0348 + row_index as f32 * 0.001,
                    ));
                    pass.push(RenderCommand::fill_rect(
                        RenderRect::new(
                            header.x + 128.0,
                            header.y - 22.5,
                            (header.width - 128.0).max(8.0),
                            2.0,
                        ),
                        [0.43, 0.46, 0.50, 0.82],
                        Layer::END_PIXELED + 0.0348 + row_index as f32 * 0.001,
                    ));
                }
            }
            for (item_index, (_, name)) in row.records.iter().enumerate() {
                let cell = Self::database_content_cell_rect_for_panel(panel, row_index, item_index);
                let icon_symbol = self.database_content_icon_symbol(row.content_type, name);
                let unlocked = self.database_content_unlocked(row.content_type, name);
                let banned = self.database_content_is_banned(row.content_type, name);
                let hovered = unlocked
                    && self
                        .last_menu_cursor
                        .is_some_and(|cursor| cell.contains_point(cursor));
                if unlocked {
                    pass.push(RenderCommand::draw_sprite(
                        icon_symbol,
                        cell,
                        if hovered {
                            [1.0, 1.0, 1.0, 1.0]
                        } else {
                            [0.80, 0.84, 0.88, 0.96]
                        },
                        0.0,
                        Layer::END_PIXELED + 0.035 + row_index as f32 * 0.001,
                    ));
                }
                pass.push(RenderCommand::stroke_rect(
                    cell,
                    [0.34, 0.48, 0.58, 0.82],
                    1.0,
                    Layer::END_PIXELED + 0.036 + row_index as f32 * 0.001,
                ));
                if !unlocked {
                    pass.push(RenderCommand::draw_text_styled(
                        desktop_ui_icon_glyph_or_label("lock", "lock"),
                        cell.center(),
                        [0.50, 0.56, 0.62, 0.92],
                        18.0,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Center)
                            .with_font(RenderFontId::Icon)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true)
                            .with_outline(true),
                        Layer::END_PIXELED + 0.037 + row_index as f32 * 0.001,
                    ));
                }
                if banned {
                    pass.push(RenderCommand::draw_text_styled(
                        desktop_ui_icon_glyph_or_label("cancel", "cancel"),
                        cell.center(),
                        [0.96, 0.20, 0.16, 0.98],
                        20.0,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Center)
                            .with_font(RenderFontId::Icon)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true)
                            .with_outline(true),
                        Layer::END_PIXELED + 0.038 + row_index as f32 * 0.001,
                    ));
                } else if self.database_content_is_patched(row.content_type, name) {
                    pass.push(RenderCommand::draw_text_styled(
                        desktop_ui_icon_glyph_or_label("fileSmall", "fileSmall"),
                        RenderPoint::new(cell.right() - 7.0, cell.y + 7.0),
                        [1.0, 1.0, 1.0, 0.55],
                        12.0,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Center)
                            .with_font(RenderFontId::Icon)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true)
                            .with_outline(true),
                        Layer::END_PIXELED + 0.038 + row_index as f32 * 0.001,
                    ));
                }
            }
        }
        if max_scroll > 0 {
            let list = Self::database_content_list_rect_for_panel(panel);
            let track = RenderRect::new(list.right() - 8.0, list.y + 6.0, 4.0, list.height - 12.0);
            let knob_height = (track.height
                * (row_capacity.max(1) as f32 / rows.len().max(1) as f32))
                .clamp(24.0, track.height);
            let travel = (track.height - knob_height).max(0.0);
            let knob_y = track.y
                + travel * (scroll_offset as f32 / max_scroll.max(1) as f32).clamp(0.0, 1.0);
            pass.push(RenderCommand::fill_rect(
                track,
                [0.10, 0.15, 0.18, 0.55],
                Layer::END_PIXELED + 0.044,
            ));
            pass.push(RenderCommand::fill_rect(
                RenderRect::new(track.x, knob_y, track.width, knob_height),
                [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 0.92],
                Layer::END_PIXELED + 0.045,
            ));
        }
        self.push_database_tab_hover_tooltip(pass, panel);
        self.push_database_content_hover_tooltip(pass, panel);
        self.push_database_content_info_dialog(pass, panel);
    }

    fn push_database_content_info_dialog(&self, pass: &mut RenderPass, panel: RenderRect) {
        let Some((content_type, name)) = self.last_database_content_opened.as_ref() else {
            return;
        };
        let dialog = Self::database_content_info_dialog_rect_for_panel(panel);
        let clip = Self::database_content_info_scrollpane_rect(dialog);
        let content = self.database_content_info_scrolled_content_rect(clip, *content_type, name);
        let close = Self::database_content_info_close_rect(dialog);
        let display_name = self.database_content_display_name(*content_type, name);
        let icon_symbol = self.database_content_icon_symbol(*content_type, name);
        let description = self.database_content_description(*content_type, name);
        let details = self.database_content_resolved_details_like_java(*content_type, name);
        let credit = self.database_content_credit(*content_type, name);
        let extra = self.database_content_extra_like_java(*content_type, name);
        let stats = self.database_content_stats_like_java(*content_type, name);
        let has_stats = !stats.is_empty();

        pass.push(RenderCommand::fill_rect(
            panel,
            [0.0, 0.0, 0.0, 0.48],
            Layer::END_PIXELED + 0.086,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            dialog,
            [1.0, 1.0, 1.0, 0.98],
            0.0,
            Layer::END_PIXELED + 0.087,
        ));
        pass.push(RenderCommand::stroke_rect(
            dialog,
            [0.52, 0.68, 0.82, 0.95],
            2.0,
            Layer::END_PIXELED + 0.088,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@info.title"),
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 28.0),
            [0.94, 0.98, 1.0, 1.0],
            15.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            Layer::END_PIXELED + 0.091,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("button"),
            clip,
            [1.0, 1.0, 1.0, 0.72],
            0.0,
            Layer::END_PIXELED + 0.089,
        ));
        pass.push(RenderCommand::stroke_rect(
            clip,
            [0.22, 0.30, 0.36, 0.90],
            1.0,
            Layer::END_PIXELED + 0.090,
        ));
        pass.push(RenderCommand::set_clip(clip));
        let icon = Self::database_content_info_header_icon_rect_for_content(content);
        pass.push(RenderCommand::draw_sprite(
            icon_symbol,
            icon,
            [0.88, 0.92, 0.96, 1.0],
            0.0,
            Layer::END_PIXELED + 0.090,
        ));
        pass.push(RenderCommand::stroke_rect(
            icon,
            [0.34, 0.48, 0.58, 0.88],
            1.0,
            Layer::END_PIXELED + 0.091,
        ));
        pass.push(RenderCommand::draw_text_styled(
            format!("[accent]{display_name}"),
            RenderPoint::new(
                icon.right() + 10.0,
                icon.center().y
                    + if self.menu_console_setting_enabled {
                        9.0
                    } else {
                        0.0
                    },
            ),
            [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
            15.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            Layer::END_PIXELED + 0.092,
        ));
        if self.menu_console_setting_enabled {
            pass.push(RenderCommand::draw_text_styled(
                name.clone(),
                RenderPoint::new(icon.right() + 10.0, icon.center().y - 12.0),
                [0.66, 0.76, 0.84, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.092,
            ));
        }
        if self.database_content_is_patched(*content_type, name) {
            let patched_y = icon.y - 10.0;
            pass.push(RenderCommand::draw_text_styled(
                desktop_ui_icon_glyph_or_label("info", "info"),
                RenderPoint::new(icon.right() + 20.0, patched_y),
                [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
                12.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_font(RenderFontId::Icon)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                Layer::END_PIXELED + 0.092,
            ));
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@database.patched"),
                RenderPoint::new(icon.right() + 36.0, patched_y),
                [0.72, 0.82, 0.90, 1.0],
                10.5,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.092,
            ));
        }
        let mut y = Self::database_content_info_body_start_y(content);
        if let Some(description) = description {
            if has_stats {
                pass.push(RenderCommand::draw_text_styled(
                    self.localize_bundle_markup_text("@category.purpose"),
                    RenderPoint::new(clip.x + 14.0, y),
                    [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
                    12.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.093,
                ));
                y -= 26.0;
            }
            pass.push(RenderCommand::draw_text_styled(
                format!("[lightgray]{description}"),
                RenderPoint::new(clip.x + 14.0, y),
                [0.72, 0.78, 0.84, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_wrap_width((clip.width - 28.0).min(500.0))
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.093,
            ));
            y -= 44.0;
        }
        if has_stats {
            let mut row_index = 0usize;
            for group in stats.groups.iter().filter(|group| !group.lines.is_empty()) {
                if stats.use_categories || row_index == 0 {
                    let category_key = if stats.use_categories {
                        format!("@category.{}", group.category)
                    } else {
                        "@category.general".to_string()
                    };
                    pass.push(RenderCommand::draw_text_styled(
                        self.localize_bundle_markup_text(category_key),
                        RenderPoint::new(clip.x + 14.0, y),
                        [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
                        12.0,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Start)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true)
                            .with_outline(true),
                        Layer::END_PIXELED + 0.093,
                    ));
                    y -= 24.0;
                }
                for stat in &group.lines {
                    pass.push(RenderCommand::draw_text_styled(
                        self.localize_bundle_markup_text(&stat.label),
                        RenderPoint::new(clip.x + 22.0, y),
                        [0.70, 0.78, 0.84, 1.0],
                        10.5,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Start)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true),
                        Layer::END_PIXELED + 0.093 + row_index as f32 * 0.0001,
                    ));
                    if !stat.value.trim().is_empty() {
                        pass.push(RenderCommand::draw_text_styled(
                            stat.value.clone(),
                            RenderPoint::new(clip.x + clip.width - 22.0, y),
                            [0.86, 0.94, 1.0, 1.0],
                            10.5,
                            0.0,
                            RenderTextStyle::new(RenderTextAlign::End)
                                .with_vertical_align(RenderTextVerticalAlign::Center)
                                .with_integer_position(true),
                            Layer::END_PIXELED + 0.0935 + row_index as f32 * 0.0001,
                        ));
                    }
                    y -= 20.0;
                    row_index += 1;
                }
            }
            y -= 12.0;
        }
        if let Some(details) = details {
            pass.push(RenderCommand::draw_text_styled(
                format!("[gray]{details}"),
                RenderPoint::new(clip.x + 14.0, y),
                [0.56, 0.64, 0.72, 1.0],
                10.5,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_wrap_width((clip.width - 28.0).min(400.0))
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.093,
            ));
            y -= 44.0;
        }
        if let Some(credit) = credit {
            let created_by = self.localize_bundle_markup_text("@content.createdby");
            let created_by = if created_by.contains("{0}") {
                created_by.replace("{0}", &credit)
            } else {
                format!("{created_by}: {credit}")
            };
            pass.push(RenderCommand::draw_text_styled(
                created_by,
                RenderPoint::new(clip.x + 14.0, y),
                [0.72, 0.82, 0.90, 1.0],
                10.5,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_wrap_width((clip.width - 28.0).min(420.0))
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.093,
            ));
        }
        let viewfields_button =
            self.database_content_info_viewfields_rect_for_content(content, *content_type, name);
        if let Some(button) = viewfields_button {
            self.push_settings_text_button_with_style(
                pass,
                button,
                self.localize_bundle_markup_text("@viewfields"),
                Some("link"),
                Layer::END_PIXELED + 0.0937,
                "grayt",
            );
        }
        if let Some(extra) = extra {
            let extra_y = viewfields_button
                .map(|button| button.y - 22.0)
                .unwrap_or(y - 28.0);
            pass.push(RenderCommand::draw_text_styled(
                extra,
                RenderPoint::new(clip.x + 14.0, extra_y),
                [0.72, 0.82, 0.90, 1.0],
                10.5,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_wrap_width((clip.width - 28.0).min(400.0))
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.0938,
            ));
        }
        pass.push(RenderCommand::clear_clip());
        let max_scroll = self.max_database_content_info_scroll_offset(clip, *content_type, name);
        if max_scroll > 0.0 {
            let track = RenderRect::new(clip.right() - 8.0, clip.y + 6.0, 4.0, clip.height - 12.0);
            let visible_ratio = (clip.height
                / self.database_content_info_body_height(clip, *content_type, name))
            .clamp(0.0, 1.0);
            let knob_height = (track.height * visible_ratio).clamp(24.0, track.height);
            let travel = (track.height - knob_height).max(0.0);
            let offset = self
                .database_content_info_scroll_offset
                .clamp(0.0, max_scroll);
            let knob_y = track.y + travel * (offset / max_scroll.max(1.0)).clamp(0.0, 1.0);
            pass.push(RenderCommand::fill_rect(
                track,
                [0.10, 0.15, 0.18, 0.56],
                Layer::END_PIXELED + 0.0938,
            ));
            pass.push(RenderCommand::fill_rect(
                RenderRect::new(track.x, knob_y, track.width, knob_height),
                [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 0.92],
                Layer::END_PIXELED + 0.0939,
            ));
        }

        self.push_settings_text_button(
            pass,
            close,
            "@back",
            Some("left"),
            Layer::END_PIXELED + 0.094,
        );
    }

