    fn push_host_route_page(&self, pass: &mut RenderPass, panel: RenderRect) {
        self.push_settings_text_button(
            pass,
            Self::route_back_button_rect_for_panel(panel),
            self.localize_bundle_markup_text("@back"),
            Some("left"),
            Layer::END_PIXELED + 0.024,
        );

        let steam = self.host_steam_enabled();
        let name = Self::host_route_name_rect_for_panel_with_steam(panel, steam);
        let color = Self::host_route_color_button_rect_for_panel_with_steam(panel, steam);
        let friends = self.host_route_friends_only_rect_for_panel_with_steam(panel, steam);
        let port = self.host_route_port_rect_for_panel_with_steam(panel, steam);
        let info = self.host_route_info_button_rect_for_panel_with_steam(panel, steam);
        let host = self.host_route_host_button_rect_for_panel_with_steam(panel, steam);
        let outline_label_color = Self::settings_label_style_font_color("outlineLabel");
        let accent_color = [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, Pal::ACCENT.a];

        for (rect, focused) in [
            (name, self.host_name_focused),
            (port, self.host_port_focused),
        ] {
            pass.push(RenderCommand::draw_sprite(
                Self::settings_text_button_symbol("grayt", focused, false),
                rect,
                if focused {
                    [1.0, 1.0, 1.0, 0.96]
                } else {
                    [1.0, 1.0, 1.0, 0.82]
                },
                0.0,
                Layer::END_PIXELED + 0.028,
            ));
        }
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@name"),
            RenderPoint::new(name.x + 14.0, name.center().y),
            outline_label_color,
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            Layer::END_PIXELED + 0.030,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.host_name_text.clone(),
            RenderPoint::new(name.x + 76.0, name.center().y),
            outline_label_color,
            12.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            Layer::END_PIXELED + 0.031,
        ));
        self.push_player_color_image_button(pass, color, Layer::END_PIXELED + 0.032);

        let friends_hovered = steam
            && self
                .last_menu_cursor
                .is_some_and(|cursor| friends.contains_point(cursor));
        if steam {
            let checkbox = Self::host_route_friends_only_check_box_rect(friends);
            pass.push(RenderCommand::draw_sprite(
                Self::settings_check_box_symbol(self.host_friends_only, friends_hovered, false),
                checkbox,
                [1.0, 1.0, 1.0, 1.0],
                0.0,
                Layer::END_PIXELED + 0.034,
            ));
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@steam.friendsonly"),
                Self::host_route_friends_only_label_point(friends),
                outline_label_color,
                12.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.035,
            ));
        }
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@server.port"),
            RenderPoint::new(port.x + 14.0, port.center().y),
            outline_label_color,
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            Layer::END_PIXELED + 0.035,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.host_port_text.clone(),
            RenderPoint::new(port.x + 116.0, port.center().y),
            outline_label_color,
            12.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            Layer::END_PIXELED + 0.036,
        ));
        if !steam {
            self.push_settings_text_button(pass, info, "?", None, Layer::END_PIXELED + 0.037);
        }
        self.push_settings_text_button_enabled(
            pass,
            host,
            "@host",
            None,
            Layer::END_PIXELED + 0.038,
            self.host_port_is_valid(),
        );

        if friends_hovered {
            let tooltip = self.localize_bundle_markup_text("@steam.friendsonly.tooltip");
            self.push_settings_pref_description_tooltip(pass, panel, friends, &tooltip);
        }

        if self.host_color_picker_open {
            let dialog = Self::player_palette_dialog_rect_for_panel(panel);
            pass.push(RenderCommand::fill_rect(
                panel,
                [0.0, 0.0, 0.0, 0.42],
                Layer::END_PIXELED + 0.074,
            ));
            pass.push(RenderCommand::draw_sprite(
                Self::settings_drawable_symbol("pane"),
                dialog,
                [1.0, 1.0, 1.0, 0.98],
                0.0,
                Layer::END_PIXELED + 0.075,
            ));
            pass.push(RenderCommand::stroke_rect(
                dialog,
                accent_color,
                2.0,
                Layer::END_PIXELED + 0.076,
            ));
            for (index, color_value) in HOST_PALETTE_COLORS.iter().copied().enumerate() {
                let swatch = Self::player_palette_color_rect_for_dialog(dialog, index);
                let selected = self.player.color == color_value;
                self.push_palette_color_image_button(
                    pass,
                    swatch,
                    color_value,
                    selected,
                    Layer::END_PIXELED + 0.078 + index as f32 * 0.001,
                );
            }
        }
        if self.host_info_dialog_open {
            let dialog = Self::host_info_dialog_rect_for_panel(panel);
            pass.push(RenderCommand::fill_rect(
                panel,
                [0.0, 0.0, 0.0, 0.44],
                Layer::END_PIXELED + 0.079,
            ));
            pass.push(RenderCommand::draw_sprite(
                Self::settings_drawable_symbol("pane"),
                dialog,
                [1.0, 1.0, 1.0, 0.98],
                0.0,
                Layer::END_PIXELED + 0.081,
            ));
            pass.push(RenderCommand::stroke_rect(
                dialog,
                [0.52, 0.68, 0.82, 0.95],
                2.0,
                Layer::END_PIXELED + 0.082,
            ));
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@info.title"),
                RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 30.0),
                [0.94, 0.98, 1.0, 1.0],
                14.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                Layer::END_PIXELED + 0.083,
            ));
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@host.info"),
                RenderPoint::new(dialog.x + 30.0, dialog.center().y + 20.0),
                outline_label_color,
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_wrap_width(dialog.width - 60.0)
                    .with_markup(true)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.084,
            ));
            self.push_settings_text_button(
                pass,
                Self::join_add_dialog_button_rect(dialog, 1),
                "@ok",
                Some("ok"),
                Layer::END_PIXELED + 0.085,
            );
        }
        self.push_host_error_dialog(pass, panel);
    }

