    fn push_join_route_java_server_card_skin(
        pass: &mut RenderPass,
        card: RenderRect,
        header_height: f32,
        layer: f32,
        alpha: f32,
    ) {
        let header_height = header_height.clamp(0.0, card.height);
        let body = RenderRect::new(card.x, card.y, card.width, card.height - header_height);
        let header = RenderRect::new(
            card.x,
            card.y + card.height - header_height,
            card.width,
            header_height,
        );
        let tint = [Pal::GRAY.r, Pal::GRAY.g, Pal::GRAY.b, alpha];
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("whitePane"),
            body,
            tint,
            0.0,
            layer,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("whiteui"),
            header,
            tint,
            0.0,
            layer + 0.0005,
        ));
    }

