    fn load_game_error_dialog_rect_for_viewport(viewport: RenderViewport) -> RenderRect {
        let stage = RenderRect::new(viewport.x, viewport.y, viewport.width, viewport.height);
        let width = (stage.width * 0.42).clamp(360.0, 560.0);
        let height = 184.0;
        RenderRect::new(
            stage.center().x - width * 0.5,
            stage.center().y - height * 0.5,
            width,
            height,
        )
    }

