    fn max_mods_browser_scroll_offset(&self, list: RenderRect) -> usize {
        self.filtered_mods_browser_indices_len()
            .saturating_sub(Self::mods_browser_visible_entry_capacity_for_list(list))
    }

    fn apply_mods_browser_scroll_delta(
        &mut self,
        surface_size: DesktopSurfaceSize,
        delta_y: f32,
    ) -> bool {
        if self.active_menu_route != Some(DesktopMenuRoute::Mods)
            || !self.mods_browser_dialog_open
            || self.mods_browser_selected_mod_index.is_some()
            || self.mods_browser_releases_dialog_index.is_some()
        {
            return false;
        }
        let Some(cursor) = self.last_menu_cursor else {
            return false;
        };
        let viewport = self.default_render_viewport_for_surface(surface_size);
        let panel = Self::active_menu_route_shell_panel_for_route(viewport, DesktopMenuRoute::Mods);
        let dialog = Self::mods_browser_dialog_rect_for_panel(panel);
        let list = Self::mods_browser_list_rect_for_dialog(dialog);
        if !list.contains_point(cursor) {
            return false;
        }
        let max = self.max_mods_browser_scroll_offset(list);
        if max == 0 {
            return false;
        }
        let current = self.mods_browser_scroll_offset.min(max);
        let rows = delta_y.abs().ceil().max(1.0) as isize;
        let step = if delta_y < 0.0 {
            rows
        } else if delta_y > 0.0 {
            -rows
        } else {
            0
        };
        let next = (current as isize + step).clamp(0, max as isize) as usize;
        self.mods_browser_scroll_offset = next;
        next != current
    }

    fn mods_browser_cache_mix_byte(hash: &mut u64, byte: u8) {
        *hash = (*hash ^ byte as u64).wrapping_mul(0x0000_0100_0000_01b3);
    }

    fn mods_browser_cache_mix_bytes(hash: &mut u64, bytes: &[u8]) {
        for byte in bytes {
            Self::mods_browser_cache_mix_byte(hash, *byte);
        }
        Self::mods_browser_cache_mix_byte(hash, 0xff);
    }

    fn mods_browser_cache_mix_str(hash: &mut u64, value: &str) {
        Self::mods_browser_cache_mix_bytes(hash, value.as_bytes());
    }

    fn mods_browser_cache_mix_optional_str(hash: &mut u64, value: Option<&str>) {
        match value {
            Some(value) => {
                Self::mods_browser_cache_mix_byte(hash, 1);
                Self::mods_browser_cache_mix_str(hash, value.trim());
            }
            None => Self::mods_browser_cache_mix_byte(hash, 0),
        }
    }

    fn mods_browser_cache_mix_optional_i32(hash: &mut u64, value: Option<i32>) {
        match value {
            Some(value) => {
                Self::mods_browser_cache_mix_byte(hash, 1);
                Self::mods_browser_cache_mix_bytes(hash, &value.to_le_bytes());
            }
            None => Self::mods_browser_cache_mix_byte(hash, 0),
        }
    }

    fn mods_browser_cache_mix_usize(hash: &mut u64, value: usize) {
        Self::mods_browser_cache_mix_bytes(hash, &value.to_le_bytes());
    }

    fn mods_browser_listing_fingerprint(&self) -> u64 {
        let mut hash = 0xcbf2_9ce4_8422_2325u64;
        Self::mods_browser_cache_mix_usize(&mut hash, self.last_mods_directory_mod_names.len());
        Self::mods_browser_cache_mix_usize(&mut hash, self.last_mods_directory_mod_metas.len());
        for (index, name) in self.last_mods_directory_mod_names.iter().enumerate() {
            Self::mods_browser_cache_mix_usize(&mut hash, index);
            Self::mods_browser_cache_mix_str(&mut hash, name);
            let meta = self.last_mods_directory_mod_metas.get(index);
            Self::mods_browser_cache_mix_optional_str(
                &mut hash,
                meta.and_then(|meta| meta.name.as_deref()),
            );
            Self::mods_browser_cache_mix_optional_str(
                &mut hash,
                meta.and_then(|meta| meta.display_name.as_deref()),
            );
            Self::mods_browser_cache_mix_optional_str(
                &mut hash,
                meta.and_then(|meta| meta.repo.as_deref()),
            );
            Self::mods_browser_cache_mix_optional_i32(&mut hash, meta.and_then(|meta| meta.stars));
            Self::mods_browser_cache_mix_optional_str(
                &mut hash,
                meta.and_then(|meta| meta.last_updated.as_deref()),
            );
        }
        hash
    }

    fn mods_browser_filtered_indices_cache_key(&self) -> DesktopModsBrowserFilteredIndicesCacheKey {
        DesktopModsBrowserFilteredIndicesCacheKey {
            query: self.mods_browser_search.trim().to_ascii_lowercase(),
            sort_date: self.mods_browser_sort_date,
            mods_len: self.last_mods_directory_mod_names.len(),
            metas_len: self.last_mods_directory_mod_metas.len(),
            listing_fingerprint: self.mods_browser_listing_fingerprint(),
        }
    }

    fn mods_browser_entry_matches_query_uncached(&self, index: usize, query: &str) -> bool {
        if query.is_empty() {
            return true;
        }
        let display_name = self
            .mods_route_mod_display_name_at_index(index)
            .unwrap_or_default()
            .to_ascii_lowercase();
        let meta = self.mods_route_mod_meta_at_index(index);
        let repo = meta
            .and_then(|meta| meta.repo.as_deref())
            .unwrap_or_default()
            .to_ascii_lowercase();
        display_name.contains(query) || repo.contains(query)
    }

    fn rebuild_mods_browser_filtered_indices_cache(
        &self,
        key: DesktopModsBrowserFilteredIndicesCacheKey,
    ) -> DesktopModsBrowserFilteredIndicesCache {
        let mut raw_repo_counts = BTreeMap::<String, usize>::new();
        for meta in &self.last_mods_directory_mod_metas {
            if let Some(repo) = meta.repo.as_deref() {
                *raw_repo_counts.entry(repo.to_string()).or_default() += 1;
            }
        }
        let installed_flags = (0..self.last_mods_directory_mod_names.len())
            .map(|index| {
                let Some(repo) = self.mods_route_mod_repo_at_index(index) else {
                    return false;
                };
                let raw_count = raw_repo_counts.get(repo).copied().unwrap_or(0);
                let self_matches_raw_repo = self
                    .last_mods_directory_mod_metas
                    .get(index)
                    .and_then(|meta| meta.repo.as_deref())
                    .is_some_and(|installed_repo| installed_repo == repo);
                raw_count.saturating_sub(usize::from(self_matches_raw_repo)) > 0
            })
            .collect::<Vec<_>>();
        let mut indices = self
            .last_mods_directory_mod_names
            .iter()
            .enumerate()
            .filter_map(|(index, _)| {
                self.mods_browser_entry_matches_query_uncached(index, &key.query)
                    .then_some(index)
            })
            .collect::<Vec<_>>();
        if key.sort_date {
            indices.sort_by(|left, right| {
                self.mods_route_mod_last_updated_at_index(*right)
                    .cmp(&self.mods_route_mod_last_updated_at_index(*left))
                    .then_with(|| left.cmp(right))
            });
        } else {
            indices.sort_by(|left, right| {
                self.mods_route_mod_stars_at_index(*right)
                    .cmp(&self.mods_route_mod_stars_at_index(*left))
                    .then_with(|| {
                        self.mods_route_mod_display_name_at_index(*left)
                            .unwrap_or_default()
                            .to_ascii_lowercase()
                            .cmp(
                                &self
                                    .mods_route_mod_display_name_at_index(*right)
                                    .unwrap_or_default()
                                    .to_ascii_lowercase(),
                            )
                    })
                    .then_with(|| left.cmp(right))
            });
        }
        DesktopModsBrowserFilteredIndicesCache {
            key,
            indices,
            installed_flags,
        }
    }

    fn refresh_mods_browser_filtered_indices_cache(&self) {
        let key = self.mods_browser_filtered_indices_cache_key();
        let is_current = {
            self.mods_browser_filtered_indices_cache
                .borrow()
                .as_ref()
                .is_some_and(|cache| cache.key == key)
        };
        if is_current {
            return;
        }
        let cache = self.rebuild_mods_browser_filtered_indices_cache(key);
        *self.mods_browser_filtered_indices_cache.borrow_mut() = Some(cache);
        self.mods_browser_filtered_indices_cache_rebuilds
            .set(self.mods_browser_filtered_indices_cache_rebuilds.get() + 1);
    }

    fn mods_browser_entry_installed_like_java(&self, index: usize) -> bool {
        self.refresh_mods_browser_filtered_indices_cache();
        self.mods_browser_filtered_indices_cache
            .borrow()
            .as_ref()
            .and_then(|cache| cache.installed_flags.get(index).copied())
            .unwrap_or(false)
    }

    fn filtered_mods_browser_indices(&self) -> Vec<usize> {
        self.refresh_mods_browser_filtered_indices_cache();
        self.mods_browser_filtered_indices_cache
            .borrow()
            .as_ref()
            .map(|cache| cache.indices.clone())
            .unwrap_or_default()
    }

    fn filtered_mods_browser_indices_len(&self) -> usize {
        self.refresh_mods_browser_filtered_indices_cache();
        self.mods_browser_filtered_indices_cache
            .borrow()
            .as_ref()
            .map(|cache| cache.indices.len())
            .unwrap_or(0)
    }

    #[cfg(test)]
    fn mods_browser_filtered_indices_cache_rebuilds(&self) -> u64 {
        self.mods_browser_filtered_indices_cache_rebuilds.get()
    }

    fn ensure_visible_mods_browser_icon_requests_for_viewport(&mut self, viewport: RenderViewport) {
        if self.active_menu_route != Some(DesktopMenuRoute::Mods)
            || !self.mods_browser_dialog_open
            || self.mods_browser_selected_mod_index.is_some()
            || self.mods_browser_releases_dialog_index.is_some()
        {
            return;
        }
        let panel = Self::active_menu_route_shell_panel_for_route(viewport, DesktopMenuRoute::Mods);
        let dialog = Self::mods_browser_dialog_rect_for_panel(panel);
        let list = Self::mods_browser_list_rect_for_dialog(dialog);
        let scroll_offset = self
            .mods_browser_scroll_offset
            .min(self.max_mods_browser_scroll_offset(list));
        for mod_index in self
            .filtered_mods_browser_indices()
            .into_iter()
            .skip(scroll_offset)
            .take(Self::mods_browser_visible_entry_capacity_for_list(list))
        {
            let Some(repo) = self.mods_route_mod_repo_at_index(mod_index) else {
                continue;
            };
            if self.mods_browser_icon_symbol_for_repo(repo).is_some() {
                continue;
            }
            let repo = repo.to_string();
            self.last_mods_browser_icon_requests
                .entry(repo.clone())
                .or_insert_with(|| DesktopModsBrowserIconRequest {
                    uri: Self::mods_browser_icon_uri(&repo),
                    repo,
                });
        }
    }

    fn mods_browser_releases_dialog_rect_for_browser(dialog: RenderRect) -> RenderRect {
        RenderRect::new(
            dialog.x + 28.0,
            dialog.y + 28.0,
            (dialog.width - 56.0).max(260.0),
            (dialog.height - 56.0).max(220.0),
        )
    }

    fn mods_browser_selection_dialog_rect_for_browser(dialog: RenderRect) -> RenderRect {
        if dialog.height > dialog.width {
            return Self::mods_route_detail_dialog_rect_for_panel(dialog);
        }
        let width = dialog.width.max(632.0);
        RenderRect::new(
            dialog.center().x - width * 0.5,
            dialog.y,
            width,
            dialog.height,
        )
    }

    fn mods_browser_selection_button_rect_for_browser(
        browser: RenderRect,
        dialog: RenderRect,
        index: usize,
        button_count: usize,
    ) -> RenderRect {
        let gap = 4.0;
        let width = 150.0;
        let height = 54.0;
        let portrait_rows = browser.height > browser.width && button_count > 2;
        let buttons_per_row = if portrait_rows {
            2
        } else {
            button_count.max(1)
        };
        let row = if portrait_rows {
            index / buttons_per_row
        } else {
            0
        };
        let column = if portrait_rows {
            index % buttons_per_row
        } else {
            index
        };
        let row_start = row * buttons_per_row;
        let row_count = (button_count - row_start).min(buttons_per_row);
        let total = width * row_count as f32 + gap * row_count.saturating_sub(1) as f32;
        RenderRect::new(
            dialog.center().x - total * 0.5 + column as f32 * (width + gap),
            dialog.y + 18.0 + row as f32 * (height + gap),
            width,
            height,
        )
    }

    fn mods_browser_selection_details_pane_rect_for_browser(
        browser: RenderRect,
        dialog: RenderRect,
        button_count: usize,
    ) -> RenderRect {
        let max_button_top = (0..button_count)
            .map(|index| {
                let rect = Self::mods_browser_selection_button_rect_for_browser(
                    browser,
                    dialog,
                    index,
                    button_count,
                );
                rect.y + rect.height
            })
            .fold(dialog.y + 72.0, f32::max);
        let bottom = max_button_top + 8.0;
        let top = dialog.y + dialog.height - 72.0;
        RenderRect::new(
            dialog.x + 28.0,
            bottom,
            dialog.width - 56.0,
            (top - bottom).max(80.0),
        )
    }

    fn mods_browser_release_entry_rect_for_dialog(dialog: RenderRect, index: usize) -> RenderRect {
        RenderRect::new(
            dialog.x + 20.0,
            dialog.y + dialog.height - 78.0 - index as f32 * 84.0,
            dialog.width - 40.0,
            74.0,
        )
    }

    fn mods_browser_release_visible_entry_capacity_for_dialog(dialog: RenderRect) -> usize {
        ((dialog.height - 100.0) / 84.0).floor().max(1.0) as usize
    }

    fn max_mods_browser_releases_scroll_offset(&self, dialog: RenderRect) -> usize {
        self.mods_browser_release_entries
            .len()
            .saturating_sub(Self::mods_browser_release_visible_entry_capacity_for_dialog(dialog))
    }

    fn apply_mods_browser_releases_scroll_delta(
        &mut self,
        surface_size: DesktopSurfaceSize,
        delta_y: f32,
    ) -> bool {
        if self.active_menu_route != Some(DesktopMenuRoute::Mods)
            || !self.mods_browser_dialog_open
            || self.mods_browser_releases_dialog_index.is_none()
        {
            return false;
        }
        let Some(cursor) = self.last_menu_cursor else {
            return false;
        };
        let viewport = self.default_render_viewport_for_surface(surface_size);
        let panel = Self::active_menu_route_shell_panel_for_route(viewport, DesktopMenuRoute::Mods);
        let browser = Self::mods_browser_dialog_rect_for_panel(panel);
        let dialog = Self::mods_browser_releases_dialog_rect_for_browser(browser);
        if !dialog.contains_point(cursor) {
            return false;
        }
        let max = self.max_mods_browser_releases_scroll_offset(dialog);
        if max == 0 {
            return false;
        }
        let current = self.mods_browser_releases_scroll_offset.min(max);
        let rows = delta_y.abs().ceil().max(1.0) as isize;
        let step = if delta_y < 0.0 {
            rows
        } else if delta_y > 0.0 {
            -rows
        } else {
            0
        };
        let next = (current as isize + step).clamp(0, max as isize) as usize;
        self.mods_browser_releases_scroll_offset = next;
        next != current
    }

    fn mods_browser_release_button_rect(entry: RenderRect, index: usize) -> RenderRect {
        let width = 150.0;
        let height = 54.0;
        let gap = 4.0;
        RenderRect::new(
            entry.right() - 12.0 - width * (index as f32 + 1.0) - gap * index as f32,
            entry.y + 10.0,
            width,
            height,
        )
    }

    fn mods_browser_selection_button_specs(
        &self,
        index: usize,
    ) -> Vec<(DesktopMenuRouteShellAction, &'static str, &'static str)> {
        let mut specs = vec![(
            DesktopMenuRouteShellAction::CloseModsBrowserSelection,
            "@back",
            "left",
        )];
        if self.mods_route_mod_repo_at_index(index).is_some() {
            let (install_action, install_label) =
                if self.mods_browser_entry_installed_like_java(index) {
                    (
                        DesktopMenuRouteShellAction::ModsBrowserReinstall(index),
                        "@mods.browser.reinstall",
                    )
                } else {
                    (
                        DesktopMenuRouteShellAction::ModsBrowserAdd(index),
                        "@mods.browser.add",
                    )
                };
            specs.push((install_action, install_label, "download"));
            specs.push((
                DesktopMenuRouteShellAction::ModsBrowserOpenGithub(index),
                "@mods.github.open",
                "link",
            ));
            specs.push((
                DesktopMenuRouteShellAction::ModsBrowserViewReleases(index),
                "@mods.browser.view-releases",
                "zoom",
            ));
        } else {
            specs.push((
                DesktopMenuRouteShellAction::ModsBrowserAdd(index),
                "@mods.browser.add",
                "download",
            ));
        }
        specs
    }

    fn mods_browser_releases_action_at_point(
        &self,
        panel: RenderRect,
        point: RenderPoint,
    ) -> Option<DesktopMenuRouteShellAction> {
        self.mods_browser_releases_dialog_index?;
        let browser = Self::mods_browser_dialog_rect_for_panel(panel);
        let dialog = Self::mods_browser_releases_dialog_rect_for_browser(browser);
        if Self::schematic_info_button_rect(dialog, 0).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::ModsBrowserCloseReleases);
        }
        let capacity = Self::mods_browser_release_visible_entry_capacity_for_dialog(dialog);
        let start = self
            .mods_browser_releases_scroll_offset
            .min(self.max_mods_browser_releases_scroll_offset(dialog));
        for (visible_index, release_index) in (start..self.mods_browser_release_entries.len())
            .take(capacity)
            .enumerate()
        {
            let entry = Self::mods_browser_release_entry_rect_for_dialog(dialog, visible_index);
            if Self::mods_browser_release_button_rect(entry, 0).contains_point(point) {
                return Some(DesktopMenuRouteShellAction::ModsBrowserOpenRelease(
                    release_index,
                ));
            }
            if Self::mods_browser_release_button_rect(entry, 1).contains_point(point) {
                return Some(DesktopMenuRouteShellAction::ModsBrowserInstallRelease(
                    release_index,
                ));
            }
        }
        None
    }

    fn mods_browser_selection_action_at_point(
        &self,
        panel: RenderRect,
        point: RenderPoint,
    ) -> Option<DesktopMenuRouteShellAction> {
        let index = self.mods_browser_selected_mod_index?;
        let browser = Self::mods_browser_dialog_rect_for_panel(panel);
        let dialog = Self::mods_browser_selection_dialog_rect_for_browser(browser);
        let specs = self.mods_browser_selection_button_specs(index);
        for (button_index, (action, _, _)) in specs.iter().enumerate() {
            if Self::mods_browser_selection_button_rect_for_browser(
                browser,
                dialog,
                button_index,
                specs.len(),
            )
            .contains_point(point)
            {
                return Some(*action);
            }
        }
        None
    }

    fn mods_browser_action_at_point(
        &self,
        panel: RenderRect,
        point: RenderPoint,
    ) -> Option<DesktopMenuRouteShellAction> {
        if !self.mods_browser_dialog_open {
            return None;
        }
        if self.mods_browser_releases_dialog_index.is_some() {
            return self.mods_browser_releases_action_at_point(panel, point);
        }
        if self.mods_browser_selected_mod_index.is_some() {
            return self.mods_browser_selection_action_at_point(panel, point);
        }
        let dialog = Self::mods_browser_dialog_rect_for_panel(panel);
        if Self::mods_browser_search_rect_for_dialog(dialog).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::FocusModsBrowserSearch);
        }
        if Self::mods_browser_sort_button_rect_for_dialog(dialog).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::ToggleModsBrowserSort);
        }
        if Self::schematic_info_button_rect(dialog, 0).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::CloseModsBrowser);
        }
        let list = Self::mods_browser_list_rect_for_dialog(dialog);
        for (visible_index, mod_index) in self
            .filtered_mods_browser_indices()
            .into_iter()
            .skip(
                self.mods_browser_scroll_offset
                    .min(self.max_mods_browser_scroll_offset(list)),
            )
            .take(Self::mods_browser_visible_entry_capacity_for_list(list))
            .enumerate()
        {
            let entry = Self::mods_browser_entry_rect_for_list(list, visible_index);
            if entry.contains_point(point) {
                return Some(DesktopMenuRouteShellAction::OpenModsBrowserSelection(
                    mod_index,
                ));
            }
        }
        None
    }

    fn mods_import_action_at_point(
        &self,
        panel: RenderRect,
        point: RenderPoint,
    ) -> Option<DesktopMenuRouteShellAction> {
        if !self.mods_import_dialog_open {
            return None;
        }
        let dialog = Self::mods_import_dialog_rect_for_panel(panel);
        if Self::mods_import_option_button_rect(dialog, 0).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::ModsImportFile);
        }
        if Self::mods_import_option_button_rect(dialog, 1).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::ModsImportGithub);
        }
        if Self::mods_import_close_button_rect(dialog).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::CloseModsImport);
        }
        None
    }

    fn mods_import_github_action_at_point(
        &self,
        panel: RenderRect,
        point: RenderPoint,
    ) -> Option<DesktopMenuRouteShellAction> {
        if !self.mods_import_github_dialog_open {
            return None;
        }
        let dialog = Self::mods_import_github_dialog_rect_for_panel(panel);
        if Self::mods_import_github_text_rect_for_dialog(dialog).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::FocusModsImportGithubText);
        }
        if Self::mods_import_github_button_rect_for_dialog(dialog, 0).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::CancelModsImportGithub);
        }
        if Self::mods_import_github_button_rect_for_dialog(dialog, 1).contains_point(point) {
            return Some(DesktopMenuRouteShellAction::ConfirmModsImportGithub);
        }
        None
    }

