    fn push_mods_browser_selection_dialog(&self, pass: &mut RenderPass, panel: RenderRect) {
        let Some(index) = self.mods_browser_selected_mod_index else {
            return;
        };
        let Some(mod_name) = self.mods_route_mod_name_at_index(index) else {
            return;
        };
        let browser = Self::mods_browser_dialog_rect_for_panel(panel);
        let dialog = Self::mods_browser_selection_dialog_rect_for_browser(browser);
        let meta = self.mods_route_mod_meta_at_index(index);
        let description = self.mods_browser_selection_description_at_index(index);
        let author = meta
            .and_then(|meta| meta.author.as_deref())
            .map(str::trim)
            .filter(|author| !author.is_empty())
            .unwrap_or_default();
        let mut details = description;
        if !author.is_empty() {
            if !details.is_empty() {
                details.push_str("\n\n");
            }
            details.push_str("[accent]");
            details.push_str(&self.localize_bundle_markup_text("@editor.author"));
            details.push_str("[lightgray] ");
            details.push_str(author);
        }
        let specs = self.mods_browser_selection_button_specs(index);
        let mut layout = DialogShellLayout::from_stage_and_panel(browser, dialog);
        layout.stage_layer = Layer::END_PIXELED + 0.109;
        layout.panel_layer = Layer::END_PIXELED + 0.1095;
        layout.accent_layer = Layer::END_PIXELED + 0.1096;
        layout.title_layer = Layer::END_PIXELED + 0.1097;
        let base_dialog = BaseDialog::new(mod_name.to_string());
        for command in base_dialog.shell_render_commands(layout) {
            pass.push(command);
        }
        let details_pane = Self::mods_browser_selection_details_pane_rect_for_browser(
            browser,
            dialog,
            specs.len(),
        );
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            details_pane,
            [1.0, 1.0, 1.0, 0.78],
            0.0,
            Layer::END_PIXELED + 0.10975,
        ));
        let detail_wrap_width: f32 = if browser.height > browser.width {
            400.0
        } else {
            500.0
        };
        pass.push(RenderCommand::draw_text_styled(
            details,
            RenderPoint::new(
                details_pane.x + 4.0,
                details_pane.y + details_pane.height - 18.0,
            ),
            [0.72, 0.80, 0.86, 1.0],
            SETTINGS_JAVA_DEFAULT_FONT_SIZE,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Top)
                .with_integer_position(true)
                .with_wrap_width(detail_wrap_width.min((details_pane.width - 8.0).max(0.0))),
            Layer::END_PIXELED + 0.1098,
        ));
        for (button_index, (_, label, icon)) in specs.iter().enumerate() {
            self.push_settings_text_button(
                pass,
                Self::mods_browser_selection_button_rect_for_browser(
                    browser,
                    dialog,
                    button_index,
                    specs.len(),
                ),
                self.localize_bundle_markup_text(label),
                Some(icon),
                Layer::END_PIXELED + 0.110 + button_index as f32 * 0.0001,
            );
        }
    }

    fn push_mods_browser_releases_dialog(&self, pass: &mut RenderPass, panel: RenderRect) {
        if self.mods_browser_releases_dialog_index.is_none() {
            return;
        };
        let browser = Self::mods_browser_dialog_rect_for_panel(panel);
        let dialog = Self::mods_browser_releases_dialog_rect_for_browser(browser);
        let mut layout = DialogShellLayout::from_stage_and_panel(browser, dialog);
        layout.stage_layer = Layer::END_PIXELED + 0.111;
        layout.panel_layer = Layer::END_PIXELED + 0.112;
        layout.accent_layer = Layer::END_PIXELED + 0.113;
        layout.title_layer = Layer::END_PIXELED + 0.114;
        let base_dialog =
            BaseDialog::new(self.localize_bundle_markup_text("@mods.browser.releases"));
        for command in base_dialog.shell_render_commands(layout) {
            pass.push(command);
        }

        if self.mods_browser_release_entries.is_empty() {
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@mods.browser.fetching"),
                dialog.center(),
                [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
                SETTINGS_JAVA_DEFAULT_FONT_SIZE,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.115,
            ));
        } else {
            let scroll_offset = self
                .mods_browser_releases_scroll_offset
                .min(self.max_mods_browser_releases_scroll_offset(dialog));
            let capacity = Self::mods_browser_release_visible_entry_capacity_for_dialog(dialog);
            for (visible_index, (release_index, release)) in self
                .mods_browser_release_entries
                .iter()
                .enumerate()
                .skip(scroll_offset)
                .take(capacity)
                .enumerate()
            {
                let entry = Self::mods_browser_release_entry_rect_for_dialog(dialog, visible_index);
                pass.push(RenderCommand::draw_sprite(
                    "whiteui",
                    entry,
                    [
                        Pal::DARKEST_GRAY.r,
                        Pal::DARKEST_GRAY.g,
                        Pal::DARKEST_GRAY.b,
                        1.0,
                    ],
                    0.0,
                    Layer::END_PIXELED + 0.115 + visible_index as f32 * 0.001,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    if release_index == 0 {
                        format!(
                            "{} {}",
                            release.name,
                            self.localize_bundle_markup_text("@mods.browser.latest")
                        )
                    } else {
                        release.name.clone()
                    },
                    RenderPoint::new(entry.x + 12.0, entry.y + entry.height - 18.0),
                    [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
                    SETTINGS_JAVA_DEFAULT_FONT_SIZE,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_wrap_width((entry.width - 340.0).max(120.0)),
                    Layer::END_PIXELED + 0.117 + visible_index as f32 * 0.001,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    release.published_at.clone(),
                    RenderPoint::new(entry.x + 12.0, entry.y + 18.0),
                    [0.58, 0.68, 0.76, 1.0],
                    SETTINGS_JAVA_DEFAULT_FONT_SIZE,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true),
                    Layer::END_PIXELED + 0.1175 + visible_index as f32 * 0.001,
                ));
                for (button_index, (label, icon)) in [
                    ("@mods.github.open-release", "link"),
                    ("@mods.browser.add", "download"),
                ]
                .into_iter()
                .enumerate()
                {
                    self.push_settings_text_button(
                        pass,
                        Self::mods_browser_release_button_rect(entry, button_index),
                        self.localize_bundle_markup_text(label),
                        Some(icon),
                        Layer::END_PIXELED
                            + 0.118
                            + visible_index as f32 * 0.001
                            + button_index as f32 * 0.0001,
                    );
                }
            }
        }
        self.push_settings_text_button(
            pass,
            Self::schematic_info_button_rect(dialog, 0),
            self.localize_bundle_markup_text("@back"),
            Some("left"),
            Layer::END_PIXELED + 0.126,
        );
    }

