    fn push_mods_route_page(
        &self,
        pass: &mut RenderPass,
        viewport: RenderViewport,
        panel: RenderRect,
    ) {
        self.push_settings_text_button(
            pass,
            Self::route_back_button_rect_for_panel(panel),
            self.localize_bundle_markup_text("@back"),
            Some("left"),
            Layer::END_PIXELED + 0.024,
        );
        let footer_button_specs = self.mods_route_footer_button_specs();
        for (index, (_, label, icon)) in footer_button_specs.iter().enumerate() {
            self.push_settings_text_button(
                pass,
                Self::mods_route_footer_button_rect_for_panel_with_count(
                    panel,
                    index,
                    footer_button_specs.len(),
                ),
                self.localize_bundle_markup_text(label),
                Some(icon),
                Layer::END_PIXELED + 0.0245 + index as f32 * 0.001,
            );
        }

        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@mods"),
            RenderPoint::new(panel.x + 28.0, panel.y + panel.height - 58.0),
            [0.72, 0.82, 0.9, 1.0],
            MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_wrap_width(panel.width - 56.0),
            Layer::END_PIXELED + 0.025,
        ));

        if self.mods_route_requires_reload() {
            pass.push(RenderCommand::draw_text_styled(
                self.mods_route_localize_status_bundle_text("@mod.reloadrequired"),
                RenderPoint::new(panel.center().x, panel.y + panel.height - 92.0),
                [1.0, 0.48, 0.42, 1.0],
                MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.0255,
            ));
        }

        let main_button_specs = self.mods_route_main_button_specs();
        for (index, (_, label, icon)) in main_button_specs.iter().enumerate() {
            self.push_settings_text_button_with_style(
                pass,
                Self::mods_route_action_button_rect_for_panel_with_count(
                    panel,
                    index,
                    main_button_specs.len(),
                ),
                self.localize_bundle_markup_text(label),
                Some(icon),
                Layer::END_PIXELED + 0.026 + index as f32 * 0.001,
                "flatBordert",
            );
        }

        let search_visible = self.mods_route_search_visible_for_viewport(viewport);
        let search = Self::mods_route_search_rect_for_panel(panel);
        if search_visible {
            pass.push(RenderCommand::draw_sprite(
                Self::settings_text_field_background_symbol(),
                search,
                if self.mods_search_focused {
                    [1.0, 1.0, 1.0, 0.98]
                } else {
                    [1.0, 1.0, 1.0, 0.96]
                },
                0.0,
                Layer::END_PIXELED + 0.027,
            ));
            pass.push(RenderCommand::draw_text_styled(
                desktop_ui_icon_glyph_or_label("zoom", "zoom"),
                RenderPoint::new(search.x + 22.0, search.center().y),
                [0.72, 0.82, 0.9, 1.0],
                MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_font(RenderFontId::Icon)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.028,
            ));
            pass.push(RenderCommand::draw_text_styled(
                if self.mods_search.is_empty() {
                    self.localize_bundle_markup_text("@search")
                } else {
                    self.mods_search.clone()
                },
                RenderPoint::new(search.x + 44.0, search.center().y),
                if self.mods_search.is_empty() {
                    [0.60, 0.70, 0.78, 1.0]
                } else {
                    [0.90, 0.96, 1.0, 1.0]
                },
                MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.028,
            ));
        }

        if let Some(result) = self
            .last_mods_delete_result
            .as_ref()
            .filter(|result| !result.deleted)
        {
            pass.push(RenderCommand::draw_text_styled(
                format!(
                    "{}: {}",
                    self.mods_route_localize_status_bundle_text("@mod.delete.error"),
                    result.name
                ),
                RenderPoint::new(
                    panel.center().x,
                    if search_visible {
                        search.y - 18.0
                    } else {
                        panel.y + panel.height - 154.0
                    },
                ),
                [1.0, 0.50, 0.46, 1.0],
                MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.0285,
            ));
        }

        if self.last_mods_directory_mod_names.is_empty() {
            let empty = Self::mods_route_empty_state_rect_for_panel(panel);
            pass.push(RenderCommand::draw_sprite(
                Self::settings_drawable_symbol("black6"),
                empty,
                [1.0, 1.0, 1.0, 0.76],
                0.0,
                Layer::END_PIXELED + 0.026,
            ));
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@mods.none"),
                RenderPoint::new(panel.center().x, empty.center().y),
                [0.78, 0.86, 0.92, 1.0],
                MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.027,
            ));
        } else {
            let filtered_indices = self.filtered_mods_route_indices();
            if filtered_indices.is_empty() {
                pass.push(RenderCommand::draw_text_styled(
                    self.localize_bundle_markup_text("@none.found"),
                    RenderPoint::new(panel.center().x, panel.y + panel.height - 228.0),
                    [0.70, 0.78, 0.84, 1.0],
                    MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true),
                    Layer::END_PIXELED + 0.029,
                ));
            }
            let visible_capacity = Self::mods_route_visible_card_capacity_for_panel(panel);
            let mut disabled_separator_drawn = false;
            for (visible_index, index) in filtered_indices
                .into_iter()
                .take(visible_capacity)
                .enumerate()
            {
                let card = Self::mods_route_mod_card_rect_for_panel(panel, visible_index);
                let icon = Self::mods_route_mod_card_icon_rect(card);
                let text_x = icon.right() + 10.0;
                let text_width =
                    (card.right() - text_x - MODS_ROUTE_MOD_CARD_ACTION_SIZE * 2.0 - 16.0)
                        .max(120.0);
                let projection = self.mods_route_mod_card_projection(index, text_width);
                let enabled = projection.enabled;
                let supported = projection.supported;
                let has_steam_id = projection.has_steam_id;
                if !enabled
                    && !disabled_separator_drawn
                    && !self.last_mods_directory_mod_names.is_empty()
                {
                    disabled_separator_drawn = true;
                    pass.push(RenderCommand::fill_rect(
                        Self::mods_route_disabled_separator_rect_for_card(card),
                        [Pal::GRAY.r, Pal::GRAY.g, Pal::GRAY.b, 1.0],
                        Layer::END_PIXELED + 0.0295 + visible_index as f32 * 0.001,
                    ));
                }
                pass.push(RenderCommand::draw_sprite(
                    Self::settings_text_button_symbol("grayt", false, false),
                    card,
                    [1.0, 1.0, 1.0, 0.84],
                    0.0,
                    Layer::END_PIXELED + 0.030 + visible_index as f32 * 0.001,
                ));
                pass.push(RenderCommand::draw_sprite(
                    projection.icon_symbol.clone(),
                    icon,
                    [1.0, 1.0, 1.0, 0.78],
                    0.0,
                    Layer::END_PIXELED + 0.0305 + visible_index as f32 * 0.001,
                ));
                pass.push(RenderCommand::stroke_rect(
                    icon,
                    [0.56, 0.72, 0.86, 0.88],
                    1.0,
                    Layer::END_PIXELED + 0.0306 + visible_index as f32 * 0.001,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    projection.title,
                    RenderPoint::new(text_x, card.y + card.height - 26.0),
                    [0.94, 0.98, 1.0, 1.0],
                    MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true),
                    Layer::END_PIXELED + 0.031 + visible_index as f32 * 0.001,
                ));
                if let Some(short_description) = projection.short_description {
                    pass.push(RenderCommand::draw_text_styled(
                        short_description,
                        RenderPoint::new(text_x, card.y + card.height - 50.0),
                        [0.72, 0.82, 0.9, 1.0],
                        MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Start)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true)
                            .with_wrap_width(text_width),
                        Layer::END_PIXELED + 0.032 + visible_index as f32 * 0.001,
                    ));
                }
                if let Some(state_text) = projection.state_text {
                    pass.push(RenderCommand::draw_text_styled(
                        state_text,
                        RenderPoint::new(text_x, card.y + 30.0),
                        [0.84, 0.74, 0.66, 1.0],
                        MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Start)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true)
                            .with_wrap_width(text_width),
                        Layer::END_PIXELED + 0.033 + visible_index as f32 * 0.001,
                    ));
                }
                for (button_index, (icon, actionable)) in [
                    (if enabled { "down" } else { "up" }, supported),
                    (if has_steam_id { "link" } else { "trash" }, true),
                ]
                .into_iter()
                .enumerate()
                {
                    let button = Self::mods_route_mod_card_action_button_rect(card, button_index);
                    let button_hovered = actionable
                        && self
                            .last_menu_cursor
                            .is_some_and(|cursor| button.contains_point(cursor));
                    pass.push(RenderCommand::draw_sprite(
                        Self::settings_image_button_symbol("clearNonei", button_hovered, false),
                        button,
                        if actionable {
                            [1.0, 1.0, 1.0, 0.76]
                        } else {
                            [0.58, 0.62, 0.66, 0.58]
                        },
                        0.0,
                        Layer::END_PIXELED + 0.033 + visible_index as f32 * 0.001,
                    ));
                    pass.push(RenderCommand::draw_text_styled(
                        desktop_ui_icon_glyph_or_label(icon, icon),
                        RenderPoint::new(button.center().x, button.center().y + 4.0),
                        Self::settings_image_button_image_color(
                            "clearNonei",
                            button_hovered,
                            false,
                            false,
                            actionable,
                        ),
                        MODS_ROUTE_FONT_SIZE_LIKE_JAVA,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Center)
                            .with_font(RenderFontId::Icon)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true),
                        Layer::END_PIXELED + 0.0335 + visible_index as f32 * 0.001,
                    ));
                }
            }
        }

        self.push_mods_detail_dialog(pass, panel);
        self.push_mods_content_dialog(pass, panel);
        self.push_mods_delete_confirm_dialog(pass, panel);
        self.push_mods_import_dialog(pass, panel);
        self.push_mods_import_github_dialog(pass, panel);
        self.push_mods_browser_dialog(pass, panel);
        let viewport = pass.viewport.unwrap_or_else(|| {
            RenderViewport::new(
                panel.x,
                panel.y,
                panel.width.max(1.0),
                panel.height.max(1.0),
            )
        });
        self.push_mods_import_github_error_dialog(pass, viewport);
        self.push_mods_directory_error_dialog(pass, viewport);
        self.push_mods_import_github_loadfrag_overlay(pass, viewport);
    }

    fn active_menu_route_shell_cache_key(
        &self,
        route: DesktopMenuRoute,
        viewport: RenderViewport,
    ) -> DesktopActiveMenuRouteShellCacheKey {
        DesktopActiveMenuRouteShellCacheKey {
            route,
            viewport_x: viewport.x,
            viewport_y: viewport.y,
            viewport_width: viewport.width,
            viewport_height: viewport.height,
            title: self.localized_active_menu_route_title(route),
        }
    }

    fn push_cached_active_menu_route_shell_commands(
        &self,
        pass: &mut RenderPass,
        route: DesktopMenuRoute,
        viewport: RenderViewport,
        panel: RenderRect,
    ) {
        let key = self.active_menu_route_shell_cache_key(route, viewport);
        if let Some(cache) = self.active_menu_route_shell_cache.borrow().as_ref() {
            if cache.key == key {
                pass.commands.reserve(cache.commands.len());
                pass.commands.extend(cache.commands.iter().cloned());
                return;
            }
        }

        let dialog = BaseDialog::new(key.title.clone());
        let stage_rect = RenderRect::new(viewport.x, viewport.y, viewport.width, viewport.height);
        let commands = dialog
            .shell_render_commands(DialogShellLayout::from_stage_and_panel(stage_rect, panel));
        pass.commands.reserve(commands.len());
        pass.commands.extend(commands.iter().cloned());
        *self.active_menu_route_shell_cache.borrow_mut() =
            Some(DesktopActiveMenuRouteShellCache { key, commands });
        self.active_menu_route_shell_cache_rebuilds.set(
            self.active_menu_route_shell_cache_rebuilds
                .get()
                .saturating_add(1),
        );
    }

    fn push_campaign_route_page(&self, pass: &mut RenderPass, panel: RenderRect) {
        let dialog = self
            .campaign_planet_dialog
            .as_ref()
            .cloned()
            .unwrap_or_else(|| {
                CampaignPlanetDialogState::look(&self.content_loader, &self.game_state)
            });
        let selected = dialog
            .selected_sector_id
            .and_then(|id| self.campaign_sector_preset_by_id(&dialog.planet_name, id))
            .or_else(|| self.content_loader.sector_by_name("groundZero"));
        let planet_label = self
            .content_loader
            .catalog()
            .planet_by_name(&dialog.planet_name)
            .map(|planet| planet.localized_name().to_string())
            .unwrap_or_else(|| dialog.planet_name.clone());
        let sector_name = selected
            .map(|sector| sector.name.clone())
            .unwrap_or_else(|| "unknown".into());
        let status_label = match dialog.mode {
            CampaignPlanetDialogMode::Look => None,
            CampaignPlanetDialogMode::Select => {
                Some(self.localize_bundle_markup_text("@sectors.select"))
            }
            CampaignPlanetDialogMode::PlanetLaunch => {
                Some(self.localize_bundle_markup_text("@sectors.launchselect"))
            }
        };
        let selector_ids = self.campaign_route_sector_selector_ids(&dialog);
        let runtime_sector = self.campaign_selected_runtime_sector(&dialog, selected);
        let sector_panel_lines =
            self.campaign_sector_selected_panel_lines_like_java(&dialog, selected, runtime_sector);
        let stats_label = self.localize_bundle_markup_text("@stats");
        let show_stats_button =
            runtime_sector.is_some_and(|sector| sector.has_base(Default::default()));
        let submission_link =
            self.campaign_sector_submission_link_for_selection(&dialog, selected, runtime_sector);
        let submission_label = self.localize_bundle_markup_text("@sectors.viewsubmission");

        let planet_card = Self::campaign_route_planet_card_rect(panel);
        pass.push(RenderCommand::fill_rect(
            planet_card,
            [0.030, 0.052, 0.070, 0.88],
            Layer::END_PIXELED + 0.020,
        ));
        pass.push(RenderCommand::draw_sprite(
            "button.9",
            planet_card,
            [1.0, 1.0, 1.0, 0.62],
            0.0,
            Layer::END_PIXELED + 0.021,
        ));
        pass.push(RenderCommand::stroke_rect(
            planet_card,
            [0.28, 0.52, 0.62, 0.86],
            1.0,
            Layer::END_PIXELED + 0.022,
        ));
        self.push_campaign_planet_renderer_plan(pass, planet_card, &dialog);
        pass.push(RenderCommand::draw_text_styled(
            planet_label.clone(),
            RenderPoint::new(
                planet_card.x + planet_card.width * 0.58,
                planet_card.y + planet_card.height * 0.68,
            ),
            [0.94, 0.98, 1.0, 1.0],
            22.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_outline(true)
                .with_integer_position(true),
            Layer::END_PIXELED + 0.026,
        ));

        let sector_card = Self::campaign_route_sector_card_rect(panel);
        pass.push(RenderCommand::fill_rect(
            sector_card,
            [0.055, 0.075, 0.092, 0.92],
            Layer::END_PIXELED + 0.030,
        ));
        pass.push(RenderCommand::draw_sprite(
            "button.9",
            sector_card,
            [1.0, 1.0, 1.0, 0.70],
            0.0,
            Layer::END_PIXELED + 0.031,
        ));
        pass.push(RenderCommand::stroke_rect(
            sector_card,
            [0.50, 0.70, 0.82, 0.92],
            1.0,
            Layer::END_PIXELED + 0.032,
        ));
        if let Some((source, tint)) =
            self.campaign_sector_large_icon_source_like_java(&dialog, selected, runtime_sector)
        {
            self.push_large_icon_source_like_java(
                pass,
                &source,
                Self::campaign_route_sector_large_icon_rect(sector_card),
                tint,
                Layer::END_PIXELED + 0.0325,
            );
        }
        pass.push(RenderCommand::draw_text_styled(
            sector_name.clone(),
            RenderPoint::new(
                sector_card.x + 24.0,
                sector_card.y + sector_card.height - 26.0,
            ),
            [0.96, 0.99, 1.0, 1.0],
            16.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_outline(true)
                .with_integer_position(true),
            Layer::END_PIXELED + 0.033,
        ));
        if let Some(status_label) = status_label {
            pass.push(RenderCommand::draw_text_styled(
                status_label,
                RenderPoint::new(sector_card.x + 24.0, sector_card.y + 10.0),
                [0.68, 0.78, 0.86, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.034,
            ));
        }
        for (index, line) in sector_panel_lines.iter().take(4).enumerate() {
            pass.push(RenderCommand::draw_text_styled(
                line.clone(),
                RenderPoint::new(
                    sector_card.x + 24.0,
                    sector_card.y + sector_card.height - 46.0 - index as f32 * 13.0,
                ),
                [0.72, 0.84, 0.90, 1.0],
                9.5,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.0345 + index as f32 * 0.0001,
            ));
        }
        if show_stats_button {
            self.push_settings_text_button_with_style(
                pass,
                Self::campaign_route_stats_button_rect(sector_card),
                stats_label,
                Some("info"),
                Layer::END_PIXELED + 0.0348,
                "cleart",
            );
        }
        if let Some((hover_label, hover_font, hover_color, hover_position)) =
            self.campaign_hovered_sector_projected_label_like_java(&dialog, planet_card)
        {
            pass.push(RenderCommand::draw_text_styled(
                hover_label,
                hover_position,
                hover_color,
                14.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_font(hover_font)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_outline(true)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.0349,
            ));
        }
        if submission_link.is_some() {
            self.push_settings_text_button_with_style(
                pass,
                Self::campaign_route_submission_button_rect(panel),
                submission_label,
                Some("link"),
                Layer::END_PIXELED + 0.0349,
                "cleart",
            );
        }
        for (index, selector_sector_id) in selector_ids.iter().copied().enumerate() {
            let rect =
                Self::campaign_route_sector_selector_button_rect(panel, index, selector_ids.len());
            let selected_button = Some(selector_sector_id) == dialog.selected_sector_id;
            pass.push(RenderCommand::draw_sprite(
                "button.9",
                rect,
                if selected_button {
                    [0.42, 0.74, 0.86, 0.86]
                } else {
                    [0.20, 0.28, 0.34, 0.70]
                },
                0.0,
                Layer::END_PIXELED + 0.035,
            ));
            pass.push(RenderCommand::stroke_rect(
                rect,
                if selected_button {
                    [0.82, 0.96, 1.0, 0.98]
                } else {
                    [0.38, 0.52, 0.60, 0.76]
                },
                1.0,
                Layer::END_PIXELED + 0.036,
            ));
            pass.push(RenderCommand::draw_text_styled(
                format!("#{selector_sector_id}"),
                rect.center(),
                if selected_button {
                    [0.98, 1.0, 1.0, 1.0]
                } else {
                    [0.70, 0.82, 0.88, 1.0]
                },
                10.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_outline(true)
                    .with_integer_position(true),
                Layer::END_PIXELED + 0.037,
            ));
        }

        if dialog.mode != CampaignPlanetDialogMode::Select {
            for (index, planet_name) in self
                .campaign_selectable_planet_names_like_java(&dialog)
                .iter()
                .enumerate()
            {
                let Some(planet) = self.content_loader.catalog().planet_by_name(planet_name) else {
                    continue;
                };
                let rect = Self::campaign_route_planet_button_rect(panel, index);
                let selected_planet = planet.name() == dialog.planet_name;
                let mut planet_color = rgba8888_to_render_color(planet.icon_color_rgba, 1.0);
                if !selected_planet {
                    planet_color[3] = 0.82;
                }
                pass.push(RenderCommand::draw_sprite(
                    Self::settings_text_button_symbol_checked(
                        "flatTogglet",
                        false,
                        false,
                        selected_planet,
                    ),
                    rect,
                    if selected_planet {
                        [0.82, 0.94, 1.0, 0.95]
                    } else {
                        [0.58, 0.66, 0.72, 0.76]
                    },
                    0.0,
                    Layer::END_PIXELED + 0.0391 + index as f32 * 0.0001,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    desktop_ui_icon_glyph_or_label(planet.meta.icon.as_str(), "planet"),
                    RenderPoint::new(rect.x + 22.0, rect.center().y),
                    planet_color,
                    11.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_font(RenderFontId::Icon)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true),
                    Layer::END_PIXELED + 0.0392 + index as f32 * 0.0001,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    planet.localized_name().to_string(),
                    RenderPoint::new(rect.x + 42.0, rect.center().y),
                    if selected_planet {
                        [0.98, 1.0, 1.0, 1.0]
                    } else {
                        [0.84, 0.90, 0.94, 0.92]
                    },
                    10.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.0393 + index as f32 * 0.0001,
                ));
            }
        }

        if self.campaign_rules_entry_visible(&dialog) {
            self.push_settings_text_button(
                pass,
                Self::campaign_route_rules_button_rect(panel),
                self.localize_bundle_markup_text("@campaign.difficulty"),
                Some("book"),
                Layer::END_PIXELED + 0.040,
            );
        }

        self.push_campaign_sector_list(pass, panel, &dialog);

        self.push_settings_text_button(
            pass,
            Self::campaign_route_secondary_button_rect(panel, 0),
            self.localize_bundle_markup_text("@back"),
            Some("left"),
            Layer::END_PIXELED + 0.038,
        );
        self.push_settings_text_button(
            pass,
            Self::campaign_route_secondary_button_rect(panel, 1),
            self.localize_bundle_markup_text("@techtree"),
            Some("tree"),
            Layer::END_PIXELED + 0.039,
        );
    }

    fn push_campaign_planet_renderer_plan(
        &self,
        pass: &mut RenderPass,
        planet_card: RenderRect,
        dialog: &CampaignPlanetDialogState,
    ) {
        let plan = self.campaign_route_planet_scene_plan(dialog, planet_card);
        pass.push(RenderCommand::custom(
            "planet-renderer-scene-plan",
            Self::campaign_planet_scene_plan_properties(&plan, planet_card, dialog),
        ));
        for (index, step) in plan.steps.iter().enumerate() {
            pass.push(RenderCommand::custom(
                "planet-renderer-scene-step",
                Self::campaign_planet_scene_step_properties(index, step),
            ));
        }
        self.push_campaign_planet_scene_preview(pass, planet_card, dialog, &plan);
    }

    fn campaign_hovered_sector_projected_label_like_java(
        &self,
        dialog: &CampaignPlanetDialogState,
        planet_card: RenderRect,
    ) -> Option<(String, RenderFontId, [f32; 4], RenderPoint)> {
        let sector_id = dialog.hovered_sector_id?;
        let preset = self.campaign_sector_preset_by_id(&dialog.planet_name, sector_id);
        let runtime = self.campaign_runtime_sector_by_id(&dialog.planet_name, sector_id);
        let (label, font, color) =
            self.campaign_sector_hover_label_like_java(dialog, preset, runtime)?;
        let plan = self.campaign_route_planet_scene_plan(dialog, planet_card);
        let position = self.campaign_planet_surface_sector_preview_point(
            &dialog.planet_name,
            sector_id,
            planet_card,
            &plan,
        )?;

        Some((label, font, color, position))
    }

    fn campaign_runtime_sector_projection_id_like_java(sector: &Sector) -> i32 {
        sector
            .preset
            .as_ref()
            .and_then(|preset| preset.sector_id)
            .unwrap_or(sector.id)
    }

    fn campaign_find_launcher_sector_id_like_java(
        &self,
        dialog: &CampaignPlanetDialogState,
        target_sector_id: i32,
    ) -> Option<i32> {
        if self
            .campaign_runtime_sector_by_id(&dialog.planet_name, target_sector_id)
            .is_some_and(|sector| sector.has_base(Default::default()))
        {
            return None;
        }

        [
            self.game_state.get_sector(),
            self.runtime.state.get_sector(),
        ]
        .into_iter()
        .flatten()
        .find(|sector| {
            sector.has_base(Default::default())
                && self.campaign_runtime_sector_matches_planet(sector, &dialog.planet_name)
        })
        .map(Self::campaign_runtime_sector_projection_id_like_java)
        .filter(|source_id| *source_id != target_sector_id)
    }

    fn campaign_sector_destination_matches_like_java(source: &Sector, target: &Sector) -> bool {
        let Some(destination) = source.info.destination.as_deref() else {
            return false;
        };
        let target_id = target.id.to_string();
        if destination == target_id {
            return true;
        }
        target.preset.as_ref().is_some_and(|preset| {
            let original_position = preset.original_position.to_string();
            preset
                .sector_id
                .is_some_and(|sector_id| destination == sector_id.to_string())
                || destination == original_position
        })
    }

    fn campaign_planet_campaign_rules_like_java(&self, planet_name: &str) -> CampaignRules {
        self.campaign_rules_by_planet
            .get(planet_name)
            .copied()
            .unwrap_or_default()
    }

    fn campaign_sector_snapshot_by_id_like_java(
        &self,
        planet_name: &str,
        sector_id: i32,
    ) -> Sector {
        if let Some(runtime) = self.campaign_runtime_sector_by_id(planet_name, sector_id) {
            return runtime.clone();
        }
        let mut sector = Sector::new(sector_id);
        sector.preset = self
            .campaign_sector_preset_by_id(planet_name, sector_id)
            .cloned();
        sector
    }

    fn campaign_planet_neighbor_sector_ids_like_java(
        &self,
        planet_name: &str,
        sector_id: i32,
    ) -> Vec<i32> {
        let Some(planet) = self.content_loader.catalog().planet_by_name(planet_name) else {
            return Vec::new();
        };
        let Some(sector_size) = planet.sector_size else {
            return Vec::new();
        };
        let Ok(sector_index) = usize::try_from(sector_id) else {
            return Vec::new();
        };
        let grid = PlanetGrid::create(sector_size);
        grid.tiles
            .get(sector_index)
            .into_iter()
            .flat_map(|tile| tile.tiles.iter().flatten().copied())
            .map(|id| id as i32)
            .collect()
    }

    fn campaign_sector_best_core_size_like_java(&self, sector: &Sector) -> i32 {
        self.content_loader
            .block_by_name(&sector.info.best_core_type)
            .map(|block| i32::from(block.base().size))
            .unwrap_or(0)
    }

    fn campaign_sector_allow_numbered_launch_like_java(
        &self,
        planet_name: &str,
        sector: &Sector,
    ) -> bool {
        if planet_name == "serpulo" {
            return sector.has_base(Default::default())
                && !sector.is_attacked(Default::default())
                && self.campaign_sector_best_core_size_like_java(sector) >= 4;
        }
        sector.has_base(Default::default())
    }

    fn campaign_sector_allow_landing_like_java(&self, planet_name: &str, sector_id: i32) -> bool {
        let Some(planet) = self.content_loader.catalog().planet_by_name(planet_name) else {
            return false;
        };
        if !planet.meta.allow_launch_to_numbered {
            return false;
        }
        let sector = self.campaign_sector_snapshot_by_id_like_java(planet_name, sector_id);
        if sector.has_base(Default::default()) {
            return true;
        }
        self.campaign_planet_neighbor_sector_ids_like_java(planet_name, sector_id)
            .into_iter()
            .any(|neighbor_id| {
                let neighbor =
                    self.campaign_sector_snapshot_by_id_like_java(planet_name, neighbor_id);
                self.campaign_sector_allow_numbered_launch_like_java(planet_name, &neighbor)
            })
    }

    fn campaign_planet_shield_arc_sector_pairs_like_java(
        &self,
        dialog: &CampaignPlanetDialogState,
    ) -> Vec<(i32, i32)> {
        let mut pairs = BTreeSet::new();
        for target_preset in self.content_loader.sectors().iter().filter(|preset| {
            preset.planet_name.as_deref() == Some(dialog.planet_name.as_str())
                && !preset.shield_sector_ids.is_empty()
        }) {
            let Some(target_id) = target_preset.sector_id else {
                continue;
            };
            let target =
                self.campaign_sector_snapshot_by_id_like_java(&dialog.planet_name, target_id);
            if target.is_captured(Default::default()) {
                continue;
            }
            for source_id in target_preset.shield_sector_ids.iter().copied() {
                let source =
                    self.campaign_sector_snapshot_by_id_like_java(&dialog.planet_name, source_id);
                if !source.is_captured(Default::default())
                    && (self
                        .campaign_sector_allow_landing_like_java(&dialog.planet_name, source_id)
                        || self.campaign_sector_allow_landing_like_java(
                            &dialog.planet_name,
                            target_id,
                        ))
                {
                    pairs.insert((source_id, target_id));
                }
            }
        }
        pairs.into_iter().collect()
    }

    fn campaign_planet_attack_arc_sector_pairs_like_java(
        &self,
        dialog: &CampaignPlanetDialogState,
    ) -> Vec<(i32, i32)> {
        if !self
            .campaign_planet_campaign_rules_like_java(&dialog.planet_name)
            .sector_invasion
        {
            return Vec::new();
        }

        let mut pairs = BTreeSet::new();
        for sector in self.campaign_sector_list_base_entries(dialog) {
            if !sector.has_base(Default::default()) {
                continue;
            }
            let target_id = Self::campaign_runtime_sector_projection_id_like_java(&sector);
            for enemy_id in
                self.campaign_planet_neighbor_sector_ids_like_java(&dialog.planet_name, target_id)
            {
                let enemy =
                    self.campaign_sector_snapshot_by_id_like_java(&dialog.planet_name, enemy_id);
                if enemy.has_enemy_base(Default::default())
                    && enemy
                        .preset
                        .as_ref()
                        .is_none_or(|preset| !preset.require_unlock)
                {
                    pairs.insert((enemy_id, target_id));
                }
            }
        }
        pairs.into_iter().collect()
    }

    fn campaign_push_planet_projected_sector_line_like_java(
        &self,
        pass: &mut RenderPass,
        planet_card: RenderRect,
        dialog: &CampaignPlanetDialogState,
        plan: &PlanetScenePlan,
        from_sector_id: i32,
        to_sector_id: i32,
        stroke: f32,
        color: [f32; 4],
        layer: f32,
    ) -> bool {
        let Some(from) = self.campaign_planet_surface_sector_preview_point(
            &dialog.planet_name,
            from_sector_id,
            planet_card,
            plan,
        ) else {
            return false;
        };
        let Some(to) = self.campaign_planet_surface_sector_preview_point(
            &dialog.planet_name,
            to_sector_id,
            planet_card,
            plan,
        ) else {
            return false;
        };

        pass.push(RenderCommand::draw_line(from, to, stroke, color, layer));
        true
    }

    fn push_campaign_planet_scene_preview(
        &self,
        pass: &mut RenderPass,
        planet_card: RenderRect,
        dialog: &CampaignPlanetDialogState,
        plan: &PlanetScenePlan,
    ) {
        let center = Self::campaign_planet_scene_preview_center(planet_card);
        let radius = Self::campaign_planet_scene_preview_radius(planet_card);

        for (index, step) in plan.steps.iter().enumerate() {
            let layer = Layer::END_PIXELED + 0.023 + index as f32 * 0.0001;
            match step {
                PlanetSceneStep::DrawSkybox(_) => {
                    for (star_index, (x, y)) in [
                        (0.12_f32, 0.70_f32),
                        (0.20_f32, 0.28_f32),
                        (0.41_f32, 0.83_f32),
                        (0.48_f32, 0.43_f32),
                    ]
                    .iter()
                    .copied()
                    .enumerate()
                    {
                        pass.push(RenderCommand::draw_pixel(
                            (planet_card.x + planet_card.width * x).round() as i32,
                            (planet_card.y + planet_card.height * y).round() as i32,
                            [0.70, 0.84, 0.92, 0.35 + star_index as f32 * 0.08],
                            layer,
                        ));
                    }
                }
                PlanetSceneStep::DrawPlanet { planet, transform } => {
                    let preview_center = Self::campaign_planet_scene_project_point(
                        planet_card,
                        plan,
                        [
                            transform.values[0][3],
                            transform.values[1][3],
                            transform.values[2][3],
                        ],
                    );
                    let preview_radius = self.campaign_planet_scene_preview_radius_for_planet(
                        planet,
                        &dialog.planet_name,
                        radius,
                    );
                    pass.push(RenderCommand::draw_circle(
                        preview_center,
                        preview_radius,
                        self.campaign_planet_scene_preview_color(planet, 0.96),
                        true,
                        layer,
                    ));
                }
                PlanetSceneStep::DrawClouds { planet, .. } if planet == &dialog.planet_name => {
                    pass.push(RenderCommand::draw_polygon(
                        center,
                        radius * 1.035,
                        40,
                        0.0,
                        [0.76, 0.88, 0.95, 0.30],
                        false,
                        layer,
                    ));
                }
                PlanetSceneStep::DrawSectors { planet } if planet == &dialog.planet_name => {
                    let sector_ids =
                        self.campaign_planet_projection_sector_ids_like_java(&dialog.planet_name);
                    for (sector_index, sector_id) in sector_ids.iter().copied().enumerate() {
                        let Some(marker) = self.campaign_planet_surface_sector_preview_point(
                            &dialog.planet_name,
                            sector_id,
                            planet_card,
                            plan,
                        ) else {
                            continue;
                        };
                        let selected = Some(sector_id) == dialog.selected_sector_id;
                        let hovered = Some(sector_id) == dialog.hovered_sector_id;
                        pass.push(RenderCommand::draw_circle(
                            marker,
                            if selected || hovered { 3.2 } else { 1.15 },
                            if hovered {
                                [1.00, 0.92, 0.45, 0.95]
                            } else if selected {
                                [0.55, 0.95, 1.00, 0.95]
                            } else {
                                [0.62, 0.78, 0.84, 0.30]
                            },
                            true,
                            layer + sector_index as f32 * 0.00001,
                        ));
                    }
                }
                PlanetSceneStep::RenderOverProjections { planet }
                    if planet == &dialog.planet_name =>
                {
                    let mut line_index = 0usize;
                    if let Some(target_sector_id) =
                        dialog.hovered_sector_id.or(dialog.selected_sector_id)
                    {
                        let preset = self
                            .campaign_sector_preset_by_id(&dialog.planet_name, target_sector_id);
                        let runtime = self
                            .campaign_runtime_sector_by_id(&dialog.planet_name, target_sector_id);
                        if !runtime.is_some_and(|sector| sector.has_base(Default::default()))
                            && self.campaign_sector_can_select_like_java(dialog, preset, runtime)
                        {
                            if let Some(source_sector_id) = self
                                .campaign_find_launcher_sector_id_like_java(
                                    dialog,
                                    target_sector_id,
                                )
                            {
                                if self.campaign_push_planet_projected_sector_line_like_java(
                                    pass,
                                    planet_card,
                                    dialog,
                                    plan,
                                    source_sector_id,
                                    target_sector_id,
                                    if Some(target_sector_id) == dialog.hovered_sector_id {
                                        1.5
                                    } else {
                                        1.0
                                    },
                                    if Some(target_sector_id) == dialog.hovered_sector_id {
                                        [1.00, 0.86, 0.36, 0.70]
                                    } else {
                                        [0.48, 0.90, 1.00, 0.56]
                                    },
                                    layer + line_index as f32 * 0.00001,
                                ) {
                                    line_index += 1;
                                }
                            }
                        }
                    }

                    if dialog.mode == CampaignPlanetDialogMode::PlanetLaunch
                        && dialog.hovered_sector_id.is_none()
                        && self.campaign_launch_sector_planet_name_like_java(dialog)
                            == Some(dialog.planet_name.as_str())
                    {
                        if let (Some(source_sector_id), Some(target_sector_id)) =
                            (dialog.launch_sector_id, dialog.selected_sector_id)
                        {
                            let _ = self.campaign_push_planet_projected_sector_line_like_java(
                                pass,
                                planet_card,
                                dialog,
                                plan,
                                source_sector_id,
                                target_sector_id,
                                1.25,
                                [0.72, 0.92, 1.00, 0.66],
                                layer + line_index as f32 * 0.00001,
                            );
                        }
                    }

                    for (source_sector_id, target_sector_id) in
                        self.campaign_planet_shield_arc_sector_pairs_like_java(dialog)
                    {
                        if self.campaign_push_planet_projected_sector_line_like_java(
                            pass,
                            planet_card,
                            dialog,
                            plan,
                            source_sector_id,
                            target_sector_id,
                            0.30,
                            rgba8888_to_render_color(0xf25555ff, 0.62),
                            layer + line_index as f32 * 0.00001,
                        ) {
                            line_index += 1;
                        }
                    }

                    for (enemy_sector_id, base_sector_id) in
                        self.campaign_planet_attack_arc_sector_pairs_like_java(dialog)
                    {
                        if self.campaign_push_planet_projected_sector_line_like_java(
                            pass,
                            planet_card,
                            dialog,
                            plan,
                            enemy_sector_id,
                            base_sector_id,
                            0.24,
                            rgba8888_to_render_color(0xf25555ff, 0.50),
                            layer + line_index as f32 * 0.00001,
                        ) {
                            line_index += 1;
                        }
                    }

                    if let Some(selected_sector) =
                        self.campaign_selected_runtime_sector(dialog, None)
                    {
                        if selected_sector.has_base(Default::default()) {
                            for sector in self.campaign_sector_list_base_entries(dialog) {
                                if sector.id == selected_sector.id {
                                    continue;
                                }
                                if Self::campaign_sector_destination_matches_like_java(
                                    &sector,
                                    selected_sector,
                                ) && sector.info.any_exports()
                                {
                                    if self.campaign_push_planet_projected_sector_line_like_java(
                                        pass,
                                        planet_card,
                                        dialog,
                                        plan,
                                        Self::campaign_runtime_sector_projection_id_like_java(
                                            &sector,
                                        ),
                                        Self::campaign_runtime_sector_projection_id_like_java(
                                            selected_sector,
                                        ),
                                        1.05,
                                        [0.58, 0.62, 0.66, 0.58],
                                        layer + line_index as f32 * 0.00001,
                                    ) {
                                        line_index += 1;
                                    }
                                }
                                if Self::campaign_sector_destination_matches_like_java(
                                    selected_sector,
                                    &sector,
                                ) && selected_sector.info.any_exports()
                                {
                                    if self.campaign_push_planet_projected_sector_line_like_java(
                                        pass,
                                        planet_card,
                                        dialog,
                                        plan,
                                        Self::campaign_runtime_sector_projection_id_like_java(
                                            selected_sector,
                                        ),
                                        Self::campaign_runtime_sector_projection_id_like_java(
                                            &sector,
                                        ),
                                        1.05,
                                        [0.68, 0.92, 0.76, 0.62],
                                        layer + line_index as f32 * 0.00001,
                                    ) {
                                        line_index += 1;
                                    }
                                }
                            }
                        }
                    }
                }
                PlanetSceneStep::RenderProjections { planet } if planet == &dialog.planet_name => {
                    let sector_ids =
                        self.campaign_planet_projection_sector_ids_like_java(&dialog.planet_name);
                    for (sector_index, sector_id) in sector_ids.iter().copied().enumerate() {
                        let Some(marker) = self.campaign_planet_surface_sector_preview_point(
                            &dialog.planet_name,
                            sector_id,
                            planet_card,
                            plan,
                        ) else {
                            continue;
                        };
                        let preset =
                            self.campaign_sector_preset_by_id(&dialog.planet_name, sector_id);
                        let runtime =
                            self.campaign_runtime_sector_by_id(&dialog.planet_name, sector_id);
                        if Some(sector_id) != dialog.hovered_sector_id {
                            let size = if Some(sector_id) == dialog.selected_sector_id {
                                6.0
                            } else {
                                3.6
                            };
                            let rect = RenderRect::from_center(marker, size, size);
                            if let Some((source, tint)) = self
                                .campaign_sector_large_icon_source_like_java(
                                    dialog, preset, runtime,
                                )
                            {
                                self.push_large_icon_source_like_java(
                                    pass,
                                    &source,
                                    rect,
                                    tint,
                                    layer + sector_index as f32 * 0.00001,
                                );
                            } else {
                                pass.push(RenderCommand::draw_sprite(
                                    "circle-shadow",
                                    rect,
                                    if Some(sector_id) == dialog.selected_sector_id {
                                        [0.58, 0.96, 1.00, 0.86]
                                    } else {
                                        [0.72, 0.84, 0.90, 0.30]
                                    },
                                    0.0,
                                    layer + sector_index as f32 * 0.00001,
                                ));
                            }
                        }
                        if self.campaign_debug_show_numbers {
                            let snapshot = self.campaign_sector_snapshot_by_id_like_java(
                                &dialog.planet_name,
                                sector_id,
                            );
                            if snapshot.has_enemy_base(Default::default())
                                || snapshot.preset.is_some()
                            {
                                pass.push(RenderCommand::draw_text_styled(
                                    sector_id.to_string(),
                                    marker,
                                    if snapshot.preset.is_none() {
                                        [1.0, 0.20, 0.20, 0.96]
                                    } else {
                                        [1.0, 1.0, 1.0, 0.96]
                                    },
                                    7.0,
                                    0.0,
                                    RenderTextStyle::new(RenderTextAlign::Center)
                                        .with_font(RenderFontId::Outline)
                                        .with_vertical_align(RenderTextVerticalAlign::Center),
                                    layer + 0.00005 + sector_index as f32 * 0.00001,
                                ));
                            }
                        }
                    }
                    if let Some(hovered_sector_id) = dialog.hovered_sector_id {
                        if let Some(marker) = self.campaign_planet_surface_sector_preview_point(
                            &dialog.planet_name,
                            hovered_sector_id,
                            planet_card,
                            plan,
                        ) {
                            let rect = RenderRect::from_center(marker, 9.0, 9.0);
                            let preset = self.campaign_sector_preset_by_id(
                                &dialog.planet_name,
                                hovered_sector_id,
                            );
                            let runtime = self.campaign_runtime_sector_by_id(
                                &dialog.planet_name,
                                hovered_sector_id,
                            );
                            if let Some((source, tint)) = self
                                .campaign_hovered_projection_icon_source_like_java(
                                    dialog, preset, runtime,
                                )
                            {
                                self.push_large_icon_source_like_java(
                                    pass,
                                    &source,
                                    rect,
                                    tint,
                                    layer + sector_ids.len() as f32 * 0.00001,
                                );
                            }
                        }
                    }
                }
                PlanetSceneStep::DrawAtmosphere { planet } if planet == &dialog.planet_name => {
                    pass.push(RenderCommand::draw_circle(
                        center,
                        radius * 1.17,
                        [0.34, 0.74, 0.92, 0.24],
                        false,
                        layer,
                    ));
                }
                PlanetSceneStep::DrawOrbit { planet, alpha, .. }
                    if planet == &dialog.planet_name =>
                {
                    pass.push(RenderCommand::draw_polygon(
                        center,
                        radius * 1.36,
                        64,
                        0.0,
                        [0.48, 0.72, 0.86, alpha * 0.24],
                        false,
                        layer,
                    ));
                }
                _ => {}
            }
        }
    }

    fn campaign_planet_scene_preview_center(planet_card: RenderRect) -> RenderPoint {
        RenderPoint::new(
            planet_card.x + planet_card.width * 0.28,
            planet_card.y + planet_card.height * 0.52,
        )
    }

    fn campaign_planet_scene_preview_radius(planet_card: RenderRect) -> f32 {
        planet_card.height.min(planet_card.width) * 0.28
    }

    fn campaign_planet_scene_surface_radius(planet_card: RenderRect) -> f32 {
        Self::campaign_planet_scene_preview_radius(planet_card) * PLANET_RENDERER_OUTLINE_RAD
    }

    fn campaign_planet_scene_project_point(
        planet_card: RenderRect,
        plan: &PlanetScenePlan,
        position: [f32; 3],
    ) -> RenderPoint {
        let center = Self::campaign_planet_scene_preview_center(planet_card);
        let radius = Self::campaign_planet_scene_preview_radius(planet_card);
        let scale = (radius * 0.18).max(1.0);
        RenderPoint::new(
            center.x + (position[0] - plan.camera.look_at[0]) * scale,
            center.y + (position[2] - plan.camera.look_at[2]) * scale,
        )
    }

    fn campaign_planet_scene_preview_radius_for_planet(
        &self,
        planet_name: &str,
        selected_planet_name: &str,
        selected_radius: f32,
    ) -> f32 {
        if planet_name == selected_planet_name {
            return selected_radius;
        }
        let selected_world_radius = self
            .content_loader
            .catalog()
            .planet_by_name(selected_planet_name)
            .map(|planet| planet.meta.radius)
            .unwrap_or(1.0)
            .max(0.001);
        let planet_world_radius = self
            .content_loader
            .catalog()
            .planet_by_name(planet_name)
            .map(|planet| planet.meta.radius)
            .unwrap_or(selected_world_radius);
        (selected_radius * (planet_world_radius / selected_world_radius) * 0.25)
            .clamp(selected_radius * 0.12, selected_radius * 0.36)
    }

    fn campaign_planet_scene_preview_color(&self, planet_name: &str, alpha: f32) -> [f32; 4] {
        let mut color = self
            .content_loader
            .catalog()
            .planet_by_name(planet_name)
            .map(|planet| rgba8888_to_render_color(planet.icon_color_rgba, alpha))
            .unwrap_or([0.35, 0.72, 0.86, alpha]);
        color[3] = alpha;
        color
    }

    fn campaign_planet_dialog_camera_position(
        &self,
        dialog: &CampaignPlanetDialogState,
    ) -> [f32; 3] {
        dialog
            .selected_sector_id
            .and_then(|sector_id| {
                self.campaign_planet_surface_sector_vector(&dialog.planet_name, sector_id)
            })
            .unwrap_or([0.0, 0.0, 1.0])
    }

    fn campaign_planet_surface_sector_preview_point(
        &self,
        planet_name: &str,
        sector_id: i32,
        planet_card: RenderRect,
        plan: &PlanetScenePlan,
    ) -> Option<RenderPoint> {
        let sector = self.campaign_planet_surface_sector_vector(planet_name, sector_id)?;
        let (right, up, normal) = Self::campaign_planet_scene_camera_basis(plan);
        if Self::campaign_vec3_dot(sector, normal) < 0.0 {
            return None;
        }

        let center = Self::campaign_planet_scene_preview_center(planet_card);
        let radius = Self::campaign_planet_scene_surface_radius(planet_card);
        Some(RenderPoint::new(
            center.x + Self::campaign_vec3_dot(sector, right) * radius,
            center.y - Self::campaign_vec3_dot(sector, up) * radius,
        ))
    }

    fn campaign_planet_surface_sector_id_at_surface_point(
        &self,
        panel: RenderRect,
        dialog: &CampaignPlanetDialogState,
        point: RenderPoint,
    ) -> Option<i32> {
        let planet_card = Self::campaign_route_planet_card_rect(panel);
        if !planet_card.contains_point(point) {
            return None;
        }

        let planet = self
            .content_loader
            .catalog()
            .planet_by_name(&dialog.planet_name)?;
        let sector_size = planet.sector_size?;
        let center = Self::campaign_planet_scene_preview_center(planet_card);
        let radius = Self::campaign_planet_scene_surface_radius(planet_card);
        let x = (point.x - center.x) / radius;
        let y = -(point.y - center.y) / radius;
        let dist2 = x * x + y * y;
        if dist2 > 1.0 {
            return None;
        }

        let plan = self.campaign_route_planet_scene_plan(dialog, planet_card);
        let (right, up, normal) = Self::campaign_planet_scene_camera_basis(&plan);
        let forward = (1.0 - dist2).sqrt();
        let pick = Self::campaign_vec3_normalize(Self::campaign_vec3_add(
            Self::campaign_vec3_add(
                Self::campaign_vec3_scale(right, x),
                Self::campaign_vec3_scale(up, y),
            ),
            Self::campaign_vec3_scale(normal, forward),
        ));

        let grid = PlanetGrid::create(sector_size);
        grid.tiles
            .iter()
            .max_by(|left, right| {
                Self::campaign_vec3_dot([left.v.x, left.v.y, left.v.z], pick)
                    .partial_cmp(&Self::campaign_vec3_dot(
                        [right.v.x, right.v.y, right.v.z],
                        pick,
                    ))
                    .unwrap()
            })
            .map(|tile| tile.id as i32)
    }

    fn campaign_planet_surface_sector_vector(
        &self,
        planet_name: &str,
        sector_id: i32,
    ) -> Option<[f32; 3]> {
        let planet = self.content_loader.catalog().planet_by_name(planet_name)?;
        let sector_size = planet.sector_size?;
        let grid = PlanetGrid::create(sector_size);
        grid.tiles
            .get(sector_id as usize)
            .map(|tile| [tile.v.x, tile.v.y, tile.v.z])
    }

    fn campaign_planet_scene_camera_basis(
        plan: &PlanetScenePlan,
    ) -> ([f32; 3], [f32; 3], [f32; 3]) {
        let normal = Self::campaign_vec3_normalize(Self::campaign_vec3_sub(
            plan.camera.position,
            plan.camera.look_at,
        ));
        let mut reference_up = [0.0, 1.0, 0.0];
        if Self::campaign_vec3_len(Self::campaign_vec3_cross(reference_up, normal)) < 0.0001 {
            reference_up = [0.0, 0.0, 1.0];
        }
        let right = Self::campaign_vec3_normalize(Self::campaign_vec3_cross(reference_up, normal));
        let up = Self::campaign_vec3_normalize(Self::campaign_vec3_cross(normal, right));
        (right, up, normal)
    }

    fn campaign_vec3_add(left: [f32; 3], right: [f32; 3]) -> [f32; 3] {
        [left[0] + right[0], left[1] + right[1], left[2] + right[2]]
    }

    fn campaign_vec3_sub(left: [f32; 3], right: [f32; 3]) -> [f32; 3] {
        [left[0] - right[0], left[1] - right[1], left[2] - right[2]]
    }

    fn campaign_vec3_scale(value: [f32; 3], scale: f32) -> [f32; 3] {
        [value[0] * scale, value[1] * scale, value[2] * scale]
    }

    fn campaign_vec3_dot(left: [f32; 3], right: [f32; 3]) -> f32 {
        left[0] * right[0] + left[1] * right[1] + left[2] * right[2]
    }

    fn campaign_vec3_cross(left: [f32; 3], right: [f32; 3]) -> [f32; 3] {
        [
            left[1] * right[2] - left[2] * right[1],
            left[2] * right[0] - left[0] * right[2],
            left[0] * right[1] - left[1] * right[0],
        ]
    }

    fn campaign_vec3_len(value: [f32; 3]) -> f32 {
        Self::campaign_vec3_dot(value, value).sqrt()
    }

    fn campaign_vec3_normalize(value: [f32; 3]) -> [f32; 3] {
        Self::campaign_vec3_scale(value, 1.0 / Self::campaign_vec3_len(value))
    }

    fn campaign_route_planet_scene_plan(
        &self,
        dialog: &CampaignPlanetDialogState,
        planet_card: RenderRect,
    ) -> PlanetScenePlan {
        let solar_system = self.campaign_route_solar_system_node(&dialog.planet_name);
        let mut params = PlanetRendererParams::new(dialog.planet_name.clone(), solar_system);
        params.view_w = planet_card.width.round().max(1.0) as i32;
        params.view_h = planet_card.height.round().max(1.0) as i32;
        params.graphics_width = params.view_w;
        params.graphics_height = params.view_h;
        params.zoom = match dialog.mode {
            CampaignPlanetDialogMode::Look => 1.0,
            CampaignPlanetDialogMode::Select => 0.95,
            CampaignPlanetDialogMode::PlanetLaunch => 1.05,
        };
        params.cam_pos = self.campaign_planet_dialog_camera_position(dialog);
        params.ui_alpha = 1.0;
        params.draw_skybox = true;
        params.draw_ui = true;
        params.always_draw_atmosphere = false;
        params.atmosphere_enabled = true;
        params.has_interface_renderer = true;

        PlanetRenderer::new().render(&params)
    }

    fn campaign_route_solar_system_node(&self, selected_planet_name: &str) -> PlanetRenderNode {
        let planets = &self.content_loader.catalog().planets;
        let Some(selected_planet) = planets
            .iter()
            .find(|planet| planet.name() == selected_planet_name)
        else {
            return PlanetRenderNode::new(selected_planet_name, 1.0)
                .grid(true)
                .atmosphere(true);
        };

        let mut root_name = selected_planet.name();
        while let Some(planet) = planets.iter().find(|planet| planet.name() == root_name) {
            let Some(parent_name) = planet.parent_name.as_deref() else {
                break;
            };
            root_name = parent_name;
        }

        let root_planet = planets
            .iter()
            .find(|planet| planet.name() == root_name)
            .unwrap_or(selected_planet);
        let orbit_radii = Self::campaign_route_planet_orbit_radii(planets);
        Self::campaign_route_planet_render_node_from_content(
            root_planet,
            planets,
            &orbit_radii,
            [0.0, 0.0, 0.0],
            0,
        )
    }

    fn campaign_route_planet_orbit_radii(
        planets: &[mindustry_core::mindustry::content::planets::PlanetContent],
    ) -> BTreeMap<String, f32> {
        let mut orbit_radii = BTreeMap::new();
        let mut total_radii = BTreeMap::new();

        for planet in planets {
            let name = planet.name().to_string();
            let total_radius = planet.meta.total_radius.max(planet.meta.radius);
            total_radii.insert(name.clone(), total_radius);

            let Some(parent_name) = planet.parent_name.as_ref() else {
                orbit_radii.insert(name, 0.0);
                continue;
            };

            let parent = planets
                .iter()
                .find(|candidate| candidate.name() == parent_name.as_str())
                .unwrap();
            let parent_total = *total_radii
                .get(parent_name)
                .unwrap_or(&parent.meta.total_radius.max(parent.meta.radius));
            let orbit_radius = if planet.meta.orbit_radius > 0.0 {
                planet.meta.orbit_radius
            } else {
                parent_total + parent.meta.orbit_spacing + total_radius
            };

            orbit_radii.insert(name, orbit_radius);
            let parent_entry = total_radii
                .entry(parent_name.clone())
                .or_insert(parent_total);
            *parent_entry = (*parent_entry).max(orbit_radius + total_radius);
        }

        orbit_radii
    }

    fn campaign_route_planet_render_node_from_content(
        planet: &mindustry_core::mindustry::content::planets::PlanetContent,
        planets: &[mindustry_core::mindustry::content::planets::PlanetContent],
        orbit_radii: &BTreeMap<String, f32>,
        parent_position: [f32; 3],
        child_index: usize,
    ) -> PlanetRenderNode {
        let orbit_radius = *orbit_radii.get(planet.name()).unwrap_or(&0.0);
        let position = if planet.parent_name.is_some() {
            let angle = ((planet.id as f32 + child_index as f32) * 137.507_77).to_radians();
            [
                parent_position[0] + angle.cos() * orbit_radius,
                parent_position[1],
                parent_position[2] + angle.sin() * orbit_radius,
            ]
        } else {
            [0.0, 0.0, 0.0]
        };

        let mut node = PlanetRenderNode::new(planet.name(), planet.meta.radius)
            .at(position)
            .cam_radius(0.0)
            .orbit_radius(orbit_radius)
            .grid(planet.meta.has_grid)
            .atmosphere(planet.has_atmosphere)
            .visible(planet.meta.visible);
        node.draw_orbit = planet.meta.draw_orbit;
        node.clip_radius = planet.meta.radius + 0.8;

        for (index, child) in planets
            .iter()
            .filter(|candidate| candidate.parent_name.as_deref() == Some(planet.name()))
            .enumerate()
        {
            node.children
                .push(Self::campaign_route_planet_render_node_from_content(
                    child,
                    planets,
                    orbit_radii,
                    position,
                    index,
                ));
        }

        node
    }

    fn campaign_planet_scene_plan_properties(
        plan: &PlanetScenePlan,
        planet_card: RenderRect,
        dialog: &CampaignPlanetDialogState,
    ) -> Vec<RenderProperty> {
        vec![
            RenderProperty::new("source", "desktop.CampaignRoute.PlanetDialog"),
            RenderProperty::new("planet", dialog.planet_name.clone()),
            RenderProperty::new("mode", Self::campaign_planet_dialog_mode_label(dialog.mode)),
            RenderProperty::new("rect_x", planet_card.x.to_string()),
            RenderProperty::new("rect_y", planet_card.y.to_string()),
            RenderProperty::new("rect_width", planet_card.width.to_string()),
            RenderProperty::new("rect_height", planet_card.height.to_string()),
            RenderProperty::new("camera_width", plan.camera.width.to_string()),
            RenderProperty::new("camera_height", plan.camera.height.to_string()),
            RenderProperty::new("camera_fov", plan.camera.fov.to_string()),
            RenderProperty::new("camera_far", plan.camera.far.to_string()),
            RenderProperty::new("camera_x", plan.camera.position[0].to_string()),
            RenderProperty::new("camera_y", plan.camera.position[1].to_string()),
            RenderProperty::new("camera_z", plan.camera.position[2].to_string()),
            RenderProperty::new("look_x", plan.camera.look_at[0].to_string()),
            RenderProperty::new("look_y", plan.camera.look_at[1].to_string()),
            RenderProperty::new("look_z", plan.camera.look_at[2].to_string()),
            RenderProperty::new("projector_scaling", plan.projector_scaling.to_string()),
            RenderProperty::new("step_count", plan.steps.len().to_string()),
            RenderProperty::new(
                "selected_sector",
                dialog
                    .selected_sector_id
                    .map(|sector_id| sector_id.to_string())
                    .unwrap_or_default(),
            ),
            RenderProperty::new(
                "hovered_sector",
                dialog
                    .hovered_sector_id
                    .map(|sector_id| sector_id.to_string())
                    .unwrap_or_default(),
            ),
        ]
    }

    fn campaign_planet_scene_step_properties(
        index: usize,
        step: &PlanetSceneStep,
    ) -> Vec<RenderProperty> {
        let mut properties = vec![
            RenderProperty::new("index", index.to_string()),
            RenderProperty::new("kind", Self::campaign_planet_scene_step_kind(step)),
        ];

        match step {
            PlanetSceneStep::DepthMask(enabled) => {
                properties.push(RenderProperty::new("enabled", enabled.to_string()));
            }
            PlanetSceneStep::BloomCapture {
                width,
                height,
                blending,
            } => {
                properties.push(RenderProperty::new("width", width.to_string()));
                properties.push(RenderProperty::new("height", height.to_string()));
                properties.push(RenderProperty::new("blending", blending.to_string()));
            }
            PlanetSceneStep::DrawSkybox(plan) => {
                properties.push(RenderProperty::new("cubemap", plan.cubemap.clone()));
                properties.push(RenderProperty::new("shader", plan.shader.clone()));
                properties.push(RenderProperty::new(
                    "vertex_count",
                    plan.vertex_count.to_string(),
                ));
            }
            PlanetSceneStep::DrawPlanet { planet, transform }
            | PlanetSceneStep::DrawClouds { planet, transform } => {
                properties.push(RenderProperty::new("planet", planet.clone()));
                properties.push(RenderProperty::new("x", transform.values[0][3].to_string()));
                properties.push(RenderProperty::new("y", transform.values[1][3].to_string()));
                properties.push(RenderProperty::new("z", transform.values[2][3].to_string()));
            }
            PlanetSceneStep::DrawSectors { planet }
            | PlanetSceneStep::DrawAtmosphere { planet }
            | PlanetSceneStep::RenderOverProjections { planet }
            | PlanetSceneStep::RenderProjections { planet } => {
                properties.push(RenderProperty::new("planet", planet.clone()));
            }
            PlanetSceneStep::DrawOrbit {
                planet,
                points,
                alpha,
            } => {
                properties.push(RenderProperty::new("planet", planet.clone()));
                properties.push(RenderProperty::new("points", points.to_string()));
                properties.push(RenderProperty::new("alpha", alpha.to_string()));
            }
            PlanetSceneStep::FlushDraw
            | PlanetSceneStep::ClearDepth
            | PlanetSceneStep::EnableDepthTest
            | PlanetSceneStep::EnableBackfaceCulling
            | PlanetSceneStep::UniverseDrawBegin
            | PlanetSceneStep::UniverseDraw
            | PlanetSceneStep::BloomRender
            | PlanetSceneStep::EnableBlend
            | PlanetSceneStep::DisableBackfaceCulling
            | PlanetSceneStep::DisableDepthTest
            | PlanetSceneStep::CameraUpdate => {}
        }

        properties
    }

    fn campaign_planet_scene_step_kind(step: &PlanetSceneStep) -> &'static str {
        match step {
            PlanetSceneStep::FlushDraw => "FlushDraw",
            PlanetSceneStep::ClearDepth => "ClearDepth",
            PlanetSceneStep::EnableDepthTest => "EnableDepthTest",
            PlanetSceneStep::DepthMask(_) => "DepthMask",
            PlanetSceneStep::EnableBackfaceCulling => "EnableBackfaceCulling",
            PlanetSceneStep::UniverseDrawBegin => "UniverseDrawBegin",
            PlanetSceneStep::BloomCapture { .. } => "BloomCapture",
            PlanetSceneStep::DrawSkybox(_) => "DrawSkybox",
            PlanetSceneStep::UniverseDraw => "UniverseDraw",
            PlanetSceneStep::DrawPlanet { .. } => "DrawPlanet",
            PlanetSceneStep::DrawClouds { .. } => "DrawClouds",
            PlanetSceneStep::DrawSectors { .. } => "DrawSectors",
            PlanetSceneStep::DrawAtmosphere { .. } => "DrawAtmosphere",
            PlanetSceneStep::DrawOrbit { .. } => "DrawOrbit",
            PlanetSceneStep::RenderOverProjections { .. } => "RenderOverProjections",
            PlanetSceneStep::BloomRender => "BloomRender",
            PlanetSceneStep::EnableBlend => "EnableBlend",
            PlanetSceneStep::RenderProjections { .. } => "RenderProjections",
            PlanetSceneStep::DisableBackfaceCulling => "DisableBackfaceCulling",
            PlanetSceneStep::DisableDepthTest => "DisableDepthTest",
            PlanetSceneStep::CameraUpdate => "CameraUpdate",
        }
    }

    fn campaign_planet_dialog_mode_label(mode: CampaignPlanetDialogMode) -> &'static str {
        match mode {
            CampaignPlanetDialogMode::Look => "look",
            CampaignPlanetDialogMode::Select => "select",
            CampaignPlanetDialogMode::PlanetLaunch => "planetLaunch",
        }
    }

    fn push_campaign_sector_list(
        &self,
        pass: &mut RenderPass,
        panel: RenderRect,
        dialog: &CampaignPlanetDialogState,
    ) {
        if dialog.mode == CampaignPlanetDialogMode::PlanetLaunch {
            return;
        }
        let base_entries = self.campaign_sector_list_base_entries(dialog);
        if base_entries.is_empty() {
            return;
        }
        let layer = Layer::END_PIXELED + 0.041;
        let toggle = Self::campaign_sector_list_toggle_rect(panel);
        let attacked = base_entries
            .iter()
            .filter(|sector| sector.is_attacked(Default::default()))
            .count();
        let mut label = self.localize_bundle_markup_text("@sectorlist");
        if attacked > 0 {
            let attacked_text = self.format_bundle_text(
                "sectorlist.attacked",
                &[format!("[red]{attacked}[]").as_str()],
            );
            label.push('\n');
            label.push_str(&attacked_text);
        }
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("button"),
            toggle,
            if self.campaign_sector_list_open {
                [0.32, 0.54, 0.68, 0.92]
            } else {
                [1.0, 1.0, 1.0, 0.46]
            },
            0.0,
            layer,
        ));
        pass.push(RenderCommand::stroke_rect(
            toggle,
            [0.54, 0.74, 0.88, 0.92],
            1.0,
            layer + 0.001,
        ));
        if attacked > 0 {
            self.push_large_icon_like_java(
                pass,
                "warning",
                RenderRect::from_center(
                    RenderPoint::new(toggle.x + 22.0, toggle.center().y - 8.0),
                    18.0,
                    18.0,
                ),
                [0.66, 0.80, 1.0, 1.0],
                layer + 0.0015,
            );
        }
        pass.push(RenderCommand::draw_text_styled(
            label,
            RenderPoint::new(
                toggle.x + if attacked > 0 { 42.0 } else { 14.0 },
                toggle.center().y,
            ),
            [0.92, 0.97, 1.0, 1.0],
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.002,
        ));
        pass.push(RenderCommand::draw_text_styled(
            if self.campaign_sector_list_open {
                desktop_ui_icon_glyph_or_label("upOpen", "upOpen")
            } else {
                desktop_ui_icon_glyph_or_label("downOpen", "downOpen")
            },
            RenderPoint::new(toggle.right() - 22.0, toggle.center().y),
            [0.96, 1.0, 1.0, 1.0],
            15.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_font(RenderFontId::Icon)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.003,
        ));

        if !self.campaign_sector_list_open {
            return;
        }

        let pane = Self::campaign_sector_list_pane_rect(panel);
        pass.push(RenderCommand::fill_rect(
            pane,
            [0.02, 0.03, 0.04, 0.86],
            layer + 0.010,
        ));
        pass.push(RenderCommand::stroke_rect(
            pane,
            [0.30, 0.44, 0.54, 0.92],
            1.0,
            layer + 0.011,
        ));
        let search = Self::campaign_sector_list_search_rect(pane);
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("button"),
            search,
            if self.campaign_sector_list_search_focused {
                [0.28, 0.44, 0.56, 0.94]
            } else {
                [1.0, 1.0, 1.0, 0.30]
            },
            0.0,
            layer + 0.012,
        ));
        pass.push(RenderCommand::draw_text_styled(
            desktop_ui_icon_glyph_or_label("zoom", "zoom"),
            RenderPoint::new(search.x + 18.0, search.center().y),
            [0.72, 0.84, 0.92, 1.0],
            14.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_font(RenderFontId::Icon)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            layer + 0.013,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.campaign_sector_list_search.clone(),
            RenderPoint::new(search.x + 36.0, search.center().y),
            [0.88, 0.95, 1.0, 1.0],
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            layer + 0.014,
        ));
        if !self.campaign_sector_list_search.is_empty() {
            let clear = Self::campaign_sector_list_clear_rect(search);
            pass.push(RenderCommand::draw_text_styled(
                desktop_ui_icon_glyph_or_label("cancel", "cancel"),
                clear.center(),
                [0.90, 0.96, 1.0, 1.0],
                13.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_font(RenderFontId::Icon)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                layer + 0.015,
            ));
        }

        let entries = self.campaign_sector_list_filtered_entries(dialog);
        if entries.is_empty() {
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@none.found"),
                RenderPoint::new(pane.center().x, pane.y + 52.0),
                [0.72, 0.80, 0.86, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.020,
            ));
            return;
        }

        for (index, sector) in entries.iter().take(4).enumerate() {
            let rect = Self::campaign_sector_list_entry_rect(pane, index);
            let selected = Some(sector.id) == dialog.selected_sector_id;
            pass.push(RenderCommand::draw_sprite(
                Self::settings_drawable_symbol("button"),
                rect,
                if selected {
                    [0.34, 0.62, 0.76, 0.90]
                } else {
                    [1.0, 1.0, 1.0, 0.22]
                },
                0.0,
                layer + 0.020 + index as f32 * 0.003,
            ));
            let attacked = sector.is_attacked(Default::default());
            if attacked {
                self.push_large_icon_like_java(
                    pass,
                    "warning",
                    RenderRect::from_center(
                        RenderPoint::new(rect.x + 18.0, rect.center().y + 7.0),
                        16.0,
                        16.0,
                    ),
                    [0.66, 0.80, 1.0, 1.0],
                    layer + 0.0208 + index as f32 * 0.003,
                );
            }
            pass.push(RenderCommand::draw_text_styled(
                self.campaign_sector_list_display_name(sector),
                RenderPoint::new(
                    rect.x + if attacked { 32.0 } else { 12.0 },
                    rect.center().y + 7.0,
                ),
                if attacked {
                    [1.0, 0.72, 0.50, 1.0]
                } else {
                    [0.90, 0.96, 1.0, 1.0]
                },
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                layer + 0.021 + index as f32 * 0.003,
            ));
            if attacked {
                let wave = format!(
                    "{} [accent]{}",
                    self.localize_bundle_markup_text("@sectors.wave"),
                    sector.info.wave
                );
                pass.push(RenderCommand::draw_text_styled(
                    wave,
                    RenderPoint::new(rect.x + 22.0, rect.center().y - 9.0),
                    [0.74, 0.84, 0.90, 1.0],
                    8.5,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true),
                    layer + 0.022 + index as f32 * 0.003,
                ));
            }
        }
    }

    fn campaign_rules_toggle_specs(
        &self,
    ) -> Vec<(&'static str, bool, DesktopMenuRouteShellAction)> {
        let planet_name = self.campaign_rules_planet_name.as_deref().or_else(|| {
            self.campaign_planet_dialog
                .as_ref()
                .map(|dialog| dialog.planet_name.as_str())
        });
        let planet =
            planet_name.and_then(|name| self.content_loader.catalog().planet_by_name(name));
        let mut specs = Vec::new();

        if planet.is_some_and(|planet| planet.meta.allow_sector_invasion) {
            specs.push((
                "@rules.invasions",
                self.campaign_rules_draft.sector_invasion,
                DesktopMenuRouteShellAction::ToggleCampaignRuleInvasions,
            ));
        }

        specs.extend([
            (
                "@rules.fog",
                self.campaign_rules_draft.fog,
                DesktopMenuRouteShellAction::ToggleCampaignRuleFog,
            ),
            (
                "@rules.showspawns",
                self.campaign_rules_draft.show_spawns,
                DesktopMenuRouteShellAction::ToggleCampaignRuleShowSpawns,
            ),
            (
                "@rules.randomwaveai",
                self.campaign_rules_draft.random_wave_ai,
                DesktopMenuRouteShellAction::ToggleCampaignRuleRandomWaveAi,
            ),
            (
                "@rules.pauseDisabled",
                self.campaign_rules_draft.pause_disabled,
                DesktopMenuRouteShellAction::ToggleCampaignRulePauseDisabled,
            ),
        ]);

        if planet_name
            .is_some_and(|name| self.campaign_planet_rules_for_name(name).show_rts_ai_rule)
        {
            specs.push((
                "@rules.rtsai.campaign",
                self.campaign_rules_draft.rts_ai,
                DesktopMenuRouteShellAction::ToggleCampaignRuleRtsAi,
            ));
        }

        if planet.is_some_and(|planet| !planet.meta.clear_sector_on_lose) {
            specs.push((
                "@rules.clearsectoronloss",
                self.campaign_rules_draft.clear_sector_on_lose,
                DesktopMenuRouteShellAction::ToggleCampaignRuleClearSectorOnLoss,
            ));
        }

        specs
    }

    fn campaign_difficulty_info_text(&self, difficulty: Difficulty) -> String {
        let multipliers = difficulty.multipliers();
        let mut result = String::new();

        if multipliers.enemy_health_multiplier != 1.0 {
            let value = Difficulty::percent_stat(multipliers.enemy_health_multiplier);
            result.push_str(
                &self.format_bundle_text("difficulty.enemyHealthMultiplier", &[value.as_str()]),
            );
            result.push('\n');
        }

        if multipliers.enemy_spawn_multiplier != 1.0 {
            let value = Difficulty::percent_stat(multipliers.enemy_spawn_multiplier);
            result.push_str(
                &self.format_bundle_text("difficulty.enemySpawnMultiplier", &[value.as_str()]),
            );
            result.push('\n');
        }

        if multipliers.wave_time_multiplier != 1.0 {
            let value = Difficulty::percent_stat_neg(multipliers.wave_time_multiplier);
            result.push_str(
                &self.format_bundle_text("difficulty.waveTimeMultiplier", &[value.as_str()]),
            );
            result.push('\n');
        }

        if result.is_empty() {
            self.localize_bundle_markup_text("@difficulty.nomodifiers")
        } else {
            result
        }
    }

    fn campaign_rules_hovered_difficulty(
        &self,
        dialog: RenderRect,
    ) -> Option<(Difficulty, RenderRect)> {
        let cursor = self.last_menu_cursor?;
        Difficulty::ALL
            .iter()
            .copied()
            .enumerate()
            .find_map(|(index, difficulty)| {
                let rect = Self::campaign_rules_difficulty_button_rect(dialog, index);
                rect.contains_point(cursor).then_some((difficulty, rect))
            })
    }

    fn campaign_rules_rule_info_text(&self, label_key: &str) -> Option<String> {
        let info_key = format!("{label_key}.info");
        let localized = self.localize_bundle_markup_text_or(&info_key, "");
        (!localized.is_empty()).then_some(localized)
    }

    fn campaign_rules_hovered_rule_info(&self, dialog: RenderRect) -> Option<(String, RenderRect)> {
        let cursor = self.last_menu_cursor?;
        self.campaign_rules_toggle_specs()
            .iter()
            .enumerate()
            .find_map(|(index, (label_key, _, _))| {
                let rect = Self::campaign_rules_toggle_rect(dialog, index);
                if rect.contains_point(cursor) {
                    self.campaign_rules_rule_info_text(label_key)
                        .map(|text| (text, rect))
                } else {
                    None
                }
            })
    }

