    fn push_campaign_rules_dialog(&self, pass: &mut RenderPass, panel: RenderRect) {
        let layer = Layer::END_PIXELED + 0.244;
        let dialog = Self::campaign_rules_dialog_rect(panel);
        pass.push(RenderCommand::fill_rect(
            panel,
            [0.0, 0.0, 0.0, 0.58],
            layer,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            dialog,
            [1.0, 1.0, 1.0, 0.98],
            0.0,
            layer + 0.001,
        ));
        pass.push(RenderCommand::stroke_rect(
            dialog,
            [0.62, 0.82, 1.0, 0.96],
            2.0,
            layer + 0.002,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@campaign.difficulty"),
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 30.0),
            [0.94, 0.98, 1.0, 1.0],
            18.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.003,
        ));

        for (index, difficulty) in Difficulty::ALL.iter().copied().enumerate() {
            let rect = Self::campaign_rules_difficulty_button_rect(dialog, index);
            let selected = self.campaign_rules_draft.difficulty == difficulty;
            self.push_settings_text_button_enabled_checked_with_style(
                pass,
                rect,
                self.localized_difficulty_label_like_java(difficulty),
                None,
                layer + 0.010 + index as f32 * 0.001,
                true,
                selected,
                "flatTogglet",
            );
        }

        for (index, (label_key, checked, _)) in
            self.campaign_rules_toggle_specs().iter().enumerate()
        {
            let rect = Self::campaign_rules_toggle_rect(dialog, index);
            let hovered = self
                .last_menu_cursor
                .is_some_and(|cursor| rect.contains_point(cursor));
            if hovered {
                pass.push(RenderCommand::fill_rect(
                    rect,
                    [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 0.10],
                    layer + 0.029 + index as f32 * 0.001,
                ));
            }
            let check_rect = Self::campaign_rules_toggle_check_box_rect(rect);
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text(label_key),
                Self::campaign_rules_toggle_label_point(rect),
                Self::settings_check_box_font_color(true),
                12.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.031 + index as f32 * 0.001,
            ));
            pass.push(RenderCommand::draw_sprite(
                Self::settings_check_box_symbol(*checked, hovered, false),
                check_rect,
                [1.0, 1.0, 1.0, 1.0],
                0.0,
                layer + 0.032 + index as f32 * 0.001,
            ));
        }

        if let Some((difficulty, target)) = self.campaign_rules_hovered_difficulty(dialog) {
            self.push_campaign_rules_hover_tooltip(
                pass,
                panel,
                target,
                self.campaign_difficulty_info_text(difficulty),
                layer + 0.080,
            );
        } else if let Some((text, target)) = self.campaign_rules_hovered_rule_info(dialog) {
            self.push_campaign_rules_hover_tooltip(pass, panel, target, text, layer + 0.080);
        }

        self.push_settings_text_button(
            pass,
            Self::campaign_rules_close_rect(dialog),
            self.localize_bundle_markup_text("@ok"),
            Some("ok"),
            layer + 0.090,
        );
    }

