    fn push_campaign_launch_loadout_dialog(&self, pass: &mut RenderPass, panel: RenderRect) {
        let layer = Layer::END_PIXELED + 0.246;
        let dialog = Self::campaign_launch_loadout_dialog_rect(panel);
        let valid = self.campaign_launch_loadout_valid();
        let allows_resources = self.campaign_launch_loadout_allows_resources();
        let allows_schematics = self.campaign_launch_loadout_allows_schematics();
        let capacity = self.campaign_launch_loadout_capacity();
        let source_name = self.campaign_launch_loadout_sector_name();
        let from_label = self.format_bundle_text("launch.from", &[source_name.as_str()]);
        let capacity_text = capacity.to_string();
        let capacity_label = self.format_bundle_text("launch.capacity", &[capacity_text.as_str()]);

        pass.push(RenderCommand::fill_rect(
            panel,
            [0.0, 0.0, 0.0, 0.56],
            layer,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            dialog,
            [1.0, 1.0, 1.0, 0.98],
            0.0,
            layer + 0.001,
        ));
        pass.push(RenderCommand::stroke_rect(
            dialog,
            [0.62, 0.82, 1.0, 0.96],
            2.0,
            layer + 0.002,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@configure"),
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 28.0),
            [0.94, 0.98, 1.0, 1.0],
            16.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.004,
        ));
        pass.push(RenderCommand::draw_text_styled(
            from_label,
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 58.0),
            [0.78, 0.88, 0.96, 1.0],
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            layer + 0.005,
        ));

        let items_rect = Self::campaign_launch_loadout_items_rect(dialog);
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("button"),
            items_rect,
            [1.0, 1.0, 1.0, 0.24],
            0.0,
            layer + 0.006,
        ));
        pass.push(RenderCommand::stroke_rect(
            items_rect,
            [0.34, 0.50, 0.62, 0.84],
            1.0,
            layer + 0.007,
        ));

        let stacks = self.campaign_launch_loadout_stacks();
        let source = self.campaign_launch_loadout_source_sector();
        let schematic_amounts = self
            .campaign_launch_loadout_selected_candidate()
            .map(|candidate| {
                candidate.requirements.into_iter().fold(
                    BTreeMap::<String, i32>::new(),
                    |mut amounts, stack| {
                        *amounts.entry(stack.item).or_insert(0) += stack.amount;
                        amounts
                    },
                )
            })
            .unwrap_or_default();
        pass.push(RenderCommand::set_clip(items_rect));
        for (index, stack) in stacks.iter().enumerate() {
            let row = Self::campaign_launch_loadout_item_cell_rect(items_rect, index);
            pass.push(RenderCommand::draw_sprite(
                Self::settings_drawable_symbol("button"),
                row,
                [1.0, 1.0, 1.0, 0.18],
                0.0,
                layer + 0.010 + index as f32 * 0.001,
            ));
            let icon_symbol = item_full_icon_region_symbol(&stack.item, &self.content_loader)
                .filter(|symbol| self.texture_atlas.lookup(symbol).is_ok())
                .unwrap_or_else(|| stack.item.clone());
            pass.push(RenderCommand::draw_sprite(
                icon_symbol,
                RenderRect::new(row.x + 10.0, row.center().y - 10.0, 20.0, 20.0),
                [1.0, 1.0, 1.0, 0.96],
                0.0,
                layer + 0.011 + index as f32 * 0.001,
            ));
            pass.push(RenderCommand::draw_text_styled(
                {
                    let base = if allows_resources {
                        let schematic = schematic_amounts.get(&stack.item).copied().unwrap_or(0);
                        let launch = (stack.amount - schematic).max(0);
                        format!("{}[gray] ({} + {})", stack.amount, launch, schematic)
                    } else {
                        stack.amount.to_string()
                    };
                    if let Some(source) = source {
                        let available = source.stored_item_amount(&stack.item);
                        if available < stack.amount {
                            format!(
                                "[scarlet]{}/[lightgray]{}",
                                available.min(stack.amount),
                                base
                            )
                        } else {
                            base
                        }
                    } else {
                        base
                    }
                },
                RenderPoint::new(row.x + 36.0, row.center().y),
                [0.94, 0.98, 1.0, 1.0],
                10.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.012 + index as f32 * 0.001,
            ));
        }
        pass.push(RenderCommand::clear_clip());

        if !allows_schematics {
            if let Some(description) = self.campaign_launch_loadout_destination_description() {
                let description_rect = Self::campaign_launch_loadout_description_rect(dialog);
                pass.push(RenderCommand::draw_sprite(
                    Self::settings_drawable_symbol("button"),
                    description_rect,
                    [1.0, 1.0, 1.0, 0.16],
                    0.0,
                    layer + 0.078,
                ));
                pass.push(RenderCommand::stroke_rect(
                    description_rect,
                    [0.34, 0.50, 0.62, 0.70],
                    1.0,
                    layer + 0.079,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    description,
                    RenderPoint::new(description_rect.center().x, description_rect.center().y),
                    [0.76, 0.86, 0.94, 1.0],
                    10.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_wrap_width(description_rect.width - 28.0)
                        .with_integer_position(true),
                    layer + 0.080,
                ));
            }
        } else {
            let picker = Self::campaign_launch_loadout_picker_rect(dialog);
            let candidates = self.campaign_launch_loadout_candidates();
            let selected = self
                .campaign_launch_loadout_selected_candidate()
                .map(|candidate| candidate.name);
            for (index, candidate) in candidates.iter().enumerate() {
                let cell = Self::campaign_launch_loadout_picker_candidate_rect(
                    picker,
                    index,
                    candidates.len(),
                );
                let checked = selected.as_deref() == Some(candidate.name.as_str());
                let hovered = self
                    .last_menu_cursor
                    .is_some_and(|cursor| cell.contains_point(cursor));
                let (button_symbol, button_tint) =
                    Self::settings_text_button_symbol_and_tint_checked(
                        "togglet", hovered, false, checked, true, 0.96,
                    );
                pass.push(RenderCommand::draw_sprite(
                    button_symbol,
                    cell,
                    button_tint,
                    0.0,
                    layer + 0.078 + index as f32 * 0.004,
                ));
                let preview = Self::campaign_launch_loadout_picker_candidate_preview_rect(cell);
                pass.push(RenderCommand::draw_sprite(
                    "schematic-background",
                    preview,
                    [0.70, 0.78, 0.86, 0.74],
                    0.0,
                    layer + 0.079 + index as f32 * 0.004,
                ));
                pass.push(RenderCommand::stroke_rect(
                    preview,
                    if hovered || checked {
                        [0.62, 0.82, 1.0, 0.96]
                    } else {
                        [0.34, 0.50, 0.62, 0.70]
                    },
                    if hovered || checked { 2.0 } else { 1.0 },
                    layer + 0.080 + index as f32 * 0.004,
                ));
                let preview_entry = candidate.preview_entry();
                if self.push_schematic_preview_tiles(
                    pass,
                    preview,
                    &preview_entry,
                    layer + 0.081 + index as f32 * 0.004,
                ) == 0
                {
                    pass.push(RenderCommand::draw_sprite(
                        "refresh",
                        RenderRect::from_center(
                            preview.center(),
                            preview.width.min(preview.height) * 0.25,
                            preview.width.min(preview.height) * 0.25,
                        ),
                        [0.82, 0.90, 0.96, 0.94],
                        0.0,
                        layer + 0.082 + index as f32 * 0.004,
                    ));
                }
            }
        }
        pass.push(RenderCommand::draw_text_styled(
            capacity_label,
            RenderPoint::new(dialog.center().x, items_rect.y + items_rect.height + 8.0),
            [0.78, 0.88, 0.96, 1.0],
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            layer + 0.081,
        ));
        if !valid {
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@sector.missingresources"),
                RenderPoint::new(dialog.center().x, dialog.y + 94.0),
                [1.0, 0.35, 0.34, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.082,
            ));
        }

        self.push_settings_text_button(
            pass,
            Self::campaign_launch_loadout_back_rect(dialog),
            self.localize_bundle_markup_text("@back"),
            Some("left"),
            layer + 0.090,
        );
        self.push_settings_text_button_enabled_checked_with_style(
            pass,
            Self::campaign_launch_loadout_max_rect(dialog),
            self.localize_bundle_markup_text("@resources.max"),
            Some("add"),
            layer + 0.091,
            allows_resources,
            self.campaign_launch_loadout_use_max_resources,
            "togglet",
        );
        self.push_settings_text_button_enabled(
            pass,
            Self::campaign_launch_loadout_resources_rect(dialog),
            self.localize_bundle_markup_text("@resources"),
            Some("edit"),
            layer + 0.092,
            allows_resources && !self.campaign_launch_loadout_use_max_resources,
        );
        self.push_settings_text_button_enabled(
            pass,
            Self::campaign_launch_loadout_confirm_rect(dialog),
            self.localize_bundle_markup_text("@launch.text"),
            Some("ok"),
            layer + 0.093,
            valid,
        );
    }

    fn push_campaign_launch_resources_dialog(&self, pass: &mut RenderPass, panel: RenderRect) {
        let layer = Layer::END_PIXELED + 0.348;
        let dialog = Self::campaign_launch_resources_dialog_rect(panel);
        let list = Self::campaign_launch_resources_items_rect(dialog);
        let capacity = self.campaign_launch_loadout_capacity().max(0);
        let capacity_text = capacity.to_string();
        let stacks = self.campaign_launch_resources_visible_draft();

        pass.push(RenderCommand::fill_rect(
            panel,
            [0.0, 0.0, 0.0, 0.62],
            layer,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            dialog,
            [1.0, 1.0, 1.0, 0.98],
            0.0,
            layer + 0.001,
        ));
        pass.push(RenderCommand::stroke_rect(
            dialog,
            [0.62, 0.82, 1.0, 0.96],
            2.0,
            layer + 0.002,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@configure"),
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 28.0),
            [0.94, 0.98, 1.0, 1.0],
            16.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.004,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.format_bundle_text("launch.capacity", &[capacity_text.as_str()]),
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 56.0),
            [0.70, 0.80, 0.88, 1.0],
            10.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            layer + 0.005,
        ));

        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("button"),
            list,
            [1.0, 1.0, 1.0, 0.18],
            0.0,
            layer + 0.006,
        ));
        pass.push(RenderCommand::stroke_rect(
            list,
            [0.34, 0.50, 0.62, 0.84],
            1.0,
            layer + 0.007,
        ));

        for (index, stack) in stacks.iter().take(10).enumerate() {
            let row = Self::campaign_launch_resources_item_rect(list, index);
            pass.push(RenderCommand::draw_sprite(
                Self::settings_drawable_symbol("pane"),
                row,
                [1.0, 1.0, 1.0, 0.18],
                0.0,
                layer + 0.010 + index as f32 * 0.001,
            ));
            self.push_settings_text_button(
                pass,
                Self::campaign_launch_resources_item_minus_rect(row),
                "-",
                None,
                layer + 0.011 + index as f32 * 0.001,
            );
            self.push_settings_text_button(
                pass,
                Self::campaign_launch_resources_item_plus_rect(row),
                "+",
                None,
                layer + 0.012 + index as f32 * 0.001,
            );
            self.push_settings_icon_button(
                pass,
                Self::campaign_launch_resources_item_edit_rect(row),
                "pencil",
                layer + 0.013 + index as f32 * 0.001,
            );
            let icon_symbol = item_full_icon_region_symbol(&stack.item, &self.content_loader)
                .filter(|symbol| self.texture_atlas.lookup(symbol).is_ok())
                .unwrap_or_else(|| stack.item.clone());
            pass.push(RenderCommand::draw_sprite(
                icon_symbol,
                RenderRect::new(row.x + 112.0, row.center().y - 11.0, 22.0, 22.0),
                [1.0, 1.0, 1.0, 0.96],
                0.0,
                layer + 0.014 + index as f32 * 0.001,
            ));
            pass.push(RenderCommand::draw_text_styled(
                self.pause_loadout_item_label(&stack.item),
                RenderPoint::new(row.x + 142.0, row.center().y),
                [0.84, 0.92, 1.0, 1.0],
                10.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.015 + index as f32 * 0.001,
            ));
            pass.push(RenderCommand::draw_text_styled(
                stack.amount.to_string(),
                RenderPoint::new(row.right() - 12.0, row.center().y),
                [0.94, 0.98, 1.0, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::End)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.016 + index as f32 * 0.001,
            ));
        }

        self.push_settings_text_button(
            pass,
            Self::campaign_launch_resources_back_rect(dialog),
            self.localize_bundle_markup_text("@back"),
            Some("left"),
            layer + 0.090,
        );
        self.push_settings_text_button(
            pass,
            Self::campaign_launch_resources_max_rect(dialog),
            self.localize_bundle_markup_text("@max"),
            Some("export"),
            layer + 0.091,
        );
        self.push_settings_text_button(
            pass,
            Self::campaign_launch_resources_reset_rect(dialog),
            self.localize_bundle_markup_text("@settings.reset"),
            Some("refresh"),
            layer + 0.092,
        );
    }

    fn push_campaign_sector_stats_item_icons(
        &self,
        pass: &mut RenderPass,
        names: &[String],
        x: f32,
        y: f32,
        layer: f32,
    ) {
        for (index, name) in names.iter().take(8).enumerate() {
            let icon_symbol = item_full_icon_region_symbol(name, &self.content_loader)
                .filter(|symbol| self.texture_atlas.lookup(symbol).is_ok())
                .unwrap_or_else(|| name.clone());
            pass.push(RenderCommand::draw_sprite(
                icon_symbol,
                RenderRect::new(x + index as f32 * 26.0, y - 10.0, 20.0, 20.0),
                [1.0, 1.0, 1.0, 0.96],
                0.0,
                layer + index as f32 * 0.0001,
            ));
        }
    }

    fn push_campaign_sector_stats_rate_section(
        &self,
        pass: &mut RenderPass,
        label: String,
        stats: &HashMap<String, ExportStat>,
        cursor_y: &mut f32,
        dialog: RenderRect,
        layer: f32,
    ) {
        let lines = self.campaign_sector_stat_item_lines(stats);
        if lines.is_empty() {
            return;
        }
        pass.push(RenderCommand::draw_text_styled(
            label,
            RenderPoint::new(dialog.x + 30.0, *cursor_y),
            [0.84, 0.92, 1.0, 1.0],
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer,
        ));
        *cursor_y -= 22.0;
        for (index, (item, amount)) in lines.iter().take(6).enumerate() {
            let y = *cursor_y - index as f32 * 18.0;
            self.push_campaign_sector_stats_item_icons(
                pass,
                std::slice::from_ref(item),
                dialog.x + 42.0,
                y,
                layer + 0.001 + index as f32 * 0.0002,
            );
            pass.push(RenderCommand::draw_text_styled(
                amount.clone(),
                RenderPoint::new(dialog.x + 70.0, y),
                [0.76, 0.84, 0.90, 1.0],
                10.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.0015 + index as f32 * 0.0002,
            ));
        }
        *cursor_y -= 18.0 * lines.len().min(6) as f32 + 8.0;
    }

    fn push_campaign_sector_stats_dialog(&self, pass: &mut RenderPass, panel: RenderRect) {
        let Some(sector) = self.campaign_sector_stats_snapshot() else {
            return;
        };
        let layer = Layer::END_PIXELED + 0.250;
        let dialog = Self::campaign_sector_stats_dialog_rect(panel);
        let has_base = Self::campaign_sector_has_base_for_stats(&sector);
        let title = sector
            .info
            .name
            .clone()
            .or_else(|| {
                sector
                    .preset
                    .as_ref()
                    .map(|preset| preset.localized_name.clone())
            })
            .filter(|name| !name.is_empty())
            .unwrap_or_else(|| format!("#{}", sector.id));

        pass.push(RenderCommand::fill_rect(
            panel,
            [0.0, 0.0, 0.0, 0.56],
            layer,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            dialog,
            [1.0, 1.0, 1.0, 0.98],
            0.0,
            layer + 0.001,
        ));
        pass.push(RenderCommand::stroke_rect(
            dialog,
            [0.62, 0.82, 1.0, 0.96],
            2.0,
            layer + 0.002,
        ));
        pass.push(RenderCommand::draw_text_styled(
            title,
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 28.0),
            [0.94, 0.98, 1.0, 1.0],
            16.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.004,
        ));

        let mut cursor_y = dialog.y + dialog.height - 62.0;
        if let Some(description) = sector
            .preset
            .as_ref()
            .and_then(|preset| preset.description.as_ref())
        {
            pass.push(RenderCommand::draw_text_styled(
                description.clone(),
                RenderPoint::new(dialog.x + 30.0, cursor_y),
                [0.72, 0.82, 0.90, 1.0],
                10.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_wrap_width(dialog.width - 60.0),
                layer + 0.005,
            ));
            cursor_y -= 34.0;
        }

        let time_line = format!(
            "{} [accent]{}",
            self.localize_bundle_markup_text("@sectors.time"),
            Self::campaign_sector_play_time_label(&sector)
        );
        pass.push(RenderCommand::draw_text_styled(
            time_line,
            RenderPoint::new(dialog.x + 30.0, cursor_y),
            [0.82, 0.90, 0.96, 1.0],
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            layer + 0.006,
        ));
        cursor_y -= 20.0;

        if sector.info.attempts > 0 {
            pass.push(RenderCommand::draw_text_styled(
                format!(
                    "{} [accent]{}",
                    self.localize_bundle_markup_text("@sectors.attempts"),
                    sector.info.attempts
                ),
                RenderPoint::new(dialog.x + 30.0, cursor_y),
                [0.82, 0.90, 0.96, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.007,
            ));
            cursor_y -= 20.0;
        }
        if sector.info.waves && has_base {
            pass.push(RenderCommand::draw_text_styled(
                format!(
                    "{} [accent]{}",
                    self.localize_bundle_markup_text("@sectors.wave"),
                    sector.info.wave
                ),
                RenderPoint::new(dialog.x + 30.0, cursor_y),
                [0.82, 0.90, 0.96, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.008,
            ));
            cursor_y -= 20.0;
        }
        if sector.is_attacked(Default::default()) || !has_base {
            let threat_key = Self::campaign_threat_key(sector.threat);
            pass.push(RenderCommand::draw_text_styled(
                format!(
                    "{} [accent]{}",
                    self.localize_bundle_markup_text("@sectors.threat"),
                    self.localized_threat_label_like_java(threat_key)
                ),
                RenderPoint::new(dialog.x + 30.0, cursor_y),
                [0.82, 0.90, 0.96, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.009,
            ));
            cursor_y -= 20.0;
        }

        if !sector.info.resources.is_empty() {
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@sectors.resources"),
                RenderPoint::new(dialog.x + 30.0, cursor_y),
                [0.84, 0.92, 1.0, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                layer + 0.010,
            ));
            cursor_y -= 24.0;
            self.push_campaign_sector_stats_item_icons(
                pass,
                &sector.info.resources,
                dialog.x + 42.0,
                cursor_y,
                layer + 0.011,
            );
            cursor_y -= 28.0;
        }

        if sector.is_attacked(Default::default()) && !sector.save_exists {
            pass.push(RenderCommand::draw_text_styled(
                self.format_bundle_text("sector.lockdown", &[]),
                RenderPoint::new(dialog.x + 30.0, cursor_y),
                [1.0, 0.46, 0.36, 1.0],
                10.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_wrap_width(dialog.width - 60.0),
                layer + 0.012,
            ));
            cursor_y -= 28.0;
        }

        self.push_campaign_sector_stats_rate_section(
            pass,
            self.localize_bundle_markup_text("@sectors.production"),
            &sector.info.production,
            &mut cursor_y,
            dialog,
            layer + 0.020,
        );
        self.push_campaign_sector_stats_rate_section(
            pass,
            self.localize_bundle_markup_text("@sectors.export"),
            &sector.info.export,
            &mut cursor_y,
            dialog,
            layer + 0.030,
        );
        if has_base {
            self.push_campaign_sector_stats_rate_section(
                pass,
                self.localize_bundle_markup_text("@sectors.import"),
                &sector.info.imports,
                &mut cursor_y,
                dialog,
                layer + 0.040,
            );
        }

        if has_base && !sector.info.items.is_empty() {
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@sectors.stored"),
                RenderPoint::new(dialog.x + 30.0, cursor_y),
                [0.84, 0.92, 1.0, 1.0],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Start)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                layer + 0.050,
            ));
            cursor_y -= 24.0;
            let stored_names = sector
                .info
                .items
                .iter()
                .filter(|(_, amount)| *amount > 0)
                .map(|(name, _)| name.clone())
                .collect::<Vec<_>>();
            self.push_campaign_sector_stats_item_icons(
                pass,
                &stored_names,
                dialog.x + 42.0,
                cursor_y,
                layer + 0.051,
            );
        }

        self.push_settings_text_button(
            pass,
            Self::campaign_sector_stats_close_rect(dialog),
            self.localize_bundle_markup_text("@back"),
            Some("left"),
            layer + 0.090,
        );
        self.push_settings_text_button_enabled(
            pass,
            Self::campaign_sector_stats_abandon_rect(dialog),
            self.localize_bundle_markup_text("@sector.abandon"),
            Some("cancel"),
            layer + 0.091,
            has_base,
        );
    }

    fn active_menu_route_shell_cache_rebuilds(&self) -> u64 {
        self.active_menu_route_shell_cache_rebuilds.get()
    }

    fn push_discord_route_page(&self, pass: &mut RenderPass, panel: RenderRect) {
        let layer = Layer::END_PIXELED + 0.021;
        let card = Self::discord_route_content_rect_for_panel(panel);
        let color = [
            0x72 as f32 / 255.0,
            0x89 as f32 / 255.0,
            0xda as f32 / 255.0,
            1.0,
        ];
        let dark_color = [color[0] * 0.8, color[1] * 0.8, color[2] * 0.8, color[3]];

        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("button"),
            card,
            [1.0, 1.0, 1.0, 0.96],
            0.0,
            layer,
        ));
        let stripe = RenderRect::new(
            card.x,
            card.y + 5.0,
            DISCORD_DIALOG_COLOR_STRIPE_WIDTH,
            (card.height - 5.0).max(1.0),
        );
        pass.push(RenderCommand::fill_rect(stripe, color, layer + 0.001));
        pass.push(RenderCommand::fill_rect(
            RenderRect::new(
                card.x,
                card.y,
                DISCORD_DIALOG_COLOR_STRIPE_WIDTH,
                5.0_f32.min(card.height),
            ),
            dark_color,
            layer + 0.002,
        ));
        pass.push(RenderCommand::draw_text_styled(
            desktop_ui_icon_glyph_or_label("discord", "link"),
            RenderPoint::new(
                card.x + DISCORD_DIALOG_COLOR_STRIPE_WIDTH + card.height * 0.5,
                card.center().y,
            ),
            [1.0, 1.0, 1.0, 1.0],
            34.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_font(RenderFontId::Icon)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true),
            layer + 0.003,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@discord"),
            RenderPoint::new(
                card.x + DISCORD_DIALOG_COLOR_STRIPE_WIDTH + card.height + 10.0,
                card.center().y,
            ),
            [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
            SETTINGS_JAVA_DEFAULT_FONT_SIZE,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_wrap_width(
                    card.width - DISCORD_DIALOG_COLOR_STRIPE_WIDTH - card.height - 22.0,
                )
                .with_integer_position(true),
            layer + 0.004,
        ));
    }

    fn push_active_menu_route_shell(
        &self,
        pass: &mut RenderPass,
        viewport: RenderViewport,
        frame_index: u64,
    ) {
        let Some(route) = self.active_menu_route else {
            return;
        };

        let panel = Self::active_menu_route_shell_panel_for_route(viewport, route);
        self.push_cached_active_menu_route_shell_commands(pass, route, viewport, panel);
        if route == DesktopMenuRoute::Campaign {
            self.push_campaign_route_page(pass, panel);
        } else if route == DesktopMenuRoute::About {
            self.push_about_route_page(pass, panel);
        } else if route == DesktopMenuRoute::Join {
            self.push_join_route_page(pass, viewport, panel, frame_index);
        } else if route == DesktopMenuRoute::Host {
            self.push_host_route_page(pass, panel);
        } else if matches!(
            route,
            DesktopMenuRoute::LoadGame | DesktopMenuRoute::SaveGame
        ) {
            self.push_load_game_route_page(pass, viewport, panel);
        } else if route == DesktopMenuRoute::Database {
            self.push_database_route_page(pass, panel);
        } else if route == DesktopMenuRoute::TechTree {
            self.push_tech_tree_route_page(pass, panel);
        } else if matches!(
            route,
            DesktopMenuRoute::CustomGame | DesktopMenuRoute::Editor
        ) {
            self.push_map_list_route_page(pass, panel, route);
        } else if route == DesktopMenuRoute::Schematics {
            self.push_schematics_route_page(pass, panel);
        } else if route == DesktopMenuRoute::Mods {
            self.push_mods_route_page(pass, viewport, panel);
        } else if route == DesktopMenuRoute::Discord {
            self.push_discord_route_page(pass, panel);
        } else if route == DesktopMenuRoute::Settings
            && self.settings_dialog_state.page == DesktopSettingsPage::Main
        {
            self.push_settings_main_menu_buttons(pass, panel);
            self.push_settings_route_buttons(pass, panel);
        } else if route == DesktopMenuRoute::Settings
            && self.settings_dialog_state.page == DesktopSettingsPage::Data
        {
            self.push_settings_data_page(pass, panel);
            self.push_settings_route_buttons(pass, panel);
        } else if route == DesktopMenuRoute::Settings
            && self.settings_dialog_state.page == DesktopSettingsPage::DynamicCategory
        {
            self.push_settings_dynamic_category_page(pass, panel);
            self.push_settings_route_buttons(pass, panel);
        } else if route == DesktopMenuRoute::Settings
            && matches!(
                self.settings_dialog_state.page,
                DesktopSettingsPage::Game
                    | DesktopSettingsPage::Graphics
                    | DesktopSettingsPage::Sound
            )
        {
            self.push_settings_route_controls(pass, panel);
            self.push_settings_route_buttons(pass, panel);
        } else {
            for (index, line) in self.active_menu_route_shell_lines(route).iter().enumerate() {
                if route == DesktopMenuRoute::Settings && line.starts_with("button:") {
                    continue;
                }
                pass.push(RenderCommand::draw_text_styled(
                    self.localize_bundle_markup_text(line),
                    RenderPoint::new(
                        panel.x + panel.width * 0.5,
                        panel.y + panel.height - 118.0 - index as f32 * 20.0,
                    ),
                    [0.56, 0.64, 0.72, 1.0],
                    12.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true),
                    Layer::END_PIXELED + 0.02,
                ));
            }
            if route == DesktopMenuRoute::Settings {
                self.push_settings_route_controls(pass, panel);
                self.push_settings_route_buttons(pass, panel);
            }
        }
        if route == DesktopMenuRoute::Settings {
            self.push_settings_child_dialog(pass, panel);
            self.push_settings_data_confirm_dialog(pass, panel);
        }
        if route == DesktopMenuRoute::Discord {
            if let Some(back_rect) =
                Self::discord_route_shell_back_rect_for_viewport(viewport, route)
            {
                self.push_settings_text_button(
                    pass,
                    back_rect,
                    self.localize_bundle_markup_text("@back"),
                    Some("left"),
                    Layer::END_PIXELED + 0.030,
                );
            }
            if let Some(copy_rect) =
                Self::discord_route_shell_copy_rect_for_viewport(viewport, route)
            {
                self.push_settings_text_button(
                    pass,
                    copy_rect,
                    self.localize_bundle_markup_text("@copylink"),
                    Some("copy"),
                    Layer::END_PIXELED + 0.031,
                );
            }
            if let Some(open_rect) =
                Self::active_menu_route_shell_primary_rect_for_viewport(viewport, route)
            {
                self.push_settings_text_button(
                    pass,
                    open_rect,
                    self.localize_bundle_markup_text("@openlink"),
                    Some("discord"),
                    Layer::END_PIXELED + 0.032,
                );
            }
        } else if let Some(primary_rect) =
            Self::active_menu_route_shell_primary_rect_for_viewport(viewport, route)
        {
            let Some(label_key) = self.active_menu_route_shell_primary_label(route) else {
                return;
            };
            let primary_enabled = self.active_menu_route_shell_primary_enabled(route);
            let label = self.localize_bundle_markup_text(label_key);
            pass.push(RenderCommand::fill_rect(
                primary_rect,
                if primary_enabled {
                    [0.18, 0.35, 0.58, 0.92]
                } else {
                    [0.12, 0.14, 0.16, 0.72]
                },
                Layer::END_PIXELED + 0.03,
            ));
            pass.push(RenderCommand::draw_sprite(
                "button.9",
                primary_rect,
                if primary_enabled {
                    [1.0, 1.0, 1.0, 1.0]
                } else {
                    [0.56, 0.58, 0.60, 0.78]
                },
                0.0,
                Layer::END_PIXELED + 0.035,
            ));
            pass.push(RenderCommand::stroke_rect(
                primary_rect,
                if primary_enabled {
                    [0.58, 0.75, 0.92, 1.0]
                } else {
                    [0.32, 0.36, 0.40, 0.82]
                },
                1.0,
                Layer::END_PIXELED + 0.04,
            ));
            pass.push(RenderCommand::draw_text_styled(
                label,
                primary_rect.center(),
                if primary_enabled {
                    [0.95, 0.98, 1.0, 1.0]
                } else {
                    [0.60, 0.64, 0.68, 0.92]
                },
                16.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                Layer::END_PIXELED + 0.05,
            ));
        }
        if route != DesktopMenuRoute::Discord {
            if let Some(copy_rect) =
                Self::discord_route_shell_copy_rect_for_viewport(viewport, route)
            {
                pass.push(RenderCommand::fill_rect(
                    copy_rect,
                    [0.16, 0.24, 0.32, 0.9],
                    Layer::END_PIXELED + 0.03,
                ));
                pass.push(RenderCommand::draw_sprite(
                    "button.9",
                    copy_rect,
                    [1.0, 1.0, 1.0, 1.0],
                    0.0,
                    Layer::END_PIXELED + 0.035,
                ));
                pass.push(RenderCommand::stroke_rect(
                    copy_rect,
                    [0.48, 0.68, 0.82, 1.0],
                    1.0,
                    Layer::END_PIXELED + 0.04,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    self.localize_bundle_markup_text("@copylink"),
                    copy_rect.center(),
                    [0.9, 0.96, 1.0, 1.0],
                    15.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.05,
                ));
            }
        }
        if route == DesktopMenuRoute::Campaign && self.campaign_intro_select_dialog_open {
            self.push_campaign_intro_select_dialog(pass, viewport);
        }
        if route == DesktopMenuRoute::Campaign && self.campaign_serpulo_rework_notice_open {
            self.push_campaign_serpulo_rework_notice_dialog(pass, panel);
        }
        if route == DesktopMenuRoute::Campaign && self.campaign_rules_dialog_open {
            self.push_campaign_rules_dialog(pass, panel);
        }
        if route == DesktopMenuRoute::Campaign && self.campaign_launch_loadout_dialog_open {
            self.push_campaign_launch_loadout_dialog(pass, panel);
            if self.campaign_launch_resources_dialog_open {
                self.push_campaign_launch_resources_dialog(pass, panel);
            }
        }
        if route == DesktopMenuRoute::Campaign && self.campaign_sector_stats_dialog_open {
            self.push_campaign_sector_stats_dialog(pass, panel);
        }
    }

