    fn push_pause_banned_content_dialog(
        &self,
        pass: &mut RenderPass,
        dialog_parent: RenderRect,
        kind: DesktopBannedContentKind,
        rules: &Rules,
    ) {
        let layer = Layer::END_PIXELED + 0.230;
        let dialog = Self::map_play_banned_content_dialog_rect(dialog_parent);
        pass.push(RenderCommand::fill_rect(
            dialog_parent,
            [0.0, 0.0, 0.0, 0.52],
            layer,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            dialog,
            [1.0, 1.0, 1.0, 0.98],
            0.0,
            layer + 0.001,
        ));
        pass.push(RenderCommand::stroke_rect(
            dialog,
            [0.62, 0.82, 1.0, 0.96],
            2.0,
            layer + 0.002,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text(kind.selected_label_key()),
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 26.0),
            [0.94, 0.98, 1.0, 1.0],
            15.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.004,
        ));
        let search = Self::map_play_banned_content_search_rect(dialog);
        pass.push(RenderCommand::draw_sprite(
            Self::settings_text_button_symbol(
                "grayt",
                false,
                self.pause_custom_rules_banned_content_search_focused,
            ),
            search,
            if self.pause_custom_rules_banned_content_search_focused {
                [1.0, 1.0, 1.0, 0.96]
            } else {
                [1.0, 1.0, 1.0, 0.84]
            },
            0.0,
            layer + 0.005,
        ));
        pass.push(RenderCommand::draw_text_styled(
            desktop_ui_icon_glyph_or_label("zoom", "zoom"),
            RenderPoint::new(search.x + 20.0, search.center().y),
            [0.72, 0.82, 0.9, 1.0],
            13.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_font(RenderFontId::Icon)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.006,
        ));
        let search_text = if self.pause_custom_rules_banned_content_search.is_empty() {
            self.localize_bundle_markup_text_or("@search", "Search")
        } else {
            self.pause_custom_rules_banned_content_search.clone()
        };
        pass.push(RenderCommand::draw_text_styled(
            search_text,
            RenderPoint::new(search.x + 40.0, search.center().y),
            if self.pause_custom_rules_banned_content_search.is_empty() {
                [0.60, 0.70, 0.78, 1.0]
            } else {
                [0.90, 0.96, 1.0, 1.0]
            },
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Start)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_wrap_width((search.width - 80.0).max(80.0))
                .with_integer_position(true),
            layer + 0.007,
        ));
        let clear = Self::map_play_banned_content_search_clear_rect(dialog);
        pass.push(RenderCommand::draw_text_styled(
            desktop_ui_icon_glyph_or_label("cancel", "x"),
            clear.center(),
            [0.72, 0.82, 0.9, 1.0],
            12.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_font(RenderFontId::Icon)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.008,
        ));
        if kind == DesktopBannedContentKind::Blocks {
            for (category_index, category) in Category::ALL.into_iter().enumerate() {
                self.push_map_list_filter_icon_toggle(
                    pass,
                    Self::map_play_banned_content_category_rect(dialog, category_index),
                    desktop_ui_icon_glyph_or_label(category.wire_name(), category.wire_name()),
                    self.pause_custom_rules_banned_content_selected_category == Some(category),
                    true,
                    layer + 0.009 + category_index as f32 * 0.0002,
                );
            }
            if let Some(category) = self.pause_custom_rules_banned_content_selected_category {
                pass.push(RenderCommand::draw_text_styled(
                    category.wire_name(),
                    RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 132.0),
                    [0.62, 0.74, 0.84, 0.92],
                    8.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true),
                    layer + 0.011,
                ));
            }
        }
        for (selected_side, label, color) in [
            (true, kind.selected_label_key(), [0.95, 0.44, 0.42, 1.0]),
            (
                false,
                kind.deselected_label_key(),
                [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, 1.0],
            ),
        ] {
            let grid = Self::map_play_banned_content_grid_rect(dialog, selected_side);
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text(label),
                RenderPoint::new(grid.center().x, dialog.y + dialog.height - 138.0),
                color,
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                layer + 0.006,
            ));
            pass.push(RenderCommand::stroke_rect(
                RenderRect::new(grid.x, dialog.y + dialog.height - 150.0, grid.width, 1.0),
                color,
                1.0,
                layer + 0.007,
            ));
        }

        let max_scroll = self.pause_banned_content_max_scroll_offset(dialog, kind, rules);
        let scroll = self
            .pause_custom_rules_banned_content_scroll_offset
            .min(max_scroll);
        for (selected_side, color) in [
            (true, [1.0, 0.78, 0.78, 0.34]),
            (false, [1.0, 1.0, 1.0, 0.24]),
        ] {
            let grid = Self::map_play_banned_content_grid_rect(dialog, selected_side);
            let columns = Self::map_play_banned_content_grid_columns(grid);
            let visible_capacity = columns * Self::map_play_banned_content_visible_rows(dialog);
            let entries = self.pause_banned_content_column_entries(kind, rules, selected_side);
            for (visible_index, entry) in entries
                .iter()
                .skip(scroll * columns)
                .take(visible_capacity)
                .enumerate()
            {
                let row =
                    Self::map_play_banned_content_item_rect(dialog, selected_side, visible_index);
                pass.push(RenderCommand::draw_sprite(
                    Self::settings_drawable_symbol("button"),
                    row,
                    color,
                    0.0,
                    layer + 0.010 + visible_index as f32 * 0.0005,
                ));
                let icon_symbol = match kind {
                    DesktopBannedContentKind::Blocks => self
                        .content_loader
                        .block_by_name(&entry.name)
                        .and_then(block_full_icon_region_symbol),
                    DesktopBannedContentKind::Units => {
                        unit_full_icon_region_symbol(&entry.name, &self.content_loader)
                    }
                }
                .filter(|symbol| self.texture_atlas.lookup(symbol.as_str()).is_ok());
                if let Some(symbol) = icon_symbol {
                    pass.push(RenderCommand::draw_sprite(
                        symbol,
                        RenderRect::from_center(row.center(), 32.0, 32.0),
                        [1.0, 1.0, 1.0, 1.0],
                        0.0,
                        layer + 0.011 + visible_index as f32 * 0.0005,
                    ));
                }
            }
            if entries.is_empty() {
                let row = Self::map_play_banned_content_item_rect(dialog, selected_side, 0);
                pass.push(RenderCommand::draw_text_styled(
                    self.localize_bundle_markup_text("@empty"),
                    row.center(),
                    [0.62, 0.70, 0.76, 0.80],
                    10.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true),
                    layer + 0.030,
                ));
            }
            self.push_settings_text_button(
                pass,
                Self::map_play_banned_content_add_all_rect(dialog, selected_side),
                self.localize_bundle_markup_text("@addall"),
                Some("add"),
                layer + 0.040,
            );
        }
        if max_scroll > 0 {
            pass.push(RenderCommand::draw_text_styled(
                format!("{}/{}", scroll + 1, max_scroll + 1),
                RenderPoint::new(dialog.right() - 42.0, dialog.y + 48.0),
                [0.62, 0.70, 0.76, 0.82],
                9.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.044,
            ));
        }
        self.push_settings_text_button(
            pass,
            Self::map_play_banned_content_close_rect(dialog),
            self.localize_bundle_markup_text("@back"),
            Some("left"),
            layer + 0.050,
        );
    }

    fn push_pause_weather_dialog(
        &self,
        pass: &mut RenderPass,
        dialog_parent: RenderRect,
        rules: &Rules,
    ) {
        let layer = Layer::END_PIXELED + 0.231;
        let dialog = Self::map_play_weather_dialog_rect(dialog_parent);
        pass.push(RenderCommand::fill_rect(
            dialog_parent,
            [0.0, 0.0, 0.0, 0.52],
            layer,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            dialog,
            [1.0, 1.0, 1.0, 0.98],
            0.0,
            layer + 0.001,
        ));
        pass.push(RenderCommand::stroke_rect(
            dialog,
            [0.62, 0.82, 1.0, 0.96],
            2.0,
            layer + 0.002,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@rules.weather"),
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 26.0),
            [0.94, 0.98, 1.0, 1.0],
            15.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            layer + 0.004,
        ));
        if rules.weather.is_empty() {
            pass.push(RenderCommand::draw_text_styled(
                self.localize_bundle_markup_text("@empty"),
                RenderPoint::new(dialog.center().x, dialog.center().y + 28.0),
                [0.62, 0.70, 0.76, 0.82],
                11.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.006,
            ));
        }
        let max_scroll = Self::map_play_weather_max_scroll_offset(dialog, rules.weather.len());
        let scroll = self
            .pause_custom_rules_weather_scroll_offset
            .min(max_scroll);
        let visible_rows = Self::map_play_weather_visible_entry_rows(dialog);
        let columns = Self::map_play_weather_entry_columns(dialog);
        let first_visible = scroll * columns;
        let last_visible = (scroll + visible_rows) * columns;
        let clip = Self::map_play_weather_entries_clip_rect(dialog);
        if !rules.weather.is_empty() {
            pass.push(RenderCommand::set_clip(clip));
            for (weather_index, entry) in rules
                .weather
                .iter()
                .enumerate()
                .skip(first_visible)
                .take(last_visible.saturating_sub(first_visible))
            {
                let row =
                    Self::map_play_weather_entry_rect_with_scroll(dialog, weather_index, scroll);
                pass.push(RenderCommand::draw_sprite(
                    Self::settings_drawable_symbol("button"),
                    row,
                    [1.0, 1.0, 1.0, 0.28],
                    0.0,
                    layer + 0.010 + weather_index as f32 * 0.001,
                ));
                let display_name = self
                    .content_loader
                    .weather_by_name(&entry.weather)
                    .map(|weather| weather.weather().localized_name().to_string())
                    .unwrap_or_else(|| entry.weather.clone());
                pass.push(RenderCommand::draw_text_styled(
                    display_name,
                    RenderPoint::new(row.x + 10.0, row.y + row.height - 14.0),
                    [0.90, 0.96, 1.0, 1.0],
                    10.5,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    layer + 0.011 + weather_index as f32 * 0.001,
                ));
                for (field_index, number) in DesktopWeatherNumber::ALL.into_iter().enumerate() {
                    let field = Self::map_play_weather_entry_number_rect(row, field_index);
                    let button_layer =
                        layer + 0.012 + weather_index as f32 * 0.001 + field_index as f32 * 0.0001;
                    self.push_settings_text_button_enabled(
                        pass,
                        Self::map_play_weather_entry_number_button_rect(field, false),
                        "-",
                        None,
                        button_layer,
                        !entry.always,
                    );
                    self.push_settings_text_button_enabled(
                        pass,
                        Self::map_play_weather_entry_number_button_rect(field, true),
                        "+",
                        None,
                        button_layer + 0.00002,
                        !entry.always,
                    );
                    pass.push(RenderCommand::draw_text_styled(
                        format!("{} {}", number.label(), number.value_text(entry)),
                        RenderPoint::new(field.center().x, field.center().y),
                        if entry.always {
                            [0.46, 0.52, 0.58, 0.78]
                        } else {
                            [0.72, 0.84, 0.92, 0.96]
                        },
                        8.0,
                        0.0,
                        RenderTextStyle::new(RenderTextAlign::Center)
                            .with_vertical_align(RenderTextVerticalAlign::Center)
                            .with_integer_position(true),
                        button_layer + 0.00004,
                    ));
                }
                self.push_settings_text_button(
                    pass,
                    Self::map_play_weather_entry_always_rect(row),
                    format!(
                        "{} {}",
                        if entry.always { "✓" } else { "□" },
                        self.localize_bundle_markup_text("@rules.weather.always")
                    ),
                    None,
                    layer + 0.013 + weather_index as f32 * 0.001,
                );
                self.push_settings_text_button(
                    pass,
                    Self::map_play_weather_entry_remove_rect(row),
                    "X",
                    None,
                    layer + 0.014 + weather_index as f32 * 0.001,
                );
            }
            pass.push(RenderCommand::ClearClip);
        }
        if max_scroll > 0 {
            pass.push(RenderCommand::draw_text_styled(
                format!("{}/{}", scroll + 1, max_scroll + 1),
                RenderPoint::new(dialog.right() - 42.0, dialog.y + 48.0),
                [0.62, 0.70, 0.76, 0.82],
                9.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true),
                layer + 0.044,
            ));
        }
        self.push_settings_text_button(
            pass,
            Self::map_play_weather_add_button_rect(dialog),
            self.localize_bundle_markup_text("@add"),
            Some("add"),
            layer + 0.049,
        );
        self.push_settings_text_button(
            pass,
            Self::map_play_weather_close_rect(dialog),
            self.localize_bundle_markup_text("@back"),
            Some("left"),
            layer + 0.050,
        );
        if self.pause_custom_rules_weather_add_dialog_open {
            self.push_pause_weather_add_dialog(pass, dialog, rules);
        }
    }

