    fn push_pause_overlay_modal(&self, pass: &mut RenderPass, panel: RenderRect) {
        let Some(modal) = self.pause_overlay_modal else {
            return;
        };
        if modal == DesktopPausedOverlayModal::CustomRules {
            self.push_pause_overlay_custom_rules_modal(pass, panel);
            return;
        }
        if modal == DesktopPausedOverlayModal::WorldProcessors {
            self.push_pause_world_processors_dialog(pass, panel);
            return;
        }
        let dialog = Self::pause_overlay_modal_rect_for_panel(panel);
        let (title, body): (&str, String) = match modal {
            DesktopPausedOverlayModal::Objective => {
                ("@objective", self.pause_overlay_objective_text())
            }
            DesktopPausedOverlayModal::Abandon => ("@abandon", "@abandon.confirm".into()),
            DesktopPausedOverlayModal::CustomRules => unreachable!(),
            DesktopPausedOverlayModal::WorldProcessors => unreachable!("handled above"),
            DesktopPausedOverlayModal::QuitConfirm => ("@confirm", "@quit.confirm".into()),
        };

        pass.push(RenderCommand::fill_rect(
            dialog,
            [0.04, 0.06, 0.08, 0.94],
            Layer::END_PIXELED + 0.160,
        ));
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            dialog,
            [1.0, 1.0, 1.0, 0.98],
            0.0,
            Layer::END_PIXELED + 0.161,
        ));
        pass.push(RenderCommand::stroke_rect(
            dialog,
            [0.50, 0.70, 0.84, 0.96],
            2.0,
            Layer::END_PIXELED + 0.162,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text(title),
            RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 30.0),
            [0.94, 0.98, 1.0, 1.0],
            14.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            Layer::END_PIXELED + 0.163,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text(&body),
            RenderPoint::new(dialog.center().x, dialog.center().y + 4.0),
            [0.78, 0.86, 0.92, 1.0],
            11.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_wrap_width(dialog.width - 52.0)
                .with_integer_position(true),
            Layer::END_PIXELED + 0.165,
        ));
        if modal == DesktopPausedOverlayModal::QuitConfirm {
            self.push_settings_text_button(
                pass,
                Self::pause_overlay_modal_cancel_rect(dialog),
                "@cancel",
                None,
                Layer::END_PIXELED + 0.166,
            );
            self.push_settings_text_button(
                pass,
                Self::pause_overlay_modal_ok_rect(dialog),
                "@ok",
                None,
                Layer::END_PIXELED + 0.166,
            );
        } else {
            self.push_settings_text_button(
                pass,
                Self::pause_overlay_modal_close_rect(dialog),
                "@back",
                Some("left"),
                Layer::END_PIXELED + 0.166,
            );
        }
    }

    fn pause_overlay_render_pass(&self, viewport: RenderViewport) -> Option<RenderPass> {
        if !self.has_renderable_world_for_default_frame()
            || (!self.game_state.is_paused()
                && !self.game_state.game_over
                && self.active_menu_route.is_none()
                && self.campaign_complete_dialog.is_none())
        {
            return None;
        }

        let mut pass = RenderPass::new(RenderPassKind::Ui)
            .with_order(RenderPassKind::Ui.default_order() + 1)
            .with_viewport(viewport)
            .with_camera(self.default_render_camera_for_viewport(viewport));
        pass.push(RenderCommand::fill_rect(
            viewport.as_rect(),
            [0.0, 0.0, 0.0, 0.36],
            Layer::END_PIXELED + 0.140,
        ));

        if self.campaign_complete_dialog.is_some() {
            self.push_campaign_complete_dialog_like_java(&mut pass, viewport);
            return Some(pass);
        }

        if self.active_menu_route.is_some() {
            self.push_active_menu_route_shell(&mut pass, viewport, 0);
            return Some(pass);
        }

        if self.game_state.game_over {
            let dialog = Self::game_over_dialog_rect_for_viewport(viewport);
            pass.push(RenderCommand::draw_sprite(
                Self::settings_drawable_symbol("pane"),
                dialog,
                [1.0, 1.0, 1.0, 0.97],
                0.0,
                Layer::END_PIXELED + 0.141,
            ));
            pass.push(RenderCommand::stroke_rect(
                dialog,
                [0.52, 0.68, 0.82, 0.95],
                2.0,
                Layer::END_PIXELED + 0.142,
            ));
            pass.push(RenderCommand::draw_text_styled(
                self.game_over_title_text(),
                RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 34.0),
                [0.94, 0.98, 1.0, 1.0],
                15.0,
                0.0,
                RenderTextStyle::new(RenderTextAlign::Center)
                    .with_vertical_align(RenderTextVerticalAlign::Center)
                    .with_integer_position(true)
                    .with_outline(true),
                Layer::END_PIXELED + 0.143,
            ));
            if self.game_over_is_high_score() {
                pass.push(RenderCommand::draw_text_styled(
                    self.localize_bundle_markup_text("@highscore"),
                    RenderPoint::new(dialog.center().x, dialog.y + dialog.height - 62.0),
                    [1.0, 0.82, 0.42, 1.0],
                    11.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.1435,
                ));
            }
            let stats_rect = Self::game_over_stats_rect(dialog);
            pass.push(RenderCommand::draw_sprite(
                "whiteui",
                stats_rect,
                [0.0, 0.0, 0.0, 0.34],
                0.0,
                Layer::END_PIXELED + 0.144,
            ));
            for (index, (label, value)) in self.game_over_stat_rows().into_iter().enumerate() {
                let row_y = stats_rect.y + stats_rect.height - 18.0 - index as f32 * 28.0;
                pass.push(RenderCommand::draw_text_styled(
                    label,
                    RenderPoint::new(stats_rect.x + 14.0, row_y),
                    [0.86, 0.92, 0.98, 1.0],
                    10.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.145 + index as f32 * 0.0001,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    value.to_string(),
                    RenderPoint::new(stats_rect.right() - 14.0, row_y),
                    [1.0, 0.82, 0.42, 1.0],
                    10.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::End)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.1455 + index as f32 * 0.0001,
                ));
            }
            if let Some(playtime) = self.game_over_playtime_text() {
                let row_y = stats_rect.y + 18.0;
                pass.push(RenderCommand::draw_text_styled(
                    self.localize_bundle_markup_text("@stats.playtime"),
                    RenderPoint::new(stats_rect.x + 14.0, row_y),
                    [0.86, 0.92, 0.98, 1.0],
                    10.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Start)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.146,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    format!("[accent]{playtime}"),
                    RenderPoint::new(stats_rect.right() - 14.0, row_y),
                    [1.0, 0.82, 0.42, 1.0],
                    10.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::End)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.1465,
                ));
            }
            if self.game_state.is_campaign() && self.pause_overlay_net_active() {
                pass.push(RenderCommand::draw_text_styled(
                    self.localize_bundle_markup_text("@gameover.waiting"),
                    RenderPoint::new(dialog.center().x, dialog.y + 100.0),
                    [0.94, 0.98, 1.0, 1.0],
                    10.0,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.147,
                ));
            }
            self.push_settings_text_button(
                &mut pass,
                Self::game_over_menu_button_rect(dialog),
                self.game_over_primary_button_label(),
                Some("left"),
                Layer::END_PIXELED + 0.150,
            );
            return Some(pass);
        }

        let button_specs = self.pause_overlay_button_specs();
        let panel = self.pause_overlay_panel_for_current_state(viewport);
        pass.push(RenderCommand::draw_sprite(
            Self::settings_drawable_symbol("pane"),
            panel,
            [1.0, 1.0, 1.0, 0.96],
            0.0,
            Layer::END_PIXELED + 0.141,
        ));
        pass.push(RenderCommand::stroke_rect(
            panel,
            [0.40, 0.58, 0.70, 0.92],
            2.0,
            Layer::END_PIXELED + 0.142,
        ));
        pass.push(RenderCommand::draw_text_styled(
            self.localize_bundle_markup_text("@menu"),
            RenderPoint::new(panel.center().x, panel.y + panel.height - 25.0),
            [0.94, 0.98, 1.0, 1.0],
            13.0,
            0.0,
            RenderTextStyle::new(RenderTextAlign::Center)
                .with_vertical_align(RenderTextVerticalAlign::Center)
                .with_integer_position(true)
                .with_outline(true),
            Layer::END_PIXELED + 0.143,
        ));
        let button_rects = self.pause_overlay_button_rects_for_panel(panel, &button_specs);
        for (index, spec) in button_specs.into_iter().enumerate() {
            self.push_settings_text_button_enabled(
                &mut pass,
                button_rects[index],
                spec.label,
                spec.icon,
                Layer::END_PIXELED + 0.145 + index as f32 * 0.0001,
                spec.enabled,
            );
        }
        if self.pause_overlay_custom_rules_visible() {
            let custom = Self::pause_overlay_custom_rules_button_rect_for_viewport(viewport);
            self.push_settings_text_button(
                &mut pass,
                custom,
                self.localize_bundle_markup_text("@customize"),
                Some("book"),
                Layer::END_PIXELED + 0.154,
            );
            if self
                .last_menu_cursor
                .is_some_and(|cursor| custom.contains_point(cursor))
            {
                let label = self.localize_bundle_markup_text("@customize");
                let tooltip = RenderRect::new(
                    custom.right() + 10.0,
                    custom.center().y - 17.0,
                    (label.len() as f32 * 7.0 + 28.0).clamp(92.0, 260.0),
                    34.0,
                );
                pass.push(RenderCommand::draw_sprite(
                    Self::settings_drawable_symbol("pane"),
                    tooltip,
                    [1.0, 1.0, 1.0, 0.94],
                    0.0,
                    Layer::END_PIXELED + 0.155,
                ));
                pass.push(RenderCommand::draw_text_styled(
                    label,
                    tooltip.center(),
                    [0.92, 0.97, 1.0, 1.0],
                    9.5,
                    0.0,
                    RenderTextStyle::new(RenderTextAlign::Center)
                        .with_vertical_align(RenderTextVerticalAlign::Center)
                        .with_integer_position(true)
                        .with_outline(true),
                    Layer::END_PIXELED + 0.156,
                ));
            }
        }
        self.push_pause_overlay_modal(&mut pass, panel);
        Some(pass)
    }

    fn menu_graphics_frame_for_surface(
        &mut self,
        frame_index: u64,
        viewport: RenderViewport,
    ) -> DesktopGraphicsFrame {
        self.external_bundle_active_frame_index
            .set(Some(frame_index));
        self.content_icon_runtime_registry_active_frame_index
            .set(Some(frame_index));
        if self.active_menu_route == Some(DesktopMenuRoute::Settings)
            && self.settings_child_dialog == Some(DesktopSettingsChildDialog::Language)
        {
            self.materialize_settings_default_locale_like_java();
        }
        let input = self.menu_frame_input_for_viewport(viewport);
        self.menu_renderer_state
            .set_locale(self.settings_locale.clone());
        let mut plan = self
            .menu_renderer_state
            .render_plan_without_ui_render_commands(input);
        self.finalize_menu_frame_plan_for_desktop_visuals(&mut plan);
        let mut menu_pass = if desktop_fast_menu_enabled() {
            self.fast_menu_render_pass_from_plan(&mut plan, viewport)
        } else {
            plan.into_render_pass().unwrap_or_else(|| {
                let camera = self.default_render_camera_for_viewport(viewport);
                let mut pass = RenderPass::new(RenderPassKind::Custom("menu".to_string()))
                    .with_viewport(viewport)
                    .with_camera(camera);
                pass.push(RenderCommand::clear([0.0, 0.0, 0.0, 1.0]));
                self.push_menu_empty_plan_fallback(&mut pass, viewport);
                pass
            })
        };

        let frame_viewport = menu_pass.viewport.unwrap_or(viewport);
        self.insert_menu_background_layers(&mut menu_pass, frame_viewport);
        self.ensure_visible_mods_browser_icon_requests_for_viewport(frame_viewport);
        self.sync_external_bundle_loaded_notice_like_java();
        self.push_active_menu_route_shell(&mut menu_pass, frame_viewport, frame_index);
        self.push_menu_info_message(&mut menu_pass, frame_viewport);
        self.push_menu_guard_message(&mut menu_pass, frame_viewport);
        if !matches!(
            self.active_menu_route,
            Some(DesktopMenuRoute::LoadGame | DesktopMenuRoute::SaveGame)
        ) {
            self.push_load_game_error_dialog(&mut menu_pass, frame_viewport);
        }
        self.push_menu_boot_diagnostics(&mut menu_pass, frame_viewport);
        self.push_mobile_terminal_overlay(&mut menu_pass, frame_viewport);
        self.push_menu_logo_and_version_chrome(&mut menu_pass, frame_viewport);
        self.tick_save_game_pending_save();
        self.tick_load_game_pending_load();
        self.tick_host_pending_run();
        self.tick_join_font_ignore_dirty_task_like_java();
        self.ensure_menu_pass_has_screen_visible_commands(&mut menu_pass, frame_viewport);
        let camera = menu_pass
            .camera
            .unwrap_or_else(|| self.default_render_camera_for_viewport(frame_viewport));
        let mut render_frame = RenderFramePlan::new(
            frame_index,
            RenderSize::new(frame_viewport.width, frame_viewport.height),
            camera,
            frame_viewport,
        );
        render_frame.push_pass(menu_pass);

        let mut bridge = RenderBridge::new();
        bridge.set_render_frame(render_frame);
        let frame = DesktopGraphicsFrame {
            bundle: bridge.finish(),
            floor_chunk_batches: Vec::new(),
            minimap_texture_frame: None,
            font_glyph_upload_plan: Some(self.cached_font_glyph_upload_plan_for_frame()),
            texture_atlas: Arc::clone(&self.texture_atlas),
            mod_texture_source_bytes: Arc::clone(&self.mod_texture_source_bytes),
        };
        self.external_bundle_active_frame_index.set(None);
        self.content_icon_runtime_registry_active_frame_index
            .set(None);
        frame
    }

