    #[derive(Debug, Default)]
    struct RecordingPlatform {
        open_result: bool,
        opened_uris: Vec<String>,
        opened_folders: Vec<String>,
        file_chooser_requests: Vec<FileChooserRequest>,
        shared_files: Vec<String>,
        viewed_listing_ids: Vec<String>,
        viewed_listings: Vec<String>,
        published: Vec<String>,
        invited_friends: usize,
        clipboard_texts: Vec<String>,
        clipboard_read: Option<String>,
    }

    impl Platform for RecordingPlatform {
        fn invite_friends(&mut self) {
            self.invited_friends += 1;
        }

        fn open_uri(&mut self, uri: &str) -> bool {
            self.opened_uris.push(uri.to_string());
            self.open_result
        }

        fn open_folder(&mut self, path: &str) -> bool {
            self.opened_folders.push(path.to_string());
            self.open_result
        }

        fn share_file(&mut self, file: &str) {
            self.shared_files.push(file.to_string());
        }

        fn show_file_chooser(
            &mut self,
            open: bool,
            title: &str,
            extension: &str,
        ) -> FileChooserRequest {
            let request = FileChooserRequest::new(open, title, extension);
            self.file_chooser_requests.push(request.clone());
            request
        }

        fn view_listing(&mut self, publishable_name: &str) {
            self.viewed_listings.push(publishable_name.to_string());
        }

        fn view_listing_id(&mut self, map_id: &str) {
            self.viewed_listing_ids.push(map_id.to_string());
        }

        fn publish(&mut self, publishable_name: &str) {
            self.published.push(publishable_name.to_string());
        }

        fn set_clipboard_text(&mut self, text: &str) {
            self.clipboard_texts.push(text.to_string());
            self.clipboard_read = Some(text.to_string());
        }

        fn get_clipboard_text(&mut self) -> Option<String> {
            self.clipboard_read.clone()
        }
    }

    fn free_local_port() -> u16 {
        for _ in 0..1024 {
            let tcp = TcpListener::bind("127.0.0.1:0").unwrap();
            let port = tcp.local_addr().unwrap().port();
            if UdpSocket::bind(("127.0.0.1", port)).is_ok() {
                return port;
            }
        }
        panic!("could not reserve a local TCP/UDP port pair");
    }

    #[derive(Clone, Default)]
    struct RecordingHostProvider {
        host_ports: Arc<Mutex<Vec<u16>>>,
    }

    impl NetProvider for RecordingHostProvider {
        fn connect_client(
            &mut self,
            _ip: &str,
            _port: u16,
            _success: Box<dyn Fn() + Send + 'static>,
        ) -> io::Result<()> {
            Ok(())
        }

        fn send_client(&mut self, _object: &PacketKind, _reliable: bool) -> io::Result<()> {
            Ok(())
        }

        fn disconnect_client(&mut self) {}

        fn discover_servers(
            &self,
            _callback: mindustry_core::mindustry::net::HostCallback,
            done: mindustry_core::mindustry::net::DoneCallback,
        ) {
            done();
        }

        fn ping_host(
            &self,
            _address: &str,
            _port: u16,
            _timeout: Duration,
        ) -> io::Result<mindustry_core::mindustry::net::Host> {
            Err(io::Error::new(
                io::ErrorKind::Unsupported,
                "recording host provider does not ping",
            ))
        }

        fn host_server(&mut self, port: u16) -> io::Result<()> {
            self.host_ports.lock().unwrap().push(port);
            Ok(())
        }

        fn get_connections(&self) -> Vec<mindustry_core::mindustry::net::NetConnection> {
            Vec::new()
        }

        fn close_server(&mut self) {}
    }

    #[derive(Clone)]
    struct FailingHostProvider {
        message: &'static str,
    }

    impl NetProvider for FailingHostProvider {
        fn connect_client(
            &mut self,
            _ip: &str,
            _port: u16,
            _success: Box<dyn Fn() + Send + 'static>,
        ) -> io::Result<()> {
            Ok(())
        }

        fn send_client(&mut self, _object: &PacketKind, _reliable: bool) -> io::Result<()> {
            Ok(())
        }

        fn disconnect_client(&mut self) {}

        fn discover_servers(
            &self,
            _callback: mindustry_core::mindustry::net::HostCallback,
            done: mindustry_core::mindustry::net::DoneCallback,
        ) {
            done();
        }

        fn ping_host(
            &self,
            _address: &str,
            _port: u16,
            _timeout: Duration,
        ) -> io::Result<mindustry_core::mindustry::net::Host> {
            Err(io::Error::new(io::ErrorKind::Unsupported, self.message))
        }

        fn host_server(&mut self, _port: u16) -> io::Result<()> {
            Err(io::Error::new(io::ErrorKind::AddrInUse, self.message))
        }

        fn get_connections(&self) -> Vec<mindustry_core::mindustry::net::NetConnection> {
            Vec::new()
        }

        fn close_server(&mut self) {}
    }

