    #[test]
    fn desktop_frame_loop_resize_and_scale_factor_reuse_font_upload_plan_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let mut frame_loop =
            DesktopFrameLoopState::new(Default::default(), DesktopFramePacing::uncapped());
        let mut graphics_renderer = HeadlessDesktopGraphicsRenderer::default();
        let mut effect_renderer = HeadlessDesktopEffectRenderer::default();

        let first_result = launcher.step_desktop_frame_loop(
            &mut frame_loop,
            &[DesktopFrameLoopEvent::Tick],
            &mut graphics_renderer,
            &mut effect_renderer,
        );
        assert!(first_result.presented);
        assert_eq!(launcher.font_glyph_upload_plan_cache_rebuilds(), 1);
        let first_plan = launcher
            .font_glyph_upload_plan_cache
            .as_ref()
            .expect("first menu frame should populate the Java-like font upload cache")
            .plan
            .clone();

        let scaled_result = launcher.step_desktop_frame_loop(
            &mut frame_loop,
            &[DesktopFrameLoopEvent::ScaleFactorChanged(1.75)],
            &mut graphics_renderer,
            &mut effect_renderer,
        );
        assert!(scaled_result.presented);
        assert_eq!(scaled_result.surface.scale_factor, 1.75);
        assert_eq!(
            launcher.font_glyph_upload_plan_cache_rebuilds(),
            1,
            "Java Fonts are not regenerated by a DPI scale event; the Rust frontend must not rebuild the font atlas plan on every scale-factor frame"
        );
        assert_eq!(
            launcher
                .font_glyph_upload_plan_cache
                .as_ref()
                .expect("scale-factor menu frame should keep the font upload cache")
                .plan,
            first_plan
        );

        let resized_result = launcher.step_desktop_frame_loop(
            &mut frame_loop,
            &[DesktopFrameLoopEvent::Resize(DesktopSurfaceSize::new(
                1600, 900,
            ))],
            &mut graphics_renderer,
            &mut effect_renderer,
        );
        assert!(resized_result.presented);
        assert_eq!(
            resized_result.surface.size,
            DesktopSurfaceSize::new(1600, 900)
        );
        assert_eq!(
            launcher.font_glyph_upload_plan_cache_rebuilds(),
            1,
            "Java Fonts atlas state is independent from window size; resizing the frontend must not cause a low-FPS font upload rebuild loop"
        );
        assert_eq!(
            launcher
                .font_glyph_upload_plan_cache
                .as_ref()
                .expect("resized menu frame should keep the font upload cache")
                .plan,
            first_plan
        );
    }

    #[test]
    fn desktop_frame_loop_uncapped_menu_delta_uses_elapsed_time_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let mut frame_loop =
            DesktopFrameLoopState::new(Default::default(), DesktopFramePacing::uncapped());
        frame_loop.last_frame_instant = Some(Instant::now() - Duration::from_millis(8));
        let mut graphics_renderer = HeadlessDesktopGraphicsRenderer::default();
        let mut effect_renderer = HeadlessDesktopEffectRenderer::default();

        let result = launcher.step_desktop_frame_loop(
            &mut frame_loop,
            &[DesktopFrameLoopEvent::Tick],
            &mut graphics_renderer,
            &mut effect_renderer,
        );

        assert!(result.presented);
        assert!(
            (1.0 / 240.0..=0.050).contains(&launcher.menu_frame_delta_seconds),
            "Java ClientLauncher updates Time from real graphics delta; uncapped Rust menu delta should use elapsed time instead of hard-coded 1/60, got {}",
            launcher.menu_frame_delta_seconds
        );
        assert!(
            (launcher.menu_frame_delta_seconds - (1.0 / 60.0)).abs() > 0.002,
            "uncapped menu delta should no longer be the fixed 60fps fallback after the first frame"
        );
        assert!(frame_loop.last_frame_instant.is_some());
    }

    #[test]
    fn desktop_frame_loop_paced_sleep_only_after_successful_present() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let mut frame_loop = DesktopFrameLoopState::new(
            Default::default(),
            DesktopFramePacing::new(std::time::Duration::from_millis(16)),
        );
        let mut graphics_renderer = HeadlessDesktopGraphicsRenderer::default();
        let mut effect_renderer = HeadlessDesktopEffectRenderer::default();
        let mut sleep_durations = Vec::new();
        let mut poll_count = 0u32;

        let summary = launcher.run_with_desktop_frame_loop(
            &mut frame_loop,
            &mut graphics_renderer,
            &mut effect_renderer,
            None,
            |_| {
                poll_count += 1;
                match poll_count {
                    1 => vec![DesktopFrameLoopEvent::Tick],
                    2 => vec![DesktopFrameLoopEvent::CloseRequested],
                    _ => panic!("paced loop should stop after the close request"),
                }
            },
            |_| {},
            |duration| sleep_durations.push(duration),
        );

        assert_eq!(summary.exit_reason, DesktopFrameLoopExitReason::Closed);
        assert_eq!(summary.steps, 2);
        assert_eq!(summary.frames_presented, 1);
        assert_eq!(summary.last_frame_index, Some(0));
        assert_eq!(poll_count, 2);
        assert_eq!(graphics_renderer.frames_rendered, 1);
        assert_eq!(effect_renderer.frames_rendered, 1);
        assert_eq!(sleep_durations, vec![std::time::Duration::from_millis(16)]);
    }

    #[test]
    fn desktop_frame_loop_closed_state_short_circuits_without_poll_render_or_sleep() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let mut frame_loop = DesktopFrameLoopState::new(
            Default::default(),
            DesktopFramePacing::new(std::time::Duration::from_millis(16)),
        );
        frame_loop.closed = true;
        let mut graphics_renderer = HeadlessDesktopGraphicsRenderer::default();
        let mut effect_renderer = HeadlessDesktopEffectRenderer::default();

        let summary = launcher.run_with_desktop_frame_loop(
            &mut frame_loop,
            &mut graphics_renderer,
            &mut effect_renderer,
            None,
            |_| panic!("closed loop state should short-circuit before polling"),
            |_| panic!("closed loop state should not reach after-present"),
            |_| panic!("closed loop state should not sleep"),
        );

        assert_eq!(summary.exit_reason, DesktopFrameLoopExitReason::Closed);
        assert_eq!(summary.steps, 0);
        assert_eq!(summary.frames_presented, 0);
        assert_eq!(summary.last_frame_index, None);
        assert!(frame_loop.closed);
        assert_eq!(graphics_renderer.frames_rendered, 0);
        assert_eq!(effect_renderer.frames_rendered, 0);
    }

