    #[test]
    fn desktop_launcher_default_atlas_resolves_menu_background_tile_symbols() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.font_locale = "en".into();
        launcher
            .settings_overrides
            .insert("locale".into(), "en".into());

        for symbol in [
            "sand",
            "sand-wall",
            "shale",
            "shale-wall",
            "stone",
            "stone-wall",
            "ore-copper",
            "ore-lead",
            "ore-coal",
            "ore-titanium",
            "ore-thorium",
        ] {
            assert!(
                launcher.texture_atlas.has(symbol),
                "menu background tile sprite `{symbol}` should resolve from the default atlas"
            );
        }
        let sand_floor = launcher
            .texture_atlas
            .lookup("sand-floor1")
            .expect("menu floor atlas symbol should resolve");
        assert_eq!(
            sand_floor.page_type,
            PageType::Environment,
            "menu background terrain sprites should resolve in the upstream environment page"
        );
        assert!(
            sand_floor.region.source_path.is_empty(),
            "native menu rendering should use the packed upstream environment atlas page; direct raw terrain PNGs expose transparent debug pixels in OpenGL"
        );
    }

    #[test]
    fn desktop_playable_smoke_ready_after_world_stream_and_confirm() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let content = launcher.content_loader.clone();
        let mut server_runtime = GameRuntime::default();
        let smoke = server_runtime.seed_playable_smoke_world(&content);
        let default_team = TeamId(server_runtime.state.rules.default_team as u8);
        let (spawn_x, spawn_y) = server_runtime
            .state
            .teams
            .get_or_null(default_team.0)
            .and_then(|team| team.core())
            .map(|core| (core.x, core.y))
            .expect("smoke core spawn should exist");
        let mut player = NetworkPlayerData::bootstrap();
        player.team = default_team;
        player.name = Some("smoke-client".into());
        player.x = spawn_x;
        player.y = spawn_y;

        let world_data = NetworkWorldData {
            map_tags: server_runtime.state.map.tags.clone(),
            player_id: 77,
            player: Some(player),
            map_snapshot: Some(server_runtime.export_network_map_snapshot(&content)),
            ..NetworkWorldData::default()
        };

        launcher.client.setup();
        {
            let state = launcher.net_client.state();
            let mut state = state.lock().unwrap();
            state.connected = true;
            state.connect_confirm_sent = true;
            state.last_loaded_world_data = Some(world_data);
        }

        launcher.show_loading_fragment_like_java("@connecting.data");
        launcher.set_loading_fragment_button_like_java();
        assert!(launcher.loading_fragment_state.visible);

        launcher.update();

        let status = launcher.playable_smoke_status();
        assert!(status.ready(), "{status:?}, smoke={smoke:?}");
        assert!(launcher.playable_smoke_ready());
        assert!(
            !launcher.loading_fragment_state.visible,
            "world data completion and connect confirm should hide the Java LoadingFragmentState"
        );
        assert_eq!(status.world_width, 16);
        assert_eq!(status.world_height, 16);
        assert_eq!(status.buildings, 1);
    }

