    #[test]
    fn desktop_graphics_font_atlas_seed_scans_upstream_bundle_texts_like_java() {
        let seed = super::desktop_real_font_atlas_seed_characters();
        for text in [
            "Restart required to apply changes.",
            "开始游戏",
            "繁體中文",
            "Mechanical Fishe",
        ] {
            for character in text.chars().filter(|character| !character.is_control()) {
                assert!(
                    seed.contains(&character),
                    "font atlas seed should include bundle text character U+{:04X} '{}' from '{}'",
                    character as u32,
                    character,
                    text
                );
            }
        }
        assert!(
            seed.contains(&'設') && seed.contains(&'語'),
            "asset bundle scanner should include non-hardcoded Japanese bundle glyphs before Fonts.loadExtraFonts-style override"
        );
        assert!(
            seed.contains(&super::UPSTREAM_ROUTER_LANGUAGE_GLYPH),
            "router locale replacement glyph must be available to the default text atlas"
        );
    }

    #[test]
    fn desktop_graphics_font_atlas_japanese_override_uses_bundle_non_ascii_seed_like_java() {
        let seed = super::desktop_real_font_atlas_seed_characters();
        let override_seed = super::desktop_real_font_atlas_japanese_override_characters();
        assert!(override_seed.iter().all(|character| !character.is_ascii()));
        assert!(!override_seed.contains(&'P'));
        assert!(!override_seed.contains(&' '));
        for character in seed
            .iter()
            .copied()
            .filter(|character| !character.is_ascii())
            .take(32)
        {
            assert!(
                override_seed.contains(&character),
                "font_jp override seed should be derived from every non-ASCII UI/bundle seed character"
            );
        }
        assert!(
            override_seed.contains(&'設') && override_seed.contains(&'語'),
            "Japanese bundle text should feed the font_jp override source"
        );
    }

    #[test]
    fn desktop_graphics_font_atlas_japanese_override_adds_late_non_ascii_glyphs_without_placeholder(
    ) {
        use ab_glyph::{Font as _, GlyphId};

        let seed = super::desktop_real_font_atlas_seed_characters();
        let font_path = super::default_desktop_font_asset_source_traces()
            .into_iter()
            .find(|source| source.source_path == "fonts/font_jp.woff")
            .and_then(|source| source.file_path)
            .expect("upstream Fonts.loadExtraFonts should resolve fonts/font_jp.woff");
        let font_bytes = std::fs::read(&font_path).expect("font_jp.woff should be readable");
        let font_bytes = super::desktop_decode_woff1_to_sfnt(&font_bytes)
            .expect("font_jp.woff should decode to sfnt bytes");
        let font = super::FontArc::try_from_vec(font_bytes).expect("font_jp.woff should parse");
        let dynamic_character = (0x3040..=0x30ff)
            .chain(0x3400..=0x9fff)
            .filter_map(char::from_u32)
            .find(|character| !seed.contains(character) && font.glyph_id(*character) != GlyphId(0))
            .expect("font_jp.woff should contain at least one non-seeded CJK/kana glyph");

        let atlas_before = super::desktop_default_real_font_atlas_for_locale("ja")
            .expect("Japanese font atlas should build before incremental registration");
        let key = super::DesktopRealFontGlyphKey::new(RenderFontId::Default, dynamic_character)
            .expect("dynamic Japanese glyph key should exist");
        assert!(
            !atlas_before.glyphs.contains_key(&key),
            "test glyph should start outside the pre-baked Rust seed so DrawText exercises Java font_jp incremental behavior"
        );

        let quads = super::opengl_backend_primitive_quads_from_action_for_locale(
            &super::DesktopGraphicsOpenGlBackendAdapterAction::DrawText {
                text: format!("Probe{dynamic_character}"),
                position: RenderPoint::new(0.0, 0.0),
                color: [1.0, 1.0, 1.0, 1.0],
                size: 18.0,
                rotation: 0.0,
                align: RenderTextAlign::Start,
                style: RenderTextStyle::default(),
                layer: Layer::OVERLAY_UI,
            },
            Some(RenderTarget::Screen),
            super::opengl_backend_default_sprite_shader_program(),
            super::DesktopGraphicsOpenGlBackendBlendState::default(),
            None,
            "ja",
        );

        assert!(
            super::desktop_external_font_seed_characters().contains(&dynamic_character),
            "Java font_jp incremental loading should be mirrored by registering the late Japanese glyph into the Rust font seed"
        );
        let atlas_after = super::desktop_default_real_font_atlas_for_locale("ja").expect(
            "Japanese incremental atlas should rebuild after registering a supported glyph",
        );
        assert!(
            atlas_after.glyphs.contains_key(&key),
            "registered Japanese glyph U+{:04X} '{}' should be present in the rebuilt real font atlas",
            dynamic_character as u32,
            dynamic_character
        );
        assert!(
            quads.iter().any(|quad| {
                quad.symbol == format!("font:Default:DrawText:U+{:04X}", dynamic_character as u32)
            }),
            "DrawText should use a real font_jp glyph for U+{:04X} '{}', not the primitive placeholder path",
            dynamic_character as u32,
            dynamic_character
        );
    }

    #[test]
    fn desktop_graphics_font_atlas_loads_font_jp_only_for_japanese_locale_and_overrides() {
        let traces = super::default_desktop_font_asset_source_traces();
        let english_sources =
            super::desktop_default_real_font_atlas_sources_for_locale(&traces, "en");
        let japanese_sources =
            super::desktop_default_real_font_atlas_sources_for_locale(&traces, "ja");

        assert!(
            english_sources.iter().all(|source| !source
                .file_path
                .replace('\\', "/")
                .ends_with("/font_jp.woff")),
            "Java Fonts.loadExtraFonts gates font_jp behind Locale language == ja"
        );
        assert!(
            japanese_sources
                .iter()
                .any(|source| source.file_path.replace('\\', "/").ends_with("/font_jp.woff")
                    && source.font_id == RenderFontId::Default
                    && source.override_existing),
            "Japanese locale should load font_jp as Fonts.def.data.setOverride, not a passive fallback"
        );
        assert!(
            japanese_sources
                .iter()
                .any(|source| source.file_path.replace('\\', "/").ends_with("/font_jp.woff")
                    && source.font_id == RenderFontId::Outline
                    && source.override_existing),
            "Java Fonts.loadExtraFonts also loads font_jp_outline and calls Fonts.outline.data.setOverride"
        );

        let default_source = japanese_sources
            .iter()
            .find(|source| source.file_path.replace('\\', "/").ends_with("/font.woff"))
            .cloned()
            .expect("upstream Fonts.def should resolve fonts/font.woff");
        let japanese_source = japanese_sources
            .iter()
            .find(|source| {
                source
                    .file_path
                    .replace('\\', "/")
                    .ends_with("/font_jp.woff")
            })
            .cloned()
            .expect("upstream Fonts.loadExtraFonts should resolve fonts/font_jp.woff");
        let default_atlas = super::desktop_build_real_font_atlas(&[default_source.clone()])
            .expect("default font source should rasterize");
        let japanese_atlas = super::desktop_build_real_font_atlas(&[japanese_source.clone()])
            .expect("font_jp source should rasterize");

        let glyph_metrics_differ =
            |left: &super::DesktopRealFontGlyph, right: &super::DesktopRealFontGlyph| {
                (left.width - right.width).abs() > 0.001
                    || (left.height - right.height).abs() > 0.001
                    || (left.offset_x - right.offset_x).abs() > 0.001
                    || (left.offset_y - right.offset_y).abs() > 0.001
                    || (left.advance - right.advance).abs() > 0.001
            };
        let primary_key = default_atlas
            .glyphs
            .iter()
            .find_map(|(key, default_glyph)| {
                if key.font_key != super::DesktopRealFontGlyphKey::DEFAULT
                    || key.character.is_ascii()
                {
                    return None;
                }
                japanese_atlas
                    .glyphs
                    .get(key)
                    .filter(|japanese_glyph| glyph_metrics_differ(default_glyph, japanese_glyph))
                    .map(|_| *key)
            })
            .expect("font.woff and font_jp.woff should share at least one non-ASCII glyph with distinct metrics");

        let combined_atlas = super::desktop_build_real_font_atlas(&[
            default_source.clone(),
            japanese_source.clone(),
        ])
        .expect("combined default/font_jp atlas should rasterize");
        let default_glyph = default_atlas
            .glyphs
            .get(&primary_key)
            .expect("primary glyph should exist in default font");
        let combined_glyph = combined_atlas
            .glyphs
            .get(&primary_key)
            .expect("combined atlas should keep a glyph for the shared codepoint");
        let japanese_glyph = japanese_atlas
            .glyphs
            .get(&primary_key)
            .expect("candidate glyph should exist in font_jp");

        assert!(
            glyph_metrics_differ(default_glyph, combined_glyph),
            "font_jp should behave like Arc FontData.setOverride and overwrite glyph U+{:04X} '{}' in Japanese locale",
            primary_key.character as u32,
            primary_key.character
        );
        assert!(
            !glyph_metrics_differ(japanese_glyph, combined_glyph),
            "combined Japanese atlas should take the font_jp metrics for the shared override glyph"
        );
    }

    #[test]
    fn desktop_graphics_font_atlas_rasterizes_bundle_locale_glyphs_like_java() {
        let atlas = super::desktop_default_real_font_atlas()
            .expect("upstream Fonts.def/font_jp should build a real glyph atlas");
        for character in ['缩', '體', '設', '語'] {
            let key = super::DesktopRealFontGlyphKey::new(RenderFontId::Default, character)
                .expect("bundle locale glyph key should exist");
            let glyph = atlas.glyphs.get(&key).unwrap_or_else(|| {
                panic!(
                    "bundle locale glyph U+{:04X} '{}' should be rasterized from upstream font/font_jp, not placeholder text",
                    character as u32, character
                )
            });
            assert!(
                glyph.width > 0.0 && glyph.height > 0.0,
                "bundle locale glyph U+{:04X} '{}' should have real glyph bounds",
                character as u32,
                character
            );
        }
    }

    #[test]
    fn desktop_graphics_opengl_backend_draw_text_default_applies_java_font_shadow() {
        let quads = super::opengl_backend_primitive_quads_from_action(
            &super::DesktopGraphicsOpenGlBackendAdapterAction::DrawText {
                text: "Play".to_string(),
                position: RenderPoint::new(48.0, 48.0),
                color: [1.0, 1.0, 1.0, 1.0],
                size: 18.0,
                rotation: 0.0,
                align: RenderTextAlign::Start,
                style: RenderTextStyle::default(),
                layer: Layer::OVERLAY_UI,
            },
            Some(RenderTarget::Screen),
            super::opengl_backend_default_sprite_shader_program(),
            super::DesktopGraphicsOpenGlBackendBlendState::default(),
            None,
        );

        assert!(!quads.is_empty());
        let base_count = quads
            .iter()
            .filter(|quad| {
                (quad.layer - Layer::OVERLAY_UI).abs() < 0.0001
                    && quad.vertices[0].color == [1.0, 1.0, 1.0, 1.0]
            })
            .count();
        let shadow_count = quads
            .iter()
            .filter(|quad| {
                (quad.layer - (Layer::OVERLAY_UI - 0.000_05)).abs() < 0.000_01
                    && quad.vertices[0].color == super::DESKTOP_DEFAULT_FONT_SHADOW_COLOR
            })
            .count();
        assert!(base_count > 0);
        assert_eq!(
            shadow_count, base_count,
            "Java Fonts.def uses Color.darkGray shadowOffsetY=2; default font quads must emit a matching shadow pass"
        );
    }

