    #[test]
    fn desktop_graphics_opengl_backend_markup_colors_real_font_foreground_like_java() {
        let base_color = [0.82, 0.90, 1.0, 1.0];
        let quads = super::opengl_backend_primitive_quads_from_action(
            &super::DesktopGraphicsOpenGlBackendAdapterAction::DrawText {
                text: "[accent]A[]B".to_string(),
                position: RenderPoint::new(48.0, 48.0),
                color: base_color,
                size: 18.0,
                rotation: 0.0,
                align: RenderTextAlign::Start,
                style: RenderTextStyle::default(),
                layer: Layer::OVERLAY_UI,
            },
            Some(RenderTarget::Screen),
            super::opengl_backend_default_sprite_shader_program(),
            super::DesktopGraphicsOpenGlBackendBlendState::default(),
            None,
        );
        let accent = [Pal::ACCENT.r, Pal::ACCENT.g, Pal::ACCENT.b, base_color[3]];
        let a_color = quads
            .iter()
            .find(|quad| {
                (quad.layer - Layer::OVERLAY_UI).abs() < 0.000_01 && quad.symbol.ends_with("U+0041")
            })
            .map(|quad| quad.vertices[0].color)
            .expect("markup text should draw foreground A glyph");
        let b_color = quads
            .iter()
            .find(|quad| {
                (quad.layer - Layer::OVERLAY_UI).abs() < 0.000_01 && quad.symbol.ends_with("U+0042")
            })
            .map(|quad| quad.vertices[0].color)
            .expect("markup text should draw foreground B glyph");

        assert_eq!(
            a_color, accent,
            "Java Fonts.def markupEnabled applies [accent] to foreground glyphs"
        );
        assert_eq!(
            b_color, base_color,
            "Java [] resets markup color back to the draw call base color"
        );
        assert!(
            quads
                .iter()
                .filter(|quad| { (quad.layer - (Layer::OVERLAY_UI - 0.000_05)).abs() < 0.000_01 })
                .all(|quad| quad.vertices[0].color == super::DESKTOP_DEFAULT_FONT_SHADOW_COLOR),
            "Java default font shadow remains dark gray and is not recolored by foreground markup"
        );
    }

    #[test]
    fn desktop_graphics_opengl_backend_real_font_layout_keeps_newline_char_color_indices() {
        super::desktop_real_font_text_layout_cache_clear();
        let atlas = super::desktop_default_real_font_atlas()
            .expect("upstream default font atlas should be available");
        let layout = super::opengl_backend_real_font_text_layout(
            "AB\nC",
            &atlas,
            RenderFontId::Default,
            18.0,
        )
        .expect("real font text layout should resolve seeded glyphs");

        assert_eq!(layout.lines.len(), 2);
        assert_eq!(
            layout.glyph_count, 3,
            "shared layout should cache the visible glyph count for repeated shadow/outline passes"
        );
        assert_eq!(
            layout.lines[0]
                .glyphs
                .iter()
                .map(|glyph| glyph.char_index)
                .collect::<Vec<_>>(),
            vec![0, 1],
            "foreground markup colors index visible glyphs before the newline"
        );
        assert_eq!(
            layout.lines[1]
                .glyphs
                .iter()
                .map(|glyph| glyph.char_index)
                .collect::<Vec<_>>(),
            vec![3],
            "shared layout must keep the skipped newline index so Java-style markup colors stay aligned"
        );
    }

    #[test]
    fn desktop_graphics_opengl_backend_real_font_layout_cache_reuses_stable_text_like_java() {
        super::desktop_real_font_text_layout_cache_clear();
        let atlas = super::desktop_default_real_font_atlas()
            .expect("upstream default font atlas should be available");

        let first = super::opengl_backend_real_font_text_layout(
            "Play",
            &atlas,
            RenderFontId::Default,
            18.0,
        )
        .expect("first real font layout should build");
        let second = super::opengl_backend_real_font_text_layout(
            "Play",
            &atlas,
            RenderFontId::Default,
            18.0,
        )
        .expect("stable real font layout should be cached");
        assert!(
            Arc::ptr_eq(&first, &second),
            "stable menu text should reuse the cached real font layout across frames"
        );
        assert!(
            first
                .lines
                .iter()
                .flat_map(|line| line.glyphs.iter())
                .all(|glyph| glyph.quad_binding.source_png_bytes.is_none()),
            "cached glyph layout should prebake per-glyph texture bindings without cloning the full font atlas during shadow/outline passes"
        );

        let resized = super::opengl_backend_real_font_text_layout(
            "Play",
            &atlas,
            RenderFontId::Default,
            19.0,
        )
        .expect("different font size should build a distinct layout");
        assert!(
            !Arc::ptr_eq(&first, &resized),
            "font size changes alter Java glyph scale and must not reuse stale layout metrics"
        );

        let mut changed_atlas = (*atlas).clone();
        changed_atlas.source_key_digest = changed_atlas.source_key_digest.wrapping_add(1);
        let changed = super::opengl_backend_real_font_text_layout(
            "Play",
            &changed_atlas,
            RenderFontId::Default,
            18.0,
        )
        .expect("atlas source changes should build a distinct layout");
        assert!(
            !Arc::ptr_eq(&first, &changed),
            "atlas source changes can move glyph UVs and must not reuse the old cached layout"
        );
    }

    #[test]
    fn desktop_graphics_opengl_backend_real_font_layout_cache_evicts_cold_entries_without_full_clear(
    ) {
        super::desktop_real_font_text_layout_cache_clear();
        let atlas = super::desktop_default_real_font_atlas()
            .expect("upstream default font atlas should be available");
        let hot = super::opengl_backend_real_font_text_layout(
            "Play",
            &atlas,
            RenderFontId::Default,
            18.0,
        )
        .expect("stable menu text should build");

        for index in 0..(super::DESKTOP_REAL_FONT_TEXT_LAYOUT_CACHE_MAX_ENTRIES + 16) {
            let a = ((index / (26 * 26)) % 26) as u8 + b'A';
            let b = ((index / 26) % 26) as u8 + b'A';
            let c = (index % 26) as u8 + b'A';
            let cold = format!("Cold {}{}{}", a as char, b as char, c as char);
            super::opengl_backend_real_font_text_layout(&cold, &atlas, RenderFontId::Default, 18.0)
                .expect("cold real font text should build");

            let still_hot = super::opengl_backend_real_font_text_layout(
                "Play",
                &atlas,
                RenderFontId::Default,
                18.0,
            )
            .expect("hot menu text should remain cached");
            assert!(
                Arc::ptr_eq(&hot, &still_hot),
                "front-end menus reuse stable labels every frame; cache pressure should evict cold rows without clearing hot text layouts"
            );
        }

        assert!(
            super::desktop_real_font_text_layout_cache_len()
                <= super::DESKTOP_REAL_FONT_TEXT_LAYOUT_CACHE_MAX_ENTRIES,
            "layout cache must stay bounded while avoiding full-cache clear storms"
        );
    }

    #[test]
    fn desktop_graphics_opengl_backend_real_font_quad_bindings_do_not_clone_atlas_pixels_per_glyph()
    {
        let atlas = super::desktop_default_real_font_atlas()
            .expect("upstream default font atlas should be available");
        let glyph = atlas
            .glyphs
            .values()
            .next()
            .copied()
            .expect("real font atlas should contain glyphs");

        let quad_binding = super::opengl_backend_font_glyph_atlas_texture_binding_for_quad(
            "font:Default:DrawText:U+0050",
            &atlas,
            glyph.uv,
            glyph.width.ceil() as u32,
            glyph.height.ceil() as u32,
        );
        let upload_binding = super::opengl_backend_font_glyph_atlas_texture_binding(
            "font:DrawText",
            &atlas,
            [0.0, 0.0, 1.0, 1.0],
            atlas.texture_width,
            atlas.texture_height,
        );

        assert!(
            quad_binding.source_png_bytes.is_none(),
            "per-glyph draw quads must not clone the whole runtime font atlas on every menu text pass"
        );
        assert!(
            upload_binding.source_png_bytes.is_some(),
            "the resource-table binding still carries atlas pixels for the actual OpenGL upload"
        );
        assert_eq!(
            quad_binding.texture_identity.key,
            super::DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY
        );
    }

    #[test]
    fn desktop_graphics_opengl_backend_reuses_uploaded_font_atlas_binding_without_pixel_clone_for_stable_fps(
    ) {
        let atlas = super::desktop_default_real_font_atlas()
            .expect("upstream default font atlas should be available");
        let upload_binding = super::opengl_backend_font_glyph_atlas_texture_binding(
            "font:DrawText",
            &atlas,
            [0.0, 0.0, 1.0, 1.0],
            atlas.texture_width,
            atlas.texture_height,
        );
        let mut executor = super::DesktopGraphicsOpenGlBackendExecutor::default();
        executor
            .state
            .sprite_texture_resource_table
            .register_binding(&upload_binding);
        {
            let resource = executor
                .state
                .sprite_texture_resource_table
                .resources
                .get_mut(super::DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY)
                .expect("font atlas resource should be registered before DrawText");
            assert!(
                resource.source_png_bytes.is_some(),
                "the first font atlas registration may carry pixels for upload"
            );
            resource.identity = resource.identity.clone().with_uploaded_gl_handle(77, 1);
            resource.applied_sampler = Some(resource.sampler);
        }

        let target = RenderTarget::Screen;
        executor.consume_opengl_backend_step(opengl_backend_test_step(
            0,
            target.clone(),
            DesktopGraphicsOpenGlBackendStepKind::BeginPass,
        ));
        executor.consume_opengl_backend_step(opengl_backend_test_step(
            0,
            target.clone(),
            DesktopGraphicsOpenGlBackendStepKind::Command {
                kind: "DrawText",
                command: RenderCommand::draw_text(
                    "Play",
                    RenderPoint::new(48.0, 48.0),
                    [1.0, 1.0, 1.0, 1.0],
                    18.0,
                    0.0,
                    RenderTextAlign::Start,
                    Layer::OVERLAY_UI,
                ),
                resolved_sprite: None,
            },
        ));
        executor.consume_opengl_backend_step(opengl_backend_test_step(
            0,
            target,
            DesktopGraphicsOpenGlBackendStepKind::EndPass,
        ));

        let resource = executor
            .state
            .sprite_texture_resource_table
            .get(super::DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY)
            .expect("DrawText should keep the runtime font atlas resource registered");
        assert_eq!(
            resource.identity.gl_handle,
            Some(77),
            "stable text frames must keep reusing the uploaded Java font atlas texture"
        );
        assert!(
            resource.source_png_bytes.is_none(),
            "after the atlas has a GL handle, per-frame DrawText resource registration must not clone the whole font atlas pixels"
        );
    }

