    #[test]
    fn desktop_graphics_opengl_backend_markup_respects_java_font_markup_enabled_flags() {
        assert!(super::opengl_backend_text_markup_enabled(
            RenderTextStyle::default().with_font(RenderFontId::Default)
        ));
        assert!(super::opengl_backend_text_markup_enabled(
            RenderTextStyle::default().with_font(RenderFontId::Outline)
        ));
        for font in [
            RenderFontId::Icon,
            RenderFontId::IconLarge,
            RenderFontId::Logic,
            RenderFontId::Tech,
            RenderFontId::Monospace,
        ] {
            assert!(
                !super::opengl_backend_text_markup_enabled(
                    RenderTextStyle::default().with_font(font)
                ),
                "Java only sets Fonts.def/Fonts.outline markupEnabled=true; {font:?} should not parse color tags by default"
            );
        }

        let base_color = [0.82, 0.90, 1.0, 1.0];
        let red = super::opengl_backend_rgba_color(0xff0000ff, base_color[3]);
        let default_quads = super::opengl_backend_text_placeholder_quads(
            "[red]A[]",
            RenderPoint::new(12.0, 24.0),
            base_color,
            18.0,
            0.0,
            RenderTextAlign::Start,
            RenderTextStyle::default().with_font(RenderFontId::Default),
            Layer::OVERLAY_UI,
            Some(RenderTarget::Screen),
            super::opengl_backend_default_sprite_shader_program(),
            super::DesktopGraphicsOpenGlBackendBlendState::default(),
            None,
        );
        assert!(
            default_quads
                .iter()
                .any(|quad| quad.vertices[0].color == red),
            "Fonts.def markupEnabled=true should parse [red]"
        );

        let tech_quads = super::opengl_backend_text_placeholder_quads(
            "[red]A[]",
            RenderPoint::new(12.0, 24.0),
            base_color,
            18.0,
            0.0,
            RenderTextAlign::Start,
            RenderTextStyle::default().with_font(RenderFontId::Tech),
            Layer::OVERLAY_UI,
            Some(RenderTarget::Screen),
            super::opengl_backend_default_sprite_shader_program(),
            super::DesktopGraphicsOpenGlBackendBlendState::default(),
            None,
        );
        assert!(
            tech_quads
                .iter()
                .all(|quad| quad.vertices[0].color == base_color),
            "Fonts.tech is not markupEnabled in Java; Rust must keep literal bracket text at the base color instead of parsing [red]"
        );
        assert!(
            tech_quads.len() > default_quads.len(),
            "non-markup fonts should keep the literal [red]...[] characters instead of stripping tags"
        );
    }

