    #[test]
    fn desktop_graphics_opengl_backend_outline_font_uses_java_border_width() {
        let atlas = super::desktop_default_real_font_atlas()
            .expect("upstream default/outline font atlas should be available");
        let default_key = super::DesktopRealFontGlyphKey::new(RenderFontId::Default, 'P')
            .expect("default glyph key should exist");
        let outline_key = super::DesktopRealFontGlyphKey::new(RenderFontId::Outline, 'P')
            .expect("outline glyph key should exist");
        let default_glyph = atlas
            .glyphs
            .get(&default_key)
            .expect("Fonts.def glyph should be rasterized");
        let outline_glyph = atlas
            .glyphs
            .get(&outline_key)
            .expect("Fonts.outline glyph should be rasterized as a separate atlas entry");
        let border = super::DESKTOP_OUTLINE_FONT_BORDER_WIDTH;
        assert!(
            outline_glyph.width >= default_glyph.width + border * 2.0
                && outline_glyph.height >= default_glyph.height + border * 2.0,
            "Java Fonts.outline sets FreeType borderWidth=Scl.scl(2f); the real Outline glyph bitmap should expand by the 2px border"
        );
        assert!(
            outline_glyph.offset_x <= default_glyph.offset_x - border
                && outline_glyph.offset_y >= default_glyph.offset_y + border,
            "prebaked Outline glyph bounds should include the Java border on both axes"
        );
        assert!(atlas.pixels.chunks_exact(4).any(|pixel| {
            pixel[0] == super::DESKTOP_FONT_DARK_GRAY_RGBA8[0]
                && pixel[1] == super::DESKTOP_FONT_DARK_GRAY_RGBA8[1]
                && pixel[2] == super::DESKTOP_FONT_DARK_GRAY_RGBA8[2]
                && pixel[3] > 0
        }));
    }

    #[test]
    fn desktop_graphics_opengl_backend_outline_font_matches_java_space_x_adjustment() {
        let atlas = super::desktop_default_real_font_atlas()
            .expect("upstream default/outline font atlas should be available");
        let default_width =
            super::opengl_backend_real_font_text_line_width("PP", &atlas, RenderFontId::Default)
                .expect("default font should measure two glyphs");
        let outline_width =
            super::opengl_backend_real_font_text_line_width("PP", &atlas, RenderFontId::Outline)
                .expect("outline font should measure two glyphs");

        assert!(
            (outline_width - (default_width - super::DESKTOP_OUTLINE_FONT_BORDER_WIDTH * 2.0))
                .abs()
                < 0.01,
            "Java Fonts.loadDefaultFont applies spaceX -= borderWidth for outline fonts, so every outline glyph advance should be tightened by the 2px border width"
        );

        let outline_quads = super::opengl_backend_primitive_quads_from_action(
            &super::DesktopGraphicsOpenGlBackendAdapterAction::DrawText {
                text: "PP".to_string(),
                position: RenderPoint::new(120.0, 48.0),
                color: [1.0, 1.0, 1.0, 1.0],
                size: 18.0,
                rotation: 0.0,
                align: RenderTextAlign::Center,
                style: RenderTextStyle::default().with_font(RenderFontId::Outline),
                layer: Layer::OVERLAY_UI,
            },
            Some(RenderTarget::Screen),
            super::opengl_backend_default_sprite_shader_program(),
            super::DesktopGraphicsOpenGlBackendBlendState::default(),
            None,
        );
        assert_eq!(
            outline_quads.len(),
            2,
            "Fonts.outline should render two prebaked Outline glyph quads for 'PP', not runtime duplicate outline/shadow layers"
        );
        assert!(
            outline_quads.iter().all(|quad| {
                (quad.layer - Layer::OVERLAY_UI).abs() < 0.00001
                    && quad.symbol.starts_with("font:Outline:DrawText:")
            }),
            "Java spaceX adjustment should be expressed through the Outline glyph advances, not through extra runtime layers"
        );
    }

    #[test]
    fn desktop_graphics_opengl_backend_outline_font_uses_prebaked_border_without_runtime_shadow_like_java(
    ) {
        let quads = super::opengl_backend_primitive_quads_from_action(
            &super::DesktopGraphicsOpenGlBackendAdapterAction::DrawText {
                text: "P".to_string(),
                position: RenderPoint::new(48.0, 48.0),
                color: [1.0, 1.0, 1.0, 1.0],
                size: 18.0,
                rotation: 0.0,
                align: RenderTextAlign::Start,
                style: RenderTextStyle::default().with_font(RenderFontId::Outline),
                layer: Layer::OVERLAY_UI,
            },
            Some(RenderTarget::Screen),
            super::opengl_backend_default_sprite_shader_program(),
            super::DesktopGraphicsOpenGlBackendBlendState::default(),
            None,
        );

        assert_eq!(
            quads.len(),
            1,
            "Java Fonts.outline is a separate prebaked border font; RenderFontId::Outline must not add runtime shadow/outline duplicate quads"
        );
        assert!(
            quads
                .iter()
                .all(|quad| quad.symbol.starts_with("font:Outline:DrawText:")),
            "RenderFontId::Outline should resolve through the Outline atlas key, not Default + runtime effects"
        );
    }

