    #[test]
    fn desktop_graphics_font_atlas_icon_large_uses_java_border_width() {
        let play = upstream_ui_icon_glyph_string("play").expect("Icon.play glyph should exist");
        let character = play
            .chars()
            .next()
            .expect("Icon.play should map to a single icon font glyph");
        let traces = super::default_desktop_font_asset_source_traces();
        let icon_large_source =
            super::desktop_default_real_font_atlas_sources_for_locale(&traces, "en")
                .into_iter()
                .find(|source| source.font_id == RenderFontId::IconLarge)
                .expect(
                    "Java Fonts.iconLarge should resolve fonts/icon.ttf into the real font atlas",
                );

        assert_eq!(icon_large_source.base_size, 48.0);
        assert_eq!(
            icon_large_source.border_width,
            super::DESKTOP_ICON_LARGE_FONT_BORDER_WIDTH
        );
        assert_eq!(
            icon_large_source.border_color,
            super::DESKTOP_ICON_LARGE_FONT_BORDER_COLOR
        );

        let mut plain_source = icon_large_source.clone();
        plain_source.border_width = 0;
        plain_source.border_color = [0, 0, 0, 0];
        let bordered_atlas = super::desktop_build_real_font_atlas(&[icon_large_source])
            .expect("bordered IconLarge atlas should build");
        let plain_atlas = super::desktop_build_real_font_atlas(&[plain_source])
            .expect("plain IconLarge atlas should build");
        let key = super::DesktopRealFontGlyphKey::new(RenderFontId::IconLarge, character)
            .expect("IconLarge should have a real font glyph key");
        let bordered = bordered_atlas
            .glyphs
            .get(&key)
            .expect("bordered IconLarge glyph should be present");
        let plain = plain_atlas
            .glyphs
            .get(&key)
            .expect("plain IconLarge glyph should be present");

        let border = super::DESKTOP_ICON_LARGE_FONT_BORDER_WIDTH as f32;
        assert!(
            bordered.width >= plain.width + border * 2.0
                && bordered.height >= plain.height + border * 2.0,
            "Java Fonts.iconLarge uses borderWidth=5, so the rasterized glyph bounds must expand by the dark gray border"
        );
        assert!((bordered.advance - plain.advance).abs() < 0.001);
        assert!(bordered.offset_x <= plain.offset_x - border);
        assert!(bordered.offset_y >= plain.offset_y + border);
        assert!(bordered_atlas.pixels.chunks_exact(4).any(|pixel| {
            pixel[0] == super::DESKTOP_ICON_LARGE_FONT_BORDER_COLOR[0]
                && pixel[1] == super::DESKTOP_ICON_LARGE_FONT_BORDER_COLOR[1]
                && pixel[2] == super::DESKTOP_ICON_LARGE_FONT_BORDER_COLOR[2]
                && pixel[3] > 0
        }));
        assert!(bordered_atlas.pixels.chunks_exact(4).any(|pixel| {
            pixel[0] == 255 && pixel[1] == 255 && pixel[2] == 255 && pixel[3] > 0
        }));
    }

