    struct EnvVarGuard {
        key: &'static str,
        previous: Option<std::ffi::OsString>,
        _lock: std::sync::MutexGuard<'static, ()>,
    }

    fn env_var_fixture_lock_for(key: &'static str) -> &'static Mutex<()> {
        static ASSET_ROOT_LOCK: OnceLock<Mutex<()>> = OnceLock::new();
        static ASSET_RAW_ROOT_LOCK: OnceLock<Mutex<()>> = OnceLock::new();
        static GENERIC_ENV_LOCK: OnceLock<Mutex<()>> = OnceLock::new();
        match key {
            "MINDUSTRY_ASSET_ROOT" => ASSET_ROOT_LOCK.get_or_init(|| Mutex::new(())),
            "MINDUSTRY_ASSET_RAW_ROOT" => ASSET_RAW_ROOT_LOCK.get_or_init(|| Mutex::new(())),
            _ => GENERIC_ENV_LOCK.get_or_init(|| Mutex::new(())),
        }
    }

    impl EnvVarGuard {
        fn set(key: &'static str, value: &std::path::Path) -> Self {
            let guard = env_var_fixture_lock_for(key)
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            let previous = std::env::var_os(key);
            std::env::set_var(key, value);
            Self {
                key,
                previous,
                _lock: guard,
            }
        }
    }

    impl Drop for EnvVarGuard {
        fn drop(&mut self) {
            if let Some(previous) = &self.previous {
                std::env::set_var(self.key, previous);
            } else {
                std::env::remove_var(self.key);
            }
        }
    }

    #[test]
    fn desktop_packed_atlas_source_path_matches_java_max_texture_gate() {
        assert_eq!(
            super::desktop_packed_atlas_source_path_for_max_texture_size(4096),
            "sprites/sprites.aatls",
            "Java ClientLauncher loads the main packed atlas when maxTextureSize >= 4096"
        );
        assert_eq!(
            super::desktop_packed_atlas_source_path_for_max_texture_size(8192),
            "sprites/sprites.aatls"
        );
        assert_eq!(
            super::desktop_packed_atlas_source_path_for_max_texture_size(4095),
            "sprites/fallback/sprites.aatls",
            "Java ClientLauncher switches to sprites/fallback/sprites.aatls below 4096"
        );
        assert_eq!(
            super::desktop_packed_atlas_source_path_for_max_texture_size(2048),
            "sprites/fallback/sprites.aatls"
        );
    }

    #[test]
    fn desktop_merge_packed_atlas_regions_uses_java_fallback_atlas_for_low_texture_size() {
        {
            let _max_texture_guard =
                EnvVarGuard::set("MINDUSTRY_MAX_TEXTURE_SIZE", std::path::Path::new("2048"));
            let mut atlas = TextureAtlasPlan::new();
            super::desktop_merge_packed_atlas_regions(&mut atlas);
            assert!(
                atlas
                    .page(PageType::Main)
                    .source_path
                    .replace('\\', "/")
                    .contains("sprites/fallback/"),
                "Java ClientLauncher should load sprites/fallback/sprites.aatls when GL max texture size is below 4096"
            );
        }

        {
            let _max_texture_guard =
                EnvVarGuard::set("MINDUSTRY_MAX_TEXTURE_SIZE", std::path::Path::new("4096"));
            let mut atlas = TextureAtlasPlan::new();
            super::desktop_merge_packed_atlas_regions(&mut atlas);
            let main_source = atlas.page(PageType::Main).source_path.replace('\\', "/");
            assert!(
                main_source.ends_with("sprites/sprites.png")
                    && !main_source.contains("sprites/fallback/"),
                "Java ClientLauncher should keep the main sprites.aatls path at the 4096 threshold"
            );
        }
    }

