    #[test]
    fn desktop_launcher_mods_route_renders_scanned_mod_cards_and_back_button() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.mods_directory_arg = Some("C:/mods directory".into());
        launcher.last_mods_directory_mod_names =
            vec!["alpha".into(), "beta".into(), "gamma".into()];
        launcher.last_mods_directory_mod_roots =
            vec!["C:/mods/alpha pack".into(), "C:/mods/beta".into()];
        launcher.last_mods_directory_mod_metas = vec![
            ModMetadata::from_source_text(
                "alpha",
                Some("mod.hjson"),
                r#"
name: alpha
displayName: "Alpha Pack"
author: "Alpha Author"
version: "1.0.0"
description: "Alpha fixture mod."
"#,
            ),
            ModMetadata::from_source_text(
                "beta",
                Some("mod.hjson"),
                r#"
name: beta
displayName: "Beta Override"
author: "Beta Author"
version: "2.0.0"
repo: "Beta/Override"
"#,
            ),
        ];
        launcher.last_mods_directory_merge_count = Some(3);
        launcher.dispatch_menu_action(MenuButtonRole::Mods);

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Mods,
        );
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let render_frame = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("mods route should render a frame");
        let commands = render_frame
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .copied()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&"Mods"));
        assert!(texts.contains(&"Alpha Pack"));
        assert!(texts.contains(&"Beta Override"));
        assert!(texts.contains(&"gamma"));
        assert!(!texts
            .iter()
            .any(|text| text.contains("Open Folder: alpha pack")));
        assert!(!texts
            .iter()
            .any(|text| text.contains("Repo Beta/Override") && text.contains("Reinstall")));
        assert!(!texts.iter().any(|text| text.contains("Install")));
        assert!(texts.contains(&"Back"));
        assert!(texts.contains(&"Open Folder"));
        assert!(texts.contains(&"Import Mod"));
        assert!(!texts.contains(&"browser search: Icon.zoom + Icon.list"));
        for raw_key in [
            "@mods.guide",
            "@mods.openfolder",
            "@mod.import",
            "@mods.browser",
            "@back",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "ModsDialog route final DrawText should localize {raw_key} before rendering"
            );
        }
        for shell_prefix in [
            "footer button:",
            "button:",
            "modal:",
            "event:",
            "browser:",
            "download:",
            "empty:",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(shell_prefix)),
                "ModsDialog visible DrawText should not leak Rust route-shell prefix {shell_prefix}"
            );
        }
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Mods);
        assert!(lines.contains(&"browser: BaseDialog @mods.browser".to_string()));
        assert!(
            !lines.iter().any(|line| line.starts_with("mods scanned:")),
            "Java ModsDialog does not expose Rust-only scan-count diagnostics in the visible route shell"
        );
        let main_button_specs = launcher.mods_route_main_button_specs();
        assert_eq!(
            main_button_specs
                .iter()
                .map(|(_, label, _)| *label)
                .collect::<Vec<_>>(),
            vec!["@mod.import", "@mods.browser"],
            "Java ModsDialog content button table only contains import/browser; guide/openfolder live in BaseDialog buttons"
        );
        let flat_border_symbol =
            DesktopLauncher::settings_text_button_symbol("flatBordert", false, false);
        let expected_main_button_width = (super::MODS_ROUTE_MOD_CARD_WIDTH_MAX - 8.0) * 0.5;
        for index in 0..main_button_specs.len() {
            let rect = DesktopLauncher::mods_route_action_button_rect_for_panel_with_count(
                panel,
                index,
                main_button_specs.len(),
            );
            assert_eq!(
                rect.height, 60.0,
                "Java ModsDialog.setup uses buttons.defaults().height(60f) for @mod.import/@mods.browser"
            );
            assert!(
                (rect.width - expected_main_button_width).abs() < f32::EPSILON,
                "Java ModsDialog.setup lays the two main buttons across a 520f table; got width {}",
                rect.width
            );
            assert!(
                commands.iter().any(|command| match command {
                    RenderCommand::DrawSprite {
                        symbol,
                        rect: command_rect,
                        ..
                    } => {
                        symbol == &flat_border_symbol && command_rect == &rect
                    }
                    _ => false,
                }),
                "Java ModsDialog.setup renders @mod.import/@mods.browser with Styles.flatBordert"
            );
        }

        let mut platform = RecordingPlatform {
            open_result: true,
            ..Default::default()
        };
        let guide = DesktopLauncher::mods_route_footer_button_rect_for_panel(panel, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, guide.x, guide.y),
            Some(super::DesktopMenuRouteShellAction::OpenModsGuide),
            "Java ModsDialog wires @mods.guide to Core.app.openURI(modGuideURL)"
        );
        let guide_action = launcher.dispatch_mods_guide_action_with_platform(&mut platform);
        assert_eq!(guide_action.uri, super::MODS_GUIDE_URL);
        assert!(guide_action.opened);
        assert_eq!(launcher.last_mods_guide_action, Some(guide_action));
        assert_eq!(
            platform.opened_uris,
            vec![super::MODS_GUIDE_URL.to_string()]
        );

        let open_folder =
            DesktopLauncher::mods_route_footer_button_rect_for_panel(panel, 1).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                open_folder.x,
                open_folder.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenModsDirectory)
        );
        let directory_action = launcher.dispatch_mods_directory_action_with_platform(&mut platform);
        assert_eq!(directory_action.path, "C:/mods directory");
        assert_eq!(directory_action.uri, "file:///C:/mods%20directory");
        assert!(directory_action.opened);
        assert_eq!(
            launcher.last_mods_directory_action,
            Some(directory_action.clone())
        );
        assert_eq!(
            platform.opened_uris,
            vec![
                super::MODS_GUIDE_URL.to_string(),
                "file:///C:/mods%20directory".to_string()
            ]
        );

        let back = DesktopLauncher::route_back_button_rect_for_panel(panel).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, back.x, back.y),
            Some(super::DesktopMenuRouteShellAction::CloseRoute)
        );
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::CloseRoute);
        assert_eq!(launcher.active_menu_route, None);
    }

    #[test]
    fn desktop_launcher_mods_route_card_title_uses_single_line_ellipsis_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.last_mods_directory_mod_names = vec!["long-title".into()];
        launcher.last_mods_directory_mod_metas = vec![ModMetadata::from_source_text(
            "long-title",
            Some("mod.hjson"),
            r#"
name: long-title
displayName: "Extremely Long Mod Display Name That Should Stay On One Line Like Java ModsDialog Cards Instead Of Wrapping"
author: "Long Author"
version: "1.0.0"
description: "short body"
"#,
        )];
        launcher.dispatch_menu_action(MenuButtonRole::Mods);

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Mods,
        );
        let card = DesktopLauncher::mods_route_mod_card_rect_for_panel(panel, 0);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let title = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("mods route should render a frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .find_map(|command| match command {
                RenderCommand::DrawText {
                    text,
                    position,
                    size,
                    style,
                    ..
                } if card.contains_point(*position)
                    && *size == super::MODS_ROUTE_FONT_SIZE_LIKE_JAVA
                    && text.starts_with("Extremely Long") =>
                {
                    Some((text, style))
                }
                _ => None,
            })
            .expect("long ModsDialog card title should be rendered");
        assert!(
            title.0.ends_with("..."),
            "Java ModsDialog uses Label.setEllipsis(true) for mod titles"
        );
        assert!(
            !title.0.contains('\n'),
            "Java ModsDialog mod titles stay on a single line"
        );
        assert_eq!(
            title.1.wrap_width, None,
            "Rust must not use wrap_width for ModsDialog card titles; Java uses single-line ellipsis"
        );
    }

