    #[test]
    fn desktop_launcher_mods_browser_empty_releases_json_returns_to_selection_with_info_like_java()
    {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.last_mods_directory_mod_names = vec!["beta".into()];
        launcher.last_mods_directory_mod_metas = vec![ModMetadata::from_source_text(
            "beta",
            Some("mod.hjson"),
            r#"
name: beta
displayName: "Beta Override"
author: "Beta Author"
description: "Beta browser entry"
repo: "Beta/Override"
"#,
        )];
        launcher.dispatch_menu_action(MenuButtonRole::Mods);
        launcher
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::OpenModsBrowser);
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsBrowserSelection(0),
        );

        let mut platform = RecordingPlatform::default();
        launcher
            .dispatch_mods_browser_action_with_platform(
                0,
                super::DesktopModsBrowserActionKind::ViewReleases,
                &mut platform,
            )
            .expect("view releases should enter Java-style loading state");
        assert_eq!(launcher.mods_browser_releases_dialog_index, Some(0));
        assert!(launcher.mods_browser_release_entries.is_empty());

        assert_eq!(
            launcher.apply_mods_browser_releases_json_for_mod(0, "[]"),
            0
        );
        assert_eq!(launcher.mods_browser_releases_dialog_index, None);
        assert!(launcher.mods_browser_release_entries.is_empty());
        assert_eq!(launcher.mods_browser_selected_mod_index, Some(0));
        assert_eq!(
            launcher.last_menu_info_message.as_deref(),
            Some("@mods.browser.noreleases")
        );

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("mods browser selection and info should render after empty releases")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&"beta"));
        assert!(texts.iter().any(|text| text.contains("No Releases Found")));
        assert!(
            !texts.contains(&"Fetching Releases..."),
            "Java hides the loading dialog and returns to selection on an empty releases response"
        );
    }

    #[test]
    fn desktop_launcher_mods_browser_scrolls_all_matching_cards_like_java_scrollpane() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        for index in 0..6 {
            let name = format!("mod-{index}");
            let source = format!(
                r#"
name: mod-{index}
displayName: "Mod {index}"
author: "Author {index}"
"#
            );
            launcher.last_mods_directory_mod_names.push(name.clone());
            launcher
                .last_mods_directory_mod_metas
                .push(ModMetadata::from_source_text(
                    name,
                    Some("mod.hjson"),
                    &source,
                ));
        }
        launcher.dispatch_menu_action(MenuButtonRole::Mods);
        launcher
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::OpenModsBrowser);

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Mods,
        );
        let dialog = DesktopLauncher::mods_browser_dialog_rect_for_panel(panel);
        let list = DesktopLauncher::mods_browser_list_rect_for_dialog(dialog);
        let visible_capacity = DesktopLauncher::mods_browser_visible_entry_capacity_for_list(list);
        assert!(
            visible_capacity < 6,
            "test assumes the default browser pane cannot show all six rows at once"
        );

        let before = launcher.menu_graphics_frame_for_surface(0, viewport);
        let before_texts = before
            .bundle
            .render_frame
            .as_ref()
            .expect("mods browser frame should render before scrolling")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(before_texts.contains(&"Mod 0"));
        assert!(
            !before_texts.contains(&"Mod 4"),
            "before scrolling only the first visible Java ScrollPane rows should be drawn"
        );

        let cursor = list.center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: cursor.x,
                    y: cursor.y,
                },
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -1.0,
                },
            ],
        );
        assert_eq!(launcher.mods_browser_scroll_offset, 1);

        let first_visible = DesktopLauncher::mods_browser_entry_rect_for_list(list, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                first_visible.x,
                first_visible.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenModsBrowserSelection(1)),
            "scrolling the Java-style browser pane must keep hit testing mapped to the underlying listing index"
        );

        let after = launcher.menu_graphics_frame_for_surface(0, viewport);
        let after_texts = after
            .bundle
            .render_frame
            .as_ref()
            .expect("mods browser frame should render after scrolling")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let expected_last_visible_after_scroll = format!("Mod {}", visible_capacity.min(5));
        assert!(
            after_texts.contains(&expected_last_visible_after_scroll.as_str()),
            "after one Java ScrollPane row, the last visible Mods Browser row should follow the current 80f row capacity: expected {expected_last_visible_after_scroll}, texts={after_texts:?}"
        );
    }

    #[test]
    fn desktop_launcher_caches_mods_browser_filtered_indices_between_stable_queries() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.last_mods_directory_mod_names =
            vec!["alpha".into(), "beta".into(), "gamma".into()];
        launcher.last_mods_directory_mod_metas = vec![
            ModMetadata::from_source_text(
                "alpha",
                Some("mod.hjson"),
                r#"
name: alpha
displayName: "Alpha"
repo: "Shared/Repo"
stars: 5
lastUpdated: "2024-01-01"
"#,
            ),
            ModMetadata::from_source_text(
                "beta",
                Some("mod.hjson"),
                r#"
name: beta
displayName: "Beta"
repo: "Beta/Repo"
stars: 50
lastUpdated: "2025-01-01"
"#,
            ),
            ModMetadata::from_source_text(
                "gamma",
                Some("mod.hjson"),
                r#"
name: gamma
displayName: "Gamma"
repo: "Shared/Repo"
stars: 10
lastUpdated: "2023-01-01"
"#,
            ),
        ];

        assert_eq!(launcher.mods_browser_filtered_indices_cache_rebuilds(), 0);
        assert_eq!(launcher.filtered_mods_browser_indices(), vec![1, 0, 2]);
        assert_eq!(launcher.mods_browser_filtered_indices_cache_rebuilds(), 1);
        assert_eq!(launcher.filtered_mods_browser_indices(), vec![1, 0, 2]);
        assert_eq!(
            launcher.mods_browser_filtered_indices_cache_rebuilds(),
            1,
            "stable Mods Browser queries should reuse the filtered/sorted index cache"
        );
        assert!(launcher.mods_browser_entry_installed_like_java(0));
        assert!(launcher.mods_browser_entry_installed_like_java(2));
        assert!(!launcher.mods_browser_entry_installed_like_java(1));
        assert_eq!(
            launcher.mods_browser_filtered_indices_cache_rebuilds(),
            1,
            "installed-state lookups should share the same cached repo snapshot"
        );

        launcher.mods_browser_search = "beta".into();
        assert_eq!(launcher.filtered_mods_browser_indices(), vec![1]);
        assert_eq!(launcher.mods_browser_filtered_indices_cache_rebuilds(), 2);
        assert_eq!(launcher.filtered_mods_browser_indices(), vec![1]);
        assert_eq!(
            launcher.mods_browser_filtered_indices_cache_rebuilds(),
            2,
            "unchanged search text should not rebuild the browser filter"
        );

        launcher.mods_browser_sort_date = false;
        assert_eq!(launcher.filtered_mods_browser_indices(), vec![1]);
        assert_eq!(launcher.mods_browser_filtered_indices_cache_rebuilds(), 3);

        launcher.last_mods_directory_mod_names.push("delta".into());
        launcher
            .last_mods_directory_mod_metas
            .push(ModMetadata::from_source_text(
                "delta",
                Some("mod.hjson"),
                r#"
name: delta
displayName: "Delta"
repo: "Delta/Repo"
stars: 99
lastUpdated: "2026-01-01"
"#,
            ));
        assert_eq!(launcher.filtered_mods_browser_indices(), vec![1]);
        assert_eq!(
            launcher.mods_browser_filtered_indices_cache_rebuilds(),
            4,
            "direct test/public-field listing mutations should still invalidate the cache"
        );
    }

