    #[test]
    fn desktop_launcher_mods_import_github_java_release_assets_fallback_and_error_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.mods_import_github_text = "Anon/JarFallback".into();
        launcher.confirm_mods_import_github_like_java();
        launcher
            .apply_mods_import_github_repo_api_json_like_java(
                r#"{"default_branch":"main","language":"Kotlin"}"#,
            )
            .expect("Kotlin should use Java release jar import path");

        let fallback = launcher
            .apply_mods_import_github_java_release_json_like_java(
                r#"{
                    "assets": [
                        {"name":"source.zip","browser_download_url":"https://download.example/source.zip"},
                        {"name":"fallback.jar","browser_download_url":"https://download.example/fallback.jar"}
                    ]
                }"#,
            )
            .expect("regular jar should be used when dexed jar is absent");
        assert_eq!(
            fallback,
            super::DesktopModsImportGithubJavaJarAssetTarget {
                repo: "Anon/JarFallback".into(),
                release: None,
                asset_name: "fallback.jar".into(),
                uri: "https://download.example/fallback.jar".into(),
            }
        );
        assert_eq!(launcher.last_menu_guard_message, None);

        let mut missing = DesktopLauncher::new(Vec::new());
        missing.mods_import_github_text = "Anon/NoJar".into();
        missing.confirm_mods_import_github_like_java();
        missing
            .apply_mods_import_github_repo_api_json_like_java(
                r#"{"default_branch":"main","language":"Java"}"#,
            )
            .expect("Java should use release metadata path");
        assert_eq!(
            missing.apply_mods_import_github_java_release_json_like_java(
                r#"{"assets":[{"name":"not-a-jar.zip","browser_download_url":"https://download.example/not.zip"}]}"#
            ),
            None,
            "Java ModsDialog reports an error when the release has no jar asset"
        );
        assert_eq!(missing.mods_import_github_download_state, None);
        assert!(missing
            .mods_import_github_error_dialog_message
            .as_deref()
            .is_some_and(|message| message.contains("No JAR file found")));
        assert_eq!(
            missing
                .last_mods_import_github_download_result
                .as_ref()
                .map(|result| result.imported),
            Some(false)
        );
    }

