    #[test]
    fn desktop_launcher_mods_route_directory_error_opens_modal_instead_of_inline_banner() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Mods);
        launcher.mods_directory_error = Some("broken @error.title mods dir".into());

        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Mods);
        assert!(
            lines.contains(&"modal: @error.title message=broken @error.title mods dir".to_string())
        );
        assert!(lines.contains(&"button: @ok".to_string()));
        assert!(
            !lines.iter().any(|line| line.contains("mods error:")),
            "Java ModsDialog.modError uses a blocking error dialog instead of an inline Rust diagnostic banner"
        );

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let error_title = launcher.localize_bundle_markup_text("@error.title");
        let ok_label = launcher.localize_bundle_markup_text("@ok");
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("mods directory error should render a modal frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&error_title.as_str()));
        assert!(
            texts.contains(&"broken @error.title mods dir"),
            "rendered texts: {texts:?}"
        );
        assert!(!texts.contains(&"broken Error mods dir"));
        assert!(texts.contains(&ok_label.as_str()));
        assert!(
            !texts.iter().any(|text| text.contains("mods error:")),
            "the visible Mods page must not leak Rust-only directory diagnostics"
        );

        let dialog = DesktopLauncher::load_game_error_dialog_rect_for_viewport(viewport);
        let ok = DesktopLauncher::load_game_error_dialog_ok_button_rect(dialog).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, ok.x, ok.y),
            Some(super::DesktopMenuRouteShellAction::CloseModsDirectoryError)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::CloseModsDirectoryError,
        );
        assert_eq!(launcher.mods_directory_error, None);
    }

    #[test]
    fn desktop_launcher_mods_route_import_file_selection_copies_and_marks_reload_like_java() {
        let root = temp_desktop_path("mods-import-file-selection");
        let mods_dir = root.join("mods");
        let source_dir = root.join("incoming");
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&mods_dir).expect("mods dir should be creatable");
        std::fs::create_dir_all(&source_dir).expect("incoming dir should be creatable");
        std::fs::write(mods_dir.join("Example_Mod_One.zip"), b"old")
            .expect("existing imported mod should be writable");
        let source = source_dir.join("Example Mod One.jar");
        std::fs::write(&source, b"jar bytes").expect("source jar should be writable");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.mods_directory_arg = Some(mods_dir.display().to_string());
        launcher.dispatch_menu_action(MenuButtonRole::Mods);
        launcher
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::OpenModsImport);

        let mut platform = RecordingPlatform::default();
        let request = launcher.dispatch_mods_import_file_with_platform(&mut platform);
        assert!(request.accepts(source.display().to_string().as_str()));
        let result = launcher
            .complete_mods_import_file_selection(&source)
            .expect("Java Mods.importMod-style file selection should copy into mods dir");
        assert!(result.imported);
        assert_eq!(result.mod_name, "Example_Mod_One1");
        assert!(
            result.destination.ends_with("/Example_Mod_One1.zip"),
            "Java importMod always writes the copied archive as a .zip with conflict suffixes"
        );
        assert!(std::path::Path::new(&result.destination).is_file());
        assert_eq!(
            std::fs::read(&result.destination).expect("copied import should be readable"),
            b"jar bytes"
        );
        assert_eq!(
            launcher.last_mods_directory_mod_names,
            vec!["Example_Mod_One1".to_string()]
        );
        assert_eq!(
            launcher.last_mods_directory_mod_roots,
            vec![result.destination.clone()]
        );
        assert_eq!(
            launcher.last_mods_directory_mod_metas[0].name.as_deref(),
            Some("Example_Mod_One1")
        );
        assert!(launcher.last_mods_directory_mod_states[0].enabled);
        assert!(launcher.last_mods_directory_mod_states[0].requires_reload);
        assert!(launcher.mods_route_requires_reload());
        assert_eq!(launcher.last_mods_import_file_result, Some(result.clone()));
        assert!(launcher.mods_route_lines().iter().any(|line| {
            line.contains("event: mods.importMod")
                && line.contains("Example_Mod_One1")
                && line.contains("reload=true")
        }));

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::CloseRoute);
        assert_eq!(launcher.mods_route_reload_count, 1);
        assert!(!launcher.mods_route_requires_reload());
    }

    #[test]
    fn desktop_launcher_mods_archive_discovery_reads_zip_metadata_like_java_mods_load() {
        fn minimal_png_bytes(width: u32, height: u32) -> Vec<u8> {
            let mut bytes = Vec::new();
            bytes.extend_from_slice(&[0x89, b'P', b'N', b'G', b'\r', b'\n', 0x1a, b'\n']);
            bytes.extend_from_slice(&13u32.to_be_bytes());
            bytes.extend_from_slice(b"IHDR");
            bytes.extend_from_slice(&width.to_be_bytes());
            bytes.extend_from_slice(&height.to_be_bytes());
            bytes.extend_from_slice(&[8, 6, 0, 0, 0]);
            bytes.extend_from_slice(&0u32.to_be_bytes());
            bytes
        }

        let root = temp_desktop_path("mods-archive-discovery");
        let mods_dir = root.join("mods");
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&mods_dir).expect("mods dir should be creatable");
        let archive = mods_dir.join("Archive Pack.zip");
        let archive_icon_png = minimal_png_bytes(9, 9);
        let archive_router_png = minimal_png_bytes(40, 12);
        let archive_bytes = super::desktop_settings_data_zip_bytes(&[
            super::DesktopSettingsDataArchiveEntry {
                name: "archive-pack/mod.hjson".into(),
                data: Some(
                    br#"
name: archive-inner
displayName: "Archive Pack"
author: "Zip Tester"
repo: "Anon/archive"
"#
                    .to_vec(),
                ),
            },
            super::DesktopSettingsDataArchiveEntry {
                name: "archive-pack/icon.png".into(),
                data: Some(archive_icon_png.clone()),
            },
            super::DesktopSettingsDataArchiveEntry {
                name: "archive-pack/assets/data.txt".into(),
                data: Some(b"data".to_vec()),
            },
            super::DesktopSettingsDataArchiveEntry {
                name: "archive-pack/sprites/router.png".into(),
                data: Some(archive_router_png.clone()),
            },
        ])
        .expect("archive fixture should encode");
        std::fs::write(&archive, archive_bytes).expect("archive fixture should write");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.mods_directory_arg = Some(mods_dir.display().to_string());
        let merged = launcher
            .merge_mods_directory_arg_into_texture_atlas()
            .expect("archive-backed mod should enter mods discovery");
        assert_eq!(merged, 1);
        assert_eq!(
            launcher.last_mods_directory_mod_names,
            vec!["Archive_Pack".to_string()]
        );
        assert_eq!(
            launcher.last_mods_directory_mod_roots,
            vec![archive.to_string_lossy().into_owned()]
        );
        assert_eq!(
            launcher.last_mods_directory_mod_metas[0]
                .display_name_or_name()
                .unwrap(),
            "Archive Pack"
        );
        assert_eq!(
            launcher.last_mods_directory_mod_metas[0].repo.as_deref(),
            Some("Anon/archive")
        );
        assert_eq!(
            launcher.last_mods_directory_mod_icon_symbols,
            vec![Some("mod-icon-Archive_Pack".to_string())]
        );
        assert_eq!(
            launcher.mods_route_mod_icon_symbol_at_index(0),
            Some("mod-icon-Archive_Pack")
        );
        let icon_region = launcher
            .texture_atlas
            .lookup("mod-icon-Archive_Pack")
            .expect("archive root icon should enter texture atlas")
            .region;
        assert_eq!(icon_region.width, 9);
        assert_eq!(icon_region.height, 9);
        assert_eq!(
            launcher
                .mod_texture_source_bytes
                .get("mod-icon-Archive_Pack")
                .map(Vec::as_slice),
            Some(archive_icon_png.as_slice())
        );
        launcher.dispatch_menu_action(MenuButtonRole::Mods);
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsDetail(0),
        );
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let renders_archive_detail_icon = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("mods detail should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .any(|command| {
                matches!(
                    command,
                    RenderCommand::DrawSprite { symbol, layer, .. }
                        if symbol == "mod-icon-Archive_Pack" && *layer >= Layer::END_PIXELED + 0.070
                )
            });
        assert!(
            !renders_archive_detail_icon,
            "Java ModsDialog.showMod does not render an extra icon preview in the detail dialog"
        );
        let region = launcher
            .texture_atlas
            .lookup("Archive_Pack-router")
            .expect("archive sprite should be merged into atlas with Java mod prefix")
            .region;
        assert_eq!(region.source_path, "sprites/router.png");
        assert_eq!(region.width, 40);
        assert_eq!(region.height, 12);
        assert_eq!(
            launcher
                .mod_texture_source_bytes
                .get("Archive_Pack-router")
                .map(Vec::as_slice),
            Some(archive_router_png.as_slice()),
            "archive-backed sprite bytes must remain available for real texture upload"
        );

        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn desktop_launcher_mods_route_opens_and_closes_detail_dialog() {
        let root = temp_desktop_path("mods-detail-content");
        let alpha_root = root.join("alpha pack");
        let beta_root = root.join("beta");
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(alpha_root.join("content/blocks"))
            .expect("alpha content dir should be creatable");
        std::fs::create_dir_all(&beta_root).expect("beta dir should be creatable");
        std::fs::write(
            alpha_root.join("content/blocks/router.hjson"),
            "name: router\n",
        )
        .expect("alpha content file should be writable");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.last_mods_directory_mod_names =
            vec!["alpha".into(), "beta".into(), "gamma".into()];
        launcher.last_mods_directory_mod_roots = vec![
            alpha_root.to_string_lossy().into_owned(),
            beta_root.to_string_lossy().into_owned(),
        ];
        launcher.last_mods_directory_mod_metas = vec![
            ModMetadata::from_source_text(
                "alpha",
                Some("mod.hjson"),
                r#"
name: alpha
displayName: "Alpha Pack"
author: "Alpha Author"
version: "1.0.0"
description: "Alpha fixture mod."
"#,
            ),
            ModMetadata::from_source_text(
                "beta",
                Some("mod.hjson"),
                r#"
name: beta
displayName: "Beta Override"
author: "Beta Author"
version: "2.0.0"
repo: "Beta/Override"
"#,
            ),
        ];
        launcher.last_mods_directory_merge_count = Some(3);
        launcher.dispatch_menu_action(MenuButtonRole::Mods);

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Mods,
        );
        let card = DesktopLauncher::mods_route_mod_card_rect_for_panel(panel, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, card.x, card.y),
            Some(super::DesktopMenuRouteShellAction::OpenModsDetail(0))
        );

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsDetail(0),
        );
        assert_eq!(launcher.mods_selected_mod_index, Some(0));

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("mods detail should render a frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&"Alpha Pack"));
        assert!(!texts.iter().any(|text| text.contains("Open Folder:")));
        assert!(texts.contains(&"Open Folder"));
        assert!(texts.contains(&"Name:"));
        assert!(texts.contains(&"Version:"));
        assert!(texts.contains(&"Author:"));
        assert!(texts.contains(&"Description:"));
        assert!(texts.contains(&"1.0.0"));
        assert!(texts.contains(&"Alpha Author"));
        assert!(texts.contains(&"Alpha fixture mod."));
        assert!(!texts.iter().any(|text| text.starts_with("metadata:")));
        assert!(texts.contains(&"View Content"));
        assert!(!texts.iter().any(|text| text.starts_with("mods scanned:")));
        assert!(!texts.contains(&"@mods.viewcontent: 0"));
        assert!(!texts.contains(&"state: loaded"));
        assert!(!texts.contains(&"content: 0"));
        assert!(!texts.contains(&"mod detail placeholder: browser/import/delete later"));

        let dialog = DesktopLauncher::mods_route_detail_dialog_rect_for_panel(panel);
        let open_folder = DesktopLauncher::schematic_info_button_rect(dialog, 1).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                open_folder.x,
                open_folder.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenModsFolder(0))
        );
        let mut platform = RecordingPlatform {
            open_result: true,
            ..Default::default()
        };
        let folder_action = launcher
            .dispatch_mods_folder_action_with_platform(0, &mut platform)
            .expect("mod root should open as file URI");
        assert_eq!(
            folder_action.path,
            alpha_root.to_string_lossy().into_owned()
        );
        assert!(folder_action.opened);
        assert_eq!(platform.opened_uris, vec![folder_action.uri.clone()]);

        let view_content = DesktopLauncher::mods_route_detail_content_button_rect(dialog).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                view_content.x,
                view_content.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenModsContent(0))
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsContent(0),
        );
        assert_eq!(launcher.last_mods_content_index, Some(0));
        assert_eq!(launcher.mods_content_dialog_index, Some(0));
        let content_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let content_texts = content_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("mods content dialog should render a frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(content_texts.contains(&"Alpha Pack"));
        assert!(!content_texts.contains(&"View Content: Alpha Pack"));
        assert!(!content_texts
            .iter()
            .any(|text| text.contains("router") && text.contains("Blocks")));
        assert!(!content_texts
            .iter()
            .any(|text| text.contains("blocks/router.hjson")));
        assert!(!content_texts.contains(&"@none"));
        assert!(!content_texts.contains(&"@mods.contents.none"));
        assert!(!content_texts.contains(&"content entries: 0"));
        let content_dialog = DesktopLauncher::mods_content_dialog_rect_for_panel(panel);
        let grid = DesktopLauncher::mods_content_grid_rect_for_dialog(content_dialog);
        let first_content_entry_rect = DesktopLauncher::mods_content_entry_rect_for_grid(grid, 0);
        assert_eq!(first_content_entry_rect.width, 50.0);
        assert_eq!(first_content_entry_rect.height, 50.0);
        let first_content_entry = first_content_entry_rect.center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                first_content_entry.x,
                first_content_entry.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenModsContentEntry(0))
        );
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: first_content_entry.x,
                y: first_content_entry.y,
            }],
        );
        let hover_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let hover_commands = hover_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("hovered mods content dialog should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let hover_texts = hover_commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let expected_tooltip = launcher.mods_content_entries_for_mod(0)[0].title.clone();
        assert!(
            hover_texts.contains(&expected_tooltip.as_str()),
            "Java ModsDialog content grid attaches tooltip(c.localizedName) to each icon"
        );
        let tooltip_width =
            (expected_tooltip.chars().count() as f32 * 7.0 + 8.0).clamp(72.0, 280.0);
        let tooltip_height = 28.0;
        let tooltip_x = (first_content_entry.x + 14.0)
            .min(panel.right() - tooltip_width - 4.0)
            .max(panel.x + 4.0);
        let tooltip_y = (first_content_entry.y + 14.0)
            .min(panel.y + panel.height - tooltip_height - 4.0)
            .max(panel.y + 4.0);
        let tooltip = RenderRect::new(tooltip_x, tooltip_y, tooltip_width, tooltip_height);
        assert!(hover_commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &DesktopLauncher::settings_drawable_symbol("black6")
                    && *rect == tooltip
        )), "Java Tooltip(c.localizedName) uses the standard compact black tooltip chrome, not a Rust-only button tooltip");
        assert!(
            hover_commands.iter().any(|command| matches!(
                command,
            RenderCommand::DrawText { text, position, size, .. }
                if text == &expected_tooltip
                    && *position == RenderPoint::new(tooltip.x + 4.0, tooltip.center().y)
                    && (*size - 11.0).abs() < f32::EPSILON
            )),
            "Mods content tooltip text should keep Java tooltip padding and font size"
        );
        assert!(
            !hover_commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, .. } if *rect == tooltip
            )),
            "Java tooltip(c.localizedName) should not add the old Rust-only tooltip stroke"
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsContentEntry(0),
        );
        assert_eq!(launcher.last_mods_content_entry_index, Some(0));
        assert_eq!(
            launcher.last_database_content_opened,
            Some((ContentType::Block, "router".into())),
            "Java ModsDialog content grid opens ContentInfoDialog for the clicked UnlockableContent"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                open_folder.x,
                open_folder.y
            ),
            None,
            "open mods content dialog should block clicks from reaching the detail dialog behind it"
        );
        let close_content = DesktopLauncher::schematic_info_button_rect(content_dialog, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                close_content.x,
                close_content.y
            ),
            Some(super::DesktopMenuRouteShellAction::CloseModsContent)
        );
        launcher
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::CloseModsContent);
        assert_eq!(launcher.mods_content_dialog_index, None);

        let detail_back = DesktopLauncher::schematic_info_button_rect(dialog, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                detail_back.x,
                detail_back.y
            ),
            Some(super::DesktopMenuRouteShellAction::CloseModsDetail)
        );
        launcher
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::CloseModsDetail);
        assert_eq!(launcher.mods_selected_mod_index, None);

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsDetail(1),
        );
        assert_eq!(launcher.mods_selected_mod_index, Some(1));
        let beta_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let beta_texts = beta_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("mods detail with repo should render a frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(beta_texts.contains(&"Beta Override"));
        assert!(!beta_texts.contains(&"Mod: Beta Override"));
        assert!(
            !beta_texts.iter().any(|text| text.contains("Beta/Override")),
            "Java ModsDialog.showMod keeps repo in the button actions instead of adding a metadata row"
        );
        assert!(beta_texts.contains(&"Reinstall"));
        assert!(
            !beta_texts.contains(&"View Content"),
            "Java ModsDialog only shows @mods.viewcontent when actual mod content exists"
        );
        let beta_button_count = launcher.mods_route_detail_button_specs(1).len();
        assert_eq!(
            beta_button_count, 4,
            "Java showMod top row exposes back, folder, repo and reinstall; view content is a separate block"
        );
        let repo_button =
            DesktopLauncher::mods_route_detail_button_rect(dialog, 2, beta_button_count).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                repo_button.x,
                repo_button.y
            ),
            Some(super::DesktopMenuRouteShellAction::ModsDetailOpenGithub(1))
        );
        let reinstall_button =
            DesktopLauncher::mods_route_detail_button_rect(dialog, 3, beta_button_count).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                reinstall_button.x,
                reinstall_button.y
            ),
            Some(super::DesktopMenuRouteShellAction::ModsDetailReinstall(1))
        );
        let view_content_button =
            DesktopLauncher::mods_route_detail_content_button_rect(dialog).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                view_content_button.x,
                view_content_button.y
            ),
            None
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsContent(1),
        );
        assert_eq!(launcher.mods_content_dialog_index, None);
        let mut platform = RecordingPlatform {
            open_result: true,
            ..Default::default()
        };
        let repo_action = launcher
            .dispatch_mods_browser_action_with_platform(
                1,
                super::DesktopModsBrowserActionKind::OpenGithub,
                &mut platform,
            )
            .expect("repo mod should open GitHub from local detail");
        assert_eq!(
            repo_action.uri.as_deref(),
            Some("https://github.com/Beta/Override")
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ModsDetailReinstall(1),
        );
        assert_eq!(
            launcher
                .last_mods_browser_action
                .as_ref()
                .map(|action| (action.kind, action.repo.as_deref())),
            Some((
                super::DesktopModsBrowserActionKind::Reinstall,
                Some("Beta/Override")
            ))
        );

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsDetail(2),
        );
        assert_eq!(launcher.mods_selected_mod_index, Some(2));
        let gamma_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let gamma_texts = gamma_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("mods detail without metadata should render a frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(gamma_texts.contains(&"gamma"));
        assert!(!gamma_texts.contains(&"Mod: gamma"));
        assert!(gamma_texts.contains(&"Name:"));
        assert!(
            !gamma_texts.iter().any(|text| text.contains("Unknown")),
            "Java ModsDialog.showMod only adds author/version rows when metadata fields are present"
        );
        assert!(!gamma_texts.iter().any(|text| text.starts_with("Author:")));
        assert!(!gamma_texts.iter().any(|text| text.starts_with("Version:")));

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::CloseRoute);
        assert_eq!(launcher.active_menu_route, None);
        assert_eq!(launcher.mods_selected_mod_index, None);

        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn desktop_launcher_mods_content_grid_scrolls_icon_rows_like_java_pane() {
        let root = temp_desktop_path("mods-content-scroll");
        let alpha_root = root.join("alpha");
        let content_dir = alpha_root.join("content/blocks");
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&content_dir).expect("content dir should be creatable");
        for index in 0..64 {
            std::fs::write(
                content_dir.join(format!("block{index:02}.hjson")),
                format!("name: block{index:02}\n"),
            )
            .expect("content file should be writable");
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.last_mods_directory_mod_names = vec!["alpha".into()];
        launcher.last_mods_directory_mod_roots = vec![alpha_root.to_string_lossy().into_owned()];
        launcher.last_mods_directory_mod_metas = vec![ModMetadata::from_source_text(
            "alpha",
            Some("mod.hjson"),
            r#"
name: alpha
displayName: "Alpha Pack"
"#,
        )];
        launcher.dispatch_menu_action(MenuButtonRole::Mods);
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsDetail(0),
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsContent(0),
        );

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Mods,
        );
        let dialog = DesktopLauncher::mods_content_dialog_rect_for_panel(panel);
        let grid = DesktopLauncher::mods_content_grid_rect_for_dialog(dialog);
        let columns = DesktopLauncher::mods_content_entry_columns_for_grid(grid);
        assert!(launcher.max_mods_content_scroll_offset(grid, 0) > 0);

        let cursor = grid.center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: cursor.x,
                    y: cursor.y,
                },
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -1.0,
                },
            ],
        );
        assert_eq!(launcher.mods_content_scroll_offset, 1);

        let first_visible = DesktopLauncher::mods_content_entry_rect_for_grid(grid, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                first_visible.x,
                first_visible.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenModsContentEntry(
                columns
            )),
            "scrolling Java-style content pane must map the first visible icon to the first entry of the next row"
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenModsContentEntry(columns),
        );
        assert_eq!(launcher.last_mods_content_entry_index, Some(columns));

        let _ = std::fs::remove_dir_all(root);
    }

