    #[cfg(feature = "opengl-backend")]
    #[test]
    fn desktop_opengl_backend_frame_plan_skips_submitted_font_texture_before_pixel_clone() {
        let font_upload_plan = super::DesktopFontAtlasPlan {
            texture_name: DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_NAME.to_string(),
            font_asset_count: 1,
            resolved_font_asset_count: 1,
            content_icon_glyph_count: 0,
            planned_glyph_count: 3,
            unresolved_font_source_paths: Vec::new(),
            missing_icon_atlas_symbols: Vec::new(),
            content_icon_load_error: None,
            placeholder_fallback_required: true,
        }
        .upload_plan();
        assert!(
            font_upload_plan.rgba8888_pixels.is_some(),
            "fixture must carry real font pixels so this test proves the plan builder skips cloning them"
        );
        let frame = DesktopGraphicsFrame {
            bundle: RenderBridge::new().finish(),
            floor_chunk_batches: Vec::new(),
            minimap_texture_frame: None,
            font_glyph_upload_plan: Some(font_upload_plan),
            texture_atlas: Arc::new(TextureAtlasPlan::new()),
            mod_texture_source_bytes: BTreeMap::new().into(),
        };
        let mut submitted = BTreeMap::new();
        submitted.insert(DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY.to_string(), 1);

        let plan = super::DesktopGraphicsOpenGlBackendFramePlan::from_frame_direct_with_effect_buffer_surface_and_submitted_generations(
            &frame,
            None,
            Some(&submitted),
        );

        assert!(
            plan.texture_upload_plans.iter().all(|upload| upload.texture_key != DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY),
            "stable frames with an already submitted font atlas generation should skip generating the font texture upload plan before cloning rgba8888 pixels"
        );
    }

