    #[test]
    fn desktop_launcher_default_surface_frame_bridges_menu_plan_without_world() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let mut renderer = HeadlessDesktopGraphicsRenderer::default();
        let surface = DesktopSurfaceSize::new(800, 600);

        let stats =
            launcher.render_default_graphics_frame_for_surface_with(0, surface, 2, &mut renderer);

        assert_eq!(renderer.frames_rendered, 1);
        assert_eq!(stats.render_passes, 1);
        assert!(stats.render_commands >= 18);
        assert_eq!(renderer.last_trace.render_passes.len(), 1);
        let menu_pass = &renderer.last_trace.render_passes[0];
        assert_eq!(menu_pass.kind, RenderPassKind::Custom("menu".to_string()));
        assert_eq!(menu_pass.target, RenderTarget::Screen);
        assert!(menu_pass
            .commands
            .iter()
            .all(|command| !matches!(command, RenderCommand::Custom { name, .. } if name == "startup-menu-preview")));
        let menu_texts = menu_pass
            .commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(!menu_texts.contains(&"RUST MDT PREVIEW"));
        assert!(!menu_texts.contains(&"WORLD NOT LOADED"));
        assert!(menu_pass
            .commands
            .iter()
            .all(|command| !matches!(command, RenderCommand::Custom { .. })));
        assert!(menu_pass
            .commands
            .iter()
            .any(|command| matches!(command, RenderCommand::DrawSprite { .. })));
        assert!(menu_pass
            .commands
            .iter()
            .any(|command| matches!(command, RenderCommand::FillRect { .. })));
        let localized_play_text = launcher.localize_bundle_markup_text("@play");
        assert!(
            menu_pass.commands.iter().any(|command| match command {
                RenderCommand::DrawText { text, .. } =>
                    text == "Play"
                        || text.as_str() == localized_play_text.as_str()
                        || text == "开始游戏",
                RenderCommand::DrawSprite { .. } => false,
                _ => false,
            }),
            "menu pass should render the Java MenuFragment play button as runtime Core.bundle text"
        );
        assert!(
            menu_pass.commands.iter().all(|command| {
                !matches!(command, RenderCommand::DrawSprite { symbol, .. } if symbol.starts_with("menu-label-zh-"))
            }),
            "Java MenuFragment does not use generated Chinese label sprites for menu buttons"
        );
        assert!(menu_pass.commands.iter().all(
            |command| !matches!(command, RenderCommand::DrawText { text, .. } if text == "Campaign")
        ));
        assert!(
            menu_pass
                .commands
                .iter()
                .filter(|command| matches!(command, RenderCommand::Clear { .. }))
                .count()
                >= 1
        );
        assert!(renderer.last_opengl_backend_executor_state.clear_commands >= 1);
        assert!(renderer
            .last_opengl_backend_executor_state
            .sprite_quads
            .iter()
            .any(|quad| {
                quad.symbol == "primitive:DrawText" || quad.symbol.contains(":DrawText:U+")
            }));
        assert!(renderer
            .last_opengl_backend_executor_state
            .sprite_quads
            .iter()
            .all(|quad| !quad.symbol.starts_with("menu-label-zh-")));
    }

    #[test]
    fn desktop_launcher_menu_frame_prefers_java_menu_world_over_synthetic_space_background() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let pass = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain a render frame")
            .passes
            .iter()
            .find(|pass| pass.kind == RenderPassKind::Custom("menu".to_string()))
            .expect("menu frame should contain the Java menu pass");

        assert!(
            DesktopLauncher::menu_pass_has_java_world_background(pass),
            "normal menu rendering should already contain the Java MenuRenderer floor/shadow/wall/flyer/darkness layers"
        );
        assert!(
            !DesktopLauncher::menu_pass_has_synthetic_background(pass),
            "the old space/planet approximation should not be layered behind a valid Java menu world"
        );
        assert!(pass.commands.iter().all(|command| {
            !matches!(
                command,
                RenderCommand::Custom { name, .. } if name == "menu-background-approximation"
            )
        }));
    }

    #[test]
    fn desktop_launcher_menu_frame_draws_visible_asset_diagnostics_when_assets_are_missing() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.font_asset_sources = vec![DesktopFontAssetSourceTrace {
            source_path: "fonts/font.woff".into(),
            file_path: None,
        }];
        launcher.content_icon_glyph_registry = DesktopContentIconGlyphRegistry::new(
            "icons/icons.properties",
            None,
            Vec::new(),
            Some("missing fixture".into()),
        );
        launcher.texture_atlas = Arc::new(TextureAtlasPlan::new());
        let viewport = RenderViewport::new(0.0, 0.0, 800.0, 600.0);

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should be available")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();

        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::FillRect { color, .. } if *color == [0.20, 0.04, 0.03, 0.90]
            )
        }));
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. } if text == launcher.localize_bundle_markup_text("@warning").as_str()
            )
        }));
        assert!(!commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. } if text == "render asset diagnostics"
            )
        }));
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. } if text == "asset warning: fonts 0/1"
            )
        }));
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. } if text.starts_with("asset warning: ui skin 0/")
            )
        }));
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. } if text.starts_with("missing ui: sprites/ui/")
            )
        }));
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. }
                    if text == "asset warning: icons icons/icons.properties"
            )
        }));
    }

