    #[test]
    fn desktop_launcher_paused_world_overlay_renders_campaign_objective_branch() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.game_state.world.resize(16, 16);
        launcher.game_state.set(GameStateState::Paused);
        let mut sector = Sector::new(173);
        let mut preset = mindustry_core::mindustry::r#type::SectorPreset::new("ground-zero");
        preset.description = Some("Campaign objective text".into());
        sector.preset = Some(preset);
        launcher.game_state.set_sector(Some(sector));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = launcher.pause_overlay_panel_for_current_state(viewport);
        let objective_center = launcher
            .pause_overlay_button_rect_for_action(
                panel,
                super::DesktopPausedOverlayAction::Objective,
            )
            .expect("Objective button should be visible")
            .center();
        let abandon_center = launcher
            .pause_overlay_button_rect_for_action(panel, super::DesktopPausedOverlayAction::Abandon)
            .expect("Abandon button should be visible")
            .center();

        assert_eq!(
            launcher.pause_overlay_action_at_surface_point(
                surface,
                objective_center.x,
                objective_center.y
            ),
            Some(super::DesktopPausedOverlayAction::Objective)
        );
        assert_eq!(
            launcher.pause_overlay_action_at_surface_point(
                surface,
                abandon_center.x,
                abandon_center.y
            ),
            Some(super::DesktopPausedOverlayAction::Abandon)
        );

        let mut renderer = HeadlessDesktopGraphicsRenderer::default();
        launcher.render_default_graphics_frame_for_surface_with(0, surface, 1, &mut renderer);
        let texts = renderer
            .last_trace
            .render_passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@objective").as_str()));
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@abandon").as_str()));
        assert!(!texts.contains(&launcher.localize_bundle_markup_text("@savegame").as_str()));
        assert!(!texts.contains(&launcher.localize_bundle_markup_text("@loadgame").as_str()));

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: objective_center.x,
                    y: objective_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "left".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.pause_overlay_modal,
            Some(super::DesktopPausedOverlayModal::Objective)
        );
        launcher.render_default_graphics_frame_for_surface_with(1, surface, 1, &mut renderer);
        let modal_texts = renderer
            .last_trace
            .render_passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(modal_texts.contains(&"Campaign objective text"));
        assert!(
            !modal_texts
                .iter()
                .any(|text| text.contains("FullTextDialog")),
            "FullTextDialog.show renders only the title/body, not the Java class name"
        );
        assert!(
            renderer.last_trace.render_passes.iter().any(|pass| {
                pass.commands.iter().any(|command| {
                    matches!(
                        command,
                        RenderCommand::DrawText { text, style, .. }
                            if text == "Campaign objective text" && style.wrap_width.is_some()
                    )
                })
            }),
            "FullTextDialog body should wrap like cont.add(text).grow().wrap().labelAlign(center)"
        );

        let modal = DesktopLauncher::pause_overlay_modal_rect_for_panel(panel);
        let close = DesktopLauncher::pause_overlay_modal_close_rect(modal).center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: close.x,
                    y: close.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "left".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(launcher.pause_overlay_modal, None);
    }

    #[test]
    fn desktop_launcher_paused_world_overlay_campaign_abandon_matches_java_server_client_and_gameover_rules(
    ) {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.game_state.world.resize(16, 16);
        launcher.game_state.set(GameStateState::Paused);
        launcher.game_state.set_sector(Some(Sector::new(173)));

        let abandon_enabled = |launcher: &DesktopLauncher| {
            launcher
                .pause_overlay_button_specs()
                .iter()
                .find(|spec| spec.action == super::DesktopPausedOverlayAction::Abandon)
                .expect("campaign pause overlay should include Abandon")
                .enabled
        };

        assert!(
            abandon_enabled(&launcher),
            "Java PausedDialog keeps @abandon enabled while offline"
        );

        launcher
            .runtime
            .set_network_context(GameRuntimeNetworkContext::server());
        assert!(
            abandon_enabled(&launcher),
            "Java PausedDialog keeps @abandon enabled on a server"
        );

        launcher
            .runtime
            .set_network_context(GameRuntimeNetworkContext::client());
        assert!(
            !abandon_enabled(&launcher),
            "Java PausedDialog disables @abandon for net clients"
        );

        launcher
            .runtime
            .set_network_context(GameRuntimeNetworkContext::server());
        launcher.game_state.game_over = true;
        assert!(
            !abandon_enabled(&launcher),
            "Java PausedDialog disables @abandon when the campaign is already game over"
        );
    }

