    #[test]
    fn desktop_launcher_paused_world_overlay_quit_requires_confirmation() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.game_state.world.resize(16, 16);
        launcher.game_state.set(GameStateState::Paused);
        let mut save_tags = BTreeMap::new();
        save_tags.insert("version".into(), LATEST_SAVE_VERSION.to_string());
        save_tags.insert("build".into(), "158".into());
        save_tags.insert("saved".into(), "42".into());
        save_tags.insert("playtime".into(), "123000".into());
        save_tags.insert("mapname".into(), "Autosave Resume".into());
        save_tags.insert("wave".into(), "12".into());
        save_tags.insert("mods".into(), "[]".into());
        save_tags.insert("autosave".into(), "true".into());
        let save_path = std::path::PathBuf::from("saves/autosave-resume.msav");
        let save_slot = SaveSlotRecord::with_meta(save_path, SaveMeta::from_tags(save_tags));
        launcher.load_game_slots = vec![save_slot.clone()];
        launcher.last_load_game_result = Some(super::DesktopLoadGameAction {
            slot: save_slot.index(),
            file: save_slot.file.display().to_string(),
            map_name: Some("Autosave Resume".into()),
            timestamp: save_slot.timestamp(),
            kind: super::DesktopLoadGameActionKind::Load,
            status: "loaded".into(),
        });

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = launcher.pause_overlay_panel_for_current_state(viewport);
        let quit_center = launcher
            .pause_overlay_button_rect_for_action(panel, super::DesktopPausedOverlayAction::Quit)
            .expect("Quit button should be visible")
            .center();

        let mut renderer = HeadlessDesktopGraphicsRenderer::default();
        launcher.render_default_graphics_frame_for_surface_with(0, surface, 1, &mut renderer);
        let pause_texts = renderer
            .last_trace
            .render_passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(pause_texts.contains(&launcher.localize_bundle_markup_text("@save.quit").as_str()));
        assert!(!pause_texts.contains(&launcher.localize_bundle_markup_text("@quit").as_str()));

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: quit_center.x,
                    y: quit_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "left".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.pause_overlay_modal,
            Some(super::DesktopPausedOverlayModal::QuitConfirm)
        );
        assert_eq!(
            launcher.last_pause_quit_result,
            Some(super::DesktopPauseQuitResult::Shown)
        );
        assert!(launcher.game_state.is_paused());

        launcher.render_default_graphics_frame_for_surface_with(0, surface, 1, &mut renderer);
        let confirm_texts = renderer
            .last_trace
            .render_passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(confirm_texts.contains(&launcher.localize_bundle_markup_text("@confirm").as_str()));
        assert!(
            !confirm_texts
                .iter()
                .any(|text| text.contains("PausedDialog.showQuitConfirm")),
            "PausedDialog.showQuitConfirm should not render its Java method name"
        );
        assert!(confirm_texts.contains(
            &launcher
                .localize_bundle_markup_text("@quit.confirm")
                .as_str()
        ));
        assert!(confirm_texts.contains(&launcher.localize_bundle_markup_text("@cancel").as_str()));
        assert!(confirm_texts.contains(&launcher.localize_bundle_markup_text("@ok").as_str()));

        let dialog = DesktopLauncher::pause_overlay_modal_rect_for_panel(panel);
        let cancel = DesktopLauncher::pause_overlay_modal_cancel_rect(dialog).center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: cancel.x,
                    y: cancel.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "left".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(launcher.pause_overlay_modal, None);
        assert_eq!(
            launcher.last_pause_quit_result,
            Some(super::DesktopPauseQuitResult::Cancelled)
        );
        assert!(launcher.game_state.is_paused());

        launcher.dispatch_pause_overlay_action(super::DesktopPausedOverlayAction::Quit);
        let ok = DesktopLauncher::pause_overlay_modal_ok_rect(dialog).center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved { x: ok.x, y: ok.y },
                DesktopInputTickEvent::MouseButton {
                    button: "left".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(launcher.pause_overlay_modal, None);
        assert_eq!(
            launcher.last_pause_quit_result,
            Some(super::DesktopPauseQuitResult::Confirmed)
        );
        assert!(launcher.game_state.is_menu());
    }

