    #[test]
    fn desktop_launcher_non_submenu_route_fades_open_desktop_submenu_like_java_menu_fragment() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let surface = DesktopSurfaceSize::new(800, 600);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let input = DesktopLauncher::default_menu_frame_input_for_viewport(viewport);

        let play = launcher.dispatch_menu_action(MenuButtonRole::Play);
        assert_eq!(
            play,
            super::DesktopMenuActionDispatch {
                role: MenuButtonRole::Play,
                submenu_changed: true,
                route: None,
                close_requested: false,
            }
        );
        assert!(launcher.menu_renderer_state.has_active_desktop_submenu());
        assert!(launcher
            .menu_renderer_state
            .ui_plan(input)
            .buttons
            .iter()
            .any(|button| button.role == MenuButtonRole::Join));

        let editor = launcher.dispatch_menu_action(MenuButtonRole::Editor);
        assert_eq!(
            editor,
            super::DesktopMenuActionDispatch {
                role: MenuButtonRole::Editor,
                submenu_changed: false,
                route: Some(super::DesktopMenuRoute::Editor),
                close_requested: false,
            }
        );
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::Editor)
        );
        assert!(
            launcher.menu_renderer_state.has_active_desktop_submenu(),
            "Java MenuFragment.fadeOutMenu() keeps submenu children alive while non-submenu root actions open their route"
        );
        assert_eq!(
            launcher.menu_renderer_state.selected_root,
            MenuButtonRole::Play
        );
        let fading = launcher.menu_frame_for_render(MenuFrameInput::new(
            surface.width as f32,
            surface.height as f32,
            4.0,
            MENU_SUBMENU_FADE_OUT_SECONDS * 0.25,
        ));
        let DesktopFramePayload::Menu(fading_plan) = fading.payload else {
            panic!("fading menu frame should contain menu payload");
        };
        assert!(fading_plan.ui.submenu_alpha > 0.0);
        assert!(fading_plan.ui.submenu_alpha < 1.0);
        assert!(fading_plan
            .ui
            .buttons
            .iter()
            .any(|button| button.role == MenuButtonRole::Campaign));
        assert!(fading_plan
            .ui
            .buttons
            .iter()
            .any(|button| button.role == MenuButtonRole::Join));

        let faded = launcher.menu_frame_for_render(MenuFrameInput::new(
            surface.width as f32,
            surface.height as f32,
            4.0,
            MENU_SUBMENU_FADE_OUT_SECONDS,
        ));
        let DesktopFramePayload::Menu(faded_plan) = faded.payload else {
            panic!("faded menu frame should contain menu payload");
        };
        assert_eq!(faded_plan.ui.submenu_alpha, 0.0);
        assert!(faded_plan
            .ui
            .buttons
            .iter()
            .all(|button| button.role != MenuButtonRole::Campaign));
        assert!(faded_plan
            .ui
            .buttons
            .iter()
            .all(|button| button.role != MenuButtonRole::Join));
        assert!(faded_plan
            .ui
            .buttons
            .iter()
            .any(|button| button.role == MenuButtonRole::Editor));
        assert!(!launcher.menu_renderer_state.has_active_desktop_submenu());
    }

