    #[test]
    fn desktop_launcher_editor_ingame_loads_real_asset_map_snapshot_when_available() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.refresh_map_list_cards_from_assets();
        let index = launcher
            .map_list_cards
            .iter()
            .position(|map| map.file == "maps/default/archipelago.msav")
            .expect("Archipelago asset map should be discovered from copied upstream resources");
        let selected_map = launcher.map_list_cards[index].clone();

        assert!(launcher.begin_edit_map(selected_map.clone()));
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::EditorInGame);

        assert!(launcher.game_state.is_playing());
        assert!(launcher.runtime.state.is_playing());
        assert_eq!(launcher.runtime.state.map.file, selected_map.file);
        assert_eq!(
            launcher.runtime.state.world.width() as i32,
            selected_map.width
        );
        assert_eq!(
            launcher.runtime.state.world.height() as i32,
            selected_map.height
        );
        assert!(launcher.game_state.rules.editor);
        assert!(launcher.game_state.playtesting_map.is_none());
        assert_eq!(launcher.last_campaign_launch_report, None);
        let report = launcher
            .last_runtime_map_load_report
            .as_ref()
            .expect("EditorInGame should load the real local map snapshot before smoke fallback");
        assert_eq!(
            report.tiles,
            launcher.runtime.state.world.width() * launcher.runtime.state.world.height()
        );
        assert!(report.tiles > 0);
    }

    #[test]
    fn desktop_launcher_editor_route_shift_playtest_skips_map_play_dialog_like_java() {
        fn attack_only_map(name: &str) -> MapDescriptor {
            let mut tags = BTreeMap::new();
            tags.insert("name".to_string(), name.to_string());
            tags.insert("author".to_string(), "Mapper".to_string());
            let mut map = MapDescriptor::new(
                format!("maps/custom/{name}.msav"),
                128,
                128,
                tags,
                true,
                1,
                158,
            );
            map.spawns = 0;
            map.teams = vec![1, 2];
            map
        }

        let map = attack_only_map("Shift Attack");
        let mut normal = DesktopLauncher::new(Vec::new());
        normal.map_list_cards = vec![map.clone()];
        normal.begin_edit_map(map.clone());
        normal.menu_shift_pressed = false;
        normal.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::EditorPlaytest);
        assert_eq!(normal.map_play_dialog_index, Some(0));
        assert!(normal.map_play_playtesting);
        assert_eq!(
            normal.active_menu_route,
            Some(super::DesktopMenuRoute::Editor)
        );
        assert!(!normal.game_state.is_playing());

        let mut shifted = DesktopLauncher::new(Vec::new());
        shifted.map_list_cards = vec![map.clone()];
        shifted.begin_edit_map(map);
        shifted.menu_shift_pressed = true;
        shifted
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::EditorPlaytest);
        assert!(shifted.game_state.is_playing());
        assert!(shifted.runtime.state.is_playing());
        assert_eq!(shifted.active_menu_route, None);
        assert_eq!(shifted.map_play_dialog_index, None);
        assert!(!shifted.map_play_playtesting);
        assert_eq!(shifted.map_play_selected_mode, Gamemode::Attack);
        assert_eq!(
            shifted.game_state.rules.mode_name.as_deref(),
            Some(Gamemode::Attack.wire_name())
        );
        assert!(shifted.game_state.rules.attack_mode);
        assert_eq!(
            shifted
                .game_state
                .playtesting_map
                .as_ref()
                .map(MapDescriptor::plain_name)
                .as_deref(),
            Some("Shift Attack")
        );
        assert_eq!(
            shifted
                .runtime
                .state
                .playtesting_map
                .as_ref()
                .map(MapDescriptor::plain_name)
                .as_deref(),
            Some("Shift Attack")
        );
        assert_eq!(shifted.game_state.map.plain_name(), "Shift Attack");
        assert_eq!(shifted.runtime.state.map.plain_name(), "Shift Attack");
        assert_eq!(shifted.runtime.state.world.width(), 128);
        assert_eq!(shifted.runtime.state.world.height(), 128);
    }

    #[test]
    fn desktop_launcher_editor_route_publishes_or_views_workshop_like_java() {
        let mut tags = BTreeMap::new();
        tags.insert("name".to_string(), "Publish Arena".to_string());
        tags.insert("description".to_string(), "Ready for workshop".to_string());
        let mut map = MapDescriptor::new(
            "maps/custom/publish-arena.msav",
            128,
            128,
            tags,
            true,
            2,
            158,
        );
        map.spawns = 1;

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.menu_renderer_state.config = launcher
            .menu_renderer_state
            .config
            .with_desktop_workshop_enabled(true);
        launcher.map_list_cards = vec![map.clone()];
        launcher.begin_edit_map(map);

        assert!(launcher
            .editor_maps_route_lines()
            .iter()
            .any(|line| line.contains("@editor.publish.workshop")));
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Editor,
        );
        let workshop_center =
            DesktopLauncher::map_list_action_button_rect_for_panel(panel, 5).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                workshop_center.x,
                workshop_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::EditorWorkshop)
        );

        let mut platform = RecordingPlatform::default();
        let publish = launcher
            .dispatch_editor_workshop_with_platform(&mut platform)
            .expect("valid editor map should publish");
        assert_eq!(
            publish.kind,
            super::DesktopEditorWorkshopActionKind::Publish
        );
        assert_eq!(platform.published, vec!["Publish Arena".to_string()]);
        assert_eq!(launcher.editor_workshop_error, None);

        let mut steam_tags = BTreeMap::new();
        steam_tags.insert("name".to_string(), "Steam Arena".to_string());
        steam_tags.insert("description".to_string(), "Already published".to_string());
        steam_tags.insert("steamid".to_string(), "123456789".to_string());
        let mut steam_map = MapDescriptor::new(
            "maps/custom/steam-arena.msav",
            128,
            128,
            steam_tags,
            true,
            2,
            158,
        );
        steam_map.spawns = 1;
        let mut steam_launcher = DesktopLauncher::new(Vec::new());
        steam_launcher.menu_renderer_state.config = steam_launcher
            .menu_renderer_state
            .config
            .with_desktop_workshop_enabled(true);
        steam_launcher.map_list_cards = vec![steam_map.clone()];
        steam_launcher.begin_edit_map(steam_map);
        assert!(steam_launcher
            .editor_maps_route_lines()
            .iter()
            .any(|line| line.contains("@view.workshop")));
        let view = steam_launcher
            .dispatch_editor_workshop_with_platform(&mut platform)
            .expect("steamid map should view listing id");
        assert_eq!(
            view.kind,
            super::DesktopEditorWorkshopActionKind::ViewListingId
        );
        assert_eq!(view.steam_id.as_deref(), Some("123456789"));
        assert_eq!(platform.viewed_listing_ids, vec!["123456789".to_string()]);

        let mut invalid_tags = BTreeMap::new();
        invalid_tags.insert("name".to_string(), "Invalid Arena".to_string());
        let mut invalid_map = MapDescriptor::new(
            "maps/custom/invalid-arena.msav",
            128,
            128,
            invalid_tags,
            true,
            2,
            158,
        );
        invalid_map.spawns = 1;
        let mut invalid_launcher = DesktopLauncher::new(Vec::new());
        invalid_launcher.menu_renderer_state.config = invalid_launcher
            .menu_renderer_state
            .config
            .with_desktop_workshop_enabled(true);
        invalid_launcher.map_list_cards = vec![invalid_map.clone()];
        invalid_launcher.begin_edit_map(invalid_map);
        let no_description = invalid_launcher
            .dispatch_editor_workshop_with_platform(&mut RecordingPlatform::default())
            .expect("invalid editor map should report no description");
        assert_eq!(
            no_description.kind,
            super::DesktopEditorWorkshopActionKind::ErrorNoDescription
        );
        assert_eq!(
            invalid_launcher.editor_workshop_error.as_deref(),
            Some("@editor.nodescription")
        );

        invalid_launcher.game_state.map.tags.insert(
            "description".to_string(),
            "Has description but no spawn".to_string(),
        );
        invalid_launcher.game_state.map.spawns = 0;
        let no_spawn = invalid_launcher
            .dispatch_editor_workshop_with_platform(&mut RecordingPlatform::default())
            .expect("invalid editor map should report no spawn");
        assert_eq!(
            no_spawn.kind,
            super::DesktopEditorWorkshopActionKind::ErrorNoSpawn
        );
        assert_eq!(
            invalid_launcher.editor_workshop_error.as_deref(),
            Some("@map.nospawn")
        );
    }

