    #[test]
    fn desktop_launcher_editor_map_info_locales_button_opens_map_locales_dialog_like_java() {
        let _lang_guard = EnvVarGuard::set("LANG", std::path::Path::new("en_US.UTF-8"));
        let mut locales = MapLocales::new();
        let selected_locale = String::from("fr");
        locales.put_property(selected_locale.as_str(), "name", "Nom Localisé");

        let mut tags = BTreeMap::new();
        tags.insert("name".to_string(), "Localized Arena".to_string());
        tags.insert("author".to_string(), "Mapper".to_string());
        tags.insert("locales".to_string(), locales.to_json_string());
        let mut map = MapDescriptor::new(
            "maps/custom/localized-arena.msav",
            180,
            180,
            tags,
            true,
            1,
            158,
        );
        map.spawns = 1;

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = selected_locale.clone();
        launcher.player_locale = selected_locale.clone();
        launcher.map_list_cards = vec![map];
        launcher.dispatch_menu_action(MenuButtonRole::Editor);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorInfo),
        ));
        assert_eq!(launcher.editor_map_info_dialog_index, Some(0));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Editor,
        );
        let dialog = DesktopLauncher::map_card_dialog_rect_for_panel(panel);
        let locales_button = DesktopLauncher::map_editor_locales_button_rect(dialog).center();
        let open_locales = super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorLocales),
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                locales_button.x,
                locales_button.y
            ),
            Some(open_locales)
        );

        launcher.dispatch_menu_route_shell_action(open_locales);
        assert_eq!(launcher.editor_map_info_dialog_index, Some(0));
        assert_eq!(launcher.editor_map_locales_dialog_index, Some(0));
        assert_eq!(
            launcher
                .editor_map_locales_dialog
                .as_ref()
                .map(|dialog| dialog.selected_locale.as_str()),
            Some(selected_locale.as_str()),
            "Java MapLocalesDialog selectedLocale must follow settings.locale, not the OS LANG fallback"
        );
        assert!(
            launcher
                .editor_map_locales_dialog
                .as_ref()
                .and_then(|dialog| {
                    dialog
                        .locales
                        .locales
                        .get(selected_locale.as_str())
                        .and_then(|values| values.get("name"))
                })
                .map(String::as_str)
                == Some("Nom Localisé")
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("MapLocalesDialog overlay should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            texts.iter().any(|text| text.contains("Nom Localisé")),
            "MapLocalesDialog should render the current locale property value from map.tags.locales; texts={texts:?}"
        );
        assert!(
            texts.iter().any(|text| *text == "name"),
            "MapLocalesDialog should render property keys from map.tags.locales"
        );

        let open_in_background = DesktopLauncher::map_editor_action_button_rect(dialog, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                open_in_background.x,
                open_in_background.y
            ),
            None,
            "MapLocalesDialog is modal like Java and must block EditorMapsDialog buttons behind it"
        );

        let locales_dialog = DesktopLauncher::map_editor_locales_dialog_rect_for_panel(panel);
        let close_locales = DesktopLauncher::map_editor_locales_close_rect(locales_dialog).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                close_locales.x,
                close_locales.y
            ),
            Some(super::DesktopMenuRouteShellAction::CloseEditorMapLocalesDialog)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::CloseEditorMapLocalesDialog,
        );
        assert_eq!(launcher.editor_map_locales_dialog_index, None);
        assert_eq!(
            launcher.editor_map_info_dialog_index,
            Some(0),
            "Closing MapLocalesDialog should return to the editor map info dialog"
        );
    }

