    #[test]
    fn desktop_launcher_editor_map_locales_search_filter_and_row_selection_match_java() {
        let mut locales = MapLocales::new();
        let current_locale = MapLocales::current_locale();
        locales.put_property(current_locale.as_str(), "name", "Current Localized Name");
        locales.put_property("fr", "name", "bonjour");
        locales.put_property("fr", "description", "salut");
        locales.put_property("en", "name", "hello");
        locales.put_property("en", "description", "world");
        locales.put_property("id_ID", "name", "halo");

        let mut tags = BTreeMap::new();
        tags.insert("name".to_string(), "Search Locales Arena".to_string());
        tags.insert("author".to_string(), "Mapper".to_string());
        tags.insert("locales".to_string(), locales.to_json_string());
        let mut map = MapDescriptor::new(
            "maps/custom/search-locales-arena.msav",
            180,
            180,
            tags,
            true,
            1,
            158,
        );
        map.spawns = 1;

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.map_list_cards = vec![map];
        launcher.dispatch_menu_action(MenuButtonRole::Editor);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorInfo),
        ));
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorLocales),
        ));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Editor,
        );
        let locales_dialog = DesktopLauncher::map_editor_locales_dialog_rect_for_panel(panel);

        let row_entries = DesktopLauncher::map_editor_locales_locale_rows_like_java(
            launcher
                .editor_map_locales_dialog
                .as_mut()
                .expect("editor locales dialog should open"),
            "en",
        );
        let fr_index = row_entries
            .iter()
            .enumerate()
            .find_map(|(index, entry)| match entry {
                MapLocalesDialogLocaleEntry::Locale(row) if row.locale == "fr" => Some(index),
                _ => None,
            })
            .expect("fr locale row should exist");
        match &row_entries[fr_index] {
            MapLocalesDialogLocaleEntry::Locale(row) => assert_eq!(
                row.display_name, "French",
                "Java MapLocalesDialog uses Locale.getDisplayName(Core.bundle.getLocale()), not LanguageDialog's native display name"
            ),
            other => panic!("expected fr locale row, got {other:?}"),
        }
        let locale_order = row_entries
            .iter()
            .filter_map(|entry| match entry {
                MapLocalesDialogLocaleEntry::Locale(row) => Some(row.locale.as_str()),
                MapLocalesDialogLocaleEntry::Add(_) => None,
            })
            .collect::<Vec<_>>();
        let id_pos = locale_order
            .iter()
            .position(|locale| *locale == "id_ID")
            .expect("id_ID row should be present");
        let en_pos = locale_order
            .iter()
            .position(|locale| *locale == "en")
            .expect("en row should be present");
        assert!(
            id_pos < en_pos,
            "Java MapLocalesDialog follows Vars.locales display-name order, so Bahasa Indonesia/id_ID appears before English/en; order={locale_order:?}"
        );
        let fr_row = DesktopLauncher::map_editor_locales_locale_row_rect(locales_dialog, fr_index);
        let select_action =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::SelectEditorLocales(fr_index),
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                fr_row.center().x,
                fr_row.center().y
            ),
            Some(select_action)
        );
        launcher.dispatch_menu_route_shell_action(select_action);
        assert_eq!(
            launcher
                .editor_map_locales_dialog
                .as_ref()
                .map(|dialog| dialog.selected_locale.as_str()),
            Some("fr")
        );
        let selected_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let selected_commands = selected_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("MapLocalesDialog selected frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let fr_item =
            DesktopLauncher::map_editor_locales_locale_item_rect(locales_dialog, fr_index);
        assert!(selected_commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &DesktopLauncher::settings_text_button_symbol_checked("flatTogglet", false, false, true)
                        && *rect == fr_item
            )
        }), "Java MapLocalesDialog locale rows use Styles.flatTogglet and drive checked=true for the selected locale");
        assert!(
            !selected_commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &DesktopLauncher::settings_text_button_symbol("flatTogglet", true, false)
                        && *rect == fr_item
            )),
            "selected locale must not be rendered as a mere hover state; Java calls b.setChecked(selectedLocale.equals(name))"
        );
        let collapse = DesktopLauncher::map_editor_locales_collapse_rect(locales_dialog);
        assert!(selected_commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, position, color, .. }
                    if text == &super::desktop_ui_icon_glyph_or_label("downOpen", "downOpen")
                        && *position == collapse.center()
                        && *color == mindustry_core::mindustry::ui::UiStyleColor::Gray.rgba()
            )
        }), "Java Styles.emptyTogglei renders the uncollapsed top collapse icon with imageUpColor=Color.gray");
        let filter_icon = DesktopLauncher::map_editor_locales_filter_icon_rect(locales_dialog);
        assert!(
            selected_commands.iter().any(|command| {
                matches!(
                    command,
                    RenderCommand::DrawText { text, position, color, .. }
                        if text == &super::desktop_ui_icon_glyph_or_label("filter", "filter")
                            && *position == filter_icon.center()
                            && *color == mindustry_core::mindustry::ui::UiStyleColor::White.rgba()
                )
            }),
            "Java Styles.emptyi renders the filter icon with imageUpColor=Color.white"
        );

        let search = DesktopLauncher::map_editor_locales_search_rect(locales_dialog);
        let search_action =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::FocusEditorLocalesSearch,
            ));
        assert_eq!(
            launcher.active_menu_text_input_at_surface_point(surface, search.center()),
            true,
            "MapLocalesDialog search field should accept keyboard focus like Java"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                search.center().x,
                search.center().y
            ),
            Some(search_action)
        );
        launcher.dispatch_menu_route_shell_action(search_action);
        launcher.apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("bonjour".into())]);
        assert_eq!(
            launcher
                .editor_map_locales_dialog
                .as_ref()
                .map(|dialog| dialog.search_string.as_str()),
            Some("bonjour")
        );

        let filtered_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let filtered_commands = filtered_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("MapLocalesDialog filtered frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let filtered_texts = filtered_commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            filtered_texts.iter().filter(|text| **text == "bonjour").count() == 1,
            "search-by-name should hide the current locale property value until the filter is toggled"
        );
        assert!(
            filtered_texts.iter().any(|text| *text == "French"),
            "Rendered MapLocalesDialog locale rows should use Locale.getDisplayName(Core.bundle.getLocale()) for the active English UI locale; texts={filtered_texts:?}"
        );
        let clear_rect = DesktopLauncher::map_editor_locales_search_clear_rect(locales_dialog);
        let cancel_glyph = super::desktop_ui_icon_glyph_or_label("cancel", "cancel");
        assert!(
            filtered_commands.iter().any(|command| {
                matches!(
                    command,
                    RenderCommand::DrawText { text, position, color, style, .. }
                        if text == &cancel_glyph
                            && *position == clear_rect.center()
                            && *color == mindustry_core::mindustry::ui::UiStyleColor::White.rgba()
                            && style.font == RenderFontId::Icon
                )
            }),
            "Java MapLocalesDialog search clear is an Icon.cancel Styles.emptyi ImageButton"
        );
        assert!(
            !filtered_commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if *rect == clear_rect
                        && symbol == &DesktopLauncher::settings_text_button_symbol("defaultt", false, false)
            )),
            "search clear must not draw a default TextButton background; Java uses Styles.emptyi"
        );

        let filter_action =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::OpenEditorLocalesFilter,
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                filter_icon.center().x,
                filter_icon.center().y
            ),
            Some(filter_action)
        );
        launcher.dispatch_menu_route_shell_action(filter_action);
        assert!(launcher.editor_map_locales_filter_open);
        assert!(
            !launcher
                .editor_map_locales_dialog
                .as_ref()
                .is_some_and(|dialog| dialog.search_by_value),
            "Java MapLocalesDialog Icon.filter opens filterDialog first; it must not toggle searchByValue immediately"
        );

        let filter_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let filter_texts = filter_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("MapLocalesDialog filterDialog frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        for expected in [
            launcher.localize_bundle_markup_text("@locales.filter"),
            launcher.localize_bundle_markup_text("@search"),
            launcher.localize_bundle_markup_text("@locales.byname"),
            launcher.localize_bundle_markup_text("@locales.byvalue"),
            launcher.localize_bundle_markup_text("@locales.showcorrect"),
            launcher.localize_bundle_markup_text("@locales.showmissing"),
            launcher.localize_bundle_markup_text("@locales.showsame"),
        ] {
            assert!(
                filter_texts.contains(&expected.as_str()),
                "Java MapLocalesDialog.filterDialog should render '{expected}', texts={filter_texts:?}"
            );
        }

        let filter_dialog = DesktopLauncher::map_editor_locales_filter_dialog_rect(locales_dialog);
        let byvalue = DesktopLauncher::map_editor_locales_filter_mode_button_rect(filter_dialog, 1);
        let byvalue_action =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::SetEditorLocalesSearchByValue(true),
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                byvalue.center().x,
                byvalue.center().y
            ),
            Some(byvalue_action)
        );
        launcher.dispatch_menu_route_shell_action(byvalue_action);
        assert!(launcher
            .editor_map_locales_dialog
            .as_ref()
            .is_some_and(|dialog| dialog.search_by_value));
        assert!(
            launcher.editor_map_locales_filter_open,
            "Java filterDialog stays open after choosing search mode"
        );

        let show_missing =
            DesktopLauncher::map_editor_locales_filter_status_button_rect(filter_dialog, 1);
        let show_missing_action =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::ToggleEditorLocalesShowMissing,
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                show_missing.center().x,
                show_missing.center().y
            ),
            Some(show_missing_action)
        );
        launcher.dispatch_menu_route_shell_action(show_missing_action);
        assert!(launcher
            .editor_map_locales_dialog
            .as_ref()
            .is_some_and(|dialog| !dialog.show_missing));
        let mut model_without_missing = launcher
            .editor_map_locales_dialog
            .as_ref()
            .expect("MapLocalesDialog should stay open")
            .clone();
        model_without_missing.clear_search();
        assert!(
            !model_without_missing
                .main_cards(panel.width, launcher.menu_ui_scale)
                .iter()
                .any(|card| {
                    card.status
                        == mindustry_core::mindustry::ui::dialogs::MapLocalesDialogPropertyStatus::Missing
                }),
            "Java filterDialog @locales.showmissing controls MapLocalesDialog.buildMain filtering"
        );

        let value_frame = launcher.menu_graphics_frame_for_surface(2, viewport);
        let value_texts = value_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("MapLocalesDialog value-filtered frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            value_texts
                .iter()
                .filter(|text| **text == "bonjour")
                .count()
                >= 2,
            "search-by-value should reveal the selected locale property card"
        );

        let filter_back = DesktopLauncher::map_editor_locales_filter_back_rect(filter_dialog);
        let close_filter_action =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::CloseEditorLocalesFilter,
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                filter_back.center().x,
                filter_back.center().y
            ),
            Some(close_filter_action)
        );
        launcher.dispatch_menu_route_shell_action(close_filter_action);
        assert!(!launcher.editor_map_locales_filter_open);

        let clear_action =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::ClearEditorLocalesSearch,
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                clear_rect.center().x,
                clear_rect.center().y
            ),
            Some(clear_action)
        );
        launcher.dispatch_menu_route_shell_action(clear_action);
        assert_eq!(
            launcher
                .editor_map_locales_dialog
                .as_ref()
                .map(|dialog| dialog.search_string.as_str()),
            Some("")
        );
    }

    #[test]
    fn desktop_launcher_editor_map_locales_add_locale_button_opens_picker_and_inserts_locale_like_java(
    ) {
        let mut locales = MapLocales::new();
        locales.put_property("en", "name", "English Localized Name");

        let mut tags = BTreeMap::new();
        tags.insert("name".to_string(), "Add Locale Arena".to_string());
        tags.insert("author".to_string(), "Mapper".to_string());
        tags.insert("locales".to_string(), locales.to_json_string());
        let mut map = MapDescriptor::new(
            "maps/custom/add-locale-arena.msav",
            180,
            180,
            tags,
            true,
            1,
            158,
        );
        map.spawns = 1;

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.map_list_cards = vec![map];
        launcher.dispatch_menu_action(MenuButtonRole::Editor);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorInfo),
        ));
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorLocales),
        ));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Editor,
        );
        let locales_dialog = DesktopLauncher::map_editor_locales_dialog_rect_for_panel(panel);
        let rows = DesktopLauncher::map_editor_locales_locale_rows_like_java(
            launcher
                .editor_map_locales_dialog
                .as_mut()
                .expect("MapLocalesDialog should be open"),
            "en",
        );
        let add_row_index = rows
            .iter()
            .position(|entry| matches!(entry, MapLocalesDialogLocaleEntry::Add(_)))
            .expect("Java MapLocalesDialog.buildLocalesTable appends an @add row");
        let add_row =
            DesktopLauncher::map_editor_locales_locale_item_rect(locales_dialog, add_row_index);
        let open_picker =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::OpenEditorLocalesAddLocaleChooser,
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                add_row.center().x,
                add_row.center().y
            ),
            Some(open_picker),
            "Clicking the left @add row should open Java's addLocaleDialog picker"
        );
        launcher.dispatch_menu_route_shell_action(open_picker);
        assert!(launcher.editor_map_locales_add_locale_open);
        assert!(!launcher.editor_map_locales_search_focused);

        let options = launcher.editor_map_locales_available_add_locale_options();
        assert!(!options.is_empty());
        let target_code = options[0].code.to_string();
        let target_label = super::map_locales_display_name_for_code(&target_code, "en");
        let chooser = DesktopLauncher::map_editor_locales_add_locale_dialog_rect(
            locales_dialog,
            options.len(),
        );
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("addLocaleDialog should render as a child BaseDialog")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            texts.contains(&target_label.as_str()),
            "addLocaleDialog should render missing locale display names localized by Core.bundle.getLocale(); texts={texts:?}"
        );

        let first_row = DesktopLauncher::map_editor_locales_add_locale_row_rect(chooser, 0);
        let add_locale =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::AddEditorLocalesLocale(0),
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                first_row.center().x,
                first_row.center().y
            ),
            Some(add_locale)
        );
        launcher.dispatch_menu_route_shell_action(add_locale);
        let dialog = launcher
            .editor_map_locales_dialog
            .as_ref()
            .expect("MapLocalesDialog should stay open after selecting a locale");
        assert!(!launcher.editor_map_locales_add_locale_open);
        assert_eq!(dialog.selected_locale, target_code);
        assert!(dialog.locales.locales.contains_key(&target_code));
        assert!(
            dialog.is_dirty(),
            "Selecting a missing locale should mark MapLocalesDialog dirty like Java"
        );
    }

    #[test]
    fn desktop_launcher_editor_map_locales_add_icon_button_opens_picker_and_appends_icon_like_java()
    {
        let mut locales = MapLocales::new();
        locales.put_property("en", "alpha", "Alpha ");
        locales.put_property("fr", "alpha", "Alpha FR");

        let mut tags = BTreeMap::new();
        tags.insert("name".to_string(), "Add Icon Arena".to_string());
        tags.insert("author".to_string(), "Mapper".to_string());
        tags.insert("locales".to_string(), locales.to_json_string());
        let mut map = MapDescriptor::new(
            "maps/custom/add-icon-arena.msav",
            180,
            180,
            tags,
            true,
            1,
            158,
        );
        map.spawns = 1;

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.map_list_cards = vec![map];
        launcher.dispatch_menu_action(MenuButtonRole::Editor);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorInfo),
        ));
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorLocales),
        ));

        let surface = DesktopSurfaceSize::new(1920, 1080);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Editor,
        );
        let locales_dialog = DesktopLauncher::map_editor_locales_dialog_rect_for_panel(panel);
        let main = DesktopLauncher::map_editor_locales_main_area_rect(locales_dialog);
        let columns_by_dialog =
            ((main.width + 10.0) / (super::MAP_LOCALES_CARD_WIDTH + 10.0)).floor() as usize;
        let columns =
            super::MapLocalesDialog::main_column_count(panel.width, launcher.menu_ui_scale)
                .min(columns_by_dialog.max(1))
                .max(1);
        let alpha_card = DesktopLauncher::map_editor_locales_card_rect(main, 0, columns);
        let edit = DesktopLauncher::map_editor_locales_card_edit_rect(alpha_card);
        let open_edit =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::OpenEditorLocalesPropertyEdit(0),
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                edit.center().x,
                edit.center().y
            ),
            Some(open_edit)
        );
        launcher.dispatch_menu_route_shell_action(open_edit);
        assert_eq!(
            launcher.editor_map_locales_property_edit_key.as_deref(),
            Some("alpha")
        );

        let edit_dialog =
            DesktopLauncher::map_editor_locales_property_edit_dialog_rect(locales_dialog);
        let add_icon_button =
            DesktopLauncher::map_editor_locales_property_edit_button_rect(edit_dialog, 2);
        let open_picker =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::OpenEditorLocalesAddIconChooser,
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                add_icon_button.center().x,
                add_icon_button.center().y
            ),
            Some(open_picker),
            "Java propEditDialog @locales.addicon opens addIconDialog instead of a disabled placeholder"
        );
        launcher.dispatch_menu_route_shell_action(open_picker);
        assert!(launcher.editor_map_locales_add_icon_open);
        assert_eq!(launcher.editor_map_locales_property_edit_key, None);
        assert_eq!(
            launcher.editor_map_locales_add_icon_key.as_deref(),
            Some("alpha")
        );

        let add_icon_dialog =
            DesktopLauncher::map_editor_locales_add_icon_dialog_rect(locales_dialog);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("addIconDialog should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@locales.addicon")
                .as_str()
        ));
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@search").as_str()));

        let search = DesktopLauncher::map_editor_locales_add_icon_search_rect(add_icon_dialog);
        let focus_search =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::FocusEditorLocalesAddIconSearch,
            ));
        assert_eq!(
            launcher.active_menu_text_input_at_surface_point(surface, search.center()),
            true
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                search.center().x,
                search.center().y
            ),
            Some(focus_search)
        );
        launcher.dispatch_menu_route_shell_action(focus_search);
        launcher
            .apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("right open".into())]);
        assert_eq!(launcher.editor_map_locales_add_icon_search, "right open");

        let candidates = launcher.editor_map_locales_add_icon_candidates();
        let candidate_index = candidates
            .iter()
            .position(|candidate| candidate.name == "rightOpen")
            .expect("Iconc.rightOpen should be searchable in addIconDialog");
        let expected_output = candidates[candidate_index].output.clone();
        let columns = DesktopLauncher::map_editor_locales_add_icon_columns(add_icon_dialog);
        let visible_rows =
            DesktopLauncher::map_editor_locales_add_icon_visible_rows(add_icon_dialog);
        assert!(
            candidate_index < columns * visible_rows,
            "rightOpen should be visible after filtering to a narrow Java Iconc search"
        );
        let cell = DesktopLauncher::map_editor_locales_add_icon_cell_rect(
            add_icon_dialog,
            candidate_index,
            columns,
        );
        let add_icon =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::AddEditorLocalesIcon(candidate_index),
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                cell.center().x,
                cell.center().y
            ),
            Some(add_icon)
        );
        launcher.dispatch_menu_route_shell_action(add_icon);
        let dialog = launcher
            .editor_map_locales_dialog
            .as_ref()
            .expect("MapLocalesDialog should remain open after choosing icon");
        assert!(!launcher.editor_map_locales_add_icon_open);
        assert_eq!(launcher.editor_map_locales_add_icon_key, None);
        assert_eq!(
            dialog
                .locales
                .locales
                .get("en")
                .and_then(|values| values.get("alpha"))
                .map(String::as_str),
            Some(format!("Alpha {expected_output}").as_str())
        );
        assert!(dialog.is_dirty());
    }

    #[test]
    fn desktop_launcher_editor_map_locales_property_add_panel_mutates_selected_or_all_locales_like_java(
    ) {
        let mut locales = MapLocales::new();
        locales.put_property("en", "name", "English Localized Name");
        locales.put_property("fr", "name", "Nom français");

        let mut tags = BTreeMap::new();
        tags.insert("name".to_string(), "Property Add Arena".to_string());
        tags.insert("author".to_string(), "Mapper".to_string());
        tags.insert("locales".to_string(), locales.to_json_string());
        let mut map = MapDescriptor::new(
            "maps/custom/property-add-arena.msav",
            180,
            180,
            tags,
            true,
            1,
            158,
        );
        map.spawns = 1;

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.map_list_cards = vec![map];
        launcher.dispatch_menu_action(MenuButtonRole::Editor);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorInfo),
        ));
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorLocales),
        ));

        let surface = DesktopSurfaceSize::new(1920, 1080);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Editor,
        );
        let locales_dialog = DesktopLauncher::map_editor_locales_dialog_rect_for_panel(panel);
        let name_rect = DesktopLauncher::map_editor_locales_property_name_rect(locales_dialog);
        let value_rect = DesktopLauncher::map_editor_locales_property_value_rect(locales_dialog);
        let add_rect = DesktopLauncher::map_editor_locales_property_add_rect(locales_dialog);

        assert!(launcher.active_menu_text_input_at_surface_point(surface, name_rect.center()));
        let focus_name =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::FocusEditorLocalesPropertyName,
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                name_rect.center().x,
                name_rect.center().y
            ),
            Some(focus_name)
        );
        launcher.dispatch_menu_route_shell_action(focus_name);
        launcher
            .apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("subtitle".into())]);
        assert_eq!(launcher.editor_map_locales_property_name, "subtitle");

        let focus_value =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::FocusEditorLocalesPropertyValue,
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                value_rect.center().x,
                value_rect.center().y
            ),
            Some(focus_value)
        );
        launcher.dispatch_menu_route_shell_action(focus_value);
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Text("hello everyone".into())],
        );
        assert_eq!(launcher.editor_map_locales_property_value, "hello everyone");

        let add_property =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::AddEditorLocalesProperty,
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                add_rect.center().x,
                add_rect.center().y
            ),
            Some(add_property)
        );
        launcher.dispatch_menu_route_shell_action(add_property);
        let dialog = launcher
            .editor_map_locales_dialog
            .as_ref()
            .expect("MapLocalesDialog should remain open after adding a property");
        assert_eq!(
            dialog
                .locales
                .locales
                .get("en")
                .and_then(|values| values.get("subtitle"))
                .map(String::as_str),
            Some("hello everyone")
        );
        assert_eq!(
            dialog
                .locales
                .locales
                .get("fr")
                .and_then(|values| values.get("subtitle"))
                .map(String::as_str),
            Some("hello everyone"),
            "Java MapLocalesDialog property @add writes to all locales when applytoall is checked"
        );
        assert!(dialog.is_dirty());
        assert!(launcher.editor_map_locales_property_name.is_empty());
        assert!(launcher.editor_map_locales_property_value.is_empty());
        assert_eq!(launcher.editor_map_locales_property_focused, None);

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::ToggleEditorLocalesApplyToAll,
            ),
        ));
        launcher.dispatch_menu_route_shell_action(focus_name);
        launcher.apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("credits".into())]);
        launcher.dispatch_menu_route_shell_action(focus_value);
        launcher.apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("solo".into())]);
        launcher.dispatch_menu_route_shell_action(add_property);
        let dialog = launcher
            .editor_map_locales_dialog
            .as_ref()
            .expect("MapLocalesDialog should remain open after adding selected-locale property");
        assert_eq!(
            dialog
                .locales
                .locales
                .get("en")
                .and_then(|values| values.get("credits"))
                .map(String::as_str),
            Some("solo")
        );
        assert!(
            !dialog
                .locales
                .locales
                .get("fr")
                .is_some_and(|values| values.contains_key("credits")),
            "Java MapLocalesDialog property @add writes only selectedLocale when applytoall is unchecked"
        );
    }

    #[test]
    fn desktop_launcher_editor_map_locales_property_trash_removes_selected_or_all_like_java() {
        let mut locales = MapLocales::new();
        locales.put_property("en", "alpha", "one");
        locales.put_property("en", "bravo", "two");
        locales.put_property("fr", "alpha", "un");
        locales.put_property("fr", "bravo", "deux");

        let mut tags = BTreeMap::new();
        tags.insert("name".to_string(), "Property Trash Arena".to_string());
        tags.insert("author".to_string(), "Mapper".to_string());
        tags.insert("locales".to_string(), locales.to_json_string());
        let mut map = MapDescriptor::new(
            "maps/custom/property-trash-arena.msav",
            180,
            180,
            tags,
            true,
            1,
            158,
        );
        map.spawns = 1;

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.map_list_cards = vec![map];
        launcher.dispatch_menu_action(MenuButtonRole::Editor);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorInfo),
        ));
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(0, super::DesktopMapCardActionKind::OpenEditorLocales),
        ));

        let surface = DesktopSurfaceSize::new(1920, 1080);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Editor,
        );
        let locales_dialog = DesktopLauncher::map_editor_locales_dialog_rect_for_panel(panel);
        let main = DesktopLauncher::map_editor_locales_main_area_rect(locales_dialog);
        let columns_by_dialog =
            ((main.width + 10.0) / (super::MAP_LOCALES_CARD_WIDTH + 10.0)).floor() as usize;
        let columns =
            super::MapLocalesDialog::main_column_count(panel.width, launcher.menu_ui_scale)
                .min(columns_by_dialog.max(1))
                .max(1);
        let first_card = DesktopLauncher::map_editor_locales_card_rect(main, 0, columns);
        let trash = DesktopLauncher::map_editor_locales_card_trash_rect(first_card);
        let remove_alpha =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::RemoveEditorLocalesProperty(0),
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                trash.center().x,
                trash.center().y
            ),
            Some(remove_alpha)
        );
        launcher.dispatch_menu_route_shell_action(remove_alpha);
        let dialog = launcher
            .editor_map_locales_dialog
            .as_ref()
            .expect("MapLocalesDialog should remain open after removing a property");
        assert!(
            !dialog
                .locales
                .locales
                .values()
                .any(|values| values.contains_key("alpha")),
            "Java remove button removes from all locales when applytoall is checked"
        );
        assert!(dialog.is_dirty());

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::MapCard(
            super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::ToggleEditorLocalesApplyToAll,
            ),
        ));
        let first_remaining = DesktopLauncher::map_editor_locales_card_rect(main, 0, columns);
        let trash = DesktopLauncher::map_editor_locales_card_trash_rect(first_remaining);
        let remove_bravo =
            super::DesktopMenuRouteShellAction::MapCard(super::DesktopMapCardAction::new(
                0,
                super::DesktopMapCardActionKind::RemoveEditorLocalesProperty(0),
            ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                trash.center().x,
                trash.center().y
            ),
            Some(remove_bravo)
        );
        launcher.dispatch_menu_route_shell_action(remove_bravo);
        let dialog = launcher
            .editor_map_locales_dialog
            .as_ref()
            .expect("MapLocalesDialog should remain open after selected-locale remove");
        assert!(
            !dialog
                .locales
                .locales
                .get("en")
                .is_some_and(|values| values.contains_key("bravo")),
            "Java remove button removes only selectedLocale when applytoall is unchecked"
        );
        assert!(
            dialog
                .locales
                .locales
                .get("fr")
                .is_some_and(|values| values.contains_key("bravo")),
            "Other locale should keep the property when applytoall is unchecked"
        );
    }

