    #[test]
    fn desktop_launcher_schematic_tags_modal_and_icon_picker_do_not_hard_truncate_like_java() {
        let surface = DesktopSurfaceSize::new(1280, 720);
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.schematic_tag_order = (0..7).map(|index| format!("tag{index}")).collect();
        launcher.schematic_cards = vec![super::DesktopSchematicCardEntry {
            name: "Canonical Tags".into(),
            description: String::new(),
            width: 1,
            height: 1,
            tile_count: 1,
            requirements: Vec::new(),
            power_consumption_centi: 0,
            power_production_centi: 0,
            preview_tiles: Vec::new(),
            labels: vec!["tag0".into()],
            has_steam_id: false,
            mod_name: None,
        }];
        launcher.dispatch_menu_action(MenuButtonRole::Schematics);
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenSchematicTags,
        );

        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Schematics,
        );
        let dialog = DesktopLauncher::schematic_info_dialog_rect_for_panel(panel);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("tags modal should render all canonical tags")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&"tag6 | 0"));
        let tag6 = DesktopLauncher::schematic_tag_editor_select_rect(
            DesktopLauncher::schematic_tag_editor_row_rect(dialog, 6),
        )
        .center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, tag6.x, tag6.y),
            Some(super::DesktopMenuRouteShellAction::SchematicModalButton(
                super::DesktopSchematicModalButton::TagSelect(6)
            )),
            "Tags modal render and hit-test should cover the same full tag list"
        );

        launcher.schematic_modal = Some(super::DesktopSchematicModal::IconTag { card_index: 0 });
        let candidates = launcher.schematic_icon_tag_candidates();
        let accessible_count = super::SCHEMATIC_ICON_TAG_ACCESSIBLE_ICONS_LIKE_JAVA.len();
        assert!(
            candidates
                .iter()
                .take(accessible_count)
                .all(|candidate| candidate.section == super::MapLocalesDialogIconSectionKind::Iconc),
            "Java showNewIconTag renders Vars.accessibleIcons before content icon sections"
        );
        assert!(
            candidates.iter().any(|candidate| matches!(
                candidate.section,
                super::MapLocalesDialogIconSectionKind::Content(ContentType::Item)
            )),
            "Java showNewIconTag appends unlocked item content emojis after accessibleIcons"
        );
        assert!(
            candidates.iter().any(|candidate| matches!(
                candidate.section,
                super::MapLocalesDialogIconSectionKind::Content(ContentType::Liquid)
                    | super::MapLocalesDialogIconSectionKind::Content(ContentType::Block)
            )),
            "Java showNewIconTag appends defaultContentIcons sections, not just Iconc glyphs"
        );
        assert!(
            candidates.len() > 24,
            "upstream icon picker has more than the old Rust hard limit"
        );
        let candidate_text = candidates[24].output.clone();
        let frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("icon tag picker should render candidates past the old limit")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&candidate_text.as_str()));
        let icon_tag_title = launcher.localize_bundle_markup_text("@schematic.icontag");
        assert!(
            !texts.contains(&icon_tag_title.as_str()),
            "Java showNewIconTag uses a bare fullscreen Dialog body; Rust should not add an Icon Tag title"
        );
        let icon_dialog = DesktopLauncher::schematic_icon_tag_dialog_rect_for_panel(panel);
        assert_eq!(
            DesktopLauncher::schematic_icon_tag_button_rect(icon_dialog, 0).width,
            super::SCHEMATIC_ICON_TAG_BUTTON_SIZE_LIKE_JAVA
        );
        assert_eq!(
            DesktopLauncher::schematic_icon_tag_button_rect(icon_dialog, 0).height,
            super::SCHEMATIC_ICON_TAG_BUTTON_SIZE_LIKE_JAVA
        );
        assert!(
            DesktopLauncher::schematic_icon_tag_columns(icon_dialog) > 6,
            "Java columns are width-based up to 20, not the old fixed 6-column grid"
        );
        let icon24 = DesktopLauncher::schematic_icon_tag_button_rect(icon_dialog, 24).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, icon24.x, icon24.y),
            Some(super::DesktopMenuRouteShellAction::SchematicModalButton(
                super::DesktopSchematicModalButton::CardTagAddIcon {
                    card_index: 0,
                    icon_index: 24
                }
            ))
        );
    }

    #[test]
    fn desktop_launcher_schematics_icon_tag_picker_scrolls_overflow_candidates_like_java() {
        let surface = DesktopSurfaceSize::new(640, 360);
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.schematic_cards = vec![super::DesktopSchematicCardEntry {
            name: "Scrollable Tags".into(),
            description: String::new(),
            width: 1,
            height: 1,
            tile_count: 1,
            requirements: Vec::new(),
            power_consumption_centi: 0,
            power_production_centi: 0,
            preview_tiles: Vec::new(),
            labels: Vec::new(),
            has_steam_id: false,
            mod_name: None,
        }];
        launcher.dispatch_menu_action(MenuButtonRole::Schematics);
        launcher.schematic_modal = Some(super::DesktopSchematicModal::IconTag { card_index: 0 });

        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Schematics,
        );
        let dialog = DesktopLauncher::schematic_icon_tag_dialog_rect_for_panel(panel);
        let clip = DesktopLauncher::schematic_icon_tag_clip_rect(dialog);
        let candidates = launcher.schematic_icon_tag_candidates();
        let max_scroll =
            DesktopLauncher::schematic_icon_tag_max_scroll_rows(dialog, candidates.len());
        assert!(
            max_scroll > 0,
            "Java showNewIconTag wraps candidates in a scroll pane when icon rows overflow"
        );

        let cursor = clip.center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: cursor.x,
                    y: cursor.y,
                },
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -100.0,
                },
            ],
        );
        assert_eq!(
            launcher.schematic_icon_tag_scroll_offset, max_scroll,
            "wheel input over the icon pane should clamp to the final Java-like row window"
        );

        let (_, first_index, capacity) = DesktopLauncher::schematic_icon_tag_visible_window(
            dialog,
            candidates.len(),
            launcher.schematic_icon_tag_scroll_offset,
        );
        let target_index = candidates.len() - 1;
        assert!(
            target_index >= first_index && target_index < first_index + capacity,
            "the last icon candidate should become visible after scrolling to the bottom"
        );
        let target =
            DesktopLauncher::schematic_icon_tag_button_rect(dialog, target_index - first_index)
                .center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, target.x, target.y),
            Some(super::DesktopMenuRouteShellAction::SchematicModalButton(
                super::DesktopSchematicModalButton::CardTagAddIcon {
                    card_index: 0,
                    icon_index: target_index
                }
            ))
        );

        let back = DesktopLauncher::schematic_info_button_rect(dialog, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, back.x, back.y),
            Some(super::DesktopMenuRouteShellAction::SchematicModalButton(
                super::DesktopSchematicModalButton::Back
            )),
            "the Java back button stays outside the scroll pane and remains clickable"
        );

        let frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("scrolled icon picker should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::SetClip { rect } if *rect == clip
        )));
        assert!(commands
            .iter()
            .any(|command| matches!(command, RenderCommand::ClearClip)));
    }

