        assert_eq!(
            launcher.last_database_content_opened,
            Some((ContentType::Item, "copper".to_string()))
        );
        let hidden_copper_details = "Hidden copper lore should stay locked".to_string();
        {
            let copper = launcher
                .content_loader
                .catalog_mut()
                .items
                .iter_mut()
                .find(|item| item.base.mappable.name == "copper")
                .expect("base content should expose copper");
            copper.base.details = Some(hidden_copper_details.clone());
            copper.base.hide_details = true;
            copper.base.always_unlocked = false;
            copper.base.unlocked = false;
        }
        let detail_lines =
            launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Database);
        assert!(detail_lines.contains(&"dialog: ContentInfoDialog".to_string()));
        assert!(detail_lines.contains(&"@info.title".to_string()));
        assert!(detail_lines.contains(&"content: item / copper".to_string()));

        let detail_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let detail_commands = detail_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("database content info frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let detail_texts = detail_commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            detail_texts.contains(&launcher.localize_bundle_markup_text("@info.title").as_str())
        );
        assert!(detail_texts.contains(&"[accent]copper"));
        assert!(
            detail_texts.contains(&"copper"),
            "Java ContentInfoDialog appends raw content.name below localizedName when console setting is enabled"
        );
        assert!(
            !detail_texts.contains(&"item / copper"),
            "Java ContentInfoDialog header shows raw content.name in console mode, not a Rust-side content_type/name debug label"
        );
        launcher.menu_console_setting_enabled = false;
        let no_console_detail_frame = launcher.menu_graphics_frame_for_surface(2, viewport);
        let no_console_detail_texts = no_console_detail_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("non-console database content info frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(no_console_detail_texts.contains(&"[accent]copper"));
        assert!(
            !no_console_detail_texts.contains(&"copper"),
            "Java ContentInfoDialog omits the raw content.name line when console setting is disabled"
        );
        launcher.menu_console_setting_enabled = true;
        let patched_text = launcher.localize_bundle_markup_text("@database.patched");
        assert!(
            !detail_texts.contains(&patched_text.as_str()),
            "Java ContentInfoDialog only shows @database.patched while state.isGame()"
        );
        launcher.game_state.set(GameStateState::Playing);
        let game_detail_frame = launcher.menu_graphics_frame_for_surface(2, viewport);
        let game_detail_texts = game_detail_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("in-game database content info frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
