    #[test]
    fn desktop_launcher_database_treats_non_campaign_game_content_as_unlocked_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let hidden_copper_details = "Hidden copper lore should be visible outside campaign games";
        {
            let copper = launcher
                .content_loader
                .catalog_mut()
                .items
                .iter_mut()
                .find(|item| item.base.mappable.name == "copper")
                .expect("base content should expose copper");
            copper.base.details = Some(hidden_copper_details.into());
            copper.base.hide_details = true;
            copper.base.always_unlocked = false;
            copper.base.unlocked = false;
        }

        assert!(!launcher.database_content_unlocked(ContentType::Item, "copper"));
        let locked_details = launcher.localize_bundle_markup_text_or(
            "@unlock.incampaign",
            "< Unlock in campaign for details >",
        );
        let resolved_locked_details = launcher
            .database_content_resolved_details_like_java(ContentType::Item, "copper")
            .expect("locked hideDetails content should render the unlock placeholder");
        assert!(
            resolved_locked_details.contains(&locked_details),
            "menu DatabaseDialog should still hide locked hideDetails content"
        );

        launcher.game_state.set(GameStateState::Playing);
        assert!(
            !launcher.game_state.is_campaign(),
            "test fixture should be a non-campaign game"
        );
        assert!(launcher.database_content_unlocked(ContentType::Item, "copper"));
        assert_eq!(
            launcher.database_content_resolved_details_like_java(ContentType::Item, "copper"),
            Some(hidden_copper_details.to_string()),
            "Java DatabaseDialog.unlocked() returns true outside campaign/menu, so ContentInfoDialog reveals details"
        );
    }

    #[test]
    fn desktop_launcher_database_search_matches_java_localized_name_only() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let (probe_type, probe_name, probe_display) = ContentType::ALL
            .into_iter()
            .find_map(|content_type| {
                launcher
                    .database_visible_records_for_type(content_type)
                    .into_iter()
                    .find_map(|(_, name)| {
                        let display = launcher.database_content_display_name(content_type, name);
                        let raw_lower = name.to_lowercase();
                        let display_lower = display.to_lowercase();
                        (!display_lower.is_empty()
                            && display_lower != raw_lower
                            && !display_lower.contains(&raw_lower))
                        .then(|| (content_type, name.to_string(), display_lower))
                    })
            })
            .expect("base database should expose a visible content entry with localizedName != raw name");

        launcher.database_search = probe_display.clone();
        assert!(
            launcher
                .database_visible_records_for_type(probe_type)
                .iter()
                .any(|(_, name)| *name == probe_name),
            "Java DatabaseDialog search matches the localized/display name"
        );

        launcher.database_search = probe_name.clone();
        assert!(
            !launcher
                .database_visible_records_for_type(probe_type)
                .iter()
                .any(|(_, name)| *name == probe_name),
            "Java DatabaseDialog does not search the raw content name when it differs from localizedName"
        );

        launcher.database_search = "copper".into();
        assert!(launcher
            .database_visible_records_for_type(ContentType::Item)
            .iter()
            .any(|(_, name)| *name == "copper"));
        launcher.database_search = " copper".into();
        assert!(
            !launcher
                .database_visible_records_for_type(ContentType::Item)
                .iter()
                .any(|(_, name)| *name == "copper"),
            "Java DatabaseDialog keeps leading spaces in search.getText().toLowerCase()"
        );

        launcher.database_search.clear();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Database);
        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("database route frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@players.search")
                .as_str()
        ));
        for raw_key in ["@players.search", "@database-category.", "@database-tag."] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "Database visible route text should localize {raw_key}; raw keys are diagnostic-only"
            );
        }
    }

