    #[test]
    fn desktop_launcher_database_content_info_stats_keep_java_stat_categories() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let first_block_name = launcher
            .database_visible_records_for_type(ContentType::Block)
            .first()
            .map(|(_, name)| (*name).to_string())
            .expect("base content should expose at least one block in DatabaseDialog");
        let block_stats =
            launcher.database_content_stats_like_java(ContentType::Block, &first_block_name);
        assert!(
            block_stats.use_categories,
            "Java Block.init() sets stats.useCategories=true before ContentInfoDialog.show() renders StatCat headers"
        );
        assert!(block_stats
            .groups
            .iter()
            .any(|group| group.category == "general"
                && group.lines.iter().any(|line| line.label == "@stat.health")));

        let first_unit_name = launcher
            .database_visible_records_for_type(ContentType::Unit)
            .first()
            .map(|(_, name)| (*name).to_string())
            .expect("base content should expose at least one unit in DatabaseDialog");
        let unit_stats =
            launcher.database_content_stats_like_java(ContentType::Unit, &first_unit_name);
        assert!(
            !unit_stats.use_categories,
            "UnitType stats stay in Java's default flat ContentInfoDialog mode unless the content opts into StatCat headers"
        );
        assert!(unit_stats
            .groups
            .iter()
            .any(|group| group.category == "function"
                && group.lines.iter().any(|line| line.label == "@stat.range")));
        assert_eq!(
            unit_stats.visible_category_count(),
            1,
            "non-categorized Java stats render under one @category.general header even when individual Stat values have function categories"
        );

        launcher.active_menu_route = Some(super::DesktopMenuRoute::Database);
        launcher.last_database_content_opened = Some((ContentType::Unit, first_unit_name));
        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("database content info frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@category.general")
                .as_str()
        ));
        for raw_key in ["@info.title", "@category.general", "@stat.range"] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "ContentInfoDialog visible text should localize {raw_key}; raw content field names are handled separately"
            );
        }
        assert!(
            !texts.contains(
                &launcher
                    .localize_bundle_markup_text("@category.function")
                    .as_str()
            ),
            "ContentInfoDialog should not display StatCat.function when stats.useCategories=false"
        );
    }

    #[test]
    fn desktop_launcher_database_content_info_header_scrolls_like_java_scrollpane() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.dispatch_menu_action(MenuButtonRole::Database);
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Database);
        let surface = DesktopSurfaceSize::new(960, 480);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Database,
        );
        let dialog = DesktopLauncher::database_content_info_dialog_rect_for_panel(panel);
        let clip = DesktopLauncher::database_content_info_scrollpane_rect(dialog);

        let (content_type, name) = ContentType::ALL
            .into_iter()
            .find_map(|content_type| {
                launcher
                    .database_visible_records_for_type(content_type)
                    .into_iter()
                    .find_map(|(_, name)| {
                        (launcher.max_database_content_info_scroll_offset(clip, content_type, name)
                            > 0.0)
                            .then(|| (content_type, name.to_string()))
                    })
            })
            .expect("base Database content should include an overflowing ContentInfoDialog entry");

        let top_table_height =
            launcher.database_content_info_body_height(clip, content_type, &name);
        let top_content =
            launcher.database_content_info_scrolled_content_rect(clip, content_type, &name);
        assert!(
            top_table_height > clip.height,
            "fixture should force Java ScrollPane overflow for the whole ContentInfoDialog table"
        );
        assert_eq!(
            top_content.height, top_table_height,
            "scrolled content rect should model Java's whole ScrollPane table, including the header"
        );
        assert!(
            (top_content.y + top_content.height - (clip.y + clip.height)).abs() < 0.01,
            "unscrolled Java ScrollPane table should align its top with the clipped viewport top"
        );
        assert!(
            top_content.y < clip.y,
            "overflowing Java ScrollPane table should extend below the clipped viewport"
        );

        launcher.last_database_content_opened = Some((content_type, name.clone()));
        launcher.database_content_info_scroll_offset = 0.0;
        let top_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let top_commands = top_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("database content info should render at the top")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let content_text_after_clip = |commands: &[&RenderCommand]| -> Option<(String, f32)> {
            let mut inside_content_clip = false;
            for command in commands.iter().copied() {
                match command {
                    RenderCommand::SetClip { .. } => {
                        inside_content_clip = true;
                    }
                    RenderCommand::ClearClip if inside_content_clip => break,
                    RenderCommand::DrawText { text, position, .. }
                        if inside_content_clip && !text.trim().is_empty() =>
                    {
                        return Some((text.clone(), position.y));
                    }
                    _ => {}
                }
            }
            None
        };
        let (probe_label, top_probe_y) = content_text_after_clip(&top_commands)
            .expect("top ContentInfoDialog should render text inside the scroll pane");
        let display_name = format!(
            "[accent]{}",
            launcher.database_content_display_name(content_type, &name)
        );
        let text_position_after_clip = |commands: &[&RenderCommand], expected: &str| {
            let mut inside_content_clip = false;
            for command in commands.iter().copied() {
                match command {
                    RenderCommand::SetClip { .. } => inside_content_clip = true,
                    RenderCommand::ClearClip if inside_content_clip => break,
                    RenderCommand::DrawText { text, position, .. }
                        if inside_content_clip && text == expected =>
                    {
                        return Some(*position);
                    }
                    _ => {}
                }
            }
            None
        };
        let top_header_position = text_position_after_clip(&top_commands, &display_name).expect(
            "Java ContentInfoDialog header display name should be inside the ScrollPane table",
        );
        assert!(
            clip.contains_point(top_header_position),
            "ContentInfoDialog header display name should start inside the clipped ScrollPane viewport"
        );

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: clip.center().x,
                    y: clip.center().y,
                },
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -1.0,
                },
            ],
        );
        assert!(
            launcher.database_content_info_scroll_offset > 0.0,
            "Java ContentInfoDialog wraps details in a ScrollPane, so wheel input inside it should scroll the detail content"
        );
        let scrolled_content =
            launcher.database_content_info_scrolled_content_rect(clip, content_type, &name);
        assert_eq!(
            (scrolled_content.y + scrolled_content.height - top_content.y - top_content.height)
                .round() as i32,
            super::DATABASE_CONTENT_INFO_SCROLL_ROW_HEIGHT.round() as i32,
            "scrolling should move the whole Java ScrollPane table, not just the post-header body"
        );

        let scrolled_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let scrolled_commands = scrolled_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("scrolled database content info should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        assert!(scrolled_commands
            .iter()
            .any(|command| matches!(command, RenderCommand::SetClip { .. })));
        assert!(scrolled_commands
            .iter()
            .any(|command| matches!(command, RenderCommand::ClearClip)));
        let scrolled_probe_y = scrolled_commands
            .iter()
            .find_map(|command| match command {
                RenderCommand::DrawText { text, position, .. } if text == &probe_label => {
                    Some(position.y)
                }
                _ => None,
            })
            .expect("scrolled ContentInfoDialog should still render the probe stat label");
        assert_eq!(
            (scrolled_probe_y - top_probe_y).round() as i32,
            super::DATABASE_CONTENT_INFO_SCROLL_ROW_HEIGHT.round() as i32,
            "scrolling the Java ContentInfoDialog ScrollPane should move only the clipped detail content"
        );
        let scrolled_header_position = text_position_after_clip(&scrolled_commands, &display_name)
            .expect("scrolled ContentInfoDialog should still render the header display name");
        assert_eq!(
            (scrolled_header_position.y - top_header_position.y).round() as i32,
            super::DATABASE_CONTENT_INFO_SCROLL_ROW_HEIGHT.round() as i32,
            "Java ContentInfoDialog puts icon/name header in the same ScrollPane table as description/stats"
        );

        let close = DesktopLauncher::database_content_info_close_rect(dialog).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, close.x, close.y),
            Some(super::DesktopMenuRouteShellAction::CloseDatabaseContent),
            "ContentInfoDialog close button should remain outside the scrolling pane"
        );
    }

    #[test]
    fn desktop_launcher_database_content_info_dialog_renders_team_extra_after_viewfields() {
        let mut catalog = mindustry_core::mindustry::content::ContentCatalog::default();
        catalog
            .team_entries
            .push(mindustry_core::mindustry::r#type::TeamEntry::new(
                0, "crux", 2,
            ));
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.content_loader =
            mindustry_core::mindustry::core::content_loader::ContentLoader::from_catalog(catalog)
                .expect("test catalog with a TeamEntry should build");
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Database);
        launcher.menu_console_setting_enabled = true;
        launcher.last_database_content_opened = Some((ContentType::Team, "crux".into()));

        let extra = launcher
            .database_content_extra_like_java(ContentType::Team, "crux")
            .expect("Java TeamEntry.displayExtra should expose team lore");
        assert_eq!(
            extra,
            launcher.localize_bundle_markup_text_or("@team.crux.log", "@team.crux.log")
        );

        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Team ContentInfoDialog should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.clone()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let viewfields_label = launcher.localize_bundle_markup_text("@viewfields");
        let viewfields_index = texts
            .iter()
            .position(|text| text == &viewfields_label)
            .expect(
                "console-enabled ContentInfoDialog should render @viewfields before displayExtra",
            );
        assert!(
            !texts.iter().any(|text| text.contains("@viewfields")),
            "ContentInfoDialog final DrawText should localize @viewfields before rendering"
        );
        let extra_index = texts
            .iter()
            .position(|text| text == &extra)
            .expect("TeamEntry.displayExtra should render the team lore text");
        assert!(
            extra_index > viewfields_index,
            "Java ContentInfoDialog invokes content.displayExtra(table) after the console @viewfields button"
        );
    }

    #[test]
    fn desktop_launcher_menu_renders_logo_and_version_overlay() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        assert!(launcher.texture_atlas.lookup("logo").is_ok());
        assert!(launcher.texture_atlas.lookup("serpulo").is_ok());
        assert!(launcher.texture_atlas.lookup("erekir").is_ok());
        assert!(launcher.texture_atlas.lookup("discord-banner").is_ok());
        assert!(launcher.texture_atlas.lookup("info-banner").is_ok());
        assert!(launcher.texture_atlas.lookup("flat-down-base.9").is_ok());
        assert!(launcher.texture_atlas.lookup("window-empty.9").is_ok());
        assert!(launcher.texture_atlas.lookup("pane.9").is_ok());
        assert!(launcher.texture_atlas.lookup("button.9").is_ok());
        assert!(launcher.texture_atlas.lookup("button-down.9").is_ok());
        assert!(launcher.texture_atlas.lookup("whiteui").is_ok());
        assert!(launcher.texture_atlas.lookup("sand-floor1").is_ok());
        assert!(launcher.texture_atlas.lookup("shale-wall1").is_ok());
        assert!(launcher.texture_atlas.lookup("ore-copper1").is_ok());

        for source_path in upstream_ui_skin_sprite_source_paths() {
            let atlas_name =
                TextureAtlasSpriteSourceDescriptor::from_source_path(source_path).atlas_name;
            assert!(
                launcher.texture_atlas.lookup(&atlas_name).is_ok(),
                "default desktop atlas should include upstream UI skin sprite: {source_path}"
            );
        }

        assert!(
            launcher.texture_atlas.lookup("menu-label-zh-play").is_err(),
            "Java MenuFragment renders localized button labels through Core.bundle text; generated Chinese menu label sprites are transitional Rust-only assets and must not be part of the default atlas"
        );

        for source_path in desktop_menu_icon_sprite_virtual_source_paths() {
            let atlas_name =
                TextureAtlasSpriteSourceDescriptor::from_virtual_source_path(source_path.as_str())
                    .atlas_name;
            let region = launcher
                .texture_atlas
                .lookup(&atlas_name)
                .unwrap_or_else(|_| {
                    panic!(
                    "default desktop atlas should include upstream menu icon sprite: {source_path}"
                )
                });
            assert_eq!(region.region.source_path, source_path.as_str());
        }

        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);
        assert!(launcher
            .menu_renderer_state
            .select_desktop_root(MenuButtonRole::Play));
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let render_frame = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame");
        assert_eq!(render_frame.passes.len(), 1);
        let menu_pass = &render_frame.passes[0];
        assert!(!menu_pass.commands.is_empty());
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();

        assert!(
            commands.iter().any(|command| {
                DesktopLauncher::render_command_layer(command).is_some_and(|layer| {
                    (-130.0..=-80.0).contains(&layer)
                        || (layer - super::MENU_DARKNESS_LAYER).abs() < f32::EPSILON
                })
            }),
            "menu frame should include either the Java world background darkness layer or the current bucketed synthetic menu background"
        );
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. } if text == "Play"
            )
        }));
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. } if text == "Campaign"
            )
        }));
        let logo = commands
            .iter()
            .find_map(|command| match command {
                RenderCommand::DrawSprite {
                    symbol,
                    rect,
                    layer,
                    ..
                } if symbol == "logo" => Some((*rect, *layer)),
                _ => None,
            })
            .expect("menu chrome should draw the logo sprite");
        assert_eq!(
            logo,
            (
                RenderRect::new(256.0, 607.0, 768.0, 107.0),
                Layer::END_PIXELED + 0.08
            )
        );
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, position, color, style, layer, .. }
                    if text == &upstream_menu_version_text()
                        && *position == RenderPoint::new(640.0, 605.0)
                        && *color == upstream_menu_version_color()
                        && style.font == RenderFontId::Outline
                        && !style.outline
                        && (*layer - (Layer::END_PIXELED + 0.09)).abs() < f32::EPSILON
            )
        }));
    }

