    #[test]
    fn desktop_launcher_menu_uses_settings_locale_bundle_for_menu_buttons() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "zh_CN".into();
        assert!(launcher
            .menu_renderer_state
            .select_desktop_root(MenuButtonRole::Database));

        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let sprites = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawSprite { symbol, .. } => Some(symbol.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();

        for key in [
            "@settings",
            "@mods",
            "@database.button",
            "@database",
            "@schematics",
            "@about.button",
        ] {
            let expected = launcher.localize_bundle_markup_text(key);
            assert!(
                texts.contains(&expected.as_str()),
                "desktop menu final DrawText should contain localized {key} label `{expected}`"
            );
        }
        assert!(!sprites
            .iter()
            .any(|symbol| symbol.starts_with("menu-label-zh-")));
        assert!(
            !texts.contains(&"Core Database"),
            "Java MenuFragment resolves @database through the active Core.bundle locale and renders it as text"
        );
        assert!(
            !texts.iter().any(|text| text.starts_with('@')),
            "menu final DrawText should not leak raw bundle keys for root/submenu labels"
        );
    }

