    #[test]
    fn desktop_launcher_menu_route_titles_use_settings_locale_bundle_like_java_dialogs() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "zh_CN".into();

        assert_eq!(
            launcher.localized_menu_route_title(DesktopMenuRoute::Join),
            "加入游戏"
        );
        assert_eq!(
            launcher.localized_menu_route_title(DesktopMenuRoute::Host),
            "创建联机游戏"
        );
        assert_eq!(
            launcher.localized_menu_route_title(DesktopMenuRoute::SaveGame),
            "保存游戏"
        );
        assert_eq!(
            launcher.localized_menu_route_title(DesktopMenuRoute::Database),
            "核心数据库"
        );
        assert_eq!(
            launcher.localized_menu_route_title(DesktopMenuRoute::TechTree),
            "",
            "Java ResearchDialog calls super(\"\"); @techtree is the menu-entry text, not the dialog title"
        );
        assert_eq!(
            launcher.localized_menu_route_title(DesktopMenuRoute::Discord),
            "",
            "Java DiscordDialog calls super(\"\") and renders @discord inside the dialog content"
        );
        assert_eq!(
            launcher.localized_menu_route_title(DesktopMenuRoute::Editor),
            "地图",
            "Java EditorMapsDialog uses @maps as its dialog title; @editor is only the menu-entry label"
        );

        launcher.active_menu_route = Some(DesktopMenuRoute::Join);
        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu route frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();

        assert!(texts.contains(&"加入游戏"));
        assert!(texts.contains(&"名称："));
        assert!(texts.contains(&"添加服务器"));
        assert!(texts.contains(&"本地服务器"));
        assert!(texts.contains(&"远程服务器"));
        assert!(
            !texts.contains(&"JOIN GAME"),
            "route shell title should not bypass Core.bundle with hard-coded all-caps text"
        );
        for raw_key in ["@name", "@server.add", "@servers.local"] {
            assert!(
                !texts.contains(&raw_key),
                "JoinDialog chrome should resolve visible bundle key {raw_key} before rendering"
            );
        }

        let mut fallback_launcher = DesktopLauncher::new(Vec::new());
        fallback_launcher.settings_locale = "unknown".into();
        assert_eq!(
            fallback_launcher.localized_menu_route_title(DesktopMenuRoute::Join),
            "Join Game"
        );
        assert_eq!(
            fallback_launcher.localized_menu_route_title(DesktopMenuRoute::Host),
            "Host Multiplayer Game"
        );
        for route in [
            DesktopMenuRoute::Host,
            DesktopMenuRoute::SaveGame,
            DesktopMenuRoute::LoadGame,
            DesktopMenuRoute::Join,
            DesktopMenuRoute::Database,
            DesktopMenuRoute::Mods,
            DesktopMenuRoute::Settings,
        ] {
            assert!(
                !route.fallback_title().contains('@'),
                "{route:?} fallback title should be human-readable instead of a raw bundle key"
            );
        }
    }

    #[test]
    fn desktop_launcher_default_font_asset_sources_follow_upstream_fonts_registry() {
        let launcher = DesktopLauncher::new(Vec::new());
        let source_paths = launcher
            .font_asset_sources
            .iter()
            .map(|source| source.source_path.as_str())
            .collect::<Vec<_>>();

        assert!(source_paths.contains(&"fonts/font.woff"));
        assert!(source_paths.contains(&"fonts/font_jp.woff"));
        assert!(source_paths.contains(&"fonts/icon.ttf"));
        assert!(source_paths.contains(&"fonts/logic.ttf"));
        assert!(source_paths.contains(&"fonts/monospace.woff"));
        assert!(source_paths.contains(&"fonts/tech.ttf"));
        assert!(source_paths.contains(&"icons/icons.properties"));
        let report = launcher.font_asset_validation_report();
        assert!(report.total_count <= launcher.font_asset_sources.len());
        assert_eq!(
            report.resolved_count + report.missing_source_paths.len(),
            report.total_count
        );
    }

    #[test]
    fn desktop_graphics_font_atlas_loads_font_jp_only_for_japanese_locale_and_overrides_default_and_outline(
    ) {
        let sources = vec![
            DesktopFontAssetSourceTrace {
                source_path: "fonts/font.woff".into(),
                file_path: Some(
                    "D:/MDT/mindustry-upstream-v157.4/core/assets/fonts/font.woff".into(),
                ),
            },
            DesktopFontAssetSourceTrace {
                source_path: "fonts/font_jp.woff".into(),
                file_path: Some(
                    "D:/MDT/mindustry-upstream-v157.4/core/assets/fonts/font_jp.woff".into(),
                ),
            },
        ];

        for locale in ["en", "zh_CN", "ko_KR", "id_ID"] {
            let plan = super::desktop_default_real_font_atlas_sources_for_locale(&sources, locale);
            assert!(
                !plan.iter().any(|source| source
                    .file_path
                    .ends_with("fonts/font_jp.woff")),
                "Java Fonts.loadExtraFonts only applies font_jp/font_jp_outline for Japanese locale, not {locale}"
            );
        }

        for locale in ["ja", "ja_JP", "ja-JP.UTF-8"] {
            let plan = super::desktop_default_real_font_atlas_sources_for_locale(&sources, locale);
            let japanese_overrides = plan
                .iter()
                .filter(|source| source.file_path.ends_with("fonts/font_jp.woff"))
                .collect::<Vec<_>>();
            assert_eq!(
                japanese_overrides.len(),
                2,
                "Java Fonts.loadExtraFonts overrides both Fonts.def and Fonts.outline with font_jp/font_jp_outline for {locale}"
            );
            assert!(japanese_overrides
                .iter()
                .all(|source| source.override_existing));
            assert!(japanese_overrides
                .iter()
                .any(|source| source.font_id == RenderFontId::Default));
            assert!(japanese_overrides
                .iter()
                .any(|source| source.font_id == RenderFontId::Outline));
            assert_eq!(
                japanese_overrides[0].characters, japanese_overrides[1].characters,
                "font_jp and font_jp_outline should share the same Japanese glyph seed"
            );
        }
    }

    #[test]
    fn desktop_graphics_font_atlas_japanese_outline_override_matches_java_border_metadata() {
        let sources = vec![
            DesktopFontAssetSourceTrace {
                source_path: "fonts/font.woff".into(),
                file_path: Some(
                    "D:/MDT/mindustry-upstream-v157.4/core/assets/fonts/font.woff".into(),
                ),
            },
            DesktopFontAssetSourceTrace {
                source_path: "fonts/font_jp.woff".into(),
                file_path: Some(
                    "D:/MDT/mindustry-upstream-v157.4/core/assets/fonts/font_jp.woff".into(),
                ),
            },
        ];
        let plan = super::desktop_default_real_font_atlas_sources_for_locale(&sources, "ja");
        let japanese_default = plan
            .iter()
            .find(|source| {
                source.font_id == RenderFontId::Default
                    && source.file_path.ends_with("fonts/font_jp.woff")
            })
            .expect("Japanese locale should override Fonts.def with font_jp");
        let japanese_outline = plan
            .iter()
            .find(|source| {
                source.font_id == RenderFontId::Outline
                    && source.file_path.ends_with("fonts/font_jp.woff")
            })
            .expect("Japanese locale should override Fonts.outline with font_jp_outline");

        assert_eq!(
            japanese_default.border_width, 0,
            "Java font_jp default override only sets shadowColor/shadowOffsetY, not borderColor"
        );
        assert_eq!(japanese_default.border_color, [0, 0, 0, 0]);
        assert_eq!(
            japanese_outline.border_width,
            super::DESKTOP_OUTLINE_FONT_BORDER_WIDTH as u32,
            "Java font_jp_outline uses the outline FreeType loader border width"
        );
        assert_eq!(
            japanese_outline.border_color,
            super::DESKTOP_FONT_DARK_GRAY_RGBA8,
            "Java font_jp_outline sets borderColor = Color.darkGray"
        );
    }

    #[test]
    fn desktop_font_asset_sources_resolve_from_mindustry_asset_root() {
        let root = temp_desktop_path("font-asset-root");
        let asset_root = root.join("assets");
        let asset_raw_root = root.join("assets-raw");
        let font_path = asset_root.join("fonts/font.woff");
        let icon_properties_path = asset_root.join("icons/icons.properties");
        let fontgen_config_path = asset_raw_root.join("fontgen/config.json");
        std::fs::create_dir_all(font_path.parent().unwrap())
            .expect("font fixture dir should be writable");
        std::fs::create_dir_all(icon_properties_path.parent().unwrap())
            .expect("icon fixture dir should be writable");
        std::fs::create_dir_all(fontgen_config_path.parent().unwrap())
            .expect("fontgen fixture dir should be writable");
        std::fs::write(&font_path, b"font").expect("font fixture should be writable");
        std::fs::write(&icon_properties_path, b"63743=spawn|block-spawn-ui\n")
            .expect("icons fixture should be writable");
        std::fs::write(&fontgen_config_path, b"{\"font\":\"icon\"}\n")
            .expect("fontgen config fixture should be writable");

        let _asset_guard = EnvVarGuard::set("MINDUSTRY_ASSET_ROOT", &asset_root);
        let sources = super::default_desktop_font_asset_source_traces();
        let font = sources
            .iter()
            .find(|source| source.source_path == "fonts/font.woff")
            .expect("font source should be listed");
        let icons = sources
            .iter()
            .find(|source| source.source_path == "icons/icons.properties")
            .expect("icons properties source should be listed");
        let fontgen = sources
            .iter()
            .find(|source| source.source_path == "fontgen/config.json")
            .expect("fontgen config source should be listed");
        let expected_font_path = font_path.to_string_lossy().replace('\\', "/");
        let expected_icons_path = icon_properties_path.to_string_lossy().replace('\\', "/");
        let expected_fontgen_path = fontgen_config_path.to_string_lossy().replace('\\', "/");

        assert!(font.resolved());
        assert!(icons.resolved());
        assert!(fontgen.resolved());
        assert_eq!(font.file_path.as_deref(), Some(expected_font_path.as_str()));
        assert_eq!(
            icons.file_path.as_deref(),
            Some(expected_icons_path.as_str())
        );
        assert_eq!(
            fontgen.file_path.as_deref(),
            Some(expected_fontgen_path.as_str())
        );

        let report = super::desktop_validate_font_asset_sources(&sources);
        assert!(
            report.resolved_count >= 3,
            "fixture font, icons.properties and assets-raw fontgen/config.json should resolve even when local upstream defaults resolve additional assets"
        );
    }

    #[test]
    fn desktop_content_icon_glyph_registry_loads_upstream_icon_properties() {
        let root = temp_desktop_path("content-icon-glyph-root");
        let asset_root = root.join("assets");
        let icon_properties_path = asset_root.join("icons/icons.properties");
        std::fs::create_dir_all(icon_properties_path.parent().unwrap())
            .expect("icon fixture dir should be writable");
        std::fs::write(
            &icon_properties_path,
            b"63743=spawn|block-spawn-ui\n63744=router|block-router-ui\n",
        )
        .expect("icons fixture should be writable");

        let _asset_guard = EnvVarGuard::set("MINDUSTRY_ASSET_ROOT", &asset_root);
        let registry = super::default_desktop_content_icon_glyph_registry();
        let expected_icons_path = icon_properties_path.to_string_lossy().replace('\\', "/");

        assert_eq!(registry.source_path, "icons/icons.properties");
        assert_eq!(
            registry.file_path.as_deref(),
            Some(expected_icons_path.as_str())
        );
        assert!(registry.loaded());
        assert_eq!(registry.len(), 2);
        assert_eq!(
            registry
                .get_by_name("spawn")
                .map(|icon| icon.atlas_symbol.as_str()),
            Some("block-spawn-ui")
        );
        assert_eq!(
            registry
                .get_by_unicode(63744)
                .map(|icon| icon.name.as_str()),
            Some("router")
        );
        assert_eq!(
            registry
                .get_by_atlas_symbol("block-router-ui")
                .map(|icon| icon.unicode),
            Some(63744)
        );

        let report = registry.validation_report();
        assert!(report.loaded());
        assert_eq!(report.icon_count, 2);
        assert!(report.load_error.is_none());
    }

    #[test]
    fn desktop_fonts_unicode_to_name_prefers_content_icons_then_iconc_like_java() {
        let play = super::desktop_iconc_glyph_by_name_like_java("play")
            .expect("upstream Iconc.play should exist");
        let mut texture_atlas = TextureAtlasPlan::new();
        let _ = texture_atlas.insert_or_replace_region(
            PageType::Ui,
            TextureAtlasRegion::new(
                PageType::Ui,
                "block-alpha-ui",
                "sprites/ui/block-alpha-ui.png",
                0,
                0,
                16,
                16,
                true,
            ),
        );
        let _ = texture_atlas.insert_or_replace_region(
            PageType::Main,
            TextureAtlasRegion::new(
                PageType::Main,
                "main-page-symbol",
                "sprites/main-page-symbol.png",
                0,
                0,
                16,
                16,
                true,
            ),
        );
        let registry = DesktopContentIconGlyphRegistry::new(
            "icons/icons.properties",
            Some("icons/icons.properties".into()),
            vec![
                super::UpstreamContentIcon {
                    unicode: 0xf8ff,
                    name: "alphaaaa".into(),
                    atlas_symbol: "block-alpha-ui".into(),
                },
                super::UpstreamContentIcon {
                    unicode: 0xf8fe,
                    name: "main-only".into(),
                    atlas_symbol: "main-page-symbol".into(),
                },
            ],
            None,
        );

        assert_eq!(
            super::desktop_unicode_to_name_like_java(&registry, &texture_atlas, 0xf8ff).as_deref(),
            Some("block-alpha-ui"),
            "Java Fonts.registerIcon writes unicodeToName[ch] = regionName for content icons registered on the UI atlas page"
        );
        assert_eq!(
            super::desktop_unicode_to_name_like_java(&registry, &texture_atlas, 0xf8fe),
            None,
            "Java Fonts.loadContentIcons skips non-UI-page atlas entries, so their unicode must not become a large-icon name"
        );
        assert_eq!(
            super::desktop_unicode_to_name_like_java(&registry, &texture_atlas, play.codepoint)
                .as_deref(),
            Some("play"),
            "Java Fonts.unicodeToName falls back to Iconc.codeToName when no registered content icon exists"
        );
    }

    #[test]
    fn desktop_ui_icon_glyph_aliases_avoid_raw_small_icon_names_like_java() {
        for (alias, canonical) in [
            ("cancelSmall", "cancel"),
            ("down-open", "downOpen"),
            ("eyeOffSmall", "eyeOff"),
            ("eyeSmall", "eye"),
            ("fileSmall", "file"),
            ("pencilSmall", "pencil"),
            ("powerSmall", "power"),
            ("up-open", "upOpen"),
        ] {
            let alias_glyph = super::desktop_ui_icon_glyph_or_label(alias, alias);
            let canonical_glyph = super::desktop_ui_icon_glyph_or_label(canonical, canonical);
            assert_eq!(
                alias_glyph, canonical_glyph,
                "Java UI code uses the canonical Iconc.{canonical} glyph; Rust must not draw raw alias text {alias}"
            );
            assert_ne!(
                alias_glyph, alias,
                "missing icon aliases should never leak English/raw icon names into visible UI"
            );
        }

        let discord = super::desktop_ui_icon_glyph_or_label("discord", "discord");
        let link = super::desktop_ui_icon_glyph_or_label("link", "link");
        assert_ne!(
            discord, "discord",
            "Java Icon.discord is a real Iconc glyph; it must not leak raw English token text"
        );
        assert_ne!(
            discord, link,
            "Java Links/DiscordDialog use Icon.discord, not Icon.link; the visible Discord mark should not be downgraded to the generic link glyph"
        );
    }

    #[test]
    fn desktop_fonts_get_large_icon_uses_iconlarge_glyph_then_atlas_fallback_like_java() {
        let play = super::desktop_iconc_glyph_by_name_like_java("play")
            .expect("upstream Iconc.play should exist");
        let play_character = char::from_u32(play.codepoint)
            .expect("Iconc.play should be a valid icon font character");
        let mut glyphs = BTreeMap::new();
        glyphs.insert(
            super::DesktopRealFontGlyphKey::new(RenderFontId::IconLarge, play_character)
                .expect("IconLarge play glyph key should be valid"),
            super::DesktopRealFontGlyph {
                uv: [0.0, 0.0, 0.5, 0.5],
                width: 24.0,
                height: 24.0,
                offset_x: 0.0,
                offset_y: 0.0,
                advance: 24.0,
            },
        );
        let font_atlas = super::DesktopRealFontAtlas {
            file_path: "fixture-icon-large-atlas".into(),
            source_key_digest: 0,
            texture_width: 2,
            texture_height: 2,
            pixels: vec![255; 16],
            glyphs,
            metrics: BTreeMap::new(),
        };
        let texture_atlas = TextureAtlasPlan::from_virtual_source_paths([
            "sprites/play.png",
            "sprites/block-alpha-ui.png",
            "sprites/error.png",
        ]);

        assert!(matches!(
            super::desktop_large_icon_source_like_java(
                "play",
                &texture_atlas,
                Some(&font_atlas)
            ),
            Some(super::DesktopLargeIconSourceLikeJava::IconLargeGlyph {
                name,
                unicode,
                ..
            }) if name == "play" && unicode == play.codepoint
        ));
        assert!(matches!(
            super::desktop_large_icon_source_like_java(
                "block-alpha-ui",
                &texture_atlas,
                Some(&font_atlas)
            ),
            Some(super::DesktopLargeIconSourceLikeJava::AtlasRegion { name, symbol })
                if name == "block-alpha-ui" && symbol == "block-alpha-ui"
        ));
        assert!(matches!(
            super::desktop_large_icon_source_like_java(
                "missing-large-icon",
                &texture_atlas,
                Some(&font_atlas)
            ),
            Some(super::DesktopLargeIconSourceLikeJava::AtlasRegion { name, symbol })
                if name == "missing-large-icon" && symbol == "error"
        ), "Java Core.atlas.find(name) returns a visible missing/error region instead of making large icons disappear");
    }

    #[test]
    fn desktop_bundle_and_icons_properties_keep_icons_strict_but_bundle_text_uses_utf8_first_fallback(
    ) {
        let root = temp_desktop_path("utf8-first-bundle-icons-root");
        let asset_root = root.join("assets");
        let icon_properties_path = asset_root.join("icons/icons.properties");
        std::fs::create_dir_all(icon_properties_path.parent().unwrap())
            .expect("strict UTF-8 icon fixture dir should be writable");
        std::fs::write(
            &icon_properties_path,
            b"63743=spawn|block-spawn-ui\nstrict.invalid=\xff\n",
        )
        .expect("invalid UTF-8 icon fixture should be writable");

        let _asset_guard = EnvVarGuard::set("MINDUSTRY_ASSET_ROOT", &asset_root);
        let registry = super::default_desktop_content_icon_glyph_registry();
        assert!(
            registry.load_error.is_some(),
            "Java reads icons/icons.properties as text; invalid UTF-8 must not be silently replaced into a content icon registry"
        );
        assert!(!registry.loaded());

        let data_dir = root.join("data");
        std::fs::create_dir_all(&data_dir)
            .expect("strict UTF-8 external bundle dir should be writable");
        std::fs::write(
            data_dir.join("bundle.properties"),
            b"play = Broken \xff Play\n",
        )
        .expect("invalid UTF-8 external bundle should be writable");
        let values = super::desktop_external_bundle_values_for_data_dir(
            data_dir.to_string_lossy().as_ref(),
            "en",
        )
        .expect("external bundle should decode with UTF-8 first and legacy fallback");
        assert!(
            values.contains_key("play"),
            "external bundle text should be loaded even when UTF-8 fails, after trying legacy encodings"
        );
    }

