    #[test]
    fn desktop_content_icon_glyph_registry_last_write_wins_for_duplicate_names_like_java() {
        let registry = DesktopContentIconGlyphRegistry::new(
            "icons/icons.properties",
            Some("icons/icons.properties".into()),
            vec![
                super::UpstreamContentIcon {
                    unicode: 0xf8ff,
                    name: "sand".into(),
                    atlas_symbol: "item-sand-ui".into(),
                },
                super::UpstreamContentIcon {
                    unicode: 0xf900,
                    name: "sand".into(),
                    atlas_symbol: "floor-sand-ui".into(),
                },
            ],
            None,
        );

        assert_eq!(
            registry
                .get_by_name("sand")
                .map(|icon| (icon.unicode, icon.atlas_symbol.as_str())),
            Some((0xf900, "floor-sand-ui")),
            "Java ObjectMap.put overwrites duplicate content icon names with the later icons.properties row"
        );
        assert_eq!(
            registry
                .get_by_unicode(0xf8ff)
                .map(|icon| icon.atlas_symbol.as_str()),
            Some("item-sand-ui")
        );
        assert_eq!(
            registry
                .get_by_atlas_symbol("floor-sand-ui")
                .map(|icon| icon.name.as_str()),
            Some("sand")
        );
        assert_eq!(
            registry.validation_report().icon_count,
            2,
            "duplicate-name rows remain distinct source rows; only name lookup follows Java put semantics"
        );
    }

    #[test]
    fn desktop_launcher_localized_text_formats_icon_tokens_like_java_ui_format_icons() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.content_icon_glyph_registry = DesktopContentIconGlyphRegistry::new(
            "icons/icons.properties",
            Some("icons/icons.properties".into()),
            vec![
                super::UpstreamContentIcon {
                    unicode: 0xf8ff,
                    name: "alphaaaa".into(),
                    atlas_symbol: "block-alpha-ui".into(),
                },
                super::UpstreamContentIcon {
                    unicode: 0xf8fe,
                    name: "main-icon".into(),
                    atlas_symbol: "main-page-symbol".into(),
                },
                super::UpstreamContentIcon {
                    unicode: 0xf8fd,
                    name: "missing-atlas".into(),
                    atlas_symbol: "missing-atlas-symbol".into(),
                },
            ],
            None,
        );
        let _ = Arc::make_mut(&mut launcher.texture_atlas).insert_or_replace_region(
            PageType::Ui,
            TextureAtlasRegion::new(
                PageType::Ui,
                "block-alpha-ui",
                "sprites/ui/block-alpha-ui.png",
                0,
                0,
                16,
                16,
                true,
            ),
        );
        let _ = Arc::make_mut(&mut launcher.texture_atlas).insert_or_replace_region(
            PageType::Main,
            TextureAtlasRegion::new(
                PageType::Main,
                "main-page-symbol",
                "sprites/main-page-symbol.png",
                0,
                0,
                16,
                16,
                true,
            ),
        );

        let play = super::desktop_ui_icon_glyph_or_label("play", "play");
        let alpha = "\u{f8ff}";
        assert_eq!(
            launcher.localize_bundle_markup_text("tap :play: then :alphachan:"),
            format!("tap {play} then {alpha}")
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("keep :missing: raw"),
            "keep :missing: raw"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("skip :main-icon: and :missing-atlas:"),
            "skip :main-icon: and :missing-atlas:",
            "Java UI.formatIcons only replaces content icons registered by Fonts.loadContentIcons on the UI atlas page"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("server 127.0.0.1:6567"),
            "server 127.0.0.1:6567"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("coords 10:20"),
            "coords 10:20"
        );
    }

    #[test]
    fn desktop_launcher_reuses_content_icon_runtime_registry_within_menu_frame() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.content_icon_glyph_registry = DesktopContentIconGlyphRegistry::new(
            "icons/icons.properties",
            Some("icons/icons.properties".into()),
            vec![super::UpstreamContentIcon {
                unicode: 0xf8ff,
                name: "alphaaaa".into(),
                atlas_symbol: "block-alpha-ui".into(),
            }],
            None,
        );
        let _ = Arc::make_mut(&mut launcher.texture_atlas).insert_or_replace_region(
            PageType::Ui,
            TextureAtlasRegion::new(
                PageType::Ui,
                "block-alpha-ui",
                "sprites/ui/block-alpha-ui.png",
                0,
                0,
                16,
                16,
                true,
            ),
        );

        launcher
            .content_icon_runtime_registry_active_frame_index
            .set(Some(7));
        assert_eq!(launcher.content_icon_runtime_registry_cache_rebuilds(), 0);
        assert_eq!(launcher.format_icons_like_java(":alphachan:"), "\u{f8ff}");
        assert_eq!(launcher.content_icon_runtime_registry_cache_rebuilds(), 1);
        assert_eq!(
            launcher.format_icons_like_java("again :alphachan:"),
            "again \u{f8ff}"
        );
        assert_eq!(
            launcher.content_icon_runtime_registry_cache_rebuilds(),
            1,
            "stable icon-token labels in one menu frame should reuse the Java-like content icon runtime registry"
        );

        launcher
            .content_icon_runtime_registry_active_frame_index
            .set(Some(8));
        assert_eq!(launcher.format_icons_like_java(":alphachan:"), "\u{f8ff}");
        assert_eq!(
            launcher.content_icon_runtime_registry_cache_rebuilds(),
            1,
            "new menu frames may revalidate the registry key, but unchanged atlas/registry should not rebuild it"
        );
        launcher
            .content_icon_runtime_registry_active_frame_index
            .set(None);
    }

    #[test]
    fn desktop_launcher_leading_bundle_key_localization_keeps_literal_mid_string_keys_like_java_dialogs(
    ) {
        let launcher = DesktopLauncher::new(Vec::new());
        let disconnect_error = launcher.localize_bundle_markup_text("@disconnect.error");

        assert_eq!(
            launcher.localize_leading_bundle_key_text_like_java("@play"),
            launcher.localize_bundle_markup_text("@play"),
            "Java dialog helpers localize a bundle key when it is the leading UI text token"
        );
        assert_eq!(
            launcher.localize_leading_bundle_key_text_like_java("@disconnect.error [accent]@play"),
            format!("{disconnect_error} [accent]@play"),
            "Java explicit dialog entry points localize the leading key but keep later literal @tokens untouched"
        );
        assert_eq!(
            launcher.localize_leading_bundle_key_text_like_java("literal @play raw"),
            "literal @play raw",
            "literal server/error text should not be scanned for arbitrary mid-string bundle keys"
        );
        assert_eq!(
            launcher.join_connection_error_message_like_java(
                "@disconnect.error while @play",
                "@disconnect.timeout",
            ),
            format!("{disconnect_error} while @play"),
            "JoinDialog error keys should use the same leading-key boundary as Java UI.showOkText/showConfirm"
        );
        assert_eq!(
            launcher.join_connection_error_message_with_detail_like_java(
                "network @play",
                "@disconnect.error",
            ),
            format!("{disconnect_error}\nnetwork @play"),
            "non-key network details are appended as literal diagnostic detail, not recursively bundle-expanded"
        );
    }

