    #[test]
    fn desktop_content_icon_bitmap_glyphs_crop_from_packed_ui_atlas_like_java() {
        let root = temp_desktop_path("content-icon-packed-atlas-root");
        let asset_root = root.join("assets");
        let icon_properties_path = asset_root.join("icons/icons.properties");
        std::fs::create_dir_all(icon_properties_path.parent().unwrap())
            .expect("icon fixture dir should be writable");
        std::fs::write(&icon_properties_path, b"63743=test-atlas|aegires-wreck0\n")
            .expect("icons fixture should be writable");
        let _asset_guard = EnvVarGuard::set("MINDUSTRY_ASSET_ROOT", &asset_root);

        let atlas_icon = super::UpstreamContentIcon {
            unicode: 63743,
            name: "test-atlas".into(),
            atlas_symbol: "aegires-wreck0".into(),
        };

        let packed_regions = super::desktop_packed_atlas_regions_for_content_icons_like_java();
        assert!(
            packed_regions
                .iter()
                .any(|region| region.page_type == PageType::Ui
                    && region.name == atlas_icon.atlas_symbol),
            "upstream sprites.aatls should expose aegires-wreck0 on the UI page"
        );
        let image = super::desktop_real_font_content_icon_image_from_packed_atlas_like_java(
            &atlas_icon,
            &packed_regions,
        )
        .expect("content icon should be cropped from the packed UI atlas");
        assert!(image.width > 0);
        assert!(image.height > 0);
        assert!(
            image.pixels.chunks_exact(4).any(|rgba| rgba[3] > 0),
            "cropped content icon should carry visible pixels"
        );

        let mut metrics = BTreeMap::new();
        metrics.insert(
            super::DesktopRealFontGlyphKey::DEFAULT,
            super::DesktopRealFontMetrics {
                base_size: 18.0,
                ascent: 14.0,
                line_height: 20.0,
            },
        );
        let glyphs = super::desktop_real_font_content_icon_bitmap_glyphs_like_java(&metrics);
        let glyph_key = super::DesktopRealFontGlyphKey::new(
            RenderFontId::Default,
            char::from_u32(atlas_icon.unicode).unwrap(),
        )
        .expect("atlas unicode should map to a font glyph key");
        assert!(
            glyphs.iter().any(|glyph| glyph.key == glyph_key
                && glyph.width > 0
                && glyph.height > 0
                && glyph.pixels.chunks_exact(4).any(|rgba| rgba[3] > 0)),
            "Java Fonts.loadContentIcons registers atlas-backed aegires-wreck0 as a visible bitmap glyph"
        );
    }

