        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: info_center.x,
                y: info_center.y,
            }],
        );
        let hover_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let hover_commands = hover_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        assert!(hover_commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, tint, .. }
                if symbol == "info-banner" && *rect == info_rect && *tint == [1.0, 1.0, 1.0, 1.0]
        )), "Java MenuFragment gives infoBanner only as ImageButtonStyle.up, so hover must not brighten it");
        assert!(!hover_commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, tint, .. }
                if symbol == "info-banner" && *rect == info_rect && *tint != [1.0, 1.0, 1.0, 1.0]
        )));

