    #[test]
    fn desktop_launcher_mobile_terminal_toolbar_actions_consume_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.menu_renderer_state.config.mobile = true;
        launcher.set_menu_mobile_terminal_open_like_java(true);
        launcher.console_fragment.add_message("newest");
        launcher.console_fragment.add_message("older");

        let surface = DesktopSurfaceSize::new(540, 960);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let row = DesktopLauncher::mobile_terminal_toolbar_row_rect_for_viewport(
            viewport,
            launcher.menu_scene_margin_bottom,
            5,
        );
        let click_button = |launcher: &mut DesktopLauncher, index: usize| {
            let center = DesktopLauncher::mobile_terminal_toolbar_button_rect(row, index).center();
            launcher.apply_menu_input_events(
                surface,
                &[
                    DesktopInputTickEvent::CursorMoved {
                        x: center.x,
                        y: center.y,
                    },
                    DesktopInputTickEvent::MouseButton {
                        button: "primary".into(),
                        pressed: true,
                    },
                ],
            );
        };

        click_button(&mut launcher, 1);
        assert_eq!(
            launcher.last_console_mobile_toolbar_action,
            Some(super::ConsoleMobileButtonAction::ScrollUp)
        );
        assert_eq!(launcher.console_fragment.scroll_pos(), 1);

        click_button(&mut launcher, 2);
        assert_eq!(
            launcher.last_console_mobile_toolbar_action,
            Some(super::ConsoleMobileButtonAction::ScrollDown)
        );
        assert_eq!(launcher.console_fragment.scroll_pos(), 0);

        click_button(&mut launcher, 0);
        assert_eq!(
            launcher.last_console_mobile_toolbar_action,
            Some(super::ConsoleMobileButtonAction::OpenTextInput)
        );
        assert_eq!(
            launcher.last_console_actions,
            vec![super::ConsoleAction::OpenMobileTextInput]
        );

        click_button(&mut launcher, 3);
        assert_eq!(
            launcher.last_console_mobile_toolbar_action,
            Some(super::ConsoleMobileButtonAction::OpenScriptFileChooser)
        );
        assert_eq!(
            launcher.last_console_script_file_request,
            Some(FileChooserRequest::new(true, "js", "js"))
        );

        click_button(&mut launcher, 4);
        assert_eq!(
            launcher.last_console_mobile_toolbar_action,
            Some(super::ConsoleMobileButtonAction::Hide)
        );
        assert_eq!(
            launcher.last_console_actions,
            vec![super::ConsoleAction::Hide]
        );
        assert!(!launcher.menu_mobile_terminal_open);
        assert!(!launcher.console_fragment.shown());
    }

    #[test]
    fn desktop_launcher_about_menu_route_renders_upstream_credits_links_and_contributors() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.menu_renderer_state.config.mobile = true;
        let surface = DesktopSurfaceSize::new(540, 960);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let chrome = DesktopLauncher::menu_chrome_layout_for_viewport(viewport);

        let info_center = chrome
            .info_rect
            .expect("mobile chrome layout should include info")
            .center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: info_center.x,
                    y: info_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );

        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::About)
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();

        assert!(
            !texts.contains(&"upstream: AboutDialog"),
            "Java AboutDialog does not render Rust route-shell upstream debug text"
        );
        let links_line = launcher.about_links_line();
        assert!(
            !texts.contains(&links_line.as_str()),
            "Java AboutDialog shows the link ScrollPane directly instead of a Rust-only links summary"
        );
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@link.discord.description")
                .as_str()
        ));
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@link.github.description")
                .as_str()
        ));
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@link.wiki.description")
                .as_str()
        ));
        for raw_key in [
            "@link.discord.description",
            "@link.github.description",
            "@link.wiki.description",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "AboutDialog link card final DrawText should localize {raw_key} before rendering"
            );
        }
        assert!(
            !texts.iter().any(|text| text.starts_with("url: https://")),
            "Java AboutDialog link cards show title/description/Icon.link, not raw URL text"
        );
        assert!(!texts
            .iter()
            .any(|text| text.contains("pending AboutDialog port")));

        launcher
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::ShowAboutCredits);
        assert_eq!(
            launcher.about_route_page,
            super::DesktopAboutRoutePage::Credits
        );

        let frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let credit_texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            credit_texts.contains(&"Discord"),
            "credits should be drawn as a modal over the original About link list"
        );
        assert!(credit_texts.contains(&launcher.localize_bundle_markup_text("@credits").as_str()));
        assert!(credit_texts.contains(
            &launcher
                .localize_bundle_markup_text("@credits.text")
                .as_str()
        ));
        let contributors_line = launcher.localize_bundle_markup_text("@contributors");
        assert!(credit_texts.contains(&contributors_line.as_str()));
        assert!(credit_texts.contains(&launcher.localize_bundle_markup_text("@back").as_str()));
        for raw_key in ["@credits", "@credits.text", "@contributors", "@back"] {
            assert!(
                !credit_texts.iter().any(|text| text.contains(raw_key)),
                "CreditsDialog final DrawText should localize {raw_key} before rendering"
            );
        }
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            DesktopMenuRoute::About,
        );
        let credits_dialog = DesktopLauncher::about_credits_dialog_rect_for_panel(panel);
        let credits_close = DesktopLauncher::about_credits_dialog_close_rect(credits_dialog);
        assert_eq!(
            credits_close.width,
            super::SETTINGS_BACK_BUTTON_WIDTH,
            "Java AboutDialog.showCredits() uses BaseDialog.addCloseButton(), width 210f"
        );
        assert_eq!(
            credits_close.height,
            super::SETTINGS_BACK_BUTTON_HEIGHT,
            "Java BaseDialog.addCloseButton() uses a 64f-tall close button"
        );
        assert_eq!(
            launcher.active_menu_route_shell_primary_label(super::DesktopMenuRoute::About),
            None,
            "AboutDialog.showCredits opens a nested BaseDialog with its own @back footer; the original @credits footer button must not stay active underneath"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                credits_close.center().x,
                credits_close.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ShowAboutLinks)
        );
        assert!(
            !credit_texts.iter().any(|text| text.starts_with("scroll:")),
            "Java Credits dialog uses a ScrollPane, not a Rust-only textual overflow marker"
        );
        assert!(
            !credit_texts.iter().any(|text| text.contains(" | ")),
            "Java CreditsDialog renders contributors as a 3-column table, not a pipe-joined line"
        );
        for contributor in ["redloong9527", "Prosta4okua", "Felix Corvus"] {
            assert!(
                credit_texts.contains(&contributor),
                "credits should render contributor {contributor} as its own table cell"
            );
        }
        assert!(credit_texts.iter().any(|text| text.contains("Space")));
    }

    #[test]
    fn desktop_launcher_about_contributors_are_loaded_from_resource_like_java() {
        let contributors_path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../core/assets/contributors");
        let contributors_text = std::fs::read_to_string(&contributors_path)
            .expect("Rust core/assets/contributors should mirror Java Core.files.internal(\"contributors\")");
        let expected = super::about_contributors_from_utf8_like_java(&contributors_text);

        assert!(
            expected.len() > 100,
            "contributors asset should contain the upstream translator/contributor list"
        );
        assert_eq!(super::about_contributors(), expected.as_slice());

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.dispatch_menu_action(MenuButtonRole::About);
        launcher
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::ShowAboutCredits);
        let surface = DesktopSurfaceSize::new(540, 960);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let credit_texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();

        for contributor in expected.iter().take(3) {
            assert!(
                credit_texts.contains(&contributor.as_str()),
                "Java CreditsDialog renders contributor {contributor} as an individual table cell"
            );
        }
        assert!(
            !credit_texts.iter().any(|text| text.contains(" | ")),
            "Java CreditsDialog uses three table columns instead of pipe-joined text"
        );
    }

    #[test]
    fn desktop_launcher_about_route_uses_upstream_link_cards_and_hitboxes() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let surface = DesktopSurfaceSize::new(540, 960);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        launcher.dispatch_menu_action(MenuButtonRole::About);

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::About,
        );
        assert!(
            panel.height
                > DesktopLauncher::active_menu_route_shell_panel_for_viewport(viewport).height
        );

        let first_card = DesktopLauncher::about_link_card_rect_for_panel(panel, 0);
        assert_eq!(first_card.width, 400.0);
        assert_eq!(first_card.height, 90.0);
        let credits_button = DesktopLauncher::active_menu_route_shell_primary_rect_for_viewport(
            viewport,
            super::DesktopMenuRoute::About,
        )
        .expect("AboutDialog.setup should add the @credits footer button");
        assert_eq!(
            credits_button.width,
            super::ABOUT_CREDITS_BUTTON_WIDTH_LIKE_JAVA,
            "Java AboutDialog.setup uses buttons.button(\"@credits\", ...).size(200f, 64f)"
        );
        assert_eq!(
            credits_button.height,
            super::ABOUT_CREDITS_BUTTON_HEIGHT_LIKE_JAVA,
            "Java AboutDialog @credits button should be 64px tall like the footer button row"
        );
        assert_eq!(credits_button.center().x, panel.center().x);
        let first_action = DesktopLauncher::about_link_action_rect_for_card(first_card);
        assert_eq!(
            first_action.width,
            first_card.height - 5.0,
            "Java AboutDialog link button uses .size(h - 5, h)"
        );
        assert_eq!(first_action.height, first_card.height);
        assert_eq!(
            launcher.about_link_name_at_surface_point(
                surface,
                first_card.center().x,
                first_card.center().y
            ),
            None,
            "Java AboutDialog only the right Icon.link button opens the URL, not the whole card"
        );
        assert_eq!(
            launcher.about_link_name_at_surface_point(
                surface,
                first_action.center().x,
                first_action.center().y
            ),
            Some("discord")
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();

        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == "whiteui" && *rect == first_card
            )
        }));
        let first_icon_cell = RenderRect::new(
            first_card.x + 40.0,
            first_card.y,
            (first_card.height - 5.0).max(1.0),
            first_card.height,
        );
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == "whiteui" && *rect == first_icon_cell
            )
        }), "Java AboutDialog wraps link.icon in a grayPanel cell instead of a separate dark outlined box");
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, .. } if *rect == first_icon_cell
            )),
            "Java AboutDialog icon cells do not add a Rust-only colored outline around the drawable"
        );
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. } if text == "Discord"
            )
        }));
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &DesktopLauncher::settings_image_button_symbol("clearNonei", false, false)
                        && *rect == first_action
            )
        }));
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == "button.9" && *rect == first_action
            )),
            "Java AboutDialog uses Styles.clearNonei for the right link ImageButton, not a solid button background"
        );
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, size, style, .. }
                    if text == "Discord"
                        && (*size - super::ABOUT_LINK_TITLE_FONT_SIZE_LIKE_JAVA).abs()
                            < f32::EPSILON
                        && !style.outline
            )
        }), "Java AboutDialog link titles are default Label text, not a compressed outlined Rust-only title");
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. }
                    if text == &super::desktop_ui_icon_glyph_or_label("discord", "discord")
            )
        }));
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, .. }
                    if text == &super::desktop_ui_icon_glyph_or_label("link", "link")
            )
        }));
        for raw_icon_token in super::ABOUT_LINKS
            .iter()
            .map(|link| link.icon)
            .chain(std::iter::once("link"))
        {
            assert!(
                !commands.iter().any(|command| matches!(
                    command,
                    RenderCommand::DrawText { text, style, .. }
                        if text == raw_icon_token && style.font == RenderFontId::Icon
                )),
                "Java AboutDialog uses Icon drawables; missing glyphs must not leak raw icon token '{raw_icon_token}'"
            );
        }
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, position, color, .. }
                    if text == &super::desktop_ui_icon_glyph_or_label("link", "link")
                        && *position == first_action.center()
                        && *color == mindustry_core::mindustry::ui::UiStyleColor::White.rgba()
            )
        }), "Java Styles.clearNonei keeps the About link action icon at imageUpColor=Color.white, not the previous Rust-only blue tint");
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: first_action.center().x,
                y: first_action.center().y,
            }],
        );
        let hover_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let hover_commands = hover_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        assert!(hover_commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &DesktopLauncher::settings_image_button_symbol("clearNonei", true, false)
                        && *rect == first_action
            )
        }), "Java Styles.clearNonei uses flatOver as the hovered About link ImageButton background");
        assert!(commands.iter().any(|command| {
            matches!(
                command,
                RenderCommand::DrawText { text, size, style, .. }
                    if text == &launcher.localize_bundle_markup_text("@link.discord.description")
                        && (*size - super::ABOUT_LINK_DESCRIPTION_FONT_SIZE_LIKE_JAVA).abs()
                            < f32::EPSILON
                        && style.wrap_width.is_some()
                        && !style.outline
            )
        }), "Java AboutDialog labelWrap descriptions use the default label font size and do not add runtime outline");
    }

    #[test]
    fn desktop_launcher_about_links_resolve_bundle_text_like_java_links() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "zh_CN".into();

        let discord = launcher
            .about_link_by_name("discord")
            .expect("About links should include Discord");
        assert_eq!(
            launcher.about_link_title(discord),
            "Discord",
            "Java Links.LinkEntry falls back to Strings.capitalize(name.replace('-', ' ')) when link.<name>.title is missing"
        );
        assert_eq!(
            launcher.about_link_description(discord),
            "Mindustry 官方的 Discord 聊天室",
            "Java Links.LinkEntry reads link descriptions from Core.bundle at runtime"
        );

        let google_play = super::ABOUT_LINKS
            .iter()
            .find(|link| link.name == "google-play")
            .expect("About links should keep the upstream google-play entry");
        assert_eq!(
            launcher.about_link_title(google_play),
            "Google play",
            "Java title fallback capitalizes the hyphen-replaced link name instead of using a fixed Rust title"
        );

        launcher.dispatch_menu_action(MenuButtonRole::About);
        let surface = DesktopSurfaceSize::new(540, 960);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&"Mindustry 官方的 Discord 聊天室"));
        assert!(
            !texts.contains(&"The official Mindustry Discord chatroom"),
            "AboutDialog should not render the static English description when the selected bundle provides a localized value"
        );
    }

    #[test]
    fn desktop_launcher_about_route_scrolls_links_and_credits_like_scrollpane() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let surface = DesktopSurfaceSize::new(540, 960);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        launcher.dispatch_menu_action(MenuButtonRole::About);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::About,
        );
        let clip = DesktopLauncher::about_links_clip_rect_for_panel(panel);
        assert!(
            launcher.max_about_links_scroll_offset_for_panel(panel) > 0,
            "fixture should contain more About links than the visible ScrollPane"
        );

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: clip.center().x,
                    y: clip.center().y,
                },
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -1.0,
                },
            ],
        );
        assert_eq!(launcher.about_links_scroll_offset, 1);
        let first_visible_card = DesktopLauncher::about_link_card_rect_for_panel(panel, 0);
        let first_visible =
            DesktopLauncher::about_link_action_rect_for_card(first_visible_card).center();
        assert_eq!(
            launcher.about_link_name_at_surface_point(surface, first_visible.x, first_visible.y),
            Some("changelog")
        );

        launcher
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::ShowAboutCredits);
        let dialog = DesktopLauncher::about_credits_dialog_rect_for_panel(panel);
        assert!(
            DesktopLauncher::max_about_credits_scroll_offset_for_dialog(dialog) > 0,
            "fixture should contain more contributor rows than the visible Credits ScrollPane"
        );
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: dialog.center().x,
                    y: dialog.center().y,
                },
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -1.0,
                },
            ],
        );
        assert_eq!(launcher.about_credits_scroll_offset, 1);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        for contributor in ["redloong9527", "Prosta4okua", "Felix Corvus"] {
            assert!(!texts.contains(&contributor));
        }
        for contributor in ["Vanguard", "Timmeey86", "Epowerj"] {
            assert!(
                texts.contains(&contributor),
                "scrolled Java CreditsDialog row should render contributor {contributor} as its own cell"
            );
        }
    }

