    #[test]
    fn desktop_launcher_about_menu_route_filters_banned_links_for_ios_or_steam_mode() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.about_filter_banned_links = true;
        launcher.dispatch_menu_action(MenuButtonRole::About);

        let lines = launcher.about_route_link_lines();
        let joined = lines.join("\n");

        assert!(joined.contains("The official Mindustry Discord chatroom"));
        assert!(joined.contains("Game source code"));
        for banned in ["Google play", "Itch.io", "Dev builds", "F droid"] {
            assert!(
                !joined.contains(banned),
                "filtered About links should omit {banned}"
            );
        }

        let mut steam_launcher = DesktopLauncher::new(Vec::new());
        steam_launcher.settings_locale = "en".into();
        steam_launcher.set_setting_override("platform", "steam", "true");
        steam_launcher.dispatch_menu_action(MenuButtonRole::About);
        let steam_joined = steam_launcher.about_route_link_lines().join("\n");
        assert!(steam_joined.contains("The official Mindustry Discord chatroom"));
        for banned in ["Google play", "Itch.io", "Dev builds", "F droid"] {
            assert!(
                !steam_joined.contains(banned),
                "Java AboutDialog filters {banned} automatically when steam is enabled"
            );
        }

        let mut ios_launcher = DesktopLauncher::new(Vec::new());
        ios_launcher.settings_locale = "en".into();
        ios_launcher.set_setting_override("platform", "ios", "true");
        ios_launcher.dispatch_menu_action(MenuButtonRole::About);
        let ios_joined = ios_launcher.about_route_link_lines().join("\n");
        assert!(ios_joined.contains("The official Mindustry Discord chatroom"));
        for banned in ["Google play", "Itch.io", "Dev builds", "F droid"] {
            assert!(
                !ios_joined.contains(banned),
                "Java AboutDialog filters {banned} automatically when iOS is enabled"
            );
        }
    }

    #[test]
    fn desktop_launcher_about_link_action_opens_uri_and_fires_wiki_event() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let mut platform = RecordingPlatform {
            open_result: true,
            ..Default::default()
        };

        let action = launcher
            .dispatch_about_link_action_with_platform("wiki", &mut platform)
            .expect("wiki link should exist");

        assert_eq!(
            platform.opened_uris,
            vec!["https://mindustrygame.github.io/wiki/"]
        );
        assert!(platform.clipboard_texts.is_empty());
        assert_eq!(action.name, "wiki");
        assert!(action.opened);
        assert!(action.wiki_event_fired);
        assert_eq!(action.clipboard_text, None);
        assert_eq!(action.error_message, None);
        assert_eq!(launcher.last_about_link_action, Some(action));
        assert_eq!(launcher.last_about_linkfail_message, None);
    }

    #[test]
    fn desktop_launcher_about_link_action_copies_url_and_records_linkfail_when_open_uri_fails() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let mut platform = RecordingPlatform::default();

        let action = launcher
            .dispatch_about_link_action_with_platform("bug", &mut platform)
            .expect("bug link should exist");

        assert_eq!(
            platform.opened_uris,
            vec!["https://github.com/Anuken/Mindustry/issues/new?assignees=&labels=bug&projects=&template=bug_report.yml"]
        );
        assert_eq!(
            platform.clipboard_texts,
            vec!["https://github.com/Anuken/Mindustry/issues/new?assignees=&labels=bug&projects=&template=bug_report.yml"]
        );
        assert_eq!(action.name, "bug");
        assert!(!action.opened);
        assert!(!action.wiki_event_fired);
        assert_eq!(action.clipboard_text.as_deref(), Some(action.url.as_str()));
        assert_eq!(action.error_message.as_deref(), Some("@linkfail"));
        assert_eq!(launcher.last_about_link_action, Some(action));
        assert_eq!(
            launcher.last_about_linkfail_message.as_deref(),
            Some("@linkfail")
        );
    }

