    #[test]
    fn desktop_launcher_menu_chrome_records_discord_and_becheck_actions() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.menu_becheck_active = true;
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let chrome = DesktopLauncher::menu_chrome_layout_for_viewport(viewport);

        let discord_center = chrome.discord_rect.center();
        assert_eq!(
            launcher.menu_chrome_action_at_surface_point(
                surface,
                discord_center.x,
                discord_center.y
            ),
            Some(super::DesktopMenuChromeAction::Discord)
        );
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: discord_center.x,
                    y: discord_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.last_menu_chrome_action,
            Some(super::DesktopMenuChromeAction::Discord)
        );
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::Discord)
        );
        assert_eq!(launcher.last_menu_action, None);

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let symbols = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawSprite { symbol, .. } => Some(symbol.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let discord_text = launcher.localize_bundle_markup_text("@discord");
        assert!(texts.contains(&discord_text.as_str()));
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawText { text, size, .. }
                    if text == &discord_text
                        && (*size - super::SETTINGS_JAVA_DEFAULT_FONT_SIZE).abs() < f32::EPSILON
            )),
            "Java DiscordDialog renders @discord with the default Label font size, not the earlier compressed Rust-only size"
        );
        for raw_debug in [
            "upstream: DiscordDialog",
            "discord:",
            "url:",
            "button: copylink",
            "button: openlink",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_debug)),
                "Java DiscordDialog should not render route debug prefix/text '{raw_debug}'"
            );
        }
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@back").as_str()));
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@copylink").as_str()));
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@openlink").as_str()));
        assert!(symbols.contains(&"button.9"));
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Discord,
        );
        let card = DesktopLauncher::discord_route_content_rect_for_panel(panel);
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &DesktopLauncher::settings_drawable_symbol("button") && *rect == card
        )), "Java DiscordDialog should render the @discord row on a Tex.button-style card");
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::FillRect { rect, color, .. }
                if *rect == RenderRect::new(
                    card.x,
                    card.y + 5.0,
                    super::DISCORD_DIALOG_COLOR_STRIPE_WIDTH,
                    card.height - 5.0
                ) && *color == [0x72 as f32 / 255.0, 0x89 as f32 / 255.0, 0xda as f32 / 255.0, 1.0]
        )), "Java DiscordDialog should render its Discord blue left stripe instead of a raw url/debug line");
        let discord_icon = super::desktop_ui_icon_glyph_or_label("discord", "link");
        let discord_icon_position = RenderPoint::new(
            card.x + super::DISCORD_DIALOG_COLOR_STRIPE_WIDTH + card.height * 0.5,
            card.center().y,
        );
        assert!(
            !discord_icon.trim().is_empty(),
            "Java DiscordDialog uses Icon.discord; Rust fallback must never leave the Discord card icon blank"
        );
        assert_ne!(
            discord_icon, "discord",
            "missing Discord icon glyph must fall back to a real icon glyph, not raw English token text"
        );
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawText { text, position, style, .. }
                    if text == &discord_icon
                        && *position == discord_icon_position
                        && style.font == RenderFontId::Icon
            )),
            "Java DiscordDialog renders a non-empty icon on the Discord card"
        );

        let back_rect = DesktopLauncher::discord_route_shell_back_rect_for_viewport(
            viewport,
            super::DesktopMenuRoute::Discord,
        )
        .expect("Discord route should expose a Java-sized back button");
        let open_rect = DesktopLauncher::active_menu_route_shell_primary_rect_for_viewport(
            viewport,
            super::DesktopMenuRoute::Discord,
        )
        .expect("Discord route should expose an open button");
        let copy_rect = DesktopLauncher::discord_route_shell_copy_rect_for_viewport(
            viewport,
            super::DesktopMenuRoute::Discord,
        )
        .expect("Discord route should expose a copylink button");
        for rect in [back_rect, copy_rect, open_rect] {
            assert_eq!(rect.width, super::DISCORD_DIALOG_BUTTON_WIDTH);
            assert_eq!(rect.height, super::DISCORD_DIALOG_BUTTON_HEIGHT);
        }
        assert!(
            back_rect.x < copy_rect.x && copy_rect.x < open_rect.x,
            "Java DiscordDialog buttons are ordered @back, @copylink, @openlink"
        );
        assert!(
            copy_rect.x < open_rect.x,
            "Java DiscordDialog buttons are ordered @back, @copylink, @openlink; copy should sit before open"
        );
        assert_eq!(
            copy_rect.y, open_rect.y,
            "Java DiscordDialog copy/open buttons share the same row"
        );
        assert_eq!(back_rect.y, copy_rect.y);

        let open_center = open_rect.center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: open_center.x,
                    y: open_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        let action = launcher
            .last_about_link_action
            .as_ref()
            .expect("Discord OPEN should dispatch link action");
        assert_eq!(action.name, "discord");
        assert_eq!(action.url, "https://discord.gg/mindustry");
        assert_eq!(action.error_message.as_deref(), Some("@linkfail"));

        let copy_center = copy_rect.center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: copy_center.x,
                    y: copy_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.last_menu_route_shell_action,
            Some(super::DesktopMenuRouteShellAction::CopyDiscordLink)
        );
        assert_eq!(
            launcher.last_discord_clipboard_text.as_deref(),
            Some("https://discord.gg/mindustry")
        );
        let back_center = back_rect.center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: back_center.x,
                    y: back_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.last_menu_route_shell_action,
            Some(super::DesktopMenuRouteShellAction::CloseRoute)
        );
        assert_eq!(launcher.active_menu_route, None);

        let becheck_center = chrome
            .becheck_rect
            .expect("desktop chrome layout should include becheck")
            .center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: becheck_center.x,
                    y: becheck_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "Left".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.last_menu_chrome_action,
            Some(super::DesktopMenuChromeAction::Becheck)
        );
        assert_eq!(
            launcher.last_menu_info_message.as_deref(),
            Some(super::MENU_BECHECK_NO_UPDATES_MESSAGE)
        );
        let becheck_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let becheck_texts = becheck_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("becheck frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(becheck_texts.contains(
            &launcher
                .localize_bundle_markup_text(super::MENU_BECHECK_NO_UPDATES_MESSAGE)
                .as_str()
        ));
        assert_eq!(launcher.last_menu_action, None);
    }

    #[test]
    fn desktop_launcher_load_game_route_lists_save_slots_and_records_slot_click() {
        let root = temp_desktop_path("load-game-route");
        let save_dir = root.join("saves");
        std::fs::create_dir_all(&save_dir).expect("save fixture dir should be writable");

        let mut old_tags = BTreeMap::new();
        old_tags.insert("mapname".into(), "Old Map".into());
        old_tags.insert("saved".into(), "100".into());
        old_tags.insert("wave".into(), "3".into());
        let mut old_bytes = Vec::new();
        write_deflated_save_meta_prefix(&mut old_bytes, LATEST_SAVE_VERSION, &old_tags)
            .expect("old save meta should encode");
        std::fs::write(save_dir.join("1.msav"), old_bytes).expect("old save should write");

        let mut new_tags = BTreeMap::new();
        new_tags.insert("mapname".into(), "New Map".into());
        new_tags.insert("saved".into(), "200".into());
        new_tags.insert("wave".into(), "9".into());
        new_tags.insert("autosave".into(), "true".into());
        new_tags.insert("rules".into(), r#"{"modeName":"attack"}"#.into());
        let mut new_bytes = Vec::new();
        write_deflated_save_meta_prefix(&mut new_bytes, LATEST_SAVE_VERSION, &new_tags)
            .expect("new save meta should encode");
        std::fs::write(save_dir.join("2.msav"), new_bytes).expect("new save should write");
        std::fs::write(save_dir.join("backup-ignored.msav"), b"not scanned")
            .expect("backup decoy should write");
        let preview_dir = root.join("previews");
        std::fs::create_dir_all(&preview_dir).expect("preview fixture dir should be writable");
        std::fs::write(preview_dir.join("save_slot_2.png"), b"preview")
            .expect("slot preview fixture should write");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.data_dir = root.display().to_string();
        launcher.client.context.paths.save_dir = save_dir.display().to_string();
        launcher.dispatch_menu_action(MenuButtonRole::LoadGame);
        launcher.game_state.rules.editor = true;
        launcher.game_state.set_sector(Some(Sector::new(99)));
        launcher.runtime.state.rules.editor = true;
        launcher.runtime.state.set_sector(Some(Sector::new(99)));
        launcher.net_client.net_mut().mark_server_active();

        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::LoadGame)
        );
        assert_eq!(launcher.load_game_slots.len(), 2);
        assert_eq!(
            launcher.load_game_slots[0]
                .meta
                .as_ref()
                .and_then(|meta| meta.map_name.as_deref()),
            Some("New Map")
        );

        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::LoadGame);
        assert!(lines.contains(&"save slots: 2".to_string()));
        assert!(lines.iter().any(|line| line.contains("#0 untitled")));
        assert!(lines.iter().any(|line| line.contains("@save.wave: 9")));
        assert!(lines
            .iter()
            .any(|line| line.contains("@save.map: New Map / @mode.attack.name")));
        assert!(!lines
            .iter()
            .any(|line| line.contains("pending LoadDialog port")));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::LoadGame,
        );
        let search_row = DesktopLauncher::load_game_search_rect_for_panel(panel);
        let search_field = DesktopLauncher::load_game_search_field_rect_for_row(search_row);
        let first_mode_button = DesktopLauncher::load_game_mode_filter_button_rect(search_row, 0);
        let second_mode_button = DesktopLauncher::load_game_mode_filter_button_rect(search_row, 1);
        assert_eq!(
            (search_row.height, search_field.height),
            (60.0, 60.0),
            "Java LoadDialog search row should be tall enough to match the 60f mode toggle buttons"
        );
        assert_eq!(
            (first_mode_button.width, first_mode_button.height),
            (60.0, 60.0),
            "Java LoadDialog mode filters use .size(60f)"
        );
        assert_eq!(
            second_mode_button.x - first_mode_button.x,
            first_mode_button.width - 12.0,
            "Java LoadDialog applies padLeft(-12f) between 60f mode filter buttons"
        );
        assert!(
            search_field.right() < first_mode_button.x,
            "Java LoadDialog search.field(...).growX() ends before the mode toggle buttons instead of painting a full-row input behind them"
        );
        assert!(
            search_field.right() <= first_mode_button.x - 10.0 + f32::EPSILON,
            "Java LoadDialog keeps a visible gap between the search TextField and the first mode chip"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                search_field.center().x,
                search_field.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::FocusLoadGameSearch)
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                first_mode_button.center().x,
                first_mode_button.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleLoadGameMode(
                DesktopLauncher::load_game_mode_filter_modes()[0]
            )),
            "Java LoadDialog mode toggle buttons sit outside the TextField hit target"
        );
        let initial_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let initial_commands = initial_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("initial load game frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let search_field_symbol = DesktopLauncher::settings_text_field_background_symbol();
        assert!(
            initial_commands.iter().any(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } => {
                    symbol == &search_field_symbol && rect == &search_field
                }
                _ => false,
            }),
            "Java LoadDialog renders a distinct TextField for search, not a full-width row background"
        );
        assert!(
            !initial_commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, .. } if *rect == search_field
            )),
            "Java LoadDialog search.field uses the TextField style itself; Rust should not add an extra focused outline around @save.search"
        );
        assert!(
            !initial_commands.iter().any(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } => {
                    symbol == &search_field_symbol && rect == &search_row
                }
                _ => false,
            }),
            "mode toggles should not sit on top of the search TextField drawable"
        );
        let slot_center =
            DesktopLauncher::load_game_slot_line_rect_for_viewport(viewport, 0).center();
        assert_eq!(
            launcher.load_game_slot_at_surface_point(surface, slot_center.x, slot_center.y),
            Some(0)
        );
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: slot_center.x,
                    y: slot_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );

        let action = launcher
            .last_load_game_action
            .as_ref()
            .expect("clicking a save slot should record a load action");
        assert_eq!(action.slot, "2");
        assert!(action.file.ends_with("2.msav"));
        assert_eq!(action.map_name.as_deref(), Some("New Map"));
        assert_eq!(action.timestamp, 200);
        assert_eq!(action.kind, super::DesktopLoadGameActionKind::Load);
        assert_eq!(action.status, "selected-for-load");
        assert!(
            launcher.load_game_pending_load.is_some(),
            "Java LoadDialog.runLoadSave should enter a visible loading phase before playing"
        );
        assert_eq!(launcher.last_load_game_result, None);
        let loading_lines =
            launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::LoadGame);
        assert!(loading_lines.contains(&"loadfrag: @loading".to_string()));
        assert!(
            !loading_lines
                .iter()
                .any(|line| line.starts_with("@loading:")),
            "Java LoadingFragment only exposes @loading, not Rust-only slot diagnostics"
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("load game frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@save.search")
                .as_str()
        ));
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@save.import")
                .as_str()
        ));
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@loading").as_str()));
        for raw_key in ["@save.search", "@save.import", "@loading"] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "LoadDialog final DrawText should localize {raw_key} before rendering"
            );
        }
        assert!(
            !texts.iter().any(|text| text.starts_with("@loading:")),
            "LoadDialog loading overlay should not render Rust-only slot diagnostics"
        );
        let stage_rect = RenderRect::new(viewport.x, viewport.y, viewport.width, viewport.height);
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::FillRect { rect, color, .. }
                    if *rect == stage_rect && *color == [0.0, 0.0, 0.0, 0.80]
            )),
            "Java LoadingFragment uses a full-screen Styles.black8 overlay, not a LoadDialog-local panel overlay"
        );
        assert!(
            commands
                .iter()
                .filter(|command| matches!(
                    command,
                    RenderCommand::DrawLine { layer, .. }
                        if *layer >= Layer::END_PIXELED + 0.091
                            && *layer <= Layer::END_PIXELED + 0.112
                ))
                .count()
                >= 4,
            "Java LoadingFragment should draw the two full-width WarningBar edge/stripe groups"
        );
        assert!(texts.contains(&"[accent]untitled"));
        let visible_slot = &launcher.load_game_slots[0];
        let map_line = launcher.load_game_slot_map_name_render_line(visible_slot);
        let mode_wave_line = launcher.load_game_slot_mode_wave_render_line(visible_slot);
        let autosave_line = launcher.load_game_slot_autosave_render_line(visible_slot);
        let playtime_line = launcher.load_game_slot_playtime_render_line(visible_slot);
        let date_line = DesktopLauncher::load_game_slot_date_render_line(visible_slot);
        assert!(texts.contains(&map_line.as_str()));
        assert!(texts.contains(&mode_wave_line.as_str()));
        assert!(texts.contains(&autosave_line.as_str()));
        assert!(texts.contains(&playtime_line.as_str()));
        assert!(texts.contains(&date_line.as_str()));
        for raw_key in [
            "@save.map",
            "@save.wave",
            "@save.autosave",
            "@save.playtime",
            "@mode.attack.name",
            "@mode.survival.name",
            "@on",
            "@off",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "LoadDialog save-card final DrawText should localize {raw_key} before rendering"
            );
        }
        let route_panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::LoadGame,
        );
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::FillRect { rect, color, .. }
                    if *rect == route_panel && (color[3] - 0.54).abs() < 0.001
            )),
            "LoadDialog pending load should no longer render the old route-local 54% black panel overlay"
        );
        let search_rect = DesktopLauncher::load_game_search_rect_for_panel(route_panel);
        for (index, mode) in [
            Gamemode::Survival,
            Gamemode::Sandbox,
            Gamemode::Attack,
            Gamemode::Pvp,
        ]
        .into_iter()
        .enumerate()
        {
            let rect = DesktopLauncher::load_game_mode_filter_button_rect(search_rect, index);
            assert_eq!(
                (rect.width, rect.height),
                (60.0, 60.0),
                "Java LoadDialog mode filters are Styles.emptyTogglei buttons with size(60f)"
            );
            if index > 0 {
                let previous =
                    DesktopLauncher::load_game_mode_filter_button_rect(search_rect, index - 1);
                assert_eq!(
                    rect.x - previous.x,
                    48.0,
                    "Java padLeft(-12f) makes adjacent 60f mode filter buttons overlap by 12px"
                );
            }
            let icon = DesktopLauncher::load_game_mode_filter_icon(mode);
            let glyph = super::desktop_ui_icon_glyph_or_label(icon, mode.wire_name());
            assert!(
                commands.iter().any(|command| matches!(
                    command,
                    RenderCommand::DrawText { text, position, color, style, .. }
                        if text == &glyph
                            && *position == rect.center()
                            && *color == DesktopLauncher::settings_image_button_image_color(
                                "emptyTogglei",
                                false,
                                false,
                                true,
                                true
                            )
                            && style.font == RenderFontId::Icon
                            && !style.outline
                )),
                "Java LoadDialog mode filter should render {icon} as a checked Styles.emptyTogglei icon toggle"
            );
            assert!(
                !commands.iter().any(|command| matches!(
                    command,
                    RenderCommand::DrawSprite { symbol, rect: sprite_rect, .. }
                        if *sprite_rect == rect
                            && (symbol == &DesktopLauncher::settings_text_button_symbol("grayt", false, false)
                                || symbol == &DesktopLauncher::settings_text_button_symbol("grayt", false, true))
                )),
                "Java Styles.emptyTogglei mode filter should not draw a grayt button background"
            );
        }
        assert!(!texts.iter().any(|text| text.starts_with("#0 New Map")));
        let symbols = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawSprite { symbol, .. } => Some(symbol.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let nomap_symbol = DesktopLauncher::settings_drawable_symbol("nomap");
        assert!(
            symbols.contains(&nomap_symbol.as_str()),
            "Java LoadDialog uses Core.atlas.find(\"nomap\") as the only missing-preview placeholder"
        );
        assert!(
            !texts.iter().any(|text| text.starts_with("save_slot_")),
            "Java LoadDialog does not print internal preview texture keys over missing previews"
        );
        assert!(
            symbols.contains(&"save_slot_2"),
            "Java LoadDialog slot.previewTexture() should surface as the slot preview sprite"
        );
        let slot_card = DesktopLauncher::load_game_slot_card_rect_for_panel(
            DesktopLauncher::active_menu_route_shell_panel_for_route(
                viewport,
                super::DesktopMenuRoute::LoadGame,
            ),
            0,
        );
        assert!(
            !initial_commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, .. } if *rect == slot_card
            )),
            "Java LoadDialog Styles.grayt card should not receive an extra Rust-only full-card stroke"
        );
        let preview_rect = DesktopLauncher::load_game_slot_preview_rect(slot_card);
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == "whiteui" && *rect == preview_rect
            )),
            "Java LoadDialog BorderImage swaps the preview region directly and should not draw an extra whiteui backing sprite"
        );
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, color, thickness, .. }
                    if *rect == preview_rect
                        && (*thickness - 4.0).abs() < f32::EPSILON
                        && (color[0] - super::Pal::GRAY.r).abs() < 0.001
                        && (color[1] - super::Pal::GRAY.g).abs() < 0.001
                        && (color[2] - super::Pal::GRAY.b).abs() < 0.001
                        && (color[3] - 1.0).abs() < 0.001
            )),
            "Java LoadDialog wraps save previews in BorderImage(def, 4f)"
        );
        let autosave_button = DesktopLauncher::load_game_slot_action_button_rect(slot_card, 0);
        assert_eq!(
            (autosave_button.width, autosave_button.height),
            (40.0, 40.0),
            "Java LoadDialog slot actions use t.defaults().size(40f)"
        );
        let delete_button = DesktopLauncher::load_game_slot_action_button_rect(slot_card, 1);
        assert_eq!(
            autosave_button.x - delete_button.x,
            40.0,
            "Java LoadDialog slot action buttons are adjacent 40f emptyi cells"
        );
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if *rect == autosave_button
                        && (symbol == &DesktopLauncher::settings_text_button_symbol("grayt", false, false)
                            || symbol == &DesktopLauncher::settings_text_button_symbol("grayt", false, true))
            )),
            "Java Styles.emptyTogglei autosave action should not draw a grayt background"
        );
        assert!(
            texts.contains(&super::desktop_ui_icon_glyph_or_label("save", "save").as_str()),
            "Java LoadDialog uses Icon.save for the autosave toggle"
        );
        let save_glyph = super::desktop_ui_icon_glyph_or_label("save", "save");
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawText { text, position, color, style, size, .. }
                    if text == &save_glyph
                        && *position == autosave_button.center()
                        && *size == 16.0
                        && *color == DesktopLauncher::settings_image_button_image_color(
                            "emptyTogglei",
                            false,
                            false,
                            true,
                            true
                        )
                        && style.font == RenderFontId::Icon
                        && !style.outline
            )),
            "LoadDialog autosave glyph must use Styles.emptyTogglei checked image color and the upstream icon font"
        );
        let rename_glyph = super::desktop_ui_icon_glyph_or_label("pencil", "pencil");
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawText { text, color, style, .. }
                    if text == &rename_glyph
                        && *color == DesktopLauncher::settings_image_button_image_color(
                            "emptyi",
                            false,
                            false,
                            false,
                            true
                        )
                        && style.font == RenderFontId::Icon
                        && !style.outline
            )),
            "Java LoadDialog uses Icon.pencil with Styles.emptyi image color for the rename slot action"
        );
        let input = DesktopLauncher::default_menu_frame_input_for_viewport(viewport);
        let settings_center = launcher
            .menu_renderer_state
            .ui_plan(input)
            .buttons
            .iter()
            .find(|button| button.role == MenuButtonRole::Settings)
            .expect("menu ui should include SETTINGS")
            .rect
            .center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: settings_center.x,
                    y: settings_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: false,
                },
            ],
        );
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::LoadGame),
            "LoadingFragment is a full-screen touchable modal; menu buttons must not receive clicks while a save is loading"
        );
        assert!(launcher.load_game_pending_load.is_some());
        assert_eq!(launcher.last_menu_pressed_button, None);
        assert_eq!(launcher.last_menu_visual_pressed_button, None);
        for frame_index in 1..=u64::from(super::LOAD_GAME_LOADING_DELAY_FRAMES) {
            launcher.menu_graphics_frame_for_surface(frame_index, viewport);
        }
        assert_eq!(
            launcher.active_menu_route, None,
            "completed load should close the LoadDialog route like Java runLoadSave"
        );
        assert!(launcher.load_game_pending_load.is_none());
        assert!(launcher.game_state.is_playing());
        assert!(launcher.runtime.state.is_playing());
        assert!(
            !launcher.net_client.net_mut().active(),
            "Java LoadDialog.runLoadSave calls net.reset() before slot.load()"
        );
        assert!(!launcher.game_state.rules.editor);
        assert_eq!(launcher.game_state.get_sector(), None);
        assert!(!launcher.runtime.state.rules.editor);
        assert_eq!(launcher.runtime.state.get_sector(), None);
        assert_eq!(launcher.game_state.wave, 9);
        assert_eq!(launcher.game_state.map.name(), "New Map");
        assert_eq!(
            launcher
                .last_load_game_action
                .as_ref()
                .map(|action| action.status.as_str()),
            Some("selected-for-load"),
            "click audit should remain distinct from the completed load result"
        );
        let loaded = launcher
            .last_load_game_result
            .as_ref()
            .expect("completed pending load should record a loaded result");
        assert_eq!(loaded.slot, "2");
        assert_eq!(loaded.status, "loaded");

        launcher.dispatch_menu_action(MenuButtonRole::LoadGame);
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::LoadGame)
        );
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: autosave_button.center().x,
                    y: autosave_button.center().y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        let autosave_action = launcher
            .last_load_game_action
            .as_ref()
            .expect("autosave button should record a toggle action");
        assert_eq!(
            autosave_action.kind,
            super::DesktopLoadGameActionKind::ToggleAutosave
        );
        assert_eq!(autosave_action.status, "toggle-autosave");
        assert_eq!(
            launcher
                .settings_overrides
                .get(&launcher.load_game_slots[0].autosave_setting_key())
                .map(String::as_str),
            Some("false"),
            "Java SaveSlot.setAutosave writes save-<index>-autosave into settings"
        );
        assert!(!launcher.load_game_slot_is_autosave(&launcher.load_game_slots[0]));
        let toggled_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let toggled_commands = toggled_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("toggled autosave frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let toggled_texts = toggled_commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let toggled_autosave_line =
            launcher.load_game_slot_autosave_render_line(&launcher.load_game_slots[0]);
        assert!(toggled_texts.contains(&toggled_autosave_line.as_str()));
        assert!(
            !toggled_texts
                .iter()
                .any(|text| text.contains("@save.autosave") || text.contains("@off")),
            "LoadDialog autosave toggle final DrawText should localize @save.autosave/@off before rendering"
        );
        let card_rects = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } if symbol == "whiteui" => {
                    Some(*rect)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(card_rects.contains(&slot_card));

        let load_panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::LoadGame,
        );
        let load_back = DesktopLauncher::route_back_button_rect_for_panel(load_panel);
        let import_rect = DesktopLauncher::load_game_import_button_rect_for_panel(load_panel);
        assert_eq!(
            import_rect.x,
            load_back.right() + 12.0,
            "Java LoadDialog addSetup() puts @save.import in the same button row after the back button"
        );
        assert_eq!(
            import_rect.right(),
            load_panel.right() - 28.0,
            "Java LoadDialog addSetup() uses fillX() for @save.import instead of a fixed-width block"
        );
        let import = import_rect.center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, import.x, import.y),
            Some(super::DesktopMenuRouteShellAction::LoadGameImport)
        );
        let mut platform = RecordingPlatform::default();
        let request = launcher.dispatch_load_game_import_with_platform(&mut platform);
        assert!(request.open);
        assert_eq!(request.title, "@save.import");
        assert_eq!(request.extension, "msav");
        assert_eq!(launcher.last_load_game_import_request, Some(request));

        let invalid_source = root.join("invalid.msav");
        std::fs::write(&invalid_source, b"not a valid save")
            .expect("invalid import fixture should write");
        let invalid_error = launcher
            .import_load_game_save_file(&invalid_source)
            .expect_err("invalid save should be rejected");
        assert_eq!(invalid_error, "@save.import.invalid");
        assert_eq!(
            launcher.load_game_error.as_deref(),
            Some("@save.import.invalid")
        );
        assert!(!invalid_error.contains(':'));

        let missing_source = root.join("missing.msav");
        let missing_display = missing_source.display().to_string();
        let expected_missing_error =
            launcher.format_bundle_text("save.import.fail", &[missing_display.as_str()]);
        let missing_error = launcher
            .import_load_game_save_file(&missing_source)
            .expect_err("missing imported save should surface a user import failure");
        assert_eq!(missing_error, expected_missing_error);
        assert!(!missing_error.contains("failed to read imported save"));

        let mut imported_tags = BTreeMap::new();
        imported_tags.insert("mapname".into(), "Imported Map".into());
        imported_tags.insert("saved".into(), "999".into());
        imported_tags.insert("wave".into(), "12".into());
        let mut imported_bytes = Vec::new();
        write_deflated_save_meta_prefix(&mut imported_bytes, LATEST_SAVE_VERSION, &imported_tags)
            .expect("imported save meta should encode");
        let imported_source = root.join("incoming.msav");
        std::fs::write(&imported_source, imported_bytes).expect("imported source should write");
        let imported = launcher
            .import_load_game_save_file(&imported_source)
            .expect("valid non-campaign save should import");
        assert!(imported.destination.ends_with("0.msav"));
        assert_eq!(imported.map_name.as_deref(), Some("Imported Map"));
        assert_eq!(imported.timestamp, 999);
        assert_eq!(imported.status, "imported");
        assert_eq!(launcher.load_game_error, None);
        assert!(save_dir.join("0.msav").exists());
        assert_eq!(launcher.last_load_game_import_result, Some(imported));
        assert_eq!(launcher.load_game_slots.len(), 3);
        assert!(launcher
            .load_game_slots
            .iter()
            .any(|slot| launcher.load_game_slot_display_title(slot) == "incoming"));

        let rename_action = launcher
            .dispatch_load_game_slot_action_kind_with_platform(
                0,
                super::DesktopLoadGameActionKind::Rename,
                &mut platform,
            )
            .expect("rename button should open text input mirror");
        assert_eq!(rename_action.kind, super::DesktopLoadGameActionKind::Rename);
        assert_eq!(launcher.load_game_rename_dialog_slot, Some(0));
        assert_eq!(launcher.load_game_rename_text, "incoming");
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::Key {
                    key_code: "Delete".into(),
                    pressed: true,
                },
                DesktopInputTickEvent::Text("Renamed Save".into()),
            ],
        );
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::LoadGame,
        );
        let rename_dialog = DesktopLauncher::load_game_rename_dialog_rect_for_panel(panel);
        let ok = DesktopLauncher::load_game_rename_button_rect(rename_dialog, 1).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, ok.x, ok.y),
            Some(super::DesktopMenuRouteShellAction::LoadGameRenameOk)
        );
        let cancel = DesktopLauncher::load_game_rename_button_rect(rename_dialog, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, cancel.x, cancel.y),
            Some(super::DesktopMenuRouteShellAction::LoadGameRenameCancel)
        );
        let rename_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let rename_texts = rename_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("rename dialog should render a frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let rename_sprites = rename_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("rename dialog should render a frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } => Some((symbol.as_str(), *rect)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let rename_field = DesktopLauncher::load_game_rename_field_rect(rename_dialog);
        let text_field_background = DesktopLauncher::settings_text_field_background_symbol();
        let text_field_cursor = DesktopLauncher::settings_text_field_cursor_symbol();
        let save_rename_label = launcher.localize_bundle_markup_text("@save.rename");
        assert!(rename_texts.contains(&save_rename_label.as_str()));
        assert!(!rename_texts.contains(&"@save.rename"));
        assert!(rename_texts.contains(&launcher.localize_bundle_markup_text("@ok").as_str()));
        assert!(rename_texts.contains(&launcher.localize_bundle_markup_text("@cancel").as_str()));
        assert!(rename_sprites.iter().any(|(symbol, rect)| {
            *symbol == text_field_background.as_str() && *rect == rename_field
        }));
        assert!(
            rename_sprites.iter().any(|(symbol, rect)| {
                *symbol == text_field_cursor.as_str()
                    && *rect
                        == DesktopLauncher::single_line_text_field_cursor_rect(
                            rename_field,
                            "Renamed Save",
                        )
            }),
            "LoadDialog rename text input should render the Java TextField cursor"
        );
        launcher
            .dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::LoadGameRenameOk);
        let rename = launcher
            .last_load_game_rename_result
            .clone()
            .expect("rename confirmation should write result");
        assert_eq!(rename.previous_name, "incoming");
        assert_eq!(rename.new_name, "Renamed Save");
        assert_eq!(rename.status, "renamed");
        assert_eq!(launcher.last_load_game_rename_result, Some(rename));
        assert_eq!(launcher.load_game_rename_dialog_slot, None);
        let closed_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let closed_texts = closed_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("load game route should still render after closing rename dialog")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(!closed_texts.contains(&"@save.rename"));
        assert_eq!(
            launcher.load_game_slot_display_title(&launcher.load_game_slots[0]),
            "Renamed Save"
        );
        launcher.load_game_search = "renamed".into();
        assert_eq!(launcher.filtered_load_game_slot_indices(), vec![0]);
        launcher.load_game_search.clear();

        let mut platform = RecordingPlatform::default();
        let export_action = launcher
            .dispatch_load_game_slot_action_kind_with_platform(
                0,
                super::DesktopLoadGameActionKind::Export,
                &mut platform,
            )
            .expect("imported save should request export");
        assert_eq!(export_action.kind, super::DesktopLoadGameActionKind::Export);
        assert_eq!(export_action.status, "export");
        assert_eq!(
            launcher.last_load_game_export_request,
            Some(FileChooserRequest::new(false, "@save", "msav"))
        );
        let export_target = root.join("exported-save");
        let exported = launcher
            .export_load_game_save_file_to(0, &export_target)
            .expect("export should copy save file");
        assert!(exported.destination.ends_with("exported-save.msav"));
        assert_eq!(exported.map_name.as_deref(), Some("Imported Map"));
        assert_eq!(exported.status, "exported");
        assert_eq!(
            launcher.last_load_game_export_result,
            Some(exported.clone())
        );
        assert_eq!(
            std::fs::read(save_dir.join("0.msav")).expect("imported save should exist"),
            std::fs::read(root.join("exported-save.msav")).expect("exported save should exist")
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_run_load_save_falls_back_to_backup_on_corrupt_primary() {
        let root = temp_desktop_path("load-game-backup-fallback");
        let save_dir = root.join("saves");
        std::fs::create_dir_all(&save_dir).expect("save fixture dir should be writable");
        let primary = save_dir.join("3.msav");
        std::fs::write(&primary, b"broken primary save").expect("corrupt primary should write");

        let mut backup_tags = BTreeMap::new();
        backup_tags.insert("mapname".into(), "Backup Map".into());
        backup_tags.insert("saved".into(), "300".into());
        backup_tags.insert("wave".into(), "12".into());
        backup_tags.insert("rules".into(), r#"{"modeName":"pvp"}"#.into());
        let mut backup_bytes = Vec::new();
        write_deflated_save_meta_prefix(&mut backup_bytes, LATEST_SAVE_VERSION, &backup_tags)
            .expect("backup save meta should encode");
        std::fs::write(super::backup_file_for_path(&primary), backup_bytes)
            .expect("backup save should write");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.save_dir = save_dir.display().to_string();
        launcher.dispatch_menu_action(MenuButtonRole::LoadGame);

        assert_eq!(launcher.load_game_slots.len(), 1);
        assert_eq!(
            launcher.load_game_slots[0]
                .meta
                .as_ref()
                .and_then(|meta| meta.map_name.as_deref()),
            Some("Backup Map"),
            "LoadDialog list should already be able to recover metadata from the backup"
        );

        launcher
            .dispatch_load_game_slot_action_kind(0, super::DesktopLoadGameActionKind::Load)
            .expect("backup-backed save slot should start loading");
        launcher.campaign_planet_dialog = Some(super::CampaignPlanetDialogState::look(
            &launcher.content_loader,
            &launcher.game_state,
        ));
        launcher.map_play_dialog_index = Some(0);
        launcher.editor_map_info_dialog_index = Some(0);
        launcher.map_play_mode_help_dialog_open = true;
        launcher.map_play_customize_dialog_open = true;
        launcher.map_play_rules_edit_dialog_open = true;
        launcher.map_play_loadout_dialog_open = true;
        launcher.map_play_loadout_scroll_offset = 3;
        launcher.map_play_banned_content_dialog = Some(super::DesktopBannedContentKind::Blocks);
        launcher.map_play_weather_dialog_open = true;
        launcher.map_play_weather_add_dialog_open = true;
        launcher.map_play_ambient_light_dialog_open = true;
        launcher.map_play_planet_dialog_open = true;
        launcher.map_play_rules = Some(mindustry_core::mindustry::game::Rules::default());
        launcher.map_play_rules_error = Some("stale rules error".into());
        launcher.map_play_playtesting = true;
        launcher.load_game_search_focused = true;
        launcher.load_game_error = Some("@save.corrupted".into());
        launcher.load_game_rename_dialog_slot = Some(0);
        launcher.load_game_delete_dialog_slot = Some(0);
        launcher.load_game_missing_mods_confirm_slot = Some(0);
        launcher.load_game_missing_mods = vec!["stale-mod".into()];
        launcher.load_game_rename_text = "stale rename".into();
        launcher.save_game_new_dialog_open = true;
        launcher.save_game_new_text = "stale save".into();
        launcher.save_game_overwrite_dialog_slot = Some(0);
        let viewport =
            launcher.default_render_viewport_for_surface(DesktopSurfaceSize::new(1280, 720));
        for frame_index in 1..=u64::from(super::LOAD_GAME_LOADING_DELAY_FRAMES) {
            launcher.menu_graphics_frame_for_surface(frame_index, viewport);
        }

        assert_eq!(launcher.load_game_error, None);
        assert_eq!(launcher.active_menu_route, None);
        assert_eq!(launcher.campaign_planet_dialog, None);
        assert_eq!(launcher.map_play_dialog_index, None);
        assert_eq!(launcher.editor_map_info_dialog_index, None);
        assert!(!launcher.map_play_mode_help_dialog_open);
        assert!(!launcher.map_play_customize_dialog_open);
        assert!(!launcher.map_play_rules_edit_dialog_open);
        assert!(!launcher.map_play_loadout_dialog_open);
        assert_eq!(launcher.map_play_loadout_scroll_offset, 0);
        assert_eq!(launcher.map_play_banned_content_dialog, None);
        assert!(!launcher.map_play_weather_dialog_open);
        assert!(!launcher.map_play_weather_add_dialog_open);
        assert!(!launcher.map_play_ambient_light_dialog_open);
        assert!(!launcher.map_play_planet_dialog_open);
        assert_eq!(launcher.map_play_rules, None);
        assert_eq!(launcher.map_play_rules_error, None);
        assert!(!launcher.map_play_playtesting);
        assert!(!launcher.load_game_search_focused);
        assert_eq!(launcher.load_game_rename_dialog_slot, None);
        assert_eq!(launcher.load_game_delete_dialog_slot, None);
        assert_eq!(launcher.load_game_missing_mods_confirm_slot, None);
        assert!(launcher.load_game_missing_mods.is_empty());
        assert!(launcher.load_game_rename_text.is_empty());
        assert!(!launcher.save_game_new_dialog_open);
        assert!(launcher.save_game_new_text.is_empty());
        assert_eq!(launcher.save_game_overwrite_dialog_slot, None);
        assert!(launcher.game_state.is_playing());
        assert_eq!(launcher.game_state.wave, 12);
        assert_eq!(launcher.game_state.map.name(), "Backup Map");
        assert_eq!(
            launcher
                .last_load_game_result
                .as_ref()
                .map(|action| action.status.as_str()),
            Some("loaded"),
            "Java SaveIO.load falls back to the backup before reporting a corrupted save"
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_load_game_cautious_load_confirms_missing_mods_like_java() {
        let root = temp_desktop_path("load-game-missing-mod-confirm");
        let save_dir = root.join("saves");
        std::fs::create_dir_all(&save_dir).expect("save fixture dir should be writable");

        let mut tags = BTreeMap::new();
        tags.insert("mapname".into(), "Modded Map".into());
        tags.insert("saved".into(), "400".into());
        tags.insert("wave".into(), "8".into());
        tags.insert(
            "mods".into(),
            r#"["example-mod:1.0","missing-mod:2.0"]"#.into(),
        );
        let mut bytes = Vec::new();
        write_deflated_save_meta_prefix(&mut bytes, LATEST_SAVE_VERSION, &tags)
            .expect("modded save meta should encode");
        std::fs::write(save_dir.join("5.msav"), bytes).expect("modded save should write");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.save_dir = save_dir.display().to_string();
        launcher.dispatch_menu_action(MenuButtonRole::LoadGame);
        launcher.last_mods_directory_mod_names = vec!["example-mod".into()];
        launcher.last_mods_directory_mod_metas =
            vec![mindustry_core::mindustry::modsys::ModMetadata {
                name: Some("example mod".into()),
                version: Some("1.0".into()),
                ..Default::default()
            }];
        launcher.last_mods_directory_mod_states =
            vec![super::DesktopModsRouteModStateSnapshot::default()];

        let action = launcher
            .dispatch_load_game_slot_action_kind(0, super::DesktopLoadGameActionKind::Load)
            .expect("modded slot should still record the load click");
        assert_eq!(action.status, "missing-mods-confirm");
        assert_eq!(launcher.load_game_pending_load, None);
        assert_eq!(launcher.load_game_missing_mods_confirm_slot, Some(0));
        assert_eq!(launcher.load_game_missing_mods, vec!["missing-mod:2.0"]);

        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::LoadGame);
        assert!(lines.contains(&"dialog: @warning".to_string()));
        assert!(lines.iter().any(|line| line.contains("missing-mod:2.0")));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::LoadGame,
        );
        let dialog = DesktopLauncher::load_game_missing_mods_dialog_rect_for_panel(panel);
        let missing_cancel = DesktopLauncher::load_game_confirm_button_rect(dialog, 0);
        let missing_ok = DesktopLauncher::load_game_confirm_button_rect(dialog, 1);
        assert_eq!(
            missing_cancel.height, 54.0,
            "Java UI.showConfirm buttons are 54f tall"
        );
        assert_eq!(
            missing_ok.width, 200.0,
            "wide load/save confirm dialogs should use Java UI.showConfirm's 200f button width"
        );
        let cancel = missing_cancel.center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, cancel.x, cancel.y),
            Some(super::DesktopMenuRouteShellAction::LoadGameMissingModsCancel)
        );
        assert!(launcher.apply_menu_back_key());
        assert_eq!(launcher.load_game_missing_mods_confirm_slot, None);
        assert_eq!(
            launcher.last_menu_route_shell_action,
            Some(super::DesktopMenuRouteShellAction::LoadGameMissingModsCancel)
        );

        launcher
            .dispatch_load_game_slot_action_kind(0, super::DesktopLoadGameActionKind::Load)
            .expect("second modded load should reopen confirmation");
        let ok = missing_ok.center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, ok.x, ok.y),
            Some(super::DesktopMenuRouteShellAction::LoadGameMissingModsOk)
        );
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Key {
                key_code: "Enter".into(),
                pressed: true,
            }],
        );
        assert!(launcher.load_game_pending_load.is_some());
        assert_eq!(launcher.load_game_missing_mods_confirm_slot, None);
        assert_eq!(
            launcher.last_menu_route_shell_action,
            Some(super::DesktopMenuRouteShellAction::LoadGameMissingModsOk)
        );
        assert_eq!(
            launcher
                .last_load_game_action
                .as_ref()
                .map(|load| load.status.as_str()),
            Some("selected-for-load")
        );

        for frame_index in 1..=u64::from(super::LOAD_GAME_LOADING_DELAY_FRAMES) {
            launcher.menu_graphics_frame_for_surface(frame_index, viewport);
        }

        assert_eq!(launcher.active_menu_route, None);
        assert_eq!(launcher.load_game_missing_mods_confirm_slot, None);
        assert!(launcher.load_game_missing_mods.is_empty());
        assert_eq!(
            launcher.last_menu_route_shell_action,
            Some(super::DesktopMenuRouteShellAction::LoadGameMissingModsOk)
        );
        assert!(launcher.game_state.is_playing());
        assert_eq!(launcher.game_state.map.name(), "Modded Map");
        assert_eq!(
            launcher
                .last_load_game_result
                .as_ref()
                .map(|load| load.status.as_str()),
            Some("loaded")
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_run_load_save_reports_corrupted_when_primary_and_backup_fail() {
        let root = temp_desktop_path("load-game-corrupted");
        let save_dir = root.join("saves");
        std::fs::create_dir_all(&save_dir).expect("save fixture dir should be writable");
        let primary = save_dir.join("4.msav");
        std::fs::write(&primary, b"broken primary save").expect("corrupt primary should write");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.active_menu_route = Some(super::DesktopMenuRoute::LoadGame);
        launcher.load_game_slots = vec![super::SaveSlotRecord::new(primary.clone())];
        launcher
            .dispatch_load_game_slot_action_kind(0, super::DesktopLoadGameActionKind::Load)
            .expect("corrupt save should still enter Java LoadDialog loading flow");
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        for frame_index in 1..=u64::from(super::LOAD_GAME_LOADING_DELAY_FRAMES) {
            launcher.menu_graphics_frame_for_surface(frame_index, viewport);
        }

        assert_eq!(
            launcher.active_menu_route, None,
            "Java LoadDialog.runLoadSave hides the LoadDialog before showing UI.showErrorMessage"
        );
        assert!(launcher.load_game_pending_load.is_none());
        assert!(!launcher.game_state.is_playing());
        assert_eq!(launcher.load_game_error.as_deref(), Some("@save.corrupted"));
        let guard_message = launcher
            .last_menu_guard_message
            .clone()
            .expect("corrupted load should retain the underlying SaveException details");
        assert_ne!(
            guard_message.as_str(),
            "@save.corrupted",
            "user-facing @save.corrupted should stay separate from the underlying failure details"
        );
        launcher.load_game_search_focused = true;
        launcher.apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("ignored".into())]);
        assert!(
            launcher.load_game_search.is_empty(),
            "Java UI.showErrorMessage modal should block LoadDialog background text input"
        );
        let error_frame = launcher.menu_graphics_frame_for_surface(
            u64::from(super::LOAD_GAME_LOADING_DELAY_FRAMES) + 1,
            viewport,
        );
        let error_texts = error_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("corrupted load should render the global UI.showErrorMessage modal")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            !error_texts.contains(&"save slots: error | @save.corrupted"),
            "Java LoadDialog reports corrupted saves through UI.showErrorMessage, not an inline Rust-only slot banner"
        );
        assert!(
            error_texts.contains(
                &launcher
                    .localize_bundle_markup_text("@error.title")
                    .as_str()
            ),
            "Java UI.showErrorMessage should render an @error.title modal"
        );
        assert!(
            error_texts.contains(
                &launcher
                    .localize_bundle_markup_text("@save.corrupted")
                    .as_str()
            ),
            "Java UI.showErrorMessage should render the localized corrupted-save message"
        );
        assert!(
            error_texts.contains(&launcher.localize_bundle_markup_text("@ok").as_str()),
            "Java UI.showErrorMessage should expose a single @ok close button"
        );
        assert!(
            !error_texts.contains(&guard_message.as_str()),
            "underlying SaveException details should not be drawn over the modal error text"
        );
        let dialog = DesktopLauncher::load_game_error_dialog_rect_for_viewport(viewport);
        let ok_center = DesktopLauncher::load_game_error_dialog_ok_button_rect(dialog).center();
        assert_eq!(
            launcher
                .last_load_game_result
                .as_ref()
                .map(|action| action.status.as_str()),
            Some("corrupted"),
            "Java LoadDialog.runLoadSave should surface @save.corrupted instead of entering gameplay"
        );
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: ok_center.x,
                    y: ok_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "left".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(launcher.load_game_error, None);
        assert_eq!(launcher.last_menu_guard_message, None);
        assert_eq!(
            launcher.last_menu_route_shell_action,
            Some(super::DesktopMenuRouteShellAction::CloseLoadGameError)
        );

        launcher.load_game_error = Some("@save.corrupted".into());
        launcher.last_menu_guard_message = Some("hidden SaveException details".into());
        assert!(launcher.apply_menu_back_key());
        assert_eq!(launcher.load_game_error, None);
        assert_eq!(launcher.last_menu_guard_message, None);

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_load_game_route_toggles_mode_filters_like_upstream_load_dialog() {
        let root = temp_desktop_path("load-game-mode-filter");
        let save_dir = root.join("saves");
        std::fs::create_dir_all(&save_dir).expect("save fixture dir should be writable");

        let mut survival_tags = BTreeMap::new();
        survival_tags.insert("mapname".into(), "Old Map".into());
        survival_tags.insert("saved".into(), "100".into());
        survival_tags.insert("wave".into(), "3".into());
        let mut survival_bytes = Vec::new();
        write_deflated_save_meta_prefix(&mut survival_bytes, LATEST_SAVE_VERSION, &survival_tags)
            .expect("survival save meta should encode");
        std::fs::write(save_dir.join("1.msav"), survival_bytes)
            .expect("survival save should write");

        let mut attack_tags = BTreeMap::new();
        attack_tags.insert("mapname".into(), "New Map".into());
        attack_tags.insert("saved".into(), "200".into());
        attack_tags.insert("wave".into(), "9".into());
        attack_tags.insert("rules".into(), r#"{"modeName":"attack"}"#.into());
        let mut attack_bytes = Vec::new();
        write_deflated_save_meta_prefix(&mut attack_bytes, LATEST_SAVE_VERSION, &attack_tags)
            .expect("attack save meta should encode");
        std::fs::write(save_dir.join("2.msav"), attack_bytes).expect("attack save should write");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.save_dir = save_dir.display().to_string();
        launcher.dispatch_menu_action(MenuButtonRole::LoadGame);

        assert_eq!(
            launcher.filtered_load_game_slot_indices(),
            vec![0, 1],
            "newer attack save and older survival save should both be visible initially"
        );
        assert!(launcher.load_game_hidden_modes.is_empty());

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::LoadGame,
        );
        let search = DesktopLauncher::load_game_search_rect_for_panel(panel);
        let attack_filter = DesktopLauncher::load_game_mode_filter_button_rect(search, 2).center();
        let editor_filter = DesktopLauncher::load_game_mode_filter_button_rect(search, 4).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                attack_filter.x,
                attack_filter.y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleLoadGameMode(
                Gamemode::Attack
            ))
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                editor_filter.x,
                editor_filter.y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleLoadGameMode(
                Gamemode::Editor
            )),
            "Java LoadDialog iterates Gamemode.all, including the hidden editor mode filter"
        );

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: attack_filter.x,
                    y: attack_filter.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(launcher.load_game_hidden_modes, vec![Gamemode::Attack]);
        assert_eq!(
            launcher.filtered_load_game_slot_indices(),
            vec![1],
            "hiding attack should leave the survival slot visible"
        );
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::LoadGame);
        assert!(lines.contains(&"hidden modes: attack".to_string()));
        assert!(lines.iter().any(|line| line.contains("#0 untitled")));
        assert!(!lines.iter().any(|line| line.contains("New Map")));

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let filter_commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("filtered load game frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = filter_commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&"[accent]untitled"));
        assert!(!texts.contains(&"[accent]New Map"));
        assert!(
            !texts.contains(&"1 / 2"),
            "Java LoadDialog does not render a Rust-only filtered/total summary beside mode filters"
        );
        assert!(
            texts.contains(
                &launcher
                    .localize_bundle_markup_text("@mode.attack.name")
                    .as_str()
            ),
            "Java LoadDialog mode filter buttons expose @mode.<name>.name as hover tooltip"
        );
        let attack_tooltip_label = launcher.localize_bundle_markup_text("@mode.attack.name");
        let attack_tooltip_width =
            (attack_tooltip_label.chars().count() as f32 * 7.0 + 8.0).clamp(56.0, 260.0);
        let attack_tooltip_height = 28.0;
        let attack_tooltip = RenderRect::new(
            (attack_filter.x + 14.0)
                .min(panel.right() - attack_tooltip_width - 4.0)
                .max(panel.x + 4.0),
            (attack_filter.y + 14.0)
                .min(panel.y + panel.height - attack_tooltip_height - 4.0)
                .max(panel.y + 4.0),
            attack_tooltip_width,
            attack_tooltip_height,
        );
        let (black6_symbol, black6_tint) =
            DesktopLauncher::settings_drawable_symbol_and_tint("black6", 1.0);
        assert!(
            filter_commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, tint, .. }
                    if symbol == &black6_symbol && *rect == attack_tooltip && *tint == black6_tint
            )),
            "Java LoadDialog tooltip(...) should render with Styles.black6 chrome"
        );
        assert!(
            !filter_commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, .. } if *rect == attack_tooltip
            )),
            "Java Tooltip for LoadDialog mode filters does not add a Rust-only stroked pane"
        );
        assert!(
            filter_commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawText { text, position, color, size, .. }
                    if text == &attack_tooltip_label
                        && *position == RenderPoint::new(attack_tooltip.x + 4.0, attack_tooltip.center().y)
                        && *color == [0.94, 0.98, 1.0, 1.0]
                        && (*size - 11.0).abs() < f32::EPSILON
            )),
            "Java Tooltip uses a compact black6 label with 4f margin, not the old blue pane tooltip"
        );
        let attack_glyph = super::desktop_ui_icon_glyph_or_label(
            DesktopLauncher::load_game_mode_filter_icon(Gamemode::Attack),
            Gamemode::Attack.wire_name(),
        );
        assert!(
            filter_commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawText { text, position, color, style, .. }
                    if text == &attack_glyph
                        && *position == DesktopLauncher::load_game_mode_filter_button_rect(search, 2).center()
                        && *color == DesktopLauncher::settings_image_button_image_color(
                            "emptyTogglei",
                            true,
                            false,
                            false,
                            true
                        )
                        && style.font == RenderFontId::Icon
                        && !style.outline
            )),
            "hidden LoadDialog mode filters should render with Java Styles.emptyTogglei unchecked image color"
        );

        let survival_filter =
            DesktopLauncher::load_game_mode_filter_button_rect(search, 0).center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: survival_filter.x,
                    y: survival_filter.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert!(launcher.load_game_hidden_modes.contains(&Gamemode::Attack));
        assert!(launcher
            .load_game_hidden_modes
            .contains(&Gamemode::Survival));
        assert!(launcher.filtered_load_game_slot_indices().is_empty());
        let empty_lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::LoadGame);
        assert!(empty_lines.contains(&"empty: @save.none".to_string()));
        assert!(!empty_lines.contains(&"empty: @none.found".to_string()));
        let empty_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let empty_render_frame = empty_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("empty filtered load game frame should contain render frame");
        let empty_commands = empty_render_frame
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let empty_texts = empty_commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(empty_texts.contains(&launcher.localize_bundle_markup_text("@save.none").as_str()));
        assert!(
            !empty_texts.contains(&launcher.localize_bundle_markup_text("@none.found").as_str())
        );
        let save_none_text = launcher.localize_bundle_markup_text("@save.none");
        let list = DesktopLauncher::load_game_list_rect_for_panel(panel);
        let expected_empty_point = DesktopLauncher::load_game_empty_message_point_for_list(list);
        let empty_draw = empty_commands
            .iter()
            .find_map(|command| match command {
                RenderCommand::DrawText {
                    text,
                    position,
                    style,
                    ..
                } if text == &save_none_text => Some((*position, *style)),
                _ => None,
            })
            .expect("@save.none should render when all LoadDialog slots are filtered out");
        assert_eq!(
            empty_draw.0, expected_empty_point,
            "Java LoadDialog adds @save.none through the slots table flow; Rust should not center it in the list pane"
        );
        assert_eq!(empty_draw.1.horizontal_align, RenderTextAlign::Start);
        assert_ne!(empty_draw.0, list.center());
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: survival_filter.x,
                    y: survival_filter.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: attack_filter.x,
                    y: attack_filter.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert!(launcher.load_game_hidden_modes.is_empty());
        assert_eq!(launcher.filtered_load_game_slot_indices(), vec![0, 1]);

        let empty_save_dir = root.join("empty-saves");
        std::fs::create_dir_all(&empty_save_dir).expect("empty save dir should be writable");
        let mut empty_launcher = DesktopLauncher::new(Vec::new());
        empty_launcher.client.context.paths.save_dir = empty_save_dir.display().to_string();
        empty_launcher.dispatch_menu_action(MenuButtonRole::LoadGame);
        assert!(empty_launcher.load_game_slots.is_empty());
        let empty_slot_lines =
            empty_launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::LoadGame);
        assert!(empty_slot_lines.contains(&"empty: @save.none".to_string()));
        assert!(
            !empty_slot_lines
                .iter()
                .any(|line| line.contains(".msav") || line.starts_with("dir:")),
            "Java LoadDialog empty slot table only adds @save.none, not Rust-only filesystem diagnostics"
        );
        empty_launcher.open_pause_overlay_route(super::DesktopMenuRoute::SaveGame);
        let empty_save_lines =
            empty_launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::SaveGame);
        assert!(empty_save_lines.contains(&"empty: @save.none".to_string()));
        assert!(
            !empty_save_lines
                .iter()
                .any(|line| line.contains(".msav") || line.starts_with("dir:")),
            "SaveDialog inherits LoadDialog empty table and should not expose Rust-only filesystem diagnostics"
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_save_dialog_new_save_input_contract_matches_upstream_savegame() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.active_menu_route = Some(super::DesktopMenuRoute::SaveGame);
        launcher.save_game_new_dialog_open = true;
        launcher.save_game_new_text.clear();

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::SaveGame,
        );
        let dialog = DesktopLauncher::load_game_rename_dialog_rect_for_panel(panel);

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("save dialog frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let sprites = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("save dialog frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } => Some((symbol.as_str(), *rect)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let field = DesktopLauncher::load_game_rename_field_rect(dialog);
        let text_field_background = DesktopLauncher::settings_text_field_background_symbol();
        let text_field_cursor = DesktopLauncher::settings_text_field_cursor_symbol();

        assert!(
            texts.contains(&launcher.localize_bundle_markup_text("@savegame").as_str()),
            "upstream SaveDialog should title the route with localized @savegame"
        );
        assert!(
            texts.contains(&launcher.localize_bundle_markup_text("@save.new").as_str()),
            "upstream SaveDialog should expose the localized new-save button"
        );
        assert!(
            texts.contains(
                &launcher
                    .localize_bundle_markup_text("@save.newslot")
                    .as_str()
            ),
            "upstream SaveDialog should label the new-save text input with localized @save.newslot"
        );
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@cancel").as_str()));
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@ok").as_str()));
        for raw_key in [
            "@savegame",
            "@save",
            "@save.new",
            "@save.newslot",
            "@cancel",
            "@ok",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "SaveDialog new-save final DrawText should localize {raw_key} before rendering"
            );
        }
        assert!(
            sprites.iter().any(|(symbol, rect)| {
                *symbol == text_field_background.as_str() && *rect == field
            }),
            "desktop UI.showTextInput should skin the new-save input with Java defaultField"
        );
        assert!(
            sprites.iter().any(|(symbol, rect)| {
                *symbol == text_field_cursor.as_str()
                    && *rect == DesktopLauncher::single_line_text_field_cursor_rect(field, "")
            }),
            "desktop UI.showTextInput should show the focused Java TextField cursor"
        );

        let cancel = DesktopLauncher::load_game_rename_button_rect(dialog, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, cancel.x, cancel.y),
            Some(super::DesktopMenuRouteShellAction::SaveGameNewCancel)
        );

        let ok = DesktopLauncher::load_game_rename_button_rect(dialog, 1).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, ok.x, ok.y),
            None,
            "empty save-name input should keep OK disabled"
        );
    }

    #[test]
    fn desktop_launcher_save_game_new_dialog_and_load_search_focus_are_stable() {
        let root = temp_desktop_path("save-game-focus-stability");
        let save_dir = root.join("saves");
        std::fs::create_dir_all(&save_dir).expect("save fixture dir should be writable");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.save_dir = save_dir.display().to_string();

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);

        launcher.dispatch_menu_action(MenuButtonRole::LoadGame);
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::LoadGame)
        );
        assert!(
            launcher.load_game_search_focused,
            "LoadDialog.show should focus the search field on desktop so the first key is not lost"
        );
        launcher.apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("Map 2".into())]);
        assert_eq!(launcher.load_game_search, "Map 2");
        let load_panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::LoadGame,
        );
        let search_row = DesktopLauncher::load_game_search_rect_for_panel(load_panel);
        let search_field = DesktopLauncher::load_game_search_field_rect_for_row(search_row);
        let load_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let load_sprites = load_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("focused LoadDialog search frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } => Some((symbol.as_str(), *rect)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let text_field_background = DesktopLauncher::settings_text_field_background_symbol();
        let text_field_cursor = DesktopLauncher::settings_text_field_cursor_symbol();
        assert!(load_sprites.iter().any(|(symbol, rect)| {
            *symbol == text_field_background.as_str() && *rect == search_field
        }));
        assert!(
            load_sprites.iter().any(|(symbol, rect)| {
                *symbol == text_field_cursor.as_str()
                    && *rect
                        == DesktopLauncher::single_line_text_field_cursor_rect(search_field, "Map 2")
            }),
            "focused LoadDialog search should render the Java TextField cursor at the typed text end"
        );

        launcher.open_pause_overlay_route(super::DesktopMenuRoute::SaveGame);
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::SaveGame)
        );
        assert!(
            launcher.load_game_search_focused,
            "SaveDialog inherits LoadDialog.show and should also focus the search field before a text input dialog opens"
        );
        assert!(launcher.load_game_search.is_empty());
        launcher.load_game_search = "background search".into();
        launcher.load_game_scroll_offset = 2;

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::SaveGame,
        );
        let new_save_center =
            DesktopLauncher::load_game_import_button_rect_for_panel(panel).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                new_save_center.x,
                new_save_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::SaveGameNew),
            "SaveDialog replaces LoadDialog's import button with @save.new"
        );
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: new_save_center.x,
                    y: new_save_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert!(launcher.save_game_new_dialog_open);
        assert!(
            !launcher.load_game_search_focused,
            "ui.showTextInput should hand keyboard focus to the new-save text field instead of the background search box"
        );

        launcher
            .apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("Alpha Save".into())]);
        assert_eq!(launcher.save_game_new_text, "Alpha Save");
        let save_dialog = DesktopLauncher::load_game_rename_dialog_rect_for_panel(panel);
        let save_field = DesktopLauncher::load_game_rename_field_rect(save_dialog);
        let save_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let save_sprites = save_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("focused SaveDialog new-save frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } => Some((symbol.as_str(), *rect)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(save_sprites.iter().any(|(symbol, rect)| {
            *symbol == text_field_background.as_str() && *rect == save_field
        }));
        assert!(
            save_sprites.iter().any(|(symbol, rect)| {
                *symbol == text_field_cursor.as_str()
                    && *rect
                        == DesktopLauncher::single_line_text_field_cursor_rect(
                            save_field,
                            "Alpha Save"
                        )
            }),
            "focused SaveDialog new-save input should render the Java TextField cursor at the typed text end"
        );
        assert_eq!(
            launcher.load_game_search, "background search",
            "typing in the new-save dialog must not leak into the inherited LoadDialog search field"
        );
        assert_eq!(launcher.load_game_scroll_offset, 2);

        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Key {
                key_code: "Backspace".into(),
                pressed: true,
            }],
        );
        assert_eq!(launcher.save_game_new_text, "Alpha Sav");
        assert_eq!(launcher.load_game_search, "background search");

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::Text("e".into()),
                DesktopInputTickEvent::Key {
                    key_code: "Enter".into(),
                    pressed: true,
                },
            ],
        );
        assert!(!launcher.save_game_new_dialog_open);
        assert!(launcher.save_game_new_text.is_empty());
        assert_eq!(
            launcher
                .save_game_pending_save
                .as_ref()
                .map(|pending| &pending.operation),
            Some(&super::DesktopSaveGamePendingOperation::New {
                name: "Alpha Save".into()
            })
        );
        assert_eq!(launcher.load_game_search, "background search");

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::Text("ignored".into()),
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -1.0,
                },
            ],
        );
        assert_eq!(
            launcher.load_game_search, "background search",
            "the visible @saving modal must keep background search input blocked until the save finishes"
        );
        assert_eq!(launcher.load_game_scroll_offset, 2);

        for frame_index in 0..u64::from(super::SAVE_GAME_SAVING_DELAY_FRAMES) {
            launcher.menu_graphics_frame_for_surface(frame_index, viewport);
        }
        let result = launcher
            .last_save_game_result
            .as_ref()
            .expect("new save should complete after the Java-style loadfrag delay");
        assert_eq!(result.status, "created");
        assert_eq!(result.name, "Alpha Save");
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::SaveGame),
            "SaveDialog.addSetup should rebuild the save list after a new save instead of hiding the dialog"
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_load_save_route_autofocus_matches_java_desktop_only() {
        let mut desktop = DesktopLauncher::new(Vec::new());
        desktop.dispatch_menu_action(MenuButtonRole::LoadGame);
        assert!(
            desktop.load_game_search_focused,
            "Java LoadDialog.show focuses search only when Core.app.isDesktop()"
        );
        desktop.open_pause_overlay_route(super::DesktopMenuRoute::SaveGame);
        assert!(
            desktop.load_game_search_focused,
            "SaveDialog inherits the same desktop-only LoadDialog.show search focus"
        );

        let mut mobile = DesktopLauncher::new(Vec::new());
        mobile.menu_renderer_state.config.mobile = true;
        mobile.dispatch_menu_action(MenuButtonRole::LoadGame);
        assert!(
            !mobile.load_game_search_focused,
            "Java LoadDialog.show should not steal keyboard focus on mobile"
        );
        mobile.load_game_search_focused = true;
        mobile.open_pause_overlay_route(super::DesktopMenuRoute::SaveGame);
        assert!(
            !mobile.load_game_search_focused,
            "SaveDialog should preserve the same Core.app.isDesktop() guard on mobile"
        );
    }

