        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.save_dir = save_dir.display().to_string();

        launcher.dispatch_menu_action(MenuButtonRole::LoadGame);
        launcher.load_game_search = "Load Search".into();
        launcher.load_game_hidden_modes = vec![Gamemode::Sandbox];
        launcher.load_game_scroll_offset = 3;

        launcher.open_pause_overlay_route(super::DesktopMenuRoute::SaveGame);
        assert!(launcher.load_game_search.is_empty());
        assert!(launcher.load_game_hidden_modes.is_empty());
        assert_eq!(launcher.load_game_scroll_offset, 0);
