    #[test]
    fn desktop_launcher_language_options_match_upstream_vars_locales_like_java() {
        let raw_asset_codes = include_str!("../../core/assets/locales")
            .lines()
            .map(str::trim)
            .filter(|code| !code.is_empty())
            .collect::<Vec<_>>();
        let upstream_locale_codes = super::settings_language_codes_from_locales_asset_like_java(
            include_str!("../../core/assets/locales"),
        );
        let rust_locale_codes = super::settings_language_options_like_java()
            .iter()
            .map(|option| option.code.to_string())
            .collect::<Vec<_>>();

        assert_eq!(
            rust_locale_codes.len(),
            raw_asset_codes.len() + 1,
            "Java Vars.init exposes every raw core/assets/locales entry plus the synthetic router locale"
        );
        assert_eq!(rust_locale_codes.last().map(String::as_str), Some("router"));
        for code in raw_asset_codes {
            assert!(
                rust_locale_codes.iter().any(|rust_code| rust_code == code),
                "LanguageDialog production options should include locale code {code} from core/assets/locales"
            );
        }
        assert_eq!(
            rust_locale_codes, upstream_locale_codes,
            "Java Vars.init reads core/assets/locales, sorts them, then appends new Locale(\"router\") before LanguageDialog iterates Vars.locales"
        );
    }

    #[test]
    fn desktop_map_locales_display_name_uses_current_ui_locale_not_language_dialog_native_name() {
        assert_eq!(
            super::settings_language_display_name_for_code("fr"),
            "Français",
            "LanguageDialog keeps Java getDisplayName(locale) native names"
        );
        assert_eq!(
            super::map_locales_display_name_for_code("fr", "en"),
            "French",
            "MapLocalesDialog should use Locale.getDisplayName(Core.bundle.getLocale()) for the active English UI locale"
        );
        assert_eq!(
            super::map_locales_display_name_for_code("zh_CN", "en_US"),
            "Chinese (China)"
        );
        assert_eq!(
            super::map_locales_display_name_for_code("in_ID", "en"),
            "Indonesian (Indonesia)",
            "Java legacy Indonesian code should resolve through the id_ID locale alias"
        );
        assert_eq!(
            super::map_locales_display_name_for_code("zz_ZZ", "en"),
            "zz_ZZ",
            "Unknown locale codes should remain visible instead of falling back to an unrelated LanguageDialog row"
        );
    }

