    #[test]
    fn desktop_launcher_default_locale_prefers_system_locale_like_java() {
        assert_eq!(
            DesktopLauncher::settings_default_locale_code_from_sources(
                Some("zh-Hant-HK"),
                ["ja-JP", "en-US"]
            ),
            "zh_TW",
            "Java LanguageDialog.findClosestLocale starts from Locale.getDefault(), so system locale must beat LANG/LC_*"
        );
        assert_eq!(
            DesktopLauncher::settings_default_locale_code_from_sources(
                None::<&str>,
                ["pt-PT.UTF-8", "zh-CN"]
            ),
            "pt_PT",
            "LANG/LC_* remain a fallback only when no system Locale.getDefault() equivalent is available"
        );
        assert_eq!(
            DesktopLauncher::settings_default_locale_code_from_sources(
                Some(""),
                ["ja-JP", "en-US"]
            ),
            "ja_JP",
            "empty system locale probes should not mask the environment fallback"
        );
        assert_eq!(
            DesktopLauncher::settings_default_locale_code_from_sources(None::<&str>, ["", ""]),
            "en",
            "when both system and environment locale probes fail, Java fallback remains English"
        );
    }

    #[test]
    fn desktop_launcher_non_windows_system_locale_probe_uses_posix_locale_vars_like_java() {
        assert_eq!(
            super::desktop_system_default_locale_code_from_posix_environment([
                ("LANGUAGE", "fr_FR"),
                ("LANG", "ja_JP.UTF-8"),
            ])
            .as_deref(),
            Some("ja_JP.UTF-8"),
            "Java Locale.getDefault() on POSIX is driven by locale categories, not LANGUAGE"
        );
        assert_eq!(
            super::desktop_system_default_locale_code_from_posix_environment([
                ("LANG", "ja_JP.UTF-8"),
                ("LC_MESSAGES", "pt_PT.UTF-8"),
                ("LC_ALL", "zh_CN.UTF-8"),
            ])
            .as_deref(),
            Some("zh_CN.UTF-8"),
            "LC_ALL should win when emulating the POSIX source behind Java Locale.getDefault()"
        );
        assert_eq!(
            super::desktop_system_default_locale_code_from_posix_environment([
                ("LC_ALL", ""),
                ("LC_MESSAGES", "  "),
                ("LANGUAGE", "fr_FR"),
            ]),
            None,
            "LANGUAGE remains a fallback input, not the system Locale.getDefault() source"
        );
    }

    #[test]
    fn desktop_launcher_default_locale_environment_fallback_ignores_language_env_like_java() {
        assert_eq!(
            DesktopLauncher::settings_environment_default_locale_codes_from_environment([
                ("LANGUAGE", "fr_FR"),
                ("LANG", "ja_JP.UTF-8"),
            ]),
            vec!["ja_JP.UTF-8".to_string()],
            "Java Locale.getDefault() fallback follows locale categories; LANGUAGE must not override LANG"
        );
        assert_eq!(
            DesktopLauncher::settings_environment_default_locale_codes_from_environment([
                ("LANGUAGE", "fr_FR"),
                ("LC_MESSAGES", "pt_PT.UTF-8"),
                ("LANG", "ja_JP.UTF-8"),
            ]),
            vec!["pt_PT.UTF-8".to_string(), "ja_JP.UTF-8".to_string()],
            "fallback locale candidates should preserve Java-like LC_MESSAGES before LANG ordering"
        );
        assert_eq!(
            DesktopLauncher::settings_environment_default_locale_codes_from_environment([
                ("LANGUAGE", "fr_FR"),
                ("LC_ALL", ""),
                ("LC_MESSAGES", " "),
            ]),
            Vec::<String>::new(),
            "LANGUAGE alone is not a Java Locale.getDefault() source"
        );
    }

    #[test]
    fn desktop_launcher_settings_language_default_locale_materializes_like_java() {
        let expected = DesktopLauncher::settings_closest_locale_code("default");
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher
            .settings_overrides
            .insert("locale".into(), "default".into());
        launcher.last_settings_language_restart_message = None;
        launcher.last_menu_info_message = None;

        assert_eq!(
            launcher.selected_settings_language_locale_code_like_java(),
            expected,
            "pre-open selected locale may be computed, but Java still materializes default when LanguageDialog reads getLocale()"
        );
        launcher.dispatch_settings_action(super::DesktopSettingsAction::OpenLanguageDialog);

        assert_eq!(
            launcher
                .settings_overrides
                .get("locale")
                .map(String::as_str),
            Some(expected.as_str()),
            "LanguageDialog.getLocale() should replace the default sentinel with the closest actual locale"
        );
        assert_eq!(
            launcher.selected_settings_language_locale_code_like_java(),
            expected
        );
        assert_eq!(
            launcher.last_settings_language_restart_message, None,
            "materializing default locale is not a user language click and must not emit @language.restart"
        );
        assert_eq!(
            launcher.settings_child_dialog,
            Some(super::DesktopSettingsChildDialog::Language)
        );

        let mut missing = DesktopLauncher::new(Vec::new());
        missing.settings_overrides.remove("locale");
        missing.dispatch_settings_action(super::DesktopSettingsAction::OpenLanguageDialog);
        assert_eq!(
            missing.settings_overrides.get("locale").map(String::as_str),
            Some(expected.as_str()),
            "missing locale setting follows Core.settings default and should be materialized when opening LanguageDialog"
        );
    }

