    #[test]
    fn desktop_launcher_language_options_sort_like_java_case_insensitive_display_names() {
        assert_eq!(
            super::java_case_insensitive_order_cmp("English", "english"),
            std::cmp::Ordering::Equal,
            "Java String.CASE_INSENSITIVE_ORDER treats ASCII case-only differences as equal"
        );
        assert_eq!(
            super::java_case_insensitive_order_cmp("Bahasa Indonesia", "Català"),
            std::cmp::Ordering::Less
        );

        let options = super::settings_language_options_like_java();
        assert_eq!(
            options.last().map(|option| option.code),
            Some("router"),
            "Java Vars.init appends the synthetic router locale after sorting real locales"
        );
        for pair in options[..options.len().saturating_sub(1)].windows(2) {
            let [left, right] = pair else {
                continue;
            };
            assert!(
                super::java_case_insensitive_order_cmp(left.display_name, right.display_name)
                    != std::cmp::Ordering::Greater,
                "LanguageDialog options must stay sorted by display name using Java String.CASE_INSENSITIVE_ORDER: {} before {}",
                left.display_name,
                right.display_name
            );
        }
    }

