    #[test]
    fn desktop_launcher_language_dialog_uses_java_scrollpane_button_metrics() {
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = RenderViewport::new(0.0, 0.0, surface.width as f32, surface.height as f32);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let dialog = DesktopLauncher::settings_language_dialog_rect_for_panel(panel);
        let scrollpane = DesktopLauncher::settings_language_scrollpane_rect(dialog);
        let clip = DesktopLauncher::settings_language_list_clip_rect(dialog);
        let first = DesktopLauncher::settings_language_row_rect(dialog, 0);
        let second = DesktopLauncher::settings_language_row_rect(dialog, 1);

        assert_eq!(
            first.width,
            super::SETTINGS_LANGUAGE_LIST_WIDTH,
            "Java LanguageDialog creates each TextButton with size(400f, 50f)"
        );
        assert_eq!(first.height, super::SETTINGS_LANGUAGE_ROW_HEIGHT);
        assert_eq!(
            first.x,
            clip.x + super::SETTINGS_LANGUAGE_TABLE_MARGIN_HORIZONTAL,
            "Java langs table keeps marginLeft(24f) before the 400px language buttons"
        );
        assert_eq!(
            clip.width,
            super::SETTINGS_LANGUAGE_LIST_WIDTH
                + super::SETTINGS_LANGUAGE_TABLE_MARGIN_HORIZONTAL * 2.0,
            "ScrollPane content clip should include Java table left/right margins around the buttons"
        );
        assert_eq!(
            scrollpane.width,
            clip.width + super::SETTINGS_LANGUAGE_SCROLLBAR_WIDTH,
            "ScrollPane should reserve chrome width for its vertical scrollbar"
        );
        assert_eq!(
            first.y - second.y,
            super::SETTINGS_LANGUAGE_ROW_HEIGHT + super::SETTINGS_LANGUAGE_ROW_GAP
        );
        assert!(
            DesktopLauncher::settings_language_visible_rows_for_dialog(dialog) > 7,
            "LanguageDialog should derive its ScrollPane height from the BaseDialog content area instead of the older fixed seven-row Rust cap"
        );
    }

    fn settings_menu_draw_texts_for_surface(
        launcher: &mut DesktopLauncher,
        surface: DesktopSurfaceSize,
        frame_index: u64,
    ) -> Vec<(String, RenderFontId, bool, RenderPoint)> {
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(frame_index, viewport);
        frame
            .bundle
            .render_frame
            .as_ref()
            .expect("settings menu should contain a render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText {
                    text,
                    style,
                    position,
                    ..
                } => Some((text.clone(), style.font, style.outline, *position)),
                _ => None,
            })
            .collect()
    }

    #[test]
    fn desktop_launcher_language_dialog_keeps_400x50_rows_and_margin_24_stable_across_window_sizes_and_avoids_page_number_text(
    ) {
        for surface in [
            DesktopSurfaceSize::new(1280, 720),
            DesktopSurfaceSize::new(1920, 1080),
        ] {
            let mut launcher = DesktopLauncher::new(Vec::new());
            launcher.settings_locale = "en".into();
            launcher.player_locale = "en".into();
            launcher.dispatch_menu_action(MenuButtonRole::Settings);
            launcher.dispatch_menu_route_shell_action(
                super::DesktopMenuRouteShellAction::Settings(
                    super::DesktopSettingsAction::OpenLanguageDialog,
                ),
            );

            let viewport = launcher.default_render_viewport_for_surface(surface);
            let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
                viewport,
                super::DesktopMenuRoute::Settings,
            );
            let dialog = DesktopLauncher::settings_language_dialog_rect_for_panel(panel);
            let clip = DesktopLauncher::settings_language_list_clip_rect(dialog);
            let row = DesktopLauncher::settings_language_row_rect(dialog, 0);
            let visible_rows = DesktopLauncher::settings_language_visible_rows_for_dialog(dialog);
            launcher.settings_language_scroll_offset = super::settings_language_options_like_java()
                .len()
                .saturating_sub(visible_rows);

            assert_eq!(
                row.width,
                super::SETTINGS_LANGUAGE_LIST_WIDTH,
                "Java LanguageDialog keeps each locale row at 400px wide regardless of window size"
            );
            assert_eq!(
                row.height,
                super::SETTINGS_LANGUAGE_ROW_HEIGHT,
                "Java LanguageDialog keeps each locale row at 50px tall regardless of window size"
            );
            assert_eq!(
                row.x,
                clip.x + super::SETTINGS_LANGUAGE_TABLE_MARGIN_HORIZONTAL,
                "Java LanguageDialog keeps the 24px left margin before the 400px locale buttons"
            );

            let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
            let commands = frame
                .bundle
                .render_frame
                .as_ref()
                .expect("language dialog frame should contain render frame")
                .passes
                .iter()
                .flat_map(|pass| pass.commands.iter())
                .collect::<Vec<_>>();
            let language_options = super::settings_language_options_like_java();
            assert!(
                commands.into_iter().any(
                    |command| matches!(command, RenderCommand::SetClip { rect } if rect == &clip)
                ),
                "Java LanguageDialog must keep the locale list inside the scroll clip when the window changes"
            );
            assert!(
                frame
                    .bundle
                    .render_frame
                    .as_ref()
                    .expect("language dialog frame should contain render frame")
                    .passes
                    .iter()
                    .flat_map(|pass| pass.commands.iter())
                    .any(|command| matches!(command, RenderCommand::ClearClip)),
                "Java LanguageDialog must clear its list clip after rendering the locale rows"
            );

            let clipped_texts = settings_menu_draw_texts_for_surface(&mut launcher, surface, 0)
                .into_iter()
                .filter(|(_, _, _, position)| clip.contains_point(*position))
                .map(|(text, _, _, _)| text)
                .collect::<Vec<_>>();
            assert!(
                !clipped_texts.is_empty(),
                "Java LanguageDialog should still render locale labels inside the clipped list area"
            );
            assert!(
                clipped_texts.iter().all(|text| language_options
                    .iter()
                    .any(|option| text.as_str() == option.display_name)),
                "Java LanguageDialog clipped texts should stay on locale labels only: {:?}",
                clipped_texts
            );
            assert!(
                !clipped_texts.iter().any(|text| {
                    let text = text.trim();
                    text.to_ascii_lowercase().contains("page")
                        || text.split_once('/').is_some_and(|(left, right)| {
                            !left.is_empty()
                                && !right.is_empty()
                                && left.chars().all(|ch| ch.is_ascii_digit())
                                && right.chars().all(|ch| ch.is_ascii_digit())
                        })
                }),
                "Java LanguageDialog should not draw page-number style text inside the locale list"
            );
        }
    }

    #[test]
    fn desktop_settings_language_dialog_preserves_scroll_offset_between_openings_like_java() {
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = RenderViewport::new(0.0, 0.0, surface.width as f32, surface.height as f32);
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenLanguageDialog,
        ));

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let dialog = DesktopLauncher::settings_language_dialog_rect_for_panel(panel);
        let visible_rows = DesktopLauncher::settings_language_visible_rows_for_dialog(dialog);
        let language_options = super::settings_language_options_like_java();
        let max_offset = language_options.len().saturating_sub(visible_rows);
        let preserved_offset = max_offset.min(4).max(1);
        launcher.settings_language_scroll_offset = preserved_offset;

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::CloseChildDialog,
        ));
        assert_eq!(launcher.settings_child_dialog, None);
        assert_eq!(
            launcher.settings_language_scroll_offset, preserved_offset,
            "Java UI.language is a persistent LanguageDialog; closing it should not reset ScrollPane position"
        );

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenDataDialog,
        ));
        assert_eq!(
            launcher.settings_language_scroll_offset, preserved_offset,
            "Opening another Settings child dialog should not erase the LanguageDialog ScrollPane state"
        );
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::CloseChildDialog,
        ));
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenLanguageDialog,
        ));
        assert_eq!(
            launcher.settings_language_scroll_offset, preserved_offset,
            "Reopening LanguageDialog should keep the previous locale list offset like Java's singleton dialog"
        );

        let first_row = DesktopLauncher::settings_language_row_rect(dialog, 0);
        let expected_first_visible = language_options[preserved_offset].display_name;
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let first_row_texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("language dialog should render after reopening")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, position, .. }
                    if first_row.contains_point(*position) =>
                {
                    Some(text.as_str())
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            first_row_texts.contains(&expected_first_visible),
            "LanguageDialog should render from preserved offset {preserved_offset}: first row texts={first_row_texts:?}"
        );
    }

    #[test]
    fn desktop_launcher_language_dialog_renders_every_display_name_with_default_font() {
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = RenderViewport::new(0.0, 0.0, surface.width as f32, surface.height as f32);
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenLanguageDialog,
        ));
        let language_options = super::settings_language_options_like_java();
        let atlas = super::desktop_default_real_font_atlas_for_locale(&launcher.font_locale)
            .expect("LanguageDialog should render through the real default font atlas");
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let dialog = DesktopLauncher::settings_language_dialog_rect_for_panel(panel);
        let visible_rows = DesktopLauncher::settings_language_visible_rows_for_dialog(dialog);
        let max_offset = language_options.len().saturating_sub(visible_rows);

        for (index, option) in language_options.iter().enumerate() {
            launcher.settings_language_scroll_offset =
                index.saturating_sub(visible_rows - 1).min(max_offset);
            let frame = launcher.menu_graphics_frame_for_surface(index as u64, viewport);
            let command = frame
                .bundle
                .render_frame
                .as_ref()
                .expect("language dialog should render")
                .passes
                .iter()
                .flat_map(|pass| pass.commands.iter())
                .find_map(|command| match command {
                    RenderCommand::DrawText {
                        text, size, style, ..
                    } if text == option.display_name => Some((*size, *style)),
                    _ => None,
                })
                .unwrap_or_else(|| {
                    panic!(
                        "LanguageDialog visible ScrollPane should draw locale {} as '{}'",
                        option.code, option.display_name
                    )
                });
            assert_eq!(
                command.1.font,
                RenderFontId::Default,
                "LanguageDialog TextButton labels use the default UI font"
            );
            assert_eq!(
                command.0,
                DesktopLauncher::settings_text_button_font_size("flatTogglet"),
                "LanguageDialog language buttons should use the same readable UI label size as other Settings buttons"
            );
            for character in option
                .display_name
                .chars()
                .filter(|character| !character.is_ascii() && !character.is_control())
            {
                let key = super::DesktopRealFontGlyphKey::new(RenderFontId::Default, character)
                    .expect("LanguageDialog display glyph key should exist");
                assert!(
                    atlas.glyphs.contains_key(&key),
                    "visible LanguageDialog locale {} glyph U+{:04X} '{}' must be present in the real Default font atlas",
                    option.code,
                    character as u32,
                    character
                );
            }
        }
    }

    #[test]
    fn desktop_launcher_language_dialog_display_names_reach_real_opengl_glyph_quads_like_java() {
        for font_locale in ["en", "ja"] {
            let atlas = super::desktop_default_real_font_atlas_for_locale(font_locale)
                .unwrap_or_else(|| panic!("{font_locale} should build a real font atlas"));
            for option in super::settings_language_options_like_java() {
                let label = super::settings_language_display_name_for_code(option.code);
                let quads = super::opengl_backend_primitive_quads_from_action_for_locale(
                    &super::DesktopGraphicsOpenGlBackendAdapterAction::DrawText {
                        text: label.clone(),
                        position: RenderPoint::new(0.0, 0.0),
                        color: [1.0, 1.0, 1.0, 1.0],
                        size: DesktopLauncher::settings_text_button_font_size("flatTogglet"),
                        rotation: 0.0,
                        align: RenderTextAlign::Center,
                        style: RenderTextStyle::default(),
                        layer: Layer::OVERLAY_UI,
                    },
                    Some(RenderTarget::Screen),
                    super::opengl_backend_default_sprite_shader_program(),
                    super::DesktopGraphicsOpenGlBackendBlendState::default(),
                    None,
                    font_locale,
                );
                assert!(
                    !quads.is_empty(),
                    "LanguageDialog label for locale {} should produce OpenGL font quads",
                    option.code
                );
                assert!(
                    quads.iter().all(|quad| quad.texture_identity.key
                        == super::DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY),
                    "LanguageDialog label '{}' should render from the real font atlas in locale {}, never the primitive placeholder texture",
                    label,
                    font_locale
                );
                assert!(
                    quads.iter().all(|quad| quad.symbol != "primitive:DrawText"),
                    "LanguageDialog label '{}' should not fall back to primitive DrawText in locale {}",
                    label,
                    font_locale
                );
                for character in label
                    .chars()
                    .filter(|character| !character.is_whitespace() && !character.is_control())
                {
                    let key = super::DesktopRealFontGlyphKey::new(RenderFontId::Default, character)
                        .expect("LanguageDialog display glyph key should exist");
                    assert!(
                        atlas.glyphs.contains_key(&key),
                        "LanguageDialog label '{}' for locale {} must preseed glyph U+{:04X} '{}' in font locale {}",
                        label,
                        option.code,
                        character as u32,
                        character,
                        font_locale
                    );
                    let exact_symbol = format!("font:Default:DrawText:U+{:04X}", character as u32);
                    assert!(
                        quads.iter().any(|quad| quad.symbol == exact_symbol),
                        "LanguageDialog label '{}' for locale {} must emit exact glyph quad {} in font locale {}, not a Java Fonts.getGlyph fallback",
                        label,
                        option.code,
                        exact_symbol,
                        font_locale
                    );
                }
            }
        }
    }

    #[test]
    fn desktop_launcher_language_dialog_visible_rows_reach_real_opengl_quads_like_java() {
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = RenderViewport::new(0.0, 0.0, surface.width as f32, surface.height as f32);
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.font_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenLanguageDialog,
        ));

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let dialog = DesktopLauncher::settings_language_dialog_rect_for_panel(panel);
        let visible_rows = DesktopLauncher::settings_language_visible_rows_for_dialog(dialog);
        let language_options = super::settings_language_options_like_java();
        let max_offset = language_options.len().saturating_sub(visible_rows);

        for target_code in ["th", "ko", "uk_UA", "router"] {
            let option_index = language_options
                .iter()
                .position(|option| option.code == target_code)
                .unwrap_or_else(|| panic!("LanguageDialog should include locale {target_code}"));
            let option = &language_options[option_index];
            launcher.settings_language_scroll_offset = option_index
                .saturating_sub(visible_rows - 1)
                .min(max_offset);

            let frame = launcher.menu_graphics_frame_for_surface(option_index as u64, viewport);
            let render_frame = frame
                .bundle
                .render_frame
                .as_ref()
                .expect("LanguageDialog frame should contain render commands");
            let visible_texts = render_frame
                .passes
                .iter()
                .flat_map(|pass| pass.commands.iter())
                .filter_map(|command| match command {
                    RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert!(
                visible_texts.contains(&option.display_name),
                "LanguageDialog final frame should draw locale {} as '{}'",
                option.code,
                option.display_name
            );

            let plan = DesktopGraphicsOpenGlBackendFramePlan::from_frame(&frame);
            let mut executor = DesktopGraphicsOpenGlBackendExecutor::default();
            plan.drive_step_sink(&mut executor);

            for character in option
                .display_name
                .chars()
                .filter(|character| !character.is_whitespace() && !character.is_control())
            {
                let expected_symbol = format!("font:Default:DrawText:U+{:04X}", character as u32);
                assert!(
                    executor.state.sprite_quads.iter().any(|quad| {
                        quad.symbol == expected_symbol
                            && quad.texture_identity.key == DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY
                    }),
                    "LanguageDialog locale {} glyph U+{:04X} '{}' must reach the real OpenGL font atlas from the final menu frame",
                    option.code,
                    character as u32,
                    character
                );
            }
            assert!(
                executor
                    .state
                    .sprite_quads
                    .iter()
                    .all(|quad| quad.symbol != "primitive:DrawText"),
                "LanguageDialog locale {} should not fall back to primitive DrawText quads in the final menu frame",
                option.code
            );
        }
    }

    #[test]
    fn desktop_launcher_language_dialog_scrolls_by_subrow_pixels_like_java_scrollpane() {
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = RenderViewport::new(0.0, 0.0, surface.width as f32, surface.height as f32);
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenLanguageDialog,
        ));

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let dialog = DesktopLauncher::settings_language_dialog_rect_for_panel(panel);
        let first_row = DesktopLauncher::settings_language_row_rect(dialog, 0);
        let first_option = &super::settings_language_options_like_java()[0];

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: dialog.center().x,
                    y: dialog.center().y,
                },
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -0.5,
                },
            ],
        );

        assert_eq!(
            launcher.settings_language_scroll_offset, 0,
            "half-wheel movement should not immediately replace the first visible LanguageDialog row"
        );
        assert_eq!(
            launcher.settings_language_scroll_subrow_offset,
            super::SETTINGS_LANGUAGE_ROW_HEIGHT * 0.5,
            "Java Scene2D ScrollPane scrolls continuously in pixels, so half a row should be preserved visually"
        );
        let shifted_first = DesktopLauncher::settings_language_row_rect_with_subrow_offset(
            dialog,
            0,
            launcher.settings_language_scroll_subrow_offset,
        );
        assert_eq!(
            shifted_first.y,
            first_row.y - super::SETTINGS_LANGUAGE_ROW_HEIGHT * 0.5
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let first_text_position = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("language dialog frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .find_map(|command| match command {
                RenderCommand::DrawText { text, position, .. }
                    if text == first_option.display_name =>
                {
                    Some(*position)
                }
                _ => None,
            })
            .expect("first visible language row should still render after half-row scroll");
        assert_eq!(
            first_text_position,
            shifted_first.center(),
            "LanguageDialog text should move by the same pixel offset as the row background"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                shifted_first.center().x,
                shifted_first.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::Settings(
                super::DesktopSettingsAction::SelectLanguage(first_option.code)
            )),
            "LanguageDialog hit-test must follow the half-row ScrollPane offset"
        );
    }

    #[test]
    fn desktop_launcher_language_dialog_scrollpane_clip_blocks_hidden_subrow_hit_and_hover_like_java(
    ) {
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = RenderViewport::new(0.0, 0.0, surface.width as f32, surface.height as f32);
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenLanguageDialog,
        ));

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let dialog = DesktopLauncher::settings_language_dialog_rect_for_panel(panel);
        let list_clip = DesktopLauncher::settings_language_list_clip_rect(dialog);
        let visible_rows = DesktopLauncher::settings_language_visible_rows_for_dialog(dialog);
        let language_options = super::settings_language_options_like_java();
        assert!(
            language_options.len() > visible_rows,
            "LanguageDialog test needs one ScrollPane-clipped overflow row"
        );

        launcher.settings_language_scroll_offset = 0;
        launcher.settings_language_scroll_subrow_offset = super::SETTINGS_LANGUAGE_ROW_HEIGHT * 0.5;
        let hidden_row = DesktopLauncher::settings_language_row_rect_with_subrow_offset(
            dialog,
            visible_rows,
            launcher.settings_language_scroll_subrow_offset,
        );
        let hidden_point = hidden_row.center();
        assert!(hidden_row.contains_point(hidden_point));
        assert!(
            !list_clip.contains_point(hidden_point),
            "the extra rendered row should sit outside the Java ScrollPane viewport and be clipped"
        );

        let hidden_option = &language_options[visible_rows];
        let hit = launcher.active_menu_route_shell_action_at_surface_point(
            surface,
            hidden_point.x,
            hidden_point.y,
        );
        assert!(
            !matches!(
                hit,
                Some(super::DesktopMenuRouteShellAction::Settings(
                    super::DesktopSettingsAction::SelectLanguage(code)
                )) if code == hidden_option.code
            ),
            "Java ScrollPane should not let a clipped-out LanguageDialog row receive clicks"
        );

        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: hidden_point.x,
                y: hidden_point.y,
            }],
        );
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("language dialog frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let selected =
            launcher.selected_settings_language_locale_code_like_java() == hidden_option.code;
        let (normal_symbol, normal_tint) =
            DesktopLauncher::settings_text_button_symbol_and_tint_checked(
                "flatTogglet",
                false,
                false,
                selected,
                true,
                1.0,
            );
        let (hover_symbol, hover_tint) =
            DesktopLauncher::settings_text_button_symbol_and_tint_checked(
                "flatTogglet",
                true,
                false,
                selected,
                true,
                1.0,
            );
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, tint, .. }
                    if symbol == &normal_symbol && *rect == hidden_row && *tint == normal_tint
            )),
            "clipped-out LanguageDialog row should keep its non-hover Styles.flatTogglet state"
        );
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, tint, .. }
                    if symbol == &hover_symbol && *rect == hidden_row && *tint == hover_tint
            )),
            "cursor outside the Java ScrollPane viewport must not hover the clipped-out language row"
        );
    }

