    #[test]
    fn desktop_opengl_outline_font_uses_prebaked_glyph_not_runtime_outline_pass_like_java() {
        let quads = super::opengl_backend_primitive_quads_from_action(
            &super::DesktopGraphicsOpenGlBackendAdapterAction::DrawText {
                text: "OK".into(),
                position: RenderPoint::new(0.0, 0.0),
                color: [1.0, 1.0, 1.0, 1.0],
                size: DesktopLauncher::settings_label_style_font_size("outlineLabel"),
                rotation: 0.0,
                align: RenderTextAlign::Center,
                style: RenderTextStyle::default().with_font(RenderFontId::Outline),
                layer: Layer::OVERLAY_UI,
            },
            Some(RenderTarget::Screen),
            super::opengl_backend_default_sprite_shader_program(),
            super::DesktopGraphicsOpenGlBackendBlendState::default(),
            None,
        );
        let font_quads = quads
            .iter()
            .filter(|quad| quad.texture_identity.key == DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY)
            .collect::<Vec<_>>();

        assert_eq!(
            font_quads.len(),
            2,
            "Java Fonts.outline is a prebaked FreeType border font; drawing two characters must not emit shadow + 8-direction runtime outline duplicates"
        );
        for character in ['O', 'K'] {
            let expected_symbol = format!("font:Outline:DrawText:U+{:04X}", character as u32);
            assert_eq!(
                font_quads
                    .iter()
                    .filter(|quad| quad.symbol == expected_symbol)
                    .count(),
                1,
                "prebaked outline glyph '{}' should appear exactly once",
                character
            );
        }
        assert!(
            quads.iter().all(|quad| quad.symbol != "primitive:DrawText"),
            "prebaked outline text should still render from the real font atlas"
        );
    }

