    #[test]
    fn desktop_launcher_ru_tr_planet_data_settings_labels_are_localized() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let keys = [
            "settings.clearplanetdata",
            "settings.planetselect",
            "settings.clearplanetresearch",
            "settings.clearplanetresearch.confirm",
            "settings.clearplanetcampaignsaves",
            "settings.clearplanetcampaignsaves.confirm",
        ];
        let english_values = [
            "Clear Planet Data",
            "Planet: {0}",
            "Clear Planet Research",
            "Are you sure you want to clear {0}'s research?",
            "Clear Planet Campaign Saves",
            "Are you sure you want to clear {0}'s campaign saves?",
        ];

        for locale in ["ru", "tr"] {
            launcher.settings_locale = locale.into();
            for (key, english) in keys.iter().zip(english_values) {
                let localized = launcher.localize_bundle_markup_text(format!("@{key}"));
                assert_ne!(
                    localized, english,
                    "{locale} {key} should not fall back to the English upstream placeholder"
                );
                assert!(
                    !localized.starts_with('@'),
                    "{locale} {key} should resolve through the locale bundle"
                );
                if english.contains("{0}") {
                    assert!(
                        localized.contains("{0}"),
                        "{locale} {key} must preserve the Java MessageFormat placeholder"
                    );
                }
            }
        }
    }

    #[test]
    fn desktop_graphics_font_seed_covers_planet_data_locale_strings_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let keys = [
            "settings.clearplanetdata",
            "settings.planetselect",
            "settings.clearplanetresearch",
            "settings.clearplanetresearch.confirm",
            "settings.clearplanetcampaignsaves",
            "settings.clearplanetcampaignsaves.confirm",
        ];
        let seed = super::desktop_real_font_atlas_seed_characters();

        for locale in ["ru", "tr"] {
            launcher.settings_locale = locale.into();
            let atlas = super::desktop_default_real_font_atlas_for_locale(locale)
                .unwrap_or_else(|| panic!("{locale} should build the real Default font atlas"));

            for key in keys {
                let text = launcher.localize_bundle_markup_text(format!("@{key}"));
                assert!(
                    !text.starts_with('@'),
                    "{locale} {key} should resolve before the font seed/OpenGL path is checked"
                );

                let quads = super::opengl_backend_primitive_quads_from_action_for_locale(
                    &super::DesktopGraphicsOpenGlBackendAdapterAction::DrawText {
                        text: text.clone(),
                        position: RenderPoint::new(0.0, 0.0),
                        color: [1.0, 1.0, 1.0, 1.0],
                        size: DesktopLauncher::settings_text_button_font_size("flatt"),
                        rotation: 0.0,
                        align: RenderTextAlign::Center,
                        style: RenderTextStyle::default(),
                        layer: Layer::OVERLAY_UI,
                    },
                    Some(RenderTarget::Screen),
                    super::opengl_backend_default_sprite_shader_program(),
                    super::DesktopGraphicsOpenGlBackendBlendState::default(),
                    None,
                    locale,
                );

                assert!(
                    !quads.is_empty(),
                    "{locale} {key} should emit OpenGL glyph quads for '{text}'"
                );
                assert!(
                    quads.iter().all(|quad| quad.texture_identity.key
                        == super::DESKTOP_FONT_GLYPH_ATLAS_TEXTURE_KEY),
                    "{locale} {key} should render from the real font atlas, never the primitive placeholder"
                );
                assert!(
                    quads.iter().all(|quad| quad.symbol != "primitive:DrawText"),
                    "{locale} {key} should not fall back to primitive DrawText"
                );

                for character in text
                    .chars()
                    .filter(|character| !character.is_whitespace() && !character.is_control())
                {
                    assert!(
                        seed.contains(&character),
                        "{locale} {key} font seed must include U+{:04X} '{}' from '{}'",
                        character as u32,
                        character,
                        text
                    );
                    let glyph_key =
                        super::DesktopRealFontGlyphKey::new(RenderFontId::Default, character)
                            .expect("planet data locale glyph key should exist");
                    assert!(
                        atlas.glyphs.contains_key(&glyph_key),
                        "{locale} Default atlas must include U+{:04X} '{}' from '{}'",
                        character as u32,
                        character,
                        text
                    );
                    let exact_symbol = format!("font:Default:DrawText:U+{:04X}", character as u32);
                    assert!(
                        quads.iter().any(|quad| quad.symbol == exact_symbol),
                        "{locale} {key} must emit exact glyph quad {exact_symbol} for '{}'",
                        text
                    );
                }
            }
        }
    }

