    #[test]
    fn desktop_bundle_properties_parser_handles_java_escape_semantics() {
        let parsed = super::desktop_parse_bundle_properties_source(concat!(
            "\u{feff}bom = stripped\n",
            "# comment\n",
            "! comment\n",
            "plain = hello\n",
            "unicode = \\u4E2D\\u6587\n",
            "emoji = \\uD83D\\uDE80\n",
            "continued = line1 \\\n",
            "    line2\n",
            "key\\:name = colon key\n",
            "key\\=name: equals key\n",
            "space\\ key spaced\\ value\n",
            "escaped = hello\\ world\\:x\\=y\n",
            "tab = left\\tright\n",
            "no_separator\n",
        ));

        assert_eq!(parsed.get("bom").map(String::as_str), Some("stripped"));
        assert_eq!(parsed.get("plain").map(String::as_str), Some("hello"));
        assert_eq!(
            parsed.get("unicode").map(String::as_str),
            Some("\u{4e2d}\u{6587}"),
            "Java PropertiesUtils.load decodes unicode escapes before UI text/font seeding"
        );
        assert_eq!(
            parsed.get("emoji").map(String::as_str),
            Some("🚀"),
            "Java properties surrogate pairs must decode to one scalar so UI text and font seed do not show replacement glyphs"
        );
        assert_eq!(
            parsed.get("continued").map(String::as_str),
            Some("line1 line2"),
            "Java properties consume the continuation backslash and trim leading whitespace on the next physical line"
        );
        assert_eq!(
            parsed.get("key:name").map(String::as_str),
            Some("colon key")
        );
        assert_eq!(
            parsed.get("key=name").map(String::as_str),
            Some("equals key")
        );
        assert_eq!(
            parsed.get("space key").map(String::as_str),
            Some("spaced value")
        );
        assert_eq!(
            parsed.get("escaped").map(String::as_str),
            Some("hello world:x=y")
        );
        assert_eq!(parsed.get("tab").map(String::as_str), Some("left\tright"));
        assert_eq!(parsed.get("no_separator").map(String::as_str), Some(""));
    }

    #[test]
    fn desktop_launcher_loads_external_bundle_before_internal_locale_like_java() {
        let root = std::env::temp_dir().join(format!(
            "mindustry-desktop-external-bundle-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).expect("external bundle fixture dir should be writable");
        std::fs::write(
            root.join("bundle"),
            "play = External Play\nsettings = External Settings\nsector.origin.credit = External Credit\nserver.versions = C:{0}|S:{1}\nbundle.external = External bundle loaded [accent]{0}\nexternal.seed = 外部彧語\n",
        )
        .expect("external bundle fixture should be writable");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.data_dir = root.display().to_string();
        launcher.settings_locale = "ja".into();

        assert_eq!(
            launcher.localize_bundle_markup_text("@play"),
            "External Play",
            "Java Vars.loadSettings tries Core.files.local(\"bundle\") before the internal locale bundle"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@settings"),
            "External Settings"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@sector.origin.credit"),
            "Mechanical Fishe",
            "Java merges global.properties after external bundle loading, so globals still override external translations"
        );
        assert_eq!(
            launcher.format_bundle_text("server.versions", &["158", "157"]),
            "C:158|S:157",
            "formatting should use the external bundle value before internal locale fallback"
        );
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let external_bundle_path = root.join("bundle").display().to_string();
        let external_notice = format!("External bundle loaded [accent]{external_bundle_path}");
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("external bundle notice frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            launcher.last_menu_info_message.as_deref(),
            Some(external_notice.as_str()),
            "Java Vars.loadSettings shows bundle.external after loading Core.files.local(\"bundle\")"
        );
        assert!(texts.contains(&external_notice.as_str()));
        let external_seed = super::desktop_external_font_seed_characters();
        let full_seed = super::desktop_real_font_atlas_seed_characters();
        for character in "外部彧語".chars() {
            assert!(
                external_seed.contains(&character),
                "external bundle values should enter the external font seed before atlas upload"
            );
            assert!(
                full_seed.contains(&character),
                "external bundle values should be merged into the default font atlas seed"
            );
        }
        launcher.last_menu_info_message = None;
        let frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("second external bundle notice frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            launcher.last_menu_info_message, None,
            "external bundle loaded notice should not be re-created every menu frame"
        );
        assert!(!texts.contains(&external_notice.as_str()));

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_caches_external_bundle_family_between_stable_frames_and_invalidates_on_change(
    ) {
        let root = std::env::temp_dir().join(format!(
            "mindustry-desktop-external-bundle-cache-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).expect("external bundle cache dir should be writable");
        let bundle_path = root.join("bundle");
        std::fs::write(
            &bundle_path,
            "play = Cached Play\nsettings = Cached Settings\nbundle.external = Cached bundle [accent]{0}\n",
        )
        .expect("cached external bundle should be writable");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.data_dir = root.display().to_string();
        launcher.settings_locale = "en".into();

        assert_eq!(launcher.external_bundle_cache_rebuilds(), 0);
        assert_eq!(launcher.localize_bundle_markup_text("@play"), "Cached Play");
        assert_eq!(launcher.external_bundle_cache_rebuilds(), 1);
        assert_eq!(
            launcher.localize_bundle_markup_text("@settings"),
            "Cached Settings"
        );
        assert_eq!(
            launcher.external_bundle_cache_rebuilds(),
            1,
            "repeated key lookups in one stable bundle family must reuse parsed external values"
        );

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let _first = launcher.menu_graphics_frame_for_surface(0, viewport);
        let after_first_frame = launcher.external_bundle_cache_rebuilds();
        let _second = launcher.menu_graphics_frame_for_surface(1, viewport);
        assert_eq!(
            launcher.external_bundle_cache_rebuilds(),
            after_first_frame,
            "stable menu frames must not re-read the external bundle family"
        );

        std::fs::write(
            &bundle_path,
            "play = Cached Play Updated\nsettings = Cached Settings\nbundle.external = Cached bundle [accent]{0}\n",
        )
        .expect("updated cached external bundle should be writable");
        assert_eq!(
            launcher.localize_bundle_markup_text("@play"),
            "Cached Play Updated"
        );
        assert_eq!(
            launcher.external_bundle_cache_rebuilds(),
            after_first_frame + 1,
            "changing the bundle file must invalidate the cached parsed values"
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_validates_external_bundle_family_once_per_menu_frame() {
        let root = std::env::temp_dir().join(format!(
            "mindustry-desktop-external-bundle-frame-cache-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).expect("external bundle frame cache dir should be writable");
        std::fs::write(
            root.join("bundle"),
            "play = Frame Play\nsettings = Frame Settings\nquit = Frame Quit\nbundle.external = Frame bundle [accent]{0}\n",
        )
        .expect("external bundle frame fixture should be writable");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.data_dir = root.display().to_string();
        launcher.settings_locale = "en".into();

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        assert_eq!(launcher.external_bundle_cache_validations(), 0);

        let _first = launcher.menu_graphics_frame_for_surface(0, viewport);
        assert_eq!(
            launcher.external_bundle_cache_validations(),
            1,
            "one menu frame localizes many labels, but the external bundle family should hit filesystem validation once"
        );
        assert_eq!(
            launcher.external_bundle_cache_rebuilds(),
            1,
            "first menu frame still loads the Java-style external bundle family"
        );

        let _second = launcher.menu_graphics_frame_for_surface(1, viewport);
        assert_eq!(
            launcher.external_bundle_cache_validations(),
            2,
            "a new frame may revalidate for hot-reload semantics, but repeated key lookups inside that frame must reuse the validation"
        );
        assert_eq!(
            launcher.external_bundle_cache_rebuilds(),
            1,
            "unchanged external bundle family should not be reparsed on stable frames"
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_loads_external_bundle_properties_family_like_java_vars_load_settings() {
        let root = std::env::temp_dir().join(format!(
            "mindustry-desktop-external-bundle-family-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).expect("external bundle family dir should be writable");
        std::fs::write(
            root.join("bundle"),
            "play = Legacy Play\nsettings = Legacy Settings\nexternal.seed = 遗留彧\n",
        )
        .expect("legacy external bundle should be writable");
        std::fs::write(
            root.join("bundle.properties"),
            "play = Root Play\nsettings = Root Settings\nbundle.external = Root external bundle [accent]{0}\nexternal.seed = 根部語\n",
        )
        .expect("root external bundle should be writable");
        std::fs::write(
            root.join("bundle_en.properties"),
            "play = English Play\nserver.versions = E:{0}/{1}\nexternal.seed = 英语鸮\n",
        )
        .expect("English external bundle should be writable");
        std::fs::write(
            root.join("bundle_zh.properties"),
            "play = Chinese Play\nsettings = Chinese Settings\nexternal.seed = 中文鸮\n",
        )
        .expect("Chinese external bundle should be writable");
        std::fs::write(
            root.join("bundle_zh_CN.properties"),
            "play = Simplified Play\nserver.versions = ZH:{0}/{1}\nexternal.seed = 简体鸮\n",
        )
        .expect("Simplified Chinese external bundle should be writable");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.data_dir = root.display().to_string();
        launcher.settings_locale = "zh_CN".into();

        assert_eq!(
            launcher.localize_bundle_markup_text("@play"),
            "English Play",
            "Java Vars.loadSettings creates external bundles with Locale.ENGLISH, so bundle_en.properties overrides bundle.properties even when settings_locale is zh_CN"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@settings"),
            "Root Settings",
            "bundle_zh.properties is ignored for external bundles because Java forces Locale.ENGLISH at Core.files.local(\"bundle\")"
        );
        assert_eq!(
            launcher.format_bundle_text("server.versions", &["158", "157"]),
            "E:158/157"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@database"),
            "@database",
            "once an external bundle family exists, missing keys should not fall back into the internal locale bundle"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@sector.origin.credit"),
            "Mechanical Fishe",
            "global.properties is still merged after external bundle loading"
        );

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let external_bundle_path = root.join("bundle").display().to_string();
        let external_notice = format!("Root external bundle [accent]{external_bundle_path}");
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("external bundle family notice frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            launcher.last_menu_info_message.as_deref(),
            Some(external_notice.as_str()),
            "Java Vars.loadSettings formats bundle.external with the base handle path, not a concrete .properties file"
        );
        assert!(texts.contains(&external_notice.as_str()));
        let external_seed = super::desktop_external_font_seed_characters();
        for character in "遗留彧根部語英语鸮".chars() {
            assert!(
                external_seed.contains(&character),
                "Java external bundle loading uses the English family, so bare/root/en values should enter the font seed"
            );
        }

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_merges_mod_bundle_properties_into_active_bundle_like_java() {
        let root = temp_desktop_path("mod-bundle-overlay");
        let alpha = root.join("alpha");
        let beta = root.join("beta");
        std::fs::create_dir_all(alpha.join("bundles"))
            .expect("alpha bundle fixture dir should be writable");
        std::fs::create_dir_all(beta.join("bundles"))
            .expect("beta bundle fixture dir should be writable");
        std::fs::write(
            alpha.join("bundles/bundle.properties"),
            "play = Alpha Root\nmod.root = Alpha Root Only\nserver.versions = Alpha Root {0}/{1}\n",
        )
        .expect("alpha root bundle should write");
        std::fs::write(
            alpha.join("bundles/bundle_zh.properties"),
            "settings = Alpha Language Settings\nplay = Alpha Language\n",
        )
        .expect("alpha language bundle should write");
        std::fs::write(
            alpha.join("bundles/bundle_zh_CN.properties"),
            "play = Alpha Exact\nserver.versions = Alpha Exact {0}/{1}\n",
        )
        .expect("alpha exact bundle should write");
        std::fs::write(
            beta.join("bundles/bundle_zh_CN.properties"),
            "play = Beta Exact\nserver.versions = Beta Exact {0}/{1}\n",
        )
        .expect("beta exact bundle should write");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "zh_CN".into();
        launcher.last_mods_directory_mod_names = vec!["alpha".into(), "beta".into()];
        launcher.last_mods_directory_mod_roots = vec![
            alpha.to_string_lossy().into_owned(),
            beta.to_string_lossy().into_owned(),
        ];
        launcher.last_mods_directory_mod_states =
            vec![super::DesktopModsRouteModStateSnapshot::default(); 2];
        launcher.refresh_mods_directory_bundle_values_like_java();

        assert_eq!(
            launcher.localize_bundle_markup_text("@play"),
            "Beta Exact",
            "Java Mods.buildFiles loads enabled mods in order; later mod bundle values override earlier mod values for the same locale"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@settings"),
            "Alpha Language Settings",
            "mod bundle lookup should fall back from bundle_zh_CN to bundle_zh before the root bundle"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@mod.root"),
            "Alpha Root Only",
            "bundle.properties should act as the root parent bundle for mod-provided keys"
        );
        assert_eq!(
            launcher.format_bundle_text("server.versions", &["158", "157"]),
            "Beta Exact 158/157",
            "formatted UI text must use the same mod overlay lookup as plain @key localization"
        );

        launcher.last_mods_directory_mod_states[1].enabled = false;
        launcher.refresh_mods_directory_bundle_values_like_java();
        assert_eq!(
            launcher.localize_bundle_markup_text("@play"),
            "Alpha Exact",
            "Java orderedMods only includes enabled mods; disabling beta should remove its bundle overlay"
        );

        std::fs::remove_dir_all(root).ok();
    }

