    #[test]
    fn desktop_launcher_mod_bundle_beats_external_bundle_family_like_java() {
        let root = temp_desktop_path("mod-bundle-beats-external-family");
        let alpha = root.join("alpha");
        std::fs::create_dir_all(alpha.join("bundles"))
            .expect("alpha bundle fixture dir should be writable");
        std::fs::write(
            root.join("bundle.properties"),
            "play = External Play\nsettings = External Settings\nsector.origin.credit = External Credit\n",
        )
        .expect("external root bundle should write");
        std::fs::write(
            root.join("bundle_en.properties"),
            "play = External English Play\n",
        )
        .expect("external English bundle should write");
        std::fs::write(
            alpha.join("bundles/bundle.properties"),
            "play = Mod Play\nsector.origin.credit = Mod Credit\n",
        )
        .expect("alpha root bundle should write");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.data_dir = root.display().to_string();
        launcher.settings_locale = "en".into();
        launcher.last_mods_directory_mod_names = vec!["alpha".into()];
        launcher.last_mods_directory_mod_roots = vec![alpha.to_string_lossy().into_owned()];
        launcher.last_mods_directory_mod_states =
            vec![super::DesktopModsRouteModStateSnapshot::default()];
        launcher.refresh_mods_directory_bundle_values_like_java();

        assert_eq!(
            launcher.localize_bundle_markup_text("@play"),
            "Mod Play",
            "Java mod bundle overlay should beat external bundle family values"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@sector.origin.credit"),
            "Mod Credit",
            "mod bundle overlay should beat global.properties, which already beats external bundle values"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@settings"),
            "External Settings",
            "missing mod/global keys should still fall through to the external bundle before internal bundle"
        );

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_mod_bundle_seed_refreshes_font_upload_plan_like_java() {
        let root = temp_desktop_path("mod-bundle-font-seed");
        let alpha = root.join("alpha");
        std::fs::create_dir_all(alpha.join("bundles"))
            .expect("alpha bundle fixture dir should be writable");

        let before_seed = super::desktop_external_font_seed_characters();
        let seed_char = (0xe000..=0xf8ff)
            .filter_map(char::from_u32)
            .find(|character| !before_seed.contains(character))
            .expect("test should find an unused private-use seed character");

        let mut launcher = DesktopLauncher::new(Vec::new());
        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);
        let first = launcher
            .menu_graphics_frame_for_surface(0, viewport)
            .font_glyph_upload_plan
            .clone()
            .expect("initial menu frame should expose a font glyph upload plan");
        assert_eq!(launcher.font_glyph_upload_plan_cache_rebuilds(), 1);

        std::fs::write(
            alpha.join("bundles/bundle.properties"),
            format!("mod.seed = {seed_char} Mod Bundle Seed\n"),
        )
        .expect("alpha bundle seed fixture should write");
        launcher.last_mods_directory_mod_names = vec!["alpha".into()];
        launcher.last_mods_directory_mod_roots = vec![alpha.to_string_lossy().into_owned()];
        launcher.last_mods_directory_mod_states =
            vec![super::DesktopModsRouteModStateSnapshot::default()];
        launcher.refresh_mods_directory_bundle_values_like_java();

        assert!(
            super::desktop_external_font_seed_characters().contains(&seed_char),
            "mod bundle values should be registered into the dynamic font seed before atlas upload"
        );
        assert_eq!(
            launcher.localize_bundle_markup_text("@mod.seed"),
            format!("{seed_char} Mod Bundle Seed")
        );

        let _second = launcher
            .menu_graphics_frame_for_surface(1, viewport)
            .font_glyph_upload_plan
            .clone()
            .expect("mod bundle seed changes should still expose a font glyph upload plan");
        assert_eq!(
            launcher.font_glyph_upload_plan_cache_rebuilds(),
            2,
            "mod bundle seed changes must dirty the cached font upload plan through the dynamic seed key"
        );
        let _ = first;

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_settings_windows_specific_titles_follow_java_like_windows() {
        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock should be after epoch")
            .as_nanos();
        let root = std::env::temp_dir().join(format!(
            "mindustry-desktop-settings-windows-title-{}-{unique}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).expect("settings title bundle dir should be writable");
        std::fs::write(
            root.join("bundle.properties"),
            "setting.example.name = Generic Example\nsetting.example.name.windows = Windows Example\n",
        )
        .expect("settings title bundle should be writable");

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.client.context.paths.data_dir = root.display().to_string();
        launcher.settings_locale = "en".into();

        if cfg!(windows) {
            assert_eq!(
                launcher.settings_pref_label("example"),
                "Windows Example",
                "Java SettingsMenuDialog.Setting checks setting.<key>.name.windows first on Windows"
            );
        } else {
            assert_eq!(
                launcher.settings_pref_label("example"),
                "Generic Example",
                "non-Windows platforms should fall back to the generic setting title"
            );
        }

        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn desktop_launcher_settings_child_dialog_backdrops_cover_viewport_like_java_basedialog() {
        fn frame_has_full_viewport_backdrop(
            launcher: &mut DesktopLauncher,
            viewport: RenderViewport,
            alpha: f32,
        ) -> bool {
            let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
            let full = RenderRect::new(viewport.x, viewport.y, viewport.width, viewport.height);
            frame
                .bundle
                .render_frame
                .as_ref()
                .expect("settings dialog frame should render")
                .passes
                .iter()
                .flat_map(|pass| pass.commands.iter())
                .any(|command| {
                    let expects_base_dialog_stage = [0.28_f32, 0.44, 0.46]
                        .iter()
                        .any(|expected| (alpha - expected).abs() < 0.001);
                    matches!(
                        command,
                        RenderCommand::FillRect { rect, color, .. }
                            if *rect == full && (color[3] - alpha).abs() < 0.001
                    ) || expects_base_dialog_stage
                        && matches!(
                            command,
                            RenderCommand::DrawSprite { symbol, rect, tint, .. }
                                if symbol == "whiteui"
                                    && *rect == full
                                    && (tint[3] - 0.9).abs() < 0.001
                        )
                })
        }

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = RenderViewport::new(0.0, 0.0, surface.width as f32, surface.height as f32);
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Settings);

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenDataDialog,
        ));
        assert!(frame_has_full_viewport_backdrop(
            &mut launcher,
            viewport,
            0.44
        ));

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::ClearPlanetData,
        ));
        assert!(frame_has_full_viewport_backdrop(
            &mut launcher,
            viewport,
            0.28
        ));
        assert!(frame_has_full_viewport_backdrop(
            &mut launcher,
            viewport,
            0.44
        ));

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenPlanetChooser,
        ));
        assert!(frame_has_full_viewport_backdrop(
            &mut launcher,
            viewport,
            0.46
        ));
        let settings_panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let chooser = DesktopLauncher::settings_planet_chooser_dialog_rect(
            settings_panel,
            launcher.settings_visible_planet_count(),
        );
        let chooser_back = DesktopLauncher::settings_planet_chooser_back_button_rect(chooser);
        assert_eq!(chooser_back.width, super::SETTINGS_BACK_BUTTON_WIDTH);
        assert_eq!(chooser_back.height, super::SETTINGS_BACK_BUTTON_HEIGHT);
        assert!(
            (chooser_back.center().x - chooser.center().x).abs() < 0.01,
            "Java BaseDialog.addCloseButton centers @back in the dialog footer"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                chooser_back.center().x,
                chooser_back.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::Settings(
                super::DesktopSettingsAction::ClosePlanetChooser
            )),
            "Planet chooser hit testing must use the same 210x64 @back rect that is rendered"
        );
        let chooser_pane = DesktopLauncher::settings_planet_chooser_pane_rect(chooser);
        assert!(
            (chooser_pane.y - (chooser_back.y + chooser_back.height + 14.0)).abs() < 0.01,
            "Planet chooser content pane should be laid out above the Java BaseDialog @back button, not above a 46px schematic info button"
        );

        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::ClosePlanetChooser,
        ));
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::ClearPlanetResearch,
        ));
        assert!(frame_has_full_viewport_backdrop(
            &mut launcher,
            viewport,
            0.50
        ));
    }

    #[test]
    fn desktop_launcher_settings_resize_refreshes_scroll_focus_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.settings_dialog_state.page = super::DesktopSettingsPage::Game;
        let (table, specs) = launcher
            .settings_active_pref_specs()
            .expect("game settings should expose specs");
        let small = DesktopSurfaceSize::new(640, 360);
        let small_viewport = launcher.default_render_viewport_for_surface(small);
        let small_panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            small_viewport,
            super::DesktopMenuRoute::Settings,
        );
        let small_clip = DesktopLauncher::settings_pref_widget_clip_rect_for_panel(small_panel);
        let small_max = DesktopLauncher::settings_max_scroll_offset_for_total_height(
            small_clip,
            DesktopLauncher::settings_pref_widget_total_height_for_specs_with_reset(&specs),
        );
        assert!(small_max > 0);
        launcher.settings_scroll_offsets.insert(table, small_max);
        launcher.settings_language_scroll_offset = usize::MAX;
        launcher.settings_keybind_scroll_offset = usize::MAX;
        launcher.last_menu_cursor = Some(small_clip.center());
        launcher.last_settings_hovered_control =
            Some(super::DesktopSettingsControlId::new(table, specs[0].key));
        launcher.last_settings_pressed_control =
            Some(super::DesktopSettingsControlId::new(table, specs[0].key));
        launcher.settings_scroll_drag_state =
            Some(super::DesktopSettingsScrollDragState::new(table, 3.0));

        let resized = DesktopSurfaceSize::new(1920, 1080);
        let resized_viewport = launcher.default_render_viewport_for_surface(resized);
        let resized_panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            resized_viewport,
            super::DesktopMenuRoute::Settings,
        );
        let resized_clip = DesktopLauncher::settings_pref_widget_clip_rect_for_panel(resized_panel);
        let resized_max = DesktopLauncher::settings_max_scroll_offset_for_total_height(
            resized_clip,
            DesktopLauncher::settings_pref_widget_total_height_for_specs_with_reset(&specs),
        );
        let resized_language_dialog =
            DesktopLauncher::settings_language_dialog_rect_for_panel(resized_panel);
        let resized_language_visible_rows =
            DesktopLauncher::settings_language_visible_rows_for_dialog(resized_language_dialog);
        let resized_language_max = super::settings_language_options_like_java()
            .len()
            .saturating_sub(resized_language_visible_rows);
        assert!(resized_max < small_max);

        let mut frame_loop =
            DesktopFrameLoopState::new(Default::default(), DesktopFramePacing::uncapped());
        let mut graphics_renderer = HeadlessDesktopGraphicsRenderer::default();
        let mut effect_renderer = HeadlessDesktopEffectRenderer::default();
        let result = launcher.step_desktop_frame_loop(
            &mut frame_loop,
            &[DesktopFrameLoopEvent::Resize(resized)],
            &mut graphics_renderer,
            &mut effect_renderer,
        );
        assert!(result.presented);
        assert_eq!(result.resized_to, Some(resized));
        assert_eq!(
            launcher.settings_scroll_offsets.get(table).copied(),
            Some(resized_max),
            "Java SettingsMenuDialog.onResize() rebuilds tables and updateScrollFocus() keeps the active SettingsTable scroll focus in range"
        );
        assert_eq!(launcher.last_menu_cursor, None);
        assert_eq!(launcher.last_settings_hovered_control, None);
        assert_eq!(launcher.last_settings_pressed_control, None);
        assert_eq!(launcher.settings_scroll_drag_state, None);
        assert_eq!(
            launcher.settings_language_scroll_offset,
            resized_language_max
        );
        assert_eq!(
            launcher.settings_keybind_scroll_offset,
            launcher
                .settings_keybind_visible_items()
                .len()
                .saturating_sub(super::SETTINGS_KEYBIND_VISIBLE_ROWS)
        );
    }

    #[test]
    fn desktop_launcher_settings_dynamic_categories_join_main_menu_model() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let category_index = launcher.add_settings_dynamic_category(
            "example-mod",
            "Mod Settings",
            "whiteui",
            "Dynamic category from SettingsMenuDialog.addCategory",
        );
        assert_eq!(category_index, 0);
        launcher.dispatch_menu_action(MenuButtonRole::Settings);

        let entries = launcher.settings_visible_main_menu_entries();
        assert_eq!(entries.len(), 7);
        assert_eq!(
            entries.last().map(|entry| entry.label.as_str()),
            Some("Mod Settings")
        );
        assert_eq!(
            entries.last().and_then(|entry| entry.dynamic_index),
            Some(category_index)
        );
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Settings);
        assert!(lines.contains(&"categories: 7".to_string()));
        assert!(lines
            .iter()
            .any(|line| { line.contains("category: Mod Settings") && !line.contains("target:") }));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let dynamic_button = DesktopLauncher::settings_main_menu_button_rect_for_panel(panel, 6);
        let dynamic_icon_rect =
            DesktopLauncher::settings_main_menu_button_icon_rect(dynamic_button);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("settings main frame should render dynamic category icon")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &DesktopLauncher::settings_drawable_symbol("whiteui")
                    && *rect == dynamic_icon_rect
        )), "Java SettingsMenuDialog.addCategory(region) renders a TextureRegionDrawable with Scaling.fit for custom category icons");
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawText { text, position, style, .. }
                    if text == "whiteui"
                        && dynamic_button.contains_point(*position)
                        && style.font == RenderFontId::Icon
            )),
            "custom Settings category region names must not be drawn as raw icon-font text"
        );
        let dynamic_button = dynamic_button.center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                dynamic_button.x,
                dynamic_button.y
            ),
            Some(super::DesktopMenuRouteShellAction::Settings(
                super::DesktopSettingsAction::OpenDynamicCategory(category_index)
            ))
        );
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenDynamicCategory(category_index),
        ));
        assert_eq!(
            launcher.settings_dialog_state.page,
            super::DesktopSettingsPage::DynamicCategory
        );
        assert_eq!(
            launcher.settings_dynamic_category_page_index,
            Some(category_index)
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("dynamic settings category page should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(!texts.contains(&"Mod Settings"));
        assert!(!texts.contains(&"Dynamic category from SettingsMenuDialog.addCategory"));
        assert!(!texts.contains(&"dynamic target: example-mod"));
        assert_eq!(
            launcher.settings_route_action_for_line(5),
            Some(super::DesktopSettingsAction::ResetCurrentPage)
        );
        assert_eq!(
            launcher.settings_route_action_for_line(6),
            Some(super::DesktopSettingsAction::BackToMain)
        );

        assert!(launcher.apply_menu_back_key());
        assert_eq!(
            launcher.settings_dialog_state.page,
            super::DesktopSettingsPage::Main
        );
        assert_eq!(launcher.settings_dynamic_category_page_index, None);
        assert_eq!(
            launcher.last_settings_action,
            Some(super::DesktopSettingsAction::BackToMain)
        );
    }

    #[test]
    fn desktop_launcher_settings_dynamic_text_and_area_prefs_render_edit_and_reset_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let category_index = launcher.add_settings_dynamic_category(
            "mod-text-settings",
            "Text Settings",
            "settings",
            "SettingsTable builder entries",
        );
        launcher
            .add_settings_dynamic_category_text_pref(category_index, "serverName", "alpha")
            .expect("dynamic text pref should register");
        launcher
            .add_settings_dynamic_category_area_text_pref(category_index, "serverMotd", "welcome")
            .expect("dynamic area text pref should register");
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenDynamicCategory(category_index),
        ));

        let (table, specs) = launcher
            .settings_active_pref_specs()
            .expect("dynamic category should expose a SettingsTable-like pref list");
        assert_eq!(table, "mod-text-settings");
        assert_eq!(specs.len(), 2);
        assert_eq!(specs[0].kind, super::DesktopSettingsPrefKind::Text);
        assert_eq!(specs[1].kind, super::DesktopSettingsPrefKind::AreaText);
        assert_eq!(
            launcher.settings_route_action_for_line(5),
            Some(super::DesktopSettingsAction::ResetCurrentPage)
        );
        assert_eq!(
            launcher.settings_route_action_for_line(6),
            Some(super::DesktopSettingsAction::BackToMain)
        );

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let clip = DesktopLauncher::settings_pref_widget_clip_rect_for_panel(panel);
        let scroll = launcher.settings_scroll_offset_pixels_for_specs(table, clip, &specs);
        let text_row = DesktopLauncher::settings_pref_widget_row_rect_for_specs_with_scroll(
            clip, &specs, 0, scroll,
        );
        let text_field = DesktopLauncher::settings_pref_widget_text_field_rect(text_row);
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                text_field.center().x,
                text_field.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::Settings(
                super::DesktopSettingsAction::FocusSettingText(table, "serverName")
            ))
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("dynamic text settings page should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let initial_area_row = DesktopLauncher::settings_pref_widget_row_rect_for_specs_with_scroll(
            clip, &specs, 1, scroll,
        );
        let initial_area_field =
            DesktopLauncher::settings_pref_widget_area_text_rect(initial_area_row);
        let text_field_background = DesktopLauncher::settings_text_field_background_symbol();
        for field in [text_field, initial_area_field] {
            assert!(
                commands.iter().any(|command| matches!(
                    command,
                    RenderCommand::DrawSprite { symbol, rect, .. }
                        if symbol == &text_field_background && *rect == field
                )),
                "Java TextField/TextArea should render the style background for {field:?}"
            );
            assert!(
                !commands.iter().any(|command| matches!(
                    command,
                    RenderCommand::StrokeRect { rect, .. } if *rect == field
                )),
                "Java TextFieldStyle/AreaTextSetting should not add a Rust-only StrokeRect border around {field:?}"
            );
        }
        let expected_area_label = launcher.settings_pref_label("serverMotd");
        let area_label_position = commands
            .iter()
            .find_map(|command| match command {
                RenderCommand::DrawText { text, position, .. } if text == &expected_area_label => {
                    Some(*position)
                }
                _ => None,
            })
            .expect("area text label should be rendered");
        let area_value_position = commands
            .iter()
            .find_map(|command| match command {
                RenderCommand::DrawText { text, position, .. } if text == "welcome" => {
                    Some(*position)
                }
                _ => None,
            })
            .expect("area text value should be rendered");
        assert!(area_label_position.y < area_value_position.y);
        assert!(!commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, .. } if text == "Text Settings"
        )));
        assert!(!commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, .. } if text == "SettingsTable builder entries"
        )));
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, .. } if text == "alpha"
        )));
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, .. } if text == "welcome"
        )));
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, color, .. }
                if text == "alpha"
                    && *color == DesktopLauncher::settings_text_field_font_color(true)
        )));
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, color, .. }
                if text == "welcome"
                    && *color == DesktopLauncher::settings_text_field_font_color(true)
        )));
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, color, .. }
                if text == &expected_area_label
                    && *color == DesktopLauncher::settings_label_style_font_color("defaultLabel")
        )));

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: text_field.center().x,
                    y: text_field.center().y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.settings_text_focused_control,
            Some(super::DesktopSettingsControlId::new(table, "serverName"))
        );
        launcher.apply_menu_input_events(surface, &[DesktopInputTickEvent::Text(" beta".into())]);
        assert_eq!(
            launcher
                .setting_effective_value(table, "serverName")
                .as_deref(),
            Some("alpha beta")
        );
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Key {
                key_code: "Backspace".into(),
                pressed: true,
            }],
        );
        assert_eq!(
            launcher
                .setting_effective_value(table, "serverName")
                .as_deref(),
            Some("alpha bet")
        );
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Key {
                key_code: "Enter".into(),
                pressed: true,
            }],
        );
        assert_eq!(launcher.settings_text_focused_control, None);

        let area_row = DesktopLauncher::settings_pref_widget_row_rect_for_specs_with_scroll(
            clip, &specs, 1, scroll,
        );
        let area = DesktopLauncher::settings_pref_widget_area_text_rect(area_row);
        assert!(
            area.y > DesktopLauncher::settings_pref_widget_area_label_point(area_row).y,
            "Java SettingsMenuDialog.AreaTextSetting.add() renders the label on the line above the TextArea"
        );
        assert!(
            (area.y - (area_row.y + 22.0)).abs() < 0.01,
            "area text field should start below the label line"
        );
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: area.center().x,
                    y: area.center().y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.settings_text_focused_control,
            Some(super::DesktopSettingsControlId::new(table, "serverMotd"))
        );
        launcher.apply_menu_input_events(surface, &[DesktopInputTickEvent::Text(" line".into())]);
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Key {
                key_code: "Enter".into(),
                pressed: true,
            }],
        );
        launcher.apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("two".into())]);
        assert_eq!(
            launcher
                .setting_effective_value(table, "serverMotd")
                .as_deref(),
            Some("welcome line\ntwo")
        );
        let area_cursor_rect = DesktopLauncher::settings_pref_widget_area_text_cursor_rect(
            area,
            launcher
                .setting_effective_value(table, "serverMotd")
                .as_deref()
                .unwrap_or_default(),
        );
        assert!(area_cursor_rect.x > area.x + 8.0);
        assert!(area_cursor_rect.y > area.y + 8.0);
        let area_cursor_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let area_cursor_symbol = DesktopLauncher::settings_text_field_cursor_symbol();
        assert!(
            area_cursor_frame
                .bundle
                .render_frame
                .as_ref()
                .expect("focused area text settings page should render")
                .passes
                .iter()
                .flat_map(|pass| pass.commands.iter())
                .any(|command| match command {
                    RenderCommand::DrawSprite { symbol, rect, .. } => {
                        symbol == &area_cursor_symbol && rect == &area_cursor_rect
                    }
                    _ => false,
                }),
            "Java TextArea caret follows the edited text instead of staying pinned to the upper-left corner"
        );

        launcher.dispatch_settings_action(super::DesktopSettingsAction::ResetCurrentPage);
        assert_eq!(
            launcher
                .setting_effective_value(table, "serverName")
                .as_deref(),
            Some("alpha")
        );
        assert_eq!(
            launcher
                .setting_effective_value(table, "serverMotd")
                .as_deref(),
            Some("welcome")
        );
        assert!(!launcher
            .settings_overrides
            .contains_key(&DesktopLauncher::settings_storage_key(table, "serverName")));
        assert!(!launcher
            .settings_overrides
            .contains_key(&DesktopLauncher::settings_storage_key(table, "serverMotd")));
    }

    #[test]
    fn desktop_launcher_settings_text_and_area_pref_description_tooltips_match_java_hit_targets() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let category_index = launcher.add_settings_dynamic_category(
            "tooltip-text-settings",
            "Tooltip Settings",
            "settings",
            "SettingsTable tooltip hit target fixtures",
        );
        launcher
            .add_settings_dynamic_category_text_pref(category_index, "uiscale", "100")
            .expect("text pref with upstream description should register");
        launcher
            .add_settings_dynamic_category_area_text_pref(category_index, "detach-camera", "off")
            .expect("area pref with upstream description should register");
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenDynamicCategory(category_index),
        ));

        let (table, specs) = launcher
            .settings_active_pref_specs()
            .expect("dynamic category should expose tooltip specs");
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let clip = DesktopLauncher::settings_pref_widget_clip_rect_for_panel(panel);
        let scroll = launcher.settings_scroll_offset_pixels_for_specs(table, clip, &specs);
        let text_row = DesktopLauncher::settings_pref_widget_row_rect_for_specs_with_scroll(
            clip, &specs, 0, scroll,
        );
        let text_field = DesktopLauncher::settings_pref_widget_text_field_rect(text_row);
        let text_label_hover = RenderPoint::new(text_field.right() + 32.0, text_row.center().y);
        assert!(!text_field.contains_point(text_label_hover));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                text_label_hover.x,
                text_label_hover.y
            ),
            None,
            "clicking the TextSetting label area should not focus the TextField"
        );
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: text_label_hover.x,
                y: text_label_hover.y,
            }],
        );
        let text_tooltip_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let text_tooltip_rect = DesktopLauncher::settings_pref_description_tooltip_rect(
            panel,
            text_label_hover,
            "Restart required to apply changes.",
        );
        let text_tooltip_chrome = DesktopLauncher::settings_pref_description_tooltip_chrome();
        let black6_symbol = DesktopLauncher::settings_drawable_symbol("black6");
        assert_eq!(text_tooltip_chrome.background_symbol, "black6");
        assert_eq!(text_tooltip_chrome.margin, 4.0);
        assert_eq!(text_tooltip_chrome.border_color, [0.28, 0.38, 0.46, 0.70]);
        assert_eq!(text_tooltip_chrome.text_color, [0.72, 0.78, 0.84, 1.0]);
        let text_tooltip_commands = text_tooltip_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("text tooltip frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        assert!(
            text_tooltip_commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, tint, .. }
                    if symbol == &black6_symbol
                        && *rect == text_tooltip_rect
                        && *tint == text_tooltip_chrome.background_tint
            )),
            "Java tooltip chrome should use Styles.black6 as the background"
        );
        assert!(
            text_tooltip_commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, color, thickness, .. }
                    if *rect == text_tooltip_rect
                        && *color == text_tooltip_chrome.border_color
                        && (*thickness - text_tooltip_chrome.border_thickness).abs() < f32::EPSILON
            )),
            "Java tooltip chrome should keep its border color metadata centralized"
        );
        assert!(
            !text_tooltip_commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, .. } if *rect == text_row
            )),
            "Java SettingsMenuDialog ui.addDescTooltip(...) should not draw a Rust-only highlight stroke around the hovered setting row"
        );
        assert!(
            text_tooltip_commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawText { text, color, .. }
                    if text == "Restart required to apply changes."
                        && *color == text_tooltip_chrome.text_color
            )),
            "Java tooltip chrome should use the light-gray description text color"
        );
        let text_tooltip_texts = text_tooltip_commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            text_tooltip_texts
                .iter()
                .any(|text| text.contains("Restart required to apply changes")),
            "Java TextSetting.addDesc(prefTable) should show the description when hovering the field+label prefTable, not only the TextField"
        );

        let area_row = DesktopLauncher::settings_pref_widget_row_rect_for_specs_with_scroll(
            clip, &specs, 1, scroll,
        );
        let area_field = DesktopLauncher::settings_pref_widget_area_text_rect(area_row);
        let area_label_hit = DesktopLauncher::settings_pref_widget_area_label_hit_rect(area_row);
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: area_label_hit.x + 8.0,
                y: area_label_hit.center().y,
            }],
        );
        let area_label_tooltip_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let area_label_tooltip_texts = area_label_tooltip_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("area label tooltip frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            area_label_tooltip_texts
                .iter()
                .any(|text| text.contains("camera moves independently")),
            "Java AreaTextSetting.addDesc(label) should show the description when hovering the title label"
        );

        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: area_field.center().x,
                y: area_field.center().y,
            }],
        );
        let area_field_frame = launcher.menu_graphics_frame_for_surface(2, viewport);
        let area_field_texts = area_field_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("area field hover frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            !area_field_texts
                .iter()
                .any(|text| text.contains("camera moves independently")),
            "Java AreaTextSetting binds addDesc to the label, so hovering inside the TextArea body alone should not show the description tooltip"
        );
    }

    #[test]
    fn desktop_launcher_settings_dynamic_category_without_description_maps_back_line_like_java_dialog(
    ) {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let category_index = launcher.add_settings_dynamic_category(
            "empty-description-mod",
            "Empty Description",
            "settings",
            "   ",
        );
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.dispatch_menu_route_shell_action(super::DesktopMenuRouteShellAction::Settings(
            super::DesktopSettingsAction::OpenDynamicCategory(category_index),
        ));

        let lines = launcher.settings_route_lines();
        assert!(lines.contains(&"settings page: dynamic-category".to_string()));
        assert!(lines.iter().any(|line| {
            line.contains("category: Empty Description") && !line.contains("target:")
        }));
        assert!(
            !lines.iter().any(|line| line.starts_with("description:")),
            "Java SettingsMenuDialog.addCategory can add a page without description; Rust must not reserve a dead description line"
        );
        assert_eq!(
            lines.get(4).map(String::as_str),
            Some("table: empty-description-mod settings: 0")
        );
        assert_eq!(
            lines.get(5).map(String::as_str),
            Some("button: reset-to-defaults")
        );
        assert_eq!(lines.get(6).map(String::as_str), Some("button: back"));
        assert_eq!(
            launcher.settings_route_action_for_line(5),
            Some(super::DesktopSettingsAction::ResetCurrentPage)
        );
        assert_eq!(
            launcher.settings_route_action_for_line(6),
            Some(super::DesktopSettingsAction::BackToMain)
        );

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("empty dynamic category settings page should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(!texts.contains(&"Empty Description"));
        assert!(!texts.contains(&"SettingsMenuDialog.addCategory(...)"));

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Settings,
        );
        let back_center = DesktopLauncher::settings_back_button_rect_for_panel(panel).center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: back_center.x,
                    y: back_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );

        assert_eq!(
            launcher.settings_dialog_state.page,
            super::DesktopSettingsPage::Main
        );
        assert_eq!(launcher.settings_dynamic_category_page_index, None);
        assert_eq!(
            launcher.last_settings_action,
            Some(super::DesktopSettingsAction::BackToMain)
        );
    }

    #[test]
    fn desktop_launcher_settings_immediate_side_effects_match_upstream_menu_expectations() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher
            .join_community_groups
            .push(super::DesktopJoinCommunityGroup::new(
                "Cached",
                vec!["cached.example:6567".into()],
                true,
            ));
        launcher.join_community_cache_loaded = true;
        launcher.join_community_feed_fetched = true;
        launcher.set_setting_override("game", "communityservers", "false");
        assert!(launcher.join_community_groups.is_empty());
        assert!(!launcher.join_community_cache_loaded);
        assert!(!launcher.join_community_feed_fetched);
        assert_eq!(launcher.join_community_cache_error, None);

        launcher.set_setting_override("graphics", "uiEdgePadding", "24");
        assert_eq!(launcher.menu_scene_margin_top, 24.0);
        assert_eq!(launcher.menu_scene_margin_left, 24.0);
        assert_eq!(launcher.menu_scene_margin_right, 24.0);
        assert_eq!(launcher.menu_scene_margin_bottom, 24.0);

        assert!(!launcher.menu_macnotch_enabled);
        launcher.set_setting_override("graphics", "macnotch", "true");
        assert!(launcher.menu_macnotch_enabled);
        launcher.set_setting_override("graphics", "macnotch", "false");
        assert!(!launcher.menu_macnotch_enabled);

        launcher.set_setting_override("graphics", "uiscale", "150");
        assert_eq!(launcher.menu_ui_scale, 1.5);
        assert_eq!(
            launcher
                .settings_overrides
                .get(&DesktopLauncher::settings_storage_key(
                    "graphics",
                    "uiscalechanged"
                ))
                .map(String::as_str),
            Some("true")
        );
        launcher.set_setting_override("graphics", "uiscale", "100");
        assert_eq!(launcher.menu_ui_scale, 1.0);
        assert_eq!(
            launcher
                .settings_overrides
                .get(&DesktopLauncher::settings_storage_key(
                    "graphics",
                    "uiscalechanged"
                ))
                .map(String::as_str),
            Some("false")
        );

        launcher.set_setting_override("graphics", "pixelate", "true");
        assert!(launcher.pixelate);
        launcher.set_setting_override("graphics", "pixelate", "false");
        assert!(!launcher.pixelate);

        assert!(launcher.graphics_vsync_enabled);
        launcher.set_setting_override("graphics", "vsync", "false");
        assert!(!launcher.graphics_vsync_enabled);
        launcher.set_setting_override("graphics", "vsync", "true");
        assert!(launcher.graphics_vsync_enabled);

        assert!(!launcher.graphics_fullscreen_enabled);
        launcher.set_setting_override("graphics", "fullscreen", "true");
        assert!(launcher.graphics_fullscreen_enabled);
        launcher.set_setting_override("graphics", "fullscreen", "false");
        assert!(!launcher.graphics_fullscreen_enabled);

        assert!(launcher.texture_atlas.linear_filter());
        launcher.set_setting_override("graphics", "linear", "false");
        assert!(!launcher.texture_atlas.linear_filter());
        assert!(
            !launcher
                .texture_atlas
                .lookup("logo")
                .unwrap()
                .region
                .pack_meta
                .linear_filter,
            "Java Settings linear checkbox immediately reapplies filters to already-loaded atlas textures"
        );
        launcher.set_setting_override("graphics", "linear", "true");
        assert!(launcher.texture_atlas.linear_filter());

        assert!(launcher.renderer_bloom_enabled);
        launcher.set_setting_override("graphics", "bloom", "false");
        assert!(!launcher.renderer_bloom_enabled);
        launcher.set_setting_override("graphics", "bloom", "true");
        assert!(launcher.renderer_bloom_enabled);

        assert_eq!(launcher.renderer_bloom_intensity, 2.5);
        launcher.set_setting_override("graphics", "bloomintensity", "16");
        assert_eq!(launcher.renderer_bloom_intensity, 5.0);
        launcher.set_setting_override("graphics", "bloomintensity", "0");
        assert_eq!(launcher.renderer_bloom_intensity, 1.0);

        assert_eq!(launcher.renderer_bloom_blur_passes, 2);
        launcher.set_setting_override("graphics", "bloomblur", "9");
        assert_eq!(launcher.renderer_bloom_blur_passes, 9);
    }

    #[test]
    fn desktop_launcher_fullscreen_binding_toggles_setting_like_java_control_update() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let surface = DesktopSurfaceSize::new(1280, 720);

        assert!(!launcher.graphics_fullscreen_enabled);
        assert_eq!(
            launcher.setting_override_value("graphics", "fullscreen"),
            None
        );

        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Key {
                key_code: "F11".into(),
                pressed: true,
            }],
        );
        assert!(launcher.graphics_fullscreen_enabled);
        assert_eq!(
            launcher.setting_override_value("graphics", "fullscreen"),
            Some("true"),
            "Java Control.update toggles Core.graphics fullscreen and writes settings.fullscreen"
        );

        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Key {
                key_code: "F11".into(),
                pressed: true,
            }],
        );
        assert!(!launcher.graphics_fullscreen_enabled);
        assert_eq!(
            launcher.setting_override_value("graphics", "fullscreen"),
            Some("false")
        );

        launcher.last_settings_rebind_key = Some("move_x");
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Key {
                key_code: "F11".into(),
                pressed: true,
            }],
        );
        assert!(
            !launcher.graphics_fullscreen_enabled,
            "KeybindDialog capture should not also toggle fullscreen"
        );
        assert_eq!(launcher.last_settings_rebind_key, Some("move_x"));
    }

