    #[test]
    fn desktop_launcher_settings_keybind_rebinds_persist_to_java_keybind_settings_shape() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.dispatch_settings_action(super::DesktopSettingsAction::OpenControlsDialog);

        launcher.dispatch_settings_action(super::DesktopSettingsAction::StartKeyRebind("move_x"));
        assert!(launcher.commit_settings_keybind_rebind("K"));
        assert_eq!(
            launcher.settings_keybind_pending_axis_min.as_deref(),
            Some("K")
        );
        assert!(!launcher
            .settings_overrides
            .contains_key("keybind-default-keyboard-move_x-single"));

        assert!(launcher.commit_settings_keybind_rebind("L"));
        assert_eq!(
            launcher
                .settings_keybind_overrides
                .get("move_x")
                .map(String::as_str),
            Some("K / L")
        );
        assert_eq!(
            launcher
                .settings_overrides
                .get("keybind-default-keyboard-move_x-single")
                .map(String::as_str),
            Some("false")
        );
        assert_eq!(
            launcher
                .settings_overrides
                .get("keybind-default-keyboard-move_x-min")
                .map(String::as_str),
            Some("80")
        );
        assert_eq!(
            launcher
                .settings_overrides
                .get("keybind-default-keyboard-move_x-max")
                .map(String::as_str),
            Some("81")
        );
        assert!(
            !launcher
                .settings_overrides
                .contains_key("keybind-default-keyboard-move_x-rust-display"),
            "known Java keybind values should persist only in Java Settings shape, not Rust-only display fallback"
        );

        let mut reloaded = DesktopLauncher::new(Vec::new());
        reloaded.settings_overrides = launcher.settings_overrides.clone();
        assert_eq!(reloaded.load_settings_keybinds_from_settings(), 1);
        assert_eq!(
            reloaded
                .settings_keybind_overrides
                .get("move_x")
                .map(String::as_str),
            Some("K / L")
        );

        reloaded.dispatch_settings_action(super::DesktopSettingsAction::StartKeyRebind("select"));
        assert!(reloaded.commit_settings_keybind_rebind("primary"));
        assert_eq!(
            reloaded
                .settings_overrides
                .get("keybind-default-keyboard-select-single")
                .map(String::as_str),
            Some("true")
        );
        assert_eq!(
            reloaded
                .settings_overrides
                .get("keybind-default-keyboard-select-key")
                .map(String::as_str),
            Some("21")
        );
        assert!(
            !reloaded
                .settings_overrides
                .contains_key("keybind-default-keyboard-select-rust-display"),
            "single key rebinds should not persist Rust-only display fallback"
        );
        reloaded.dispatch_settings_action(super::DesktopSettingsAction::StartKeyRebind("select"));
        assert!(
            !reloaded.commit_settings_keybind_rebind("unknownRustKeyName"),
            "unknown key names should be rejected instead of becoming visible raw Controls text"
        );

        reloaded.dispatch_settings_action(super::DesktopSettingsAction::ResetKey("move_x"));
        assert!(!reloaded.settings_keybind_overrides.contains_key("move_x"));
        assert!(!reloaded
            .settings_overrides
            .contains_key("keybind-default-keyboard-move_x-single"));
        assert!(!reloaded
            .settings_overrides
            .contains_key("keybind-default-keyboard-move_x-min"));
        assert!(!reloaded
            .settings_overrides
            .contains_key("keybind-default-keyboard-move_x-max"));

        reloaded.dispatch_settings_action(super::DesktopSettingsAction::ResetAllKeys);
        assert!(reloaded.settings_keybind_overrides.is_empty());
        assert!(!reloaded.settings_overrides.keys().any(|key| {
            key.starts_with("keybind-default-keyboard-select-")
                || key.starts_with("keybind-default-keyboard-move_x-")
        }));
    }

    #[test]
    fn desktop_launcher_settings_main_menu_entries_cache_reuses_stable_runtime_projection() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        assert_eq!(
            launcher.settings_visible_main_menu_entries_cache_rebuilds(),
            0
        );

        let first = launcher.settings_visible_main_menu_entries();
        assert!(!first.is_empty());
        assert_eq!(
            launcher.settings_visible_main_menu_entries_cache_rebuilds(),
            1
        );
        assert_eq!(launcher.settings_visible_main_menu_entries(), first);
        assert_eq!(
            launcher.settings_visible_main_menu_entries_cache_rebuilds(),
            1,
            "stable SettingsMenuDialog main page frames should reuse the visible entry projection"
        );

        launcher.menu_renderer_state.config.mobile = true;
        let mobile = launcher.settings_visible_main_menu_entries();
        assert_eq!(
            launcher.settings_visible_main_menu_entries_cache_rebuilds(),
            2,
            "mobile runtime gates can change Java Settings menu entries and must invalidate the cache"
        );
        assert_eq!(launcher.settings_visible_main_menu_entries(), mobile);
        assert_eq!(
            launcher.settings_visible_main_menu_entries_cache_rebuilds(),
            2
        );

        let dynamic_index =
            launcher.add_settings_dynamic_category("ctf-extra", "@settings.ctf", "settings", "");
        let dynamic = launcher.settings_visible_main_menu_entries();
        assert_eq!(
            launcher.settings_visible_main_menu_entries_cache_rebuilds(),
            3
        );
        assert!(dynamic.iter().any(|entry| {
            entry.dynamic_index == Some(dynamic_index) && entry.target == "dynamic:ctf-extra"
        }));

        launcher.add_settings_dynamic_category("ctf-extra", "@settings.ctf.renamed", "wrench", "");
        let renamed = launcher.settings_visible_main_menu_entries();
        assert_eq!(
            launcher.settings_visible_main_menu_entries_cache_rebuilds(),
            4,
            "renaming a dynamic Settings category changes the Java menu button label/icon and must invalidate the cache"
        );
        assert!(renamed.iter().any(|entry| {
            entry.dynamic_index == Some(dynamic_index)
                && entry.label == "@settings.ctf.renamed"
                && entry.icon == "wrench"
        }));
    }

