    #[test]
    fn desktop_launcher_settings_reset_current_page_removes_only_that_table_overrides() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.dispatch_menu_action(MenuButtonRole::Settings);
        launcher.settings_dialog_state.page = super::DesktopSettingsPage::Game;

        launcher.set_setting_override("game", "saveinterval", "120");
        launcher.set_setting_override("game", "communityservers", "false");
        launcher.set_setting_override("graphics", "fullscreen", "true");
        launcher.set_setting_override("sound", "musicvol", "15");

        assert_eq!(
            launcher
                .setting_effective_value("game", "saveinterval")
                .as_deref(),
            Some("120")
        );
        assert_eq!(
            launcher
                .setting_effective_value("graphics", "fullscreen")
                .as_deref(),
            Some("true")
        );
        assert_eq!(
            launcher
                .setting_effective_value("sound", "musicvol")
                .as_deref(),
            Some("15")
        );

        launcher.dispatch_settings_action(super::DesktopSettingsAction::ResetCurrentPage);

        assert_eq!(
            launcher.last_settings_action,
            Some(super::DesktopSettingsAction::ResetCurrentPage)
        );
        assert_eq!(
            launcher.settings_dialog_state.page,
            super::DesktopSettingsPage::Game
        );
        assert_eq!(
            launcher.setting_override_value("game", "saveinterval"),
            None
        );
        assert_eq!(
            launcher
                .setting_effective_value("game", "saveinterval")
                .as_deref(),
            Some("60")
        );
        assert_eq!(
            launcher.setting_override_value("game", "communityservers"),
            None
        );
        assert_eq!(
            launcher
                .setting_effective_value("game", "communityservers")
                .as_deref(),
            Some("true")
        );
        assert_eq!(
            launcher
                .setting_effective_value("graphics", "fullscreen")
                .as_deref(),
            Some("true")
        );
        assert_eq!(
            launcher
                .setting_effective_value("sound", "musicvol")
                .as_deref(),
            Some("15")
        );
    }

    #[test]
    fn desktop_launcher_menu_back_key_closes_route_shell_then_submenu() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let surface = DesktopSurfaceSize::new(800, 600);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let input = DesktopLauncher::default_menu_frame_input_for_viewport(viewport);
        let play_center = launcher
            .menu_renderer_state
            .ui_plan(input)
            .buttons
            .iter()
            .find(|button| button.role == MenuButtonRole::Play)
            .expect("menu ui should include PLAY root")
            .rect
            .center();

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: play_center.x,
                    y: play_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );

        let campaign_center = launcher
            .menu_renderer_state
            .ui_plan(input)
            .buttons
            .iter()
            .find(|button| button.role == MenuButtonRole::Campaign)
            .expect("play submenu should include CAMPAIGN")
            .rect
            .center();

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: campaign_center.x,
                    y: campaign_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::Campaign)
        );

        if launcher.campaign_intro_select_dialog_open
            || launcher.campaign_serpulo_rework_notice_open
        {
            launcher.apply_menu_input_events(
                surface,
                &[DesktopInputTickEvent::Key {
                    key_code: "Escape".into(),
                    pressed: true,
                }],
            );
            assert_eq!(
                launcher.active_menu_route,
                Some(super::DesktopMenuRoute::Campaign),
                "Java dialog stack closes campaign intro/notice before closing the route shell"
            );
            assert!(!launcher.campaign_intro_select_dialog_open);
            assert!(!launcher.campaign_serpulo_rework_notice_open);
        }

        for _ in 0..3 {
            launcher.apply_menu_input_events(
                surface,
                &[DesktopInputTickEvent::Key {
                    key_code: "Escape".into(),
                    pressed: true,
                }],
            );
            if launcher.active_menu_route.is_none() {
                break;
            }
        }
        assert_eq!(launcher.active_menu_route, None);
        assert_eq!(launcher.campaign_planet_dialog, None);

        let database_center = launcher
            .menu_renderer_state
            .ui_plan(input)
            .buttons
            .iter()
            .find(|button| button.role == MenuButtonRole::Database)
            .expect("menu ui should include DATABASE root")
            .rect
            .center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: database_center.x,
                    y: database_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "left".into(),
                    pressed: true,
                },
            ],
        );
        assert_eq!(
            launcher.menu_renderer_state.selected_root,
            MenuButtonRole::Database
        );

        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::Key {
                key_code: "Back".into(),
                pressed: true,
            }],
        );
        assert_eq!(
            launcher.menu_renderer_state.selected_root,
            MenuButtonRole::Play
        );
    }

    #[test]
    fn desktop_launcher_campaign_menu_route_shell_uses_content_start_sector() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        let surface = DesktopSurfaceSize::new(800, 600);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let input = DesktopLauncher::default_menu_frame_input_for_viewport(viewport);
        let play_center = launcher
            .menu_renderer_state
            .ui_plan(input)
            .buttons
            .iter()
            .find(|button| button.role == MenuButtonRole::Play)
            .expect("menu ui should include PLAY root")
            .rect
            .center();

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: play_center.x,
                    y: play_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );

        let campaign_center = launcher
            .menu_renderer_state
            .ui_plan(input)
            .buttons
            .iter()
            .find(|button| button.role == MenuButtonRole::Campaign)
            .expect("play submenu should include CAMPAIGN")
            .rect
            .center();

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: campaign_center.x,
                    y: campaign_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );

        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::Campaign)
        );
        assert_eq!(
            launcher.campaign_planet_dialog,
            Some(super::CampaignPlanetDialogState {
                planet_name: "serpulo".into(),
                mode: super::CampaignPlanetDialogMode::Look,
                selected_sector_id: Some(15),
                hovered_sector_id: None,
                launch_sector_id: None,
                launch_candidate_planet_names: Vec::new(),
                new_preset_sector_ids: vec![15],
            })
        );
        assert_eq!(
            launcher.last_menu_dispatch,
            Some(super::DesktopMenuActionDispatch {
                role: MenuButtonRole::Campaign,
                submenu_changed: false,
                route: Some(super::DesktopMenuRoute::Campaign),
                close_requested: false,
            })
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("menu frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            !texts.contains(&"upstream: PlanetDialog"),
            "Java PlanetDialog does not render Rust route-shell upstream debug text"
        );
        assert!(texts.iter().any(|text| text.contains("groundZero")));
        assert!(
            !texts.iter().any(|text| text.contains("groundZero #15")),
            "Java PlanetDialog only appends sector ids when debugSelect is enabled"
        );
        assert!(
            !texts.iter().any(|text| text.contains("new sector")),
            "Java PlanetDialog announces new presets transiently instead of rendering a fixed English badge"
        );
        for rust_only_status in [
            "Ready to launch",
            "Select a launch sector",
            "Launch sector ready",
        ] {
            assert!(
                !texts.contains(&rust_only_status),
                "Campaign route should not render Rust-only hardcoded status text: {rust_only_status}"
            );
        }
        let launch_label = launcher.localize_bundle_markup_text("@sectors.launch");
        assert!(texts.contains(&launch_label.as_str()));
        let back_label = launcher.localize_bundle_markup_text("@back");
        let tech_tree_label = launcher.localize_bundle_markup_text("@techtree");
        assert!(texts.contains(&back_label.as_str()));
        assert!(texts.contains(&tech_tree_label.as_str()));
        for raw_key in [
            "@campaign.difficulty",
            "@back",
            "@techtree",
            "@sectors.launch",
            "@sectors.select",
            "@sectors.launchselect",
            "@stats",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "Campaign PlanetDialog shell final DrawText should localize {raw_key} before rendering"
            );
        }
        assert!(
            !texts.contains(&"planet: serpulo"),
            "Campaign route should render a dedicated PlanetDialog body instead of generic route lines"
        );
        assert!(
            !texts
                .iter()
                .any(|text| text.starts_with("PlanetDialog sector preview")),
            "Campaign route body should not leak Java class/debug labels into real UI copy"
        );

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let back_center = DesktopLauncher::campaign_route_secondary_button_rect(panel, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                back_center.x,
                back_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::CloseRoute)
        );
        let tech_tree_center =
            DesktopLauncher::campaign_route_secondary_button_rect(panel, 1).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                tech_tree_center.x,
                tech_tree_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenCampaignTechTree)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenCampaignTechTree,
        );
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::TechTree)
        );
        assert!(
            launcher.campaign_planet_dialog.is_some(),
            "Java ResearchDialog opens over PlanetDialog, so Campaign state must remain available for Back"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_builds_planet_renderer_params_from_dialog_state() {
        fn custom_properties<'a>(
            command: &'a RenderCommand,
            expected_name: &str,
        ) -> Option<&'a [RenderProperty]> {
            match command {
                RenderCommand::Custom { name, properties } if name == expected_name => {
                    Some(properties.as_slice())
                }
                _ => None,
            }
        }

        fn property<'a>(properties: &'a [RenderProperty], key: &str) -> &'a str {
            properties
                .iter()
                .find(|property| property.key == key)
                .map(|property| property.value.as_str())
                .unwrap()
        }

        fn close_f32(left: f32, right: f32) -> bool {
            (left - right).abs() < 0.01
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        launcher.campaign_planet_dialog = Some(super::CampaignPlanetDialogState {
            planet_name: "serpulo".into(),
            mode: super::CampaignPlanetDialogMode::Look,
            selected_sector_id: Some(15),
            hovered_sector_id: Some(15),
            launch_sector_id: None,
            launch_candidate_planet_names: Vec::new(),
            new_preset_sector_ids: vec![15],
        });

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let content = DesktopLauncher::campaign_route_content_rect(panel);
        let planet_card = RenderRect::new(
            content.x,
            content.y + content.height * 0.34,
            content.width,
            content.height * 0.60,
        );
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign route should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();

        let scene = commands
            .iter()
            .find_map(|command| custom_properties(command, "planet-renderer-scene-plan"))
            .expect("Campaign PlanetDialog planet card should consume PlanetRenderer::render");
        assert_eq!(
            property(scene, "source"),
            "desktop.CampaignRoute.PlanetDialog"
        );
        assert_eq!(property(scene, "planet"), "serpulo");
        assert_eq!(property(scene, "mode"), "look");
        assert_eq!(property(scene, "selected_sector"), "15");
        assert_eq!(property(scene, "hovered_sector"), "15");
        assert_eq!(
            property(scene, "camera_width"),
            &(planet_card.width.round().max(1.0) as i32).to_string()
        );
        assert_eq!(
            property(scene, "camera_height"),
            &(planet_card.height.round().max(1.0) as i32).to_string()
        );
        assert_eq!(
            property(scene, "projector_scaling"),
            &(1.0f32 / 150.0).to_string()
        );

        let step_properties = commands
            .iter()
            .filter_map(|command| custom_properties(command, "planet-renderer-scene-step"))
            .collect::<Vec<_>>();
        assert_eq!(
            property(scene, "step_count").parse::<usize>().unwrap(),
            step_properties.len()
        );
        let step_kinds = step_properties
            .iter()
            .map(|properties| property(properties, "kind"))
            .collect::<Vec<_>>();
        assert_eq!(step_kinds.first().copied(), Some("FlushDraw"));
        assert!(step_kinds.contains(&"BloomCapture"));
        assert!(step_kinds.contains(&"DrawSkybox"));
        assert!(step_kinds.contains(&"UniverseDraw"));
        assert!(step_kinds.contains(&"DrawPlanet"));
        assert!(step_kinds.contains(&"DrawClouds"));
        assert!(step_kinds.contains(&"DrawSectors"));
        assert!(step_kinds.contains(&"DrawAtmosphere"));
        assert!(step_kinds.contains(&"DrawOrbit"));
        assert!(step_kinds.contains(&"RenderOverProjections"));
        assert!(step_kinds.contains(&"BloomRender"));
        assert!(step_kinds.contains(&"RenderProjections"));
        assert_eq!(step_kinds.last().copied(), Some("CameraUpdate"));

        assert!(step_properties.iter().any(|properties| {
            property(properties, "kind") == "DrawSectors"
                && property(properties, "planet") == "serpulo"
        }));
        assert!(step_properties.iter().any(|properties| {
            property(properties, "kind") == "DrawSkybox"
                && property(properties, "cubemap") == "cubemaps/stars/"
        }));

        let preview_center = DesktopLauncher::campaign_planet_scene_preview_center(planet_card);
        let preview_radius = DesktopLauncher::campaign_planet_scene_preview_radius(planet_card);
        assert!(
            commands
                .iter()
                .any(|command| matches!(command, RenderCommand::DrawPixel { .. })),
            "DrawSkybox scene step should drive visible star pixels in the campaign planet preview"
        );
        assert!(
            commands.iter().any(|command| match command {
                RenderCommand::DrawCircle {
                    center,
                    radius,
                    filled,
                    ..
                } => *filled && *center == preview_center && close_f32(*radius, preview_radius),
                _ => false,
            }),
            "DrawPlanet scene step should drive a visible selected planet circle"
        );
        assert!(
            commands.iter().any(|command| match command {
                RenderCommand::DrawPolygon {
                    center,
                    radius,
                    filled,
                    ..
                } => {
                    !*filled
                        && *center == preview_center
                        && (close_f32(*radius, preview_radius * 1.035)
                            || close_f32(*radius, preview_radius * 1.36))
                }
                _ => false,
            }),
            "DrawClouds/DrawOrbit scene steps should drive visible polygon overlays"
        );
        assert!(
            commands.iter().any(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } => {
                    symbol == "circle-shadow" && planet_card.contains_point(rect.center())
                }
                _ => false,
            }),
            "RenderProjections scene step should drive visible sector icon sprites"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_projection_layer_renders_all_visible_sectors_like_java() {
        fn close_point(left: RenderPoint, right: RenderPoint) -> bool {
            (left.x - right.x).abs() <= 0.01 && (left.y - right.y).abs() <= 0.01
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        let dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("campaign route should create PlanetDialog state")
            .clone();

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let planet_card = DesktopLauncher::campaign_route_planet_card_rect(panel);
        let plan = launcher.campaign_route_planet_scene_plan(&dialog, planet_card);
        let selector_ids = launcher.campaign_route_sector_selector_ids(&dialog);
        let sector_ids =
            launcher.campaign_planet_projection_sector_ids_like_java(&dialog.planet_name);
        let planet = launcher
            .content_loader
            .catalog()
            .planet_by_name(&dialog.planet_name)
            .expect("campaign planet should exist in content catalog");
        let grid_ids = mindustry_core::mindustry::graphics::g3d::PlanetGrid::create(
            planet
                .sector_size
                .expect("Serpulo campaign planet should have a PlanetGrid sector size"),
        )
        .tiles
        .iter()
        .map(|tile| tile.id as i32)
        .collect::<Vec<_>>();
        assert!(
            sector_ids.len() > selector_ids.len(),
            "Java PlanetDialog.renderProjections iterates planet.sectors, not only selector buttons"
        );
        assert_eq!(
            &sector_ids[..grid_ids.len()],
            grid_ids.as_slice(),
            "projection ids should preserve PlanetGrid tile order like planet.sectors"
        );
        for preset_id in [15, 76, 101] {
            assert!(
                sector_ids.contains(&preset_id),
                "projection ids should include known Serpulo preset sector {preset_id}"
            );
        }

        let visible_sector_count = sector_ids
            .iter()
            .copied()
            .filter(|sector_id| {
                launcher
                    .campaign_planet_surface_sector_preview_point(
                        &dialog.planet_name,
                        *sector_id,
                        planet_card,
                        &plan,
                    )
                    .is_some()
            })
            .count();
        let (non_selector_sector_id, non_selector_projection) = sector_ids
            .iter()
            .copied()
            .find_map(|sector_id| {
                if selector_ids.contains(&sector_id)
                    || launcher
                        .campaign_sector_preset_by_id(&dialog.planet_name, sector_id)
                        .is_some()
                {
                    return None;
                }
                launcher
                    .campaign_planet_surface_sector_preview_point(
                        &dialog.planet_name,
                        sector_id,
                        planet_card,
                        &plan,
                    )
                    .map(|projection| (sector_id, projection))
            })
            .expect("Serpulo should expose visible numbered sectors beyond the selector ids");

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let circle_projection_centers = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == "circle-shadow" && planet_card.contains_point(rect.center()) =>
                {
                    Some(rect.center())
                }
                _ => None,
            })
            .collect::<Vec<_>>();

        assert!(
            visible_sector_count > selector_ids.len() * 4,
            "visible planet.sectors projection count should exceed the old 5-button selector subset"
        );
        assert!(
            circle_projection_centers.len() > selector_ids.len() * 4,
            "RenderProjections should emit visible primitives for the full sector projection layer"
        );
        assert!(
            circle_projection_centers
                .iter()
                .any(|position| close_point(*position, non_selector_projection)),
            "non-selector numbered sector #{non_selector_sector_id} should still be rendered by PlanetDialog.renderProjections"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_projection_debug_show_numbers_renders_preset_sector_ids_like_java(
    ) {
        fn close_point(left: RenderPoint, right: RenderPoint) -> bool {
            (left.x - right.x).abs() <= 0.01 && (left.y - right.y).abs() <= 0.01
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        let dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("campaign route should create PlanetDialog state")
            .clone();
        let debug_sector_id = dialog
            .selected_sector_id
            .expect("campaign route should start with a selected preset sector");

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let planet_card = DesktopLauncher::campaign_route_planet_card_rect(panel);
        let plan = launcher.campaign_route_planet_scene_plan(&dialog, planet_card);
        let debug_projection = launcher
            .campaign_planet_surface_sector_preview_point(
                &dialog.planet_name,
                debug_sector_id,
                planet_card,
                &plan,
            )
            .expect("selected preset sector should have a visible projection point");

        let default_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let default_numbers = default_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter(|command| match command {
                RenderCommand::DrawText {
                    text,
                    position,
                    style,
                    ..
                } => {
                    text == &debug_sector_id.to_string()
                        && style.font == RenderFontId::Outline
                        && close_point(*position, debug_projection)
                }
                _ => false,
            })
            .count();
        assert_eq!(
            default_numbers, 0,
            "PlanetDialog.debugShowNumbers defaults false and should not render sector id text"
        );

        launcher.campaign_debug_show_numbers = true;
        let debug_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let debug_numbers = debug_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText {
                    text,
                    position,
                    color,
                    size,
                    style,
                    ..
                } if text == &debug_sector_id.to_string()
                    && style.font == RenderFontId::Outline
                    && style.vertical_align == RenderTextVerticalAlign::Center
                    && close_point(*position, debug_projection) =>
                {
                    Some((*color, *size))
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            debug_numbers
                .iter()
                .any(|(color, size)| *color == [1.0, 1.0, 1.0, 0.96]
                    && (*size - 7.0).abs() <= 0.01),
            "PlanetDialog.debugShowNumbers should draw preset sector id #{debug_sector_id} with Fonts.outline at projection point; numbers={debug_numbers:?}"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_overprojection_draws_launcher_arc_like_java() {
        fn close_point(left: RenderPoint, right: RenderPoint) -> bool {
            (left.x - right.x).abs() <= 0.01 && (left.y - right.y).abs() <= 0.01
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let ground_zero = launcher
            .content_loader
            .sector_by_name("groundZero")
            .expect("base content should expose Ground Zero")
            .clone();
        let source_sector_id = ground_zero
            .sector_id
            .unwrap_or(ground_zero.original_position);
        let mut source_sector = Sector::new(source_sector_id);
        source_sector.preset = Some(ground_zero);
        source_sector.save_exists = true;
        source_sector.info.has_core = true;
        launcher.game_state.set_sector(Some(source_sector.clone()));
        launcher.runtime.state.set_sector(Some(source_sector));
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let planet_card = DesktopLauncher::campaign_route_planet_card_rect(panel);
        let base_dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("campaign route should create PlanetDialog state")
            .clone();
        let sector_ids =
            launcher.campaign_planet_projection_sector_ids_like_java(&base_dialog.planet_name);
        let (target_sector_id, source_projection, target_projection) = sector_ids
            .iter()
            .copied()
            .find_map(|candidate_id| {
                if candidate_id == source_sector_id
                    || launcher
                        .campaign_sector_preset_by_id(&base_dialog.planet_name, candidate_id)
                        .is_some()
                {
                    return None;
                }
                let mut candidate_dialog = base_dialog.clone();
                candidate_dialog.selected_sector_id = Some(candidate_id);
                candidate_dialog.hovered_sector_id = None;
                let candidate_plan =
                    launcher.campaign_route_planet_scene_plan(&candidate_dialog, planet_card);
                let source_projection = launcher.campaign_planet_surface_sector_preview_point(
                    &candidate_dialog.planet_name,
                    source_sector_id,
                    planet_card,
                    &candidate_plan,
                )?;
                let target_projection = launcher.campaign_planet_surface_sector_preview_point(
                    &candidate_dialog.planet_name,
                    candidate_id,
                    planet_card,
                    &candidate_plan,
                )?;
                let preset = launcher
                    .campaign_sector_preset_by_id(&candidate_dialog.planet_name, candidate_id);
                let runtime = launcher
                    .campaign_runtime_sector_by_id(&candidate_dialog.planet_name, candidate_id);
                launcher
                    .campaign_sector_can_select_like_java(&candidate_dialog, preset, runtime)
                    .then_some((candidate_id, source_projection, target_projection))
            })
            .expect("Serpulo should expose a visible numbered target sector launchable from Ground Zero");

        let mut dialog = base_dialog.clone();
        dialog.selected_sector_id = Some(target_sector_id);
        dialog.hovered_sector_id = None;
        launcher.campaign_planet_dialog = Some(dialog);

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let lines = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawLine { from, to, .. } => Some((*from, *to)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let preview_center = DesktopLauncher::campaign_planet_scene_preview_center(planet_card);

        assert!(
            lines.iter().any(|(from, to)| {
                close_point(*from, source_projection) && close_point(*to, target_projection)
            }),
            "PlanetDialog.renderOverProjections should draw from launcher sector #{source_sector_id} to target sector #{target_sector_id}; lines={lines:?}"
        );
        assert!(
            !lines
                .iter()
                .any(|(from, to)| close_point(*from, preview_center)
                    && close_point(*to, target_projection)),
            "over-projection should no longer use the old preview-center-to-marker line"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_overprojection_draws_import_export_arcs_like_java() {
        fn close_point(left: RenderPoint, right: RenderPoint) -> bool {
            (left.x - right.x).abs() <= 0.01 && (left.y - right.y).abs() <= 0.01
        }

        fn close_color(left: [f32; 4], right: [f32; 4]) -> bool {
            left.iter()
                .zip(right.iter())
                .all(|(left, right)| (*left - *right).abs() <= 0.001)
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let selected_preset = launcher
            .content_loader
            .sector_by_name("groundZero")
            .expect("base content should expose Ground Zero")
            .clone();
        let selected_sector_id = selected_preset
            .sector_id
            .unwrap_or(selected_preset.original_position);
        let mut selected_sector = Sector::new(selected_sector_id);
        selected_sector.preset = Some(selected_preset);
        selected_sector.save_exists = true;
        selected_sector.info.has_core = true;
        launcher.game_state.set_sector(Some(selected_sector));
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let planet_card = DesktopLauncher::campaign_route_planet_card_rect(panel);
        let base_dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("campaign route should create PlanetDialog state")
            .clone();
        let plan = launcher.campaign_route_planet_scene_plan(&base_dialog, planet_card);
        let selected_projection = launcher
            .campaign_planet_surface_sector_preview_point(
                &base_dialog.planet_name,
                selected_sector_id,
                planet_card,
                &plan,
            )
            .expect("selected Ground Zero sector should be visible in the planet preview");
        let (other_preset, other_sector_id, other_projection) = launcher
            .content_loader
            .sectors()
            .iter()
            .find_map(|preset| {
                if preset.planet_name.as_deref() != Some(base_dialog.planet_name.as_str()) {
                    return None;
                }
                let sector_id = preset.sector_id?;
                if sector_id == selected_sector_id {
                    return None;
                }
                launcher
                    .campaign_planet_surface_sector_preview_point(
                        &base_dialog.planet_name,
                        sector_id,
                        planet_card,
                        &plan,
                    )
                    .map(|projection| (preset.clone(), sector_id, projection))
            })
            .expect("Serpulo should expose another visible preset sector for import/export arcs");

        let mut selected_sector = launcher
            .game_state
            .get_sector()
            .expect("selected sector should still be in game state")
            .clone();
        selected_sector.info.destination = Some(other_sector_id.to_string());
        selected_sector.info.export.insert(
            "copper".into(),
            ExportStat {
                mean: 1.0,
                ..ExportStat::default()
            },
        );
        let mut other_sector = Sector::new(other_sector_id);
        other_sector.preset = Some(other_preset);
        other_sector.save_exists = true;
        other_sector.info.has_core = true;
        other_sector.info.destination = Some(selected_sector_id.to_string());
        other_sector.info.export.insert(
            "lead".into(),
            ExportStat {
                mean: 1.0,
                ..ExportStat::default()
            },
        );
        launcher.game_state.set_sector(Some(selected_sector));
        launcher.runtime.state.set_sector(Some(other_sector));
        if let Some(dialog) = launcher.campaign_planet_dialog.as_mut() {
            dialog.selected_sector_id = Some(selected_sector_id);
            dialog.hovered_sector_id = None;
        }

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let lines = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawLine {
                    from, to, color, ..
                } => Some((*from, *to, *color)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let import_color = [0.58, 0.62, 0.66, 0.58];
        let export_color = [0.68, 0.92, 0.76, 0.62];

        assert!(
            lines.iter().any(|(from, to, color)| {
                close_point(*from, other_projection)
                    && close_point(*to, selected_projection)
                    && close_color(*color, import_color)
            }),
            "PlanetDialog.renderOverProjections should draw import arc from sector #{other_sector_id} to selected sector #{selected_sector_id}; lines={lines:?}"
        );
        assert!(
            lines.iter().any(|(from, to, color)| {
                close_point(*from, selected_projection)
                    && close_point(*to, other_projection)
                    && close_color(*color, export_color)
            }),
            "PlanetDialog.renderOverProjections should draw export arc from selected sector #{selected_sector_id} to sector #{other_sector_id}; lines={lines:?}"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_overprojection_draws_shield_arcs_like_java() {
        fn close_point(left: RenderPoint, right: RenderPoint) -> bool {
            (left.x - right.x).abs() <= 0.01 && (left.y - right.y).abs() <= 0.01
        }

        fn close_color(left: [f32; 4], right: [f32; 4]) -> bool {
            left.iter()
                .zip(right.iter())
                .all(|(left, right)| (*left - *right).abs() <= 0.001)
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let target_preset = launcher
            .content_loader
            .sectors()
            .iter()
            .find(|preset| {
                preset.planet_name.as_deref() == Some("serpulo")
                    && !preset.shield_sector_ids.is_empty()
            })
            .expect("Serpulo content should expose a shielded sector preset")
            .clone();
        let target_sector_id = target_preset
            .sector_id
            .expect("shielded preset should be assigned to a planet sector");
        let mut target_sector = Sector::new(target_sector_id);
        target_sector.preset = Some(target_preset.clone());
        target_sector.save_exists = true;
        target_sector.info.has_core = true;
        launcher.game_state.set_sector(Some(target_sector));
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let planet_card = DesktopLauncher::campaign_route_planet_card_rect(panel);
        let base_dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("campaign route should create PlanetDialog state")
            .clone();
        let mut match_projection = None;
        let mut camera_ids = vec![target_sector_id];
        camera_ids.extend(target_preset.shield_sector_ids.iter().copied());
        camera_ids.extend(launcher.campaign_planet_projection_sector_ids_like_java("serpulo"));
        'source: for source_sector_id in target_preset.shield_sector_ids.iter().copied() {
            for camera_id in camera_ids.iter().copied() {
                let mut dialog = base_dialog.clone();
                dialog.selected_sector_id = Some(camera_id);
                dialog.hovered_sector_id = None;
                let plan = launcher.campaign_route_planet_scene_plan(&dialog, planet_card);
                let Some(source_projection) = launcher
                    .campaign_planet_surface_sector_preview_point(
                        &dialog.planet_name,
                        source_sector_id,
                        planet_card,
                        &plan,
                    )
                else {
                    continue;
                };
                let Some(target_projection) = launcher
                    .campaign_planet_surface_sector_preview_point(
                        &dialog.planet_name,
                        target_sector_id,
                        planet_card,
                        &plan,
                    )
                else {
                    continue;
                };
                match_projection = Some((
                    source_sector_id,
                    camera_id,
                    source_projection,
                    target_projection,
                ));
                break 'source;
            }
        }
        let (source_sector_id, camera_id, source_projection, target_projection) = match_projection
            .expect("a shield source and its target should be visible from at least one planet preview camera");
        if let Some(dialog) = launcher.campaign_planet_dialog.as_mut() {
            dialog.selected_sector_id = Some(camera_id);
            dialog.hovered_sector_id = None;
        }

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let lines = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawLine {
                    from, to, color, ..
                } => Some((*from, *to, *color)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let shield_color = super::rgba8888_to_render_color(0xf25555ff, 0.62);

        assert!(
            lines.iter().any(|(from, to, color)| {
                close_point(*from, source_projection)
                    && close_point(*to, target_projection)
                    && close_color(*color, shield_color)
            }),
            "PlanetDialog.renderOverProjections should draw shield arc from sector #{source_sector_id} to shield target #{target_sector_id}; lines={lines:?}"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_overprojection_draws_attack_arcs_like_java() {
        fn close_point(left: RenderPoint, right: RenderPoint) -> bool {
            (left.x - right.x).abs() <= 0.01 && (left.y - right.y).abs() <= 0.01
        }

        fn close_color(left: [f32; 4], right: [f32; 4]) -> bool {
            left.iter()
                .zip(right.iter())
                .all(|(left, right)| (*left - *right).abs() <= 0.001)
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let planet_card = DesktopLauncher::campaign_route_planet_card_rect(panel);
        let mut match_projection = None;
        let base_dialog = super::CampaignPlanetDialogState {
            planet_name: "serpulo".into(),
            mode: super::CampaignPlanetDialogMode::Look,
            selected_sector_id: None,
            hovered_sector_id: None,
            launch_sector_id: None,
            launch_candidate_planet_names: Vec::new(),
            new_preset_sector_ids: Vec::new(),
        };
        let presets = launcher.content_loader.sectors().to_vec();
        'base: for base_preset in presets.iter().filter(|preset| {
            preset.planet_name.as_deref() == Some("serpulo") && preset.sector_id.is_some()
        }) {
            let base_sector_id = base_preset.sector_id.unwrap();
            for enemy_sector_id in
                launcher.campaign_planet_neighbor_sector_ids_like_java("serpulo", base_sector_id)
            {
                let Some(enemy_preset) =
                    launcher.campaign_sector_preset_by_id("serpulo", enemy_sector_id)
                else {
                    continue;
                };
                if enemy_preset.capture_wave != 0 || enemy_preset.require_unlock {
                    continue;
                }
                let mut dialog = base_dialog.clone();
                dialog.selected_sector_id = Some(base_sector_id);
                let plan = launcher.campaign_route_planet_scene_plan(&dialog, planet_card);
                let Some(enemy_projection) = launcher.campaign_planet_surface_sector_preview_point(
                    &dialog.planet_name,
                    enemy_sector_id,
                    planet_card,
                    &plan,
                ) else {
                    continue;
                };
                let Some(base_projection) = launcher.campaign_planet_surface_sector_preview_point(
                    &dialog.planet_name,
                    base_sector_id,
                    planet_card,
                    &plan,
                ) else {
                    continue;
                };
                match_projection = Some((
                    base_preset.clone(),
                    base_sector_id,
                    enemy_sector_id,
                    enemy_projection,
                    base_projection,
                ));
                break 'base;
            }
        }
        let (
            base_preset,
            base_sector_id,
            enemy_sector_id,
            enemy_projection,
            base_projection,
        ) = match_projection.expect(
            "Serpulo content should expose a visible base sector adjacent to an enemy base sector",
        );
        let mut base_sector = Sector::new(base_sector_id);
        base_sector.preset = Some(base_preset);
        base_sector.save_exists = true;
        base_sector.info.has_core = true;
        base_sector.info.waves = false;
        base_sector.info.attack = false;
        launcher.game_state.set_sector(Some(base_sector));
        launcher.campaign_rules_by_planet.insert(
            "serpulo".into(),
            mindustry_core::mindustry::game::CampaignRules {
                sector_invasion: true,
                ..mindustry_core::mindustry::game::CampaignRules::default()
            },
        );
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        if let Some(dialog) = launcher.campaign_planet_dialog.as_mut() {
            dialog.selected_sector_id = Some(base_sector_id);
            dialog.hovered_sector_id = None;
        }

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let lines = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawLine {
                    from, to, color, ..
                } => Some((*from, *to, *color)),
                _ => None,
            })
            .collect::<Vec<_>>();
        let attack_color = super::rgba8888_to_render_color(0xf25555ff, 0.50);

        assert!(
            lines.iter().any(|(from, to, color)| {
                close_point(*from, enemy_projection)
                    && close_point(*to, base_projection)
                    && close_color(*color, attack_color)
            }),
            "PlanetDialog.renderOverProjections should draw attack arc from enemy sector #{enemy_sector_id} to vulnerable base sector #{base_sector_id}; lines={lines:?}"
        );

        let vulnerable_label = launcher.localize_bundle_markup_text("@sectors.vulnerable");
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            texts.contains(&vulnerable_label.as_str()),
            "PlanetDialog.updateSelected should show @sectors.vulnerable for a base neighboring an enemy base; texts={texts:?}"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_selected_panel_status_rows_follow_update_selected_like_java()
    {
        fn draw_texts(launcher: &mut DesktopLauncher, viewport: RenderViewport) -> Vec<String> {
            launcher
                .menu_graphics_frame_for_surface(0, viewport)
                .bundle
                .render_frame
                .as_ref()
                .expect("campaign frame should contain render frame")
                .passes
                .iter()
                .flat_map(|pass| pass.commands.iter())
                .filter_map(|command| match command {
                    RenderCommand::DrawText { text, .. } => Some(text.clone()),
                    _ => None,
                })
                .collect()
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let enemy_preset = launcher
            .content_loader
            .sectors()
            .iter()
            .find(|preset| {
                preset.planet_name.as_deref() == Some("serpulo")
                    && preset.sector_id.is_some()
                    && preset.capture_wave == 0
                    && !preset.require_unlock
            })
            .expect("Serpulo content should expose an unlocked enemy base sector")
            .clone();
        let enemy_id = enemy_preset
            .sector_id
            .expect("enemy base preset should have a sector id");

        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        launcher
            .campaign_planet_dialog
            .as_mut()
            .expect("Campaign route should build PlanetDialog state")
            .selected_sector_id = Some(enemy_id);
        let texts = draw_texts(&mut launcher, viewport);
        let threat_label = launcher.localize_bundle_markup_text("@sectors.threat");
        let underattack_label = launcher.localize_bundle_markup_text("@sectors.underattack");
        let enemy_base_label = launcher.localize_bundle_markup_text("@sectors.enemybase");
        assert!(
            texts
                .iter()
                .any(|text| text.starts_with(&format!("{threat_label} [accent]"))),
            "unbased enemy sectors should keep Java updateSelected threat row; texts={texts:?}"
        );
        assert!(
            texts.contains(&enemy_base_label),
            "unbased enemy sectors should render @sectors.enemybase; texts={texts:?}"
        );
        assert!(
            !texts.contains(&underattack_label),
            "enemybase is an else-if branch and must not imply @sectors.underattack"
        );

        let ground_zero = launcher
            .content_loader
            .sector_by_name("groundZero")
            .expect("base content should expose Ground Zero")
            .clone();
        let mut attacked = Sector::new(15);
        attacked.preset = Some(ground_zero);
        attacked.save_exists = true;
        attacked.info.has_core = true;
        attacked.info.waves = true;
        launcher.game_state.set_sector(Some(attacked.clone()));
        launcher.runtime.state.set_sector(Some(attacked));
        launcher.campaign_planet_dialog = Some(super::CampaignPlanetDialogState {
            planet_name: "serpulo".into(),
            mode: super::CampaignPlanetDialogMode::Look,
            selected_sector_id: Some(15),
            hovered_sector_id: None,
            launch_sector_id: None,
            launch_candidate_planet_names: Vec::new(),
            new_preset_sector_ids: Vec::new(),
        });
        let texts = draw_texts(&mut launcher, viewport);
        assert!(
            texts.contains(&underattack_label),
            "attacked base sectors should render @sectors.underattack; texts={texts:?}"
        );
        assert!(
            !texts.contains(&enemy_base_label),
            "Java updateSelected chooses underattack before enemybase"
        );
        assert!(
            !texts
                .iter()
                .any(|text| text.starts_with(&format!("{threat_label} [accent]"))),
            "attacked base sectors keep threat in showStats(), not in the selected-sector card"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_renders_planetdialog_like_sector_stats() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let preset = launcher
            .content_loader
            .sector_by_name("groundZero")
            .expect("base content should expose Ground Zero")
            .clone();
        let mut sector = Sector::new(15);
        sector.preset = Some(preset);
        sector.save_exists = true;
        sector.info.has_core = true;
        sector.info.resources = vec!["copper".into(), "lead".into()];
        sector.info.items = vec![("copper".into(), 300), ("silicon".into(), 50)];
        sector.info.production.insert(
            "copper".into(),
            ExportStat {
                mean: 1.25,
                ..ExportStat::default()
            },
        );
        sector.info.export.insert(
            "lead".into(),
            ExportStat {
                mean: 0.75,
                ..ExportStat::default()
            },
        );
        sector.info.imports.insert(
            "silicon".into(),
            ExportStat {
                mean: 0.50,
                ..ExportStat::default()
            },
        );
        sector.info.attempts = 3;
        sector.info.minutes_captured = 135.0;
        sector.info.wave = 12;
        sector.info.waves = true;
        sector.threat = 0.62;
        launcher.game_state.set_sector(Some(sector.clone()));
        launcher.runtime.state.set_sector(Some(sector));
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign route should render PlanetDialog body")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();

        let threat_line = format!(
            "{} [accent]{}",
            launcher.localize_bundle_markup_text("@sectors.threat"),
            launcher.localize_bundle_markup_text("@threat.high")
        );
        let wave_line = format!(
            "{} [accent]12",
            launcher.localize_bundle_markup_text("@sectors.wave")
        );
        let resources_line = format!(
            "{} [accent]Copper, Lead",
            launcher.localize_bundle_markup_text("@sectors.resources")
        );
        let stats_label = launcher.localize_bundle_markup_text("@stats");
        assert!(
            !texts.contains(&threat_line.as_str()),
            "PlanetDialog.updateSelected should not show threat on an unattacked sector with a base; texts={texts:?}"
        );
        assert!(
            !texts.contains(&wave_line.as_str()),
            "PlanetDialog.updateSelected should keep wave details in the stats dialog, not the selected-sector card"
        );
        assert!(texts.contains(&resources_line.as_str()));
        assert!(texts.contains(&stats_label.as_str()));
        for raw_key in [
            "@stats",
            "@sectors.threat",
            "@sectors.wave",
            "@sectors.resources",
            "@sector.abandon",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "PlanetDialog sector card final DrawText should localize {raw_key} before rendering"
            );
        }

        let route_lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Campaign);
        assert!(!route_lines.contains(&threat_line));
        assert!(!route_lines.contains(&wave_line));
        assert!(route_lines.contains(&resources_line));
        assert!(route_lines.contains(&format!("button: {stats_label}")));

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let stats_center = DesktopLauncher::campaign_route_stats_button_rect(
            DesktopLauncher::campaign_route_sector_card_rect(panel),
        )
        .center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                stats_center.x,
                stats_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenCampaignSectorStats)
        );

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenCampaignSectorStats,
        );
        assert!(launcher.campaign_sector_stats_dialog_open);
        let frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let dialog_texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign stats dialog should render over PlanetDialog")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let time_line = format!(
            "{} [accent]2h 15m",
            launcher.localize_bundle_markup_text("@sectors.time")
        );
        let attempts_line = format!(
            "{} [accent]3",
            launcher.localize_bundle_markup_text("@sectors.attempts")
        );
        assert!(
            dialog_texts.contains(&time_line.as_str()),
            "PlanetDialog showStats should render sector time; texts={dialog_texts:?}"
        );
        assert!(dialog_texts.contains(&attempts_line.as_str()));
        assert!(dialog_texts.contains(&wave_line.as_str()));
        assert!(dialog_texts.contains(
            &launcher
                .localize_bundle_markup_text("@sectors.resources")
                .as_str()
        ));
        assert!(dialog_texts.contains(
            &launcher
                .localize_bundle_markup_text("@sectors.production")
                .as_str()
        ));
        assert!(dialog_texts.contains(
            &launcher
                .localize_bundle_markup_text("@sectors.export")
                .as_str()
        ));
        assert!(dialog_texts.contains(
            &launcher
                .localize_bundle_markup_text("@sectors.import")
                .as_str()
        ));
        assert!(dialog_texts.contains(
            &launcher
                .localize_bundle_markup_text("@sectors.stored")
                .as_str()
        ));
        assert!(dialog_texts.contains(
            &launcher
                .localize_bundle_markup_text("@sector.abandon")
                .as_str()
        ));
        for raw_key in [
            "@stats",
            "@sectors.time",
            "@sectors.attempts",
            "@sectors.wave",
            "@sectors.resources",
            "@sectors.production",
            "@sectors.export",
            "@sectors.import",
            "@sectors.stored",
            "@sector.abandon",
        ] {
            assert!(
                !dialog_texts.iter().any(|text| text.contains(raw_key)),
                "PlanetDialog stats dialog final DrawText should localize {raw_key} before rendering"
            );
        }

        let dialog = DesktopLauncher::campaign_sector_stats_dialog_rect(panel);
        let close_center = DesktopLauncher::campaign_sector_stats_close_rect(dialog).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                close_center.x,
                close_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::CloseCampaignSectorStats)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::CloseCampaignSectorStats,
        );
        assert!(!launcher.campaign_sector_stats_dialog_open);
    }

    #[test]
    fn desktop_launcher_campaign_route_uses_large_icons_like_java_for_sector_states() {
        fn insert_icon_region(atlas: &mut TextureAtlasPlan<bool>, name: &'static str) {
            let _ = atlas.insert_or_replace_region(
                PageType::Ui,
                TextureAtlasRegion::new(
                    PageType::Ui,
                    name,
                    format!("sprites/{name}.png"),
                    0,
                    0,
                    32,
                    32,
                    true,
                ),
            );
        }

        fn has_large_icon_command(
            commands: &[RenderCommand],
            name: &str,
            rect: RenderRect,
        ) -> bool {
            let expected_glyph = super::desktop_iconc_glyph_by_name_like_java(name)
                .and_then(|glyph| char::from_u32(glyph.codepoint))
                .map(|character| character.to_string());
            commands.iter().any(|command| match command {
                RenderCommand::DrawSprite {
                    symbol,
                    rect: command_rect,
                    ..
                } => symbol == name && *command_rect == rect,
                RenderCommand::DrawText {
                    text,
                    position,
                    style,
                    ..
                } => {
                    style.font == RenderFontId::IconLarge
                        && expected_glyph.as_ref() == Some(text)
                        && *position == rect.center()
                }
                _ => false,
            })
        }

        fn campaign_commands(
            launcher: &mut DesktopLauncher,
            viewport: RenderViewport,
        ) -> Vec<RenderCommand> {
            let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
            frame
                .bundle
                .render_frame
                .as_ref()
                .expect("Campaign frame should render")
                .passes
                .iter()
                .flat_map(|pass| pass.commands.iter())
                .cloned()
                .collect()
        }

        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.texture_atlas = Arc::new(TextureAtlasPlan::new());
        insert_icon_region(Arc::make_mut(&mut launcher.texture_atlas), "warning");
        insert_icon_region(Arc::make_mut(&mut launcher.texture_atlas), "terrain");
        insert_icon_region(Arc::make_mut(&mut launcher.texture_atlas), "lock");
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let icon_rect = DesktopLauncher::campaign_route_sector_large_icon_rect(
            DesktopLauncher::campaign_route_sector_card_rect(panel),
        );

        let ground_zero = launcher
            .content_loader
            .sector_by_name("groundZero")
            .expect("base content should expose Ground Zero")
            .clone();
        let mut attacked = Sector::new(15);
        attacked.preset = Some(ground_zero.clone());
        attacked.save_exists = true;
        attacked.info.has_core = true;
        attacked.info.waves = true;
        attacked.info.icon = Some("play".into());
        launcher.game_state.set_sector(Some(attacked.clone()));
        launcher.runtime.state.set_sector(Some(attacked));
        launcher.campaign_planet_dialog = Some(super::CampaignPlanetDialogState {
            planet_name: "serpulo".into(),
            mode: super::CampaignPlanetDialogMode::Look,
            selected_sector_id: Some(15),
            hovered_sector_id: None,
            launch_sector_id: None,
            launch_candidate_planet_names: Vec::new(),
            new_preset_sector_ids: vec![15],
        });
        let commands = campaign_commands(&mut launcher, viewport);
        assert!(
            has_large_icon_command(&commands, "warning", icon_rect),
            "PlanetDialog.renderProjections should route attacked sectors through Fonts.getLargeIcon(\"warning\")"
        );

        launcher.game_state.set_sector(None);
        launcher.runtime.state.set_sector(None);
        launcher.campaign_planet_dialog = Some(super::CampaignPlanetDialogState {
            planet_name: "serpulo".into(),
            mode: super::CampaignPlanetDialogMode::Look,
            selected_sector_id: Some(15),
            hovered_sector_id: None,
            launch_sector_id: None,
            launch_candidate_planet_names: Vec::new(),
            new_preset_sector_ids: vec![15],
        });
        let commands = campaign_commands(&mut launcher, viewport);
        assert!(
            has_large_icon_command(&commands, "terrain", icon_rect),
            "unbased unlocked preset sectors should use the Java terrain large icon fallback"
        );

        let salt_flats_id = launcher
            .content_loader
            .sector_by_name("saltFlats")
            .and_then(|sector| sector.sector_id)
            .expect("base content should expose Salt Flats id");
        launcher.campaign_planet_dialog = Some(super::CampaignPlanetDialogState {
            planet_name: "serpulo".into(),
            mode: super::CampaignPlanetDialogMode::Look,
            selected_sector_id: Some(salt_flats_id),
            hovered_sector_id: None,
            launch_sector_id: None,
            launch_candidate_planet_names: Vec::new(),
            new_preset_sector_ids: vec![15],
        });
        let commands = campaign_commands(&mut launcher, viewport);
        assert!(
            has_large_icon_command(&commands, "lock", icon_rect),
            "locked preset sectors should use Fonts.getLargeIcon(\"lock\") rather than a small icon/text fallback"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_opens_sector_submission_link_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        let preset = launcher
            .content_loader
            .sector_by_name("sector-serpulo-76")
            .expect("base content should expose hidden Serpulo sector submissions")
            .clone();
        let mut sector = Sector::new(76);
        sector.preset = Some(preset);
        sector.save_exists = true;
        sector.info.has_core = true;
        sector.generate_enemy_base = true;
        launcher.game_state.set_sector(Some(sector.clone()));
        launcher.runtime.state.set_sector(Some(sector));
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        launcher
            .campaign_planet_dialog
            .as_mut()
            .expect("Campaign route should build PlanetDialog state")
            .selected_sector_id = Some(76);

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let submission_label = launcher.localize_bundle_markup_text("@sectors.viewsubmission");
        let hidden_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let hidden_texts = hidden_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign route should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            !hidden_texts.contains(&submission_label.as_str()),
            "Vars.showSectorSubmissions=false should hide Java @sectors.viewsubmission"
        );

        launcher.campaign_show_sector_submissions = true;
        let visible_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let visible_texts = visible_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign route should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            visible_texts.contains(&submission_label.as_str()),
            "Java PlanetDialog adds @sectors.viewsubmission when showSectorSubmissions is enabled"
        );
        assert!(
            !hidden_texts
                .iter()
                .any(|text| text.contains("@sectors.viewsubmission")),
            "hidden Campaign submission button must not leak raw @sectors.viewsubmission"
        );
        assert!(
            !visible_texts
                .iter()
                .any(|text| text.contains("@sectors.viewsubmission")),
            "Campaign submission button final DrawText should localize @sectors.viewsubmission before rendering"
        );

        let route_lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Campaign);
        assert!(route_lines
            .iter()
            .any(|line| line.starts_with("button: @sectors.viewsubmission ")));

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let submission_center =
            DesktopLauncher::campaign_route_submission_button_rect(panel).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                submission_center.x,
                submission_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenCampaignSectorSubmission(76))
        );

        let mut platform = RecordingPlatform {
            open_result: true,
            ..RecordingPlatform::default()
        };
        let action = launcher
            .dispatch_campaign_sector_submission_action_with_platform(76, &mut platform)
            .expect("enabled sector submission should dispatch openURI");
        assert_eq!(action.sector_id, 76);
        assert_eq!(
            action.uri,
            "https://discord.com/channels/391020510269669376/1379926833411391580/1479890094486716499"
        );
        assert!(action.opened);
        assert_eq!(platform.opened_uris, vec![action.uri.clone()]);
        assert_eq!(
            launcher.last_campaign_sector_submission_action,
            Some(action)
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_shows_initial_campaign_select_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);

        launcher.dispatch_menu_action(MenuButtonRole::Campaign);

        assert!(launcher.campaign_intro_select_dialog_open);
        assert_eq!(launcher.campaign_intro_selected_planet, None);
        assert_eq!(
            launcher
                .settings_overrides
                .get(super::CAMPAIGN_SELECT_SETTINGS_KEY),
            None,
            "Java only writes campaignselect after @ok confirms a planet"
        );
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Campaign);
        assert!(lines.contains(&"dialog: @campaign.select".to_string()));
        assert!(lines.contains(&"button: @campaign.serpulo".to_string()));
        assert!(lines.contains(&"button: @campaign.erekir".to_string()));

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign select dialog should render over PlanetDialog")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@campaign.select")
                .as_str()
        ));
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@campaign.none")
                .as_str()
        ));
        assert!(texts
            .iter()
            .any(|text| text.eq_ignore_ascii_case("serpulo")));
        assert!(texts.iter().any(|text| text.eq_ignore_ascii_case("erekir")));
        for raw_key in ["@campaign.select", "@campaign.none", "@campaign.serpulo"] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "Campaign select dialog final DrawText should localize {raw_key} before rendering"
            );
        }

        let dialog = DesktopLauncher::campaign_intro_select_dialog_rect(viewport);
        let serpulo_button = DesktopLauncher::campaign_intro_planet_button_rect(dialog, 0);
        let erekir_button = DesktopLauncher::campaign_intro_planet_button_rect(dialog, 1);
        assert_eq!(
            serpulo_button.width, serpulo_button.height,
            "Java PlanetDialog campaign select uses square planet texture buttons"
        );
        assert_eq!(
            erekir_button.width, erekir_button.height,
            "Java PlanetDialog campaign select uses square planet texture buttons"
        );
        assert!(
            (serpulo_button.width - 320.0).abs() < f32::EPSILON,
            "desktop Java campaign select planet buttons are 320x320"
        );
        assert!(
            commands.iter().copied().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == "sprites/planets/serpulo.png"
                        && serpulo_button.contains_point(rect.center())
            )),
            "Java PlanetDialog uses the upstream Serpulo planet texture, not a circular placeholder"
        );
        assert!(
            commands.iter().copied().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == "sprites/planets/erekir.png"
                        && erekir_button.contains_point(rect.center())
            )),
            "Java PlanetDialog uses the upstream Erekir planet texture, not a circular placeholder"
        );
        let ok_center = DesktopLauncher::campaign_intro_select_ok_rect(dialog).center();
        assert_eq!(
            DesktopLauncher::campaign_intro_select_ok_rect(dialog).height,
            64.0,
            "Java PlanetDialog campaign select @ok button is 300x64"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                ok_center.x,
                ok_center.y
            ),
            None,
            "Java disables @ok until a starting campaign is selected"
        );

        let serpulo_center = serpulo_button.center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                serpulo_center.x,
                serpulo_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::SelectCampaignIntroSerpulo)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::SelectCampaignIntroSerpulo,
        );
        assert_eq!(launcher.campaign_intro_selected_planet, Some("serpulo"));
        let selected_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let selected_texts = selected_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign select choice should render description")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(selected_texts.contains(
            &launcher
                .localize_bundle_markup_text("@campaign.serpulo")
                .as_str()
        ));
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                ok_center.x,
                ok_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::ConfirmCampaignIntroPlanet)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ConfirmCampaignIntroPlanet,
        );

        assert!(!launcher.campaign_intro_select_dialog_open);
        assert_eq!(launcher.campaign_intro_selected_planet, None);
        assert_eq!(
            launcher
                .settings_overrides
                .get(super::CAMPAIGN_SELECT_SETTINGS_KEY),
            Some(&"true".to_string())
        );
        assert_eq!(launcher.game_state.rules.planet, "serpulo");
        assert_eq!(launcher.runtime.state.rules.planet, "serpulo");
        let campaign_dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("confirm should rebuild Campaign PlanetDialog on selected planet");
        assert_eq!(campaign_dialog.planet_name, "serpulo");
        assert_eq!(campaign_dialog.selected_sector_id, Some(15));

        launcher.show_campaign_intro_dialogs_like_java();
        assert!(
            !launcher.campaign_intro_select_dialog_open,
            "campaignselect getBool should suppress repeated starting campaign dialog"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_back_key_clears_selected_sector_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::Campaign)
        );
        {
            let dialog = launcher
                .campaign_planet_dialog
                .as_mut()
                .expect("Campaign should show PlanetDialog");
            dialog.new_preset_sector_ids = vec![15, 101, 175];
            dialog.selected_sector_id = Some(101);
        }

        assert!(launcher.apply_menu_back_key());
        let dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("PlanetDialog should stay open after truncating new presets");
        assert_eq!(
            dialog.new_preset_sector_ids,
            vec![15],
            "Java PlanetDialog back first truncates newPresets to one entry"
        );
        assert_eq!(
            dialog.selected_sector_id,
            Some(101),
            "Java PlanetDialog selection should survive the newPresets truncation back step"
        );
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::Campaign)
        );

        assert!(launcher.apply_menu_back_key());
        let dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("PlanetDialog should stay open after clearing selection");
        assert_eq!(
            dialog.selected_sector_id, None,
            "Java PlanetDialog back should call selectSector(null) before hiding the dialog"
        );
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::Campaign)
        );

        assert!(launcher.apply_menu_back_key());
        assert_eq!(
            launcher.active_menu_route, None,
            "only after no new presets and no selected sector should Campaign route close"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_new_presets_announce_and_rotate_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        {
            let dialog = launcher
                .campaign_planet_dialog
                .as_mut()
                .expect("Campaign should show PlanetDialog");
            dialog.planet_name = "serpulo".into();
            dialog.new_preset_sector_ids = vec![15, 101];
            dialog.selected_sector_id = Some(15);
        }
        {
            let state = launcher.net_client.state();
            let mut state = state.lock().unwrap();
            state.last_announcement = None;
        }

        launcher.tick_campaign_planet_new_presets_like_java(
            super::CAMPAIGN_PLANET_PRESET_ANNOUNCE_DELAY_TICKS_LIKE_JAVA - 1.0,
        );
        assert!(
            launcher
                .net_client
                .state()
                .lock()
                .unwrap()
                .last_announcement
                .is_none(),
            "Java PlanetDialog waits 20 ticks before announcing a new preset"
        );

        launcher.tick_campaign_planet_new_presets_like_java(1.0);
        let announcement = launcher
            .net_client
            .state()
            .lock()
            .unwrap()
            .last_announcement
            .clone()
            .expect("new preset should announce exactly when presetShow reaches 20f");
        let lock_open = upstream_ui_icon_glyph_string("lockOpen")
            .expect("Iconc.lockOpen should have an upstream UI glyph");
        let announced_name = launcher.campaign_sector_display_name_for_id("serpulo", 101);
        assert!(
            announcement.contains(&lock_open) && announcement.contains(&announced_name),
            "Java PlanetDialog announce should use Iconc.lockOpen and the current new preset name; got {announcement:?}"
        );
        assert!(launcher.campaign_planet_preset_showed);

        {
            let state = launcher.net_client.state();
            let mut state = state.lock().unwrap();
            state.last_announcement = None;
        }
        launcher.tick_campaign_planet_new_presets_like_java(1.0);
        assert!(
            launcher
                .net_client
                .state()
                .lock()
                .unwrap()
                .last_announcement
                .is_none(),
            "Java PlanetDialog showed flag prevents repeated announces during the same preset window"
        );

        let remaining = super::CAMPAIGN_PLANET_SECTOR_SHOW_DURATION_TICKS_LIKE_JAVA
            - launcher.campaign_planet_preset_show
            + 1.0;
        launcher.tick_campaign_planet_new_presets_like_java(remaining);
        let dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("PlanetDialog should stay open after rotating new presets");
        assert_eq!(
            dialog.new_preset_sector_ids,
            vec![15],
            "Java PlanetDialog pops the peeked new preset after sectorShowDuration"
        );
        assert_eq!(launcher.campaign_planet_preset_show, 0.0);
        assert!(!launcher.campaign_planet_preset_showed);
    }

    #[test]
    fn desktop_launcher_campaign_route_shows_serpulo_rework_notice_once_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        launcher.campaign_had_serpulo_remaps = true;

        launcher.dispatch_menu_action(MenuButtonRole::Campaign);

        assert!(launcher.campaign_serpulo_rework_notice_open);
        assert_eq!(
            launcher
                .settings_overrides
                .get(super::SERPULO_REMAPS_NOTICE_SETTINGS_KEY),
            Some(&"true".to_string()),
            "Java settings.getBoolOnce(\"serpulo-remaps-notice\") should mark the notice as seen"
        );
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Serpulo rework notice should render over Campaign")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@campaign.rework.title")
                .as_str()
        ));
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@campaign.rework.serpulo")
                .as_str()
        ));
        for raw_key in ["@campaign.rework.title", "@campaign.rework.serpulo"] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "Serpulo rework notice final DrawText should localize {raw_key} before rendering"
            );
        }
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let dialog = DesktopLauncher::campaign_serpulo_rework_notice_dialog_rect(panel);
        let ok_center = DesktopLauncher::campaign_serpulo_rework_notice_ok_rect(dialog).center();
        assert_eq!(
            DesktopLauncher::campaign_serpulo_rework_notice_ok_rect(dialog).height,
            64.0,
            "Java Serpulo rework notice @ok button is 280x64"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                ok_center.x,
                ok_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::CloseCampaignSerpuloReworkNotice)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::CloseCampaignSerpuloReworkNotice,
        );
        assert!(!launcher.campaign_serpulo_rework_notice_open);

        launcher.show_campaign_intro_dialogs_like_java();
        assert!(
            !launcher.campaign_serpulo_rework_notice_open,
            "serpulo-remaps-notice getBoolOnce should suppress repeated notice"
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_planet_buttons_switch_planets_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);

        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        let initial_dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("Campaign route should build PlanetDialog state")
            .clone();
        assert_eq!(initial_dialog.planet_name, "serpulo");
        let planet_names = launcher.campaign_selectable_planet_names_like_java(&initial_dialog);
        assert!(
            planet_names.iter().any(|name| name == "erekir"),
            "Java PlanetDialog planet selection should expose always-unlocked landable Erekir"
        );
        assert!(
            planet_names.iter().any(|name| name == "serpulo"),
            "Java PlanetDialog planet selection should expose always-unlocked landable Serpulo"
        );
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Campaign);
        assert!(lines.contains(&"planet button: erekir".to_string()));
        assert!(lines.contains(&"planet button: serpulo".to_string()));

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign route should render planet selector buttons")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&"erekir"));
        assert!(texts.contains(&"serpulo"));

        let erekir_index = planet_names
            .iter()
            .position(|name| name == "erekir")
            .expect("Erekir should be selectable");
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let erekir_center =
            DesktopLauncher::campaign_route_planet_button_rect(panel, erekir_index).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                erekir_center.x,
                erekir_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::SelectCampaignPlanet(
                erekir_index
            ))
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::SelectCampaignPlanet(erekir_index),
        );

        let switched = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("selecting a planet should rebuild PlanetDialog state");
        assert_eq!(switched.planet_name, "erekir");
        assert_ne!(
            switched.selected_sector_id,
            initial_dialog.selected_sector_id
        );
        assert_eq!(launcher.campaign_sector_list_open, false);
        assert_eq!(
            launcher.last_menu_route_shell_action,
            Some(super::DesktopMenuRouteShellAction::SelectCampaignPlanet(
                erekir_index
            ))
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_launch_mode_hides_rules_and_sectorlist_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        let ground_zero = launcher
            .content_loader
            .sector_by_name("groundZero")
            .expect("base content should expose groundZero")
            .clone();
        let mut runtime_sector = Sector::new(
            ground_zero
                .sector_id
                .unwrap_or(ground_zero.original_position),
        );
        runtime_sector.preset = Some(ground_zero);
        runtime_sector.save_exists = true;
        runtime_sector.info.has_core = true;
        launcher.game_state.set_sector(Some(runtime_sector.clone()));
        launcher.runtime.state.set_sector(Some(runtime_sector));
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        let look_dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("Campaign route should create PlanetDialog")
            .clone();
        assert!(
            !launcher
                .campaign_sector_list_base_entries(&look_dialog)
                .is_empty(),
            "test setup should make Java sectorlist visible before planetLaunch mode"
        );

        launcher.campaign_sector_list_open = true;
        launcher.show_campaign_planet_launch_like_java(15, vec!["erekir".into()]);
        let launch_dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("planetLaunch should update Campaign PlanetDialog")
            .clone();
        assert_eq!(
            launch_dialog.mode,
            super::CampaignPlanetDialogMode::PlanetLaunch
        );
        assert_eq!(launch_dialog.planet_name, "erekir");
        assert_eq!(
            launch_dialog.launch_candidate_planet_names,
            vec!["erekir".to_string()]
        );
        assert_eq!(launch_dialog.launch_sector_id, Some(15));
        assert!(!launcher.campaign_sector_list_open);
        assert!(!launcher.campaign_rules_entry_visible(&launch_dialog));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Campaign);
        assert!(lines.contains(&"mode: PlanetLaunch".to_string()));
        assert!(lines.contains(&"launch candidates: erekir".to_string()));
        assert!(!lines.contains(&"button: @campaign.difficulty".to_string()));
        assert!(
            !lines
                .iter()
                .any(|line| line.starts_with("button: sectorlist")),
            "Java PlanetDialog.rebuildExpand hides sectorlist while mode == planetLaunch"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                DesktopLauncher::campaign_route_rules_button_rect(panel)
                    .center()
                    .x,
                DesktopLauncher::campaign_route_rules_button_rect(panel)
                    .center()
                    .y
            ),
            None
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                DesktopLauncher::campaign_sector_list_toggle_rect(panel)
                    .center()
                    .x,
                DesktopLauncher::campaign_sector_list_toggle_rect(panel)
                    .center()
                    .y
            ),
            None
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("planetLaunch Campaign route should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(!texts.contains(
            &launcher
                .localize_bundle_markup_text("@campaign.difficulty")
                .as_str()
        ));
        assert!(!texts.contains(&launcher.localize_bundle_markup_text("@sectorlist").as_str()));
        let launchselect_label = launcher.localize_bundle_markup_text("@sectors.launchselect");
        assert!(
            texts.contains(&launchselect_label.as_str()),
            "Java PlanetDialog info label uses @sectors.launchselect while mode == planetLaunch"
        );
        assert!(!texts.contains(&"Launch sector ready"));
        for raw_key in [
            "@campaign.difficulty",
            "@sectorlist",
            "@sectors.launchselect",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "planetLaunch Campaign route final DrawText should not leak hidden raw key {raw_key}"
            );
        }
    }

    #[test]
