    #[test]
    fn desktop_launcher_campaign_route_sectorlist_expands_searches_and_selects_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        let _ = Arc::make_mut(&mut launcher.texture_atlas).insert_or_replace_region(
            PageType::Ui,
            TextureAtlasRegion::new(
                PageType::Ui,
                "warning",
                "sprites/warning.png",
                0,
                0,
                32,
                32,
                true,
            ),
        );
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        let preset = launcher
            .content_loader
            .sector_by_name("saltFlats")
            .expect("base content should expose Salt Flats")
            .clone();
        let mut sector = Sector::new(preset.sector_id.unwrap_or(preset.original_position));
        sector.preset = Some(preset);
        sector.save_exists = true;
        sector.info.has_core = true;
        sector.info.name = Some("Salt Flats Base".into());
        sector.info.waves = true;
        sector.info.wave = 20;
        sector.info.minutes_captured = 300.0;
        launcher.game_state.set_sector(Some(sector.clone()));
        launcher.runtime.state.set_sector(Some(sector));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        launcher.dispatch_menu_action(MenuButtonRole::Campaign);

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let toggle = DesktopLauncher::campaign_sector_list_toggle_rect(panel);
        let toggle_center = toggle.center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                toggle_center.x,
                toggle_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleCampaignSectorList)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ToggleCampaignSectorList,
        );
        assert!(launcher.campaign_sector_list_open);

        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Campaign);
        assert!(lines.contains(&"button: sectorlist attacked:1".to_string()));
        assert!(lines
            .iter()
            .any(|line| line == "sectorlist entry: Salt Flats Base #101"));
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign sectorlist should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let sectorlist_label = launcher.localize_bundle_markup_text("@sectorlist");
        assert!(texts.iter().any(|text| text.contains(&sectorlist_label)));
        assert!(texts.iter().any(|text| text.contains("Salt Flats Base")));
        assert!(
            !texts.iter().any(|text| text.starts_with("⚠ ")
                || text.contains("⚠ Salt Flats Base")),
            "Java PlanetDialog uses Fonts.getLargeIcon(\"warning\") for sector warning markers; sector list entries should not fall back to a raw warning prefix"
        );
        let warning_rect = RenderRect::from_center(
            RenderPoint::new(toggle.x + 22.0, toggle.center().y - 8.0),
            18.0,
            18.0,
        );
        let warning_glyph = super::desktop_iconc_glyph_by_name_like_java("warning")
            .and_then(|glyph| char::from_u32(glyph.codepoint))
            .map(|character| character.to_string());
        assert!(commands.iter().any(|command| match command {
            RenderCommand::DrawSprite { symbol, rect, .. } => {
                symbol == "warning" && *rect == warning_rect
            }
            RenderCommand::DrawText {
                text,
                position,
                style,
                ..
            } => {
                style.font == RenderFontId::IconLarge
                    && warning_glyph.as_ref() == Some(text)
                    && *position == warning_rect.center()
            }
            _ => false,
        }));

        let pane = DesktopLauncher::campaign_sector_list_pane_rect(panel);
        let search = DesktopLauncher::campaign_sector_list_search_rect(pane);
        let search_icon = super::desktop_ui_icon_glyph_or_label("zoom", "zoom");
        let collapse_icon = super::desktop_ui_icon_glyph_or_label("upOpen", "upOpen");
        assert!(
            !texts
                .iter()
                .any(|text| matches!(*text, "⌕" | "⌃" | "⌄" | "×")),
            "Java SectorSelectDialog/PlanetDialog controls use Icon font glyphs, not raw Unicode fallback text"
        );
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, position, style, .. }
                if text == &search_icon
                    && *position == RenderPoint::new(search.x + 18.0, search.center().y)
                    && style.font == RenderFontId::Icon
        )));
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, position, style, .. }
                if text == &collapse_icon
                    && *position == RenderPoint::new(toggle.right() - 22.0, toggle.center().y)
                    && style.font == RenderFontId::Icon
        )));
        let search_center = search.center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                search_center.x,
                search_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::FocusCampaignSectorListSearch)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::FocusCampaignSectorListSearch,
        );
        launcher.apply_menu_input_events(surface, &[DesktopInputTickEvent::Text("missing".into())]);
        assert_eq!(launcher.campaign_sector_list_search, "missing");
        let filtered_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let filtered_commands = filtered_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign sectorlist filtered frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let filtered_texts = filtered_commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            filtered_texts.contains(&launcher.localize_bundle_markup_text("@none.found").as_str())
        );
        let clear_icon = super::desktop_ui_icon_glyph_or_label("cancel", "cancel");
        assert!(filtered_commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawText { text, position, style, .. }
                if text == &clear_icon
                    && *position == DesktopLauncher::campaign_sector_list_clear_rect(search).center()
                    && style.font == RenderFontId::Icon
        )));

        let clear_center = DesktopLauncher::campaign_sector_list_clear_rect(search).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                clear_center.x,
                clear_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::ClearCampaignSectorListSearch)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ClearCampaignSectorListSearch,
        );
        assert_eq!(launcher.campaign_sector_list_search, "");

        let entry_center = DesktopLauncher::campaign_sector_list_entry_rect(pane, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                entry_center.x,
                entry_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::SelectCampaignSector(
                101
            ))
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::SelectCampaignSector(101),
        );
        assert_eq!(
            launcher
                .campaign_planet_dialog
                .as_ref()
                .and_then(|dialog| dialog.selected_sector_id),
            Some(101)
        );
    }

    #[test]
    fn desktop_launcher_campaign_route_opens_campaign_rules_dialog_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.game_state.rules.planet = "serpulo".into();
        launcher.runtime.state.rules.planet = "serpulo".into();
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);

        launcher.dispatch_menu_action(MenuButtonRole::Campaign);

        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Campaign);
        assert!(lines.contains(&"button: @campaign.difficulty".to_string()));
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let rules_center = DesktopLauncher::campaign_route_rules_button_rect(panel).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                rules_center.x,
                rules_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::OpenCampaignRules)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenCampaignRules,
        );
        assert!(launcher.campaign_rules_dialog_open);
        assert_eq!(
            launcher.campaign_rules_planet_name.as_deref(),
            Some("serpulo")
        );
        assert_eq!(launcher.campaign_rules_draft.difficulty, Difficulty::Normal);

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign rules dialog should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@campaign.difficulty")
                .as_str()
        ));
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@difficulty.hard")
                .as_str()
        ));
        assert!(texts
            .iter()
            .any(|text| text.contains(&launcher.localize_bundle_markup_text("@rules.fog"))));
        assert!(texts
            .iter()
            .any(|text| text
                .contains(&launcher.localize_bundle_markup_text("@rules.rtsai.campaign"))));
        assert!(
            !texts
                .iter()
                .any(|text| text.contains('☑') || text.contains('☐')),
            "Java CampaignRulesDialog uses CheckBox drawables, not raw Unicode checkbox prefixes"
        );

        let dialog = DesktopLauncher::campaign_rules_dialog_rect(panel);
        let normal_button = DesktopLauncher::campaign_rules_difficulty_button_rect(dialog, 2);
        assert_eq!(normal_button.width, 140.0);
        assert_eq!(normal_button.height, 50.0);
        let expected_selected_difficulty_symbol =
            DesktopLauncher::settings_text_button_symbol_checked("flatTogglet", false, false, true);
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &expected_selected_difficulty_symbol && *rect == normal_button
        )), "CampaignRulesDialog difficulty buttons should use Java Styles.flatTogglet checked chrome");
        let fog_row = DesktopLauncher::campaign_rules_toggle_rect(dialog, 1);
        let fog_check = DesktopLauncher::campaign_rules_toggle_check_box_rect(fog_row);
        let expected_fog_check = DesktopLauncher::settings_check_box_symbol(false, false, false);
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &expected_fog_check && *rect == fog_check
            )),
            "CampaignRulesDialog rule rows should render Java CheckBox drawables"
        );

        let hard_center =
            DesktopLauncher::campaign_rules_difficulty_button_rect(dialog, 3).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                hard_center.x,
                hard_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::SetCampaignDifficulty(
                Difficulty::Hard
            ))
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::SetCampaignDifficulty(Difficulty::Hard),
        );
        assert_eq!(launcher.campaign_rules_draft.difficulty, Difficulty::Hard);
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: hard_center.x,
                y: hard_center.y,
            }],
        );
        let hard_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let hard_texts = hard_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("Campaign rules dialog should render hard difficulty info")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            hard_texts
            .iter()
            .any(|text| text.contains("Enemy Health") && text.contains("+25%")),
            "CampaignRulesDialog difficulty hover tooltip should use localized Java bundle text; texts={hard_texts:?}"
        );

        let fog_center = DesktopLauncher::campaign_rules_toggle_rect(dialog, 1).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                fog_center.x,
                fog_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleCampaignRuleFog)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ToggleCampaignRuleFog,
        );
        assert!(launcher.campaign_rules_draft.fog);

        let close_center = DesktopLauncher::campaign_rules_close_rect(dialog).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                close_center.x,
                close_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::CloseCampaignRules)
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::CloseCampaignRules,
        );
        assert!(!launcher.campaign_rules_dialog_open);
        assert_eq!(
            launcher
                .campaign_rules_by_planet
                .get("serpulo")
                .map(|rules| rules.difficulty),
            Some(Difficulty::Hard)
        );
        assert!(launcher.game_state.rules.fog);
        assert!(launcher.runtime.state.rules.fog);
        assert_eq!(launcher.game_state.rules.objective_timer_multiplier, 0.8);
        assert_eq!(launcher.runtime.state.rules.objective_timer_multiplier, 0.8);
    }

    #[test]
    fn desktop_launcher_campaign_route_rules_dialog_filters_planet_specific_rules_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);

        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        let dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("Campaign route should create PlanetDialog")
            .clone();
        let erekir_index = launcher
            .campaign_selectable_planet_names_like_java(&dialog)
            .iter()
            .position(|name| name == "erekir")
            .expect("Campaign route should expose Erekir as selectable");
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::SelectCampaignPlanet(erekir_index),
        );
        let erekir_dialog = launcher
            .campaign_planet_dialog
            .as_ref()
            .expect("selecting Erekir should keep PlanetDialog open")
            .clone();
        assert_eq!(erekir_dialog.planet_name, "erekir");
        assert!(launcher.campaign_rules_entry_visible(&erekir_dialog));

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenCampaignRules,
        );
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Campaign);
        assert!(lines.contains(&"dialog: @campaign.difficulty".to_string()));
        assert!(lines.contains(&"rule: @rules.fog=false".to_string()));
        assert!(
            !lines.iter().any(|line| line.contains("@rules.invasions")),
            "Java hides invasions unless planet.allowSectorInvasion"
        );
        assert!(
            !lines
                .iter()
                .any(|line| line.contains("@rules.rtsai.campaign")),
            "Java hides RTS AI unless planet.showRtsAIRule"
        );
        assert!(
            !lines
                .iter()
                .any(|line| line.contains("@rules.clearsectoronloss")),
            "Java hides clearSectorOnLoss when planet.clearSectorOnLose is already true"
        );

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let rules_dialog = DesktopLauncher::campaign_rules_dialog_rect(panel);
        let first_toggle_center =
            DesktopLauncher::campaign_rules_toggle_rect(rules_dialog, 0).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                first_toggle_center.x,
                first_toggle_center.y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleCampaignRuleFog),
            "hidden Java-only rows must not leave stale click indices behind"
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ToggleCampaignRuleFog,
        );
        assert!(launcher.campaign_rules_draft.fog);
        assert!(!launcher.campaign_rules_draft.sector_invasion);
    }

