    #[test]
    fn desktop_launcher_campaign_launch_button_opens_loadout_then_seeds_playable_smoke_world() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        let surface = DesktopSurfaceSize::new(800, 600);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let input = DesktopLauncher::default_menu_frame_input_for_viewport(viewport);
        let play_center = launcher
            .menu_renderer_state
            .ui_plan(input)
            .buttons
            .iter()
            .find(|button| button.role == MenuButtonRole::Play)
            .expect("menu ui should include PLAY root")
            .rect
            .center();

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: play_center.x,
                    y: play_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );

        let campaign_center = launcher
            .menu_renderer_state
            .ui_plan(input)
            .buttons
            .iter()
            .find(|button| button.role == MenuButtonRole::Campaign)
            .expect("play submenu should include CAMPAIGN")
            .rect
            .center();

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: campaign_center.x,
                    y: campaign_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "primary".into(),
                    pressed: true,
                },
            ],
        );

        let launch_center = DesktopLauncher::active_menu_route_shell_primary_rect_for_viewport(
            viewport,
            super::DesktopMenuRoute::Campaign,
        )
        .expect("campaign route should expose a primary launch button")
        .center();

        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: launch_center.x,
                    y: launch_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "Left".into(),
                    pressed: true,
                },
            ],
        );

        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::Campaign)
        );
        assert!(launcher.campaign_launch_loadout_dialog_open);
        assert_eq!(
            launcher.last_menu_route_shell_action,
            Some(super::DesktopMenuRouteShellAction::OpenCampaignLaunchLoadout)
        );
        assert!(!launcher.game_state.is_playing());

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign launch loadout frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@configure").as_str()));
        assert!(texts.iter().any(|text| text.contains("Launching From")
            || text.contains("发射")
            || text.contains("启动")));
        assert!(texts
            .iter()
            .any(|text| text.contains("Launching Item Capacity") || text.contains("容量")));
        assert!(
            texts.contains(
                &launcher
                    .localize_bundle_markup_text("@resources.max")
                    .as_str()
            ) || texts
                .iter()
                .any(|text| text.contains(&launcher.localize_bundle_markup_text("@resources.max")))
        );
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@resources").as_str()));
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@launch.text")
                .as_str()
        ));
        assert!(
            !texts.iter().any(|text| text.contains(" / size ")),
            "Java LaunchLoadoutDialog renders SchematicImage buttons, not a Rust-only coreName/size text line"
        );
        assert!(
            !texts.iter().any(|text| text.contains('✓')),
            "Java LaunchLoadoutDialog uses Styles.togglet checked state for @resources.max, not a raw checkmark prefix"
        );
        for raw_key in [
            "@configure",
            "@resources.max",
            "@resources",
            "@launch.text",
            "@launch.from",
            "@launch.capacity",
            "@sector.missingresources",
        ] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "LaunchLoadoutDialog final DrawText should localize {raw_key} before rendering"
            );
        }

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Campaign,
        );
        let loadout_dialog = DesktopLauncher::campaign_launch_loadout_dialog_rect(panel);
        for rect in [
            DesktopLauncher::campaign_launch_loadout_back_rect(loadout_dialog),
            DesktopLauncher::campaign_launch_loadout_max_rect(loadout_dialog),
            DesktopLauncher::campaign_launch_loadout_resources_rect(loadout_dialog),
            DesktopLauncher::campaign_launch_loadout_confirm_rect(loadout_dialog),
        ] {
            assert_eq!(
                rect.width, 160.0,
                "Java LaunchLoadoutDialog buttons use buttons.defaults().size(160f, 64f)"
            );
            assert_eq!(
                rect.height, 64.0,
                "Java LaunchLoadoutDialog buttons use buttons.defaults().size(160f, 64f)"
            );
        }
        let max_button = DesktopLauncher::campaign_launch_loadout_max_rect(loadout_dialog);
        let (expected_max_symbol, _) =
            DesktopLauncher::settings_text_button_symbol_and_tint_checked(
                "togglet",
                false,
                false,
                launcher.campaign_launch_loadout_use_max_resources,
                launcher.campaign_launch_loadout_allows_resources(),
                if launcher.campaign_launch_loadout_allows_resources() {
                    0.96
                } else {
                    0.54
                },
            );
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &expected_max_symbol && *rect == max_button
        )));
        let confirm_center =
            DesktopLauncher::campaign_launch_loadout_confirm_rect(loadout_dialog).center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: confirm_center.x,
                    y: confirm_center.y,
                },
                DesktopInputTickEvent::MouseButton {
                    button: "Left".into(),
                    pressed: true,
                },
            ],
        );

        assert_eq!(launcher.active_menu_route, None);
        assert_eq!(launcher.campaign_planet_dialog, None);
        assert!(!launcher.campaign_launch_loadout_dialog_open);
        assert_eq!(launcher.map_play_dialog_index, None);
        assert_eq!(launcher.editor_map_info_dialog_index, None);
        assert_eq!(launcher.load_game_rename_dialog_slot, None);
        assert_eq!(launcher.load_game_delete_dialog_slot, None);
        assert!(!launcher.save_game_new_dialog_open);
        assert_eq!(
            launcher.last_menu_route_shell_action,
            Some(super::DesktopMenuRouteShellAction::ConfirmCampaignLaunchLoadout)
        );
        let report = launcher
            .last_campaign_launch_report
            .expect("launch should seed a playable smoke world");
        assert!(report.state_playing);
        assert_eq!(report.world_width, 16);
        assert_eq!(report.world_height, 16);
        assert_eq!(report.buildings, 1);
        assert!(launcher.game_state.is_playing());
        assert!(launcher.game_state.is_campaign());
        assert_eq!(
            launcher
                .game_state
                .get_sector()
                .and_then(|sector| sector.preset.as_ref())
                .map(|preset| preset.name.as_str()),
            Some("groundZero")
        );
        assert!(launcher.runtime.state.is_playing());
        assert_eq!(launcher.runtime.state.world.width(), 16);
        assert_eq!(launcher.runtime.state.world.height(), 16);
        assert_eq!(
            launcher.runtime.network_context,
            GameRuntimeNetworkContext::offline()
        );
    }

    #[test]
    fn desktop_launcher_campaign_launch_loadout_uses_source_sector_label_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher
            .settings_overrides
            .insert(super::CAMPAIGN_SELECT_SETTINGS_KEY.into(), "true".into());
        let source_preset = launcher
            .content_loader
            .sector_by_name("groundZero")
            .expect("base content should expose Ground Zero")
            .clone();
        let mut source = Sector::new(15);
        source.preset = Some(source_preset);
        source.save_exists = true;
        source.info.has_core = true;
        launcher.game_state.set_sector(Some(source.clone()));
        launcher.runtime.state.set_sector(Some(source));

        launcher.dispatch_menu_action(MenuButtonRole::Campaign);
        {
            let dialog = launcher
                .campaign_planet_dialog
                .as_mut()
                .expect("Campaign route should build PlanetDialog state");
            assert_eq!(dialog.launch_sector_id, Some(15));
            dialog.selected_sector_id = Some(101);
        }
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::OpenCampaignLaunchLoadout,
        );
        assert!(launcher.campaign_launch_loadout_dialog_open);

        let source_name = launcher.campaign_sector_display_name_for_id("serpulo", 15);
        let destination_name = launcher.campaign_sector_display_name_for_id("serpulo", 101);
        assert_eq!(source_name, "groundZero");
        assert_eq!(destination_name, "saltFlats");
        assert_ne!(source_name, destination_name);
        assert_eq!(launcher.campaign_launch_loadout_sector_name(), source_name);

        let surface = DesktopSurfaceSize::new(800, 600);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("campaign launch loadout frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let source_label = launcher.format_bundle_text("launch.from", &[source_name.as_str()]);
        let destination_label =
            launcher.format_bundle_text("launch.from", &[destination_name.as_str()]);
        assert!(
            texts.contains(&source_label.as_str()),
            "Java LaunchLoadoutDialog renders launch.from with the source sector"
        );
        assert!(
            !texts.contains(&destination_label.as_str()),
            "launch.from must not use the selected destination sector"
        );
    }

