    #[test]
    fn desktop_launcher_join_route_polls_local_discovery_hosts_like_java_refresh_local() {
        let port = super::DEFAULT_MINDUSTRY_PORT;
        let local_version = mindustry_core::mindustry::core::net_client::DEFAULT_CLIENT_VERSION;
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        let (tx, rx) = std::sync::mpsc::channel();
        launcher.join_local_discovering = true;
        launcher.join_local_discovery_receiver = Some(std::sync::Arc::new(Mutex::new(rx)));
        tx.send(Some(mindustry_core::mindustry::net::Host::new(
            42,
            "LAN host",
            "127.0.0.1",
            port.into(),
            "local map",
            3,
            2,
            local_version,
            "official",
            Gamemode::Survival,
            8,
            "local first\nlocal second\nlocal third",
            Some("@mode.survival.name".into()),
        )))
        .unwrap();
        tx.send(None).unwrap();

        launcher.poll_join_local_discovery();

        assert!(!launcher.join_local_discovering);
        assert!(launcher.join_local_discovery_finished);
        assert_eq!(launcher.join_local_hosts.len(), 1);
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(lines.contains(&"section: @servers.local hosts: 1 state:done".to_string()));
        assert!(lines.contains(&format!("local[0]: LAN host 127.0.0.1:{port}")));
        assert!(lines.contains(&"local[0] players: 2/8".to_string()));
        assert!(lines.contains(&"local[0] map: local map".to_string()));
        assert!(lines.contains(&"local[0] mode: @mode.survival.name".to_string()));
        assert!(lines.contains(&"local[0] ping: 42ms".to_string()));
        assert!(lines.contains(&"local[0] actions: connect".to_string()));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        let local_card = DesktopLauncher::join_route_server_card_rect_for_panel(panel, 0);
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                local_card.center().x,
                local_card.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ConnectJoinLocalHost(0))
        );
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let render_frame = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join local host frame should contain render frame");
        let commands = render_frame
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let card_header = RenderRect::new(
            local_card.x,
            local_card.y + local_card.height - super::JOIN_SERVER_CARD_LOCAL_HEADER_HEIGHT,
            local_card.width,
            super::JOIN_SERVER_CARD_LOCAL_HEADER_HEIGHT,
        );
        let card_body = RenderRect::new(
            local_card.x,
            local_card.y,
            local_card.width,
            local_card.height - super::JOIN_SERVER_CARD_LOCAL_HEADER_HEIGHT,
        );
        let white_pane = DesktopLauncher::settings_drawable_symbol("whitePane");
        let white_ui = DesktopLauncher::settings_drawable_symbol("whiteui");
        assert!(
            commands.iter().any(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } => {
                    symbol == &white_pane && rect == &card_body
                }
                _ => false,
            }),
            "Java JoinDialog buildServer body uses Tex.whitePane tinted Pal.gray"
        );
        assert!(
            commands.iter().any(|command| match command {
                RenderCommand::DrawSprite { symbol, rect, .. } => {
                    symbol == &white_ui && rect == &card_header
                }
                _ => false,
            }),
            "Java JoinDialog buildServer header uses Tex.whiteui tinted Pal.gray"
        );
        let local_title = texts
            .iter()
            .find(|text| text.contains("LAN host"))
            .expect("local server title should be rendered");
        assert!(
            !local_title.contains("[gray]v"),
            "Java JoinDialog hides the version suffix when host.version and Version.type match the current client"
        );
        assert!(
            texts
                .iter()
                .any(|text| text.contains("local first\nlocal second\nlocal third")),
            "Java JoinDialog buildServer preserves up to two description newlines instead of flattening them"
        );
        assert!(!texts
            .iter()
            .any(|text| text.contains("local first local second local third")));
        assert!(!texts
            .iter()
            .any(|text| text.contains("127.0.0.1") && text.contains("Local Servers")));
        let players_label =
            launcher.format_bundle_text("players", &["[accent]2[lightgray]/[accent]8[lightgray]"]);
        assert!(texts.iter().any(|text| text.contains(&players_label)));
        let map_label = launcher.format_bundle_text("save.map", &["local map"]);
        let mode_label = "@mode.survival.name";
        assert!(texts
            .iter()
            .any(|text| text.contains(&map_label) && text.contains(&mode_label)));
        assert!(texts.iter().any(|text| text.contains("42ms")));
        assert!(!texts.contains(&"tap to connect"));

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ConnectJoinLocalHost(0),
        );
        assert_eq!(
            launcher.connect_target,
            Some(super::DesktopConnectTarget {
                host: "127.0.0.1".into(),
                port,
            })
        );
    }

    #[test]
    fn desktop_launcher_join_route_shows_all_visible_local_hosts_like_java() {
        let port = super::DEFAULT_MINDUSTRY_PORT;
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        let visible_slots = DesktopLauncher::join_route_server_card_visible_slots_for_panel(panel);
        let local_host_count = visible_slots + 2;
        launcher.join_local_hosts = (0..local_host_count)
            .map(|index| {
                mindustry_core::mindustry::net::Host::new(
                    30 + index as i32,
                    format!("LAN host {index}"),
                    format!("127.0.0.{}", index + 1),
                    port.into(),
                    format!("local map {index}"),
                    index as i32,
                    2 + index as i32,
                    158,
                    "official",
                    Gamemode::Survival,
                    8,
                    format!("local description {index}"),
                    Some("@mode.survival.name".into()),
                )
            })
            .collect();
        assert!(
            local_host_count > visible_slots,
            "fixture must exceed the first screen of Rust join cards"
        );
        assert_eq!(
            launcher.join_route_visible_local_host_count_for_panel(panel),
            local_host_count,
            "Java JoinDialog addLocalHost() appends every discovered local host; Rust must not cap LAN cards at the first visible row set"
        );
        assert_eq!(
            launcher.max_join_route_scroll_offset_for_panel(panel),
            local_host_count - visible_slots,
            "Java JoinDialog wraps hosts in one vertical ScrollPane, so LAN overflow must expose a scrollbar"
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join local multi-host frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        let last_host_label = format!("LAN host {}", local_host_count - 1);
        assert!(texts.iter().any(|text| text.contains("LAN host 0")));
        assert!(texts
            .iter()
            .any(|text| text.contains(&format!("LAN host {}", visible_slots - 1))));
        assert!(
            !texts.iter().any(|text| text.contains(&last_host_label)),
            "LAN hosts beyond the first JoinDialog ScrollPane page should not be rendered before scrolling"
        );

        let clickable_index = visible_slots.saturating_sub(1).min(local_host_count - 1);
        let visible_card =
            DesktopLauncher::join_route_server_card_rect_for_panel(panel, clickable_index);
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                visible_card.center().x,
                visible_card.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ConnectJoinLocalHost(
                clickable_index
            ))
        );

        let cursor = DesktopLauncher::join_route_scroll_clip_rect_for_panel(panel).center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: cursor.x,
                    y: cursor.y,
                },
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -2.0,
                },
            ],
        );
        assert_eq!(
            launcher.join_route_scroll_offset.round() as usize,
            local_host_count - visible_slots
        );

        let after_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let after_texts = after_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("scrolled join local multi-host frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            !after_texts.iter().any(|text| text.contains("LAN host 0")),
            "the first LAN host should scroll out of the Java-style ScrollPane"
        );
        assert!(after_texts
            .iter()
            .any(|text| text.contains(&last_host_label)));
        let last_visible_card =
            DesktopLauncher::join_route_server_card_rect_for_panel(panel, visible_slots - 1);
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                last_visible_card.center().x,
                last_visible_card.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ConnectJoinLocalHost(
                local_host_count - 1
            )),
            "LAN hit-testing must use the same scrolled local-host window as rendering"
        );
    }

    #[test]
    fn desktop_launcher_join_route_scrolls_saved_servers_after_local_overflow_like_java() {
        let port = super::DEFAULT_MINDUSTRY_PORT;
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        let visible_slots = DesktopLauncher::join_route_server_card_visible_slots_for_panel(panel);
        let local_host_count = visible_slots + 1;
        launcher.join_local_hosts = (0..local_host_count)
            .map(|index| {
                mindustry_core::mindustry::net::Host::new(
                    40 + index as i32,
                    format!("LAN host {index}"),
                    format!("127.0.1.{}", index + 1),
                    port.into(),
                    format!("local map {index}"),
                    index as i32,
                    4 + index as i32,
                    158,
                    "official",
                    Gamemode::Survival,
                    8,
                    format!("local description {index}"),
                    Some("@mode.survival.name".into()),
                )
            })
            .collect();
        launcher.join_saved_servers = (0..3)
            .map(|index| super::DesktopConnectTarget {
                host: format!("saved-after-local-{index}.example"),
                port,
            })
            .collect();
        assert_eq!(
            launcher.max_join_route_scroll_offset_for_panel(panel),
            local_host_count + launcher.join_saved_servers.len() - visible_slots
        );

        let cursor = DesktopLauncher::join_route_scroll_clip_rect_for_panel(panel).center();
        launcher.apply_menu_input_events(
            surface,
            &[
                DesktopInputTickEvent::CursorMoved {
                    x: cursor.x,
                    y: cursor.y,
                },
                DesktopInputTickEvent::Scroll {
                    delta_x: 0.0,
                    delta_y: -(local_host_count as f32 - 1.0),
                },
            ],
        );
        assert_eq!(
            launcher.join_route_scroll_offset.round() as usize,
            local_host_count - 1
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("scrolled join mixed local/saved frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            !texts.iter().any(|text| text.contains("LAN host 0")),
            "early LAN hosts should scroll out before saved servers enter the unified window"
        );
        assert!(texts
            .iter()
            .any(|text| text.contains(&format!("LAN host {}", local_host_count - 1))));
        assert!(texts
            .iter()
            .any(|text| text.contains("saved-after-local-0.example")));
        assert!(texts
            .iter()
            .any(|text| text.contains("saved-after-local-2.example")));

        let first_saved_card = DesktopLauncher::join_route_server_card_rect_for_panel(panel, 1);
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                first_saved_card.center().x,
                first_saved_card.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ConnectJoinServerCard(0)),
            "saved hit-testing must subtract the scrolled local-host overflow before indexing saved servers"
        );
    }

