    #[test]
    fn desktop_launcher_join_route_local_host_card_uses_java_buildserver_header_and_section_divider(
    ) {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        launcher
            .join_local_hosts
            .push(mindustry_core::mindustry::net::Host::new(
                31,
                "LAN host",
                "127.0.0.1",
                super::DEFAULT_MINDUSTRY_PORT.into(),
                "local map",
                3,
                2,
                158,
                "official",
                Gamemode::Survival,
                8,
                "local description",
                Some("@mode.survival.name".into()),
            ));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        assert_eq!(
            super::JOIN_SERVER_CARD_LOCAL_HEADER_HEIGHT,
            36.0,
            "Java JoinDialog.buildServer(addName=true) gives the local-host name strip height(36f)"
        );
        let local_card = DesktopLauncher::join_route_server_card_rect_for_panel(panel, 0);
        let local_header = RenderRect::new(
            local_card.x,
            local_card.y + local_card.height - super::JOIN_SERVER_CARD_LOCAL_HEADER_HEIGHT,
            local_card.width,
            super::JOIN_SERVER_CARD_LOCAL_HEADER_HEIGHT,
        );
        let stale_tall_header = RenderRect::new(
            local_card.x,
            local_card.y + local_card.height - super::JOIN_SERVER_CARD_HEADER_HEIGHT,
            local_card.width,
            super::JOIN_SERVER_CARD_HEADER_HEIGHT,
        );
        let (divider_start, divider_end) =
            DesktopLauncher::join_route_section_divider_line_for_panel(
                panel,
                super::DesktopJoinSection::Local,
            );
        assert_eq!(divider_start.x, panel.x + 46.0);
        assert_eq!(divider_end.x, panel.right() - 46.0);
        assert!(
            divider_start.y
                < DesktopLauncher::join_route_section_header_y_for_panel(
                    panel,
                    super::DesktopJoinSection::Local
                ) - 20.0,
            "Java JoinDialog.section() puts the 3f accent image in its own row below the title row"
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join local host frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let whiteui = DesktopLauncher::settings_drawable_symbol("whiteui");
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &whiteui && *rect == local_header
            )),
            "Java JoinDialog.addLocalHost -> buildServer(addName=true) renders a 36f Tex.whiteui local-host header"
        );
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &whiteui && *rect == stale_tall_header
            )),
            "local hosts must not reuse the taller saved-server action strip geometry"
        );
        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawLine { from, to, stroke, .. }
                    if *from == divider_start && *to == divider_end && (*stroke - 3.0).abs() < 0.01
            )),
            "Java JoinDialog.section() renders a full-width 3f accent divider with padLeft/padRight(10f)"
        );
        let old_inline_start = RenderPoint::new(
            panel.x + 148.0,
            DesktopLauncher::join_route_section_header_y_for_panel(
                panel,
                super::DesktopJoinSection::Local,
            ) - 1.0,
        );
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawLine { from, .. } if *from == old_inline_start
            )),
            "Join section divider should no longer be a Rust-only title-inline line"
        );
    }

    #[test]
    fn desktop_launcher_join_route_renders_local_empty_refresh_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        let (tx, rx) = std::sync::mpsc::channel();
        launcher.join_local_discovering = true;
        launcher.join_local_discovery_receiver = Some(std::sync::Arc::new(Mutex::new(rx)));
        tx.send(None).unwrap();

        launcher.poll_join_local_discovery();

        assert!(!launcher.join_local_discovering);
        assert!(launcher.join_local_discovery_finished);
        assert!(launcher.join_local_hosts.is_empty());
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(lines.contains(&"section: @servers.local hosts: 0 state:done".to_string()));
        assert!(lines.contains(&"local-empty: @hosts.none refresh:true".to_string()));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        let empty_card = DesktopLauncher::join_route_local_empty_card_rect_for_panel(panel);
        assert_eq!(empty_card.height, 70.0);
        let refresh = DesktopLauncher::join_route_local_empty_refresh_button_rect(empty_card);
        assert_eq!(refresh.width, 70.0);
        assert_eq!(refresh.height, 70.0);
        assert_eq!(
            (refresh.x - (empty_card.right() - 58.0)).abs(),
            0.0,
            "Java JoinDialog uses pad(-12f).padLeft(0) on the 70f refresh button, so the icon button sits tight against the right edge"
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                refresh.center().x,
                refresh.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::RefreshJoinLocalServers),
            "Java JoinDialog shows a local-only refresh button next to @hosts.none"
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join local empty frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@hosts.none").as_str()));
        let refresh_icon = super::desktop_ui_icon_glyph_or_label("refresh", "refresh");
        assert!(texts.contains(&refresh_icon.as_str()));
        let refresh_icon_style = commands.iter().find_map(|command| match command {
            RenderCommand::DrawText {
                text,
                position,
                color,
                style,
                ..
            } if text == &refresh_icon && refresh.contains_point(*position) => {
                Some((*color, *style))
            }
            _ => None,
        });
        let (refresh_color, refresh_style) = refresh_icon_style
            .expect("Java JoinDialog local empty refresh is an icon-only ImageButton");
        assert_eq!(
            refresh_color,
            [1.0, 1.0, 1.0, 1.0],
            "Java JoinDialog's default ImageButton keeps the refresh glyph white"
        );
        assert!(
            !refresh_style.outline,
            "Java JoinDialog's Icon.refresh button is not a Rust text-button label with outline"
        );
        let button_symbol = DesktopLauncher::settings_drawable_symbol("button");
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &button_symbol && *rect == empty_card
        )));
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, .. } if *rect == empty_card
            )),
            "Java JoinDialog.finishLocalHosts uses local.background(Tex.button) without an extra Rust-only accent stroke"
        );
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, .. } if *rect == refresh
            )),
            "Java JoinDialog.finishLocalHosts uses an ImageButton for Icon.refresh, not a stroked TextButton"
        );
    }

