    #[test]
    fn desktop_launcher_join_route_blocks_version_mismatch_like_java_safe_connect() {
        let current_version = mindustry_core::mindustry::core::net_client::DEFAULT_CLIENT_VERSION;
        let port = super::DEFAULT_MINDUSTRY_PORT;
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        launcher
            .join_local_hosts
            .push(mindustry_core::mindustry::net::Host::new(
                18,
                "Old LAN host",
                "127.0.0.1",
                port.into(),
                "old map",
                3,
                1,
                current_version - 1,
                "official",
                Gamemode::Survival,
                8,
                "old server",
                Some("@mode.survival.name".into()),
            ));

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ConnectJoinLocalHost(0),
        );

        assert_eq!(
            launcher.connect_target,
            None,
            "Java JoinDialog.safeConnect version mismatch only shows an info modal and does not seed last/connect target"
        );
        let modal = launcher
            .join_version_mismatch_dialog_message
            .clone()
            .expect("version mismatch should open the Java showInfo-style modal");
        assert_eq!(
            launcher.connect_error, None,
            "Java ui.showInfo for version mismatch is not a connection error state"
        );
        assert_eq!(launcher.join_reconnect_target, None);
        assert!(launcher.join_reconnect_receiver.is_none());
        assert!(
            !launcher.join_route_loadfrag_visible(),
            "Java JoinDialog.safeConnect does not show @connecting when the version check fails"
        );
        assert!(modal.contains(&current_version.to_string()));
        assert!(modal.contains(&(current_version - 1).to_string()));
        assert_eq!(launcher.last_menu_info_message, None);
        assert!(launcher
            .active_menu_route_shell_lines(super::DesktopMenuRoute::Join)
            .iter()
            .any(|line| line.starts_with("dialog: @info.title @server.versions")));
        {
            let state = launcher.net_client.state();
            let state = state.lock().unwrap();
            assert_eq!(state.connection_attempts, 0);
            assert!(!state.connecting);
        }

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        let dialog = DesktopLauncher::join_version_mismatch_dialog_rect_for_panel(panel);
        let ok = DesktopLauncher::join_add_dialog_button_rect(dialog, 1).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, ok.x, ok.y),
            Some(super::DesktopMenuRouteShellAction::CloseJoinVersionMismatch)
        );
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("version mismatch frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        for raw_key in ["@info.title", "@server.versions"] {
            assert!(
                !texts.iter().any(|text| text.contains(raw_key)),
                "version mismatch modal should localize visible text; raw {raw_key} belongs only in debug shell lines"
            );
        }
        let add = DesktopLauncher::join_route_add_button_rect_for_panel(panel).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, add.x, add.y),
            None
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::CloseJoinVersionMismatch,
        );
        assert_eq!(launcher.join_version_mismatch_dialog_message, None);
        assert_eq!(launcher.connect_error, None);
    }

    #[test]
    fn desktop_launcher_join_and_host_server_status_strings_match_java() {
        let current_version = mindustry_core::mindustry::core::net_client::DEFAULT_CLIENT_VERSION;
        let current_type = mindustry_core::mindustry::core::net_client::DEFAULT_CLIENT_VERSION_TYPE;
        let launcher = DesktopLauncher::new(Vec::new());

        let custom_build = launcher
            .bundle_value_for_current_locale("server.custombuild")
            .expect("server.custombuild should resolve from the same Core.bundle chain as Java");
        assert_eq!(
            launcher.join_server_version_text_like_java(-1, "custom"),
            launcher.format_bundle_text("server.version", &[custom_build.as_str(), ""]),
            "Java JoinDialog.getVersionString formats -1 as server.version(server.custombuild, \"\")"
        );
        assert_eq!(
            launcher.join_server_version_text_like_java(0, ""),
            launcher.localize_bundle_markup_text("@server.outdated"),
            "Java JoinDialog.getVersionString maps version 0 to @server.outdated"
        );

        let older = launcher.join_server_version_text_like_java(current_version - 1, current_type);
        assert!(older.starts_with(&format!(
            "{}\n",
            launcher.localize_bundle_markup_text("@server.outdated")
        )));
        assert!(older.contains(&format!("[gray]v{} {}", current_version - 1, current_type)));

        let newer = launcher.join_server_version_text_like_java(current_version + 1, current_type);
        assert!(newer.starts_with(&format!(
            "{}\n",
            launcher.localize_bundle_markup_text("@server.outdated.client")
        )));
        assert!(newer.contains(&format!("[gray]v{} {}", current_version + 1, current_type)));

        assert_eq!(
            launcher.join_server_version_text_like_java(current_version, current_type),
            "",
            "Java JoinDialog hides version text when build and Version.type both match"
        );
        assert_eq!(
            launcher.join_server_card_title_like_java(
                "Official LAN",
                current_version,
                current_type
            ),
            "Official LAN"
        );
        assert!(launcher
            .join_server_card_title_like_java("Custom LAN", -1, "custom")
            .contains(custom_build.as_str()));

        assert_eq!(
            mindustry_core::mindustry::ui::upstream_menu_bundle_value_for_locale(
                "en",
                "server.error.addressinuse"
            ),
            Some("[scarlet]Failed to open server on port 6567.[]\\n\\nMake sure no other Mindustry servers are running on your device or network!")
        );
    }

    #[test]
    fn desktop_launcher_join_route_connect_error_uses_java_like_error_modal() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        let target = super::DesktopConnectTarget {
            host: "127.0.0.1".into(),
            port: 0,
        };

        let result = launcher.connect_to_target(target.clone());

        assert!(result.is_err());
        assert_eq!(launcher.connect_target, Some(target));
        let modal = launcher
            .join_connection_error_dialog_message
            .clone()
            .expect("connect failure should open a Java showErrorMessage-style modal");
        assert_eq!(launcher.connect_error, Some(modal.clone()));
        assert!(launcher
            .active_menu_route_shell_lines(super::DesktopMenuRoute::Join)
            .iter()
            .any(|line| line.starts_with("dialog: @host.invalid message=")));
        {
            let state = launcher.net_client.state();
            let state = state.lock().unwrap();
            assert!(
                !state.connecting,
                "failed immediate connect should hide the connecting loadfrag"
            );
        }
        assert!(
            !launcher.loading_fragment_state.visible,
            "failed immediate connect should hide the Java LoadingFragmentState"
        );

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let texts = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join connect error frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(
            &launcher
                .localize_bundle_markup_text("@host.invalid")
                .as_str()
        ));
        assert!(texts.contains(&modal.as_str()));
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@ok").as_str()));

        let dialog = DesktopLauncher::join_connection_error_dialog_rect_for_panel(panel);
        let ok = DesktopLauncher::join_add_dialog_button_rect(dialog, 1).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, ok.x, ok.y),
            Some(super::DesktopMenuRouteShellAction::CloseJoinConnectionError)
        );
        let add = DesktopLauncher::join_route_add_button_rect_for_panel(panel).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(surface, add.x, add.y),
            None
        );
        assert!(launcher.apply_menu_back_key());
        assert_eq!(launcher.join_connection_error_dialog_message, None);
        assert_eq!(launcher.connect_error, None);
        assert_eq!(
            launcher.active_menu_route,
            Some(super::DesktopMenuRoute::Join)
        );
    }

    #[test]
    fn desktop_launcher_join_route_async_net_errors_open_error_modal() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        {
            let state = launcher.net_client.state();
            let mut state = state.lock().unwrap();
            state.connecting = true;
            state.last_connect_packet_error = Some("send failed".into());
        }

        launcher.update();

        let modal = launcher
            .join_connection_error_dialog_message
            .clone()
            .expect("async connect packet error should open modal");
        assert!(modal.contains("Connection error."));
        assert!(modal.contains("send failed"));
        assert_eq!(launcher.connect_error, Some(modal));
        {
            let state = launcher.net_client.state();
            let state = state.lock().unwrap();
            assert!(!state.connecting);
        }

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::CloseJoinConnectionError,
        );
        assert_eq!(launcher.join_connection_error_dialog_message, None);
        {
            let state = launcher.net_client.state();
            let state = state.lock().unwrap();
            assert_eq!(state.last_connect_packet_error, None);
        }

        {
            let state = launcher.net_client.state();
            let mut state = state.lock().unwrap();
            state.timeout_disconnects = state.timeout_disconnects.saturating_add(1);
        }
        launcher.update();
        let timeout_modal = launcher
            .join_connection_error_dialog_message
            .clone()
            .expect("timeout disconnect should open modal");
        assert_eq!(
            timeout_modal,
            launcher.localize_bundle_markup_text("@disconnect.timeout")
        );
    }

    #[test]
    fn desktop_launcher_join_route_kick_reason_opens_error_modal() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        {
            let state = launcher.net_client.state();
            let mut state = state.lock().unwrap();
            state.kicked = true;
            state.last_kick_reason = Some(mindustry_core::mindustry::net::KickCallPacket2 {
                reason: mindustry_core::mindustry::net::KickReason::Banned,
            });
        }

        launcher.update();

        let modal = launcher
            .join_connection_error_dialog_message
            .clone()
            .expect("kick reason should open JoinDialog-style error modal");
        assert_eq!(modal, "You are banned on this server.");
        assert_eq!(launcher.connect_error, Some(modal));

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::CloseJoinConnectionError,
        );
        {
            let state = launcher.net_client.state();
            let state = state.lock().unwrap();
            assert_eq!(state.last_kick_reason, None);
            assert!(!state.kicked);
        }
    }

    #[test]
    fn desktop_launcher_join_route_server_restarting_enters_reconnecting_loadfrag() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        launcher.connect_target = Some(super::DesktopConnectTarget {
            host: "127.0.0.1".into(),
            port: super::DEFAULT_MINDUSTRY_PORT,
        });
        {
            let state = launcher.net_client.state();
            let mut state = state.lock().unwrap();
            state.kicked = true;
            state.last_kick_reason = Some(mindustry_core::mindustry::net::KickCallPacket2 {
                reason: mindustry_core::mindustry::net::KickReason::ServerRestarting,
            });
        }

        launcher.sync_join_reconnect_from_net_state();

        assert!(launcher.join_reconnecting_loadfrag_visible());
        assert!(launcher.join_route_loadfrag_visible());
        assert_eq!(launcher.join_route_loadfrag_label(), Some("@reconnecting"));
        assert!(launcher.loading_fragment_state.visible);
        assert_eq!(launcher.loading_fragment_state.text, "@reconnecting");
        assert!(launcher.loading_fragment_state.cancelable);
        assert!(!launcher.loading_fragment_state.progress_visible);
        assert_eq!(launcher.join_connection_error_dialog_message, None);
        {
            let state = launcher.net_client.state();
            let state = state.lock().unwrap();
            assert_eq!(state.last_kick_reason, None);
            assert!(!state.kicked);
        }
        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(lines.contains(&"loadfrag: @reconnecting".to_string()));
        assert!(lines.contains(&"button: @cancel".to_string()));

        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::CancelJoinConnect,
        );
        assert!(!launcher.join_reconnecting_loadfrag_visible());
        assert_eq!(launcher.join_reconnect_target, None);
        assert!(launcher.join_reconnect_receiver.is_none());
        assert!(!launcher.loading_fragment_state.visible);
    }

    #[test]
    fn desktop_launcher_join_route_saved_server_columns_match_java_at_resize_edges() {
        for (graphics_width, expected_columns) in [
            (600.0, 1),
            (611.0, 1),
            (612.0, 1),
            (1222.0, 1),
            (1223.0, 2),
            (1833.0, 2),
            (1834.0, 3),
            (2444.0, 3),
            (2445.0, 4),
            (3200.0, 4),
        ] {
            assert_eq!(
                DesktopLauncher::join_route_server_card_columns_for_graphics_width_like_java(
                    graphics_width
                ),
                expected_columns,
                "JoinDialog.columns() casts the scaled-width ratio to int before clamping at graphics width {graphics_width}"
            );
        }

        let launcher = DesktopLauncher::new(Vec::new());
        for (surface_width, expected_columns) in [(1222, 1), (1223, 2), (1833, 2), (1834, 3)] {
            assert_eq!(
                launcher.join_route_columns_for_surface(DesktopSurfaceSize::new(
                    surface_width,
                    720
                )),
                expected_columns,
                "Rust panel inference should recover Core.graphics.getWidth()/Scl.scl() before applying Java JoinDialog.columns() at surface width {surface_width}"
            );
        }
    }

    #[test]
    fn desktop_launcher_join_route_uses_java_like_grid_slots_for_local_and_saved_servers() {
        let port = super::DEFAULT_MINDUSTRY_PORT;
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        launcher
            .join_local_hosts
            .push(mindustry_core::mindustry::net::Host::new(
                18,
                "LAN host",
                "127.0.0.1",
                port.into(),
                "local map",
                3,
                2,
                158,
                "official",
                Gamemode::Survival,
                8,
                "local description",
                Some("@mode.survival.name".into()),
            ));
        launcher.join_saved_servers = vec![
            super::DesktopConnectTarget {
                host: "one.example".into(),
                port,
            },
            super::DesktopConnectTarget {
                host: "two.example".into(),
                port,
            },
            super::DesktopConnectTarget {
                host: "three.example".into(),
                port,
            },
        ];

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        assert_eq!(
            DesktopLauncher::join_route_server_card_columns_for_panel(panel),
            2
        );
        let narrow_panel = RenderRect::new(panel.x, panel.y, 520.0, panel.height);
        assert_eq!(
            DesktopLauncher::join_route_server_card_columns_for_panel(narrow_panel),
            1,
            "Java JoinDialog.columns clamps narrow screens to a single column"
        );
        let wide_panel = RenderRect::new(panel.x, panel.y, 2600.0, panel.height);
        assert_eq!(
            DesktopLauncher::join_route_server_card_columns_for_panel(wide_panel),
            4,
            "Java JoinDialog.columns clamps very wide screens to at most four columns"
        );
        assert_eq!(
            DesktopLauncher::join_route_server_card_visible_slots_for_panel(panel),
            4
        );

        let local = DesktopLauncher::join_route_server_card_rect_for_panel(panel, 0);
        let saved0 = DesktopLauncher::join_route_server_card_rect_for_panel(panel, 1);
        let saved1 = DesktopLauncher::join_route_server_card_rect_for_panel(panel, 2);
        let saved2 = DesktopLauncher::join_route_server_card_rect_for_panel(panel, 3);
        assert!(local.x < saved0.x);
        assert!((local.y - saved0.y).abs() < 0.01);
        assert!((local.x - saved1.x).abs() < 0.01);
        assert!(saved1.y < local.y);
        assert!((saved1.y - saved2.y).abs() < 0.01);

        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                local.center().x,
                local.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ConnectJoinLocalHost(0))
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                saved0.center().x,
                saved0.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ConnectJoinServerCard(0))
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                saved2.center().x,
                saved2.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ConnectJoinServerCard(2))
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let render_frame = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join grid frame should contain render frame");
        let commands = render_frame
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.iter().any(|text| text.contains("LAN host")));
        assert!(texts.iter().any(|text| text.contains("one.example")));
        assert!(texts.iter().any(|text| text.contains("two.example")));
        assert!(texts.iter().any(|text| text.contains("three.example")));
        let up_icon = super::desktop_ui_icon_glyph_or_label("upOpen", "upOpen");
        let up_button = DesktopLauncher::join_route_server_card_action_button_rect(saved0, 0);
        let saved_up_icon_style = commands.iter().find_map(|command| match command {
            RenderCommand::DrawText {
                text,
                position,
                color,
                style,
                ..
            } if text == &up_icon && up_button.contains_point(*position) => Some((*color, *style)),
            _ => None,
        });
        let (saved_up_color, saved_up_style) = saved_up_icon_style.expect(
            "saved-server upOpen action icon should be rendered inside its Java action button",
        );
        assert_eq!(
            saved_up_color,
            [1.0, 1.0, 1.0, 1.0],
            "Java JoinDialog uses Styles.emptyi icon buttons with Color.white glyphs"
        );
        assert_eq!(saved_up_style.font, RenderFontId::Icon);
        assert!(
            !saved_up_style.outline,
            "Styles.emptyi does not add a Rust-only outline text pass to saved-server action icons"
        );

        launcher.last_menu_cursor = Some(up_button.center());
        let hover_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let hover_commands = hover_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("hovered join grid frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let hovered_saved_up_color = hover_commands
            .iter()
            .find_map(|command| match command {
                RenderCommand::DrawText {
                    text,
                    position,
                    color,
                    ..
                } if text == &up_icon && up_button.contains_point(*position) => Some(*color),
                _ => None,
            })
            .expect("hovered saved-server upOpen action icon should render");
        assert_eq!(
            hovered_saved_up_color,
            mindustry_core::mindustry::ui::UiStyleColor::LightGray.rgba(),
            "Java Styles.emptyi sets imageOverColor = Color.lightGray for hovered image buttons"
        );
    }

    #[test]
    fn desktop_launcher_join_route_persists_section_collapse_state_like_java() {
        let port = super::DEFAULT_MINDUSTRY_PORT;
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        launcher
            .join_local_hosts
            .push(mindustry_core::mindustry::net::Host::new(
                18,
                "LAN host",
                "127.0.0.1",
                port.into(),
                "local map",
                3,
                2,
                158,
                "official",
                Gamemode::Survival,
                8,
                "local description",
                Some("@mode.survival.name".into()),
            ));
        launcher
            .join_saved_servers
            .push(super::DesktopConnectTarget {
                host: "one.example".into(),
                port,
            });
        launcher
            .join_community_groups
            .push(super::DesktopJoinCommunityGroup::new(
                "Official",
                vec!["community.example:6567".into()],
                true,
            ));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        let local_toggle = DesktopLauncher::join_route_section_toggle_rect_for_panel(
            panel,
            super::DesktopJoinSection::Local,
        );
        let remote_toggle = DesktopLauncher::join_route_section_toggle_rect_for_panel(
            panel,
            super::DesktopJoinSection::Remote,
        );
        let global_toggle = DesktopLauncher::join_route_section_toggle_rect_for_panel(
            panel,
            super::DesktopJoinSection::Global,
        );
        let show_hidden = DesktopLauncher::join_route_show_hidden_button_rect_for_panel(panel);
        for button in [local_toggle, remote_toggle, global_toggle, show_hidden] {
            assert_eq!(
                (button.width, button.height),
                (40.0, 40.0),
                "Java JoinDialog section()/addHeader() icon buttons use 40f square image buttons"
            );
        }
        let local_toggle = local_toggle.center();
        let remote_toggle = remote_toggle.center();
        let global_toggle = global_toggle.center();

        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                local_toggle.x,
                local_toggle.y
            ),
            Some(
                super::DesktopMenuRouteShellAction::ToggleJoinSectionCollapsed(
                    super::DesktopJoinSection::Local
                )
            )
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ToggleJoinSectionCollapsed(
                super::DesktopJoinSection::Local,
            ),
        );
        assert_eq!(
            launcher.settings_overrides.get("collapsed-@servers.local"),
            Some(&"true".to_string())
        );
        let local_lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(local_lines.contains(&"section-state: @servers.local collapsed:true".to_string()));
        assert!(!local_lines.iter().any(|line| line.starts_with("local[0]")));
        let local_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let local_texts = local_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("collapsed local join frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(local_texts.contains(&"Local Servers"));
        assert!(!local_texts.iter().any(|text| text.contains("LAN host")));

        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                remote_toggle.x,
                remote_toggle.y
            ),
            Some(
                super::DesktopMenuRouteShellAction::ToggleJoinSectionCollapsed(
                    super::DesktopJoinSection::Remote
                )
            )
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ToggleJoinSectionCollapsed(
                super::DesktopJoinSection::Remote,
            ),
        );
        assert_eq!(
            launcher.settings_overrides.get("collapsed-@servers.remote"),
            Some(&"true".to_string())
        );
        let remote_lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(remote_lines.contains(&"section-state: @servers.remote collapsed:true".to_string()));
        assert!(remote_lines.contains(&"server: collapsed".to_string()));
        let remote_frame = launcher.menu_graphics_frame_for_surface(1, viewport);
        let remote_texts = remote_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("collapsed remote join frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(remote_texts.contains(&"Remote Servers"));
        assert!(!remote_texts.iter().any(|text| text.contains("one.example")));

        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                global_toggle.x,
                global_toggle.y
            ),
            Some(
                super::DesktopMenuRouteShellAction::ToggleJoinSectionCollapsed(
                    super::DesktopJoinSection::Global
                )
            )
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ToggleJoinSectionCollapsed(
                super::DesktopJoinSection::Global,
            ),
        );
        assert_eq!(
            launcher.settings_overrides.get("collapsed-@servers.global"),
            Some(&"true".to_string())
        );
        let global_lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(global_lines.contains(&"section-state: @servers.global collapsed:true".to_string()));
        assert!(!global_lines
            .iter()
            .any(|line| line.starts_with("community[0]")));
        let show_hidden = DesktopLauncher::join_route_show_hidden_button_rect_for_panel(panel);
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                show_hidden.center().x,
                show_hidden.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleJoinShowHidden)
        );
        let global_frame = launcher.menu_graphics_frame_for_surface(2, viewport);
        let global_texts = global_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("collapsed global join frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(global_texts.contains(&"Community Servers"));
        assert!(!global_texts.contains(&"@servers.community"));
        assert!(!global_texts.contains(&"@servers.showhidden"));
        assert!(!global_texts.contains(&"Official"));

        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: show_hidden.center().x,
                y: show_hidden.center().y,
            }],
        );
        let hovered_global_frame = launcher.menu_graphics_frame_for_surface(2, viewport);
        let hovered_global_texts = hovered_global_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("collapsed global hover frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            hovered_global_texts
                .iter()
                .filter(|text| **text == "Show Hidden Servers")
                .count()
                >= 1
        );
    }

    #[test]
    fn desktop_launcher_join_section_toggles_use_emptyi_image_buttons_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        launcher
            .join_community_groups
            .push(super::DesktopJoinCommunityGroup::new(
                "Official",
                vec!["community.example:6567".into()],
                true,
            ));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        let local_toggle = DesktopLauncher::join_route_section_toggle_rect_for_panel(
            panel,
            super::DesktopJoinSection::Local,
        );
        launcher.last_menu_cursor = Some(local_toggle.center());

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join section toggle frame should render")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let up_icon = super::desktop_ui_icon_glyph_or_label("upOpen", "upOpen");
        let icon_visual = commands.iter().find_map(|command| match command {
            RenderCommand::DrawText {
                text,
                position,
                color,
                style,
                ..
            } if text == &up_icon && *position == local_toggle.center() => Some((*color, *style)),
            _ => None,
        });
        let (icon_color, icon_style) =
            icon_visual.expect("join section toggle upOpen icon should render");
        assert_eq!(
            icon_color,
            mindustry_core::mindustry::ui::UiStyleColor::LightGray.rgba(),
            "Java Styles.emptyi uses imageOverColor=Color.lightGray for hovered section toggle icons"
        );
        assert!(
            icon_style.font == RenderFontId::Icon && !icon_style.outline,
            "Java Styles.emptyi section toggle icon should render as an image glyph without Rust-only outline"
        );
    }

    #[test]
    fn desktop_launcher_join_route_tracks_community_groups_like_java_server_group() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.settings_locale = "en".into();
        launcher.player_locale = "en".into();
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        let mut group = super::DesktopJoinCommunityGroup::new(
            "Official",
            vec!["community.example:6567".into()],
            true,
        );
        group.hosts.push(mindustry_core::mindustry::net::Host::new(
            37,
            "Community Host",
            "community.example",
            6567,
            "sector map",
            1,
            12,
            158,
            "community",
            Gamemode::Survival,
            24,
            "@play raw survival server",
            Some("@mode.survival.name".into()),
        ));
        group.hosts.push(mindustry_core::mindustry::net::Host::new(
            38,
            "Community EU",
            "community-eu.example",
            6568,
            "sector map 2",
            2,
            16,
            158,
            "community",
            Gamemode::Survival,
            32,
            "public survival mirror",
            Some(" @mode.attack.name ".into()),
        ));
        launcher.join_community_groups.push(group);

        let lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(lines.contains(&"section: @servers.global groups: 1".to_string()));
        assert!(lines.contains(
            &"community[0]: Official addresses:1 prioritized:true favorite:false hidden:false hosts:2"
                .to_string()
        ));
        assert!(lines.contains(
            &"community[0] entry[0]: Official addr-count:1 prioritized:true favorite:false hidden:false hosts:2 host-index:0"
                .to_string()
        ));
        assert!(lines.contains(
            &"community[0] entry[1]: Official addr-count:1 prioritized:true favorite:false hidden:false hosts:2 host-index:1"
                .to_string()
        ));
        assert!(lines
            .contains(&"community[0] host[1]: Community EU community-eu.example:6568".to_string()));
        assert!(lines.contains(&"community[0] key: server-Official".to_string()));
        assert!(
            lines.contains(&"community[0] actions: favorite hidden connect host-save".to_string())
        );

        assert!(launcher.set_join_community_group_favorite(0, true));
        assert!(launcher.set_join_community_group_hidden(0, true));
        let hidden_lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(hidden_lines.contains(&"section: @servers.global groups: 0".to_string()));
        launcher.join_show_hidden = true;
        launcher.join_search = "survival".into();
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::RefreshJoinCommunityServers,
        );
        let shown_lines = launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(shown_lines
            .contains(&"section: @servers.community search:survival hidden:on".to_string()));
        assert!(shown_lines.contains(
            &"community[0]: Official addresses:1 prioritized:true favorite:true hidden:true hosts:2"
                .to_string()
        ));

        let surface = DesktopSurfaceSize::new(1280, 720);
        let viewport = launcher.default_render_viewport_for_surface(surface);
        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let commands = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join community frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        let texts = commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&"Official"));
        assert!(texts
            .iter()
            .any(|text| text.contains("Community Host") && text.contains("[gray]v158 community")));
        assert!(texts
            .iter()
            .any(|text| text.contains("@play raw survival server")));
        assert!(
            !texts.iter().any(|text| text.contains("Play raw survival server")),
            "Java JoinDialog.buildServer shows host.description raw; embedded @play must not become a bundle value"
        );
        assert!(
            texts.iter().any(|text| text.contains("@mode.survival.name")),
            "Java JoinDialog.buildServer uses raw host.modeName when non-null; it must not localize @mode.survival.name"
        );
        assert!(texts.contains(&"Community EU   [gray]v158 community"));
        assert!(texts
            .iter()
            .any(|text| text.contains("public survival mirror")));
        assert!(
            !texts.iter().any(|text| text.contains("community.example:6567")),
            "Java JoinDialog.addCommunityHost delegates details to buildServer(..., addName=false), which does not render the host address as a visible text line"
        );
        assert!(
            !texts.iter().any(|text| text.contains("players:")),
            "Java JoinDialog uses Core.bundle.format(\"players\", ...) instead of a hard-coded players: label"
        );
        assert!(texts
            .iter()
            .any(|text| text.contains("12") && text.contains("24") && text.contains("players")));
        assert!(
            !texts.iter().any(|text| text.contains("save.map:")),
            "Java JoinDialog uses Core.bundle.format(\"save.map\", ...) instead of a hard-coded save.map: label"
        );
        assert!(texts
            .iter()
            .any(|text| text.contains("Map: sector map") && text.contains("@mode.survival.name")));
        assert!(
            texts
                .iter()
                .any(|text| text.contains("Map: sector map 2")
                    && text.contains(" @mode.attack.name ")),
            "Java JoinDialog preserves non-null host.modeName exactly except replacing newlines"
        );
        assert!(shown_lines
            .contains(&"section: @servers.community search:survival hidden:on".to_string()));

        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );
        let row = DesktopLauncher::join_route_community_group_row_rect_for_panel(panel, 0);
        let second_row = DesktopLauncher::join_route_community_group_row_rect_for_panel(panel, 1);
        assert!(
            second_row.x > row.x && (second_row.y - row.y).abs() < 0.01,
            "Java JoinDialog lays community hosts across columns() before starting the next row"
        );
        let community_header = DesktopLauncher::join_route_community_group_header_rect(row);
        let community_body = RenderRect::new(
            row.x,
            row.y,
            row.width,
            row.height - super::JOIN_COMMUNITY_GROUP_HEADER_HEIGHT,
        );
        let first_host_header = DesktopLauncher::join_route_community_host_header_rect(row, true);
        let second_host_header =
            DesktopLauncher::join_route_community_host_header_rect(second_row, false);
        let second_host_body =
            DesktopLauncher::join_route_community_host_body_rect(second_row, false);
        let white_pane = DesktopLauncher::settings_drawable_symbol("whitePane");
        let white_ui = DesktopLauncher::settings_drawable_symbol("whiteui");
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &white_pane && *rect == community_body
        )));
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &white_ui && *rect == community_header
            )),
            "Java JoinDialog.addHeader() uses transparent group header layout text + 3f image divider, not a full whiteui header block"
        );
        let community_header_line =
            DesktopLauncher::join_route_community_group_header_line_rect_for_label_width(
                row,
                launcher.join_route_community_group_header_label_width_like_java("Official"),
            );
        let favorite_button_for_header_line =
            DesktopLauncher::join_route_community_group_action_button_rect(row, 0);
        assert_eq!(community_header_line.height, 3.0);
        assert!(community_header_line.x > community_header.x + 12.0);
        assert!(community_header_line.right() < favorite_button_for_header_line.x);
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &white_ui && *rect == community_header_line
        )),
            "Java JoinDialog.addHeader() draws head.image().height(3f).growX().color(col) after the group label"
        );
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &white_ui && *rect == first_host_header
        )));
        assert_eq!(
            first_host_header.height,
            super::JOIN_COMMUNITY_HOST_HEADER_HEIGHT,
            "Java JoinDialog.addCommunityHost() adds a 45f whiteui host title bar under the group header"
        );
        let second_community_header = RenderRect::new(
            second_row.x,
            second_row.y + second_row.height - super::JOIN_COMMUNITY_GROUP_HEADER_HEIGHT,
            second_row.width,
            super::JOIN_COMMUNITY_GROUP_HEADER_HEIGHT,
        );
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &white_ui && *rect == second_community_header
            )),
            "Java JoinDialog addHeader(...) belongs to the group once; additional host rows must not repeat the group header"
        );
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &white_ui && *rect == second_host_header
        )));
        assert!(commands.iter().any(|command| matches!(
            command,
            RenderCommand::DrawSprite { symbol, rect, .. }
                if symbol == &white_pane && *rect == second_host_body
        )));
        let pane = DesktopLauncher::settings_drawable_symbol("pane");
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == &pane && *rect == row
            )),
            "Java JoinDialog community host rows use whiteui/whitePane-style table layers, not a Rust-only full pane card"
        );
        let favorite_button =
            DesktopLauncher::join_route_community_group_action_button_rect(row, 0);
        let hidden_button = DesktopLauncher::join_route_community_group_action_button_rect(row, 1);
        let add_button = DesktopLauncher::join_route_community_host_add_button_rect(row);
        for button in [favorite_button, hidden_button] {
            assert_eq!(button.width, 40.0);
            assert_eq!(button.height, 40.0);
        }
        assert_eq!(
            add_button.width,
            super::JOIN_COMMUNITY_HOST_HEADER_HEIGHT
                - super::JOIN_COMMUNITY_HOST_ADD_BUTTON_MARGIN_LIKE_JAVA * 2.0
        );
        assert_eq!(add_button.height, add_button.width);
        assert_eq!(
            add_button.right(),
            first_host_header.right() - super::JOIN_COMMUNITY_HOST_ADD_BUTTON_RIGHT_PAD_LIKE_JAVA,
            "Java JoinDialog.addCommunityHost() keeps the add ImageButton inside the 45f title bar with padRight(4f)"
        );
        assert_eq!(
            add_button.y,
            first_host_header.y + super::JOIN_COMMUNITY_HOST_ADD_BUTTON_MARGIN_LIKE_JAVA,
            "Java JoinDialog.addCommunityHost() applies margin(3f) around the add ImageButton"
        );
        let community_host_title_style = commands.iter().find_map(|command| match command {
            RenderCommand::DrawText {
                text,
                position,
                style,
                ..
            } if text.contains("Community Host") && first_host_header.contains_point(*position) => {
                Some(*style)
            }
            _ => None,
        });
        assert_eq!(
            community_host_title_style.and_then(|style| style.wrap_width),
            Some(DesktopLauncher::join_route_server_card_text_width_like_java(row)),
            "Java JoinDialog community host title uses targetWidth()-40f instead of deriving width from the add button rect"
        );
        let defaulti = DesktopLauncher::settings_image_button_symbol("defaulti", false, false);
        for (button, name) in [
            (favorite_button, "favorite star"),
            (hidden_button, "hidden eye"),
            (add_button, "community host add"),
        ] {
            assert!(
                !commands.iter().any(|command| matches!(
                    command,
                    RenderCommand::DrawSprite { symbol, rect, .. }
                        if symbol == &defaulti && *rect == button
                )),
                "Java JoinDialog uses custom/Styles.grayi/Styles.emptyi ImageButton skins for {name}, not Rust-only defaulti chrome"
            );
        }
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { rect, .. } if *rect == favorite_button
            )),
            "Java JoinDialog favorite star uses a custom ImageButtonStyle with icon colors only, not an emptyi/defaulti background sprite"
        );
        for (button, icon, name) in [
            (favorite_button, "star", "favorite star"),
            (hidden_button, "eyeOffSmall", "hidden eye"),
            (add_button, "add", "community host add"),
        ] {
            let glyph = super::desktop_ui_icon_glyph_or_label(icon, icon);
            let style = commands.iter().find_map(|command| match command {
                RenderCommand::DrawText {
                    text,
                    position,
                    style,
                    ..
                } if text == &glyph && button.contains_point(*position) => Some(*style),
                _ => None,
            });
            assert!(
                style.map(|style| !style.outline).unwrap_or(false),
                "Java JoinDialog {name} is an ImageButton icon, not outlined Rust text"
            );
        }
        let favorite_button = favorite_button.center();
        let hidden_button = hidden_button.center();
        let add_button = add_button.center();
        let connect_button = row.center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                favorite_button.x,
                favorite_button.y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleJoinCommunityFavorite(0))
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                hidden_button.x,
                hidden_button.y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleJoinCommunityHidden(0))
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                add_button.x,
                add_button.y
            ),
            Some(super::DesktopMenuRouteShellAction::AddJoinCommunityHostToSaved(0, 0))
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                connect_button.x,
                connect_button.y
            ),
            Some(super::DesktopMenuRouteShellAction::ConnectJoinCommunityHost(0, 0))
        );
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                second_row.center().x,
                second_row.center().y
            ),
            Some(super::DesktopMenuRouteShellAction::ConnectJoinCommunityHost(0, 1)),
            "Java JoinDialog renders each resolved community host as its own connectable entry"
        );
        let second_row_star =
            DesktopLauncher::join_route_community_group_action_button_rect(second_row, 0).center();
        assert_ne!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                second_row_star.x,
                second_row_star.y
            ),
            Some(super::DesktopMenuRouteShellAction::ToggleJoinCommunityFavorite(0)),
            "only the first group header row should expose favorite/hidden buttons"
        );
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: favorite_button.x,
                y: favorite_button.y,
            }],
        );
        let hovered_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let hovered_texts = hovered_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join community hover frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            !hovered_texts.contains(&"Favorite"),
            "Java JoinDialog only attaches a Tooltip to the hidden/eye button; the favorite star has no tooltip"
        );
        launcher.apply_menu_input_events(
            surface,
            &[DesktopInputTickEvent::CursorMoved {
                x: hidden_button.x,
                y: hidden_button.y,
            }],
        );
        let hovered_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let hovered_texts = hovered_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join community hidden hover frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            hovered_texts.contains(&"Hidden"),
            "Java JoinDialog keeps the hidden/eye tooltip"
        );
        let tooltip_width = ("Hidden".chars().count() as f32 * 10.0 + 8.0).clamp(56.0, 320.0);
        let tooltip_height = 28.0;
        let hidden_tooltip = RenderRect::new(
            (hidden_button.x + 14.0)
                .min(panel.right() - tooltip_width - 4.0)
                .max(panel.x + 4.0),
            (hidden_button.y + 14.0)
                .min(panel.y + panel.height - tooltip_height - 4.0)
                .max(panel.y + 4.0),
            tooltip_width,
            tooltip_height,
        );
        let (black6_symbol, black6_tint) =
            DesktopLauncher::settings_drawable_symbol_and_tint("black6", 1.0);
        let hovered_commands = hovered_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join community hidden hover frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .collect::<Vec<_>>();
        assert!(
            hovered_commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, tint, .. }
                    if symbol == &black6_symbol && *rect == hidden_tooltip && *tint == black6_tint
            )),
            "Java JoinDialog hidden tooltip uses Styles.black6 background"
        );
        assert!(
            hovered_commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawText { text, size, .. }
                    if text == "Hidden"
                        && (*size - super::SETTINGS_JAVA_DEFAULT_FONT_SIZE).abs() < f32::EPSILON
            )),
            "Java Tooltip uses the default label font scale instead of the earlier compact Rust-only 11px text"
        );
        assert!(
            !hovered_commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect { rect, .. } if *rect == hidden_tooltip
            )),
            "Java Tooltip(t -> t.background(Styles.black6).margin(4)) does not add Rust-only tooltip stroke chrome"
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ToggleJoinCommunityFavorite(0),
        );
        assert_eq!(
            launcher.settings_overrides.get("server-Official-favorite"),
            Some(&"false".to_string())
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ToggleJoinCommunityHidden(0),
        );
        assert_eq!(
            launcher.settings_overrides.get("server-Official-hidden"),
            Some(&"false".to_string())
        );
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::AddJoinCommunityHostToSaved(0, 1),
        );
        assert!(launcher
            .join_saved_servers
            .contains(&super::DesktopConnectTarget {
                host: "community-eu.example".into(),
                port: 6568,
            }));
        assert!(launcher
            .settings_overrides
            .get(super::JOIN_SERVERS_SETTINGS_KEY)
            .is_some_and(|servers| servers.contains("community-eu.example")));
        launcher.connect_target = None;
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ConnectJoinCommunityHost(0, 1),
        );
        assert_eq!(
            launcher.join_server_disclaimer_pending_target,
            Some(super::DesktopConnectTarget {
                host: "community-eu.example".into(),
                port: 6568,
            })
        );
        assert_eq!(launcher.connect_target, None);
        let disclaimer_lines =
            launcher.active_menu_route_shell_lines(super::DesktopMenuRoute::Join);
        assert!(disclaimer_lines.contains(&"dialog: @warning @servers.disclaimer".to_string()));

        let disclaimer_dialog =
            DesktopLauncher::join_server_disclaimer_dialog_rect_for_panel(panel);
        let disclaimer_ok =
            DesktopLauncher::join_add_dialog_button_rect(disclaimer_dialog, 1).center();
        assert_eq!(
            launcher.active_menu_route_shell_action_at_surface_point(
                surface,
                disclaimer_ok.x,
                disclaimer_ok.y
            ),
            Some(super::DesktopMenuRouteShellAction::ConfirmJoinServerDisclaimer)
        );
        let disclaimer_frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let disclaimer_texts = disclaimer_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("join community disclaimer frame should contain render frame")
            .passes
            .iter()
            .flat_map(|pass| pass.commands.iter())
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(disclaimer_texts.contains(&"Warning!"));
        let disclaimer_body = launcher.localize_bundle_markup_text("@servers.disclaimer");
        assert!(disclaimer_texts.iter().any(|text| text == &disclaimer_body));
        launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ConfirmJoinServerDisclaimer,
        );
        assert!(launcher.join_server_disclaimer_accepted);
        assert_eq!(
            launcher
                .settings_overrides
                .get(super::JOIN_SERVER_DISCLAIMER_SETTINGS_KEY),
            Some(&"true".to_string())
        );
        assert_eq!(
            launcher.connect_target,
            Some(super::DesktopConnectTarget {
                host: "community-eu.example".into(),
                port: 6568,
            })
        );

        let mut trusted_launcher = DesktopLauncher::new(Vec::new());
        trusted_launcher.join_community_groups = launcher.join_community_groups.clone();
        trusted_launcher.settings_overrides.insert(
            super::JOIN_SERVER_DISCLAIMER_SETTINGS_KEY.into(),
            "true".into(),
        );
        trusted_launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ConnectJoinCommunityGroup(0),
        );
        assert_eq!(trusted_launcher.join_server_disclaimer_pending_target, None);
        assert_eq!(
            trusted_launcher.connect_target,
            Some(super::DesktopConnectTarget {
                host: "community.example".into(),
                port: 6567,
            })
        );
        trusted_launcher.connect_target = None;
        trusted_launcher.dispatch_menu_route_shell_action(
            super::DesktopMenuRouteShellAction::ConnectJoinCommunityHost(0, 1),
        );
        assert_eq!(
            trusted_launcher.connect_target,
            Some(super::DesktopConnectTarget {
                host: "community-eu.example".into(),
                port: 6568,
            })
        );
    }

    #[test]
