    #[test]
    fn desktop_launcher_menu_frame_for_render_uses_menu_payload_without_world_bundle() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let frame = launcher.menu_frame_for_render(MenuFrameInput {
            graphics_width: 640.0,
            graphics_height: 360.0,
            scene_margin_top: 0.0,
            scene_margin_bottom: 0.0,
            scl4: 1.25,
            delta: 0.016,
        });

        assert_eq!(frame.kind, DesktopFrameKind::Menu);
        match frame.payload {
            DesktopFramePayload::Menu(plan) => {
                assert!(!plan.commands.is_empty());
            }
            DesktopFramePayload::World(_) => {
                panic!("menu frame must not contain a world bundle");
            }
            DesktopFramePayload::Load(_) => {
                panic!("menu frame must not use load payload");
            }
        }
    }

    #[test]
    fn desktop_launcher_reuses_finalized_menu_ui_render_command_cache_when_unchanged() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let input = MenuFrameInput::new(1280.0, 720.0, 4.0, 1.0 / 60.0);

        let first = launcher.menu_frame_for_render(input);
        let DesktopFramePayload::Menu(first_plan) = first.payload else {
            panic!("menu_frame_for_render should return menu payload");
        };
        assert_eq!(
            launcher.finalized_menu_ui_render_command_cache_rebuilds(),
            1
        );
        assert_eq!(
            first_plan.ui_render_commands,
            first_plan.ui.to_render_commands()
        );

        let second = launcher.menu_frame_for_render(input);
        let DesktopFramePayload::Menu(second_plan) = second.payload else {
            panic!("menu_frame_for_render should return menu payload");
        };
        assert_eq!(
            launcher.finalized_menu_ui_render_command_cache_rebuilds(),
            1,
            "time-only menu frames should reuse the localized/hover-finalized UI render command cache"
        );
        assert_eq!(
            first_plan.ui_render_commands,
            second_plan.ui_render_commands
        );
    }

    #[test]
    fn desktop_launcher_keeps_finalized_menu_ui_render_command_cache_during_submenu_fade() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        assert!(launcher
            .menu_renderer_state
            .select_desktop_root(MenuButtonRole::Play));

        let input = |delta| MenuFrameInput::new(1280.0, 720.0, 4.0, delta);
        let opened = launcher.menu_frame_for_render(input(0.0));
        let DesktopFramePayload::Menu(opened_plan) = opened.payload else {
            panic!("menu_frame_for_render should return menu payload");
        };
        assert_eq!(
            launcher.finalized_menu_ui_render_command_cache_rebuilds(),
            1
        );
        assert_eq!(opened_plan.ui.submenu_alpha, 0.0);
        assert_eq!(
            opened_plan.ui_render_commands,
            opened_plan.ui.to_render_commands()
        );

        let fading = launcher.menu_frame_for_render(input(MENU_SUBMENU_FADE_IN_SECONDS * 0.5));
        let DesktopFramePayload::Menu(fading_plan) = fading.payload else {
            panic!("menu_frame_for_render should return menu payload");
        };
        assert_eq!(
            launcher.finalized_menu_ui_render_command_cache_rebuilds(),
            1,
            "desktop-localized submenu alpha changes should reuse cached command groups"
        );
        assert!((fading_plan.ui.submenu_alpha - 0.5).abs() < 0.0001);
        assert_eq!(
            fading_plan.ui_render_commands,
            fading_plan.ui.to_render_commands()
        );
        assert_ne!(
            opened_plan.ui_render_commands, fading_plan.ui_render_commands,
            "frame output should still reflect current submenu fade alpha"
        );
    }

    #[test]
    fn desktop_launcher_menu_graphics_frame_for_surface_uses_single_ui_command_build() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);

        let first = launcher.menu_graphics_frame_for_surface(0, viewport);
        assert!(
            first
                .bundle
                .render_frame
                .as_ref()
                .is_some_and(|frame| frame.passes.iter().any(|pass| !pass.commands.is_empty())),
            "desktop menu graphics path must still emit visible menu commands"
        );
        assert_eq!(
            launcher.menu_renderer_state.ui_render_command_cache_rebuilds, 0,
            "desktop finalization replaces core UI commands, so the hot graphics path must not build the discarded core UI command cache"
        );
        assert_eq!(
            launcher.finalized_menu_ui_render_command_cache_rebuilds(),
            1
        );

        let _second = launcher.menu_graphics_frame_for_surface(1, viewport);
        assert_eq!(
            launcher
                .menu_renderer_state
                .ui_render_command_cache_rebuilds,
            0,
            "stable menu graphics frames should keep core UI command generation skipped"
        );
        assert_eq!(
            launcher.finalized_menu_ui_render_command_cache_rebuilds(),
            1,
            "stable menu graphics frames should reuse the localized desktop UI command cache"
        );
    }

    #[test]
    fn desktop_launcher_menu_graphics_frame_for_surface_reuses_active_route_shell_cache() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);

        let first = launcher.menu_graphics_frame_for_surface(0, viewport);
        assert!(
            first
                .bundle
                .render_frame
                .as_ref()
                .is_some_and(|frame| frame.passes.iter().any(|pass| !pass.commands.is_empty())),
            "active route shell cache must still emit visible render commands"
        );
        assert_eq!(launcher.active_menu_route_shell_cache_rebuilds(), 1);

        let _second = launcher.menu_graphics_frame_for_surface(1, viewport);
        assert_eq!(
            launcher.active_menu_route_shell_cache_rebuilds(),
            1,
            "time-only menu frames should reuse the active route dialog shell cache"
        );

        let resized = RenderViewport::new(0.0, 0.0, 1024.0, 720.0);
        let _resized_frame = launcher.menu_graphics_frame_for_surface(2, resized);
        assert_eq!(
            launcher.active_menu_route_shell_cache_rebuilds(),
            2,
            "viewport changes must rebuild active route dialog shell chrome"
        );
    }

    #[test]
    fn desktop_active_route_shell_uses_java_basedialog_skin_without_extra_panel_stroke() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.active_menu_route = Some(super::DesktopMenuRoute::Join);
        let viewport = RenderViewport::new(0.0, 0.0, 1280.0, 720.0);
        let panel = DesktopLauncher::active_menu_route_shell_panel_for_route(
            viewport,
            super::DesktopMenuRoute::Join,
        );

        let frame = launcher.menu_graphics_frame_for_surface(0, viewport);
        let render_frame = frame
            .bundle
            .render_frame
            .as_ref()
            .expect("active route should render a menu frame");
        let commands = &render_frame.passes[0].commands;

        assert!(
            commands.iter().any(|command| matches!(
                command,
                RenderCommand::DrawSprite { symbol, rect, .. }
                    if symbol == "window-empty.9" && *rect == panel
            )),
            "Java BaseDialog route shell should be skinned by Tex.windowEmpty/window-empty.9"
        );
        assert!(
            !commands.iter().any(|command| matches!(
                command,
                RenderCommand::StrokeRect {
                    rect,
                    color,
                    thickness,
                    ..
                } if *rect == panel
                    && *color == [0.32, 0.42, 0.5, 0.95]
                    && (*thickness - 2.0).abs() < f32::EPSILON
            )),
            "Java BaseDialog does not add the Rust-only blue-gray full-panel stroke on top of its window-empty.9 skin"
        );
    }

