    #[test]
    fn desktop_launcher_load_frame_for_render_uses_load_payload_without_world_bundle() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let mut input = LoadFrameInput::new(800.0, 600.0, 1.0, 0.25, LoadStage::Initializing, 0.42);
        input.prompt = Some("initializing".to_string());
        input.completion = Some("done".to_string());
        let loading_label = launcher.localize_bundle_markup_text("initializing");

        let frame = launcher.load_frame_for_render(input);

        assert_eq!(frame.kind, DesktopFrameKind::Load);
        match frame.payload {
            DesktopFramePayload::Load(plan) => {
                assert_eq!(plan.stage, LoadStage::Initializing);
                assert!(!plan.commands.is_empty());
                let pass = plan
                    .to_render_pass()
                    .expect("desktop load payload should convert into a visible render pass");
                assert_eq!(pass.kind, RenderPassKind::Custom("load".to_string()));
                assert!(
                    pass.commands
                        .iter()
                        .any(|command| matches!(command, RenderCommand::Clear { .. })),
                    "load frame pass must clear the screen before drawing LoadingFragment visuals"
                );
                assert!(
                    pass.commands.iter().any(|command| {
                        matches!(command, RenderCommand::DrawText { text, .. } if text == &loading_label)
                    }),
                    "desktop load payload must localize the LoadingFragment label before rendering so startup never becomes an empty black frame"
                );
                assert!(
                    pass.commands.iter().any(|command| {
                        matches!(command, RenderCommand::FillRect { rect, color, .. }
                            if *rect == RenderRect::new(0.0, 0.0, 800.0, 600.0)
                                && *color == [0.0, 0.0, 0.0, 0.80])
                    }),
                    "desktop load payload must include the full-screen Java LoadingFragment overlay"
                );
            }
            DesktopFramePayload::World(_) => {
                panic!("load frame must not contain a world bundle");
            }
            DesktopFramePayload::Menu(_) => {
                panic!("load frame must not use menu payload");
            }
        }
    }

    #[test]
    fn desktop_launcher_loading_fragment_state_builds_java_like_load_frames() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        let surface = DesktopSurfaceSize::new(800, 600);

        assert_eq!(
            launcher.loading_fragment_frame_for_surface(surface, 0.0),
            None
        );

        launcher.show_loading_fragment_like_java("@loading");
        let loading_label = launcher.localize_bundle_markup_text("@loading");
        let cancel_label = launcher.localize_bundle_markup_text("@cancel");
        let shown = launcher
            .loading_fragment_frame_for_surface(surface, 0.0)
            .expect("shown Java LoadingFragment should produce a desktop load frame");
        let DesktopFramePayload::Load(shown_plan) = shown.payload else {
            panic!("shown LoadingFragment should use load payload");
        };
        assert!(!shown_plan
            .commands
            .iter()
            .any(|command| matches!(command, LoadRenderCommand::ProgressBar { .. })));
        let shown_pass = shown_plan
            .to_render_pass()
            .expect("shown LoadingFragment should produce visible render commands");
        let shown_texts = shown_pass
            .commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(shown_texts.contains(&loading_label.as_str()));
        assert!(!shown_texts.contains(&"@loading"));
        assert!(!shown_texts.contains(&cancel_label.as_str()));
        assert!(!shown_texts.contains(&"@cancel"));

        launcher.set_loading_fragment_progress_like_java(0.5);
        launcher.set_loading_fragment_button_like_java();
        let with_progress = launcher
            .loading_fragment_frame_for_surface(surface, 1.0 / 60.0)
            .expect("progressed Java LoadingFragment should still produce a desktop load frame");
        let DesktopFramePayload::Load(progress_plan) = with_progress.payload else {
            panic!("progressed LoadingFragment should use load payload");
        };
        assert_eq!(progress_plan.stage, LoadStage::LoadingAssets);
        assert_eq!(progress_plan.progress, 0.5);
        assert!(progress_plan
            .commands
            .iter()
            .any(|command| matches!(command, LoadRenderCommand::ProgressBar { .. })));
        let progress_pass = progress_plan
            .to_render_pass()
            .expect("progressed LoadingFragment should produce visible render commands");
        let progress_texts = progress_pass
            .commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(progress_texts.contains(&cancel_label.as_str()));
        assert!(!progress_texts.contains(&"@cancel"));

        launcher.hide_loading_fragment_like_java();
        assert_eq!(
            launcher.loading_fragment_frame_for_surface(surface, 0.0),
            None
        );
    }

