    #[test]
    fn desktop_launcher_pending_load_and_save_sync_loading_fragment_state() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.start_load_game_pending_load(super::DesktopLoadGameAction {
            slot: "7".into(),
            file: "missing.msav".into(),
            map_name: Some("Test Map".into()),
            timestamp: 0,
            kind: super::DesktopLoadGameActionKind::Load,
            status: "selected-for-load".into(),
        });
        assert!(launcher.loading_fragment_state.visible);
        assert_eq!(launcher.loading_fragment_state.text, "@loading");
        assert!(launcher.loading_fragment_state.progress_visible);
        assert_eq!(launcher.loading_fragment_state.progress, 0.0);

        launcher.tick_load_game_pending_load();
        let expected_load_progress = 1.0 / super::LOAD_GAME_LOADING_DELAY_FRAMES as f32;
        assert!(
            (launcher.loading_fragment_state.progress - expected_load_progress).abs()
                < f32::EPSILON
        );
        let load_frame = launcher
            .loading_fragment_frame_for_surface(DesktopSurfaceSize::new(800, 600), 1.0 / 60.0)
            .expect("pending LoadDialog operation should expose a LoadingFragment load frame");
        let DesktopFramePayload::Load(load_plan) = load_frame.payload else {
            panic!("pending load should use load payload");
        };
        assert!((load_plan.progress - expected_load_progress).abs() < f32::EPSILON);

        launcher.load_game_pending_load = None;
        launcher.loading_fragment_state.hide();
        launcher.start_save_game_pending_save(super::DesktopSaveGamePendingOperation::New {
            name: "Alpha".into(),
        });
        assert!(launcher.loading_fragment_state.visible);
        assert_eq!(launcher.loading_fragment_state.text, "@saving");
        assert!(launcher.loading_fragment_state.progress_visible);
        assert_eq!(launcher.loading_fragment_state.progress, 0.0);

        launcher.tick_save_game_pending_save();
        let expected_save_progress = 1.0 / super::SAVE_GAME_SAVING_DELAY_FRAMES as f32;
        assert!(
            (launcher.loading_fragment_state.progress - expected_save_progress).abs()
                < f32::EPSILON
        );
        let save_frame = launcher
            .loading_fragment_frame_for_surface(DesktopSurfaceSize::new(800, 600), 1.0 / 60.0)
            .expect("pending SaveDialog operation should expose a LoadingFragment load frame");
        let DesktopFramePayload::Load(save_plan) = save_frame.payload else {
            panic!("pending save should use load payload");
        };
        assert!((save_plan.progress - expected_save_progress).abs() < f32::EPSILON);
    }

    #[test]
    fn desktop_launcher_mods_github_download_syncs_loading_fragment_state() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.remember_mods_import_github_request_like_java(
            super::DesktopModsImportGithubRequest {
                repo: "author/example".into(),
                is_java: false,
                release: None,
            },
        );

        assert!(launcher.mods_import_github_loadfrag_visible());
        assert!(launcher.loading_fragment_state.visible);
        assert_eq!(launcher.loading_fragment_state.text, "@downloading");
        assert!(launcher.loading_fragment_state.progress_visible);
        assert_eq!(launcher.loading_fragment_state.progress, 0.0);
        assert!(launcher.loading_fragment_state.cancelable);
        let frame = launcher
            .loading_fragment_frame_for_surface(DesktopSurfaceSize::new(800, 600), 1.0 / 60.0)
            .expect("mods GitHub download should expose a LoadingFragment load frame");
        let DesktopFramePayload::Load(plan) = frame.payload else {
            panic!("mods GitHub download should use load payload");
        };
        assert_eq!(plan.progress, 0.0);
        let pass = plan
            .to_render_pass()
            .expect("mods GitHub LoadingFragment should render");
        let texts = pass
            .commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawText { text, .. } => Some(text.as_str()),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(texts.contains(&launcher.localize_bundle_markup_text("@cancel").as_str()));
        assert!(!texts.contains(&"@cancel"));

        assert!(launcher.set_mods_import_github_download_progress_like_java(0.42));
        assert_eq!(
            launcher
                .mods_import_github_download_state
                .as_ref()
                .unwrap()
                .progress,
            0.42
        );
        assert_eq!(launcher.loading_fragment_state.progress, 0.42);
        let progress_frame = launcher
            .loading_fragment_frame_for_surface(DesktopSurfaceSize::new(800, 600), 1.0 / 60.0)
            .expect("mods GitHub progress tick should expose a LoadingFragment load frame");
        let DesktopFramePayload::Load(progress_plan) = progress_frame.payload else {
            panic!("mods GitHub progress tick should use load payload");
        };
        assert_eq!(progress_plan.progress, 0.42);

        launcher.cancel_mods_import_github_download_like_java();
        assert_eq!(launcher.mods_import_github_download_state, None);
        assert!(!launcher.loading_fragment_state.visible);

        launcher.remember_mods_import_github_request_like_java(
            super::DesktopModsImportGithubRequest {
                repo: "author/error".into(),
                is_java: false,
                release: None,
            },
        );
        assert!(launcher.loading_fragment_state.visible);
        launcher.record_mods_import_github_error_like_java(
            "author/error".into(),
            "mods/authorerror.zip".into(),
            "authorerror".into(),
            "network failure".into(),
        );
        assert_eq!(launcher.mods_import_github_download_state, None);
        assert!(!launcher.loading_fragment_state.visible);
    }

    #[test]
    fn desktop_launcher_world_graphics_frame_is_not_affected_by_menu_or_load_renderer_state() {
        let viewport = RenderViewport::new(0.0, 0.0, 32.0, 32.0);
        let camera = RenderCamera::new(RenderPoint::new(16.0, 16.0), viewport);
        let minimap_camera = MinimapCamera::new(16.0, 16.0, 32.0, 32.0);

        let mut baseline = DesktopLauncher::new(Vec::new());
        let baseline_frame = baseline.graphics_frame_for_render(
            7,
            camera,
            viewport,
            minimap_camera,
            sample_minimap_overlay_input(true),
        );
        let baseline_render_frame = baseline_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("world graphics frame should contain a render frame");
        assert!(
            baseline_render_frame
                .passes
                .iter()
                .any(super::render_pass_has_screen_visible_commands),
            "Playing/world graphics frame should never submit an all-invisible frame"
        );

        let mut polluted = DesktopLauncher::new(Vec::new());
        let menu_frame = polluted.menu_frame_for_render(MenuFrameInput {
            graphics_width: 640.0,
            graphics_height: 360.0,
            scene_margin_top: 0.0,
            scene_margin_bottom: 0.0,
            scl4: 1.25,
            delta: 0.5,
        });
        let mut load_input = LoadFrameInput::new(640.0, 360.0, 1.0, 0.5, LoadStage::Failed, 0.75);
        load_input.error = Some("failure".to_string());
        let load_frame = polluted.load_frame_for_render(load_input);

        assert!(matches!(menu_frame.payload, DesktopFramePayload::Menu(_)));
        assert!(matches!(load_frame.payload, DesktopFramePayload::Load(_)));

        let polluted_frame = polluted.graphics_frame_for_render(
            7,
            camera,
            viewport,
            minimap_camera,
            sample_minimap_overlay_input(true),
        );

        assert_eq!(baseline_frame, polluted_frame);
        let polluted_render_frame = polluted_frame
            .bundle
            .render_frame
            .as_ref()
            .expect("polluted world graphics frame should contain a render frame");
        assert!(
            polluted_render_frame
                .passes
                .iter()
                .any(super::render_pass_has_screen_visible_commands),
            "Menu/Loading state must not leave the Playing/world frame invisible"
        );
    }

    #[test]
    fn desktop_launcher_standard_effect_draw_updates_ripple_lifetime() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher
            .runtime
            .client_local_effect_events
            .push(EffectCallPacket2 {
                effect: EffectCallPacket {
                    effect_id: standard_effect_id("ripple").unwrap() as u16,
                    x: 8.0,
                    y: 16.0,
                    rotation: 2.0,
                    color: type_io::RgbaColor::new(-1),
                },
                data: TypeValue::Null,
            });

        assert_eq!(launcher.materialize_local_effect_events_for_render(), 1);
        assert_eq!(
            launcher
                .runtime
                .client_local_effect_entities
                .get(&-1)
                .unwrap()
                .lifetime,
            30.0
        );

        let plans = launcher.collect_standard_local_effect_draw_plans_for_render();
        assert_eq!(plans.len(), 1);
        assert_eq!(plans[0].kind, StandardEffectDrawKind::StrokedCircle);
        assert_eq!(plans[0].center, (8.0, 16.0));
        assert_eq!(plans[0].color_mul, 1.5);
        assert!((plans[0].radius - 4.0).abs() < 0.0001);
        assert_eq!(launcher.draw_standard_local_effect_states_for_render(), 1);
        assert_eq!(
            launcher
                .runtime
                .client_local_effect_entities
                .get(&-1)
                .unwrap()
                .lifetime,
            60.0
        );

        launcher.standard_local_effect_draw_plans = plans;
        launcher.standard_local_effect_circle_primitives =
            launcher.collect_standard_local_effect_circle_primitives_for_render();
        assert_eq!(launcher.standard_local_effect_circle_primitives.len(), 1);
        launcher.standard_local_effect_square_primitives =
            launcher.collect_standard_local_effect_square_primitives_for_render();
        assert!(launcher.standard_local_effect_square_primitives.is_empty());
        launcher.standard_local_effect_line_primitives =
            launcher.collect_standard_local_effect_line_primitives_for_render();
        assert!(launcher.standard_local_effect_line_primitives.is_empty());
        launcher.standard_local_effect_light_primitives =
            launcher.collect_standard_local_effect_light_primitives_for_render();
        assert!(launcher.standard_local_effect_light_primitives.is_empty());
        launcher.clear_snapshot_apply_cursors();
        assert!(launcher.standard_local_effect_draw_plans.is_empty());
        assert!(launcher.standard_local_effect_circle_primitives.is_empty());
        assert!(launcher.standard_local_effect_square_primitives.is_empty());
        assert!(launcher.standard_local_effect_line_primitives.is_empty());
        assert!(launcher.standard_local_effect_light_primitives.is_empty());
    }

    #[test]
    fn desktop_launcher_caches_fire_light_primitives_for_render() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher
            .runtime
            .client_local_effect_events
            .push(EffectCallPacket2 {
                effect: EffectCallPacket {
                    effect_id: standard_effect_id("fire").unwrap() as u16,
                    x: 32.0,
                    y: 48.0,
                    rotation: 0.0,
                    color: type_io::RgbaColor::new(-1),
                },
                data: TypeValue::Null,
            });

        launcher.update();

        assert_eq!(launcher.standard_local_effect_draw_plans.len(), 1);
        assert_eq!(
            launcher.standard_local_effect_draw_plans[0].kind,
            StandardEffectDrawKind::SeededCircleParticles
        );
        assert_eq!(launcher.standard_local_effect_circle_primitives.len(), 2);
        assert!(launcher.standard_local_effect_square_primitives.is_empty());
        assert!(launcher.standard_local_effect_line_primitives.is_empty());
        assert_eq!(launcher.standard_local_effect_light_primitives.len(), 1);
        let frame = launcher.standard_effect_render_frame();
        assert_eq!(frame.draw_plans.len(), 1);
        assert_eq!(frame.circle_primitives.len(), 2);
        assert!(frame.square_primitives.is_empty());
        assert!(frame.line_primitives.is_empty());
        assert_eq!(frame.light_primitives.len(), 1);
        assert_eq!(
            frame.draw_plans[0],
            launcher.standard_local_effect_draw_plans[0]
        );
        assert_eq!(
            frame.circle_primitives,
            launcher.standard_local_effect_circle_primitives
        );
        assert_eq!(
            frame.square_primitives,
            launcher.standard_local_effect_square_primitives
        );
        assert_eq!(
            frame.line_primitives,
            launcher.standard_local_effect_line_primitives
        );
        let light = &launcher.standard_local_effect_light_primitives[0];
        assert_eq!(light.center, (32.0, 48.0));
        assert!((light.radius - 0.8).abs() < 0.0001);
        assert_eq!(light.color, "Pal.lightFlame");
        assert_eq!(light.opacity, 0.5);

        let mut renderer = HeadlessDesktopEffectRenderer::default();
        let stats = launcher.render_standard_effect_frame_with(&mut renderer);
        assert_eq!(renderer.frames_rendered, 1);
        assert_eq!(
            stats,
            DesktopEffectRenderStats {
                draw_plans: 1,
                circle_primitives: 2,
                square_primitives: 0,
                rect_primitives: 0,
                line_primitives: 0,
                triangle_primitives: 0,
                light_primitives: 1
            }
        );
        assert_eq!(renderer.last_stats, stats);
    }

    #[test]
    fn desktop_launcher_routes_standard_effect_circles_into_graphics_backend() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher
            .runtime
            .client_local_effect_events
            .push(EffectCallPacket2 {
                effect: EffectCallPacket {
                    effect_id: standard_effect_id("fire").unwrap() as u16,
                    x: 32.0,
                    y: 48.0,
                    rotation: 0.0,
                    color: type_io::RgbaColor::new(-1),
                },
                data: TypeValue::Null,
            });

        launcher.update();
        let expected_circles = launcher
            .standard_effect_render_frame()
            .circle_primitives
            .iter()
            .map(|circle| {
                (
                    RenderPoint::new(circle.center.0, circle.center.1),
                    circle.radius,
                )
            })
            .collect::<Vec<_>>();

        let viewport = RenderViewport::new(0.0, 0.0, 96.0, 96.0);
        let camera = RenderCamera::new(RenderPoint::new(48.0, 48.0), viewport);
        let minimap_camera = MinimapCamera::new(48.0, 48.0, 96.0, 96.0);
        let frame = launcher.graphics_frame_for_render(
            3,
            camera,
            viewport,
            minimap_camera,
            sample_minimap_overlay_input(true),
        );
        let render_frame = frame.bundle.render_frame.as_ref().unwrap();
        let effect_pass = render_frame
            .passes
            .iter()
            .find(|pass| {
                if pass.kind != RenderPassKind::Overlay {
                    return false;
                }
                pass.commands
                    .iter()
                    .filter_map(|command| match command {
                        RenderCommand::DrawCircle { center, radius, .. } => {
                            Some((*center, *radius))
                        }
                        _ => None,
                    })
                    .collect::<Vec<_>>()
                    == expected_circles
            })
            .expect("standard effect circles should be routed into an overlay render pass");
        let circle_commands: Vec<_> = effect_pass
            .commands
            .iter()
            .filter_map(|command| match command {
                RenderCommand::DrawCircle {
                    center,
                    radius,
                    filled,
                    layer,
                    ..
                } => Some((*center, *radius, *filled, *layer)),
                _ => None,
            })
            .collect();
        assert_eq!(circle_commands.len(), 2);
        assert!(circle_commands.iter().all(|(_, _, filled, layer)| {
            *filled && (*layer - Layer::EFFECT).abs() < f32::EPSILON
        }));
        assert_eq!(
            circle_commands
                .iter()
                .map(|(center, radius, _, _)| (*center, *radius))
                .collect::<Vec<_>>(),
            expected_circles
        );

        let mut renderer = HeadlessDesktopGraphicsRenderer::default();
        renderer.render_graphics_frame(&frame);
        assert!(
            renderer
                .last_opengl_backend_executor_state
                .draw_circle_commands
                >= expected_circles.len()
        );
        assert!(
            renderer
                .last_opengl_backend_executor_state
                .sprite_quads
                .len()
                >= 2 * super::DESKTOP_GRAPHICS_OPENGL_CIRCLE_MIN_SEGMENTS
        );
        assert!(renderer
            .last_opengl_backend_executor_state
            .sprite_draw_call_plans
            .iter()
            .any(|plan| plan.target == Some(RenderTarget::Screen)));
    }

