    #[test]
    fn desktop_launcher_paused_dialog_shown_saves_campaign_stats_like_java() {
        let mut launcher = DesktopLauncher::new(Vec::new());
        launcher.game_state.set(GameStateState::Playing);
        launcher.game_state.set_sector(Some(Sector::new(173)));
        launcher
            .runtime
            .campaign_stats
            .add_unit_produced("flare", 5);
        launcher
            .runtime
            .campaign_stats
            .add_enemy_unit_destroyed("dagger", 2);
        launcher.runtime.campaign_stats.playtime = 1200;
        launcher.runtime.campaign_stats.sectors_captured = 1;

        assert!(launcher
            .dispatch_hud_mobile_button_action_like_java(
                mindustry_core::mindustry::ui::HudMobileButtonAction::OpenPauseDialog,
            )
            .is_none());

        let persisted = launcher
            .settings_overrides
            .get("serpulo-campaign-stats")
            .expect("PausedDialog.shown should save current planet CampaignStats");
        assert!(persisted.contains("\"enemyUnitsDestroyed\":{\"dagger\":2}"));
        assert!(persisted.contains("\"unitsProduced\":{\"flare\":5}"));
        assert!(persisted.contains("\"playtime\":1200"));
        assert!(persisted.contains("\"sectorsCaptured\":1"));

        let mut route_launcher = DesktopLauncher::new(Vec::new());
        route_launcher.game_state.set(GameStateState::Playing);
        route_launcher.game_state.set_sector(Some(Sector::new(174)));
        route_launcher
            .runtime
            .campaign_stats
            .add_building_built("router", 7);
        route_launcher.open_pause_overlay_route(super::DesktopMenuRoute::Database);
        let routed = route_launcher
            .settings_overrides
            .get("serpulo-campaign-stats")
            .expect("opening a pause child route from gameplay should pass PausedDialog.shown");
        assert!(routed.contains("\"buildingsBuilt\":{\"router\":7}"));
    }

